import jdk.jfr.consumer.RecordingFile;
import java.nio.file.Path;
import java.util.Map;
import java.util.TreeMap;

/** Đọc mẫu cấp phát và nhóm theo đường gọi của hệ thống mob. */
class AuditMobJfr {
    public static void main(String[] args) throws Exception {
        Map<String, Integer> counts = new TreeMap<>();
        try (var file = new RecordingFile(Path.of(args[0]))) {
            while (file.hasMoreEvents()) {
                var event = file.readEvent();
                if (!event.getEventType().getName().startsWith("jdk.ObjectAllocation") || event.getStackTrace() == null) {
                    continue;
                }
                boolean audio = false;
                boolean live = false;
                for (var frame : event.getStackTrace().getFrames()) {
                    String type = frame.getMethod().getType().getName();
                    String method = frame.getMethod().getName();
                    audio |= type.equals("com.voxelgame.engine.AudioManager") && method.equals("playMobSound");
                    live |= type.equals("com.voxelgame.engine.MobSpawner") && !method.startsWith("<")
                            || type.startsWith("com.voxelgame.entity.mob.") && (method.equals("updateLiving")
                            || method.equals("tick") || method.equals("findFeetY") || method.equals("canStart"));
                }
                if (live) {
                    String objectName = event.getClass("objectClass").getName();
                    String top = event.getStackTrace().getFrames().get(0).getMethod().getType().getName();
                    counts.merge((audio ? "audio " : "core ") + objectName + " from " + top, 1, Integer::sum);
                }
            }
        }
        counts.forEach((key, count) -> System.out.println(key + " " + count));
    }
}

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.Input;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3Application;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3ApplicationConfiguration;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.PixmapIO;
import com.voxelgame.VoxelGameApp;
import com.voxelgame.entity.DamageSource;
import com.voxelgame.entity.Player;
import com.voxelgame.entity.StatusEffectType;
import com.voxelgame.engine.WeatherManager;
import com.voxelgame.engine.World;
import java.lang.reflect.Field;
import java.util.Arrays;
import org.lwjgl.glfw.GLFW;

/** Kiểm tra cửa sổ thật, HUD chiến đấu và nhịp khung hình tại ba biome. */
public final class CombatDesktopSmoke extends VoxelGameApp {
    private final long[] intervals = new long[4096];
    private final String[] sampleNames = {"PLAINS", "PLAINS", "SNOWY_PLAINS", "DESERT"};
    private final String[] weatherNames = {"CLEAR", "RAIN", "SNOW", "CLEAR"};
    private long started;
    private long previous;
    private int samples;
    private int biome;
    private boolean captured;

    public static void main(String[] args) {
        Lwjgl3ApplicationConfiguration config = new Lwjgl3ApplicationConfiguration();
        config.setTitle("Ourcraft");
        config.setOpenGLEmulation(Lwjgl3ApplicationConfiguration.GLEmulation.GL30, 3, 3);
        config.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);
        config.setWindowedMode(1280, 720);
        config.useVsync(true);
        new Lwjgl3Application(new CombatDesktopSmoke(), config);
    }

    @Override
    public void create() {
        super.create();
        Player player = (Player) field("player");
        World world = (World) field("world");
        player.damage(world, 4f, DamageSource.MELEE, null, 0f, 0f);
        player.applyEffect(StatusEffectType.HUNGER, 1, 8f);
        player.applyEffect(StatusEffectType.SLOWNESS, 0, 8f);
        player.applyEffect(StatusEffectType.WEAKNESS, 0, 8f);
        player.applyEffect(StatusEffectType.POISON, 0, 3f);
        long monitor = GLFW.glfwGetPrimaryMonitor();
        System.out.println("GL renderer " + Gdx.gl.glGetString(GL20.GL_RENDERER)
                + ", monitor " + GLFW.glfwGetVideoMode(monitor).refreshRate() + " Hz");
        started = System.nanoTime();
    }

    @Override
    public void render() {
        super.render();
        long now = System.nanoTime();
        double elapsed = (now - started) / 1e9;
        if (Gdx.gl.glGetError() != GL20.GL_NO_ERROR) {
            throw new AssertionError("OpenGL báo lỗi khi vẽ HUD hoặc thế giới");
        }
        if (!captured && elapsed >= 1.5) {
            captured = true;
            try (var ignored = new Screenshot()) {
                // Ảnh được lưu khi kết thúc phạm vi kiểm tra.
            }
        }
        if (elapsed >= 5 && previous != 0 && samples < intervals.length) {
            intervals[samples++] = now - previous;
        }
        previous = now;
        if (elapsed >= 10) {
            printTiming();
            if (++biome == sampleNames.length) {
                Gdx.app.exit();
                return;
            }
            if (biome == 1) {
                keyDown(Input.Keys.F6);
            } else {
                goToNextBiome();
                if (biome == 3) {
                    goToNextBiome();
                }
            }
            WeatherManager weather = (WeatherManager) field("weather");
            System.out.println("Transition from " + weather.label());
            started = System.nanoTime();
            previous = 0;
            samples = 0;
        }
    }

    private void goToNextBiome() {
        keyDown(Input.Keys.CONTROL_LEFT);
        keyDown(Input.Keys.C);
        keyUp(Input.Keys.CONTROL_LEFT);
    }

    private void printTiming() {
        long total = 0L;
        for (int i = 0; i < samples; i++) {
            total += intervals[i];
        }
        Arrays.sort(intervals, 0, samples);
        double p95 = intervals[Math.max(0, (int) Math.ceil(samples * .95) - 1)] / 1e6;
        WeatherManager weather = (WeatherManager) field("weather");
        if (!weather.biome().name().equals(sampleNames[biome]) || !weather.label().equals(weatherNames[biome])) {
            throw new AssertionError("Sai biome hoặc thời tiết " + weather.biome() + " " + weather.label());
        }
        System.out.printf("%s %s %.2f FPS, p95 %.2f ms, %d frames%n",
                weather.biome(), weather.label(), samples * 1e9 / total, p95, samples);
    }

    private Object field(String name) {
        try {
            Field field = VoxelGameApp.class.getDeclaredField(name);
            field.setAccessible(true);
            return field.get(this);
        } catch (ReflectiveOperationException failure) {
            throw new AssertionError(failure);
        }
    }

    private static final class Screenshot implements AutoCloseable {
        @Override
        public void close() {
            Pixmap image = Pixmap.createFromFrameBuffer(0, 0, 1280, 720);
            try {
                PixmapIO.writePNG(Gdx.files.local("build/combat-hud-smoke.png"), image, -1, true);
            } finally {
                image.dispose();
            }
        }
    }
}

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.Input;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3Application;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3ApplicationConfiguration;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.PixmapIO;
import com.badlogic.gdx.math.Vector3;
import com.badlogic.gdx.utils.IntArray;
import com.voxelgame.VoxelGameApp;
import com.voxelgame.engine.*;
import com.voxelgame.entity.*;
import com.voxelgame.entity.mob.*;
import org.lwjgl.openal.AL10;

import java.lang.reflect.Field;
import java.util.Arrays;

/** Kiểm tra đầu vào Ctrl+C, cảnh thật, hiệu ứng âm thanh và sinh thú qua ba biome. */
public final class FinalMobFrameSmoke extends VoxelGameApp {
    private static final BiomeType[] BIOMES = {BiomeType.SNOWY_PLAINS, BiomeType.PLAINS, BiomeType.DESERT};
    private static final MobType[][] SPECIES = {
            {MobType.SNOW_RABBIT, MobType.WOLF, MobType.SNOW_FOX, MobType.POLAR_BEAR, MobType.GOAT},
            {MobType.COW, MobType.SHEEP, MobType.PIG, MobType.CHICKEN, MobType.HORSE, MobType.DONKEY}, {MobType.RABBIT, MobType.CAMEL}};
    private static final MobAppearance[][] APPEARANCES = {
            {MobAppearance.RABBIT_WHITE, MobAppearance.WOLF_SNOWY, MobAppearance.SNOW_FOX_SLEEP,
                    MobAppearance.POLAR_BEAR, MobAppearance.GOAT},
            {MobAppearance.COW, MobAppearance.SHEEP, MobAppearance.PIG, MobAppearance.CHICKEN, MobAppearance.HORSE_BROWN, MobAppearance.DONKEY},
            {MobAppearance.RABBIT_GOLD, MobAppearance.CAMEL}};
    private final long[] frames = new long[4096];
    private final boolean[] seen = new boolean[MobType.values().length];
    private final Vector3 anchor = new Vector3();
    private final Vector3 ground = new Vector3();
    private final Vector3 zero = new Vector3();
    private final MobEntity[] showcase = new MobEntity[6];
    private World world;
    private WorldTime clock;
    private Camera camera;
    private Field skipMouse;
    private Vector3 playerPosition;
    private Vector3 playerVelocity;
    private IntArray sources;
    private int stage;
    private int samples;
    private long start;
    private long previous;
    private int wildlife;
    private int monsters;
    private int minimumWildlife;
    private int minimumMonsters;
    private boolean showing;
    private boolean vitalsChanged;
    private final boolean control = Boolean.getBoolean("wildlife.control");
    private final boolean diagnose = Boolean.getBoolean("wildlife.diagnose");
    private final boolean atCap = Boolean.getBoolean("wildlife.cap");
    private final int single = Integer.getInteger("wildlife.single", -1);
    private int diagnosePass;
    private Object renderer;
    private long cpuStart;
    private long bytesStart;
    private long cpuTotal;
    private long bytesTotal;
    private final com.sun.management.ThreadMXBean bean =
            (com.sun.management.ThreadMXBean) java.lang.management.ManagementFactory.getThreadMXBean();

    public static void main(String[] args) {
        Lwjgl3ApplicationConfiguration config = new Lwjgl3ApplicationConfiguration();
        config.setTitle("Ourcraft");
        config.setOpenGLEmulation(Lwjgl3ApplicationConfiguration.GLEmulation.GL30, 3, 3);
        config.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);
        config.setWindowedMode(Integer.getInteger("wildlife.width", 1280), Integer.getInteger("wildlife.height", 720));
        config.useVsync(true);
        new Lwjgl3Application(new FinalMobFrameSmoke(), config);
    }

    @Override
    public void create() {
        super.create();
        world = (World) read(this, VoxelGameApp.class, "world");
        clock = (WorldTime) read(this, VoxelGameApp.class, "worldTime");
        camera = (Camera) read(this, VoxelGameApp.class, "camera");
        skipMouse = field(VoxelGameApp.class, "skipNextMouseDelta");
        playerPosition = (Vector3) read(world.getPlayer(), Entity.class, "position");
        playerVelocity = (Vector3) read(world.getPlayer(), Entity.class, "velocity");
        sources = (IntArray) read(Gdx.audio, Gdx.audio.getClass(), "allSources");
        Gdx.input.setCursorCatched(false);
        if (control) {
            for (MobType[] group : SPECIES) {
                for (MobType type : group) {
                    type.registerFactory(null);
                }
            }
        }
        System.out.println("GL " + Gdx.gl.glGetString(GL20.GL_RENDERER));
        if (single >= 0) {
            for (; stage < single; stage++) {
                keyDown(Input.Keys.CONTROL_LEFT);
                keyDown(Input.Keys.C);
                keyUp(Input.Keys.CONTROL_LEFT);
            }
        }
        renderer = read(world, World.class, "mobRenderer");
        enterBiome();
    }

    private void enterBiome() {
        keyDown(Input.Keys.CONTROL_LEFT);
        keyDown(Input.Keys.C);
        keyUp(Input.Keys.CONTROL_LEFT);
        world.getPlayer().copyPosition(anchor);
        if (world.getBiome((int) anchor.x, (int) anchor.z) != BIOMES[stage]) {
            throw new AssertionError("Ctrl+C did not reach " + BIOMES[stage]);
        }
        int targetTick = atCap ? 18000 : 6000;
        clock.update(((targetTick - clock.tickOfDay()) + 24000) % 24000 / 20d);
        if (atCap) {
            seedCap();
        }
        camera.rotate(0, -2f - camera.getPitch());
        samples = 0;
        wildlife = 0;
        monsters = 0;
        minimumWildlife = Integer.MAX_VALUE;
        minimumMonsters = Integer.MAX_VALUE;
        previous = 0;
        showing = false;
        vitalsChanged = false;
        Arrays.fill(seen, false);
        start = System.nanoTime();
    }

    private void seedCap() {
        MobType[] enemies = switch (stage) {
            case 0 -> new MobType[]{MobType.SPIDER, MobType.CREEPER, MobType.ZOMBIE, MobType.STRAY,
                    MobType.SKELETON, MobType.ENDERMAN, MobType.ZOMBIE_VILLAGER, MobType.WITCH};
            case 1 -> new MobType[]{MobType.SPIDER, MobType.CREEPER, MobType.ZOMBIE, MobType.SKELETON,
                    MobType.ENDERMAN, MobType.ZOMBIE_VILLAGER, MobType.WITCH};
            default -> new MobType[]{MobType.SPIDER, MobType.CREEPER, MobType.HUSK, MobType.PARCHED,
                    MobType.SKELETON, MobType.ZOMBIE, MobType.ENDERMAN, MobType.ZOMBIE_VILLAGER, MobType.WITCH};
        };
        int special = stage == 2 ? 3 : 0;
        if (stage == 2) {
            float x = anchor.x + 28;
            float y = world.getPrecipitationSurface((int) x, (int) anchor.z);
            CamelHusk camel = new CamelHusk(x, y, anchor.z);
            Husk husk = new Husk(x, y + 2, anchor.z, true);
            Parched archer = new Parched(x, y + 2, anchor.z);
            husk.tryMount(camel, 0);
            archer.tryMount(camel, 1);
            world.addEntity(camel);
            world.addEntity(husk);
            world.addEntity(archer);
        }
        for (int i = 0; i < 80 - special; i++) {
            double angle = i * 2.399963229728653;
            int radius = 30 + (i * 13) % 34;
            int x = (int) (anchor.x + radius * Math.cos(angle));
            int z = (int) (anchor.z + radius * Math.sin(angle));
            float y = world.getPrecipitationSurface(x, z);
            MobType[] types = i < 70 - special ? enemies : SPECIES[stage];
            world.addEntity(types[i % types.length].create(x + 0.5f, y, z + 0.5f));
        }
        System.out.println(BIOMES[stage] + " stress warmup starts with 70 hostile / 10 creature");
    }

    @Override
    public void render() {
        try {
            skipMouse.setBoolean(this, true);
        } catch (IllegalAccessException ex) {
            throw new AssertionError(ex);
        }
        playerPosition.set(anchor);
        playerVelocity.setZero();
        if (showing) {
            resetShowcase();
        }
        if (diagnose) {
            cpuStart = bean.getCurrentThreadCpuTime();
            bytesStart = bean.getCurrentThreadAllocatedBytes();
        }
        super.render();
        long now = System.nanoTime();
        double elapsed = (now - start) / 1e9;
        if (Gdx.gl.glGetError() != GL20.GL_NO_ERROR || AL10.alGetError() != AL10.AL_NO_ERROR) {
            throw new AssertionError("OpenGL or OpenAL reported an error");
        }
        if (showing) {
            if (stage == 1 && elapsed >= 0.7 && !vitalsChanged) {
                Player player = world.getPlayer();
                Object ui = read(this, VoxelGameApp.class, "uiRenderer");
                if ((int) read(ui, ui.getClass(), "vitalHealth") != (int) Math.ceil(player.getHealth())) {
                    throw new AssertionError("Incorrect HUD HP cache before change");
                }
                player.damage(world, 3f, DamageSource.POTION_MAGIC, null, 0f, 0f);
                write(player, Player.class, "hunger", 17f);
                vitalsChanged = true;
            }
            if (elapsed >= 1.4) {
                if (vitalsChanged) {
                    Object ui = read(this, VoxelGameApp.class, "uiRenderer");
                    if ((int) read(ui, ui.getClass(), "vitalHealth") != (int) Math.ceil(world.getPlayer().getHealth())
                            || (int) read(ui, ui.getClass(), "vitalFood") != 17) {
                        throw new AssertionError("Incorrect HUD HP or hunger cache after change");
                    }
                    System.out.println("HUD vitals cache updated after damage and hunger");
                }
                capture();
                advance();
            }
            return;
        }
        int currentWildlife = 0;
        int currentMonsters = 0;
        for (int i = 0; i < world.entityCount(); i++) {
            if (world.entityAt(i) instanceof MobEntity mob && mob.isAlive()) {
                mob.copyPosition(ground);
                if (ground.dst2(anchor) <= 128 * 128) {
                    if (mob.type().category() == MobCategory.CREATURE) {
                        currentWildlife++;
                        seen[mob.type().ordinal()] = true;
                    } else {
                        currentMonsters++;
                    }
                }
            }
        }
        wildlife = Math.max(wildlife, currentWildlife);
        monsters = Math.max(monsters, currentMonsters);
        if (elapsed >= (diagnose ? 2 : 7) && previous != 0 && samples < frames.length) {
            frames[samples++] = now - previous;
            minimumWildlife = Math.min(minimumWildlife, currentWildlife);
            minimumMonsters = Math.min(minimumMonsters, currentMonsters);
            if (diagnose) {
                cpuTotal += bean.getCurrentThreadCpuTime() - cpuStart;
                bytesTotal += bean.getCurrentThreadAllocatedBytes() - bytesStart;
            }
        }
        previous = now;
        if (elapsed >= (diagnose ? 8 : 15)) {
            finishMeasurement();
            if (diagnose) {
                System.out.printf("DIAGNOSTIC pass %d: %.3f ms CPU/frame; %.1f bytes/frame%n", diagnosePass,
                        cpuTotal / 1e6 / samples, bytesTotal / (double) samples);
                diagnosePass++;
                if (diagnosePass == 4) {
                    write(world, World.class, "mobRenderer", renderer);
                    Gdx.app.exit();
                } else {
                    write(world, World.class, "mobRenderer", diagnosePass % 2 == 0 ? renderer : null);
                    samples = 0;
                    previous = 0;
                    cpuTotal = 0;
                    bytesTotal = 0;
                    start = System.nanoTime();
                }
            } else if (control || atCap) {
                advance();
            } else {
                setupShowcase();
            }
        }
    }

    private void finishMeasurement() {
        StringBuilder species = new StringBuilder();
        for (MobType type : SPECIES[stage]) {
            if (seen[type.ordinal()]) {
                species.append(type).append(' ');
            }
        }
        if (!control && species.length() == 0) {
            throw new AssertionError("No natural wildlife in " + BIOMES[stage]);
        }
        long total = 0;
        for (int i = 0; i < samples; i++) {
            total += frames[i];
        }
        Arrays.sort(frames, 0, samples);
        System.out.printf("%s %s tick=%d, creature=%d–%d hostile=%d–%d, %.2f FPS p95 %.2f ms (%d samples), %s%n",
                BIOMES[stage], atCap ? "cap" : control ? "control" : "wildlife", clock.tickOfDay(),
                minimumWildlife, wildlife, minimumMonsters, monsters,
                samples * 1e9 / total, frames[(int) Math.ceil(samples * .95) - 1] / 1e6, samples, species);
    }

    private void setupShowcase() {
        for (MobType type : SPECIES[stage]) {
            checkAudio(type.id(), MobSoundEvent.AMBIENT);
        }
        if (stage == 0) {
            checkAudio("goat", MobSoundEvent.GOAT_SCREAM);
            checkAudio("wolf", MobSoundEvent.WOLF_GROWL);
        }
        anchor.y = (int) anchor.y + 18;
        Block floor = stage == 0 ? Block.SNOW_BLOCK : stage == 1 ? Block.GRASS : Block.SANDSTONE;
        for (int x = (int) anchor.x - 9; x <= (int) anchor.x + 9; x++) {
            for (int z = (int) anchor.z - 13; z <= (int) anchor.z + 3; z++) {
                world.setBlock(x, (int) anchor.y - 1, z, floor.getId());
            }
        }
        camera.rotate(0, -12f - camera.getPitch());
        int count = stage == 2 ? 3 : 6;
        for (int i = 0; i < count; i++) {
            int model = Math.min(i, SPECIES[stage].length - 1);
            float x = anchor.x + (i % 3 - 1) * 2.0f;
            float z = anchor.z - 4.2f - (i / 3) * 3.3f;
            MobEntity mob = SPECIES[stage][model].create(x, anchor.y, z);
            showcase[i] = mob;
            mob.setPersistent(true);
            // Tắt các hành vi dịch chuyển để kiểm tra từng model ở khung hình cố định.
            mob.goals().stopAll(world, mob);
            if (mob instanceof Wolf) {
                write(mob, Wolf.class, "huntDelay", 60f);
            }
            world.addEntity(mob);
        }
        showing = true;
        start = System.nanoTime();
    }

    private void resetShowcase() {
        for (int i = 0; i < showcase.length && showcase[i] != null; i++) {
            MobEntity mob = showcase[i];
            int index = Math.min(i, APPEARANCES[stage].length - 1);
            float x = anchor.x + (i % 3 - 1) * 2f;
            float z = anchor.z - 4.2f - (i / 3) * 3.3f;
            mob.setPosition(x, anchor.y, z);
            MobVisualState visual = mob.mobVisualState();
            visual.setAppearance(stage == 0 && i == 5 ? MobAppearance.RABBIT_WHITE_SPLOTCHED
                    : APPEARANCES[stage][index]);
            if (stage == 1 && i == 1) {
                visual.setSheepWoolColor(0xe78ab2);
            }
            if (stage == 0 && mob.type() == MobType.SNOW_FOX) {
                visual.setHeldBlock(Block.POPPY);
            }
            mob.lookAt(anchor.x, anchor.y + 0.9f, anchor.z);
            mob.faceBody(anchor.x, anchor.z);
        }
    }

    private void checkAudio(String id, MobSoundEvent event) {
        AudioManager audio = world.getAudio();
        Object bank = read(audio, AudioManager.class, "mobSounds");
        java.util.Map<?, ?> banks = (java.util.Map<?, ?>) read(bank, bank.getClass(), "samplesByMob");
        Object[] clips = ((Object[][]) banks.get(id))[event.ordinal()];
        audio.playMobSound(id, event, anchor.x, anchor.y, anchor.z - 2, 0, 1f);
        for (int i = 0; i < sources.size; i++) {
            int source = sources.get(i);
            if (AL10.alGetSourcei(source, AL10.AL_SOURCE_STATE) != AL10.AL_PLAYING) {
                continue;
            }
            int buffer = AL10.alGetSourcei(source, AL10.AL_BUFFER);
            for (Object clip : clips) {
                if (buffer == (int) read(clip, clip.getClass().getSuperclass(), "bufferID")) {
                    System.out.println("Audio " + id + " " + event + " OK");
                    return;
                }
            }
        }
        throw new AssertionError("No active OpenAL source for " + id + " " + event);
    }

    private void capture() {
        Pixmap screenshot = Pixmap.createFromFrameBuffer(0, 0, 1280, 720);
        try {
            PixmapIO.writePNG(Gdx.files.local("build/final-mobs-" + BIOMES[stage] + ".png"), screenshot, -1, true);
        } finally {
            screenshot.dispose();
        }
    }

    private void advance() {
        for (MobEntity mob : showcase) {
            if (mob != null) {
                mob.discard();
            }
        }
        Arrays.fill(showcase, null);
        stage++;
        if (stage == BIOMES.length || single >= 0) {
            Gdx.app.exit();
        } else {
            enterBiome();
        }
    }

    private static Field field(Class<?> type, String name) {
        try {
            Field field = type.getDeclaredField(name);
            field.setAccessible(true);
            return field;
        } catch (ReflectiveOperationException ex) {
            throw new AssertionError(ex);
        }
    }

    private static Object read(Object target, Class<?> type, String name) {
        try {
            return field(type, name).get(target);
        } catch (IllegalAccessException ex) {
            throw new AssertionError(ex);
        }
    }

    private static void write(Object target, Class<?> type, String name, Object value) {
        try {
            field(type, name).set(target, value);
        } catch (IllegalAccessException ex) {
            throw new AssertionError(ex);
        }
    }
}

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.Input;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3Application;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3ApplicationConfiguration;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.PixmapIO;
import com.badlogic.gdx.math.Vector3;
import com.badlogic.gdx.utils.IntArray;
import com.voxelgame.VoxelGameApp;
import com.voxelgame.engine.AudioManager;
import com.voxelgame.engine.BiomeType;
import com.voxelgame.engine.Camera;
import com.voxelgame.engine.MobSoundEvent;
import com.voxelgame.engine.MobSpawner;
import com.voxelgame.engine.World;
import com.voxelgame.engine.WorldTime;
import com.voxelgame.entity.Entity;
import com.voxelgame.entity.Block;
import com.voxelgame.entity.Player;
import com.voxelgame.entity.mob.MobEntity;
import com.voxelgame.entity.mob.MobType;
import com.voxelgame.entity.projectile.ProjectileEntity;
import com.voxelgame.entity.projectile.ArrowEntity;
import com.voxelgame.entity.projectile.ThrownPotionEntity;
import org.lwjgl.openal.AL10;

import java.lang.reflect.Field;
import java.util.Arrays;

/** Dùng phím thật của ứng dụng để chạy mô phỏng ban đêm liên tiếp trong ba biome. */
public final class HostileDesktopSmoke extends VoxelGameApp {
    private static final BiomeType[] TOUR = {BiomeType.SNOWY_PLAINS, BiomeType.PLAINS, BiomeType.DESERT};
    private static final MobType[] EXPECTED = {MobType.STRAY, MobType.SKELETON, MobType.PARCHED};
    private static final String[] SOUND_IDS = {"stray", "witch", "husk"};
    private static final MobSoundEvent[] SOUNDS = {MobSoundEvent.BOW_SHOOT, MobSoundEvent.WITCH_THROW,
            MobSoundEvent.HUSK_CONVERT};
    private final long[] times = new long[4096];
    private final Vector3 anchor = new Vector3();
    private final MobType[] types = MobType.values();
    private final MobType.Factory[] factories = new MobType.Factory[types.length];
    private Field skipMouse;
    private World world;
    private WorldTime clock;
    private Player player;
    private Vector3 livePosition;
    private Vector3 liveVelocity;
    private AudioManager audio;
    private IntArray openAlSources;
    private int stage;
    private boolean baseline = true;
    private final boolean controlOnly = Boolean.getBoolean("voxel.smoke.controlOnly");
    private int samples;
    private int peakMobCount;
    private int peakProjectiles;
    private boolean expectedSeen;
    private boolean checkedAudio;
    private boolean actionTest;
    private boolean arrowSeen;
    private boolean potionSeen;
    private long started;
    private long previous;

    public static void main(String[] args) {
        Lwjgl3ApplicationConfiguration config = new Lwjgl3ApplicationConfiguration();
        config.setTitle("Ourcraft");
        config.setOpenGLEmulation(Lwjgl3ApplicationConfiguration.GLEmulation.GL30, 3, 3);
        config.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);
        config.setWindowedMode(1280, 720);
        config.useVsync(true);
        new Lwjgl3Application(new HostileDesktopSmoke(), config);
    }

    @Override
    public void create() {
        super.create();
        world = (World) read(this, VoxelGameApp.class, "world");
        clock = (WorldTime) read(this, VoxelGameApp.class, "worldTime");
        player = world.getPlayer();
        audio = world.getAudio();
        livePosition = (Vector3) read(player, Entity.class, "position");
        liveVelocity = (Vector3) read(player, Entity.class, "velocity");
        openAlSources = (IntArray) read(Gdx.audio, Gdx.audio.getClass(), "allSources");
        skipMouse = field(VoxelGameApp.class, "skipNextMouseDelta");
        ((Camera) read(this, VoxelGameApp.class, "camera")).rotate(0f, -2f);
        Gdx.input.setCursorCatched(false);
        System.out.println("GL " + Gdx.gl.glGetString(GL20.GL_RENDERER));
        for (MobType type : types) {
            factories[type.ordinal()] = type.registerFactory(null);
        }
        for (int i = 0; i < 4; i++) {
            keyDown(Input.Keys.F7);
        }
        enterBiome();
    }

    private void enterBiome() {
        keyDown(Input.Keys.CONTROL_LEFT);
        keyDown(Input.Keys.C);
        keyUp(Input.Keys.CONTROL_LEFT);
        player.copyPosition(anchor);
        if (world.getBiome((int) anchor.x, (int) anchor.z) != TOUR[stage] || !MobSpawner.isNightDark(clock)) {
            throw new AssertionError("Phím điểm thử sai biome hoặc sai mốc ban đêm");
        }
        peakMobCount = 0;
        peakProjectiles = 0;
        expectedSeen = false;
        checkedAudio = false;
        samples = 0;
        started = System.nanoTime();
        previous = 0;
    }

    @Override
    public void render() {
        try {
            skipMouse.setBoolean(this, true);
        } catch (IllegalAccessException ex) {
            throw new AssertionError(ex);
        }
        livePosition.set(anchor);
        liveVelocity.setZero();
        super.render();
        long now = System.nanoTime();
        double elapsed = (now - started) / 1e9;
        if (Gdx.gl.glGetError() != GL20.GL_NO_ERROR || AL10.alGetError() != AL10.AL_NO_ERROR) {
            throw new AssertionError("Lỗi đồ họa hoặc âm thanh gốc");
        }
        if (actionTest) {
            checkAction(elapsed);
            return;
        }
        if (!baseline && !checkedAudio && elapsed > 1) {
            checkPlayback();
        }
        int mobs = 0;
        int projectiles = 0;
        for (int i = 0; i < world.entityCount(); i++) {
            if (world.entityAt(i) instanceof MobEntity mob && mob.isAlive()) {
                mobs++;
                expectedSeen |= mob.type() == EXPECTED[stage];
            } else if (world.entityAt(i) instanceof ProjectileEntity) {
                projectiles++;
            }
        }
        peakMobCount = Math.max(peakMobCount, mobs);
        peakProjectiles = Math.max(peakProjectiles, projectiles);
        if (elapsed >= 5 && previous != 0 && samples < times.length) {
            times[samples++] = now - previous;
        }
        previous = now;
        if (elapsed >= (baseline ? 10 : 13)) {
            finishBiome();
        }
    }

    /** Xác minh nguồn OpenAL của clip thuộc ngữ cảnh đã thật sự bắt đầu phát. */
    private void checkPlayback() {
        checkedAudio = true;
        Object bank = read(audio, audio.getClass(), "mobSounds");
        java.util.Map<?, ?> banks = (java.util.Map<?, ?>) read(bank, bank.getClass(), "samplesByMob");
        Object[][] groups = (Object[][]) banks.get(SOUND_IDS[stage]);
        Object[] group = groups[SOUNDS[stage].ordinal()];
        if (group == null) {
            groups = (Object[][]) read(bank, bank.getClass(), "sharedSamples");
            group = groups[SOUNDS[stage].ordinal()];
        }
        audio.playMobSound(SOUND_IDS[stage], SOUNDS[stage], anchor.x, anchor.y + 1f, anchor.z - 3f, 0f, 1f);
        for (int i = 0; i < openAlSources.size; i++) {
            int source = openAlSources.get(i);
            if (AL10.alGetSourcei(source, AL10.AL_SOURCE_STATE) != AL10.AL_PLAYING) {
                continue;
            }
            int buffer = AL10.alGetSourcei(source, AL10.AL_BUFFER);
            for (Object sample : group) {
                Class<?> openAlSound = sample.getClass().getSuperclass();
                if (buffer == (int) read(sample, openAlSound, "bufferID")) {
                    return;
                }
            }
        }
        throw new AssertionError("Không phát được mẫu cho " + SOUNDS[stage]);
    }

    private void finishBiome() {
        if (!baseline && (!expectedSeen || peakMobCount < 30)) {
            throw new AssertionError("Thiếu sinh tự nhiên cho " + TOUR[stage] + ", đạt " + peakMobCount
                    + " mob, tìm thấy " + EXPECTED[stage] + " = " + expectedSeen);
        }
        long total = 0;
        for (int i = 0; i < samples; i++) {
            total += times[i];
        }
        Arrays.sort(times, 0, samples);
        System.out.printf("%s %s tick=%d, %d mobs, max %d projectiles: %.2f FPS p95 %.2f ms (%d samples)%n",
                TOUR[stage], baseline ? "control" : "hostile", clock.tickOfDay(), peakMobCount, peakProjectiles,
                samples * 1e9 / total, times[(int) Math.ceil(samples * .95) - 1] / 1e6, samples);
        if (baseline && !controlOnly) {
            for (MobType type : types) {
                type.registerFactory(factories[type.ordinal()]);
            }
            baseline = false;
            samples = 0;
            started = System.nanoTime();
            previous = 0;
            return;
        }
        if (!baseline) {
            capture();
        }
        stage++;
        if (stage < TOUR.length) {
            for (MobType type : types) {
                type.registerFactory(null);
            }
            baseline = true;
            enterBiome();
        } else if (controlOnly) {
            Gdx.app.exit();
        } else {
            startAction();
        }
    }

    private void capture() {
        capture("build/hostile-" + TOUR[stage] + ".png");
    }

    private void capture(String file) {
        Pixmap screenshot = Pixmap.createFromFrameBuffer(0, 0, 1280, 720);
        try {
            PixmapIO.writePNG(Gdx.files.local(file), screenshot, -1, true);
        } finally {
            screenshot.dispose();
        }
    }

    /** Dùng một sàn trống để ngắm được cả hai đường đạn và loại trừ vật cản ngẫu nhiên. */
    private void startAction() {
        anchor.y = (int) anchor.y + 20;
        for (int x = (int) anchor.x - 9; x <= (int) anchor.x + 9; x++) {
            for (int z = (int) anchor.z - 17; z <= (int) anchor.z + 4; z++) {
                world.setBlock(x, (int) anchor.y - 1, z, Block.SANDSTONE.getId());
            }
        }
        player.setPosition(anchor.x, anchor.y, anchor.z);
        world.addEntity(MobType.PARCHED.create(anchor.x - 3, anchor.y, anchor.z - 9));
        world.addEntity(MobType.WITCH.create(anchor.x + 3, anchor.y, anchor.z - 8));
        actionTest = true;
        started = System.nanoTime();
    }

    private void checkAction(double elapsed) {
        for (int i = 0; i < world.entityCount(); i++) {
            Entity entity = world.entityAt(i);
            boolean firstProjectile = !arrowSeen && entity instanceof ArrowEntity
                    || !potionSeen && entity instanceof ThrownPotionEntity;
            arrowSeen |= entity instanceof ArrowEntity;
            potionSeen |= entity instanceof ThrownPotionEntity;
            if (firstProjectile) {
                capture(entity instanceof ArrowEntity ? "build/hostile-combat-arrow.png" : "build/hostile-combat-potion.png");
            }
        }
        if (arrowSeen && potionSeen) {
            System.out.println("REAL ATTACKS: saw Parched arrow and Witch potion in the game loop");
            Gdx.app.exit();
        } else if (elapsed > 8) {
            throw new AssertionError("Thiếu đạn bay thực: arrow=" + arrowSeen + ", potion=" + potionSeen);
        }
    }

    private static Field field(Class<?> type, String name) {
        try {
            Field field = type.getDeclaredField(name);
            field.setAccessible(true);
            return field;
        } catch (ReflectiveOperationException ex) {
            throw new AssertionError(ex);
        }
    }

    private static Object read(Object target, Class<?> type, String name) {
        try {
            return field(type, name).get(target);
        } catch (IllegalAccessException ex) {
            throw new AssertionError(ex);
        }
    }
}

import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3Application;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3ApplicationConfiguration;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Mesh;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.VertexAttribute;
import com.badlogic.gdx.graphics.VertexAttributes.Usage;
import com.badlogic.gdx.math.Matrix4;
import com.badlogic.gdx.math.Vector3;
import com.voxelgame.engine.ShaderProgram;
import com.voxelgame.engine.Camera;
import java.lang.reflect.Method;

/** Kiểm tra shader trên OpenGL thật qua màu pixel giữa khung hình. */
public final class LiquidFogSmoke extends ApplicationAdapter {
    public static void main(String[] args) {
        if (args.length > 0) {
            try {
                ShaderProgram.class.getMethod("enableDistanceFog", Vector3.class, float.class, float.class);
                ShaderProgram.class.getMethod("disableDistanceFog");
            } catch (ReflectiveOperationException error) {
                throw new AssertionError("Shader chưa cung cấp chế độ sương xa cho lượt thế giới", error);
            }
            return;
        }
        Lwjgl3ApplicationConfiguration configuration = new Lwjgl3ApplicationConfiguration();
        configuration.setInitialVisible(false);
        configuration.disableAudio(true);
        configuration.setWindowedMode(64, 64);
        configuration.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);
        configuration.setOpenGLEmulation(Lwjgl3ApplicationConfiguration.GLEmulation.GL30, 3, 3);
        new Lwjgl3Application(new LiquidFogSmoke(), configuration);
    }

    @Override
    public void create() {
        try {
            checkFog();
        } catch (ReflectiveOperationException error) {
            throw new AssertionError("Shader chưa cung cấp chế độ sương xa cho lượt thế giới", error);
        }
        Gdx.app.exit();
    }

    private void checkFog() throws ReflectiveOperationException {
        ShaderProgram shader = new ShaderProgram();
        Mesh mesh = new Mesh(true, 3, 0,
                new VertexAttribute(Usage.Position, 3, "aPos"),
                new VertexAttribute(Usage.TextureCoordinates, 2, "aTexCoord"),
                new VertexAttribute(Usage.Generic, 1, "aShade"));
        try {
            Method enable = ShaderProgram.class.getMethod("enableDistanceFog", Vector3.class, float.class, float.class);
            Method disable = ShaderProgram.class.getMethod("disableDistanceFog");
            mesh.setVertices(new float[] {-1, -1, 0, 0, 0, -1, 3, -1, 0, 0, 0, -1, -1, 3, 0, 0, 0, -1});
            shader.bind();
            shader.setUniformMatrix4f("uProjection", new Matrix4());
            shader.setUniform1i("uUseTexture", 0);
            shader.setUniformVec4("uTintColor", 1f, 0f, 0f, 0.65f);
            shader.setUniformVec3("uWorldLight", 0.2f, 0.2f, 0.2f);
            shader.setUniformVec3("uSkyColor", 0f, 0f, 1f);
            shader.setUniformVec3("uHorizonColor", 1f, 0f, 0f);
            shader.setUniformVec3("uSunDirection", 1f, 0f, 0f);
            shader.setUniform1f("uHorizonGlow", 0f);
            enable.invoke(shader, new Vector3(), 10f, 30f);
            verify(readPixel(shader, mesh, 5f), 255, 0, 166, "khối gần tự phát sáng");
            verify(readPixel(shader, mesh, 20f), 128, 128, 166, "trộn RGB ở giữa khoảng sương");
            verify(readPixel(shader, mesh, 40f), 0, 255, 166, "sương xa khớp màu trời");
            shader.setUniform1i("uEnvironmentMode", 4);
            shader.setUniformVec4("uTintColor", 1f, 0f, 0f, 0.65f);
            if ((readPixel(shader, mesh, 40f) >>> 8 & 0xff) != 0) {
                throw new AssertionError("Lượt giáng thủy phải giữ màu riêng");
            }
            checkLiquid(shader, mesh, Camera.LiquidView.WATER);
            checkLiquid(shader, mesh, Camera.LiquidView.LAVA);
            shader.setUniform1i("uEnvironmentMode", 0);
            disable.invoke(shader);
            verify(readPixel(shader, mesh, 40f), 255, 0, 166, "tắt sương trước overlay và HUD");
            if (Gdx.gl.glGetError() != GL20.GL_NO_ERROR) {
                throw new AssertionError("OpenGL báo lỗi khi vẽ sương");
            }
            System.out.println("FOG SMOKE PASSED on " + Gdx.gl.glGetString(GL20.GL_RENDERER));
        } finally {
            mesh.dispose();
            shader.dispose();
        }
    }

    /** So màu và alpha thật của hình học, bầu trời, mây, thiên thể và giáng thủy. */
    private static void checkLiquid(ShaderProgram shader, Mesh mesh, Camera.LiquidView liquid) {
        shader.enableLiquidFog(new Vector3(), liquid);
        int expectedRed = Math.round(liquid.red * 255f);
        int expectedBlue = Math.round(liquid.blue * 255f);
        shader.setUniform1i("uEnvironmentMode", 0);
        verify(readPixel(shader, mesh, liquid.fogEnd + 1f), expectedRed, expectedBlue, 166, "Sương chất lỏng của hình học");
        verify(readPixel(shader, mesh, liquid.fogStart * 0.5f), 255, 0, 166, "Hình học sát mắt");
        shader.setUniform1i("uEnvironmentMode", 1);
        verify(readPixel(shader, mesh, liquid.fogEnd + 1f), expectedRed, expectedBlue, 255, "Nền trời khớp sương");
        for (int mode = 2; mode <= 4; mode++) {
            shader.setUniform1i("uEnvironmentMode", mode);
            mesh.setVertices(new float[] {-1, -1, 0, 0, 0, 1, 3, -1, 0, 0, 0, 1, -1, 3, 0, 0, 0, 1});
            if ((readPixel(shader, mesh, liquid.fogEnd + 1f) & 0xff) != 0) {
                throw new AssertionError("Lớp môi trường xa phải biến mất, mode=" + mode);
            }
        }
        mesh.setVertices(new float[] {-1, -1, 0, 0, 0, -1, 3, -1, 0, 0, 0, -1, -1, 3, 0, 0, 0, -1});
    }

    private static int readPixel(ShaderProgram shader, Mesh mesh, float distance) {
        shader.setUniformMatrix4f("uModel", new Matrix4().setToTranslation(0f, 0f, -distance));
        shader.setUniformMatrix4f("uView", new Matrix4().setToTranslation(0f, 0f, distance));
        Gdx.gl.glClearColor(0f, 0f, 0f, 0f);
        Gdx.gl.glClear(GL20.GL_COLOR_BUFFER_BIT);
        mesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);
        Pixmap image = Pixmap.createFromFrameBuffer(Gdx.graphics.getBackBufferWidth() / 2,
                Gdx.graphics.getBackBufferHeight() / 2, 1, 1);
        try {
            return image.getPixel(0, 0);
        } finally {
            image.dispose();
        }
    }

    private static void verify(int rgba, int red, int blue, int alpha, String label) {
        if (Math.abs((rgba >>> 24) - red) > 2 || Math.abs((rgba >>> 8 & 0xff) - blue) > 2
                || Math.abs((rgba & 0xff) - alpha) > 2) {
            throw new AssertionError(label + " nhận 0x" + Integer.toHexString(rgba));
        }
    }
}

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3Application;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3ApplicationConfiguration;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.math.Vector3;
import com.voxelgame.VoxelGameApp;
import com.voxelgame.engine.Camera;
import com.voxelgame.engine.World;
import com.voxelgame.entity.Block;
import com.voxelgame.entity.Entity;
import com.voxelgame.entity.Player;
import com.voxelgame.entity.mob.MobEntity;
import com.voxelgame.entity.mob.MobType;

import java.lang.management.ManagementFactory;
import java.lang.reflect.Field;
import java.util.Arrays;

/** Chạy vòng cập nhật thật và đối chiếu chi phí của 80 thực thể đang hoạt động. */
public final class MobAiDesktopSmoke extends VoxelGameApp {
    private static final int CREATURES = 10;
    private static final int MONSTERS = 70;
    private static final MobType[] HOSTILES = {MobType.ZOMBIE, MobType.CREEPER, MobType.SPIDER,
            MobType.ENDERMAN, MobType.WITCH, MobType.SKELETON, MobType.HUSK, MobType.PARCHED};
    private static final MobType[] ANIMALS = {MobType.COW, MobType.SHEEP, MobType.PIG, MobType.GOAT, MobType.RABBIT};
    private final MobEntity[] mobs = new MobEntity[MONSTERS + CREATURES];
    private final float[] entryX = new float[mobs.length];
    private final float[] entryZ = new float[mobs.length];
    private final long[] frameNanos = new long[4096];
    private final com.sun.management.ThreadMXBean allocationCounter =
            (com.sun.management.ThreadMXBean) ManagementFactory.getThreadMXBean();
    private World world;
    private Vector3 playerPosition;
    private Vector3 playerVelocity;
    private Field skipDelta;
    private float x;
    private float z;
    private long start;
    private long previous;
    private long allocationStart;
    private int count;
    private int phase;

    public static void main(String[] args) {
        Lwjgl3ApplicationConfiguration config = new Lwjgl3ApplicationConfiguration();
        config.setTitle("Ourcraft — AI performance");
        config.setOpenGLEmulation(Lwjgl3ApplicationConfiguration.GLEmulation.GL30, 3, 3);
        config.setWindowedMode(1280, 720);
        config.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);
        config.useVsync(true);
        new Lwjgl3Application(new MobAiDesktopSmoke(), config);
    }

    @Override
    public void create() {
        super.create();
        world = (World) read(this, VoxelGameApp.class, "world");
        Player player = (Player) read(this, VoxelGameApp.class, "player");
        Camera camera = (Camera) read(this, VoxelGameApp.class, "camera");
        playerPosition = (Vector3) read(player, Entity.class, "position");
        playerVelocity = (Vector3) read(player, Entity.class, "velocity");
        skipDelta = field(VoxelGameApp.class, "skipNextMouseDelta");
        x = playerPosition.x;
        z = playerPosition.z;
        Gdx.input.setCursorCatched(false);
        for (int dx = -32; dx <= 32; dx++) {
            for (int dz = -50; dz <= 10; dz++) {
                world.setBlock((int) x + dx, 54, (int) z + dz, Block.DIRT.getId());
            }
        }
        camera.rotate(0f, -8f);
        System.out.println("GL " + Gdx.gl.glGetString(GL20.GL_RENDERER));
        start = System.nanoTime();
    }

    @Override
    public void render() {
        try {
            skipDelta.setBoolean(this, true);
        } catch (IllegalAccessException ex) {
            throw new AssertionError(ex);
        }
        playerPosition.set(x, 55f, z);
        playerVelocity.setZero();
        super.render();
        long now = System.nanoTime();
        double elapsed = (now - start) / 1e9;
        if (Gdx.gl.glGetError() != GL20.GL_NO_ERROR) {
            throw new AssertionError("Lỗi OpenGL");
        }
        if (elapsed >= 5 && previous != 0 && count < frameNanos.length) {
            if (count == 0) {
                allocationStart = allocated();
            }
            frameNanos[count++] = now - previous;
        }
        previous = now;
        if (elapsed < 12) {
            return;
        }
        report();
        if (phase++ == 0) {
            seedCrowd();
            start = System.nanoTime();
            count = 0;
            previous = 0;
        } else {
            int moving = 0;
            for (int i = 0; i < mobs.length; i++) {
                if (Math.abs(mobs[i].x() - entryX[i]) + Math.abs(mobs[i].z() - entryZ[i]) > 0.1f) {
                    moving++;
                }
            }
            if (world.entityCount() != mobs.length + 1 || moving < 50) {
                throw new AssertionError("Mẫu AI thiếu thực thể hoặc không di chuyển: " + world.entityCount() + ", " + moving);
            }
            System.out.printf("ACTIVE AI: %d entities, %d moved%n", mobs.length, moving);
            Gdx.app.exit();
        }
    }

    private void seedCrowd() {
        for (int i = 0; i < mobs.length; i++) {
            MobType type = i < MONSTERS ? HOSTILES[i % HOSTILES.length] : ANIMALS[i % ANIMALS.length];
            float mobX = x + (i % 10 - 4.5f) * 3.7f;
            float mobZ = z - 9 - (i / 10) * 4.5f;
            MobEntity mob = new MobEntity(type, mobX, 55f, mobZ);
            mobs[i] = mob;
            entryX[i] = mobX;
            entryZ[i] = mobZ;
            world.addEntity(mob);
        }
    }

    private long allocated() {
        return allocationCounter.getThreadAllocatedBytes(Thread.currentThread().getId());
    }

    private void report() {
        double bytesPerFrame = (allocated() - allocationStart) / (double) count;
        long total = 0L;
        for (int i = 0; i < count; i++) {
            total += frameNanos[i];
        }
        Arrays.sort(frameNanos, 0, count);
        System.out.printf("%d mobs: %.2f FPS, p95 %.2f ms, %d frames, %.1f Java bytes/frame%n",
                phase == 0 ? 0 : mobs.length, count * 1e9 / total,
                frameNanos[(int) Math.ceil(count * 0.95) - 1] / 1e6, count, bytesPerFrame);
    }

    private static Field field(Class<?> type, String name) {
        try {
            Field field = type.getDeclaredField(name);
            field.setAccessible(true);
            return field;
        } catch (ReflectiveOperationException ex) {
            throw new AssertionError(ex);
        }
    }

    private static Object read(Object owner, Class<?> type, String name) {
        try {
            return field(type, name).get(owner);
        } catch (IllegalAccessException ex) {
            throw new AssertionError(ex);
        }
    }
}

