/** Chạy lượt vẽ thật với 24 mẫu thử và xác minh vòng đời tài nguyên trước khi GLFW đóng. */
public final class MobDesktopSmoke extends VoxelGameApp {
    private static final MobAppearance[] DISPLAY = {
            MobAppearance.ZOMBIE, MobAppearance.WOLF_SNOWY_ANGRY, MobAppearance.CREEPER,
            MobAppearance.SHEEP, MobAppearance.GOAT, MobAppearance.SNOW_FOX_SLEEP,
            MobAppearance.CHICKEN, MobAppearance.HUSK, MobAppearance.SKELETON,
            MobAppearance.SPIDER, MobAppearance.ENDERMAN, MobAppearance.WITCH,
            MobAppearance.COW, MobAppearance.PIG, MobAppearance.HORSE_BROWN,
            MobAppearance.DONKEY, MobAppearance.CAMEL, MobAppearance.POLAR_BEAR,
            MobAppearance.PARCHED, MobAppearance.STRAY, MobAppearance.ZOMBIE_VILLAGER,
            MobAppearance.RABBIT_GOLD, MobAppearance.RABBIT_WHITE_SPLOTCHED, MobAppearance.CAMEL_HUSK
    };
    private static final MobVisualState.Pose[] POSES = {
            MobVisualState.Pose.UNDEAD, MobVisualState.Pose.TILT_HEAD, MobVisualState.Pose.IDLE,
            MobVisualState.Pose.GRAZE, MobVisualState.Pose.RAM, MobVisualState.Pose.SLEEP,
            MobVisualState.Pose.FLAP, MobVisualState.Pose.THRUST, MobVisualState.Pose.AIM_BOW,
            MobVisualState.Pose.IDLE, MobVisualState.Pose.ANGRY, MobVisualState.Pose.IDLE,
            MobVisualState.Pose.GRAZE, MobVisualState.Pose.IDLE, MobVisualState.Pose.IDLE,
            MobVisualState.Pose.IDLE, MobVisualState.Pose.SIT, MobVisualState.Pose.REAR,
            MobVisualState.Pose.AIM_BOW, MobVisualState.Pose.AIM_BOW, MobVisualState.Pose.UNDEAD,
            MobVisualState.Pose.HOP, MobVisualState.Pose.HOP, MobVisualState.Pose.IDLE
    };
    private final long[] intervals = new long[4096];
    private final com.sun.management.ThreadMXBean allocationCounter =
            (com.sun.management.ThreadMXBean) ManagementFactory.getThreadMXBean();
    private World world;
    private Field skipDelta;
    private Vector3 playerPosition;
    private Vector3 playerVelocity;
    private float x;
    private float z;
    private int samples;
    private long started;
    private long previous;
    private long allocationStart;
    private int phase;
    private boolean verifiedFrames;

    public static void main(String[] args) {
        Lwjgl3ApplicationConfiguration config = new Lwjgl3ApplicationConfiguration();
        config.setTitle("Ourcraft");
        config.setOpenGLEmulation(Lwjgl3ApplicationConfiguration.GLEmulation.GL30, 3, 3);
        config.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);
        config.setWindowedMode(1280, 720);
        config.useVsync(true);
        new Lwjgl3Application(new MobDesktopSmoke(), config);
    }

    @Override
    public void create() {
        super.create();
        world = (World) read(this, VoxelGameApp.class, "world");
        Player player = (Player) read(this, VoxelGameApp.class, "player");
        Camera camera = (Camera) read(this, VoxelGameApp.class, "camera");
        Gdx.input.setCursorCatched(false);
        Vector3 spawn = player.getPosition();
        x = spawn.x;
        z = spawn.z;
        int bx = (int) x;
        int bz = (int) z;
        for (int xx = bx - 11; xx <= bx + 11; xx++) {
            for (int zz = bz - 22; zz <= bz + 1; zz++) {
                world.setBlock(xx, 54, zz, Block.DIRT.getId());
            }
        }
        player.setPosition(x, 55f, z);
        playerPosition = (Vector3) read(player, Entity.class, "position");
        playerVelocity = (Vector3) read(player, Entity.class, "velocity");
        skipDelta = field(VoxelGameApp.class, "skipNextMouseDelta");
        camera.rotate(0f, -10f);
        System.out.println("GL " + Gdx.gl.glGetString(GL20.GL_RENDERER) + ", monitor "
                + GLFW.glfwGetVideoMode(GLFW.glfwGetPrimaryMonitor()).refreshRate() + " Hz");
        started = System.nanoTime();
    }

    @Override
    public void render() {
        try {
            skipDelta.setBoolean(this, true);
        } catch (IllegalAccessException error) {
            throw new AssertionError(error);
        }
        playerPosition.set(x, 55f, z);
        playerVelocity.setZero();
        super.render();
        long now = System.nanoTime();
        double elapsed = (now - started) / 1e9;
        require(Gdx.gl.glGetError() == GL20.GL_NO_ERROR, "OpenGL error");
        if (elapsed >= 5 && previous != 0 && samples < intervals.length) {
            if (samples == 0) {
                allocationStart = allocated();
            }
            intervals[samples++] = now - previous;
        }
        previous = now;
        if (elapsed < 11) {
            return;
        }
        printTiming();
        if (phase++ == 0) {
            for (int i = 0; i < DISPLAY.length; i++) {
                GalleryMob mob = new GalleryMob(x + (i % 6 - 2.5f) * 1.9f, 55f + (i / 6) * 0.16f,
                        z - 6.4f - (i / 6) * 3.7f, DISPLAY[i], POSES[i], i);
                world.addLivingEntity(mob);
            }
            world.addEntity(new GalleryProjectile(x - 6f, 56.4f, z - 8f, MobAppearance.ARROW, 38f));
            world.addEntity(new GalleryProjectile(x + 6f, 56.3f, z - 8f, MobAppearance.POTION, -28f));
            AudioManager audio = (AudioManager) read(this, VoxelGameApp.class, "audioManager");
            audio.playMobSound("goat", MobSoundEvent.GOAT_SCREAM, x, 55f, z - 6, 0, 1.5f);
            audio.playMobSound("creeper", MobSoundEvent.CREEPER_PRIMED, x, 55f, z - 8, 0, 1);
            require(AL10.alGetError() == AL10.AL_NO_ERROR, "OpenAL báo lỗi phát mob");
            started = System.nanoTime();
            previous = 0;
            samples = 0;
        } else {
            Pixmap snapshot = Pixmap.createFromFrameBuffer(0, 0, 1280, 720);
            try {
                PixmapIO.writePNG(Gdx.files.local("build/mob-render-smoke.png"), snapshot, -1, true);
            } finally {
                snapshot.dispose();
            }
            verifiedFrames = true;
            Gdx.app.exit();
        }
    }

    private long allocated() {
        return allocationCounter.getThreadAllocatedBytes(Thread.currentThread().getId());
    }

    private void printTiming() {
        long total = 0L;
        for (int i = 0; i < samples; i++) {
            total += intervals[i];
        }
        Arrays.sort(intervals, 0, samples);
        System.out.printf("%d mobs%s: %.2f FPS, p95 %.2f ms, %d frames, %.1f Java bytes/frame%n",
                phase == 0 ? 0 : DISPLAY.length, phase == 0 ? "" : " + 2 projectiles",
                samples * 1e9 / total,
                intervals[(int) Math.ceil(samples * 0.95) - 1] / 1e6, samples,
                (allocated() - allocationStart) / (double) samples);
    }

    @Override
    public void dispose() {
        if (!verifiedFrames) {
            super.dispose();
            return;
        }
        Object manager = read(this, VoxelGameApp.class, "mobTextures");
        Object renderer = read(this, VoxelGameApp.class, "mobRenderer");
        Object audio = read(this, VoxelGameApp.class, "audioManager");
        checkTextureFallback(manager);
        Map<?, ?> skins = (Map<?, ?>) read(manager, "skins");
        Map<?, ?> meshes = (Map<?, ?>) read(renderer, "meshes");
        int[] textures = skins.values().stream().mapToInt(skin ->
                ((com.badlogic.gdx.graphics.Texture) call(skin, "texture")).getTextureObjectHandle()).toArray();
        int[] buffers = new int[meshes.size()];
        int[] arrays = new int[meshes.size()];
        int index = 0;
        int boundMeshes = 0;
        for (Object mesh : meshes.values()) {
            Object vertexData = read(mesh, Mesh.class, "vertices");
            buffers[index] = (int) read(vertexData, "bufferHandle");
            arrays[index] = (int) read(vertexData, "vaoHandle");
            if (GL15.glIsBuffer(buffers[index]) && GL30.glIsVertexArray(arrays[index])) {
                boundMeshes++;
            }
            index++;
        }
        Object bank = read(audio, "mobSounds");
        Map<?, ?> sounds = (Map<?, ?>) read(bank, "samplesByMob");
        int[] soundBuffers = new int[212];
        int soundCount = 0;
        for (Object groups : sounds.values()) {
            soundCount = readSoundBuffers((Object[][]) groups, soundBuffers, soundCount);
        }
        soundCount = readSoundBuffers((Object[][]) read(bank, "sharedSamples"), soundBuffers, soundCount);
        require(soundCount == soundBuffers.length && boundMeshes > 40, "Chưa nạp hoặc chưa dùng đủ tài nguyên test");
        super.dispose();
        for (int id : textures) require(!GL11.glIsTexture(id), "Texture mob chưa giải phóng");
        for (int id : buffers) require(!GL15.glIsBuffer(id), "VBO mob chưa giải phóng");
        for (int id : arrays) require(!GL30.glIsVertexArray(id), "VAO mob chưa giải phóng");
        for (int id : soundBuffers) require(!AL10.alIsBuffer(id), "OpenAL buffer mob chưa giải phóng");
        System.out.printf("LIFECYCLE OK: %d textures, %d meshes (%d used), %d AL buffers%n",
                textures.length, buffers.length, boundMeshes, soundCount);
    }

    private static int readSoundBuffers(Object[][] groups, int[] ids, int index) {
        for (Object[] group : groups) {
            if (group == null) continue;
            for (Object sample : group) {
                int id = (int) read(sample, OpenALSound.class, "bufferID");
                require(AL10.alIsBuffer(id), "OpenAL buffer chưa được nạp");
                ids[index++] = id;
            }
        }
        return index;
    }

    private static void checkTextureFallback(Object manager) {
        try {
            MobTextureKey missing = new MobTextureKey("smoke", "missing", 0xe71587);
            Method load = manager.getClass().getDeclaredMethod("load", MobTextureKey.class);
            load.setAccessible(true);
            Object skin = load.invoke(manager, missing);
            require(skin == load.invoke(manager, missing)
                    && (boolean) call(skin, "fallback") && (int) call(skin, "width") == 16
                    && (int) call(skin, "height") == 16, "Ảnh thiếu phải tạo đúng một fallback 16 x 16");
        } catch (ReflectiveOperationException error) {
            throw new AssertionError(error);
        }
    }

    private static Object call(Object object, String name) {
        try {
            Method method = object.getClass().getDeclaredMethod(name);
            method.setAccessible(true);
            return method.invoke(object);
        } catch (ReflectiveOperationException error) {
            throw new AssertionError(error);
        }
    }

    private static Object read(Object object, String name) {
        return read(object, object.getClass(), name);
    }

    private static Object read(Object object, Class<?> owner, String name) {
        try {
            return field(owner, name).get(object);
        } catch (ReflectiveOperationException error) {
            throw new AssertionError(error);
        }
    }

    private static Field field(Class<?> owner, String name) {
        try {
            Field field = owner.getDeclaredField(name);
            field.setAccessible(true);
            return field;
        } catch (ReflectiveOperationException error) {
            throw new AssertionError(error);
        }
    }

    private static void require(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    /** Thực thể thử độc lập với bộ sinh và AI gameplay. */
    private static final class GalleryMob extends LivingEntity implements MobVisual {
        private final MobVisualState state;
        private final int id;
        private float age;

        GalleryMob(float x, float y, float z, MobAppearance appearance, MobVisualState.Pose pose, int id) {
            super(x, y, z, 0.8f, 2.1f, 20f, 0f, false);
            this.id = id;
            state = new MobVisualState(appearance);
            state.setPose(pose, 0.9f);
            if (appearance == MobAppearance.HORSE_BROWN) {
                state.setHorseMarkings(MobAppearance.HorseMarkings.WHITE_DOTS);
            } else if (appearance == MobAppearance.CREEPER) {
                state.setFuseProgress(0.72f);
            }
        }

        @Override
        protected void updateLiving(World world, float seconds) {
            age += seconds * 20f;
            state.setAnimation(145f + id % 4 * 25f, (float) Math.sin(age * 0.07f) * 15f, 0f,
                    age * 0.14f + id, 0.15f, age);
            if (state.appearance() == MobAppearance.CREEPER) {
                state.setFuseProgress(age % 30f / 30f);
            }
            if (id == 0 && getHurtFlashTimer() <= 0f) {
                damage(world, 1f, DamageSource.MELEE, null, 0f, 0f);
                heal(1f);
            }
        }

        @Override
        public void render(ShaderProgram shader) {
            throw new AssertionError("Mob thử phải đi qua lượt vẽ phân khớp");
        }

        @Override
        public MobVisualState mobVisualState() {
            return state;
        }
    }

    /** Vật thử không có HP để xác nhận renderer hỗ trợ giao diện ngoài LivingEntity. */
    private static final class GalleryProjectile extends Entity implements MobVisual {
        private final MobVisualState state;

        GalleryProjectile(float x, float y, float z, MobAppearance appearance, float pitch) {
            super(x, y, z, 0.15f, 0.3f);
            state = new MobVisualState(appearance);
            state.setAnimation(125f, 0f, 0f, 0f, 0f, 0f);
            state.setBodyPitch(pitch);
        }

        @Override
        public void update(World world, float seconds) {
        }

        @Override
        public void render(ShaderProgram shader) {
            throw new AssertionError("Đạn thử phải đi qua lượt vẽ phân khớp");
        }

        @Override
        public MobVisualState mobVisualState() {
            return state;
        }
    }
}

