/** Kiểm tra cửa sổ, đầu vào GLFW, hình ảnh frame thật và âm thanh OpenAL trên desktop. */
public final class MountDesktopSmoke extends VoxelGameApp {
    private final Vector3 arena = new Vector3();
    private final Vector3 beforeMove = new Vector3();
    private final Vector3 probe = new Vector3();
    private World world;
    private WorldTime clock;
    private WeatherManager weather;
    private Camera camera;
    private Player player;
    private Camel camel;
    private CamelHusk jockey;
    private Parched archer;
    private Object[] dashClips;
    private Object[] spearClips;
    private IntArray audioSources;
    private GLFWKeyCallback keyCallback;
    private GLFWMouseButtonCallback clickCallback;
    private long window;
    private Field skipMouse;
    private long phaseStarted;
    private int phase;
    private int timeBeforeFast;
    private boolean dashHeard;
    private boolean spearHeard;
    private boolean arrowSeen;
    private float peakDash;

    public static void main(String[] args) {
        Lwjgl3ApplicationConfiguration config = new Lwjgl3ApplicationConfiguration();
        config.setTitle("Ourcraft");
        config.setOpenGLEmulation(Lwjgl3ApplicationConfiguration.GLEmulation.GL30, 3, 3);
        config.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);
        config.setWindowedMode(1280, 720);
        config.useVsync(true);
        new Lwjgl3Application(new MountDesktopSmoke(), config);
    }

    @Override
    public void create() {
        super.create();
        world = (World) read(this, VoxelGameApp.class, "world");
        clock = (WorldTime) read(this, VoxelGameApp.class, "worldTime");
        weather = (WeatherManager) read(this, VoxelGameApp.class, "weather");
        camera = (Camera) read(this, VoxelGameApp.class, "camera");
        player = world.getPlayer();
        skipMouse = field(VoxelGameApp.class, "skipNextMouseDelta");
        window = ((Lwjgl3Graphics) Gdx.graphics).getWindow().getWindowHandle();
        keyCallback = (GLFWKeyCallback) read(Gdx.input, Gdx.input.getClass(), "keyCallback");
        clickCallback = (GLFWMouseButtonCallback) read(Gdx.input, Gdx.input.getClass(), "mouseButtonCallback");
        audioSources = (IntArray) read(Gdx.audio, Gdx.audio.getClass(), "allSources");
        Object bank = read(world.getAudio(), AudioManager.class, "mobSounds");
        Map<?, ?> clipsByMob = (Map<?, ?>) read(bank, bank.getClass(), "samplesByMob");
        dashClips = ((Object[][]) clipsByMob.get("camel"))[MobSoundEvent.CAMEL_DASH.ordinal()];
        spearClips = ((Object[][]) read(bank, bank.getClass(), "sharedSamples"))[MobSoundEvent.SPEAR_CHARGE.ordinal()];
        String title = nativeWindowTitle(window);
        require("Ourcraft".equals(title), "Wrong native title: " + title);
        System.out.println("WINDOW " + title + " | GL " + Gdx.gl.glGetString(GL20.GL_RENDERER));
        tap(GLFW_KEY_F7);
        tap(GLFW_KEY_F7);
        tap(GLFW_KEY_F6);
        tour();
        phaseStarted = System.nanoTime();
    }

    /** Gọi chính callback mà LWJGL dùng để đi qua hàng đợi và trạng thái phím dạng giữ. */
    private void key(int key, int action) {
        keyCallback.invoke(window, key, 0, action, key == GLFW_KEY_LEFT_CONTROL ? GLFW_MOD_CONTROL : 0);
    }

    private void tap(int key) {
        key(key, GLFW_PRESS);
        key(key, GLFW_RELEASE);
    }

    private void tour() {
        key(GLFW_KEY_LEFT_CONTROL, GLFW_PRESS);
        tap(GLFW_KEY_C);
        key(GLFW_KEY_LEFT_CONTROL, GLFW_RELEASE);
    }

    private void rightClick() {
        clickCallback.invoke(window, GLFW_MOUSE_BUTTON_RIGHT, GLFW_PRESS, 0);
        clickCallback.invoke(window, GLFW_MOUSE_BUTTON_RIGHT, GLFW_RELEASE, 0);
    }

    @Override
    public void render() {
        try {
            skipMouse.setBoolean(this, true);
        } catch (IllegalAccessException error) {
            throw new IllegalStateException(error);
        }
        super.render();
        double elapsed = (System.nanoTime() - phaseStarted) * 1e-9;
        require(elapsed < 14, "Timeout phase " + phase + " tick=" + clock.tickOfDay());
        require(Gdx.gl.glGetError() == GL20.GL_NO_ERROR && AL10.alGetError() == AL10.AL_NO_ERROR,
                "OpenGL or OpenAL error during phase " + phase);

        switch (phase) {
            case 0 -> {
                if (elapsed > 2.1) {
                    require(biome() == BiomeType.SNOWY_PLAINS && weather.strength() > 0.2f
                            && clock.tickOfDay() > 6000 && clock.tickOfDay() < 6180, "Ctrl+C/F6/F7 snow or noon");
                    capture("snow");
                    timeBeforeFast = clock.tickOfDay();
                    tap(GLFW_KEY_F8);
                    next();
                }
            }
            case 1 -> {
                if (elapsed > 0.3) {
                    require(clock.tickOfDay() > timeBeforeFast + 80, "F8 did not advance clock at fast speed");
                    tap(GLFW_KEY_F8);
                    tour();
                    next();
                }
            }
            case 2 -> {
                if (elapsed > 1) {
                    require(biome() == BiomeType.PLAINS && weather.rainVolume() > 0f, "Ctrl+C/F6 Plains rain");
                    prepareArena(Block.GRASS);
                    MobEntity horse = MobType.HORSE.create(arena.x - 1.8f, arena.y, arena.z - 4.2f);
                    MobEntity donkey = MobType.DONKEY.create(arena.x + 1.8f, arena.y, arena.z - 4.5f);
                    world.addEntity(horse);
                    world.addEntity(donkey);
                    next();
                }
            }
            case 3 -> {
                if (elapsed > 0.9) {
                    capture("plains-equines");
                    tour();
                    next();
                }
            }
            case 4 -> {
                if (elapsed > 2) {
                    require(biome() == BiomeType.DESERT && "CLEAR".equals(weather.label())
                            && weather.rainVolume() == 0f, "Ctrl+C Desert stays dry after rain fade");
                    prepareArena(Block.SANDSTONE);
                    camel = (Camel) MobType.CAMEL.create(arena.x, arena.y, arena.z - 3f);
                    world.addEntity(camel);
                    next();
                }
            }
            case 5 -> {
                if (elapsed > 0.35) {
                    capture("camel-before-boarding");
                    rightClick();
                    next();
                }
            }
            case 6 -> {
                if (elapsed > 0.1) {
                    require(player.getMount() == camel && player.getMountedSeat() == 0, "Aimed RMB did not board Camel");
                    camel.copyPosition(beforeMove);
                    key(GLFW_KEY_W, GLFW_PRESS);
                    key(GLFW_KEY_D, GLFW_PRESS);
                    next();
                }
            }
            case 7 -> {
                if (elapsed > 0.55) {
                    require(camel.x() > beforeMove.x + 0.75f && camel.z() < beforeMove.z - 0.75f, "W/D rider control");
                    camel.copyPosition(beforeMove);
                    key(GLFW_KEY_W, GLFW_RELEASE);
                    key(GLFW_KEY_D, GLFW_RELEASE);
                    key(GLFW_KEY_S, GLFW_PRESS);
                    key(GLFW_KEY_A, GLFW_PRESS);
                    next();
                }
            }
            case 8 -> {
                if (elapsed > 0.55) {
                    require(camel.x() < beforeMove.x - 0.65f && camel.z() > beforeMove.z + 0.65f, "S/A rider control");
                    key(GLFW_KEY_S, GLFW_RELEASE);
                    key(GLFW_KEY_A, GLFW_RELEASE);
                    key(GLFW_KEY_W, GLFW_PRESS);
                    key(GLFW_KEY_SPACE, GLFW_PRESS);
                    next();
                }
            }
            case 9 -> {
                if (camel.chargeProgress() > 0.62f) {
                    camel.copyPosition(beforeMove);
                    capture("hud-charging");
                    key(GLFW_KEY_SPACE, GLFW_RELEASE);
                    next();
                }
            }
            case 10 -> {
                peakDash = Math.max(peakDash, camel.dashCooldownRemaining());
                if (!dashHeard) {
                    dashHeard = playing(dashClips);
                }
                if (elapsed > 0.48) {
                    require(dashHeard && peakDash > 2.69f && camel.z() < beforeMove.z - 6f, "Dash, cooldown or OpenAL buffer");
                    capture("hud-cooldown");
                    key(GLFW_KEY_W, GLFW_RELEASE);
                    next();
                }
            }
            case 11 -> {
                if (elapsed > 0.38) {
                    key(GLFW_KEY_LEFT_SHIFT, GLFW_PRESS);
                    next();
                }
            }
            case 12 -> {
                if (elapsed > 0.14) {
                    key(GLFW_KEY_LEFT_SHIFT, GLFW_RELEASE);
                    require(player.getMount() == null && player.isOnGround(), "Shift did not safely dismount");
                    System.out.printf("MOUNT RMB, WASD, Space and Shift OK | dash %.3f s | OpenAL DASH playing%n", peakDash);
                    player.setPosition(arena.x, arena.y, arena.z);
                    camera.rotate(0f, 8f - camera.getPitch());
                    jockey = new CamelHusk(arena.x, arena.y, arena.z - 8.5f);
                    Husk lancer = new Husk(jockey.x(), jockey.y() + jockey.getHeight(), jockey.z(), true);
                    archer = new Parched(jockey.x(), jockey.y() + jockey.getHeight(), jockey.z());
                    require(lancer.tryMount(jockey, 0) && archer.tryMount(jockey, 1), "Cannot set desktop encounter");
                    world.addEntity(jockey);
                    world.addEntity(lancer);
                    world.addEntity(archer);
                    next();
                }
            }
            case 13 -> {
                boolean firstSpear = !spearHeard && playing(spearClips);
                if (firstSpear) {
                    spearHeard = true;
                    capture("camel-husk-spear");
                }
                for (int index = 0, count = world.entityCount(); index < count; index++) {
                    if (!arrowSeen && world.entityAt(index) instanceof ArrowEntity arrow && arrow.owner() == archer) {
                        arrowSeen = true;
                        capture("camel-husk-arrow");
                    }
                }
                if (spearHeard && arrowSeen) {
                    System.out.println("JOCKEY actual SPEAR_CHARGE OpenAL buffer playing and rear Parched arrow spawned");
                    tap(GLFW_KEY_F7);
                    tap(GLFW_KEY_F7);
                    next();
                }
            }
            case 14 -> {
                if (elapsed > 0.28) {
                    require(clock.tickOfDay() >= 18000 && clock.tickOfDay() < 18100, "F7 did not reach midnight");
                    capture("desert-midnight");
                    System.out.println("TOUR Ctrl+C Snowy Plains, Plains, Desert | F6 snow/rain | F7 noon/midnight | F8 fast clock OK");
                    Gdx.app.exit();
                }
            }
            default -> throw new IllegalStateException("Unknown stage");
        }
    }

    /** Tách trường quay khỏi vật cản địa hình để hành động có đường đi xác định. */
    private void prepareArena(Block floor) {
        player.copyPosition(arena);
        arena.x = (float) Math.floor(arena.x) + 0.5f;
        arena.z = (float) Math.floor(arena.z) + 0.5f;
        arena.y = (float) Math.floor(arena.y) + 13f;
        for (int x = (int) arena.x - 12; x <= arena.x + 12; x++) {
            for (int z = (int) arena.z - 23; z <= arena.z + 5; z++) {
                world.setBlock(x, (int) arena.y - 1, z, floor.getId());
            }
        }
        player.setPosition(arena.x, arena.y, arena.z);
        camera.rotate(-90f - camera.getYaw(), -4f - camera.getPitch());
    }

    private BiomeType biome() {
        player.copyPosition(probe);
        return world.getBiome((int) probe.x, (int) probe.z);
    }

    /** Nhận đúng buffer được sự kiện trong gameplay phát, kể cả mẫu chọn ngẫu nhiên. */
    private boolean playing(Object[] clips) {
        for (int index = 0; index < audioSources.size; index++) {
            int source = audioSources.get(index);
            if (AL10.alGetSourcei(source, AL10.AL_SOURCE_STATE) != AL10.AL_PLAYING) {
                continue;
            }
            int buffer = AL10.alGetSourcei(source, AL10.AL_BUFFER);
            for (Object clip : clips) {
                if (buffer == (int) read(clip, clip.getClass().getSuperclass(), "bufferID")) {
                    return true;
                }
            }
        }
        return false;
    }

    private void capture(String name) {
        Pixmap pixels = Pixmap.createFromFrameBuffer(0, 0, Gdx.graphics.getWidth(), Gdx.graphics.getHeight());
        try {
            PixmapIO.writePNG(Gdx.files.local("build/mount-desktop-" + name + ".png"), pixels, -1, true);
        } finally {
            pixels.dispose();
        }
    }

    private void next() {
        phase++;
        phaseStarted = System.nanoTime();
    }

    /** Đọc từ HWND, tránh suy diễn tiêu đề từ chuỗi được truyền vào cấu hình. */
    private static String nativeWindowTitle(long window) {
        long hwnd = GLFWNativeWin32.glfwGetWin32Window(window);
        long getter = User32.getLibrary().getFunctionAddress("GetWindowTextW");
        try (MemoryStack stack = MemoryStack.stackPush()) {
            ByteBuffer buffer = stack.malloc(128);
            int size = JNI.callPPI(hwnd, MemoryUtil.memAddress(buffer), buffer.capacity() / 2, getter);
            char[] title = new char[size];
            buffer.asCharBuffer().get(title);
            return new String(title);
        }
    }

    private static Field field(Class<?> type, String name) {
        try {
            Field field = type.getDeclaredField(name);
            field.setAccessible(true);
            return field;
        } catch (ReflectiveOperationException error) {
            throw new IllegalStateException(error);
        }
    }

    private static Object read(Object target, Class<?> type, String name) {
        try {
            return field(type, name).get(target);
        } catch (IllegalAccessException error) {
            throw new IllegalStateException(error);
        }
    }

    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

import java.io.ByteArrayOutputStream;
import java.io.FileInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import javax.sound.sampled.AudioFileFormat;
import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioInputStream;
import javax.sound.sampled.AudioSystem;
import java.io.ByteArrayInputStream;
import javazoom.jl.decoder.Bitstream;
import javazoom.jl.decoder.MP3Decoder;
import javazoom.jl.decoder.Header;
import javazoom.jl.decoder.OutputBuffer;

class PrepareRainLoop {
    public static void main(String[] args) throws Exception {
        Bitstream stream = new Bitstream(new FileInputStream(args[0]));
        MP3Decoder decoder = new MP3Decoder();
        Header frame = stream.readFrame();
        int channels = frame.mode() == Header.SINGLE_CHANNEL ? 1 : 2;
        int rate = frame.frequency();
        OutputBuffer decodeBuffer = new OutputBuffer(channels, false);
        decoder.setOutputBuffer(decodeBuffer);
        ByteArrayOutputStream mono = new ByteArrayOutputStream();
        do {
            decoder.decodeFrame(frame, stream);
            int size = decodeBuffer.reset();
            byte[] pcm = decodeBuffer.getBuffer();
            for (int i = 0; i < size; i += channels * 2) {
                int value = sample(pcm, i);
                if (channels == 2) value = (value + sample(pcm, i + 2)) / 2;
                write(mono, value);
            }
            stream.closeFrame();
        } while ((frame = stream.readFrame()) != null);
        stream.close();
        byte[] source = mono.toByteArray();
        int start = (int) (rate * 1.25);
        int end = rate * 12;
        int crossfade = (int) (rate * 0.65);
        ByteArrayOutputStream result = new ByteArrayOutputStream();
        result.write(source, 2 * (start + crossfade), 2 * (end - start - 2 * crossfade));
        for (int i = 0; i < crossfade; i++) {
            double t = i / (double) (crossfade - 1);
            double weight = t * t * (3 - 2 * t);
            double outGain = Math.sqrt(1 - weight);
            double inGain = Math.sqrt(weight);
            double value = sample(source, (end - crossfade + i) * 2) * outGain
                         + sample(source, (start + i) * 2) * inGain;
            write(result, (int) Math.round(Math.max(-32768, Math.min(32767, value))));
        }
        byte[] loop = result.toByteArray();
        AudioFormat format = new AudioFormat(rate, 16, 1, true, false);
        try (AudioInputStream playback = new AudioInputStream(new ByteArrayInputStream(loop), format, loop.length / 2)) {
            AudioSystem.write(playback, AudioFileFormat.Type.WAVE, Path.of(args[1]).toFile());
        }
        System.out.printf("loop %.3fs at %d Hz, seam %d to %d PCM units (%d delta)%n", loop.length / 2d / rate,
                rate, sample(loop, loop.length - 2), sample(loop, 0), sample(loop, 0) - sample(loop, loop.length - 2));
    }

    private static int sample(byte[] pcm, int i) {
        return (short) ((pcm[i] & 255) | (pcm[i + 1] << 8));
    }

    private static void write(ByteArrayOutputStream bytes, int sample) {
        bytes.write(sample & 255);
        bytes.write((sample >> 8) & 255);
    }
}

import java.io.FileInputStream;
import javazoom.jl.decoder.Bitstream;
import javazoom.jl.decoder.MP3Decoder;
import javazoom.jl.decoder.Header;
import javazoom.jl.decoder.OutputBuffer;

class RainSample {
    public static void main(String[] args) throws Exception {
        Bitstream data = new Bitstream(new FileInputStream(args[0]));
        MP3Decoder decoder = new MP3Decoder();
        double[] energy = new double[5000];
        int first = 0;
        int last = 0;
        int count = 0;
        float frameMillis = 0;
        Header header;
        OutputBuffer output = null;
        while ((header = data.readFrame()) != null) {
            frameMillis = header.ms_per_frame();
            if (output == null) { output = new OutputBuffer(header.mode() == Header.SINGLE_CHANNEL ? 1 : 2, false); decoder.setOutputBuffer(output); }
            decoder.decodeFrame(header, data);
            int length = output.reset() / 2;
            byte[] bytes = output.getBuffer();
            short[] samples = new short[length];
            for (int i = 0; i < length; i++) samples[i] = (short) ((bytes[i * 2] & 255) | (bytes[i * 2 + 1] << 8));
            if (count == 0) first = samples[0];
            last = samples[length - 1];
            double sum = 0;
            for (int i = 0; i < length; i++) sum += (double) samples[i] * samples[i];
            energy[count++] = Math.sqrt(sum / length);
            data.closeFrame();
        }
        data.close();
        System.out.printf("duration=%.2fs first=%d last=%d%n", count * frameMillis / 1000, first, last);
        for (int i = 0; i < count; i++) {
            if (i < 12 || i >= count - 12 || i % 100 == 0) System.out.printf("%d:%.0f ", i, energy[i]);
        }
        System.out.println();
    }
}

package com.voxelgame.engine;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.Input;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3Application;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3ApplicationConfiguration;
import com.badlogic.gdx.graphics.GL20;
import com.voxelgame.VoxelGameApp;
import com.voxelgame.entity.Player;
import java.lang.reflect.Field;
import java.util.Arrays;

/** Kịch bản đo nội bộ cho một góc nhìn núi, mưa ở Plains và tuyết ở vùng lạnh. */
public class TerrainDesktopSmoke extends VoxelGameApp {
    private final String[] names = {"alpine-clear", "plains-rain", "alpine-snow"};
    private final long[] frameTimes = new long[12000];
    private int phase;
    private int count;
    private long since;
    private long previous;
    private World world;
    private Player player;

    public static void main(String[] args) {
        Lwjgl3ApplicationConfiguration config = new Lwjgl3ApplicationConfiguration();
        config.setTitle("VoxelGame terrain performance check");
        config.setOpenGLEmulation(Lwjgl3ApplicationConfiguration.GLEmulation.GL30, 3, 3);
        config.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);
        config.setWindowedMode(1280, 720);
        config.useVsync(true);
        new Lwjgl3Application(new TerrainDesktopSmoke(), config);
    }

    @Override public void create() {
        long started = System.nanoTime();
        super.create();
        System.out.printf("game-create %.3f s, GL: %s%n", (System.nanoTime() - started) / 1e9,
                Gdx.gl.glGetString(GL20.GL_RENDERER));
        world = (World) field("world");
        player = (Player) field("player");
        advance(0);
    }

    @Override public void render() {
        super.render();
        long now = System.nanoTime();
        long elapsed = now - since;
        if (elapsed >= 7_000_000_000L && elapsed < 12_000_000_000L && previous != 0
                && count < frameTimes.length) {
            frameTimes[count++] = now - previous;
        }
        previous = now;
        if (elapsed < 12_000_000_000L) {
            return;
        }
        if (count == 0 || Gdx.gl.glGetError() != GL20.GL_NO_ERROR) {
            throw new AssertionError("Desktop smoke failed in " + names[phase]);
        }
        Arrays.sort(frameTimes, 0, count);
        long sum = 0;
        for (int i = 0; i < count; i++) {
            sum += frameTimes[i];
        }
        System.out.printf("%s: %.2f FPS, p95 %.2f ms, frames %d%n", names[phase], count * 1e9 / sum,
                frameTimes[(int) (0.95d * (count - 1))] / 1e6, count);
        if (++phase == names.length) {
            Gdx.app.exit();
        } else {
            advance(phase);
        }
    }

    private void advance(int next) {
        int x = next == 1 ? 1500 : 420;
        int z = next == 1 ? 896 : 960;
        float surface = world.getPrecipitationSurface(x, z);
        player.setPosition(x + 0.5f, surface + 0.1f, z + 0.5f);
        if (next == 1) {
            keyDown(Input.Keys.F6);
        }
        count = 0;
        previous = 0;
        since = System.nanoTime();
        System.out.printf("phase %s biome %s surface %.2f%n", names[next], world.getBiome(x, z), surface);
    }

    private Object field(String name) {
        try {
            Field field = VoxelGameApp.class.getDeclaredField(name);
            field.setAccessible(true);
            return field.get(this);
        } catch (ReflectiveOperationException failure) {
            throw new IllegalStateException(failure);
        }
    }
}

import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3Application;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3ApplicationConfiguration;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Mesh;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.VertexAttribute;
import com.badlogic.gdx.graphics.VertexAttributes.Usage;
import com.badlogic.gdx.math.Matrix4;
import com.badlogic.gdx.math.Vector3;
import com.voxelgame.engine.ShaderProgram;
import java.lang.reflect.Method;

/** Kiểm tra shader trên OpenGL thật qua màu pixel giữa khung hình. */
public final class TerrainFogSmoke extends ApplicationAdapter {
    public static void main(String[] args) {
        if (args.length > 0) {
            try {
                ShaderProgram.class.getMethod("enableDistanceFog", Vector3.class, float.class, float.class);
                ShaderProgram.class.getMethod("disableDistanceFog");
            } catch (ReflectiveOperationException error) {
                throw new AssertionError("Shader chưa cung cấp chế độ sương xa cho lượt thế giới", error);
            }
            return;
        }
        Lwjgl3ApplicationConfiguration configuration = new Lwjgl3ApplicationConfiguration();
        configuration.setInitialVisible(false);
        configuration.disableAudio(true);
        configuration.setWindowedMode(64, 64);
        configuration.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);
        configuration.setOpenGLEmulation(Lwjgl3ApplicationConfiguration.GLEmulation.GL30, 3, 3);
        new Lwjgl3Application(new TerrainFogSmoke(), configuration);
    }

    @Override
    public void create() {
        try {
            checkFog();
        } catch (ReflectiveOperationException error) {
            throw new AssertionError("Shader chưa cung cấp chế độ sương xa cho lượt thế giới", error);
        }
        Gdx.app.exit();
    }

    private void checkFog() throws ReflectiveOperationException {
        ShaderProgram shader = new ShaderProgram();
        Mesh mesh = new Mesh(true, 3, 0,
                new VertexAttribute(Usage.Position, 3, "aPos"),
                new VertexAttribute(Usage.TextureCoordinates, 2, "aTexCoord"),
                new VertexAttribute(Usage.Generic, 1, "aShade"));
        try {
            Method enable = ShaderProgram.class.getMethod("enableDistanceFog", Vector3.class, float.class, float.class);
            Method disable = ShaderProgram.class.getMethod("disableDistanceFog");
            mesh.setVertices(new float[] {-1, -1, 0, 0, 0, -1, 3, -1, 0, 0, 0, -1, -1, 3, 0, 0, 0, -1});
            shader.bind();
            shader.setUniformMatrix4f("uProjection", new Matrix4());
            shader.setUniform1i("uUseTexture", 0);
            shader.setUniformVec4("uTintColor", 1f, 0f, 0f, 0.65f);
            shader.setUniformVec3("uWorldLight", 0.2f, 0.2f, 0.2f);
            shader.setUniformVec3("uSkyColor", 0f, 0f, 1f);
            shader.setUniformVec3("uHorizonColor", 1f, 0f, 0f);
            shader.setUniformVec3("uSunDirection", 1f, 0f, 0f);
            shader.setUniform1f("uHorizonGlow", 0f);
            enable.invoke(shader, new Vector3(), 10f, 30f);
            verify(readPixel(shader, mesh, 5f), 255, 0, 166, "khối gần tự phát sáng");
            verify(readPixel(shader, mesh, 20f), 128, 128, 166, "trộn RGB ở giữa khoảng sương");
            verify(readPixel(shader, mesh, 40f), 0, 255, 166, "sương xa khớp màu trời");
            shader.setUniform1i("uEnvironmentMode", 4);
            shader.setUniformVec4("uTintColor", 1f, 0f, 0f, 0.65f);
            if ((readPixel(shader, mesh, 40f) >>> 8 & 0xff) != 0) {
                throw new AssertionError("Lượt giáng thủy phải giữ màu riêng");
            }
            shader.setUniform1i("uEnvironmentMode", 0);
            disable.invoke(shader);
            verify(readPixel(shader, mesh, 40f), 255, 0, 166, "tắt sương trước overlay và HUD");
            if (Gdx.gl.glGetError() != GL20.GL_NO_ERROR) {
                throw new AssertionError("OpenGL báo lỗi khi vẽ sương");
            }
            System.out.println("FOG SMOKE PASSED on " + Gdx.gl.glGetString(GL20.GL_RENDERER));
        } finally {
            mesh.dispose();
            shader.dispose();
        }
    }

    private static int readPixel(ShaderProgram shader, Mesh mesh, float distance) {
        shader.setUniformMatrix4f("uModel", new Matrix4().setToTranslation(0f, 0f, -distance));
        shader.setUniformMatrix4f("uView", new Matrix4().setToTranslation(0f, 0f, distance));
        Gdx.gl.glClearColor(0f, 0f, 0f, 0f);
        Gdx.gl.glClear(GL20.GL_COLOR_BUFFER_BIT);
        mesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);
        Pixmap image = Pixmap.createFromFrameBuffer(32, 32, 1, 1);
        try {
            return image.getPixel(0, 0);
        } finally {
            image.dispose();
        }
    }

    private static void verify(int rgba, int red, int blue, int alpha, String label) {
        if (Math.abs((rgba >>> 24) - red) > 2 || Math.abs((rgba >>> 8 & 0xff) - blue) > 2
                || Math.abs((rgba & 0xff) - alpha) > 2) {
            throw new AssertionError(label + " nhận 0x" + Integer.toHexString(rgba));
        }
    }
}

