        cfg.setWindowedMode(1280, 720);
        cfg.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);
        cfg.setInitialVisible(false);
        cfg.setForegroundFPS(0);
        cfg.useVsync(true);
        new Lwjgl3Application(new WeatherSmoke(), cfg);
    }

    @Override
    public void create() {
        super.create();
        world = (World) field(VoxelGameApp.class, "world", this);
        clock = (WorldTime) field(VoxelGameApp.class, "worldTime", this);
        weather = (WeatherManager) field(VoxelGameApp.class, "weather", this);
        player = (Player) field(VoxelGameApp.class, "player", this);
        audio = (AudioManager) field(VoxelGameApp.class, "audioManager", this);
        rain = (Music) field(AudioManager.class, "rainAmbience", audio);
        camera = (Camera) field(VoxelGameApp.class, "camera", this);
        check(rain != null, "rain stream loaded");
        camera.rotate(90, 12);
        keyDown(Input.Keys.F7);
        started = System.nanoTime();
        System.out.println("GL: " + Gdx.gl.glGetString(GL20.GL_RENDERER));
    }

    @Override
    public void render() {
        super.render();
        long now = System.nanoTime();
        double elapsed = (now - started) / 1e9;
        double frameMillis = (now - previousFrame) / 1e6;
        previousFrame = now;
        if (elapsed >= 0.8 && elapsed < 2.0) clearFrames++;
        if (elapsed >= 5.5 && elapsed < 8.0) {
            rainFrames++;
            if (frameMillis >= 22) rainSlowFrames++;
        }
        if (elapsed >= 13.0 && elapsed < 16.0) {
            snowFrames++;
            if (frameMillis >= 22) snowSlowFrames++;
        }
        frames++;
        if (frames % 30 == 1) {
            check(Gdx.gl.glGetError() == GL20.GL_NO_ERROR, "OpenGL error at frame " + frames);
        }
        if (step == 0 && elapsed >= 2) {
            screenshot("dawn");
            keyDown(Input.Keys.F7);
            keyDown(Input.Keys.F6);
            step++;
        } else if (step == 1 && elapsed >= 8) {
            check(weather.label().equals("RAIN") && weather.strength() > 0.99f, "rain reached full strength");
            check(rain.isPlaying() && rain.getVolume() > 0.68f, "OpenAL rain gain outdoors");
            screenshot("rain");
            world.setBlock(1500, 20, 896, Block.STONE.getId());
            step++;
        } else if (step == 2 && elapsed >= 9) {
            check(Math.abs(rain.getVolume() - 0.28f) < 0.025f, "roof dampens rain");
            keyDown(Input.Keys.ESCAPE);
            frozen = weather.animationSeconds();
            check(!rain.isPlaying(), "ESC pauses rain");
            audio.setVolume(0.5f);
            check(Math.abs(rain.getVolume() - 0.2f) < 0.025f, "rain volume changed while paused");
            step++;
        } else if (step == 3 && elapsed >= 10) {
            check(frozen == weather.animationSeconds(), "weather animation frozen");
            touchDown(640, 309, 0, Input.Buttons.LEFT);
            touchUp(640, 309, 0, Input.Buttons.LEFT);
            check(rain.isPlaying(), "Resume button restarts rain");
            keyDown(Input.Keys.F7);
            keyDown(Input.Keys.F7);
            keyDown(Input.Keys.F8);
            int minute = clock.minuteOfDay();
            check(minute < 2, "F7 reaches midnight");
            move(500f);
            step++;
        } else if (step == 4 && elapsed >= 16) {
            check(weather.label().equals("SNOW") && !rain.isPlaying(), "snow has no rain sound");
            check(clock.minuteOfDay() > 80, "F8 advances time");
            screenshot("snow-night");
            move(2500f);
            step++;
        } else if (step == 5 && elapsed >= 19) {
            check(weather.label().equals("CLEAR") && weather.skyStrength() == 0f, "desert dry");
            check(!rain.isPlaying() && rain.getVolume() == 0f, "desert silent");
            check(Gdx.gl.glGetError() == GL20.GL_NO_ERROR, "OpenGL end");
            System.out.printf("SMOKE PASSED, frames=%d, clear %.1f fps, rain %.1f fps (%d slow), snow %.1f fps (%d slow)%n",
                    frames, clearFrames / 1.2, rainFrames / 2.5, rainSlowFrames, snowFrames / 3.0, snowSlowFrames);
            Gdx.app.exit();
            step++;
        }
    }

    private void move(float x) {
        ((Vector3) field(Entity.class, "position", player)).set(x, 35f, 896f);
        try {
            Field flying = Player.class.getDeclaredField("isFlying");
            flying.setAccessible(true);
            flying.setBoolean(player, true);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }

    private static Object field(Class<?> type, String name, Object instance) {
        try {
            Field f = type.getDeclaredField(name);
            f.setAccessible(true);
            return f.get(instance);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }

    private static void check(boolean result, String name) {
        if (!result) throw new AssertionError(name);
    }

    private static void screenshot(String label) {
        Pixmap image = Pixmap.createFromFrameBuffer(0, 0, 1280, 720);
        try {
            PixmapIO.writePNG(Gdx.files.local("build/" + label + ".png"), image, -1, true);
        } finally {
            image.dispose();
        }
    }
}

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.Input;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3Application;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3ApplicationConfiguration;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.PixmapIO;
import com.badlogic.gdx.math.Vector3;
import com.badlogic.gdx.utils.IntArray;
import com.voxelgame.VoxelGameApp;
import com.voxelgame.engine.*;
import com.voxelgame.entity.*;
import com.voxelgame.entity.mob.*;
import org.lwjgl.openal.AL10;

import java.lang.reflect.Field;
import java.util.Arrays;

/** Kiểm tra đầu vào Ctrl+C, cảnh thật, hiệu ứng âm thanh và sinh thú qua ba biome. */
public final class WildlifeDesktopSmoke extends VoxelGameApp {
    private static final BiomeType[] BIOMES = {BiomeType.SNOWY_PLAINS, BiomeType.PLAINS, BiomeType.DESERT};
    private static final MobType[][] SPECIES = {
            {MobType.SNOW_RABBIT, MobType.WOLF, MobType.SNOW_FOX, MobType.POLAR_BEAR, MobType.GOAT},
            {MobType.COW, MobType.SHEEP, MobType.PIG, MobType.CHICKEN}, {MobType.RABBIT}};
    private static final MobAppearance[][] APPEARANCES = {
            {MobAppearance.RABBIT_WHITE, MobAppearance.WOLF_SNOWY, MobAppearance.SNOW_FOX_SLEEP,
                    MobAppearance.POLAR_BEAR, MobAppearance.GOAT},
            {MobAppearance.COW, MobAppearance.SHEEP, MobAppearance.PIG, MobAppearance.CHICKEN},
            {MobAppearance.RABBIT_GOLD}};
    private final long[] frames = new long[4096];
    private final boolean[] seen = new boolean[MobType.values().length];
    private final Vector3 anchor = new Vector3();
    private final Vector3 ground = new Vector3();
    private final Vector3 zero = new Vector3();
    private final MobEntity[] showcase = new MobEntity[6];
    private World world;
    private WorldTime clock;
    private Camera camera;
    private Field skipMouse;
    private Vector3 playerPosition;
    private Vector3 playerVelocity;
    private IntArray sources;
    private int stage;
    private int samples;
    private long start;
    private long previous;
    private int wildlife;
    private int monsters;
    private boolean showing;
    private boolean vitalsChanged;
    private final boolean control = Boolean.getBoolean("wildlife.control");
    private final boolean diagnose = Boolean.getBoolean("wildlife.diagnose");
    private final int single = Integer.getInteger("wildlife.single", -1);
    private int diagnosePass;
    private Object renderer;
    private long cpuStart;
    private long bytesStart;
    private long cpuTotal;
    private long bytesTotal;
    private final com.sun.management.ThreadMXBean bean =
            (com.sun.management.ThreadMXBean) java.lang.management.ManagementFactory.getThreadMXBean();

    public static void main(String[] args) {
        Lwjgl3ApplicationConfiguration config = new Lwjgl3ApplicationConfiguration();
        config.setTitle("Ourcraft");
        config.setOpenGLEmulation(Lwjgl3ApplicationConfiguration.GLEmulation.GL30, 3, 3);
        config.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);
        config.setWindowedMode(Integer.getInteger("wildlife.width", 1280), Integer.getInteger("wildlife.height", 720));
        config.useVsync(true);
        new Lwjgl3Application(new WildlifeDesktopSmoke(), config);
    }

    @Override
    public void create() {
        super.create();
        world = (World) read(this, VoxelGameApp.class, "world");
        clock = (WorldTime) read(this, VoxelGameApp.class, "worldTime");
        camera = (Camera) read(this, VoxelGameApp.class, "camera");
        skipMouse = field(VoxelGameApp.class, "skipNextMouseDelta");
        playerPosition = (Vector3) read(world.getPlayer(), Entity.class, "position");
        playerVelocity = (Vector3) read(world.getPlayer(), Entity.class, "velocity");
        sources = (IntArray) read(Gdx.audio, Gdx.audio.getClass(), "allSources");
        Gdx.input.setCursorCatched(false);
        if (control) {
            for (MobType[] group : SPECIES) {
                for (MobType type : group) {
                    type.registerFactory(null);
                }
            }
        }
        System.out.println("GL " + Gdx.gl.glGetString(GL20.GL_RENDERER));
        if (single >= 0) {
            for (; stage < single; stage++) {
                keyDown(Input.Keys.CONTROL_LEFT);
                keyDown(Input.Keys.C);
                keyUp(Input.Keys.CONTROL_LEFT);
            }
        }
        renderer = read(world, World.class, "mobRenderer");
        enterBiome();
    }

    private void enterBiome() {
        keyDown(Input.Keys.CONTROL_LEFT);
        keyDown(Input.Keys.C);
        keyUp(Input.Keys.CONTROL_LEFT);
        world.getPlayer().copyPosition(anchor);
        if (world.getBiome((int) anchor.x, (int) anchor.z) != BIOMES[stage]) {
            throw new AssertionError("Ctrl+C did not reach " + BIOMES[stage]);
        }
        clock.update(((6000 - clock.tickOfDay()) + 24000) % 24000 / 20d);
        camera.rotate(0, -2f - camera.getPitch());
        samples = 0;
        wildlife = 0;
        monsters = 0;
        previous = 0;
        showing = false;
        vitalsChanged = false;
        Arrays.fill(seen, false);
        start = System.nanoTime();
    }

    @Override
    public void render() {
        try {
            skipMouse.setBoolean(this, true);
        } catch (IllegalAccessException ex) {
            throw new AssertionError(ex);
        }
        playerPosition.set(anchor);
        playerVelocity.setZero();
        if (showing) {
            resetShowcase();
        }
        if (diagnose) {
            cpuStart = bean.getCurrentThreadCpuTime();
            bytesStart = bean.getCurrentThreadAllocatedBytes();
        }
        super.render();
        long now = System.nanoTime();
        double elapsed = (now - start) / 1e9;
        if (Gdx.gl.glGetError() != GL20.GL_NO_ERROR || AL10.alGetError() != AL10.AL_NO_ERROR) {
            throw new AssertionError("OpenGL or OpenAL reported an error");
        }
        if (showing) {
            if (stage == 1 && elapsed >= 0.7 && !vitalsChanged) {
                Player player = world.getPlayer();
                Object ui = read(this, VoxelGameApp.class, "uiRenderer");
                if ((int) read(ui, ui.getClass(), "vitalHealth") != (int) Math.ceil(player.getHealth())) {
                    throw new AssertionError("Incorrect HUD HP cache before change");
                }
                player.damage(world, 3f, DamageSource.POTION_MAGIC, null, 0f, 0f);
                write(player, Player.class, "hunger", 17f);
                vitalsChanged = true;
            }
            if (elapsed >= 1.4) {
                if (vitalsChanged) {
                    Object ui = read(this, VoxelGameApp.class, "uiRenderer");
                    if ((int) read(ui, ui.getClass(), "vitalHealth") != (int) Math.ceil(world.getPlayer().getHealth())
                            || (int) read(ui, ui.getClass(), "vitalFood") != 17) {
                        throw new AssertionError("Incorrect HUD HP or hunger cache after change");
                    }
                    System.out.println("HUD vitals cache updated after damage and hunger");
                }
                capture();
                advance();
            }
            return;
        }
        int currentWildlife = 0;
        int currentMonsters = 0;
        for (int i = 0; i < world.entityCount(); i++) {
            if (world.entityAt(i) instanceof MobEntity mob && mob.isAlive()) {
                mob.copyPosition(ground);
                if (ground.dst2(anchor) <= 128 * 128) {
                    if (mob.type().category() == MobCategory.CREATURE) {
                        currentWildlife++;
                        seen[mob.type().ordinal()] = true;
                    } else {
                        currentMonsters++;
                    }
                }
            }
        }
        wildlife = Math.max(wildlife, currentWildlife);
        monsters = Math.max(monsters, currentMonsters);
        if (elapsed >= (diagnose ? 2 : 7) && previous != 0 && samples < frames.length) {
            frames[samples++] = now - previous;
            if (diagnose) {
                cpuTotal += bean.getCurrentThreadCpuTime() - cpuStart;
                bytesTotal += bean.getCurrentThreadAllocatedBytes() - bytesStart;
            }
        }
        previous = now;
        if (elapsed >= (diagnose ? 8 : 15)) {
            finishMeasurement();
            if (diagnose) {
                System.out.printf("DIAGNOSTIC pass %d: %.3f ms CPU/frame; %.1f bytes/frame%n", diagnosePass,
                        cpuTotal / 1e6 / samples, bytesTotal / (double) samples);
                diagnosePass++;
                if (diagnosePass == 4) {
                    write(world, World.class, "mobRenderer", renderer);
                    Gdx.app.exit();
                } else {
                    write(world, World.class, "mobRenderer", diagnosePass % 2 == 0 ? renderer : null);
                    samples = 0;
                    previous = 0;
                    cpuTotal = 0;
                    bytesTotal = 0;
                    start = System.nanoTime();
                }
            } else if (control) {
                advance();
            } else {
                setupShowcase();
            }
        }
    }

    private void finishMeasurement() {
        StringBuilder species = new StringBuilder();
        for (MobType type : SPECIES[stage]) {
            if (seen[type.ordinal()]) {
                species.append(type).append(' ');
            }
        }
        if (!control && species.length() == 0) {
            throw new AssertionError("No natural wildlife in " + BIOMES[stage]);
        }
        long total = 0;
        for (int i = 0; i < samples; i++) {
            total += frames[i];
        }
        Arrays.sort(frames, 0, samples);
        System.out.printf("%s %s tick=%d, wildlife=%d hostile=%d, %.2f FPS p95 %.2f ms (%d samples), %s%n",
                BIOMES[stage], control ? "control" : "wildlife", clock.tickOfDay(), wildlife, monsters,
                samples * 1e9 / total, frames[(int) Math.ceil(samples * .95) - 1] / 1e6, samples, species);
    }

    private void setupShowcase() {
        for (MobType type : SPECIES[stage]) {
            checkAudio(type.id(), MobSoundEvent.AMBIENT);
        }
        if (stage == 0) {
            checkAudio("goat", MobSoundEvent.GOAT_SCREAM);
            checkAudio("wolf", MobSoundEvent.WOLF_GROWL);
        }
        anchor.y = (int) anchor.y + 18;
        Block floor = stage == 0 ? Block.SNOW_BLOCK : stage == 1 ? Block.GRASS : Block.SANDSTONE;
        for (int x = (int) anchor.x - 9; x <= (int) anchor.x + 9; x++) {
            for (int z = (int) anchor.z - 13; z <= (int) anchor.z + 3; z++) {
                world.setBlock(x, (int) anchor.y - 1, z, floor.getId());
            }
        }
        camera.rotate(0, -12f - camera.getPitch());
        int count = stage == 2 ? 3 : 6;
        for (int i = 0; i < count; i++) {
            int model = Math.min(i, SPECIES[stage].length - 1);
            float x = anchor.x + (i % 3 - 1) * 2.0f;
            float z = anchor.z - 4.2f - (i / 3) * 3.3f;
            MobEntity mob = SPECIES[stage][model].create(x, anchor.y, z);
            showcase[i] = mob;
            mob.setPersistent(true);
            // Tắt các hành vi dịch chuyển để kiểm tra từng model ở khung hình cố định.
            mob.goals().stopAll(world, mob);
            if (mob instanceof Wolf) {
                write(mob, Wolf.class, "huntDelay", 60f);
            }
            world.addEntity(mob);
        }
        showing = true;
        start = System.nanoTime();
    }

    private void resetShowcase() {
        for (int i = 0; i < showcase.length && showcase[i] != null; i++) {
            MobEntity mob = showcase[i];
            int index = Math.min(i, APPEARANCES[stage].length - 1);
            float x = anchor.x + (i % 3 - 1) * 2f;
            float z = anchor.z - 4.2f - (i / 3) * 3.3f;
            mob.setPosition(x, anchor.y, z);
            MobVisualState visual = mob.mobVisualState();
            visual.setAppearance(stage == 0 && i == 5 ? MobAppearance.RABBIT_WHITE_SPLOTCHED
                    : APPEARANCES[stage][index]);
            if (stage == 1 && i == 1) {
                visual.setSheepWoolColor(0xe78ab2);
            }
            if (stage == 0 && mob.type() == MobType.SNOW_FOX) {
                visual.setHeldBlock(Block.POPPY);
            }
            mob.lookAt(anchor.x, anchor.y + 0.9f, anchor.z);
            mob.faceBody(anchor.x, anchor.z);
        }
    }

    private void checkAudio(String id, MobSoundEvent event) {
        AudioManager audio = world.getAudio();
        Object bank = read(audio, AudioManager.class, "mobSounds");
        java.util.Map<?, ?> banks = (java.util.Map<?, ?>) read(bank, bank.getClass(), "samplesByMob");
        Object[] clips = ((Object[][]) banks.get(id))[event.ordinal()];
        audio.playMobSound(id, event, anchor.x, anchor.y, anchor.z - 2, 0, 1f);
        for (int i = 0; i < sources.size; i++) {
            int source = sources.get(i);
            if (AL10.alGetSourcei(source, AL10.AL_SOURCE_STATE) != AL10.AL_PLAYING) {
                continue;
            }
            int buffer = AL10.alGetSourcei(source, AL10.AL_BUFFER);
            for (Object clip : clips) {
                if (buffer == (int) read(clip, clip.getClass().getSuperclass(), "bufferID")) {
                    System.out.println("Audio " + id + " " + event + " OK");
                    return;
                }
            }
        }
        throw new AssertionError("No active OpenAL source for " + id + " " + event);
    }

    private void capture() {
        Pixmap screenshot = Pixmap.createFromFrameBuffer(0, 0, 1280, 720);
        try {
            PixmapIO.writePNG(Gdx.files.local("build/wildlife-" + BIOMES[stage] + ".png"), screenshot, -1, true);
        } finally {
            screenshot.dispose();
        }
    }

    private void advance() {
        for (MobEntity mob : showcase) {
            if (mob != null) {
                mob.discard();
            }
        }
        Arrays.fill(showcase, null);
        stage++;
        if (stage == BIOMES.length || single >= 0) {
            Gdx.app.exit();
        } else {
            enterBiome();
        }
    }

    private static Field field(Class<?> type, String name) {
        try {
            Field field = type.getDeclaredField(name);
            field.setAccessible(true);
            return field;
        } catch (ReflectiveOperationException ex) {
            throw new AssertionError(ex);
        }
    }

    private static Object read(Object target, Class<?> type, String name) {
        try {
            return field(type, name).get(target);
        } catch (IllegalAccessException ex) {
            throw new AssertionError(ex);
        }
    }

    private static void write(Object target, Class<?> type, String name, Object value) {
        try {
            field(type, name).set(target, value);
        } catch (IllegalAccessException ex) {
            throw new AssertionError(ex);
        }
    }
}

