import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.SplittableRandom;

class GenerateMobAudio {
    static final int RATE = 22050;
    static final double TAU = 2 * Math.PI;

    // Frequency, call length, breathiness, shimmer, pulse rate, contour, foot mass.
    record Voice(String id, double f, double length, double breath, double color,
                 double pulses, double sweep, double foot) {}

    static final Voice[] VOICES = {
        new Voice("zombie",          91,  .66, .48, .21,  8, -.35, .68),
        new Voice("zombie_villager",146,  .46, .22, .52, 11, -.29, .62),
        new Voice("skeleton",       450, .34, .82, .79, 19,  .12, .49),
        new Voice("creeper",        260, .37, .90, .64,  7, -.12, .52),
        new Voice("spider",         520, .29, .76, .85, 25,  .28, .26),
        new Voice("enderman",       215, .64, .31, .65, 13,  .55, .31),
        new Voice("witch",          280, .53, .26, .68, 10,  .14, .38),
        new Voice("cow",            113, .81, .18, .25,  4, -.32, .82),
        new Voice("sheep",          240, .59, .27, .65,  9, -.16, .57),
        new Voice("pig",            180, .35, .53, .43, 18,  .29, .51),
        new Voice("chicken",        530, .24, .23, .57, 14, -.26, .20),
        new Voice("horse",          330, .72, .27, .47, 12, -.48, .98),
        new Voice("donkey",         297, .80, .24, .60,  6,  .26, .89),
        new Voice("rabbit",         690, .17, .34, .37,  7,  .37, .15),
        new Voice("camel",           77, .69, .52, .34, 12, -.36,1.10),
        new Voice("camel_husk",      63, .55, .67, .69, 17, -.13,1.13),
        new Voice("husk",            82, .44, .70, .27, 15, -.33, .65),
        new Voice("parched",        343, .38, .84, .56, 22, -.21, .45),
        new Voice("goat",           312, .48, .22, .70, 13,  .23, .60),
        new Voice("polar_bear",      71, .75, .59, .24, 10, -.30,1.22),
        new Voice("wolf",           157, .37, .51, .45, 17, -.21, .57),
        new Voice("fox",            398, .47, .43, .62,  8,  .35, .33),
        new Voice("stray",          370, .47, .76, .61, 14, -.19, .45)
    };

    // Folder, event and two related but distinct variants for each interaction.
    record Special(String folder, String event, double length) {}
    static final Special[] SPECIALS = {
        new Special("creeper", "creeper_primed", .86),
        new Special("shared", "explode", 1.06),
        new Special("shared", "bow_shoot", .24),
        new Special("enderman", "enderman_stare", .82),
        new Special("enderman", "enderman_teleport", .39),
        new Special("enderman", "enderman_scream", .94),
        new Special("witch", "witch_throw", .33),
        new Special("witch", "witch_drink", .65),
        new Special("goat", "goat_ram", .29),
        new Special("goat", "goat_scream", .83),
        new Special("wolf", "wolf_growl", .77),
        new Special("camel", "camel_dash", .42),
        new Special("husk", "husk_convert", .86),
        new Special("shared", "spear_charge", .64)
    };

    public static void main(String[] args) throws Exception {
        Path root = Path.of(args[0]);
        for (Voice voice : VOICES) {
            for (int variant = 1; variant <= 2; variant++) {
                write(root, voice.id(), "ambient", variant, voice(voice, 0, variant));
                write(root, voice.id(), "hurt", variant, voice(voice, 1, variant));
                write(root, voice.id(), "death", variant, voice(voice, 2, variant));
                write(root, voice.id(), "step", variant, step(voice, variant));
            }
        }
        for (Special special : SPECIALS) {
            for (int variant = 1; variant <= 2; variant++) {
                write(root, special.folder(), special.event(), variant, special(special, variant));
            }
        }
    }

    static double[] voice(Voice voice, int event, int variant) {
        var random = new SplittableRandom(voice.id().hashCode() * 173L + event * 23L + variant * 101L);
        double eventLength = event == 0 ? 1 : event == 1 ? .69 : 1.19;
        double length = voice.length() * eventLength * (.90 + .18 * random.nextDouble());
        double[] samples = new double[(int) (RATE * length)];
        double initialFrequency = voice.f() * (.90 + .19 * random.nextDouble());
        double voiceBrightness = voice.color();
        double noiseMix = voice.breath() * (event == 1 ? 1.08 : 1);
        double noise = 0;
        double phase = 0;
        double wobble = .7 + random.nextDouble();
        for (int i = 0; i < samples.length; i++) {
            double t = i / (double) RATE;
            double u = t / length;
            double intonation = 1 + voice.sweep() * u + .08 * Math.sin(TAU * (u * wobble + .24));
            if (event == 1) intonation += .32 * Math.exp(-6 * u);
            if (event == 2) intonation = intonation * (.95 - .43 * u);
            double pulses = Math.sin(TAU * t * voice.pulses());
            double frequency = initialFrequency * intonation * (1 + .019 * pulses);
            phase += TAU * frequency / RATE;

            double vibration = Math.sin(phase) + .43 * voiceBrightness * Math.sin(2 * phase + .22)
                    + .32 * voiceBrightness * Math.sin(3 * phase)
                    + .12 * Math.sin(4 * phase + .6 * Math.sin(phase * .27));
            double grain = random.nextDouble(-1, 1);
            noise += (.082 + .40 * voiceBrightness) * (grain - noise);
            double texture = .62 * noise + .22 * grain;
            double oscillator = (1 - noiseMix) * vibration + noiseMix * 1.15 * texture;
            double call = .53 + .47 * Math.pow(.5 + .5 * pulses, voice.pulses() > 13 ? 3 : 1.4);
            double shape = envelope(u, event == 1 ? .045 : .12, event == 2 ? 1.75 : 1.11);
            if (event == 2) call *= .77 + .23 * Math.cos(TAU * 2.15 * u);
            if (event == 0 && voice.id().equals("donkey")) {
                call *= .27 + .73 * Math.pow(Math.abs(Math.sin(TAU * 1.3 * u)), .55);
            }
            if (event == 0 && voice.id().equals("horse")) {
                call *= .21 + .79 * Math.pow(.5 + .5 * Math.cos(TAU * 5.1 * u), 2);
            }
            samples[i] = Math.tanh(oscillator * 1.3) * shape * call;
        }
        return samples;
    }

    static double[] step(Voice voice, int variant) {
        var random = new SplittableRandom(voice.id().hashCode() * 157L + 81L * variant);
        double foot = voice.foot();
        double length = .075 + .115 * foot + .012 * random.nextDouble();
        double[] samples = new double[(int) (RATE * length)];
        double tuned = 88 + 147 * (1.26 - foot) + random.nextDouble(45);
        double noise = 0;
        for (int i = 0; i < samples.length; i++) {
            double t = i / (double) RATE;
            double u = t / length;
            double grain = random.nextDouble(-1, 1);
            noise += (.16 + .27 * (1.26 - foot)) * (grain - noise);
            double knock = Math.sin(TAU * tuned * t) * Math.exp(-9 * u);
            double strike = (.71 * noise + .13 * grain) * Math.exp(-7 * u);
            double after = (noise + .25 * Math.sin(TAU * .66 * tuned * t)) * bump(u, .30, .09);
            if (foot > .85) after += .59 * grain * bump(u, .49, .046);
            samples[i] = envelope(u, .028, .7) * (.40 * foot * knock + strike + .35 * after);
        }
        return samples;
    }

    static double[] special(Special s, int variant) {
        var random = new SplittableRandom(s.event().hashCode() * 47L + variant * 113L);
        double length = s.length() * (.91 + .17 * random.nextDouble());
        double[] samples = new double[(int) (RATE * length)];
        double tone = .90 + .20 * random.nextDouble();
        double low = 0;
        double mid = 0;
        for (int i = 0; i < samples.length; i++) {
            double t = i / (double) RATE;
            double u = t / length;
            double noise = random.nextDouble(-1, 1);
            low += .026 * (noise - low);
            mid += .24 * (noise - mid);
            double high = noise - mid;
            double p120 = TAU * tone * 120 * t;
            double sample = switch (s.event()) {
                case "creeper_primed" -> (.47 * noise + .45 * mid) * (.55 + .45 * u)
                        * (.75 + .25 * Math.sin(TAU * (8 + 13 * u) * t))
                        + .38 * high * bump(u, .025, .02);
                case "explode" -> 1.21 * Math.sin(p120 * (.87 - .29 * u)) * Math.exp(-6.0 * u)
                        + 3.10 * low * Math.exp(-2.7 * u) + 1.95 * mid * Math.exp(-7 * u)
                        + .47 * noise * bump(u, .017, .016)
                        + .22 * mid * Math.pow(.5 + .5 * Math.sin(TAU * t * 21), 3);
                case "bow_shoot" -> (.52 * Math.sin(p120 * (3.5 - 1.12 * u))
                        + .23 * Math.sin(p120 * (6.75 - 2.2 * u))) * Math.exp(-10 * u)
                        + .48 * high * bump(u, .21, .14);
                case "enderman_stare" -> (.37 * Math.sin(p120 * (1.83 + .66 * u))
                        + .33 * Math.sin(p120 * (1.89 + .62 * u)))
                        * (.7 + .30 * Math.cos(TAU * 9 * t)) + .18 * mid;
                case "enderman_teleport" -> .53 * Math.sin(p120 * (8.4 - 5.05 * u)
                        + 1.6 * Math.sin(p120 * (2.4 + u))) * Math.exp(-2 * u)
                        + .45 * high * bump(u, .15, .11) + .39 * low;
                case "enderman_scream" -> .50 * Math.sin(p120 * (3.1 + .25 * u)
                        + 2.2 * Math.sin(p120 * (.53 + .10 * u)))
                        + .26 * Math.sin(p120 * (5.3 - .18 * u)) + .64 * mid;
                case "witch_throw" -> (.70 * mid + .44 * high) * bump(u, .33, .18)
                        + .28 * Math.sin(p120 * (5.7 - 2.2 * u)) * bump(u, .56, .17);
                case "witch_drink" -> (.61 * Math.sin(p120 * (1.56 - .48 * u)
                        + 1.9 * Math.sin(TAU * (8 + 3 * u) * t)) + .79 * low)
                        * Math.pow(.5 + .5 * Math.sin(TAU * (4.35 + u) * t), 3)
                        + .18 * high * bump(u, .86, .055);
                case "goat_ram" -> (.71 * Math.sin(p120 * (.95 - .32 * u)) + .95 * mid)
                        * Math.exp(-7 * u) + .37 * high * bump(u, .11, .07);
                case "goat_scream" -> (.55 * Math.sin(p120 * (4.0 + .41 * u))
                        + .38 * Math.sin(p120 * (8.0 + .82 * u)) + .22 * mid)
                        * (.56 + .44 * Math.pow(.5 + .5 * Math.sin(TAU * t * 14), 1.6));
                case "wolf_growl" -> (.44 * Math.sin(p120 * (.83 - .13 * u))
                        + .31 * Math.sin(p120 * (1.66 - .26 * u)) + .70 * low + .30 * mid)
                        * (.63 + .37 * Math.sin(TAU * 23 * t));
                case "camel_dash" -> (.57 * low + .77 * mid + .51 * Math.sin(p120 * .63))
                        * (bump(u, .14, .05) + bump(u, .34, .068) + .57 * bump(u, .67, .17));
                case "husk_convert" -> .64 * Math.sin(p120 * (1.41 - .32 * u)
                        + 1.41 * Math.sin(p120 * (.53 + .13 * u))) * (.56 + .44 * Math.cos(TAU * 8 * t))
                        + .35 * mid + .45 * low * bump(u, .79, .14);
                case "spear_charge" -> .44 * Math.sin(p120 * (2.29 + 1.93 * u))
                        + .21 * Math.sin(p120 * (5.57 + 1.29 * u)) + (.10 + .49 * u) * high;
                default -> throw new IllegalStateException(s.event());
            };
            double attack = switch (s.event()) {
                case "explode", "goat_ram", "bow_shoot" -> .012;
                case "spear_charge" -> .48;
                default -> .093;
            };
            samples[i] = Math.tanh(sample) * envelope(u, attack, 1);
        }
        return samples;
    }

    static double envelope(double u, double attack, double release) {
        return Math.min(1, u / attack) * Math.pow(1 - u, release)
                * Math.min(1, (1 - u) / .018);
    }

    static double bump(double u, double center, double width) {
        double x = (u - center) / width;
        return Math.exp(-x * x);
    }

    static void write(Path root, String folder, String event, int variant, double[] samples) throws Exception {
        Path path = root.resolve(folder).resolve(event + variant + ".wav");
        Files.createDirectories(path.getParent());
        double peak = 0;
        for (double sample : samples) peak = Math.max(peak, Math.abs(sample));
        double level = switch (event) {
            case "step" -> .35;
            case "explode", "enderman_scream", "goat_scream" -> .84;
            case "ambient" -> .55;
            default -> .67;
        };
        ByteBuffer file = ByteBuffer.allocate(44 + samples.length * 2).order(ByteOrder.LITTLE_ENDIAN);
        file.putInt(0x46464952).putInt(36 + samples.length * 2).putInt(0x45564157);
        file.putInt(0x20746D66).putInt(16).putShort((short) 1).putShort((short) 1);
        file.putInt(RATE).putInt(RATE * 2).putShort((short) 2).putShort((short) 16);
        file.putInt(0x61746164).putInt(samples.length * 2);
        for (double sample : samples) file.putShort((short) Math.round(32767 * sample * level / peak));
        Files.write(path, file.array());
    }
}

package com.voxelgame.engine;

import java.nio.file.Files;
import java.nio.file.Path;
import javax.sound.sampled.AudioSystem;

class MobAudioCheck {
    public static void main(String[] args) throws Exception {
        var audio = Class.forName("com.voxelgame.engine.AudioManager");
        var gain = audio.getDeclaredMethod("mobGain", float.class, float.class);
        var pitch = audio.getDeclaredMethod("mobPitch", float.class, float.class);
        approx((float) gain.invoke(null, 0f, 16f), 1f);
        approx((float) gain.invoke(null, 64f, 16f), 0.5f);
        approx((float) gain.invoke(null, 256f, 16f), 0f);
        approx((float) gain.invoke(null, 257f, 16f), 0f);
        approx((float) gain.invoke(null, Float.NaN, 16f), 0f);
        approx((float) pitch.invoke(null, 1.5f, 0.5f), 1.5f);

        var event = Class.forName("com.voxelgame.engine.MobSoundEvent");
        var defaultRange = event.getDeclaredMethod("defaultRange");
        approx((float) defaultRange.invoke(event.getField("AMBIENT").get(null)), 16f);
        approx((float) defaultRange.invoke(event.getField("EXPLODE").get(null)), 32f);
        approx((float) defaultRange.invoke(event.getField("ENDERMAN_SCREAM").get(null)), 32f);
        approx((float) defaultRange.invoke(event.getField("GOAT_SCREAM").get(null)), 28f);

        Path root = Path.of("src/main/resources/audio/sfx/mob");
        try (var entries = Files.walk(root)) {
            var paths = entries.filter(path -> path.toString().endsWith(".wav")).toList();
            if (paths.size() != 212) throw new AssertionError("Expected 212 PCM WAVs, got " + paths.size());
            for (var path : paths) {
                try (var stream = AudioSystem.getAudioInputStream(path.toFile())) {
                    var format = stream.getFormat();
                    if (format.getChannels() != 1 || format.getSampleSizeInBits() != 16
                            || format.getSampleRate() != 22050f || stream.getFrameLength() < 1000) {
                        throw new AssertionError(path + " has unexpected audio " + format);
                    }
                }
            }
        }
        System.out.println("Mob audio CPU checks passed (ranges, gain, pitch and 212 PCM WAV files)");
    }

    private static void approx(float actual, float expected) {
        if (Math.abs(actual - expected) > 0.00001f) {
            throw new AssertionError("Expected " + expected + " but got " + actual);
        }
    }
}

package com.voxelgame.engine;

import com.badlogic.gdx.Audio;
import com.badlogic.gdx.Files;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.audio.Music;
import com.badlogic.gdx.audio.Sound;
import com.badlogic.gdx.files.FileHandle;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;
import java.util.LinkedHashMap;
import java.util.Map;

class MobAudioLifecycleCheck {
    static final String ROOT = "audio/sfx/mob/";
    static final String FAILED = "cow/ambient1.wav";
    static final String MISSING = "wolf/ambient2.wav";

    record MockSound(String path, int[] playback, int[] disposed, float[] lastGain) {}

    public static void main(String[] args) {
        Map<String, MockSound> samples = new LinkedHashMap<>();
        int[] attempts = {0};
        Gdx.files = proxy(Files.class, (object, method, params) -> {
            String path = (String) params[0];
            if (!method.getName().equals("classpath")) throw new AssertionError(method);
            return new FileHandle("src/main/resources/" + path) {
                @Override public boolean exists() {
                    return !path.equals(ROOT + MISSING) && super.exists();
                }
            };
        });
        Gdx.audio = proxy(Audio.class, (object, method, params) -> {
            if (method.getName().equals("newMusic")) return proxy(Music.class, (p, m, a) -> null);
            if (!method.getName().equals("newSound")) throw new AssertionError(method);
            String rawPath = ((FileHandle) params[0]).path();
            int mobRoot = rawPath.indexOf(ROOT);
            if (mobRoot < 0) return proxy(Sound.class, (p, m, a) -> null);
            String path = rawPath.substring(mobRoot + ROOT.length());
            attempts[0]++;
            if (path.equals(FAILED)) throw new IllegalArgumentException("Expected corrupt test variant");
            MockSound sound = new MockSound(path, new int[1], new int[1], new float[1]);
            if (samples.put(path, sound) != null) throw new AssertionError("Duplicate preload " + path);
            return proxy(Sound.class, (p, m, a) -> {
                if (m.getName().equals("play")) {
                    sound.playback()[0]++;
                    sound.lastGain()[0] = (float) a[0];
                    if ((float) a[1] < 1.41f || (float) a[1] > 1.59f) throw new AssertionError("Baby pitch outside jitter");
                    return 1L;
                }
                if (m.getName().equals("dispose")) {
                    if (sound.disposed()[0]++ != 0) throw new AssertionError("Double dispose " + path);
                    return null;
                }
                throw new AssertionError(m);
            });
        });

        AudioManager manager = new AudioManager();
        check(attempts[0] == 211, "Missing resource skipped, corrupt resource attempted once");
        check(samples.size() == 210, "All present decodable resources preloaded once");
        check(samples.keySet().iterator().next().equals("zombie/ambient1.wav"), "Deterministic initial sample");
        manager.playMobSound("cow", MobSoundEvent.AMBIENT, 0, 0, 0, 0, 1.5f);
        check(samples.get("cow/ambient2.wav").playback()[0] == 0, "No listener");
        manager.setMobListener(10, 20, 30);
        manager.playMobSound("cow", MobSoundEvent.AMBIENT, 10, 28, 30, 0, 1.5f);
        check(samples.get("cow/ambient2.wav").playback()[0] == 1, "Corrupt variant skipped");
        check(samples.get("cow/ambient2.wav").lastGain()[0] == 0.5f, "Default range includes vertical distance");
        manager.playMobSound("cow", MobSoundEvent.AMBIENT, 10, 36, 30, 0, 1.5f);
        check(samples.get("cow/ambient2.wav").playback()[0] == 1, "At range is silent");
        manager.playMobSound("wolf", MobSoundEvent.AMBIENT, 10, 20, 30, 0, 1.5f);
        check(samples.get("wolf/ambient1.wav").playback()[0] == 1, "Missing variant skipped");
        manager.playMobSound("creeper", MobSoundEvent.EXPLODE, 10, 36, 30, 0, 1.5f);
        MockSound one = samples.get("shared/explode1.wav");
        MockSound two = samples.get("shared/explode2.wav");
        check(one.playback()[0] + two.playback()[0] == 1 && one.lastGain()[0] + two.lastGain()[0] == 0.5f,
                "Shared effect uses the extended range");
        manager.dispose();
        manager.dispose();
        for (MockSound sound : samples.values()) {
            check(sound.disposed()[0] == 1, "Disposed one time " + sound.path());
        }
        manager.playMobSound("cow", MobSoundEvent.AMBIENT, 10, 28, 30, 0, 1.5f);
        check(samples.get("cow/ambient2.wav").playback()[0] == 1, "No playback after disposal");
        System.out.println("Mob audio lifecycle checks passed (deterministic loading, missing and corrupt files, play, and disposal)");
    }

    static <T> T proxy(Class<T> type, InvocationHandler handler) {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, handler));
    }

    static void check(boolean condition, String text) {
        if (!condition) throw new AssertionError(text);
    }
}

import com.badlogic.gdx.backends.lwjgl3.audio.Wav.WavInputStream;
import com.badlogic.gdx.files.FileHandle;
import java.nio.file.Files;
import java.nio.file.Path;

class MobDecodeCheck {
    public static void main(String[] args) throws Exception {
        int count = 0;
        long total = 0;
        byte[] bytes = new byte[8192];
        try (var resources = Files.walk(Path.of("src/main/resources/audio/sfx/mob"))) {
            for (var path : resources.filter(Files::isRegularFile).toList()) {
                try (var wav = new WavInputStream(new FileHandle(path.toFile()))) {
                    if (wav.channels != 1 || wav.bitDepth != 16 || wav.sampleRate != 22050) {
                        throw new AssertionError("Unsupported PCM WAV " + path);
                    }
                    int expected = wav.dataRemaining;
                    int actual = 0;
                    int n;
                    while ((n = wav.read(bytes)) > 0) actual += n;
                    if (actual != expected) throw new AssertionError("Truncated WAV " + path);
                    count++;
                    total += actual;
                }
            }
        }
        if (count != 212) throw new AssertionError("Expected 212 files but found " + count);
        System.out.println("libGDX LWJGL3 WAV decoder read 212 files and " + total + " PCM bytes.");
    }
}

