package com.voxelgame.engine;

import com.badlogic.gdx.math.Vector3;
import com.voxelgame.entity.Block;
import com.voxelgame.entity.projectile.ArrowEntity;
import com.voxelgame.entity.projectile.ArrowType;
import com.voxelgame.entity.projectile.ProjectileEntity;
import java.util.ArrayList;
import java.util.Random;

class ProjectileDifferential {
    record Voxel(int x, int y, int z, Block.Bounds bounds) {}
    static final float R = .045f;

    public static void main(String[] args) throws Exception {
        World world = World.empty();
        try {
            var method = ProjectileEntity.class.getDeclaredMethod("blockEntry", World.class);
            method.setAccessible(true);
            var field = ProjectileEntity.class.getDeclaredField("segment");
            field.setAccessible(true);
            var arrow = new ArrowEntity(null, 20f, 20f, 20f, 0f, 0f, 0f, ArrowType.NORMAL, 4f);
            var segment = (Vector3) field.get(arrow);
            var random = new Random(287L);
            var voxels = new ArrayList<Voxel>();
            for (int x=13; x<=27; x++) for (int y=13; y<=27; y++) for (int z=13; z<=27; z++) {
                int select = random.nextInt(24);
                if (select > 2) continue;
                Block block = select == 0 ? Block.STONE : select == 1 ? Block.CACTUS : Block.SNOW_LAYER;
                world.setBlockInternal(x, y, z, block.getId(), select == 2 ? random.nextInt(1,7) : 0);
                voxels.add(new Voxel(x,y,z,world.getCollisionBounds(x,y,z)));
            }
            for (int i=0; i<5000; i++) {
                float x=15+10*random.nextFloat(), y=15+10*random.nextFloat(), z=15+10*random.nextFloat();
                arrow.setPosition(x,y,z);
                segment.set(14*random.nextFloat()-7,14*random.nextFloat()-7,14*random.nextFloat()-7);
                float actual = (float) method.invoke(arrow, world);
                double expected = Double.POSITIVE_INFINITY;
                for (var voxel : voxels) {
                    expected = Math.min(expected, intersect(x,y,z,segment,voxel));
                }
                if (Float.isFinite(actual) != Double.isFinite(expected)
                        || (Float.isFinite(actual) && Math.abs(actual-expected) > 1e-5)) {
                    throw new AssertionError(i + ": actual=" + actual + " expected=" + expected);
                }
            }
            System.out.println("5000 seeded projectile DDA rays matched brute-force expanded-AABB collision.");
        } finally {
            world.dispose();
        }
    }

    static double intersect(float x,float y,float z,Vector3 delta,Voxel v) {
        var b = v.bounds();
        double t0=0,t1=1;
        for (int axis=0;axis<3;axis++) {
            float o=axis==0?x:axis==1?y:z;
            float d=axis==0?delta.x:axis==1?delta.y:delta.z;
            int cell=axis==0?v.x():axis==1?v.y():v.z();
            float min=cell+(axis==0?b.minX():axis==1?b.minY():b.minZ())-R;
            float max=cell+(axis==0?b.maxX():axis==1?b.maxY():b.maxZ())+R;
            if(d==0) {
                if(o<min||o>max) return Double.POSITIVE_INFINITY;
            } else {
                double a=(min-o)/(double)d,c=(max-o)/(double)d;
                if(a>c) { double swap=a;a=c;c=swap; }
                if(a>t0)t0=a;
                if(c<t1)t1=c;
                if(t0>t1)return Double.POSITIVE_INFINITY;
            }
        }
        return t0;
    }
}

