package com.voxelgame.engine;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.Input;
import com.badlogic.gdx.math.Vector3;
import com.voxelgame.VoxelGameApp;
import com.voxelgame.entity.Block;
import com.voxelgame.entity.Player;
import java.lang.reflect.Proxy;
import java.util.HashSet;
import java.util.Set;

public class ShortcutChecks {
    static void set(Object target, String name, Object value) throws Exception {
        var field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    static void require(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    public static void main(String[] args) throws Exception {
        Set<Integer> keys = new HashSet<>();
        Gdx.input = (Input) Proxy.newProxyInstance(Input.class.getClassLoader(), new Class<?>[]{Input.class},
            (proxy, method, parameters) -> keys.contains(parameters[0]));
        World world = World.empty();
        Player player = new Player(100.5f, 21f, 100.5f);
        Camera camera = new Camera();
        player.attachControls(camera);
        VoxelGameApp app = new VoxelGameApp();
        set(app, "player", player);
        set(app, "world", world);
        for (int x : new int[]{500, 1500, 2500}) {
            world.fillGeneratedColumn(x, 896, 0, 21, Block.STONE);
        }
        world.setBlock(500, 21, 896, Block.WATER.getId());
        world.fillGeneratedColumn(499, 895, 0, 21, Block.GRASS);

        int[] multipliers = {1, 3, 5, 10, 25, 50, 1};
        for (int i = 0; i < multipliers.length; i++) {
            if (i > 0) {
                keys.add(Input.Keys.CONTROL_RIGHT);
                keys.add(Input.Keys.S);
                require(app.keyDown(Input.Keys.S), "Ctrl+S must be handled");
                player.update(world, 0.01f);
                require(player.getVelocity().x == 0 && player.getVelocity().z == 0,
                    "The shortcut must not move the player backward");
                app.keyUp(Input.Keys.S);
                keys.clear();
            }
            keys.add(Input.Keys.W);
            player.update(world, 0.01f);
            float speed = (float) Math.hypot(player.getVelocity().x, player.getVelocity().z);
            require(Math.abs(speed - 5.5f * multipliers[i]) < 0.01f, "Expected speed " + multipliers[i]);
            keys.clear();
        }

        keys.add(Input.Keys.CONTROL_LEFT);
        for (int x : new int[]{499, 1500, 2500, 499}) {
            require(app.keyDown(Input.Keys.C), "Ctrl+C must be handled");
            Vector3 feet = player.getPosition();
            require(feet.x == x + 0.5f && feet.y == 21f, "Unexpected biome landing " + feet);
            require(feet.z == (x == 499 ? 895.5f : 896.5f), "Unexpected landing Z " + feet);
            require(player.getVelocity().isZero() && player.isOnGround(), "Must start grounded without velocity");
        }
        set(app, "isPaused", true);
        require(!app.keyDown(Input.Keys.C) && !app.keyDown(Input.Keys.S), "Shortcuts must be disabled while paused");
        world.dispose();

        World generated = World.empty();
        new TerrainGenerator(World.WORLD_SEED).generate(generated);
        for (BiomeType biome : BiomeType.values()) {
            require(player.teleportToBiome(generated, biome), "No landing in generated " + biome);
            Vector3 feet = player.getPosition();
            int x = (int) feet.x;
            int z = (int) feet.z;
            require(generated.getBiome(x, z) == biome, "Wrong biome");
            keys.clear();
            player.update(generated, 0.016f);
            require(player.isOnGround() && Math.abs(player.getPosition().y - feet.y) < 0.001f,
                "Landing must stay on the actual collision surface");
            System.out.println(biome + " landing: " + feet);
        }
        generated.dispose();
        System.out.println("Shortcut checks passed.");
    }
}

package com.voxelgame.engine;
import com.voxelgame.entity.Block;
import java.util.Arrays;

public final class VegetationProbe {
    public static void main(String[] args) {
        TerrainGenerator terrain = new TerrainGenerator(World.WORLD_SEED);
        World world = World.empty();
        try {
            terrain.generate(world);
            int[] trees = new int[7];
            int[] flowers = new int[4];
            int palmsNearWater = 0;
            int[] groves = new int[World.WORLD_SIZE_X / 64 + 1];
            for (int x = 0; x < World.WORLD_SIZE_X; x++) {
                for (int z = 0; z < World.WORLD_SIZE_Z; z++) {
                    int y = terrain.getSurfaceY(x, z) + 1;
                    BiomeType biome = terrain.getBiome(x, z);
                    for (int k = Math.max(1, y - 4); k <= y + 1; k++) {
                        byte id = world.getBlock(x, k, z);
                        if (id >= Block.DANDELION.getId() && id <= Block.OXEYE_DAISY.getId()) {
                            flowers[id - Block.DANDELION.getId()]++;
                        }
                        if ((id != Block.OAK_LOG.getId() && id != Block.SPRUCE_LOG.getId())
                              || world.getBlock(x, k - 1, z) == id) {
                            continue;
                        }
                        int end = k;
                        while (world.getBlock(x, end, z) == id) end++;
                        int height = end - k;
                        if (id == Block.OAK_LOG.getId()) {
                            if (biome == BiomeType.DESERT) {
                                trees[6]++;
                                if (world.getBlock(x, k - 1, z) == Block.SAND.getId()) {
                                    for (int dx = -2; dx <= 2; dx++) {
                                        for (int dz = -2; dz <= 2; dz++) {
                                            if (Math.abs(dx) + Math.abs(dz) <= 2
                                                && (world.getBlock(x + dx, k - 1, z + dz) == Block.WATER.getId()
                                                    || world.getBlock(x + dx, k - 2, z + dz) == Block.WATER.getId())) {
                                                palmsNearWater++;
                                            }
                                        }
                                    }
                                }
                            } else {
                                trees[height == 1 ? 0 : height >= 9 ? 2 : 1]++;
                                if (z < 64 && biome == BiomeType.PLAINS) groves[x / 64]++;
                            }
                        } else {
                            trees[k - 1 >= 62 ? 5 : k - 1 >= 45 ? 4 : 3]++;
                        }
                    }
                }
            }
            System.out.println("trees bush/oak/ancient/spruce/pine/dwarf/palm=" + Arrays.toString(trees));
            System.out.println("flowers=" + Arrays.toString(flowers) + ", palms near water hits=" + palmsNearWater);
            System.out.println("groves across Plains at z=0..63: " + Arrays.toString(Arrays.copyOfRange(groves, 16, 31)));
            if (Arrays.stream(trees).anyMatch(count -> count == 0) || Arrays.stream(flowers).anyMatch(count -> count == 0)
                || palmsNearWater < trees[6]) throw new AssertionError("Missing variant or oasis water");
        } finally {
            world.dispose();
        }
    }
}

package com.voxelgame;

import com.badlogic.gdx.backends.lwjgl3.Lwjgl3Application;
import com.badlogic.gdx.backends.lwjgl3.Lwjgl3ApplicationConfiguration;

/**
 * Điểm khởi chạy chính (Entry Point) của dự án Voxel Game 3D (Minecraft
 * Edition).
 *
 * Lớp này chịu trách nhiệm duy nhất: cấu hình cửa sổ Desktop thông qua
 * {@link Lwjgl3ApplicationConfiguration} và khởi tạo {@link Lwjgl3Application}
 * để chạy ứng dụng libGDX với backend LWJGL 3.
 *
 * CẤU TRÚC KIẾN TRÚC SAU TÁI CẤU TRÚC:
 * - {@code com.voxelgame.Main}: Lớp khởi chạy gốc duy nhất (giữ nguyên cấu hình
 * {@code mainClass} trong {@code build.gradle}).
 * - {@code com.voxelgame.VoxelGameApp}: Lớp ứng dụng chính kế thừa
 * {@code ApplicationAdapter},
 * quản lý toàn bộ vòng lặp Game Loop, xử lý Input, trạng thái Pause Menu.
 * - {@code com.voxelgame.entity}: Package đóng gói cây kế thừa Thực thể
 * ({@code Entity}, {@code Player},
 * {@code ItemEntity}, {@code Hotbar}, {@code Block} và 9 lớp Block con).
 * - {@code com.voxelgame.engine}: Package đóng gói lõi Engine Đồ họa, Thế giới,
 * Vật lý, Giao diện
 * và Âm thanh ({@code World}, {@code Chunk}, {@code Camera}, {@code Raycast},
 * {@code ShaderProgram},
 * {@code Texture}, {@code UIRenderer}, {@code AudioManager}).
 */
public class Main {

    /**
     * Hàm main() - điểm khởi đầu duy nhất của toàn bộ ứng dụng.
     * Tạo cấu hình cửa sổ Desktop và khởi chạy vòng lặp libGDX.
     *
     * @param args tham số dòng lệnh (không sử dụng)
     */
    public static void main(String[] args) {
        // =====================================================================
        // Tạo cấu hình cửa sổ Desktop thông qua Lwjgl3ApplicationConfiguration
        // =====================================================================
        Lwjgl3ApplicationConfiguration config = new Lwjgl3ApplicationConfiguration();
        // Dùng VAO của OpenGL 3.3 cho Mesh để không thiết lập lại thuộc tính đỉnh mỗi
        // lần vẽ chunk.
        config.setOpenGLEmulation(Lwjgl3ApplicationConfiguration.GLEmulation.GL30, 3, 3);

        // Tiêu đề cửa sổ game hiển thị trên thanh tiêu đề hệ điều hành
        config.setTitle("OurCraft");

        // Kích thước mặc định 1280 x 720 pixel (tỷ lệ 16:9 chuẩn HD)
        config.setWindowedMode(1280, 720);

        // Bật V-Sync đồng bộ tốc độ khung hình với tần số quét màn hình (thường 60 Hz)
        // để đạt 60 FPS mượt mà, loại bỏ hiện tượng xé hình (screen tearing)
        config.useVsync(true);

        // Cấu hình bộ đệm khung hình nền (Back Buffer):
        // - RGBA 8-8-8-8 bit: Mỗi kênh màu Red/Green/Blue/Alpha dùng 8 bit (256 mức)
        // - Depth Buffer 24 bit: Đảm bảo kiểm tra chiều sâu 3D chính xác cho voxel
        // - Stencil Buffer 0 bit: Không cần sử dụng
        // - Mẫu khử răng cưa (MSAA) 0: Không dùng để tối ưu hiệu năng GPU
        config.setBackBufferConfig(8, 8, 8, 8, 24, 0, 0);

        // Cho phép người dùng thay đổi kích thước cửa sổ bằng cách kéo viền
        config.setResizable(true);

        // =====================================================================
        // Khởi chạy ứng dụng libGDX với lớp VoxelGameApp (ApplicationAdapter)
        // Constructor của Lwjgl3Application sẽ:
        // 1. Tạo cửa sổ GLFW với cấu hình ở trên
        // 2. Tạo OpenGL Context 3.3 Core Profile (tương thích GLSL 330)
        // 3. Gọi VoxelGameApp.create() để khởi tạo tài nguyên
        // 4. Chạy vòng lặp Game Loop (gọi render() mỗi khung hình)
        // 5. Khi đóng cửa sổ, gọi VoxelGameApp.dispose() để giải phóng tài nguyên
        // =====================================================================
        new Lwjgl3Application(new VoxelGameApp(), config);
    }
}

