package com.voxelgame.client.audio;

import com.voxelgame.world.level.block.Block;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.audio.Music;
import com.badlogic.gdx.audio.Sound;
import com.badlogic.gdx.files.FileHandle;
import com.badlogic.gdx.utils.Disposable;
import java.util.concurrent.ThreadLocalRandom;

/** Phát danh sách nhạc theo vòng xáo và hiệu ứng âm thanh của các tương tác voxel. */
public class AudioManager implements Disposable {
    /** Đường dẫn đóng gói của năm bài nhạc đã chọn. */
    private static final String[] TRACKS = {
            "calm1.ogg", "calm3.ogg", "hal3.ogg", "piano2.ogg", "piano3.ogg"
    };
    /** Khoảng im lặng ba giây, đo bằng đồng hồ đơn điệu kể từ lúc nhận callback. */
    private static final long TRACK_GAP_NANOS = 3_000_000_000L;
    /** Khoảng chờ trước khi thử lại nếu mọi nguồn phát OpenAL đang bận. */
    private static final long RAIN_RETRY_NANOS = 200_000_000L;
    /** Bán kính nghe tối đa (block) cho âm thanh trúng đòn giữa các thực thể. */
    private static final float ENTITY_HIT_RANGE = 16.0f;
    /** Gốc tài nguyên âm thanh bên trong classpath. */
    private static final String MUSIC_ROOT = "audio/music/";
    private static final String SFX_ROOT = "audio/sfx/";

    /** Các nhóm mẫu ngắn phát theo sự kiện và theo vật liệu. */
    public enum Effect {
        DIG_GRASS("dig/grass", 4), DIG_GRAVEL("dig/gravel", 4), DIG_SAND("dig/sand", 4),
        DIG_SNOW("dig/snow", 4), DIG_STONE("dig/stone", 4), DIG_WOOD("dig/wood", 4),
        STEP_GRASS("step/grass", 6), STEP_GRAVEL("step/gravel", 4), STEP_SAND("step/sand", 5),
        STEP_SNOW("step/snow", 4), STEP_STONE("step/stone", 6), STEP_WOOD("step/wood", 6),
        GLASS_BREAK("random/glass", 3), PICKUP("random/pop"), CLICK("random/click"),
        CACTUS_HURT("damage/hit", 3), SWIM("liquid/swim", 18),
        WATER_ENTER("liquid/splash", "liquid/splash2"), DIVE("ambient/underwater/enter", 3),
        SURFACE("ambient/underwater/exit", 3), WATER_NEARBY("liquid/water"),
        LAVA_NEARBY("liquid/lava"), LAVA_POP("liquid/lavapop"),
        /** Tiếng xì hơi nước khi Water và Lava tiếp xúc tạo thành Stone. */
        FIZZ("random/fizz"),
        /** Âm thanh bắn cung, ném đạn, tụ giáo, ăn uống và thổi sừng dê (Track A). */
        BOW_SHOOT("mob/shared/bow_shoot"), THROW("random/bow"),
        SPEAR_CHARGE("mob/shared/spear_charge"),
        EAT("random/eat", 3), BURP("random/burp"), DRINK("random/drink"),
        GOAT_HORN("item/goat_horn/call0"),
        /** Âm thanh trúng đòn cận chiến hoặc đạn đạo giữa các thực thể (damage/hit1..3.ogg). */
        ENTITY_HIT("damage/hit", 3);

        /** Đường dẫn tương đối của các biến thể trong nhóm, chưa gồm đuôi OGG. */
        private final String[] paths;

        /** Gom mẫu có tên riêng vào cùng một sự kiện. */
        Effect(String... paths) {
            this.paths = paths;
        }

        /** Gom dãy mẫu được đánh số từ 1 trong gói nguồn. */
        Effect(String prefix, int count) {
            paths = new String[count];
            for (int i = 0; i < count; i++) {
                paths[i] = prefix + (i + 1);
            }
        }
    }

    /** Mẫu đào và bước chân; băng dùng riêng tiếng kính ở thời điểm vỡ. */
    private enum Material {
        GRASS(Effect.DIG_GRASS, Effect.STEP_GRASS),
        GRAVEL(Effect.DIG_GRAVEL, Effect.STEP_GRAVEL),
        SAND(Effect.DIG_SAND, Effect.STEP_SAND),
        SNOW(Effect.DIG_SNOW, Effect.STEP_SNOW),
        STONE(Effect.DIG_STONE, Effect.STEP_STONE),
        WOOD(Effect.DIG_WOOD, Effect.STEP_WOOD),
        ICE(Effect.DIG_STONE, Effect.STEP_STONE);

        private final Effect dig;
        private final Effect step;

        /** Ghép hai nhóm mẫu mô tả cùng một vật liệu. */
        Material(Effect dig, Effect step) {
            this.dig = dig;
            this.step = step;
        }
    }

    /** Tái sử dụng bảng mẫu và thứ tự bài trong suốt phiên chơi. */
    private final Sound[][] sounds = new Sound[Effect.values().length][];
    private final MobSoundBank mobSounds;
    private final FileHandle[] trackFiles = new FileHandle[TRACKS.length];
    private final int[] trackOrder = new int[TRACKS.length];
    /** Tọa độ người nghe dùng chung cho mọi sự kiện mob trong cùng lượt cập nhật. */
    private float listenerX;
    private float listenerY;
    private float listenerZ;
    private boolean mobListenerReady;
    /** Các luồng nhạc, âm nền dưới nước và tiếng mưa hoạt động độc lập. */
    private Music backgroundMusic;
    private Music underwaterAmbience;
    private Music rainAmbience;
    private float rainGain;
    private boolean rainPlaying;
    private boolean rainPaused;
    private long rainRetryAt;
    /** Con trỏ vòng xáo, bài vừa mở thành công và mốc hết khoảng nghỉ. */
    private int nextTrack = TRACKS.length;
    private int lastTrack = -1;
    private long trackDeadline;
    /** Các cờ vòng đời giúp chia sẻ đường cập nhật với game đang Pause. */
    private boolean running;
    private boolean waitingForTrack;
    private boolean underwaterPlaying;
    private boolean disposed;
    /** Âm lượng chung của nhạc nền và mưa, điều khiển bằng Pause Menu. */
    private float volume = 0.70f;

    /** Nạp trước mẫu ngắn và xác định các tài nguyên nhạc đã đóng gói. */
    public AudioManager() {
        for (int i = 0; i < TRACKS.length; i++) {
            trackFiles[i] = findAsset(MUSIC_ROOT + TRACKS[i]);
        }
        for (Effect effect : Effect.values()) {
            Sound[] variants = new Sound[effect.paths.length];
            sounds[effect.ordinal()] = variants;
            for (int i = 0; i < variants.length; i++) {
                FileHandle file = findAsset(SFX_ROOT + effect.paths[i] + ".ogg");
                if (file != null) {
                    try {
                        variants[i] = Gdx.audio.newSound(file);
                    } catch (RuntimeException error) {
                        logLoadError(file, error);
                    }
                }
            }
        }
        FileHandle rainFile = findAsset("audio/weather/rain.wav");
        if (rainFile != null) {
            try {
                rainAmbience = Gdx.audio.newMusic(rainFile);
                rainAmbience.setLooping(true);
                rainAmbience.setVolume(0f);
            } catch (RuntimeException error) {
                logLoadError(rainFile, error);
                if (rainAmbience != null) {
                    rainAmbience.dispose();
                    rainAmbience = null;
                }
            }
        }
        FileHandle underwater = findAsset(SFX_ROOT + "ambient/underwater/underwater_ambience.ogg");
        if (underwater != null) {
            try {
                underwaterAmbience = Gdx.audio.newMusic(underwater);
                underwaterAmbience.setLooping(true);
                underwaterAmbience.setVolume(0.18f);
            } catch (RuntimeException error) {
                logLoadError(underwater, error);
                if (underwaterAmbience != null) {
                    underwaterAmbience.dispose();
                    underwaterAmbience = null;
                }
            }
        }
        mobSounds = new MobSoundBank();
    }

    /** Chỉ tìm tài nguyên có đường dẫn cố định trong classpath của trò chơi. */
    static FileHandle findAsset(String path) {
        FileHandle file = Gdx.files.classpath(path);
        return file.exists() ? file : null;
    }

    /** Ghi đường dẫn mẫu lỗi để có thể phát hiện tài nguyên hỏng hoặc thiếu bộ giải mã. */
    static void logLoadError(FileHandle file, RuntimeException error) {
        System.err.println("[AudioManager] Không mở được " + file.path() + " - " + error.getMessage());
    }

    /** Bắt đầu vòng nhạc đầu tiên, giữ nguyên bài hiện tại nếu được gọi thêm. */
    public void startBackgroundMusic() {
        if (!running && !disposed) {
            running = true;
            playNextTrack();
        }
    }

    /** Kiểm tra hết khoảng nghỉ và đổi bài ngoài callback cập nhật OpenAL của libGDX. */
    public void update() {
        if (waitingForTrack && System.nanoTime() - trackDeadline >= 0L) {
            waitingForTrack = false;
            playNextTrack();
        }
        if (!rainPlaying && !rainPaused && rainGain > 0f) {
            syncRainPlayback();
        }
    }

    /** Tạo hoán vị mới bằng Fisher–Yates và tránh trùng ngay với bài vừa phát. */
    private void shuffleTracks() {
        for (int i = 0; i < trackOrder.length; i++) {
            trackOrder[i] = i;
        }
        ThreadLocalRandom random = ThreadLocalRandom.current();
        for (int i = trackOrder.length - 1; i > 0; i--) {
            swapTracks(i, random.nextInt(i + 1));
        }
        if (trackOrder[0] == lastTrack) {
            swapTracks(0, random.nextInt(1, trackOrder.length));
        }
        nextTrack = 0;
    }

    /** Đổi chỗ hai vị trí trong vòng nhạc. */
    private void swapTracks(int first, int second) {
        int previous = trackOrder[first];
        trackOrder[first] = trackOrder[second];
        trackOrder[second] = previous;
    }

    /** Nếu cuối vòng chỉ có tệp lỗi, vẫn thử đủ cả vòng mới để tìm bài còn dùng được. */
    private void playNextTrack() {
        disposeCurrentTrack();
        int maxAttempts = trackOrder.length - nextTrack + trackOrder.length;
        for (int attempts = 0; attempts < maxAttempts; attempts++) {
            if (nextTrack == trackOrder.length) {
                shuffleTracks();
            }
            int track = trackOrder[nextTrack++];
            FileHandle file = trackFiles[track];
            if (file == null) {
                continue;
            }
            try {
                backgroundMusic = Gdx.audio.newMusic(file);
                backgroundMusic.setLooping(false);
                backgroundMusic.setVolume(volume);
                backgroundMusic.setOnCompletionListener(this::onTrackComplete);
                backgroundMusic.play();
                lastTrack = track;
                return;
            } catch (RuntimeException error) {
                logLoadError(file, error);
                disposeCurrentTrack();
                trackFiles[track] = null;
            }
        }
        running = false;
    }

    /** Lập khoảng nghỉ khi luồng âm thanh báo đã phát hết bài. */
    private void onTrackComplete(Music track) {
        if (running && track == backgroundMusic) {
            trackDeadline = System.nanoTime() + TRACK_GAP_NANOS;
            waitingForTrack = true;
        }
    }

    /** Tháo callback trước khi giải phóng luồng nhạc cũ. */
    private void disposeCurrentTrack() {
        if (backgroundMusic != null) {
            backgroundMusic.setOnCompletionListener(null);
            backgroundMusic.dispose();
            backgroundMusic = null;
        }
    }

    /** Áp dụng ngay âm lượng và dùng lại giá trị này cho những bài tiếp theo. */
    public void setVolume(float newVolume) {
        volume = Math.max(0f, Math.min(1f, newVolume));
        if (backgroundMusic != null) {
            backgroundMusic.setVolume(volume);
        }
        if (rainAmbience != null) {
            rainAmbience.setVolume(volume * rainGain);
        }
    }

    /** Áp dụng cường độ mưa cục bộ sau khi đã xét biome và mái che. */
    public void setRainGain(float gain) {
        if (rainGain != gain) {
            rainGain = gain;
            if (rainAmbience != null) {
                rainAmbience.setVolume(volume * rainGain);
            }
            syncRainPlayback();
        }
    }

    /** Tạm dừng luồng mưa khi mở menu và giữ vị trí phát để tiếp tục. */
    public void setRainPaused(boolean paused) {
        rainPaused = paused;
        syncRainPlayback();
    }

    /** Chỉ đổi trạng thái OpenAL khi bắt đầu, tạnh mưa hoặc bật/tắt Pause. */
    private void syncRainPlayback() {
        boolean shouldPlay = !rainPaused && rainGain > 0f;
        if (rainAmbience != null && shouldPlay != rainPlaying) {
            if (shouldPlay) {
                long now = System.nanoTime();
                if (rainRetryAt != 0L && now - rainRetryAt < 0L) {
                    return;
                }
                rainAmbience.play();
                rainPlaying = rainAmbience.isPlaying();
                rainRetryAt = rainPlaying ? 0L : now + RAIN_RETRY_NANOS;
            } else {
                rainAmbience.pause();
                rainPlaying = false;
            }
        }
    }

    /** Tăng hoặc giảm âm lượng theo bước của giao diện. */
    public void changeVolume(float delta) {
        setVolume(volume + delta);
    }

    /** Đọc âm lượng hiện tại trong khoảng từ 0 đến 1. */
    public float getVolume() {
        return volume;
    }

    /** Quy đổi âm lượng sang phần trăm nguyên cho Pause Menu. */
    public int getVolumePercent() {
        return Math.round(volume * 100f);
    }

    /** Kiểm tra xem bài nhạc hiện tại đang phát hay đang ở khoảng nghỉ. */
    public boolean isPlaying() {
        return backgroundMusic != null && backgroundMusic.isPlaying();
    }

    /** Chọn vật liệu theo nhóm âm thanh, độc lập với biome của cột. */
    private static Material materialOf(Block block) {
        if (block == Block.DIRT || block == Block.GRAVEL) {
            return Material.GRAVEL;
        }
        if (block == Block.SAND) {
            return Material.SAND;
        }
        if (block == Block.SNOW_LAYER || block == Block.SNOW_BLOCK) {
            return Material.SNOW;
        }
        if (block == Block.OAK_LOG || block == Block.SPRUCE_LOG || block == Block.CHEST) {
            return Material.WOOD;
        }
        if (block == Block.ICE) {
            return Material.ICE;
        }
        if (block == Block.STONE || block == Block.BEDROCK || block == Block.SANDSTONE) {
            return Material.STONE;
        }
        return Material.GRASS;
    }

    /** Phát tiếng chạm nhẹ theo nhịp giữ chuột đào. */
    public void playMining(Block block) {
        playEffect(materialOf(block).step, 0.19f);
    }

    /** Phát tiếng khối vỡ sau khi thay đổi trong thế giới đã được ghi. */
    public void playBreak(Block block, float gain) {
        Material material = materialOf(block);
        playEffect(material == Material.ICE ? Effect.GLASS_BREAK : material.dig, 0.65f * gain);
    }

    /** Phát tiếng đặt khối với cao độ thấp hơn tiếng phá. */
    public void playPlace(Block block) {
        playSample(materialOf(block).dig, 0.58f, 0.8f);
    }

    /** Phát tiếng bước chân, giảm âm lượng khi rón rén. */
    public void playStep(Block block, boolean sneaking) {
        playEffect(materialOf(block).step, sneaking ? 0.10f : 0.28f);
    }

    /** Chọn tiếng chân theo mặt đất và giảm âm lượng theo khoảng cách đến mob. */
    public void playMobStep(Block ground, float x, float y, float z) {
        if (!mobListenerReady || ground == Block.AIR || ground.isLiquid()) {
            return;
        }
        float dx = x - listenerX;
        float dy = y - listenerY;
        float dz = z - listenerZ;
        float gain = mobGain(dx * dx + dy * dy + dz * dz, MobSoundEvent.STEP.defaultRange());
        playSample(materialOf(ground).step, 0.15f * gain, 1f);
    }

    /** Phát tiếng tiếp đất của người chơi hoặc cát/sỏi rơi. */
    public void playLanding(Block block, float gain) {
        playEffect(materialOf(block).step, 0.51f * gain);
    }

    /** Phát một biến thể của sự kiện ở cao độ gần với mẫu nguồn. */
    public void playEffect(Effect effect, float gain) {
        playSample(effect, gain, 1f);
    }

    /** Cập nhật tọa độ người nghe trước lượt mô phỏng phát sự kiện mob. */
    public void setMobListener(float x, float y, float z) {
        listenerX = x;
        listenerY = y;
        listenerZ = z;
        mobListenerReady = true;
    }

    /** Phát một biến thể tại tọa độ thế giới, dùng khoảng nghe mặc định khi bán kính không dương. */
    public void playMobSound(String mobId, MobSoundEvent event, float x, float y, float z,
                             float maxRange, float pitchMultiplier) {
        if (disposed || !mobListenerReady || event == null) {
            return;
        }
        float dx = x - listenerX;
        float dy = y - listenerY;
        float dz = z - listenerZ;
        float range = maxRange > 0f ? maxRange : event.defaultRange();
        float gain = mobGain(dx * dx + dy * dy + dz * dz, range);
        if (gain <= 0f) {
            return;
        }
        ThreadLocalRandom random = ThreadLocalRandom.current();
        Sound sound = mobSounds.choose(mobId, event, random);
        if (sound != null) {
            sound.play(gain, mobPitch(pitchMultiplier, random.nextFloat()), 0f);
        }
    }

    /**
     * Phát ngẫu nhiên biến thể tiếng trúng đòn ({@code damage/hit1..3.ogg}) tại tọa độ thế giới,
     * suy giảm âm lượng tuyến tính trong phạm vi 16 block tới người nghe.
     *
     * @param x tọa độ X tại điểm thực thể nhận sát thương
     * @param y tọa độ Y tại điểm thực thể nhận sát thương
     * @param z tọa độ Z tại điểm thực thể nhận sát thương
     */
    public void playEntityHit(float x, float y, float z) {
        if (disposed || !mobListenerReady) {
            return;
        }
        float dx = x - listenerX;
        float dy = y - listenerY;
        float dz = z - listenerZ;
        float gain = mobGain(dx * dx + dy * dy + dz * dz, ENTITY_HIT_RANGE);
        if (gain > 0f) {
            playSample(Effect.ENTITY_HIT, 0.55f * gain, 1.0f);
        }
    }

    /** Suy giảm tuyến tính từ nguồn đến rìa, kiểm tra bình phương trước khi tính căn. */
    public static float mobGain(float distanceSquared, float maxRange) {
        if (!(distanceSquared >= 0f && distanceSquared < (double) maxRange * maxRange)
                || !(maxRange > 0f && Float.isFinite(maxRange))) {
            return 0f;
        }
        return 1f - (float) Math.sqrt(distanceSquared) / maxRange;
    }

    /** Biến thiên cao độ ±6% quanh hệ số yêu cầu, giới hạn trong miền phát của libGDX. */
    public static float mobPitch(float pitchMultiplier, float randomUnit) {
        float multiplier = pitchMultiplier > 0f && Float.isFinite(pitchMultiplier) ? pitchMultiplier : 1f;
        return Math.max(0.5f, Math.min(2f, multiplier * (0.94f + 0.12f * randomUnit)));
    }

    /** Tận dụng bộ đệm OpenAL đã nạp và tìm biến thể kế nếu có tệp lỗi. */
    private void playSample(Effect effect, float gain, float pitch) {
        if (disposed || gain <= 0f) {
            return;
        }
        Sound[] variants = sounds[effect.ordinal()];
        ThreadLocalRandom random = ThreadLocalRandom.current();
        int index = random.nextInt(variants.length);
        for (int i = 0; i < variants.length; i++) {
            Sound sample = variants[index];
            if (sample != null) {
                sample.play(gain, pitch * (0.94f + 0.12f * random.nextFloat()), 0f);
                return;
            }
            index = (index + 1) % variants.length;
        }
    }

    /** Điều khiển vòng âm nền dưới nước riêng với luồng nhạc nền chính. */
    public void setUnderwater(boolean underwater) {
        if (underwaterAmbience != null && underwater != underwaterPlaying) {
            underwaterPlaying = underwater;
            if (underwater) {
                underwaterAmbience.play();
            } else {
                underwaterAmbience.stop();
            }
        }
    }

    /** Hủy bộ hẹn giờ và giải phóng mỗi luồng, mỗi bộ đệm đúng một lần. */
    @Override
    public void dispose() {
        if (disposed) {
            return;
        }
        disposed = true;
        running = false;
        waitingForTrack = false;
        mobSounds.dispose();
        disposeCurrentTrack();
        if (rainAmbience != null) {
            rainAmbience.dispose();
            rainAmbience = null;
        }
        if (underwaterAmbience != null) {
            underwaterAmbience.dispose();
            underwaterAmbience = null;
        }
        for (Sound[] variants : sounds) {
            for (Sound sound : variants) {
                if (sound != null) {
                    sound.dispose();
                }
            }
        }
    }

    /** Điểm gọi tương thích của hệ thống âm thanh cũ. */
    public void cleanup() {
        dispose();
    }
}

package com.voxelgame.client.audio;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.audio.Sound;
import com.badlogic.gdx.files.FileHandle;
import com.badlogic.gdx.utils.Disposable;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;

/** Nạp và sở hữu các bộ đệm WAV và OGG của mob, tra mẫu theo ID và sự kiện. */
public final class MobSoundBank implements Disposable {
    /**
     * Vị trí cố định, số biến thể bắt buộc và số biến thể tối đa cho từng nhóm mẫu.
     */
    private static final String ROOT = "audio/sfx/mob/";
    private static final String SHARED = "shared";
    private static final int REQUIRED_VARIANTS = 2;
    private static final int MAX_VARIANTS = 4;

    /** Danh mục cố định đọc được cả khi tài nguyên nằm bên trong JAR. */
    private static final String[] MOB_IDS = {
            "zombie", "zombie_villager", "skeleton", "creeper", "spider", "enderman", "witch",
            "cow", "sheep", "pig", "chicken", "horse", "donkey", "rabbit", "camel", "camel_husk",
            "husk", "parched", "goat", "polar_bear", "wolf", "fox", "stray"
    };
    /** Bốn sự kiện chung được đóng gói cho mọi mob trong danh mục. */
    private static final MobSoundEvent[] COMMON_EVENTS = {
            MobSoundEvent.AMBIENT, MobSoundEvent.HURT, MobSoundEvent.DEATH, MobSoundEvent.STEP
    };
    /** Số khe sự kiện để tra mẫu trực tiếp qua ordinal của enum. */
    private static final int EVENT_COUNT = MobSoundEvent.values().length;

    /** Một bảng theo loài và một bảng riêng cho hiệu ứng dùng chung. */
    private final Map<String, Sound[][]> samplesByMob = new HashMap<>();
    private final Sound[][] sharedSamples = new Sound[EVENT_COUNT][];

    /** Nạp từng đường dẫn đúng một lần theo thứ tự cố định khi mở game. */
    MobSoundBank() {
        for (String mobId : MOB_IDS) {
            Sound[][] events = new Sound[EVENT_COUNT][];
            samplesByMob.put(mobId, events);
            for (MobSoundEvent event : COMMON_EVENTS) {
                if (hasSpeciesSample(mobId, event)) {
                    events[event.ordinal()] = loadVariants(mobId, event);
                }
            }
        }
        loadSpecial("creeper", MobSoundEvent.CREEPER_PRIMED);
        loadSpecial(SHARED, MobSoundEvent.EXPLODE);
        loadSpecial(SHARED, MobSoundEvent.BOW_SHOOT);
        loadSpecial("enderman", MobSoundEvent.ENDERMAN_STARE);
        loadSpecial("enderman", MobSoundEvent.ENDERMAN_TELEPORT);
        loadSpecial("enderman", MobSoundEvent.ENDERMAN_SCREAM);
        loadSpecial("witch", MobSoundEvent.WITCH_THROW);
        loadSpecial("witch", MobSoundEvent.WITCH_DRINK);
        loadSpecial("goat", MobSoundEvent.GOAT_RAM);
        loadSpecial("goat", MobSoundEvent.GOAT_SCREAM);
        loadSpecial("wolf", MobSoundEvent.WOLF_GROWL);
        loadSpecial("camel", MobSoundEvent.CAMEL_DASH);
        loadSpecial("camel_husk", MobSoundEvent.CAMEL_DASH);
        loadSpecial("husk", MobSoundEvent.HUSK_CONVERT);
        loadSpecial(SHARED, MobSoundEvent.SPEAR_CHARGE);
    }

    /**
     * Creeper im lặng lúc chờ. Bốn loài không có mẫu bước riêng dùng âm của khối
     * dưới chân.
     */
    public static boolean hasSpeciesSample(String id, MobSoundEvent event) {
        if (event == MobSoundEvent.AMBIENT)
            return !id.equals("creeper");
        return event != MobSoundEvent.STEP || !MobSoundEvent.usesBlockSteps(id);
    }

    /** Lưu nhóm đặc thù đúng một nơi, kể cả hiệu ứng nhiều loài dùng chung. */
    private void loadSpecial(String folder, MobSoundEvent event) {
        Sound[][] events = SHARED.equals(folder) ? sharedSamples : samplesByMob.get(folder);
        events[event.ordinal()] = loadVariants(folder, event);
    }

    /**
     * Bỏ qua mẫu thiếu hoặc lỗi và giữ liền các phần tử đã nạp để chọn đồng đều (hỗ
     * trợ 2–4 biến thể).
     */
    private static Sound[] loadVariants(String folder, MobSoundEvent event) {
        boolean originalOgg = event == MobSoundEvent.BOW_SHOOT || event == MobSoundEvent.SPEAR_CHARGE;
        int limit = originalOgg ? 1 : MAX_VARIANTS;
        Sound[] variants = new Sound[limit];
        int loaded = 0;
        for (int variant = 1; variant <= limit; variant++) {
            String path = ROOT + folder + "/" + event.assetName() + (originalOgg ? ".ogg" : variant + ".wav");
            FileHandle file = AudioManager.findAsset(path);
            if (file == null) {
                if (variant <= REQUIRED_VARIANTS) {
                    System.err.println("[AudioManager] Thiếu mẫu âm thanh " + path);
                }
                continue;
            }
            try {
                variants[loaded] = Gdx.audio.newSound(file);
                loaded++;
            } catch (RuntimeException error) {
                AudioManager.logLoadError(file, error);
            }
        }
        if (loaded == 0) {
            return null;
        }
        return loaded == variants.length ? variants : Arrays.copyOf(variants, loaded);
    }

    /**
     * Chọn biến thể thành công trong danh mục đã nạp, không tạo đối tượng khi phát.
     */
    Sound choose(String mobId, MobSoundEvent event, ThreadLocalRandom random) {
        Sound[][] events = samplesByMob.get(mobId);
        if (events == null) {
            return null;
        }
        int index = event.ordinal();
        Sound[] variants = events[index];
        if (variants == null && event == MobSoundEvent.CAMEL_DASH && "camel_husk".equals(mobId)) {
            variants = samplesByMob.get("camel")[index];
        }
        if (variants == null) {
            variants = sharedSamples[index];
        }
        return variants == null ? null : variants[random.nextInt(variants.length)];
    }

    /**
     * Giải phóng các mẫu đã mở thành công, gồm cả nhóm chỉ nạp được một biến thể.
     */
    @Override
    public void dispose() {
        for (Sound[][] events : samplesByMob.values()) {
            disposeEvents(events);
        }
        samplesByMob.clear();
        disposeEvents(sharedSamples);
    }

    /** Xóa khe sở hữu sau khi giải phóng, cho phép gọi dọn lại an toàn. */
    private static void disposeEvents(Sound[][] events) {
        for (int i = 0; i < events.length; i++) {
            Sound[] variants = events[i];
            if (variants != null) {
                for (Sound variant : variants) {
                    variant.dispose();
                }
                events[i] = null;
            }
        }
    }
}

package com.voxelgame.client.audio;

import java.util.Locale;

/** Sự kiện dùng chung giữa hành vi mob và hệ thống phát âm thanh. */
public enum MobSoundEvent {
    AMBIENT, HURT, DEATH, STEP,
    CREEPER_PRIMED, EXPLODE(32f), BOW_SHOOT,
    ENDERMAN_STARE, ENDERMAN_TELEPORT, ENDERMAN_SCREAM(32f),
    WITCH_THROW, WITCH_DRINK, GOAT_RAM, GOAT_SCREAM(28f),
    WOLF_GROWL, CAMEL_DASH, HUSK_CONVERT, SPEAR_CHARGE;

    /** Khoảng nghe của các hiệu ứng thông thường, tính bằng block. */
    private static final float NORMAL_RANGE = 16f;
    /** Tên tiền tố cố định khi đóng gói tệp WAV và khoảng nghe mặc định. */
    private final String assetName;
    private final float defaultRange;

    /** Tạo sự kiện có khoảng nghe thông thường. */
    MobSoundEvent() {
        this(NORMAL_RANGE);
    }

    /** Tạo sự kiện có khoảng nghe riêng và chuẩn hóa tên tệp khi khởi tạo enum. */
    MobSoundEvent(float defaultRange) {
        this.defaultRange = defaultRange;
        assetName = name().toLowerCase(Locale.ROOT);
    }

    /** Trả về tiền tố tệp dùng cho tất cả biến thể của sự kiện. */
    public String assetName() {
        return assetName;
    }

    /** Các loài dùng mẫu bước của khối dưới chân theo Java 26.3. */
    public static boolean usesBlockSteps(String mobId) {
        return switch (mobId) {
            case "creeper", "enderman", "fox", "witch" -> true;
            default -> false;
        };
    }

    /** Trả về khoảng nghe nếu bên gọi không chỉ định bán kính dương. */
    public float defaultRange() {
        return defaultRange;
    }
}

package com.voxelgame.client.gui;

/**
 * Phông chữ ma trận điểm ảnh 5×7 dùng chung duy nhất cho toàn bộ tầng giao diện Client
 * ({@link HudRenderer}, {@link PauseScreen}, {@link InventoryScreen}, {@link DebugOverlayRenderer}).
 *
 * Thiết kế Zero-GC:
 * - Bảng {@link #GLYPHS} được khởi tạo tĩnh đúng một lần khi nạp lớp.
 * - Cung cấp các hàm ghi trực tiếp đỉnh quad 2D (6 float/đỉnh) vào mảng bộ đệm tái sử dụng,
 *   loại bỏ hoàn toàn mã nguồn trùng lặp giữa HUD và màn hình túi đồ.
 */
public final class BitmapFont {

    /** Chiều rộng ma trận điểm ảnh của mỗi ký tự (pixel gốc). */
    public static final int GLYPH_WIDTH = 5;
    /** Chiều cao ma trận điểm ảnh của mỗi ký tự (pixel gốc). */
    public static final int GLYPH_HEIGHT = 7;
    /** Bước tiến ngang giữa hai ký tự liên tiếp (5 pixel chữ + 1 pixel khoảng cách). */
    public static final float CHAR_ADVANCE = 6.0f;

    /** Bảng ánh xạ mã ASCII (0..127) sang 7 hàng bit 5-cột của từng ký tự. */
    private static final int[][] GLYPHS = createGlyphs();

    private BitmapFont() {
    }

    /** Kiểm tra ký tự có mẫu glyph 5×7 tích hợp hay không (không phân biệt hoa/thường). */
    public static boolean hasGlyph(char c) {
        char upper = Character.toUpperCase(c);
        return upper < GLYPHS.length && GLYPHS[upper] != null;
    }

    /** Lấy mảng 7 hàng bit của ký tự (hoặc {@code null} nếu là khoảng trắng / chưa hỗ trợ). */
    public static int[] getGlyph(char c) {
        char upper = Character.toUpperCase(c);
        return upper < GLYPHS.length ? GLYPHS[upper] : null;
    }

    /** Tính chiều rộng hiển thị (pixel) của chuỗi ký tự theo hệ số phóng {@code pixelScale}. */
    public static float measureWidth(CharSequence text, float pixelScale) {
        if (text == null || text.isEmpty()) {
            return 0.0f;
        }
        return text.length() * CHAR_ADVANCE * pixelScale;
    }

    /** Tính chiều cao hiển thị (pixel) của một dòng chữ 5×7 theo hệ số phóng {@code pixelScale}. */
    public static float measureHeight(float pixelScale) {
        return GLYPH_HEIGHT * pixelScale;
    }

    /**
     * Ghi toàn bộ đỉnh hình học (2 tam giác / pixel bật) của chuỗi ký tự vào bộ đệm đỉnh dùng lại.
     *
     * @param buffer     mảng float đích (6 float mỗi đỉnh: x, y, z, u, v, shade)
     * @param offset     vị trí float bắt đầu ghi trong {@code buffer}
     * @param text       chuỗi cần vẽ
     * @param startX     tọa độ X góc trên-trái (pixel màn hình)
     * @param startY     tọa độ Y góc trên-trái (pixel màn hình)
     * @param pixelScale hệ số phóng mỗi điểm ảnh chữ
     * @param capacity   giới hạn số float tối đa được phép ghi vào {@code buffer}
     * @return vị trí {@code offset} mới sau khi ghi xong
     */
    public static int appendTextVertices(float[] buffer, int offset, CharSequence text,
                                         float startX, float startY, float pixelScale, int capacity) {
        if (text == null || text.isEmpty()) {
            return offset;
        }
        float cursorX = startX;
        for (int i = 0; i < text.length(); i++) {
            int[] glyph = getGlyph(text.charAt(i));
            if (glyph != null) {
                for (int row = 0; row < GLYPH_HEIGHT; row++) {
                    int rowBits = glyph[row];
                    for (int col = 0; col < GLYPH_WIDTH; col++) {
                        if (((rowBits >> (4 - col)) & 1) == 1) {
                            if (offset + 36 > capacity) {
                                return offset;
                            }
                            float px = cursorX + col * pixelScale;
                            float py = startY + row * pixelScale;
                            writeQuad(buffer, offset, px, py + pixelScale, 0f,
                                    px + pixelScale, py + pixelScale, 0f,
                                    px + pixelScale, py, 0f, px, py, 0f, 0f, 0f, 1f, 1f);
                            offset += 36;
                        }
                    }
                }
            }
            cursorX += CHAR_ADVANCE * pixelScale;
        }
        return offset;
    }

    /** Ghi bốn góc thành hai tam giác với cùng thứ tự thuộc tính (6 float/đỉnh) cho UI 2D và lớp phủ 3D. */
    public static void writeQuad(float[] data, int offset, float ax, float ay, float az,
                                 float bx, float by, float bz, float cx, float cy, float cz,
                                 float dx, float dy, float dz, float u0, float v0, float u1, float v1) {
        writeVertex(data, offset, ax, ay, az, u0, v1);
        writeVertex(data, offset + 6, bx, by, bz, u1, v1);
        writeVertex(data, offset + 12, cx, cy, cz, u1, v0);
        writeVertex(data, offset + 18, ax, ay, az, u0, v1);
        writeVertex(data, offset + 24, cx, cy, cz, u1, v0);
        writeVertex(data, offset + 30, dx, dy, dz, u0, v0);
    }

    /** Ghi vị trí (x, y, z), tọa độ UV và độ sáng đầy đủ {@code 1.0f} vào bộ đệm đỉnh UI. */
    public static void writeVertex(float[] data, int offset, float x, float y, float z, float u, float v) {
        data[offset] = x;
        data[offset + 1] = y;
        data[offset + 2] = z;
        data[offset + 3] = u;
        data[offset + 4] = v;
        data[offset + 5] = 1.0f;
    }

    /** Tạo toàn bộ bảng glyph một lần duy nhất thay vì cấp phát lại cho từng chữ. */
    private static int[][] createGlyphs() {
        int[][] glyphs = new int[128][];
        for (char c = 0; c < glyphs.length; c++) {
            glyphs[c] = createGlyph5x7(c);
        }
        return glyphs;
    }

    /** Sơ đồ bit 5×7 chuẩn của bộ chữ cái, chữ số và ký tự đặc biệt dùng trên HUD/F3/Menu. */
    private static int[] createGlyph5x7(char c) {
        return switch (c) {
            case 'A' -> new int[]{0b01110, 0b10001, 0b10001, 0b11111, 0b10001, 0b10001, 0b10001};
            case 'B' -> new int[]{0b11110, 0b10001, 0b10001, 0b11110, 0b10001, 0b10001, 0b11110};
            case 'C' -> new int[]{0b01110, 0b10001, 0b10000, 0b10000, 0b10000, 0b10001, 0b01110};
            case 'D' -> new int[]{0b11100, 0b10010, 0b10001, 0b10001, 0b10001, 0b10010, 0b11100};
            case 'E' -> new int[]{0b11111, 0b10000, 0b10000, 0b11110, 0b10000, 0b10000, 0b11111};
            case 'F' -> new int[]{0b11111, 0b10000, 0b10000, 0b11110, 0b10000, 0b10000, 0b10000};
            case 'G' -> new int[]{0b01110, 0b10001, 0b10000, 0b10111, 0b10001, 0b10001, 0b01110};
            case 'H' -> new int[]{0b10001, 0b10001, 0b10001, 0b11111, 0b10001, 0b10001, 0b10001};
            case 'I' -> new int[]{0b01110, 0b00100, 0b00100, 0b00100, 0b00100, 0b00100, 0b01110};
            case 'J' -> new int[]{0b00111, 0b00010, 0b00010, 0b00010, 0b10010, 0b10010, 0b01100};
            case 'K' -> new int[]{0b10001, 0b10010, 0b10100, 0b11000, 0b10100, 0b10010, 0b10001};
            case 'L' -> new int[]{0b10000, 0b10000, 0b10000, 0b10000, 0b10000, 0b10000, 0b11111};
            case 'M' -> new int[]{0b10001, 0b11011, 0b10101, 0b10101, 0b10001, 0b10001, 0b10001};
            case 'N' -> new int[]{0b10001, 0b11001, 0b10101, 0b10011, 0b10001, 0b10001, 0b10001};
            case 'O' -> new int[]{0b01110, 0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b01110};
            case 'P' -> new int[]{0b11110, 0b10001, 0b10001, 0b11110, 0b10000, 0b10000, 0b10000};
            case 'Q' -> new int[]{0b01110, 0b10001, 0b10001, 0b10001, 0b10101, 0b10010, 0b01101};
            case 'R' -> new int[]{0b11110, 0b10001, 0b10001, 0b11110, 0b10100, 0b10010, 0b10001};
            case 'S' -> new int[]{0b01111, 0b10000, 0b10000, 0b01110, 0b00001, 0b00001, 0b11110};
