/**
 * Bộ điều khiển Đầu vào & Tương tác Người chơi của Client ({@link InputProcessor}),
 * được tách khỏi {@code VoxelGameApp} theo nguyên lý Đơn trách nhiệm (SRP).
 *
 * Chịu trách nhiệm đóng gói toàn bộ xử lý bàn phím và chuột:
 * - Xoay Camera góc nhìn thứ nhất/thứ ba với cơ chế chống giật chuột ({@code skipNextMouseDelta}).
 * - Phím tắt hệ thống: {@code ESC} (Pause/Resume/Quit), {@code E} (Túi đồ 36 ô), {@code Q}/{@code Ctrl+Q}
 *   (vứt vật phẩm), {@code F1} (tốc độ địa hình), {@code F3} (Debug Overlay), {@code F5} (CameraMode),
 *   {@code F6}/{@code F7}/{@code F8} (thời tiết/giờ), {@code Ctrl+C} (ghé tâm 5 biome), {@code 1..9} & cuộn chuột.
 * - Đào block theo độ cứng ({@code updateMiningProgress}), đặt block, đánh cận chiến và sử dụng vật phẩm.
 * - Hit-testing cho {@link com.voxelgame.client.gui.PauseScreen} và {@link InventoryScreen}.
 */
public class GameInputController implements InputProcessor {

    /**
     * Hợp đồng cầu nối giữa {@link GameInputController} và lớp điều phối ứng dụng ({@code VoxelGameApp}),
     * giúp đọc/ghi trạng thái sống mà không tạo vòng phụ thuộc chặt.
     */
    public interface Host {
        World getWorld();
        Player getPlayer();
        Camera getCamera();
        AudioManager getAudioManager();
        UIRenderer getUiRenderer();
        InventoryScreen getInventoryScreen();
        CreativeInventoryScreen getCreativeInventoryScreen();
        DebugOverlayRenderer getDebugOverlay();
        ItemUseHandler getItemUseHandler();
        ParticleManager getParticleManager();
        WeatherManager getWeather();
        WorldTime getWorldTime();
        boolean isPaused();
        void setPaused(boolean paused);
    }

    /** Thứ tự ghé thăm 5 biome theo trục X từ tây sang đông khi bấm Ctrl+C. */
    private static final BiomeType[] BIOME_TOUR = {
            BiomeType.SNOWY_PLAINS, BiomeType.FOREST, BiomeType.PLAINS, BiomeType.FLOWER_FOREST, BiomeType.DESERT
    };

    /** Độ nhạy chuột khi xoay Camera (giữ nguyên giá trị chuẩn 0.12f). */
    private static final float MOUSE_SENSITIVITY = 0.12f;
    /** Tầm với tối đa của tia bắn Raycast khi đào/đặt Block (5 ô voxel). */
    public static final float RAYCAST_REACH = 5.0f;
    /** Tầm với cơ bản dành cho đòn cận chiến tay không. */
    private static final float MELEE_REACH = 3.0f;
    /** Nhịp hồi ngắn (giây) giữa hai lần phá khối tức thì liên tiếp khi giữ chuột trái ở Creative. */
    private static final float CREATIVE_BREAK_COOLDOWN = 0.18f;

    /** Cầu nối tới các hệ thống con của ứng dụng. */
    private final Host host;

    /** Trạng thái xoay vòng biome cho phím tắt Ctrl+C. */
    private int nextBiomeIndex;

    /** Trạng thái phím Ctrl trái/phải theo thứ tự sự kiện hàng đợi của libGDX. */
    private boolean leftControlDown;
    private boolean rightControlDown;

    /** Tọa độ chuột hiện tại (dùng cho Hit-Testing nút bấm trên PauseScreen và InventoryScreen). */
    private float currentMouseX;
    private float currentMouseY;

    /** Cờ bỏ qua delta chuột ở khung hình đầu tiên sau khi khóa lại con trỏ để chống giật Camera. */
    private boolean skipNextMouseDelta = true;

    /** Cờ đánh dấu người dùng đang kéo thanh trượt âm lượng trên PauseScreen. */
    private boolean isDraggingVolumeSlider = false;

    /** Trạng thái giữ chuột trái và tích lũy tiến trình đào block theo độ cứng. */
    private boolean isLeftMouseDown = false;
    private int miningTargetX = Integer.MIN_VALUE;
    private int miningTargetY = Integer.MIN_VALUE;
    private int miningTargetZ = Integer.MIN_VALUE;
    private float miningElapsedTime = 0.0f;
    private float nextMiningSoundTime;
    private float creativeBreakCooldown;

    /** Các bộ đệm tái sử dụng cho Raycast và sinh vật phẩm rơi (zero-GC). */
    private final Vector3 eyePosition = new Vector3();
    private final Vector3 aimDirection = new Vector3();
    private final Vector3 dropPosBuffer = new Vector3();
    private final Raycast.HitResult placementHit = Raycast.HitResult.miss();
    private final Raycast.HitResult occluderHit = Raycast.HitResult.miss();
    private final Raycast.EntityHitResult entityHit = new Raycast.EntityHitResult();

    /** Khởi tạo bộ điều khiển đầu vào gắn với cầu nối {@link Host}. */
    public GameInputController(Host host) {
        this.host = host;
    }

    /** Trả về tọa độ X chuột gần nhất (pixel màn hình). */
    public float getCurrentMouseX() {
        return currentMouseX;
    }

    /** Trả về tọa độ Y chuột gần nhất (pixel màn hình). */
    public float getCurrentMouseY() {
        return currentMouseY;
    }

    /** Đánh dấu bỏ qua delta chuột ở khung hình kế tiếp (khi vừa khởi chạy hoặc khóa lại chuột). */
    public void skipNextMouseDelta() {
        this.skipNextMouseDelta = true;
    }

    /** Kiểm tra người chơi có đang giữ chuột trái và đào một mục tiêu hợp lệ hay không. */
    public boolean isActivelyMining() {
        return isLeftMouseDown && miningTargetX != Integer.MIN_VALUE;
    }

    /** Kiểm tra giao diện túi đồ (Survival 36 ô hoặc Kho Creative) hiện có đang mở hay không. */
    public boolean isInventoryOpen() {
        InventoryScreen screen = host.getInventoryScreen();
        CreativeInventoryScreen creativeScreen = host.getCreativeInventoryScreen();
        return (screen != null && screen.isOpen())
                || (creativeScreen != null && creativeScreen.isOpen());
    }

    /**
     * Xử lý xoay Camera bằng delta chuột mỗi khung hình.
     * Bỏ qua khung hình đầu tiên sau khi khóa chuột nhờ cờ {@link #skipNextMouseDelta}.
     */
    public void processMouseLook() {
        if (skipNextMouseDelta) {
            skipNextMouseDelta = false;
            return;
        }
        float deltaX = Gdx.input.getDeltaX();
        float deltaY = Gdx.input.getDeltaY();
        Camera camera = host.getCamera();
        if (camera != null) {
            camera.rotate(deltaX * MOUSE_SENSITIVITY, -deltaY * MOUSE_SENSITIVITY);
        }
    }

    /** Bật/tắt túi đồ tương ứng với chế độ chơi hiện tại ({@code CreativeInventoryScreen} hoặc {@code InventoryScreen}). */
    public void toggleInventory() {
        Player player = host.getPlayer();
        if (player == null) {
            return;
        }
        if (isInventoryOpen()) {
            closeInventory();
            return;
        }
        boolean useCreative = player.getGameMode().usesCreativeInventory();
        CreativeInventoryScreen creativeScreen = host.getCreativeInventoryScreen();
        InventoryScreen inventoryScreen = host.getInventoryScreen();
        if (useCreative && creativeScreen != null) {
            creativeScreen.open();
        } else if (inventoryScreen != null) {
            inventoryScreen.open();
        } else {
            return;
        }
        isLeftMouseDown = false;
        resetMiningProgress();
        ItemUseHandler itemUseHandler = host.getItemUseHandler();
        if (itemUseHandler != null) {
            itemUseHandler.onHotbarSlotChanged();
        }
        if (Gdx.input != null) {
            Gdx.input.setCursorCatched(false);
        }
        skipNextMouseDelta = true;
    }

    /** Đóng mọi màn hình túi đồ đang mở (Survival hoặc Creative) và khóa lại con trỏ chuột. */
    public void closeInventory() {
        InventoryScreen inventoryScreen = host.getInventoryScreen();
        CreativeInventoryScreen creativeScreen = host.getCreativeInventoryScreen();
        boolean closedAny = false;
        if (inventoryScreen != null && inventoryScreen.isOpen()) {
            inventoryScreen.close(host.getPlayer(), host.getWorld());
            closedAny = true;
        }
        if (creativeScreen != null && creativeScreen.isOpen()) {
            creativeScreen.close();
            closedAny = true;
        }
        if (!closedAny) {
            return;
        }
        isLeftMouseDown = false;
        resetMiningProgress();
        if (Gdx.input != null) {
            Gdx.input.setCursorCatched(true);
        }
        skipNextMouseDelta = true;
    }

    /** Chuyển game sang trạng thái Tạm dừng, mở PauseScreen và mở khóa con trỏ chuột. */
    public void pauseGame() {
        if (isInventoryOpen()) {
            host.getInventoryScreen().close(host.getPlayer(), host.getWorld());
        }
        host.setPaused(true);
        UIRenderer uiRenderer = host.getUiRenderer();
        if (uiRenderer != null) {
            uiRenderer.getPauseScreen().open();
        }
        isLeftMouseDown = false;
        isDraggingVolumeSlider = false;
        resetMiningProgress();
        ItemUseHandler itemUseHandler = host.getItemUseHandler();
        if (itemUseHandler != null) {
            itemUseHandler.onHotbarSlotChanged();
        }
        AudioManager audioManager = host.getAudioManager();
        if (audioManager != null) {
            audioManager.setUnderwater(false);
            audioManager.setRainPaused(true);
        }
        Gdx.input.setCursorCatched(false);
    }

    /** Tiếp tục game từ trạng thái Tạm dừng, đóng PauseScreen và khóa lại con trỏ chuột. */
    public void resumeGame() {
        host.setPaused(false);
        UIRenderer uiRenderer = host.getUiRenderer();
        if (uiRenderer != null) {
            uiRenderer.getPauseScreen().close();
        }
        isDraggingVolumeSlider = false;
        AudioManager audioManager = host.getAudioManager();
        if (audioManager != null) {
            audioManager.setRainPaused(false);
        }
        Gdx.input.setCursorCatched(true);
        skipNextMouseDelta = true;
    }

    /**
     * Cập nhật tiến trình đào block khi đang giữ chuột trái:
     * - Ở Creative ({@link GameMode#breaksInstantly()}): phá tức thì mọi khối hợp lệ (gồm Bedrock)
     *   không rơi vật phẩm với nhịp hồi ngắn {@link #CREATIVE_BREAK_COOLDOWN}.
     * - Ở Survival: tính thời gian theo độ cứng nhân {@link Item#getMiningSpeedMultiplier(Block)}.
     */
    public float updateMiningProgress(Raycast.HitResult currentHit, float deltaTime) {
        if (creativeBreakCooldown > 0.0f) {
            creativeBreakCooldown = Math.max(0.0f, creativeBreakCooldown - deltaTime);
        }
        if (!isLeftMouseDown || currentHit == null || !currentHit.isHit()) {
            resetMiningProgress();
            return 0.0f;
        }

        Player player = host.getPlayer();
        GameMode mode = player != null ? player.getGameMode() : null;
        Block targetBlock = currentHit.getBlock();
        boolean canBreak = mode != null ? mode.canBreakBlock(targetBlock) : targetBlock.isBreakable();
        if (!canBreak) {
            resetMiningProgress();
            return 0.0f;
        }

        int hitX = currentHit.getBlockX();
        int hitY = currentHit.getBlockY();
        int hitZ = currentHit.getBlockZ();

        if (mode != null && mode.breaksInstantly()) {
            if (creativeBreakCooldown <= 0.0f) {
                World world = host.getWorld();
                if (world != null) {
                    boolean broken = mode.dropsBlockItems()
                            ? breakWithDrop(world, hitX, hitY, hitZ)
                            : world.breakBlockWithoutDrop(hitX, hitY, hitZ);
                    if (broken) {
                        ParticleManager particleManager = host.getParticleManager();
                        if (particleManager != null) {
                            particleManager.spawnBlockBreak(hitX, hitY, hitZ, targetBlock, 20);
                        }
                        if (player != null) {
                            player.triggerSwing();
                        }
                    }
                }
                creativeBreakCooldown = CREATIVE_BREAK_COOLDOWN;
            }
            resetMiningProgress();
            return 0.0f;
        }

        if (hitX != miningTargetX || hitY != miningTargetY || hitZ != miningTargetZ) {
            miningTargetX = hitX;
            miningTargetY = hitY;
            miningTargetZ = hitZ;
            miningElapsedTime = 0.0f;
            nextMiningSoundTime = 0.0f;
        }

        Item heldItem = (player != null && player.getHotbar().getSelectedCount() > 0
                && player.getHotbar().getSelectedItem() != null)
                ? player.getHotbar().getSelectedItem() : Item.NONE;
        float speedMultiplier = heldItem.getMiningSpeedMultiplier(targetBlock);
        miningElapsedTime += deltaTime * speedMultiplier;
        float requiredTime = targetBlock.getHardness();

        if (miningElapsedTime >= requiredTime) {
            ParticleManager particleManager = host.getParticleManager();
            if (particleManager != null) {
                particleManager.spawnBlockBreak(miningTargetX, miningTargetY, miningTargetZ, targetBlock, 20);
            }
            World world = host.getWorld();
            if (world != null) {
                world.breakBlockAndSpawnDrop(miningTargetX, miningTargetY, miningTargetZ);
            }
            resetMiningProgress();
            return 0.0f;
        }

        AudioManager audioManager = host.getAudioManager();
        if (audioManager != null && requiredTime > 0.25f && miningElapsedTime >= nextMiningSoundTime) {
            audioManager.playMining(targetBlock);
            nextMiningSoundTime += 0.25f;
        }

        return Math.min(1.0f, miningElapsedTime / requiredTime);
    }

    /** Tiện ích gọi phá khối kèm rơi vật phẩm và trả về {@code true}. */
    private static boolean breakWithDrop(World world, int x, int y, int z) {
        world.breakBlockAndSpawnDrop(x, y, z);
        return true;
    }

    /** Đặt lại trạng thái đào block về mặc định. */
    public void resetMiningProgress() {
        miningTargetX = Integer.MIN_VALUE;
        miningTargetY = Integer.MIN_VALUE;
        miningTargetZ = Integer.MIN_VALUE;
        miningElapsedTime = 0.0f;
        nextMiningSoundTime = 0.0f;
    }

    /** Xử lý click chuột trên Pause Menu (nút Resume, nút -/+, thanh trượt âm lượng). */
    private void handlePauseMenuMouseClick(float screenX, float screenY, boolean pressed) {
        UIRenderer uiRenderer = host.getUiRenderer();
        if (uiRenderer == null) {
            return;
        }
        int screenWidth = Gdx.graphics.getWidth();
        int screenHeight = Gdx.graphics.getHeight();

        if (!pressed) {
            isDraggingVolumeSlider = false;
            return;
        }

        AudioManager audioManager = host.getAudioManager();
        if (uiRenderer.isInsideResumeButton(screenX, screenY, screenWidth, screenHeight)) {
            if (audioManager != null) {
                audioManager.playEffect(AudioManager.Effect.CLICK, 0.36f);
            }
            resumeGame();
            return;
        }
        if (uiRenderer.isInsideVolumeMinus(screenX, screenY, screenWidth, screenHeight)) {
            if (audioManager != null) {
                audioManager.playEffect(AudioManager.Effect.CLICK, 0.36f);
                audioManager.changeVolume(-0.10f);
            }
            return;
        }
        if (uiRenderer.isInsideVolumePlus(screenX, screenY, screenWidth, screenHeight)) {
            if (audioManager != null) {
                audioManager.playEffect(AudioManager.Effect.CLICK, 0.36f);
                audioManager.changeVolume(0.10f);
            }
            return;
        }
        float sliderVal = uiRenderer.getSliderVolumeAtCursor(screenX, screenY, screenWidth, screenHeight);
        if (sliderVal >= 0.0f && audioManager != null) {
            isDraggingVolumeSlider = true;
            audioManager.setVolume(sliderVal);
        }
    }

    /** Chọn thực thể từ mắt người chơi và giới hạn tia tại hộp va chạm của địa hình. */
    private Raycast.EntityHitResult aimAtEntity(float reach) {
        Camera camera = host.getCamera();
        World world = host.getWorld();
        Player player = host.getPlayer();
        camera.copyPosition(eyePosition);
        camera.copyFront(aimDirection);
        Raycast.castOccluder(world, eyePosition, aimDirection, reach, occluderHit);
        return Raycast.castEntity(world, eyePosition, aimDirection, reach, occluderHit.getDistance(),
                player, entityHit);
    }

    /** Xử lý nhấn chuột trái: ưu tiên đòn cận chiến (kể cả Jab tầm 4.2f của Iron Spear), ngược lại đào block. */
    private void handleLeftClick() {
        World world = host.getWorld();
        Camera camera = host.getCamera();
        Player player = host.getPlayer();
        if (world == null || camera == null || player == null) {
            return;
        }
        ItemUseHandler itemUseHandler = host.getItemUseHandler();
        if (itemUseHandler != null) {
            boolean hitMob = itemUseHandler.onPrimaryMelee(world, player, camera);
            isLeftMouseDown = !hitMob;
            if (hitMob) {
                resetMiningProgress();
            }
            return;
        }
        Raycast.EntityHitResult hit = aimAtEntity(MELEE_REACH);
        isLeftMouseDown = !hit.isHit();
        if (hit.isHit()) {
            resetMiningProgress();
            player.attack(world, hit.getEntity(), aimDirection);
        }
    }

    /** Xử lý nhấn chuột phải: tương tác thực thể, uống Milk Bucket dự phòng hoặc đặt block từ Hotbar. */
    private void handleRightClickPlaceBlock() {
        World world = host.getWorld();
        Camera camera = host.getCamera();
        Player player = host.getPlayer();
        if (world == null || camera == null || player == null) {
            return;
        }

        Raycast.EntityHitResult target = aimAtEntity(RAYCAST_REACH);
        if (target.isHit() && target.getEntity().onPlayerInteract(world, player)) {
            return;
        }

        Hotbar hotbar = player.getHotbar();
        Item selectedItem = hotbar.getSelectedItem();

        if (selectedItem == Item.MILK_BUCKET && hotbar.getSelectedCount() > 0) {
            player.clearStatusEffects();
            if (player.getGameMode().consumesItems()) {
                hotbar.consumeSelectedItemStack();
                if (!hotbar.addItem(Item.BUCKET, 1)) {
                    player.copyPosition(dropPosBuffer);
                    world.spawnDroppedItem(new ItemEntity(dropPosBuffer.x,
                            dropPosBuffer.y + 1.0f, dropPosBuffer.z, Item.BUCKET));
                }
            }
            AudioManager audioManager = host.getAudioManager();
            if (audioManager != null) {
                audioManager.playEffect(AudioManager.Effect.PICKUP, 0.35f);
            }
            return;
        }

        Block selectedBlock = hotbar.getSelectedBlock();
        if (selectedBlock == Block.AIR || hotbar.getSelectedCount() <= 0) {
            return;
        }

        Raycast.HitResult hit = Raycast.cast(world, camera.copyPosition(eyePosition), camera.copyFront(aimDirection),
                RAYCAST_REACH, placementHit);
        if (!hit.isHit()) {
            return;
        }

        int x = hit.getBlockX();
        int y = hit.getBlockY();
        int z = hit.getBlockZ();
        if (selectedBlock == Block.SNOW_LAYER && hit.getBlock() == Block.SNOW_LAYER
                && world.getBlockState(x, y, z) < 7) {
            if (world.tryStackSnow(x, y, z, player)) {
                finishBlockPlacement(hotbar, selectedBlock);
            }
            return;
        }

        int placeState = LeafDecaySystem.isLeaf(selectedBlock) ? LeafDecaySystem.PERSISTENT_LEAF_STATE : 0;
        if (world.tryPlaceBlock(x, y, z, selectedBlock, placeState, player)
                || world.tryPlaceBlock(hit.getPrevBlockX(), hit.getPrevBlockY(), hit.getPrevBlockZ(),
                selectedBlock, placeState, player)) {
            finishBlockPlacement(hotbar, selectedBlock);
        }
    }

    /** Trừ vật phẩm trên Hotbar (nếu chế độ tiêu hao đồ) và phát SFX vật liệu sau khi đặt block thành công. */
    private void finishBlockPlacement(Hotbar hotbar, Block placedBlock) {
        Player player = host.getPlayer();
        if (player == null || player.getGameMode().consumesItems()) {
            hotbar.consumeSelectedItem();
        }
        AudioManager audioManager = host.getAudioManager();
        if (audioManager != null) {
            audioManager.playPlace(placedBlock);
        }
    }

    /**
     * Kiểm tra phím Ctrl trái hoặc phải có đang được giữ hay không, kết hợp cả cờ sự kiện hàng đợi
     * (cho kiểm thử headless) lẫn trạng thái trực tiếp từ {@code Gdx.input} (chống lệch trạng thái khi đổi cửa sổ).
     */
    private boolean isControlDown() {
        return leftControlDown
                || rightControlDown
                || (Gdx.input != null && (Gdx.input.isKeyPressed(Input.Keys.CONTROL_LEFT)
                || Gdx.input.isKeyPressed(Input.Keys.CONTROL_RIGHT)));
    }

    /**
     * Chuyển đổi chế độ chơi ({@code Creative ↔ Survival}) khi bấm phím {@code F2},
     * đồng thời đóng màn hình túi đồ đang mở, đặt lại tiến trình đào và hủy phiên dùng vật phẩm.
     */
    private void toggleGameMode(Player player) {
        if (isInventoryOpen()) {
            closeInventory();
        }
        GameMode nextMode = player.toggleGameMode();
        isLeftMouseDown = false;
        creativeBreakCooldown = 0.0f;
        resetMiningProgress();
        ItemUseHandler itemUseHandler = host.getItemUseHandler();
        if (itemUseHandler != null) {
            itemUseHandler.onHotbarSlotChanged();
        }
        UIRenderer uiRenderer = host.getUiRenderer();
        if (uiRenderer != null) {
            uiRenderer.showGameModeToast(nextMode);
        }
    }

    /** Dịch chuyển người chơi lần lượt qua tâm 5 biome theo thứ tự từ tây sang đông. */
    private void teleportToNextBiome(Player player, World world) {
        BiomeType biome = BIOME_TOUR[nextBiomeIndex];
        nextBiomeIndex = (nextBiomeIndex + 1) % BIOME_TOUR.length;
        if (player.teleportToBiome(world, biome)) {
            resetMiningProgress();
        }
    }

    private static int getHotbarSlotFromKeycode(int keycode) {
        if (keycode >= Input.Keys.NUM_1 && keycode <= Input.Keys.NUM_9) {
            return keycode - Input.Keys.NUM_1;
        }
        return -1;
    }

    // =========================================================================
    // TRIỂN KHAI GIAO DIỆN InputProcessor
    // =========================================================================

    @Override
    public boolean keyDown(int keycode) {
        Player player = host.getPlayer();
        if (keycode == Input.Keys.F1 && player != null && player.getGameMode().canUseTerrainTools()) {
            player.cycleTerrainSpeed();
            return true;
        }

        if (keycode == Input.Keys.CONTROL_LEFT) {
            leftControlDown = true;
            return false;
        }
        if (keycode == Input.Keys.CONTROL_RIGHT) {
            rightControlDown = true;
            return false;
        }

        if (keycode == Input.Keys.ESCAPE) {
            if (isInventoryOpen()) {
                closeInventory();
                return true;
            }
            if (!host.isPaused()) {
                pauseGame();
            } else {
                Gdx.app.exit();
            }
            return true;
        }

        if (!host.isPaused() && player != null) {
            if (keycode == Input.Keys.F2) {
                toggleGameMode(player);
                return true;
            }
            if (keycode == Input.Keys.C && isControlDown()
                    && player.getGameMode().canUseTerrainTools()) {
                teleportToNextBiome(player, host.getWorld());
                return true;
            }
            switch (keycode) {
                case Input.Keys.F6 -> {
                    WeatherManager weather = host.getWeather();
                    if (weather != null) {
                        weather.toggle();
                    }
                    return true;
                }
                case Input.Keys.F7 -> {
                    WorldTime worldTime = host.getWorldTime();
                    if (worldTime != null) {
                        worldTime.nextMilestone();
                    }
                    return true;
                }
                case Input.Keys.F8 -> {
                    WorldTime worldTime = host.getWorldTime();
                    if (worldTime != null) {
                        worldTime.toggleFastForward();
                    }
                    return true;
                }
                default -> {
                }
            }
            if (keycode == Input.Keys.F5 && !isInventoryOpen()) {
                player.cycleCameraMode();
                return true;
            }
            if (keycode == Input.Keys.E) {
                toggleInventory();
                return true;
            }
            World world = host.getWorld();
            if (keycode == Input.Keys.Q && world != null && !isInventoryOpen()) {
                player.dropSelectedItem(world, isControlDown());
                return true;
            }
            DebugOverlayRenderer debugOverlay = host.getDebugOverlay();
            if (keycode == Input.Keys.F3 && debugOverlay != null) {
                debugOverlay.toggle();
                return true;
            }
            int slotIndex = getHotbarSlotFromKeycode(keycode);
            if (slotIndex >= 0 && !isInventoryOpen()) {
                int previousSlot = player.getHotbar().getSelectedSlot();
                player.getHotbar().selectSlot(slotIndex);
                ItemUseHandler itemUseHandler = host.getItemUseHandler();
                if (itemUseHandler != null && player.getHotbar().getSelectedSlot() != previousSlot) {
                    itemUseHandler.onHotbarSlotChanged();
                }
                return true;
            }
        }
        return false;
    }

    @Override
    public boolean keyUp(int keycode) {
        if (keycode == Input.Keys.CONTROL_LEFT) {
            leftControlDown = false;
        } else if (keycode == Input.Keys.CONTROL_RIGHT) {
            rightControlDown = false;
        }
        return false;
    }

    @Override
    public boolean keyTyped(char character) {
        return false;
    }

    @Override
    public boolean touchDown(int screenX, int screenY, int pointer, int button) {
        currentMouseX = screenX;
        currentMouseY = screenY;

        if (host.isPaused()) {
            if (button == Input.Buttons.LEFT) {
                handlePauseMenuMouseClick(screenX, screenY, true);
            }
            return true;
        }

        Player player = host.getPlayer();
        if (isInventoryOpen() && player != null) {
            boolean shiftDown = Gdx.input != null && (Gdx.input.isKeyPressed(Input.Keys.SHIFT_LEFT)
                    || Gdx.input.isKeyPressed(Input.Keys.SHIFT_RIGHT));
            CreativeInventoryScreen creativeScreen = host.getCreativeInventoryScreen();
            if (creativeScreen != null && creativeScreen.isOpen()) {
                creativeScreen.handleClick(player.getInventory(), screenX, screenY,
                        Gdx.graphics.getWidth(), Gdx.graphics.getHeight(), button, shiftDown);
                return true;
            }
            host.getInventoryScreen().handleClick(player.getInventory(), screenX, screenY,
                    Gdx.graphics.getWidth(), Gdx.graphics.getHeight(), button, shiftDown);
            return true;
        }

        if (button == Input.Buttons.LEFT) {
            if (player != null) {
                player.triggerSwing();
            }
            handleLeftClick();
        } else if (button == Input.Buttons.RIGHT) {
            ItemUseHandler itemUseHandler = host.getItemUseHandler();
            if (itemUseHandler != null && itemUseHandler.onSecondaryPress(host.getWorld(), player, host.getCamera())) {
                return true;
            }
            handleRightClickPlaceBlock();
        }
        return true;
    }

    @Override
    public boolean touchUp(int screenX, int screenY, int pointer, int button) {
        currentMouseX = screenX;
        currentMouseY = screenY;

        if (host.isPaused()) {
            if (button == Input.Buttons.LEFT) {
                handlePauseMenuMouseClick(screenX, screenY, false);
            }
            return true;
        }

        if (isInventoryOpen()) {
            isLeftMouseDown = false;
            resetMiningProgress();
            return true;
        }

        if (button == Input.Buttons.LEFT) {
            isLeftMouseDown = false;
            creativeBreakCooldown = 0.0f;
            resetMiningProgress();
        }
        ItemUseHandler itemUseHandler = host.getItemUseHandler();
        if (button == Input.Buttons.RIGHT && itemUseHandler != null) {
            itemUseHandler.onSecondaryRelease(host.getWorld(), host.getPlayer(), host.getCamera());
        }
        return true;
    }

    @Override
    public boolean touchDragged(int screenX, int screenY, int pointer) {
        currentMouseX = screenX;
        currentMouseY = screenY;

        UIRenderer uiRenderer = host.getUiRenderer();
        AudioManager audioManager = host.getAudioManager();
        if (host.isPaused() && isDraggingVolumeSlider && uiRenderer != null && audioManager != null) {
            int screenWidth = Gdx.graphics.getWidth();
            int screenHeight = Gdx.graphics.getHeight();
            float newVol = uiRenderer.getSliderVolumeAtCursor(screenX, screenY, screenWidth, screenHeight);
            if (newVol >= 0.0f) {
                audioManager.setVolume(newVol);
            }
        }
        return true;
    }

    @Override
    public boolean mouseMoved(int screenX, int screenY) {
        currentMouseX = screenX;
        currentMouseY = screenY;
        return true;
    }

    @Override
    public boolean scrolled(float amountX, float amountY) {
        if (!host.isPaused()) {
            CreativeInventoryScreen creativeScreen = host.getCreativeInventoryScreen();
            if (creativeScreen != null && creativeScreen.isOpen()) {
                creativeScreen.scroll(amountY);
                return true;
            }
            Player player = host.getPlayer();
            if (!isInventoryOpen() && player != null) {
                int previousSlot = player.getHotbar().getSelectedSlot();
                player.getHotbar().scroll(-amountY);
                ItemUseHandler itemUseHandler = host.getItemUseHandler();
                if (itemUseHandler != null && player.getHotbar().getSelectedSlot() != previousSlot) {
                    itemUseHandler.onHotbarSlotChanged();
                }
            }
        }
        return true;
    }

    @Override
    public boolean touchCancelled(int screenX, int screenY, int pointer, int button) {
        return touchUp(screenX, screenY, pointer, button);
    }
}

package com.voxelgame.client.model;

import com.voxelgame.world.entity.LivingEntity;

/** Mẫu phân khớp với một hay nhiều phần gốc, dùng chung giữa các cá thể. */
public abstract class MobModel {
    /** Dư địa pixel cho dịch gốc của nhảy, đứng hai chân và ngồi trong các mẫu hiện có. */
    private static final float ANIMATION_MARGIN = 16f;
    private final ModelPart[] roots;
    private final float renderRadius;

    /** Khóa cấu trúc các phần gốc khi tạo mẫu, chưa sử dụng OpenGL. */
    protected MobModel(ModelPart... roots) {
        this.roots = roots.clone();
        float maxReach = 0f;
        for (ModelPart root : this.roots) {
            maxReach = Math.max(maxReach, root.maxReach());
        }
        renderRadius = maxReach + ANIMATION_MARGIN;
    }

    /** Bán kính bao mẫu quanh chân theo pixel, gồm cả chuyển động của điểm xoay. */
    public final float renderRadius() {
        return renderRadius;
    }

    /** Kiểm tra tấm ảnh có chứa đầy đủ các mặt của lớp tương ứng. */
    public final boolean fitsLayer(ModelPart.Layer layer, int width, int height) {
        for (ModelPart root : roots) {
            if (!root.fitsLayer(layer, width, height)) {
                return false;
            }
        }
        return true;
    }

    /** Đọc các phần gốc để dựng và vẽ cây mô hình. */
    public final ModelPart[] roots() {
        return roots;
    }

    /** Trả phần đầu có điểm ngậm vật, nếu mẫu có hỗ trợ. */
    public ModelPart heldBlockPart() {
        return null;
    }

    /** Đặt lại mẫu trước khi áp dụng góc khớp của cá thể mới. */
    public final void resetPose() {
        for (ModelPart root : roots) {
            root.resetPose();
        }
    }

    /** Tính tư thế từ nhịp chân theo radian, thời gian tick và góc đầu theo độ. */
    public abstract void setupAnimation(LivingEntity entity, float limbSwing, float limbSwingAmount,
                                        float ageInTicks, float headYaw, float headPitch);
}

package com.voxelgame.client.model;

import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.client.render.entity.MobVisual;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.LivingEntity;

import com.badlogic.gdx.math.MathUtils;

/**
 * Khung khớp chuẩn Minecraft theo từng loài (tỉ lệ texel 1:1).
 * Tọa độ đo bằng pixel (16 pixel = 1 block), với chân trên Y=0 và hướng nhìn trung tính dọc -Z.
 */
public final class MobModels {
    /** Hai vị trí hông sau cần được bù khi thân dựng lên trên hai chân. */
    private static final float BEAR_HIND_HIP_DEPTH = 7f;
    private static final float EQUINE_HIND_HIP_DEPTH = 9f;

    /** Các bộ xương dùng chung, chỉ tạo hình học mô tả trước khi đến lượt vẽ. */
    public static final MobModel ZOMBIE = humanoid(HumanoidKind.ZOMBIE);
    public static final MobModel ZOMBIE_VILLAGER = humanoid(HumanoidKind.VILLAGER);
    public static final MobModel SKELETON = humanoid(HumanoidKind.SKELETON);
    public static final MobModel HUSK = humanoid(HumanoidKind.HUSK);
    public static final MobModel PARCHED = humanoid(HumanoidKind.PARCHED);
    public static final MobModel STRAY = humanoid(HumanoidKind.STRAY);
    public static final MobModel WITCH = humanoid(HumanoidKind.WITCH);
    public static final MobModel CREEPER = creeper();
    public static final MobModel SPIDER = spider();
    public static final MobModel ENDERMAN = enderman();
    public static final MobModel COW = cow();
    public static final MobModel SHEEP = sheep();
    public static final MobModel PIG = pig();
    public static final MobModel POLAR_BEAR = polarBear();
    public static final MobModel GOAT = goat();
    public static final MobModel CHICKEN = chicken();
    public static final MobModel RABBIT = rabbit();
    public static final MobModel WOLF = wolf();
    public static final MobModel FOX = fox();
    public static final MobModel HORSE = equine(false);
    public static final MobModel DONKEY = equine(true);
    public static final MobModel CAMEL = camel();
    public static final MobModel ARROW = arrow();
    public static final MobModel POTION = potion();

    /** Tập khung chỉ được khởi tạo một lần để renderer sở hữu vòng đời mesh dùng chung. */
    private MobModels() {
    }

    /** Lấy mô hình tương ứng với một diện mạo đã đăng ký. */
    public static MobModel model(MobAppearance appearance) {
        return appearance.model();
    }

    /** Dựng hộp khớp đúng 1:1 kích thước hình học và vùng trải UV Minecraft. */
    private static ModelPart skinBox(float x, float y, float z, float dx, float dy, float dz,
                                     int width, int height, int depth, int u, int v, ModelPart... children) {
        return skinBox(x, y, z, dx, dy, dz, width, height, depth, uv(u, v, width, height, depth), children);
    }

    /** Dựng hộp có chiều trải UV chỉ định (chuẩn, nằm ngang hoặc đối xứng gương). */
    private static ModelPart skinBox(float x, float y, float z, float dx, float dy, float dz,
                                     int width, int height, int depth, ModelPart.CuboidUv texture,
                                     ModelPart... children) {
        return new ModelPart(x, y, z, dx, dy, dz, width, height, depth, 0f, texture, children);
    }

    /** Dựng mặt phẳng sprite 2D vẽ cả hai mặt cho cung, giáo và lọ thuốc cầm tay. */
    private static ModelPart flatSprite(float x, float y, float z, float dx, float dy, float dz,
                                        int width, int height, int u, int v, int texW, int texH,
                                        ModelPart... children) {
        ModelPart.CuboidUv spriteUv = new ModelPart.CuboidUv(u, v, texW, texH, 0, ModelPart.UvOrientation.FLAT_SPRITE);
        return new ModelPart(x, y, z, dx, dy, dz, width, height, 0, 0f, spriteUv,
                ModelPart.Shape.FLAT_SPRITE, children).setDoubleSided(true);
    }

    /** Tạo hình trải thẳng cho đầu, chân và các bộ phận không nằm ngang. */
    private static ModelPart.CuboidUv uv(int u, int v, int width, int height, int depth) {
        return new ModelPart.CuboidUv(u, v, width, height, depth, ModelPart.UvOrientation.MINECRAFT);
    }

    /** Tạo bản đối xứng của hình trải dùng chung cho chi trái. */
    private static ModelPart.CuboidUv mirrored(int u, int v, int width, int height, int depth) {
        return new ModelPart.CuboidUv(u, v, width, height, depth, ModelPart.UvOrientation.MIRRORED);
    }

    /** Trải thân nằm ngang từ hộp nguồn có trục dài theo chiều đứng. */
    private static ModelPart.CuboidUv horizontal(int u, int v, int width, int height, int depth) {
        return new ModelPart.CuboidUv(u, v, width, height, depth, ModelPart.UvOrientation.HORIZONTAL);
    }

    /** Dựng vỏ lông, áo hoặc mắt, phồng nhẹ để tránh trùng mặt với lớp nền. */
    private static ModelPart shell(float dx, float dy, float dz, int width, int height, int depth,
                                   ModelPart.CuboidUv texture, float inflate, ModelPart.Layer layer) {
        return new ModelPart(0f, 0f, 0f, dx, dy, dz, width, height, depth, inflate, texture).setLayer(layer);
    }

    /** Tách dữ liệu hoạt ảnh khỏi lớp gameplay, kể cả khi chạy bản xem trước với thực thể thường. */
    private static MobVisualState visualState(LivingEntity entity) {
        return entity instanceof MobVisual visual ? visual.mobVisualState() : null;
    }

    /** Đọc tư thế cơ sở, dùng IDLE khi thực thể xem trước chưa khai báo tư thế. */
    private static MobVisualState.Pose pose(MobVisualState state) {
        return state == null ? MobVisualState.Pose.IDLE : state.pose();
    }

    /** Tính chu kỳ bước bằng radian và trả góc khớp theo độ. */
    private static float gait(float phase, float amount, float amplitude) {
        return (float) Math.cos(phase) * amount * amplitude;
    }

    /** Các kiểu hình người có tỷ lệ và phụ kiện riêng. */
    private enum HumanoidKind {
        ZOMBIE, VILLAGER, HUSK, SKELETON, PARCHED, STRAY, WITCH
    }

    /** Dựng tay chân, đầu và các lớp áo theo bố cục chuẩn Minecraft của từng nhóm hình người. */
    private static MobModel humanoid(HumanoidKind kind) {
        boolean bones = kind == HumanoidKind.SKELETON || kind == HumanoidKind.PARCHED || kind == HumanoidKind.STRAY;
        boolean villager = kind == HumanoidKind.VILLAGER || kind == HumanoidKind.WITCH;
        int limbSize = bones ? 2 : 4;
        int torsoDepth = villager ? 6 : 4;
        ModelPart weapon = switch (kind) {
            case SKELETON, STRAY, PARCHED -> bow();
            case HUSK -> spear();
            case WITCH -> witchPotion();
            default -> null;
        };
        ModelPart head = humanoidHead(kind);
        if (kind == HumanoidKind.WITCH) {
            // Witch dùng cặp tay khoanh liền khối kiểu Villager, nâng lên mũi khi uống thuốc.
            ModelPart crossedArms = witchCrossedArms(weapon);
            ModelPart rightLeg = humanoidLimb(kind, false, 2, 12, limbSize, null);
            ModelPart leftLeg = humanoidLimb(kind, false, -2, 12, limbSize, null);
            ModelPart.CuboidUv bodyUv = uv(16, 20, 8, 12, 6);
            ModelPart coat = shell(-4, 4, -3, 8, 20, 6, uv(0, 38, 8, 20, 6), 0.5f, ModelPart.Layer.BASE);
            ModelPart body = skinBox(0, 0, 0, -4, 12, -3, 8, 12, 6, bodyUv,
                    head, crossedArms, leftLeg, rightLeg, coat);
            return new HumanoidModel(body, head, crossedArms, null, rightLeg, leftLeg, weapon, kind);
        }

        // Trong hệ +Y lên / -Z trước: +X là bên phải của mob (trái màn hình), -X là bên trái của mob.
        ModelPart rightArm = humanoidLimb(kind, true, 5, 22, limbSize, weapon);
        ModelPart leftArm = humanoidLimb(kind, true, -5, 22, limbSize, null);
        ModelPart rightLeg = humanoidLimb(kind, false, 2, 12, limbSize, null);
        ModelPart leftLeg = humanoidLimb(kind, false, -2, 12, limbSize, null);
        ModelPart.CuboidUv bodyUv = uv(16, villager ? 20 : 16, 8, 12, torsoDepth);
        ModelPart coat = switch (kind) {
            case STRAY -> shell(-4, 12, -2, 8, 12, 4, bodyUv, 0.25f, ModelPart.Layer.OVERLAY);
            case PARCHED -> shell(-4, 12, -2, 8, 12, 4, uv(16, 48, 8, 12, 4), 0.25f, ModelPart.Layer.BASE);
            default -> null;
        };
        ModelPart[] parts = coat == null
                ? new ModelPart[]{head, rightArm, leftArm, rightLeg, leftLeg}
                : new ModelPart[]{head, rightArm, leftArm, rightLeg, leftLeg, coat};
        ModelPart body = skinBox(0, 0, 0, -4, 12, -torsoDepth * 0.5f, 8, 12, torsoDepth, bodyUv, parts);
        if (bones) {
            // Lồng ngực xương có lỗ hở alpha ở khe sườn nên vẽ cả hai mặt.
            body.setDoubleSided(true);
        }
        return new HumanoidModel(body, head, rightArm, leftArm, rightLeg, leftLeg, weapon, kind);
    }

    /** Gắn mũ nghiêng 4 tầng, mũi có nốt ruồi hoặc lớp trùm đầu khớp với đúng vùng ảnh nguồn. */
    private static ModelPart humanoidHead(HumanoidKind kind) {
        ModelPart.CuboidUv headUv = uv(0, 0, 8, 8, 8);
        return switch (kind) {
            case WITCH -> {
                ModelPart tip = skinBox(0.75f, 3.5f, 0.75f, -0.5f, 0, -0.5f, 1, 2, 1, 0, 95)
                        .setBaseRotation(-12f, 0f, 6f);
                ModelPart tier2 = skinBox(0.75f, 4, 0.25f, -2, 0, -2, 4, 4, 4, 0, 87, tip)
                        .setBaseRotation(-6f, 0f, 3f);
                ModelPart tier1 = skinBox(0.25f, 2, 0, -3.5f, 0, -3.5f, 7, 4, 7, 0, 76, tier2)
                        .setBaseRotation(-3f, 0f, 1.5f);
                ModelPart brim = skinBox(0, 9, 0, -5, 0, -5, 10, 2, 10, 0, 64, tier1);
                ModelPart mole = skinBox(0.25f, -1.5f, -1.8f, -0.5f, 0, -0.5f, 1, 1, 1, 0, 0);
                ModelPart nose = skinBox(0, 1, -4, -1, -2, -2, 2, 4, 2, 24, 0, mole);
                yield skinBox(0, 24, 0, -4, 0, -4, 8, 10, 8, 0, 0, nose, brim);
            }
            case VILLAGER -> skinBox(0, 24, 0, -4, 0, -4, 8, 10, 8, 0, 0,
                    skinBox(0, 3, -4, -1, -2, -2, 2, 4, 2, 24, 0));
            case STRAY -> skinBox(0, 24, 0, -4, 0, -4, 8, 8, 8, headUv,
                    shell(-4, 0, -4, 8, 8, 8, headUv, 0.25f, ModelPart.Layer.OVERLAY));
            case PARCHED -> skinBox(0, 24, 0, -4, 0, -4, 8, 8, 8, headUv,
                    shell(-4, 0, -4, 8, 8, 8, uv(0, 32, 8, 8, 8), 0.25f, ModelPart.Layer.BASE),
                    shell(-4, 0, -4, 8, 8, 8, uv(32, 0, 8, 8, 8), 0.5f, ModelPart.Layer.BASE));
            default -> skinBox(0, 24, 0, -4, 0, -4, 8, 8, 8, headUv);
        };
    }

    /** Dựng cặp tay khoanh trước ngực chuẩn Villager/Witch cùng vị trí cầm lọ thuốc. */
    private static ModelPart witchCrossedArms(ModelPart potion) {
        ModelPart rightUpper = skinBox(0, 0, 0, 4, -8, -2, 4, 8, 4, uv(44, 22, 4, 8, 4));
        ModelPart leftUpper = skinBox(0, 0, 0, -8, -8, -2, 4, 8, 4, mirrored(44, 22, 4, 8, 4));
        ModelPart forearms = skinBox(0, 0, 0, -4, -8, -2, 8, 4, 4, uv(40, 38, 8, 4, 4));
        return new ModelPart(0, 21, -1, 0, 0, 0, 0, 0, 0, 0f, uv(40, 38, 0, 0, 0),
                rightUpper, leftUpper, forearms, potion).setBaseRotation(43f, 0f, 0f);
    }

    /** Tạo chi chuẩn Minecraft và gắn lớp vải ngoài theo đúng chi (+X là chi phải, -X là chi trái). */
    private static ModelPart humanoidLimb(HumanoidKind kind, boolean arm, int x, int y,
                                          int size, ModelPart weapon) {
        boolean left = x < 0;
        boolean villager = kind == HumanoidKind.VILLAGER || kind == HumanoidKind.WITCH;
        int u = arm ? (villager ? 44 : 40) : 0;
        int v = villager ? 22 : 16;
        float minY = arm ? -10f : -12f;
        float side = -size * 0.5f;
        ModelPart.CuboidUv texture = left ? mirrored(u, v, size, 12, size) : uv(u, v, size, 12, size);
        ModelPart clothes = null;
        if (kind == HumanoidKind.STRAY) {
            ModelPart.CuboidUv clothUv = left ? mirrored(u, v, 4, 12, 4) : uv(u, v, 4, 12, 4);
            clothes = shell(-2f, minY, -2f, 4, 12, 4, clothUv, 0.25f, ModelPart.Layer.OVERLAY);
        } else if (kind == HumanoidKind.PARCHED) {
            if (arm && left) {
                texture = uv(56, 16, 2, 12, 2);
            }
            ModelPart.CuboidUv clothUv;
            if (arm) {
                clothUv = left ? uv(40, 48, 4, 12, 4) : uv(40, 32, 4, 12, 4);
            } else {
                clothUv = left ? mirrored(0, 48, 4, 12, 4) : uv(0, 48, 4, 12, 4);
            }
            clothes = shell(-2f, minY, -2f, 4, 12, 4, clothUv, 0.25f, ModelPart.Layer.BASE);
        }
        ModelPart[] attachments;
        if (weapon != null && clothes != null) {
            attachments = new ModelPart[]{weapon, clothes};
        } else if (weapon != null || clothes != null) {
            attachments = new ModelPart[]{weapon != null ? weapon : clothes};
        } else {
            attachments = new ModelPart[0];
        }
        float minX = arm && size == 4 ? side - Math.signum(x) : side;
        return skinBox(x, y, 0, minX, minY, side, size, 12, size, texture, attachments);
    }

    /** Bốn hình cung 16×16 chuẩn Minecraft dùng cùng điểm cầm ở tay phải. */
    private static ModelPart bow() {
        ModelPart[] frames = new ModelPart[4];
        for (int i = 0; i < frames.length; i++) {
            frames[i] = flatSprite(0, 0, 0, -7, -7, 0, 14, 14, i * 32, 64, 16, 16)
                    .setLayer(ModelPart.Layer.EQUIPMENT);
        }
        return new ModelPart(0, -9, -1, 0, 0, 0, 0, 0, 0, 0f, uv(0, 64, 0, 0, 0), frames)
                .setLayer(ModelPart.Layer.EQUIPMENT);
    }

    /** Giáo sắt chuẩn Minecraft lấy từ sprite 16×16 trên tấm trang bị held.png. */
    private static ModelPart spear() {
