    /** Chia sẻ nhịp bốn chân và chỉ điều chỉnh khớp theo những tư thế từng loài hỗ trợ. */
    private static final class QuadrupedModel extends MobModel {
        private final ModelPart body;
        private final ModelPart head;
        private final ModelPart tail;
        private final ModelPart[] legs;
        private final AnimalKind kind;

        private QuadrupedModel(ModelPart body, ModelPart head, ModelPart tail, ModelPart[] legs, AnimalKind kind) {
            super(body);
            this.body = body;
            this.head = head;
            this.tail = tail;
            this.legs = legs;
            this.kind = kind;
        }

        /** Khối ngậm theo khớp đầu khi cáo nhìn hoặc cuộn mình ngủ. */
        @Override
        public ModelPart heldBlockPart() {
            return kind == AnimalKind.FOX ? head : null;
        }

        /** Hòa chuyển động nhìn, bước, đuôi và tư thế riêng của các loài bốn chân. */
        @Override
        public void setupAnimation(LivingEntity entity, float limbSwing, float limbSwingAmount,
                                   float ageInTicks, float headYaw, float headPitch) {
            MobVisualState state = visualState(entity);
            MobVisualState.Pose pose = pose(state);
            float amount = state == null ? 0 : state.poseAmount();
            if (state != null && kind == AnimalKind.FOX && state.appearance() == MobAppearance.SNOW_FOX_SLEEP) {
                pose = MobVisualState.Pose.SLEEP;
                amount = 1;
            }
            if (state != null && kind == AnimalKind.WOLF && state.appearance() == MobAppearance.WOLF_SNOWY_ANGRY
                    && pose == MobVisualState.Pose.IDLE) {
                pose = MobVisualState.Pose.ANGRY;
                amount = 1;
            }
            walk(legs, gait(limbSwing, limbSwingAmount, 39));
            float baseHeadX = switch (kind) {
                case GOAT -> -55f;
                case EQUINE -> -30f;
                default -> 0f;
            };
            head.setRotation(baseHeadX + headPitch, headYaw, 0);
            if (tail != null) {
                float baseTailX = switch (kind) {
                    case WOLF -> -45f;
                    case FOX -> 8f;
                    case EQUINE -> 30f;
                    default -> 0f;
                };
                tail.setRotation(baseTailX, gait(limbSwing + ageInTicks * 0.06f, limbSwingAmount, 19), 0);
            }
            switch (pose) {
                case GRAZE -> head.setRotation(baseHeadX - 55 * amount, headYaw * 0.2f, 0);
                case RAM -> {
                    if (kind == AnimalKind.GOAT) {
                        head.setRotation(-55f - 18 * amount, 0, 0);
                        body.setRotation(-5 * amount, 0, 0);
                    }
                }
                case REAR -> {
                    if (kind == AnimalKind.BEAR || kind == AnimalKind.EQUINE) {
                        rear(amount, headYaw, headPitch);
                    }
                }
                case HOP -> {
                    if (kind == AnimalKind.RABBIT) {
                        body.setTranslation(0, amount * 2.5f, 0);
                        body.setRotation(12 * amount, 0, 0);
                        walk(legs, 0);
                        legs[0].setRotation(52 * amount, 0, 0);
                        legs[1].setRotation(52 * amount, 0, 0);
                        legs[2].setRotation(-36 * amount, 0, 0);
                        legs[3].setRotation(-36 * amount, 0, 0);
                    } else if (kind == AnimalKind.GOAT) {
                        if (entity.isOnGround()) {
                            body.setTranslation(0, -1.8f * amount, 0);
                            head.setRotation(-55f - 14f * amount, headYaw, 0);
                            foldLegs(24f * amount, -32f * amount);
                        } else {
                            body.setRotation(12f * amount, 0, 0);
                            foldLegs(43f * amount, -38f * amount);
                        }
                    }
                }
                case TILT_HEAD -> {
                    if (kind == AnimalKind.WOLF) {
                        head.setRotation(headPitch, headYaw, 32 * amount);
                    }
                }
                case SHAKE -> {
                    if (kind == AnimalKind.WOLF) {
                        float roll = MathUtils.sin(ageInTicks * 1.9f) * 18f * amount;
                        body.setRotation(0, 0, roll);
                        head.setRotation(headPitch, headYaw, -roll * 1.4f);
                        tail.setRotation(-45f, 0, roll);
                    }
                }
                case ANGRY -> {
                    if (kind == AnimalKind.WOLF) {
                        head.setRotation(headPitch - 12 * amount, headYaw, 0);
                        tail.setRotation(-45f - 25f * amount, 0, 0);
                    }
                }
                case POUNCE -> {
                    if (kind == AnimalKind.FOX) {
                        body.setRotation(27 * amount, 0, 0);
                        body.setTranslation(0, 2 * amount, 0);
                        foldLegs(59 * amount, -63 * amount);
                        tail.setRotation(-34 * amount, 0, 0);
                    }
                }
                case CROUCH -> {
                    if (kind == AnimalKind.FOX) {
                        body.setTranslation(0, -2 * amount, 0);
                        foldLegs(42 * amount, -48 * amount);
                        tail.setRotation(11 * amount, MathUtils.sin(ageInTicks * 0.8f) * 24 * amount, 0);
                    }
                }
                case FACEPLANT -> {
                    if (kind == AnimalKind.FOX) {
                        body.setRotation(-35 * amount, 0, 0);
                        body.setTranslation(0, -2 * amount, 0);
                        head.setRotation(-52 * amount, 0, 0);
                        foldLegs(78 * amount, -24 * amount);
                        tail.setRotation(-60 * amount, 0, 0);
                    }
                }
                case SLEEP -> {
                    if (kind == AnimalKind.FOX) {
                        sleep(amount);
                    }
                }
                case SIT -> {
                    if (kind == AnimalKind.CAMEL) {
                        sit(amount);
                    }
                }
                default -> {
                    // Tư thế thông thường giữ các giá trị bước và nhìn đã tính phía trên.
                }
            }
        }

        /** Nhấc thân lên chân sau và giữ điểm đặt hai chân sau tại chỗ. */
        private void rear(float amount, float headYaw, float headPitch) {
            float angle = 62 * amount;
            double radians = Math.toRadians(angle);
            float sine = (float) Math.sin(radians);
            float cosine = (float) Math.cos(radians);
            float hipHeight = legs[2].geometry().height();
            float hipDepth = kind == AnimalKind.BEAR ? BEAR_HIND_HIP_DEPTH : EQUINE_HIND_HIP_DEPTH;
            body.setRotation(angle, 0, 0);
            // Bù phần hông di chuyển do thân quay để chân sau vẫn chạm mặt đất.
            body.setTranslation(0, hipHeight * (1 - cosine) + hipDepth * sine,
                    hipDepth * (1 - cosine) - hipHeight * sine);
            head.setRotation((kind == AnimalKind.EQUINE ? -30f : 0f) + headPitch - 44 * amount, headYaw * 0.6f, 0);
            foldLegs(22 * amount, -angle);
        }

        /** Thu cả bốn chân, xoay đầu về sườn và quấn đuôi về trước quanh thân cáo. */
        private void sleep(float amount) {
            body.setRotation(0, 0, -13 * amount);
            body.setTranslation(0, -1.8f * amount, 0);
            head.setRotation(-17 * amount, 72 * amount, 20 * amount);
            tail.setRotation(-6 * amount, 143 * amount, 0);
            foldLegs(69 * amount, -73 * amount);
        }

        /** Hạ thân và thu chân theo hai hướng để bướu giữ thăng bằng khi lạc đà ngồi. */
        private void sit(float amount) {
            body.setTranslation(0, -12 * amount, 0);
            body.setRotation(-4 * amount, 0, 0);
            head.setRotation(-22 * amount, 0, 0);
            tail.setRotation(-23 * amount, 0, 0);
            foldLegs(78 * amount, -65 * amount);
        }

        /** Dùng cùng một góc cho hai chân trước và một góc cho hai chân sau. */
        private void foldLegs(float forward, float back) {
            legs[0].setRotation(forward, 0, 0);
            legs[1].setRotation(forward, 0, 0);
            legs[2].setRotation(back, 0, 0);
            legs[3].setRotation(back, 0, 0);
        }
    }

    /** Dựng gà ôn đới chuẩn Minecraft với hai chân vẽ hai mặt để luôn rõ từ mọi hướng. */
    private static MobModel chicken() {
        ModelPart head = skinBox(0, 9, -4, -2, 0, -2, 4, 6, 3, 0, 0,
                skinBox(0, 0, 0, -2, 2, -4, 4, 2, 2, 14, 0),
                skinBox(0, 0, 0, -1, 0, -3, 2, 2, 2, 14, 4));
        ModelPart rightWing = skinBox(3, 11, 0, 0, -4, -3, 1, 4, 6, 24, 13);
        ModelPart leftWing = skinBox(-3, 11, 0, -1, -4, -3, 1, 4, 6, 24, 13);
        ModelPart rightLeg = skinBox(1.5f, 5, 1, -1.5f, -5, -2, 3, 5, 3, 26, 0).setDoubleSided(true);
        ModelPart leftLeg = skinBox(-1.5f, 5, 1, -1.5f, -5, -2, 3, 5, 3, 26, 0).setDoubleSided(true);
        ModelPart body = skinBox(0, 0, 0, -3, 5, -4, 6, 6, 8, horizontal(0, 9, 6, 8, 6),
                head, rightWing, leftWing, rightLeg, leftLeg);
        return new ChickenModel(body, head, rightWing, leftWing, rightLeg, leftLeg);
    }

    /** Hoạt ảnh gà vỗ cánh đối xứng khi nhảy hoặc rơi. */
    private static final class ChickenModel extends MobModel {
        private final ModelPart head;
        private final ModelPart rightWing;
        private final ModelPart leftWing;
        private final ModelPart rightLeg;
        private final ModelPart leftLeg;

        private ChickenModel(ModelPart body, ModelPart head, ModelPart rightWing, ModelPart leftWing,
                             ModelPart rightLeg, ModelPart leftLeg) {
            super(body);
            this.head = head;
            this.rightWing = rightWing;
            this.leftWing = leftWing;
            this.rightLeg = rightLeg;
            this.leftLeg = leftLeg;
        }

        @Override
        public void setupAnimation(LivingEntity entity, float limbSwing, float limbSwingAmount,
                                   float ageInTicks, float headYaw, float headPitch) {
            MobVisualState state = visualState(entity);
            float flap = 5;
            if (pose(state) == MobVisualState.Pose.FLAP) {
                flap += (53 + 29 * (float) Math.sin(ageInTicks * 1.35f)) * state.poseAmount();
            }
            float step = gait(limbSwing, limbSwingAmount, 46);
            head.setRotation(headPitch, headYaw, 0);
            rightWing.setRotation(0, 0, -flap);
            leftWing.setRotation(0, 0, flap);
            rightLeg.setRotation(-step, 0, 0);
            leftLeg.setRotation(step, 0, 0);
        }
    }

    /** Dựng mũi tên chữ X chuẩn Minecraft từ tấm 32×32, đầu tên hướng về -Z. */
    private static MobModel arrow() {
        ModelPart.CuboidUv arrowUv = new ModelPart.CuboidUv(0, 0, 16, 10, 0, ModelPart.UvOrientation.FLAT_SPRITE);
        return fixed(new ModelPart(0, 1, 0, -2.5f, -2.5f, -8, 5, 5, 16, 0f, arrowUv,
                ModelPart.Shape.CROSSED_ARROW).setDoubleSided(true));
    }

    /** Dựng lọ thuốc ném chữ X chuẩn Minecraft từ sprite 16×16. */
    private static MobModel potion() {
        ModelPart.CuboidUv potionUv = new ModelPart.CuboidUv(0, 0, 16, 16, 0, ModelPart.UvOrientation.FLAT_SPRITE);
        return fixed(new ModelPart(0, 4, 0, -4, -4, -4, 8, 8, 8, 0f, potionUv,
                ModelPart.Shape.CROSSED_POTION).setDoubleSided(true));
    }

    /** Giữ tư thế cục bộ của đạn; hướng bay do biến đổi gốc quyết định. */
    private static MobModel fixed(ModelPart root) {
        return new MobModel(root) {
            @Override
            public void setupAnimation(LivingEntity entity, float limbSwing, float limbSwingAmount,
                                       float ageInTicks, float headYaw, float headPitch) {
                // Định hướng chuyển động thuộc thực thể đạn, không thuộc khung khớp.
            }
        };
    }
}

package com.voxelgame.client.model;

import com.voxelgame.client.render.Texture;

import com.badlogic.gdx.math.Matrix4;
import com.badlogic.gdx.math.Vector3;
import java.util.Objects;

/**
 * Hộp pixel hoặc mặt phẳng trang bị trong cây khớp, với mặt trước theo -Z và
 * trục đứng theo +Y.
 */
public final class ModelPart {
    /** Chọn vật liệu của bộ phận trong mỗi lượt vẽ mô hình. */
    public enum Layer {
        BASE, OVERLAY, EYES, EQUIPMENT
    }

    /**
     * Chiều trải ảnh gốc của hộp, kể cả thân nằm ngang, chi trái đối xứng và sprite
     * phẳng.
     */
    public enum UvOrientation {
        OURCRAFT, MINECRAFT, HORIZONTAL, MIRRORED, FLAT_SPRITE
    }

    /** Dạng hình học dựng lưới đỉnh của bộ phận. */
    public enum Shape {
        BOX, FLAT_SPRITE, CROSSED_POTION, CROSSED_ARROW
    }

    /** Kích thước hình trải tính theo ảnh nguồn, độc lập với tỉ lệ hộp khi vẽ. */
    public record CuboidUv(int u, int v, int width, int height, int depth, UvOrientation orientation) {
    }

    /** Độ sáng tương đối của sáu mặt theo quy ước hình học chunk. */
    private static final float SHADE_TOP = 1f;
    private static final float SHADE_BOTTOM = 0.55f;
    private static final float SHADE_NORTH_SOUTH = 0.85f;
    private static final float SHADE_EAST_WEST = 0.72f;
    /** Định dạng XYZ, UV, độ sáng của shader thế giới. */
    public static final int STRIDE = 6;
    static final int VERTEX_COUNT = 36;

    /**
     * Thông số bất biến để chia sẻ mesh giữa các bộ phận có cùng hình học và UV.
     */
    public record Geometry(float x, float y, float z, int width, int height, int depth,
            float inflate, CuboidUv uv, Shape shape) {
    }

    private final float pivotX;
    private final float pivotY;
    private final float pivotZ;
    private final Geometry geometry;
    private final ModelPart[] children;
    private float baseRotationX;
    private float baseRotationY;
    private float baseRotationZ;
    private float rotationX;
    private float rotationY;
    private float rotationZ;
    private float translationX;
    private float translationY;
    private float translationZ;
    private boolean visible = true;
    private boolean doubleSided;
    private Layer layer = Layer.BASE;

    /**
     * Lưu điểm xoay, kích thước hộp và tọa độ pixel của sơ đồ trải UV theo bố cục
     * Ourcraft.
     */
    public ModelPart(float pivotX, float pivotY, float pivotZ, float offsetX, float offsetY, float offsetZ,
            int sizeX, int sizeY, int sizeZ, int texU, int texV, float inflate, ModelPart... children) {
        this(pivotX, pivotY, pivotZ, offsetX, offsetY, offsetZ, sizeX, sizeY, sizeZ, inflate,
                new CuboidUv(texU, texV, sizeX, sizeY, sizeZ, UvOrientation.OURCRAFT), Shape.BOX, children);
    }

    /** Lưu hộp hiển thị cùng kích thước và chiều trải UV của ảnh nguồn. */
    public ModelPart(float pivotX, float pivotY, float pivotZ, float offsetX, float offsetY, float offsetZ,
            int sizeX, int sizeY, int sizeZ, float inflate, CuboidUv uv, ModelPart... children) {
        this(pivotX, pivotY, pivotZ, offsetX, offsetY, offsetZ, sizeX, sizeY, sizeZ, inflate,
                uv, Shape.BOX, children);
    }

    /**
     * Lưu bộ phận với dạng hình học chỉ định (hộp, sprite phẳng hoặc chữ thập đạn
     * đạo).
     */
    ModelPart(float pivotX, float pivotY, float pivotZ, float offsetX, float offsetY, float offsetZ,
            int sizeX, int sizeY, int sizeZ, float inflate, CuboidUv uv, Shape shape, ModelPart... children) {
        int shortestSide = Math.min(sizeX, Math.min(sizeY, sizeZ));
        float expandedSide = shortestSide + 2 * inflate;
        // Râu dê, đuôi lạc đà và sprite phẳng dùng mặt có độ dày bằng 0. Hộp Ourcraft
        // vẫn dùng hộp đặc.
        if (sizeX < 0 || sizeY < 0 || sizeZ < 0 || uv.u < 0 || uv.v < 0
                || uv.width < 0 || uv.height < 0 || uv.depth < 0
                || !Float.isFinite(inflate) || expandedSide < 0f
                || (uv.orientation == UvOrientation.OURCRAFT && (shortestSide == 0 || expandedSide == 0f))) {
            throw new IllegalArgumentException("Kích thước hộp, độ phồng hoặc gốc UV không hợp lệ");
        }
        this.pivotX = pivotX;
        this.pivotY = pivotY;
        this.pivotZ = pivotZ;
        geometry = new Geometry(offsetX, offsetY, offsetZ, sizeX, sizeY, sizeZ, inflate, uv, shape);
        this.children = children.clone();
    }

    /** Vật liệu được đặt khi dựng mẫu, độc lập với tư thế từng cá thể. */
    public ModelPart setLayer(Layer layer) {
        this.layer = Objects.requireNonNull(layer);
        return this;
    }

    /**
     * Đánh dấu bộ phận cần vẽ cả hai mặt (tắt culling) cho mặt phẳng hoặc phần có
     * khe rỗng.
     */
    public ModelPart setDoubleSided(boolean doubleSided) {
        this.doubleSided = doubleSided;
        return this;
    }

    /**
     * Đặt góc nghỉ mặc định theo độ để {@link #resetPose()} luôn khôi phục về góc
     * chuẩn của loài.
     */
    public ModelPart setBaseRotation(float x, float y, float z) {
        baseRotationX = x;
        baseRotationY = y;
        baseRotationZ = z;
        rotationX = x;
        rotationY = y;
        rotationZ = z;
        return this;
    }

    /** Đặt góc quay Euler cục bộ theo độ trong tư thế hiện tại. */
    public void setRotation(float x, float y, float z) {
        rotationX = x;
        rotationY = y;
        rotationZ = z;
    }

    /**
     * Dời điểm xoay theo pixel cục bộ, ví dụ để hạ thân khi ngồi hoặc trượt đầu
     * Enderman.
     */
    public void setTranslation(float x, float y, float z) {
        translationX = x;
        translationY = y;
        translationZ = z;
    }

    /** Ẩn bộ phận cùng các con của nó trong tư thế hiện tại. */
    public void setVisible(boolean visible) {
        this.visible = visible;
    }

    /**
     * Dọn tư thế của cá thể trước về đúng góc nghỉ mặc định để dùng lại cho cá thể
     * kế tiếp.
     */
    public void resetPose() {
        rotationX = baseRotationX;
        rotationY = baseRotationY;
        rotationZ = baseRotationZ;
        translationX = translationY = translationZ = 0f;
        visible = true;
        for (ModelPart child : children) {
            child.resetPose();
        }
    }

    /**
     * Ghi phép biến đổi từ cha vào bộ đệm được truyền vào, giữ nguyên ma trận của
     * cha.
     */
    public void writeTransform(Matrix4 parent, Matrix4 out) {
        out.set(parent).translate(pivotX + translationX, pivotY + translationY, pivotZ + translationZ);
        if (rotationZ != 0f) {
            out.rotate(Vector3.Z, rotationZ);
        }
        if (rotationY != 0f) {
            out.rotate(Vector3.Y, rotationY);
        }
        if (rotationX != 0f) {
            out.rotate(Vector3.X, rotationX);
        }
    }

    /**
     * Cho biết vùng pixel nguồn có nằm hoàn toàn trong tấm ảnh vật liệu hay không.
     */
    public boolean fitsTexture(int width, int height) {
        CuboidUv uv = geometry.uv;
        if (geometry.shape == Shape.CROSSED_ARROW) {
            return (long) uv.u + 16L <= width && (long) uv.v + 10L <= height;
        }
        if (geometry.shape != Shape.BOX || uv.orientation == UvOrientation.FLAT_SPRITE) {
            return (long) uv.u + uv.width <= width && (long) uv.v + uv.height <= height;
        }
        return (long) uv.u + 2L * (uv.width + (long) uv.depth) <= width
                && (long) uv.v + uv.depth + uv.height <= height;
    }

    /** Kiểm tra đồng thời các phần dùng cùng một lớp ảnh trong toàn bộ nhánh. */
    boolean fitsLayer(Layer target, int width, int height) {
        if (layer == target && !fitsTexture(width, height)) {
            return false;
        }
        for (ModelPart child : children) {
            if (!child.fitsLayer(target, width, height)) {
                return false;
            }
        }
        return true;
    }

    /** Bán kính quanh điểm xoay của cha khi các khớp tự do quay theo ba trục. */
    float maxReach() {
        float x = Math.max(Math.abs(geometry.x), Math.abs(geometry.x + geometry.width)) + geometry.inflate;
        float y = Math.max(Math.abs(geometry.y), Math.abs(geometry.y + geometry.height)) + geometry.inflate;
        float z = Math.max(Math.abs(geometry.z), Math.abs(geometry.z + geometry.depth)) + geometry.inflate;
        float reach = (float) Math.sqrt(x * x + y * y + z * z);
        for (ModelPart child : children) {
            reach = Math.max(reach, child.maxReach());
        }
        return reach + (float) Math.sqrt(pivotX * pivotX + pivotY * pivotY + pivotZ * pivotZ);
    }

    /**
     * Ghi đỉnh của khối hộp, mặt phẳng hoặc chữ thập đạn đạo với UV chuẩn
     * Minecraft.
     */
    public float[] buildVertices(int texWidth, int texHeight) {
        if (!fitsTexture(texWidth, texHeight)) {
            throw new IllegalArgumentException("Texture không đủ kích thước cho bộ phận");
        }
        return switch (geometry.shape) {
            case FLAT_SPRITE -> buildFlatSpriteVertices(texWidth, texHeight);
            case CROSSED_POTION -> buildCrossedPotionVertices(texWidth, texHeight);
            case CROSSED_ARROW -> buildCrossedArrowVertices(texWidth, texHeight);
            case BOX -> buildBoxVertices(texWidth, texHeight);
        };
    }

    /** Dựng một mặt phẳng 2D đơn sắc theo UV trực tiếp trên tấm sprite trang bị. */
    private float[] buildFlatSpriteVertices(int texWidth, int texHeight) {
        CuboidUv uv = geometry.uv;
        float x0 = geometry.x;
        float x1 = geometry.x + geometry.width;
        float y0 = geometry.y;
        float y1 = geometry.y + geometry.height;
        float z = geometry.z + geometry.depth * 0.5f;
        float u0 = (float) uv.u / texWidth;
        float u1 = (float) (uv.u + uv.width) / texWidth;
        float v0 = (float) uv.v / texHeight;
        float v1 = (float) (uv.v + uv.height) / texHeight;
        float[] vertices = new float[6 * STRIDE];
        face(vertices, 0, x1, y1, z, x1, y0, z, x0, y0, z, x0, y1, z, u0, v0, u1, v1, SHADE_TOP);
        return vertices;
    }

    /** Dựng hai mặt phẳng giao nhau hình chữ X cho lọ thuốc ném chuẩn Minecraft. */
    private float[] buildCrossedPotionVertices(int texWidth, int texHeight) {
        CuboidUv uv = geometry.uv;
        float x0 = geometry.x;
        float x1 = geometry.x + geometry.width;
        float y0 = geometry.y;
        float y1 = geometry.y + geometry.height;
        float z0 = geometry.z;
        float z1 = geometry.z + geometry.depth;
        float u0 = (float) uv.u / texWidth;
        float u1 = (float) (uv.u + uv.width) / texWidth;
        float v0 = (float) uv.v / texHeight;
        float v1 = (float) (uv.v + uv.height) / texHeight;
        float[] vertices = new float[12 * STRIDE];
        face(vertices, 0, x0, y1, z0, x0, y0, z0, x1, y0, z1, x1, y1, z1, u0, v0, u1, v1, SHADE_TOP);
        face(vertices, 1, x1, y1, z0, x1, y0, z0, x0, y0, z1, x0, y1, z1, u0, v0, u1, v1, SHADE_NORTH_SOUTH);
        return vertices;
    }

    /**
     * Dựng mũi tên chữ X chuẩn Minecraft từ tấm 32×32 (hai cánh dọc + hai cánh đuôi
     * ngang).
     */
    private float[] buildCrossedArrowVertices(int texWidth, int texHeight) {
        float x0 = geometry.x;
        float x1 = geometry.x + geometry.width;
        float y0 = geometry.y;
        float y1 = geometry.y + geometry.height;
        float z0 = geometry.z;
        float z1 = geometry.z + geometry.depth;
        float tailZ = z1 - 1.5f;

        // Thân tên nằm ngang từ (0, 0) đến (16, 5) trong tấm 32x32, đầu tên tại u=16,
        // đuôi tại u=0.
        float bodyU0 = 0f / texWidth;
        float bodyU1 = 16f / texWidth;
        float bodyV0 = 0f / texHeight;
        float bodyV1 = 5f / texHeight;
        // Chữ thập lông đuôi tại (0, 5) kích thước 5x5.
        float tailU0 = 0f / texWidth;
        float tailU1 = 5f / texWidth;
        float tailV0 = 5f / texHeight;
        float tailV1 = 10f / texHeight;

        float[] vertices = new float[18 * STRIDE];
        // Cánh chéo 1 (+X/+Y nối -X/-Y) dọc theo trục Z, đầu nhọn quay về -Z.
        face(vertices, 0, x1, y1, z0, x0, y0, z0, x0, y0, z1, x1, y1, z1,
                bodyU1, bodyV0, bodyU0, bodyV1, SHADE_TOP);
        // Cánh chéo 2 (-X/+Y nối +X/-Y) dọc theo trục Z.
        face(vertices, 1, x0, y1, z0, x1, y0, z0, x1, y0, z1, x0, y1, z1,
                bodyU1, bodyV0, bodyU0, bodyV1, SHADE_NORTH_SOUTH);
        // Hai mặt lông đuôi vuông góc tại cuối mũi tên.
        face(vertices, 2, x1, y1, tailZ, x1, y0, tailZ, x0, y0, tailZ, x0, y1, tailZ,
                tailU0, tailV0, tailU1, tailV1, SHADE_EAST_WEST);
        return vertices;
    }

    /**
     * Ghi sáu mặt đúng chiều pháp tuyến và đúng chiều UV Minecraft (không lật
     * gương).
     */
    private float[] buildBoxVertices(int texWidth, int texHeight) {
        float x0 = geometry.x - geometry.inflate;
        float x1 = geometry.x + geometry.width + geometry.inflate;
        float y0 = geometry.y - geometry.inflate;
        float y1 = geometry.y + geometry.height + geometry.inflate;
        float z0 = geometry.z - geometry.inflate;
        float z1 = geometry.z + geometry.depth + geometry.inflate;

        CuboidUv uv = geometry.uv;
        float u0 = (float) uv.u / texWidth;
        float u1 = (float) (uv.u + uv.depth) / texWidth;
        float u2 = (float) (uv.u + uv.depth + uv.width) / texWidth;
        float u3 = (float) (uv.u + 2 * uv.depth + uv.width) / texWidth;
        float u4 = (float) (uv.u + 2 * (uv.depth + uv.width)) / texWidth;
        float bottomU = (float) (uv.u + uv.depth + 2 * uv.width) / texWidth;
        float v0 = (float) uv.v / texHeight;
        float v1 = (float) (uv.v + uv.depth) / texHeight;
        float v2 = (float) (uv.v + uv.depth + uv.height) / texHeight;
        float[] vertices = new float[VERTEX_COUNT * STRIDE];
        boolean horizontal = uv.orientation == UvOrientation.HORIZONTAL;
        boolean vanilla = uv.orientation != UvOrientation.OURCRAFT;
        if (horizontal) {
            // Dựng trong hệ của hình trải rồi xoay quanh X để đặt thân lên bốn chân.
            float bottom = y0;
            float top = y1;
            y0 = -z1;
            y1 = -z0;
            z0 = bottom;
            z1 = top;
        }

        if (vanilla) {
            // Hệ trục VoxelGame: -Z là mặt trước, +X là bên phải của mob (trái màn hình khi
            // nhìn trực diện), +Y lên trên.
            face(vertices, 0, x0, y1, z0, x0, y0, z0, x0, y0, z1, x0, y1, z1,
                    u2, v1, u3, v2, SHADE_EAST_WEST);
            face(vertices, 1, x1, y1, z0, x1, y0, z0, x0, y0, z0, x0, y1, z0,
                    u1, v1, u2, v2, horizontal ? SHADE_BOTTOM : SHADE_NORTH_SOUTH);
            face(vertices, 2, x1, y1, z1, x1, y0, z1, x1, y0, z0, x1, y1, z0,
                    u0, v1, u1, v2, SHADE_EAST_WEST);
            face(vertices, 3, x0, y1, z1, x0, y0, z1, x1, y0, z1, x1, y1, z1,
                    u3, v1, u4, v2, horizontal ? SHADE_TOP : SHADE_NORTH_SOUTH);
            face(vertices, 4, x1, y1, z1, x1, y1, z0, x0, y1, z0, x0, y1, z1,
                    u1, v0, u2, v1, horizontal ? SHADE_NORTH_SOUTH : SHADE_TOP);
            face(vertices, 5, x1, y0, z0, x1, y0, z1, x0, y0, z1, x0, y0, z0,
                    u2, v1, bottomU, v0, horizontal ? SHADE_NORTH_SOUTH : SHADE_BOTTOM);
        } else {
            face(vertices, 0, x0, y1, z0, x0, y0, z0, x0, y0, z1, x0, y1, z1,
                    u0, v1, u1, v2, SHADE_EAST_WEST);
            face(vertices, 1, x1, y1, z0, x1, y0, z0, x0, y0, z0, x0, y1, z0,
                    u1, v1, u2, v2, horizontal ? SHADE_BOTTOM : SHADE_NORTH_SOUTH);
            face(vertices, 2, x1, y1, z1, x1, y0, z1, x1, y0, z0, x1, y1, z0,
                    u2, v1, u3, v2, SHADE_EAST_WEST);
            face(vertices, 3, x0, y1, z1, x0, y0, z1, x1, y0, z1, x1, y1, z1,
                    u3, v1, u4, v2, horizontal ? SHADE_TOP : SHADE_NORTH_SOUTH);
            face(vertices, 4, x0, y1, z0, x0, y1, z1, x1, y1, z1, x1, y1, z0,
                    u1, v0, u2, v1, horizontal ? SHADE_NORTH_SOUTH : SHADE_TOP);
            face(vertices, 5, x0, y0, z1, x0, y0, z0, x1, y0, z0, x1, y0, z1,
                    u2, v0, bottomU, v1, horizontal ? SHADE_NORTH_SOUTH : SHADE_BOTTOM);
        }

        if (uv.orientation == UvOrientation.MIRRORED) {
            // Phản chiếu vị trí đi kèm UV và đảo thứ tự đỉnh để mặt vẫn quay ra ngoài.
            float twiceCenterX = 2f * geometry.x + geometry.width;
            for (int i = 0; i < vertices.length; i += 3 * STRIDE) {
                for (int vertex = i; vertex < i + 3 * STRIDE; vertex += STRIDE) {
                    vertices[vertex] = twiceCenterX - vertices[vertex];
                }
                for (int attribute = 0; attribute < STRIDE; attribute++) {
                    int first = i + STRIDE + attribute;
                    int second = first + STRIDE;
                    float value = vertices[first];
                    vertices[first] = vertices[second];
                    vertices[second] = value;
                }
            }
        }
        return vertices;
    }

    /** Viết hai tam giác của mặt, dùng dấu âm độ sáng cho lớp mắt tự phát sáng. */
    private void face(float[] out, int index, float ax, float ay, float az, float bx, float by, float bz,
            float cx, float cy, float cz, float dx, float dy, float dz,
            float uMin, float vMin, float uMax, float vMax, float shade) {
        int i = index * 6 * STRIDE;
        float faceShade = layer == Layer.EYES ? -1f : shade;
        vertex(out, i, ax, ay, az, uMin, vMin, faceShade);
        vertex(out, i + STRIDE, bx, by, bz, uMin, vMax, faceShade);
        vertex(out, i + 2 * STRIDE, cx, cy, cz, uMax, vMax, faceShade);
        vertex(out, i + 3 * STRIDE, ax, ay, az, uMin, vMin, faceShade);
        vertex(out, i + 4 * STRIDE, cx, cy, cz, uMax, vMax, faceShade);
        vertex(out, i + 5 * STRIDE, dx, dy, dz, uMax, vMin, faceShade);
    }

    /** Ghi một đỉnh theo định dạng shader. */
    private void vertex(float[] out, int i, float x, float y, float z, float u, float v, float shade) {
        out[i] = x;
        boolean horizontal = geometry.uv.orientation == UvOrientation.HORIZONTAL;
        out[i + 1] = horizontal ? z : y;
        out[i + 2] = horizontal ? -y : z;
        out[i + 3] = u;
        out[i + 4] = v;
        out[i + 5] = shade;
    }

    /** Đọc hình học để tạo khóa mesh dùng chung. */
    public Geometry geometry() {
        return geometry;
    }

    /** Đọc các con đã cố định khi khởi tạo. */
    public ModelPart[] children() {
        return children;
    }

    /** Đọc vật liệu của bộ phận. */
    public Layer layer() {
        return layer;
    }

    /** Báo bộ phận có mặt trong tư thế hiện tại. */
    public boolean isVisible() {
        return visible;
    }

    /** Báo bộ phận có cần vẽ hai mặt không bị face culling hay không. */
    public boolean isDoubleSided() {
        return doubleSided;
    }
}

package com.voxelgame.client.render;

import com.voxelgame.world.level.block.Block;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Mesh;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.Texture.TextureFilter;
import com.badlogic.gdx.graphics.Texture.TextureWrap;
import com.badlogic.gdx.graphics.VertexAttribute;
import com.badlogic.gdx.graphics.VertexAttributes;
import com.badlogic.gdx.math.Matrix4;
import com.badlogic.gdx.utils.Disposable;
import com.badlogic.gdx.utils.GdxNativesLoader;

/**
 * Kết xuất khung dây chọn block ({@code GL_LINES}, đen mờ {@code alpha = 0.65f}) ôm sát
 * {@link Block.Bounds} nới {@code 0.004f} và lớp phủ vết nứt 10 giai đoạn ({@code destroy_stage_0..9.png})
 * đóng gói thành một texture {@code 160x16} duy nhất trên GPU, cập nhật đỉnh tại chỗ theo cơ chế zero-GC.
 */
public class BlockOutlineRenderer implements Disposable {

    /** Số giai đoạn nứt vỡ chuẩn từ {@code destroy_stage_0.png} đến {@code destroy_stage_9.png}. */
    public static final int STAGE_COUNT = 10;

    /** Độ nới khung dây chọn block để tránh trùng mặt (Z-fighting) với bề mặt khối gốc. */
    public static final float OUTLINE_EXPAND = 0.004f;

    /** Độ nới lớp phủ vết nứt nằm giữa mặt khối gốc và khung dây bên ngoài. */
    public static final float CRACK_EXPAND = 0.002f;

    /** Độ mờ của khung dây chọn block màu đen. */
    public static final float OUTLINE_ALPHA = 0.65f;

    /** Định dạng 6 số thực mỗi đỉnh khớp với {@link ShaderProgram}: aPos(3), aTexCoord(2), aShade(1). */
    private static final int FLOATS_PER_VERTEX = 6;
    private static final int LINE_VERTEX_COUNT = 24;
    private static final int CRACK_VERTEX_COUNT = 36;

    /** Kích thước atlas ngang {@code 160x16} chứa 10 giai đoạn vết nứt {@code 16x16}. */
    private static final int DESTROY_ATLAS_WIDTH = Texture.TILE_SIZE * STAGE_COUNT;
    private static final int DESTROY_ATLAS_HEIGHT = Texture.TILE_SIZE;

    private final com.badlogic.gdx.graphics.Texture destroyTexture;
    private final Mesh lineMesh;
    private final Mesh crackMesh;
    private final float[] lineVertices = new float[LINE_VERTEX_COUNT * FLOATS_PER_VERTEX];
    private final float[] crackVertices = new float[CRACK_VERTEX_COUNT * FLOATS_PER_VERTEX];
    private final Matrix4 modelMatrix = new Matrix4();
    private boolean disposed;

    /**
     * Khởi tạo bộ kết xuất viền chọn và vết nứt block:
     * nạp 10 ảnh {@code textures/destroy_stage_0..9.png}, đóng gói vào texture {@code 160x16}
     * và cấp phát trước hai {@link Mesh} cho khung dây (24 đỉnh) cùng hộp vết nứt (36 đỉnh).
     * Hỗ trợ an toàn khi chạy kiểm thử CPU không có ngữ cảnh OpenGL ({@code Gdx.gl == null}).
     */
    public BlockOutlineRenderer() {
        GdxNativesLoader.load();
        com.badlogic.gdx.graphics.Texture createdTexture = null;
        Mesh createdLineMesh = null;
        Mesh createdCrackMesh = null;

        if (Gdx.gl != null) {
            Pixmap atlasPixmap = buildDestroyAtlasPixmap();
            try {
                createdTexture = new com.badlogic.gdx.graphics.Texture(atlasPixmap);
                createdTexture.setFilter(TextureFilter.Nearest, TextureFilter.Nearest);
                createdTexture.setWrap(TextureWrap.ClampToEdge, TextureWrap.ClampToEdge);

                createdLineMesh = createDynamicMesh(LINE_VERTEX_COUNT);
                createdCrackMesh = createDynamicMesh(CRACK_VERTEX_COUNT);
            } catch (RuntimeException | Error failure) {
                if (createdTexture != null) {
                    createdTexture.dispose();
                }
                if (createdLineMesh != null) {
                    createdLineMesh.dispose();
                }
                if (createdCrackMesh != null) {
                    createdCrackMesh.dispose();
                }
                throw failure;
            } finally {
                atlasPixmap.dispose();
            }
        }

        this.destroyTexture = createdTexture;
        this.lineMesh = createdLineMesh;
        this.crackMesh = createdCrackMesh;
    }

    /** Tạo {@link Mesh} động dùng chung định dạng 6 floats/đỉnh với {@link ShaderProgram}. */
    private static Mesh createDynamicMesh(int maxVertices) {
        return new Mesh(
                Mesh.VertexDataType.VertexBufferObjectWithVAO,
                false,
                maxVertices,
                0,
                new VertexAttribute(VertexAttributes.Usage.Position, 3, "aPos"),
                new VertexAttribute(VertexAttributes.Usage.TextureCoordinates, 2, "aTexCoord"),
                new VertexAttribute(VertexAttributes.Usage.Generic, 1, "aShade")
        );
    }

    /**
     * Nạp 10 ảnh {@code textures/destroy_stage_0.png .. textures/destroy_stage_9.png} qua
     * {@link Texture#loadPixmapFlexible(String...)} và {@link Texture#readNormalizedPixel(Pixmap, int, int)},
     * đóng gói thành một {@link Pixmap} kích thước {@code 160x16} định dạng {@code RGBA8888}.
     */
    public static Pixmap buildDestroyAtlasPixmap() {
        Pixmap atlas = new Pixmap(DESTROY_ATLAS_WIDTH, DESTROY_ATLAS_HEIGHT, Pixmap.Format.RGBA8888);
        atlas.setBlending(Pixmap.Blending.None);
        try {
            for (int stage = 0; stage < STAGE_COUNT; stage++) {
                String primary = "textures/destroy_stage_" + stage + ".png";
                String secondary = "textures/block/destroy_stage_" + stage + ".png";
                Pixmap stagePixmap = Texture.loadPixmapFlexible(primary, secondary);
                if (stagePixmap != null) {
                    try {
                        blitStageToAtlas(atlas, stagePixmap, stage);
                    } finally {
                        stagePixmap.dispose();
                    }
                } else {
                    fillProceduralStageFallback(atlas, stage);
                }
            }
            return atlas;
        } catch (RuntimeException | Error failure) {
            atlas.dispose();
            throw failure;
        }
    }

    /** Sao chép và chuẩn hóa từng pixel từ ảnh giai đoạn nứt vào đúng ô {@code 16x16} trên atlas ngang. */
    private static void blitStageToAtlas(Pixmap atlas, Pixmap src, int stage) {
        int srcW = Math.max(1, src.getWidth());
        int srcH = Math.max(1, src.getHeight());
        int offsetX = stage * Texture.TILE_SIZE;
        for (int ty = 0; ty < Texture.TILE_SIZE; ty++) {
            int sy = Math.min(srcH - 1, (int) (((ty + 0.5f) / Texture.TILE_SIZE) * srcH));
            for (int tx = 0; tx < Texture.TILE_SIZE; tx++) {
                int sx = Math.min(srcW - 1, (int) (((tx + 0.5f) / Texture.TILE_SIZE) * srcW));
                int rgba = Texture.readNormalizedPixel(src, sx, sy);
                atlas.drawPixel(offsetX + tx, ty, rgba);
            }
        }
    }

    /** Sinh mẫu vết nứt dự phòng tất định nếu thiếu file ảnh giai đoạn đào. */
    private static void fillProceduralStageFallback(Pixmap atlas, int stage) {
        int offsetX = stage * Texture.TILE_SIZE;
        int threshold = stage + 1;
        for (int ty = 0; ty < Texture.TILE_SIZE; ty++) {
            for (int tx = 0; tx < Texture.TILE_SIZE; tx++) {
                int dist = Math.abs(tx - 7) + Math.abs(ty - 7);
                boolean isCrack = (tx == ty || tx + ty == 15) && dist <= threshold + 2;
                int rgba = isCrack ? Texture.packRgba(55, 55, 55, 255) : Texture.packRgba(255, 255, 255, 0);
                atlas.drawPixel(offsetX + tx, ty, rgba);
            }
        }
    }

    /**
     * Quy đổi tiến trình đào {@code miningProgress} sang chỉ số giai đoạn vết nứt {@code 0..9}.
     * Trả về {@code -1} khi chưa bắt đầu đào ({@code progress <= 0.001f}).
     *
     * @param progress tiến trình đào chuẩn hóa (thường trong {@code [0.0f, 1.0f]})
     * @return {@code -1} nếu chưa nứt, hoặc chỉ số giai đoạn trong {@code [0, 9]}
     */
    public static int stageForProgress(float progress) {
        if (progress <= 0.001f) {
            return -1;
        }
        float clamped = Math.min(0.9999f, progress);
        int stage = (int) (clamped * STAGE_COUNT);
        return Math.max(0, Math.min(STAGE_COUNT - 1, stage));
    }

    /**
     * Vẽ khung dây đen quanh hộp chọn {@link Block#getSelectionBounds(int)} của block mục tiêu
     * và vẽ lớp phủ vết nứt 10 giai đoạn khi {@code miningProgress > 0.001f}.
     *
     * @param shader         shader đang được bind sẵn với {@code uProjection} và {@code uView}
     * @param bx             tọa độ X nguyên của block
     * @param by             tọa độ Y nguyên của block
     * @param bz             tọa độ Z nguyên của block
     * @param block          loại block tại ô mục tiêu
     * @param state          metadata trạng thái của block
     * @param miningProgress tiến trình đập block hiện tại trong {@code [0.0f, 1.0f]}
     */
    public void render(ShaderProgram shader, int bx, int by, int bz, Block block, int state, float miningProgress) {
        if (disposed || shader == null || block == null || Gdx.gl == null
                || lineMesh == null || crackMesh == null || destroyTexture == null) {
            return;
        }
        Block.Bounds bounds = block.getSelectionBounds(state);
        if (bounds == null) {
            return;
        }

        float minX = bx + bounds.minX();
        float minY = by + bounds.minY();
        float minZ = bz + bounds.minZ();
        float maxX = bx + bounds.maxX();
        float maxY = by + bounds.maxY();
        float maxZ = bz + bounds.maxZ();

        modelMatrix.idt();
        shader.setUniformMatrix4f("uModel", modelMatrix);
        shader.setUniform1i("uEnvironmentMode", 0);
        shader.enableChunkColorMode(false);

        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        Gdx.gl.glEnable(GL20.GL_DEPTH_TEST);
        Gdx.gl.glDepthMask(false);

        try {
            int stage = stageForProgress(miningProgress);
            if (stage >= 0) {
                fillCrackVertices(
                        minX - CRACK_EXPAND, minY - CRACK_EXPAND, minZ - CRACK_EXPAND,
                        maxX + CRACK_EXPAND, maxY + CRACK_EXPAND, maxZ + CRACK_EXPAND,
                        stage
                );
                destroyTexture.bind(0);
                shader.setUniform1i("uUseTexture", 1);
                shader.setUniformVec4("uTintColor", 1.0f, 1.0f, 1.0f, 0.78f);
                Gdx.gl.glEnable(GL20.GL_CULL_FACE);
                crackMesh.setVertices(crackVertices, 0, crackVertices.length);
                crackMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES, 0, CRACK_VERTEX_COUNT);
            }

            fillOutlineVertices(
                    minX - OUTLINE_EXPAND, minY - OUTLINE_EXPAND, minZ - OUTLINE_EXPAND,
                    maxX + OUTLINE_EXPAND, maxY + OUTLINE_EXPAND, maxZ + OUTLINE_EXPAND
            );
            shader.setUniform1i("uUseTexture", 0);
            shader.setUniformVec4("uTintColor", 0.0f, 0.0f, 0.0f, OUTLINE_ALPHA);
            Gdx.gl.glDisable(GL20.GL_CULL_FACE);
            lineMesh.setVertices(lineVertices, 0, lineVertices.length);
            lineMesh.render(shader.getGdxShader(), GL20.GL_LINES, 0, LINE_VERTEX_COUNT);
        } finally {
            shader.setUniform1i("uUseTexture", 1);
            shader.setUniformVec4("uTintColor", 1.0f, 1.0f, 1.0f, 1.0f);
            Gdx.gl.glDepthMask(true);
            Gdx.gl.glEnable(GL20.GL_CULL_FACE);
            Gdx.gl.glDisable(GL20.GL_BLEND);
        }
    }

    /** Điền trực tiếp 12 cạnh (24 đỉnh) của hộp khung dây vào mảng {@link #lineVertices} tại chỗ (zero-GC). */
    void fillOutlineVertices(float x0, float y0, float z0, float x1, float y1, float z1) {
        int offset = 0;
        // 4 cạnh đáy (Y = y0)
        offset = putSegment(lineVertices, offset, x0, y0, z0, x1, y0, z0);
        offset = putSegment(lineVertices, offset, x1, y0, z0, x1, y0, z1);
        offset = putSegment(lineVertices, offset, x1, y0, z1, x0, y0, z1);
        offset = putSegment(lineVertices, offset, x0, y0, z1, x0, y0, z0);
        // 4 cạnh đỉnh (Y = y1)
        offset = putSegment(lineVertices, offset, x0, y1, z0, x1, y1, z0);
        offset = putSegment(lineVertices, offset, x1, y1, z0, x1, y1, z1);
        offset = putSegment(lineVertices, offset, x1, y1, z1, x0, y1, z1);
        offset = putSegment(lineVertices, offset, x0, y1, z1, x0, y1, z0);
        // 4 cạnh đứng nối đáy và đỉnh
        offset = putSegment(lineVertices, offset, x0, y0, z0, x0, y1, z0);
        offset = putSegment(lineVertices, offset, x1, y0, z0, x1, y1, z0);
        offset = putSegment(lineVertices, offset, x1, y0, z1, x1, y1, z1);
        putSegment(lineVertices, offset, x0, y0, z1, x0, y1, z1);
    }

    /** Điền trực tiếp 6 mặt (36 đỉnh tam giác) của hộp vết nứt vào {@link #crackVertices} tại chỗ (zero-GC). */
    void fillCrackVertices(float x0, float y0, float z0, float x1, float y1, float z1, int stage) {
        float stageWidth = 1.0f / STAGE_COUNT;
        float epsU = 0.0005f;
        float u0 = stage * stageWidth + epsU;
        float u1 = (stage + 1) * stageWidth - epsU;
        float v0 = 0.0f;
        float v1 = 1.0f;

        int offset = 0;
        // Mặt trên (+Y) và mặt dưới (-Y)
        offset = putQuad(crackVertices, offset, x0, y1, z1, x1, y1, z1, x1, y1, z0, x0, y1, z0, u0, v0, u1, v1, 1.00f);
        offset = putQuad(crackVertices, offset, x0, y0, z0, x1, y0, z0, x1, y0, z1, x0, y0, z1, u0, v0, u1, v1, 0.55f);
        // Mặt Nam (+Z) và mặt Bắc (-Z)
        offset = putQuad(crackVertices, offset, x0, y0, z1, x1, y0, z1, x1, y1, z1, x0, y1, z1, u0, v0, u1, v1, 0.85f);
        offset = putQuad(crackVertices, offset, x1, y0, z0, x0, y0, z0, x0, y1, z0, x1, y1, z0, u0, v0, u1, v1, 0.85f);
        // Mặt Đông (+X) và mặt Tây (-X)
        offset = putQuad(crackVertices, offset, x1, y0, z1, x1, y0, z0, x1, y1, z0, x1, y1, z1, u0, v0, u1, v1, 0.72f);
        putQuad(crackVertices, offset, x0, y0, z0, x0, y0, z1, x0, y1, z1, x0, y1, z0, u0, v0, u1, v1, 0.72f);
    }

    /** Ghi một đoạn thẳng gồm 2 đỉnh vào mảng {@code out} với {@code shade = -1.0f} (màu thuần không nhân ánh sáng). */
    private static int putSegment(float[] out, int offset,
                                  float ax, float ay, float az,
                                  float bx, float by, float bz) {
        offset = putVertex(out, offset, ax, ay, az, 0.0f, 0.0f, -1.0f);
        return putVertex(out, offset, bx, by, bz, 0.0f, 0.0f, -1.0f);
    }

    /** Ghi một mặt tứ giác gồm 2 tam giác (6 đỉnh) theo thứ tự ngược chiều kim đồng hồ nhìn từ ngoài. */
    private static int putQuad(float[] out, int offset,
                               float ax, float ay, float az,
                               float bx, float by, float bz,
                               float cx, float cy, float cz,
                               float dx, float dy, float dz,
                               float u0, float v0, float u1, float v1, float shade) {
        offset = putVertex(out, offset, ax, ay, az, u0, v1, shade);
        offset = putVertex(out, offset, bx, by, bz, u1, v1, shade);
        offset = putVertex(out, offset, cx, cy, cz, u1, v0, shade);
        offset = putVertex(out, offset, ax, ay, az, u0, v1, shade);
        offset = putVertex(out, offset, cx, cy, cz, u1, v0, shade);
        return putVertex(out, offset, dx, dy, dz, u0, v0, shade);
    }

    /** Ghi 6 float của một đỉnh vào bộ đệm tại vị trí {@code offset}. */
    private static int putVertex(float[] out, int offset,
                                 float x, float y, float z,
                                 float u, float v, float shade) {
        out[offset] = x;
        out[offset + 1] = y;
        out[offset + 2] = z;
        out[offset + 3] = u;
        out[offset + 4] = v;
        out[offset + 5] = shade;
        return offset + FLOATS_PER_VERTEX;
    }

    /** Giải phóng 2 {@link Mesh} và texture atlas vết nứt {@code 160x16} trên GPU. */
    @Override
    public void dispose() {
        if (disposed) {
            return;
        }
        disposed = true;
        if (lineMesh != null) {
            lineMesh.dispose();
        }
        if (crackMesh != null) {
            crackMesh.dispose();
        }
        if (destroyTexture != null) {
            destroyTexture.dispose();
        }
    }
}

package com.voxelgame.client.render;

import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.Matrix4;
import com.badlogic.gdx.math.Vector3;

/**
 * Quản lý góc nhìn thứ nhất (First-Person Camera) trong không gian 3 chiều và phép chiếu 2D cho giao diện.
 *
 * THỂ HIỆN TÍNH ĐÓNG GÓI (ENCAPSULATION - DEFENSIVE COPYING):
 * - Toàn bộ các vector cơ sở nội bộ (`position`, `front`, `up`, `right`, `worldUp`) được khóa `private final`.
 * - Các phương thức truy vấn `getPosition()`, `getFront()`, `getRight()`, `getUp()` luôn trả về một bản sao
 *   độc lập (`new Vector3(...)`), ngăn chặn tuyệt đối việc các lớp bên ngoài vô tình gọi sửa trực tiếp
 *   làm biến dạng hệ trục tọa độ của Camera.
 */
public class Camera {

    /** Màu, khoảng sương và độ đậm lớp phủ dùng chung cho mọi lượt vẽ khi mắt chìm. */
    public enum LiquidView {
        AIR(0f, 0f, 0f, 0f, 0f, 0f),
        WATER(0.035f, 0.18f, 0.27f, 1f, 22f, 0.23f),
        LAVA(0.64f, 0.12f, 0.015f, 0.25f, 1.6f, 0.68f);

        public final float red;
        public final float green;
        public final float blue;
        public final float fogStart;
        public final float fogEnd;
        public final float tintAlpha;

        /** Lưu bộ thông số cố định để dùng lại mỗi khung hình. */
        LiquidView(float red, float green, float blue, float fogStart, float fogEnd, float tintAlpha) {
            this.red = red;
            this.green = green;
            this.blue = blue;
            this.fogStart = fogStart;
            this.fogEnd = fogEnd;
            this.tintAlpha = tintAlpha;
        }
    }

    /** Chọn môi trường từ mắt camera, kể cả lúc người chơi đang ngồi trên thú. */
    public LiquidView liquidView(World world) {
        Block liquid = world.liquidAt(position.x, position.y, position.z);
        if (liquid == Block.WATER) {
            return LiquidView.WATER;
        }
        return liquid == Block.LAVA ? LiquidView.LAVA : LiquidView.AIR;
    }

    // Tọa độ vị trí mắt của Camera trong không gian thế giới (World Space)
    private final Vector3 position;

    // 3 vector cơ sở vuông góc từng đôi một xác định hệ trục tọa độ gắn liền với mắt người chơi
    private final Vector3 front;   // Hướng đang nhìn thẳng tới trước
    private final Vector3 up;      // Hướng đỉnh đầu của Camera
    private final Vector3 right;   // Hướng bên tay phải của Camera
    private final Vector3 worldUp; // Hướng thẳng đứng cố định của thế giới (0, 1, 0)

    // Vector đích nhìn tạm thời được tái sử dụng để tránh cấp phát rác GC trong Game Loop
    private final Vector3 lookTarget = new Vector3();

    // Góc quay Euler (đơn vị: độ - Degrees)
    private float yaw = -90.0f;
    private float pitch = 0.0f;

    // Các thông số ống kính 3D (Frustum)
    private static final float BASE_FOV_DEG = 70.0f;
    private float currentFovDeg = BASE_FOV_DEG;
    /** Độ thu hẹp góc nhìn (độ âm, tối đa -8 độ) khi kéo dây cung và giá trị mục tiêu để nội suy mượt. */
    private float bowZoomOffsetDeg = 0.0f;
    private float targetBowZoomOffsetDeg = 0.0f;
    private static final float BOW_ZOOM_LERP_SPEED = 16.0f;
    private static final float NEAR_PLANE = 0.08f;
    // Giới hạn chiều sâu kết xuất để giữ ngân sách vẽ khi thế giới mở rộng.
    private static final float FAR_PLANE = 1024.0f;

    // Bộ đệm ma trận được tái sử dụng mỗi khung hình để tránh tạo rác bộ nhớ (Garbage Collection)
    private final Matrix4 viewMatrix = new Matrix4();
    private final Matrix4 projectionMatrix = new Matrix4();
    private final Matrix4 orthoMatrix = new Matrix4();

    public Camera() {
        this.position = new Vector3(0.0f, 0.0f, 0.0f);
        this.front = new Vector3(0.0f, 0.0f, -1.0f);
        this.up = new Vector3(0.0f, 1.0f, 0.0f);
        this.right = new Vector3(1.0f, 0.0f, 0.0f);
        this.worldUp = new Vector3(0.0f, 1.0f, 0.0f);

        updateCameraVectors();
    }

    /**
     * Xoay góc nhìn Camera dựa trên độ dịch chuyển của con trỏ chuột.
     *
     * @param yawOffset độ dịch chuyển góc nhìn ngang
     * @param pitchOffset độ dịch chuyển góc nhìn dọc
     */
    public void rotate(float yawOffset, float pitchOffset) {
        yaw += yawOffset;
        pitch += pitchOffset;

        // Giới hạn góc nhìn dọc trong khoảng [-89.0, 89.0] độ để chống hiện tượng Gimbal Lock
        if (pitch > 89.0f) {
            pitch = 89.0f;
        }
        if (pitch < -89.0f) {
            pitch = -89.0f;
        }

        updateCameraVectors();
    }

    private void updateCameraVectors() {
        double yawRad = Math.toRadians(yaw);
        double pitchRad = Math.toRadians(pitch);

        front.x = (float) (Math.cos(yawRad) * Math.cos(pitchRad));
        front.y = (float) Math.sin(pitchRad);
        front.z = (float) (Math.sin(yawRad) * Math.cos(pitchRad));
        front.nor();

        right.set(front).crs(worldUp).nor();
        up.set(right).crs(front).nor();
    }

    /**
     * Cập nhật hiệu ứng mở rộng nhẹ góc nhìn (Dynamic FOV) khi người chơi Chạy nhanh (Sprint) hoặc Bay (Fly).
     *
     * @param isSprinting cờ người chơi đang chạy nhanh
     * @param isFlying cờ người chơi đang bay
     * @param deltaTime thời gian giữa hai khung hình
     */
    public void updateDynamicFov(boolean isSprinting, boolean isFlying, float deltaTime) {
        float targetFovDeg = BASE_FOV_DEG;
        if (isSprinting) {
            targetFovDeg += 8.0f;
        }
        if (isFlying) {
            targetFovDeg += 5.0f;
        }
        float lerpSpeed = Math.min(1.0f, deltaTime * 10.0f);
        currentFovDeg += (targetFovDeg - currentFovDeg) * lerpSpeed;
    }

    /**
     * Cập nhật mượt độ thu hẹp FOV khi kéo cung mà không làm thay đổi Dynamic FOV của Sprint/Fly.
     *
     * @param targetOffsetDeg độ lệch FOV mục tiêu (ví dụ {@code -8.0f * pullProgress})
     * @param deltaTime       thời gian giữa hai khung hình
     */
    public void updateBowZoom(float targetOffsetDeg, float deltaTime) {
        targetBowZoomOffsetDeg = Float.isFinite(targetOffsetDeg) ? targetOffsetDeg : 0.0f;
        if (deltaTime > 0.0f && Float.isFinite(deltaTime)) {
            float lerpSpeed = Math.min(1.0f, deltaTime * BOW_ZOOM_LERP_SPEED);
            bowZoomOffsetDeg += (targetBowZoomOffsetDeg - bowZoomOffsetDeg) * lerpSpeed;
        }
    }

    /**
     * Đặt trực tiếp độ lệch FOV kéo cung (dùng khi hủy trạng thái kéo cung do đổi ô Hotbar).
     *
     * @param offsetDeg độ lệch FOV cần áp dụng ngay lập tức
     */
    public void setBowZoomOffset(float offsetDeg) {
        float safe = Float.isFinite(offsetDeg) ? offsetDeg : 0.0f;
        targetBowZoomOffsetDeg = safe;
        bowZoomOffsetDeg = safe;
    }

    /** Trả về độ lệch FOV kéo cung hiện tại (0.0f khi không kéo cung). */
    public float getBowZoomOffset() {
        return bowZoomOffsetDeg;
    }

    /** Trả về góc FOV hiệu dụng (đã cộng cả Dynamic FOV lẫn độ lệch kéo cung). */
    public float getCurrentFovDeg() {
        return Math.max(30.0f, Math.min(110.0f, currentFovDeg + bowZoomOffsetDeg));
    }

    /**
     * Trả về Ma trận Nhìn (View Matrix) dùng phép biến đổi `lookAt(eye, center, up)`.
     * Tái sử dụng đối tượng viewMatrix có sẵn, không cấp phát thêm bộ nhớ.
     *
     * @return ma trận nhìn Matrix4
     */
    public Matrix4 getViewMatrix() {
        lookTarget.set(position).add(front);
        return viewMatrix.setToLookAt(position, lookTarget, up);
    }

    /**
     * Trả về Ma trận Chiếu phối cảnh 3D (Perspective Projection Matrix).
     *
     * @param windowWidth chiều rộng màn hình
     * @param windowHeight chiều cao màn hình
     * @return ma trận chiếu phối cảnh Matrix4
     */
    public Matrix4 getProjectionMatrix(int windowWidth, int windowHeight) {
        float aspectRatio = (float) Math.max(1, windowWidth) / Math.max(1, windowHeight);
        return projectionMatrix.setToProjection(NEAR_PLANE, FAR_PLANE, getCurrentFovDeg(), aspectRatio);
    }

    /**
     * Trả về Ma trận Chiếu trực giao 2D (Orthographic Projection Matrix) phục vụ vẽ giao diện (UI).
     * Trục Y đi từ 0 (đỉnh màn hình) xuống windowHeight (đáy màn hình), khớp 100% với hệ tọa độ Top-Left.
     *
     * @param windowWidth chiều rộng màn hình
     * @param windowHeight chiều cao màn hình
     * @return ma trận trực giao Matrix4
     */
    public Matrix4 getOrthoMatrix(int windowWidth, int windowHeight) {
        return orthoMatrix.setToOrtho(0.0f, windowWidth, windowHeight, 0.0f, -1.0f, 1.0f);
    }

    /**
     * Trả về bản sao (Defensive Copy) vị trí mắt Camera.
     *
     * @return đối tượng Vector3 mới chứa vị trí
     */
    public Vector3 getPosition() {
        return new Vector3(position);
    }

    /** Chép vị trí mắt vào bộ đệm của vòng lặp kết xuất. */
    public Vector3 copyPosition(Vector3 target) {
        return target.set(position);
    }

    public void setPosition(float x, float y, float z) {
        this.position.set(x, y, z);
    }

    /**
     * Trả về bản sao (Defensive Copy) vector hướng nhìn phía trước.
     *
     * @return đối tượng Vector3 mới chứa hướng nhìn
     */
    public Vector3 getFront() {
        return new Vector3(front);
    }

    /** Chép hướng nhìn vào bộ đệm dùng lại cho raycast. */
    public Vector3 copyFront(Vector3 target) {
        return target.set(front);
    }

    /**
     * Trả về bản sao (Defensive Copy) vector hướng bên phải.
     *
     * @return đối tượng Vector3 mới chứa hướng phải
     */
    public Vector3 getRight() {
        return new Vector3(right);
    }

    /**
     * Trả về bản sao (Defensive Copy) vector hướng đỉnh đầu Camera.
     *
     * @return đối tượng Vector3 mới chứa hướng đỉnh đầu
     */
    public Vector3 getUp() {
        return new Vector3(up);
    }

    public float getYaw() {
        return yaw;
    }

    public float getPitch() {
        return pitch;
    }
}

package com.voxelgame.client.render;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Mesh;
import com.badlogic.gdx.graphics.Texture;
import com.badlogic.gdx.graphics.VertexAttribute;
import com.badlogic.gdx.graphics.VertexAttributes;
import com.badlogic.gdx.utils.Disposable;

/** Bộ đệm tam giác dùng lại cho vòm trời, thiên thể, mây và các dải giáng thủy. */
final class EnvironmentMesh implements Disposable {
    /** Cùng định dạng sáu số thực với shader của thế giới. */
    private static final int STRIDE = 6;
    private final Mesh mesh;
    private final float[] data;
    private int size;

    /** Cấp phát một lần theo số tứ giác tối đa của một lượt vẽ. */
    EnvironmentMesh(int maxQuads) {
        int maxVertices = maxQuads * 6;
        mesh = new Mesh(Mesh.VertexDataType.VertexBufferObjectWithVAO, false, maxVertices, 0,
                new VertexAttribute(VertexAttributes.Usage.Position, 3, "aPos"),
                new VertexAttribute(VertexAttributes.Usage.TextureCoordinates, 2, "aTexCoord"),
                new VertexAttribute(VertexAttributes.Usage.Generic, 1, "aShade"));
        data = new float[maxVertices * STRIDE];
    }

    /** Đưa con trỏ về đầu mảng để dựng hình cho lượt kế tiếp. */
    void clear() {
        size = 0;
    }

    /** Thêm hai tam giác theo thứ tự góc trên trái, dưới trái, dưới phải, trên phải. */
    void quad(float ax, float ay, float az, float bx, float by, float bz,
              float cx, float cy, float cz, float dx, float dy, float dz,
              float u0, float v0, float u1, float v1, float shade) {
        vertex(ax, ay, az, u0, v0, shade);
        vertex(bx, by, bz, u0, v1, shade);
        vertex(cx, cy, cz, u1, v1, shade);
        vertex(ax, ay, az, u0, v0, shade);
        vertex(cx, cy, cz, u1, v1, shade);
        vertex(dx, dy, dz, u1, v0, shade);
    }

    /** Ghi tọa độ, UV và hệ số sáng vào vị trí đỉnh kế tiếp. */
    private void vertex(float x, float y, float z, float u, float v, float shade) {
        data[size++] = x;
        data[size++] = y;
        data[size++] = z;
        data[size++] = u;
        data[size++] = v;
        data[size++] = shade;
    }

    /** Gửi phần mảng đang dùng tới VBO. */
    void upload() {
        if (size > 0) {
            mesh.setVertices(data, 0, size);
        }
    }

    /** Vẽ số đỉnh vừa dựng, ngay cả khi VBO còn chứa dữ liệu từ lượt trước. */
    void draw(ShaderProgram shader) {
        if (size > 0) {
            mesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES, 0, size / STRIDE);
        }
    }

    /** Đọc ảnh từ classpath; cạnh lặp dùng cho mây và giáng thủy. */
    static Texture loadTexture(String name, Texture.TextureWrap wrapU, Texture.TextureWrap wrapV) {
        Texture texture = new Texture(Gdx.files.classpath("textures/environment/" + name));
        texture.setFilter(Texture.TextureFilter.Nearest, Texture.TextureFilter.Nearest);
        texture.setWrap(wrapU, wrapV);
        return texture;
    }

    /** Hủy VAO và VBO của lượt vẽ. */
    @Override
    public void dispose() {
        mesh.dispose();
    }
}

package com.voxelgame.client.render;

import com.voxelgame.client.model.ModelPart;
import com.voxelgame.world.entity.player.Hotbar;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.item.ItemUseHandler;
import com.voxelgame.world.level.block.Block;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.files.FileHandle;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Mesh;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.VertexAttribute;
import com.badlogic.gdx.graphics.VertexAttributes;
import com.badlogic.gdx.graphics.VertexAttributes.Usage;
import com.badlogic.gdx.math.Matrix4;
import com.badlogic.gdx.math.Vector3;
import com.badlogic.gdx.utils.Disposable;

/**
 * Hệ thống kết xuất mô hình tay & vật phẩm ở góc nhìn thứ nhất (Viewmodel)
 * và mô hình nhân vật {@code steve.png} ở góc nhìn thứ 3 ({@code F5}), triển khai {@link Disposable}.
 *
 * <p>Thiết kế tuân thủ zero-GC trong vòng lặp vẽ: toàn bộ {@link Mesh}, {@link Matrix4} và {@link Vector3}
 * được cấp phát một lần khi khởi tạo hoặc lưu trữ vào bộ đệm tĩnh tái sử dụng mọi khung hình,
 * đồng thời giải phóng toàn bộ tài nguyên GPU qua {@link #dispose()}.</p>
 */
public final class FirstPersonRenderer implements Disposable {

    /** Đường dẫn tài nguyên skin người chơi 64×64 và trang bị cầm tay 128×80. */
    private static final String STEVE_SKIN_PATH = "textures/entity/player/steve.png";
    private static final String HELD_EQUIPMENT_PATH = "textures/entity/equipment/held.png";

    /** Kích thước tấm ảnh chuẩn và tỉ lệ quy đổi pixel sang block cho nhân vật góc nhìn thứ 3. */
    private static final int STEVE_TEX_SIZE = 64;
    private static final int HELD_TEX_WIDTH = 128;
    private static final int HELD_TEX_HEIGHT = 80;
    private static final float PIXEL_TO_BLOCK = 1.0f / 16.0f;
    private static final float PLAYER_PIXEL_SCALE = 1.8f / 32.0f;

    /** Định dạng đỉnh 6 float dùng chung với {@link ShaderProgram}: aPos(3), aTexCoord(2), aShade(1). */
    private static final VertexAttributes VERTEX_ATTRIBUTES = new VertexAttributes(
            new VertexAttribute(Usage.Position, 3, "aPos"),
            new VertexAttribute(Usage.TextureCoordinates, 2, "aTexCoord"),
            new VertexAttribute(Usage.Generic, 1, "aShade")
    );

    /** Texture GPU cho skin Steve và bộ trang bị cung/giáo. */
    private com.badlogic.gdx.graphics.Texture steveTexture;
    private com.badlogic.gdx.graphics.Texture heldTexture;

    /** Các lưới tĩnh dựng sẵn cho tay phải góc nhìn 1, 4 khung cung, giáo sắt và 6 bộ phận góc nhìn 3. */
    private Mesh armMesh;
    private final Mesh[] bowMeshes = new Mesh[4];
    private Mesh spearMesh;

    /** Cache lưới cho item 2D độc lập (theo {@code atlasTileIndex}) và block 3D thu nhỏ (theo block ID). */
    private final Mesh[] itemMeshes = new Mesh[64];
    private final Mesh[] blockMeshes = new Mesh[256];

    /** Sáu bộ phận hình học humanoid (đầu, thân, hai tay, hai chân) của người chơi góc nhìn thứ 3. */
    private Mesh thirdHeadMesh;
    private Mesh thirdBodyMesh;
    private Mesh thirdRightArmMesh;
    private Mesh thirdLeftArmMesh;
    private Mesh thirdRightLegMesh;
    private Mesh thirdLeftLegMesh;

    /** Ma trận và vector thành viên tái sử dụng mỗi khung hình (zero-GC). */
    private final Matrix4 identityMatrix = new Matrix4();
    private final Matrix4 viewmodelProjection = new Matrix4();
    private final Matrix4 modelMatrix = new Matrix4();
    private final Matrix4 rootMatrix = new Matrix4();
    private final Matrix4 partMatrix = new Matrix4();
    private final Matrix4 heldThirdMatrix = new Matrix4();
    private final Vector3 tmpPos = new Vector3();

    private float animationClock;
    private boolean glInitialized;
    private boolean disposed;

    /**
     * Khởi tạo bộ kết xuất góc nhìn thứ nhất và góc nhìn thứ ba.
     * Nếu gọi trong môi trường kiểm thử CPU không có ngữ cảnh OpenGL ({@code Gdx.gl == null}),
     * quá trình tạo tài nguyên GPU được bỏ qua an toàn.
     */
    public FirstPersonRenderer() {
        if (Gdx.gl != null && Gdx.files != null) {
            initGlResources();
        }
    }

    /** Nạp texture và dựng trước toàn bộ lưới tĩnh trên luồng có ngữ cảnh OpenGL. */
    private void initGlResources() {
        if (glInitialized || disposed) {
            return;
        }
        try {
            steveTexture = loadTextureSafe(STEVE_SKIN_PATH, 0x3C70B5);
            heldTexture = loadTextureSafe(HELD_EQUIPMENT_PATH, 0x8A7059);

            // Cánh tay phải ở góc nhìn thứ 1: dùng UV cánh tay phải của Steve (40, 16) kích thước 4×12×4
            armMesh = buildBoxMesh(0f, -6f, -2f, 4, 12, 4, 40, 16, false);

            // 4 khung kéo dây cung trên equipment/held.png (x = 0, 32, 64, 96; y = 64; 16×16)
            for (int i = 0; i < bowMeshes.length; i++) {
                bowMeshes[i] = buildDoubleSidedQuadMesh(
                        (i * 32.0f) / HELD_TEX_WIDTH,
                        64.0f / HELD_TEX_HEIGHT,
                        (i * 32.0f + 16.0f) / HELD_TEX_WIDTH,
                        (64.0f + 16.0f) / HELD_TEX_HEIGHT
                );
            }

            // Giáo sắt trên equipment/held.png (x = 0, y = 0, 16×16)
            spearMesh = buildDoubleSidedQuadMesh(
                    0.0f,
                    0.0f,
                    16.0f / HELD_TEX_WIDTH,
                    16.0f / HELD_TEX_HEIGHT
            );

            // 6 bộ phận nhân vật góc nhìn thứ 3 theo chuẩn skin 64×64
            thirdHeadMesh = buildBoxMesh(-4f, 0f, -4f, 8, 8, 8, 0, 0, false);
            thirdBodyMesh = buildBoxMesh(-4f, 0f, -2f, 8, 12, 4, 16, 16, false);
            thirdRightArmMesh = buildBoxMesh(-1f, -10f, -2f, 4, 12, 4, 40, 16, false);
            thirdLeftArmMesh = buildBoxMesh(-3f, -10f, -2f, 4, 12, 4, 32, 48, false);
            thirdRightLegMesh = buildBoxMesh(-2f, -12f, -2f, 4, 12, 4, 0, 16, false);
            thirdLeftLegMesh = buildBoxMesh(-2f, -12f, -2f, 4, 12, 4, 16, 48, false);

            glInitialized = true;
        } catch (RuntimeException | Error failure) {
            dispose();
            throw failure;
        }
    }

    /**
     * Kết xuất tay phải hoặc vật phẩm đang cầm ở góc nhìn thứ nhất, tự động xóa Depth Buffer
     * để tay/vật phẩm không bao giờ cắt xuyên tường và khôi phục đầy đủ trạng thái OpenGL/Shader.
     *
     * @param shader         chương trình shader đang bind
     * @param player         người chơi hiện tại
     * @param useHandler     bộ quản lý trạng thái kéo cung/hạ giáo/ăn/uống
     * @param blockAtlas     texture atlas các khối 3D
     * @param itemAtlas      texture atlas vật phẩm 2D
     * @param viewportAspect tỉ lệ khung hình {@code width / height}
     */
    public void render(ShaderProgram shader, Player player, ItemUseHandler useHandler,
                       Texture blockAtlas, ItemTextureAtlas itemAtlas, float viewportAspect) {
        renderFirstPerson(shader, player, useHandler, blockAtlas, itemAtlas, null, null, viewportAspect);
    }

    /**
     * Kết xuất lớp phủ góc nhìn thứ nhất (First-Person Viewmodel) với đầy đủ hiệu ứng
     * View Bobbing, Swing, kéo cung 4 khung, hạ giáo Charge và nâng đồ ăn/thuốc,
     * sau đó khôi phục ma trận chiếu & ma trận nhìn thế giới cho các lượt vẽ kế tiếp.
     */
    public void renderFirstPerson(ShaderProgram shader, Player player, ItemUseHandler useHandler,
                                  Texture blockAtlas, ItemTextureAtlas itemAtlas,
                                  Matrix4 worldProjection, Matrix4 worldView, float viewportAspect) {
        if (disposed || shader == null || player == null || Gdx.gl == null) {
            return;
        }
        if (player.getCameraMode() != Player.CameraMode.FIRST_PERSON) {
            return;
        }
        if (!glInitialized) {
            initGlResources();
        }

        float dt = Gdx.graphics != null ? Math.min(Gdx.graphics.getDeltaTime(), 0.05f) : 0.0f;
        animationClock += dt;

        // Xóa bộ đệm chiều sâu để tay và vật phẩm góc nhìn 1 luôn nằm trước địa hình
        Gdx.gl.glClear(GL20.GL_DEPTH_BUFFER_BIT);
        Gdx.gl.glEnable(GL20.GL_DEPTH_TEST);
        Gdx.gl.glEnable(GL20.GL_CULL_FACE);
        Gdx.gl.glCullFace(GL20.GL_BACK);
        Gdx.gl.glDisable(GL20.GL_BLEND);

        try {
            shader.enableChunkColorMode(false);
            shader.setUniform1i("uEnvironmentMode", 0);
            shader.disableDistanceFog();
            shader.setUniform1i("uUseTexture", 1);
            shader.setUniformVec4("uTintColor", 1.0f, 1.0f, 1.0f, 1.0f);
            shader.setUniform1f("uMobWhiteFlash", 0.0f);
            shader.setUniformVec3("uWorldLight", 1.0f, 1.0f, 1.0f);

            float safeAspect = Math.max(0.1f, viewportAspect);
            viewmodelProjection.setToProjection(0.05f, 10.0f, 70.0f, safeAspect);
            shader.setUniformMatrix4f("uProjection", viewmodelProjection);
            shader.setUniformMatrix4f("uView", identityMatrix);

            Hotbar hotbar = player.getHotbar();
            Item held = (hotbar != null && hotbar.getSelectedCount() > 0) ? hotbar.getSelectedItem() : Item.NONE;

            float bobPhase = player.getBobPhase();
            float bobStrength = player.getBobStrength();
            float bobX = (float) Math.sin(bobPhase) * 0.025f * bobStrength;
            float bobY = -(float) Math.abs(Math.cos(bobPhase)) * 0.025f * bobStrength;

            float swing = player.getSwingProgress();
            float swingSin = (float) Math.sin(swing * Math.PI);
            float swingSqrt = (float) Math.sin(Math.sqrt(swing) * Math.PI);

            ItemUseHandler.UseState useState = useHandler != null ? useHandler.getUseState() : ItemUseHandler.UseState.NONE;
            float useProgress = useHandler != null ? useHandler.getUseProgress() : 0.0f;

            if (held == null || held.isNone()) {
                renderFirstPersonArm(shader, bobX, bobY, swingSin, swingSqrt);
            } else if (held.isBlock()) {
                renderFirstPersonBlock(shader, blockAtlas, held.getBlock(), bobX, bobY, swingSin, swingSqrt);
            } else if (held == Item.BOW) {
                float pull = (useState == ItemUseHandler.UseState.DRAW_BOW && useHandler != null)
                        ? useHandler.getBowPullProgress() : 0.0f;
                renderFirstPersonBow(shader, bobX, bobY, swingSin, swingSqrt, pull);
            } else if (held == Item.IRON_SPEAR) {
                float charge = (useState == ItemUseHandler.UseState.CHARGE_SPEAR) ? useProgress : 0.0f;
                renderFirstPersonSpear(shader, bobX, bobY, swingSin, swingSqrt, charge);
            } else {
                boolean consuming = useState == ItemUseHandler.UseState.EAT_FOOD
                        || useState == ItemUseHandler.UseState.DRINK_POTION;
                renderFirstPersonItem(shader, itemAtlas, held, bobX, bobY, swingSin, swingSqrt,
                        consuming ? useProgress : 0.0f, consuming);
            }
        } finally {
            shader.setUniformMatrix4f("uModel", identityMatrix);
            shader.setUniformVec4("uTintColor", 1.0f, 1.0f, 1.0f, 1.0f);
            shader.setUniform1i("uUseTexture", 1);
            shader.setUniform1f("uMobWhiteFlash", 0.0f);
            if (worldProjection != null) {
                shader.setUniformMatrix4f("uProjection", worldProjection);
            }
            if (worldView != null) {
                shader.setUniformMatrix4f("uView", worldView);
            }
            if (blockAtlas != null) {
                blockAtlas.bind();
            }
            Gdx.gl.glEnable(GL20.GL_DEPTH_TEST);
            Gdx.gl.glEnable(GL20.GL_CULL_FACE);
            Gdx.gl.glDisable(GL20.GL_BLEND);
        }
    }

    /**
     * Kết xuất mô hình nhân vật người chơi bằng skin {@code steve.png} ở góc nhìn thứ 3
     * ({@code THIRD_BACK} / {@code THIRD_FRONT}) ngay trong không gian thế giới hiện tại.
     */
    public void renderThirdPersonPlayer(ShaderProgram shader, Player player, ItemUseHandler useHandler,
                                        Texture blockAtlas, ItemTextureAtlas itemAtlas) {
        if (disposed || shader == null || player == null || Gdx.gl == null) {
            return;
        }
        if (player.getCameraMode() == Player.CameraMode.FIRST_PERSON) {
            return;
        }
        if (!glInitialized) {
            initGlResources();
        }

        Gdx.gl.glEnable(GL20.GL_DEPTH_TEST);
        Gdx.gl.glEnable(GL20.GL_CULL_FACE);
        Gdx.gl.glCullFace(GL20.GL_BACK);
        Gdx.gl.glDisable(GL20.GL_BLEND);

        try {
            shader.enableChunkColorMode(false);
            shader.setUniform1i("uEnvironmentMode", 0);
            shader.setUniform1i("uUseTexture", 1);
            shader.setUniform1f("uMobWhiteFlash", 0.0f);
            if (player.getHurtFlashTimer() > 0.0f) {
                shader.setUniformVec4("uTintColor", 1.0f, 0.45f, 0.45f, 1.0f);
            } else {
                shader.setUniformVec4("uTintColor", 1.0f, 1.0f, 1.0f, 1.0f);
            }

            player.copyPosition(tmpPos);
            Camera cam = player.getAttachedCamera();
            float bodyYawDeg = cam != null ? -(cam.getYaw() + 90.0f) : 0.0f;
            float headPitchDeg = cam != null ? cam.getPitch() : 0.0f;
            boolean sneaking = player.isSneaking();
            float sneakDrop = sneaking ? -0.125f : 0.0f;
            float torsoLeanDeg = sneaking ? -24.0f : 0.0f;

            rootMatrix.idt()
                    .translate(tmpPos.x, tmpPos.y + sneakDrop, tmpPos.z)
                    .rotate(Vector3.Y, bodyYawDeg)
                    .scale(PLAYER_PIXEL_SCALE, PLAYER_PIXEL_SCALE, PLAYER_PIXEL_SCALE);

            float walkAngle = (float) Math.cos(player.getLimbSwing()) * player.getLimbSwingAmount() * 55.0f;
            float swingSin = (float) Math.sin(player.getSwingProgress() * Math.PI);

            ItemUseHandler.UseState useState = useHandler != null ? useHandler.getUseState() : ItemUseHandler.UseState.NONE;
            float useProgress = useHandler != null ? useHandler.getUseProgress() : 0.0f;

            steveTexture.bind(0);

            // 1. Hai chân (xoay tại hông Y = 12)
            partMatrix.set(rootMatrix).translate(2.0f, 12.0f, 0.0f).rotate(Vector3.X, -walkAngle);
            shader.setUniformMatrix4f("uModel", partMatrix);
            thirdRightLegMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);

            partMatrix.set(rootMatrix).translate(-2.0f, 12.0f, 0.0f).rotate(Vector3.X, walkAngle);
            shader.setUniformMatrix4f("uModel", partMatrix);
            thirdLeftLegMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);

            // 2. Thân (xoay tại hông Y = 12 khi cúi rón rén)
            partMatrix.set(rootMatrix).translate(0.0f, 12.0f, 0.0f).rotate(Vector3.X, torsoLeanDeg);
            shader.setUniformMatrix4f("uModel", partMatrix);
            thirdBodyMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);

            // 3. Đầu (xoay theo góc ngẩng/cúi của camera)
            float headY = sneaking ? 22.8f : 24.0f;
            float headZ = sneaking ? -4.2f : 0.0f;
            partMatrix.set(rootMatrix).translate(0.0f, headY, headZ).rotate(Vector3.X, headPitchDeg);
            shader.setUniformMatrix4f("uModel", partMatrix);
            thirdHeadMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);

            // 4. Tay trái
            float leftArmX = -walkAngle * 0.8f;
            float leftArmY = 0.0f;
            if (useState == ItemUseHandler.UseState.DRAW_BOW) {
                leftArmX = 85.0f + headPitchDeg;
                leftArmY = 24.0f;
            }
            partMatrix.set(rootMatrix).translate(-5.0f, 22.0f, headZ)
                    .rotate(Vector3.Y, leftArmY)
                    .rotate(Vector3.X, leftArmX)
                    .rotate(Vector3.Z, 3.0f);
            shader.setUniformMatrix4f("uModel", partMatrix);
            thirdLeftArmMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);

            // 5. Tay phải + vật phẩm cầm tay
            float rightArmX = walkAngle * 0.8f + swingSin * 85.0f;
            float rightArmY = 0.0f;
            if (useState == ItemUseHandler.UseState.DRAW_BOW) {
                rightArmX = 85.0f + headPitchDeg;
                rightArmY = -6.0f;
            } else if (useState == ItemUseHandler.UseState.CHARGE_SPEAR) {
                rightArmX = 75.0f + headPitchDeg;
            } else if (useState == ItemUseHandler.UseState.EAT_FOOD || useState == ItemUseHandler.UseState.DRINK_POTION) {
                rightArmX = 52.0f + (float) Math.sin(useProgress * Math.PI * 10.0f) * 10.0f;
                rightArmY = -20.0f;
            }
            partMatrix.set(rootMatrix).translate(5.0f, 22.0f, headZ)
                    .rotate(Vector3.Y, rightArmY)
                    .rotate(Vector3.X, rightArmX)
                    .rotate(Vector3.Z, -3.0f);
            shader.setUniformMatrix4f("uModel", partMatrix);
            thirdRightArmMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);

            renderThirdPersonHeldItem(shader, player, useHandler, blockAtlas, itemAtlas, partMatrix);
        } finally {
            shader.setUniformMatrix4f("uModel", identityMatrix);
            shader.setUniformVec4("uTintColor", 1.0f, 1.0f, 1.0f, 1.0f);
            shader.setUniform1i("uUseTexture", 1);
            shader.setUniform1f("uMobWhiteFlash", 0.0f);
            if (blockAtlas != null) {
                blockAtlas.bind();
            }
            Gdx.gl.glEnable(GL20.GL_DEPTH_TEST);
            Gdx.gl.glEnable(GL20.GL_CULL_FACE);
            Gdx.gl.glDisable(GL20.GL_BLEND);
        }
    }

    /** Vẽ tay trần góc nhìn thứ nhất từ skin {@code steve.png} (bàn tay hướng ra trước, vai áo ở góc dưới phải). */
    private void renderFirstPersonArm(ShaderProgram shader, float bobX, float bobY,
                                      float swingSin, float swingSqrt) {
        modelMatrix.idt()
                .translate(0.56f + bobX, -0.56f + bobY, -0.76f)
                .translate(-0.34f * swingSqrt, 0.22f * (float) Math.sin(Math.asin(Math.min(1f, swingSin)) * 2.0), -0.32f * swingSin)
                .rotate(Vector3.Y, 42.0f - 24.0f * swingSqrt)
                .rotate(Vector3.X, 114.0f - 45.0f * swingSin)
                .rotate(Vector3.Z, -12.0f - 20.0f * swingSqrt)
                .scale(PIXEL_TO_BLOCK, PIXEL_TO_BLOCK, PIXEL_TO_BLOCK);
        steveTexture.bind(0);
        shader.setUniformMatrix4f("uModel", modelMatrix);
        armMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);
    }

    /** Vẽ khối 3D thu nhỏ trên tay phải góc nhìn thứ nhất. */
    private void renderFirstPersonBlock(ShaderProgram shader, Texture blockAtlas, Block block,
                                        float bobX, float bobY, float swingSin, float swingSqrt) {
        if (blockAtlas == null || block == null || block == Block.AIR) {
            return;
        }
        Mesh mesh = getOrCreateBlockMesh(block);
        modelMatrix.idt()
                .translate(0.56f + bobX, -0.52f + bobY, -0.82f)
                .translate(-0.32f * swingSqrt, 0.20f * swingSin, -0.28f * swingSin)
                .rotate(Vector3.Y, 45.0f - 30.0f * swingSqrt)
                .rotate(Vector3.X, -14.0f - 48.0f * swingSin)
                .rotate(Vector3.Z, 18.0f * swingSqrt)
                .scale(0.38f, 0.38f, 0.38f);
        blockAtlas.bind();
        shader.setUniformMatrix4f("uModel", modelMatrix);
        mesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);
    }

    /** Vẽ 4 khung hình cung kéo dây từ {@code equipment/held.png}. */
    private void renderFirstPersonBow(ShaderProgram shader, float bobX, float bobY,
                                      float swingSin, float swingSqrt, float pull) {
        int frame = pull <= 0.0f ? 0 : (pull < 0.65f ? 1 : (pull < 0.90f ? 2 : 3));
        float jitter = pull >= 0.90f ? (float) Math.sin(animationClock * 50.0f) * 0.004f : 0.0f;
        modelMatrix.idt()
                .translate(0.50f + bobX - 0.14f * pull + jitter, -0.40f + bobY + 0.06f * pull + jitter, -0.76f + 0.12f * pull)
                .translate(-0.28f * swingSqrt, 0.16f * swingSin, -0.24f * swingSin)
                .rotate(Vector3.Y, -12.0f + 10.0f * pull)
                .rotate(Vector3.X, -8.0f - 40.0f * swingSin)
                .rotate(Vector3.Z, -16.0f + 8.0f * pull)
                .scale(0.55f, 0.55f, 0.55f);
        heldTexture.bind(0);
        shader.setUniformMatrix4f("uModel", modelMatrix);
        bowMeshes[frame].render(shader.getGdxShader(), GL20.GL_TRIANGLES);
    }

    /** Vẽ giáo sắt {@link Item#IRON_SPEAR} từ {@code equipment/held.png} với hoạt ảnh Jab & Charge. */
    private void renderFirstPersonSpear(ShaderProgram shader, float bobX, float bobY,
                                        float swingSin, float swingSqrt, float charge) {
        modelMatrix.idt()
                .translate(0.54f + bobX - 0.18f * charge, -0.42f + bobY + 0.14f * charge, -0.78f - 0.18f * charge)
                .translate(-0.26f * swingSqrt, 0.14f * swingSin, -0.40f * swingSin)
                .rotate(Vector3.Y, -14.0f - 8.0f * charge)
                .rotate(Vector3.X, -10.0f - 38.0f * charge - 46.0f * swingSin)
                .rotate(Vector3.Z, -18.0f + 16.0f * charge)
                .scale(0.62f, 0.62f, 0.62f);
        heldTexture.bind(0);
        shader.setUniformMatrix4f("uModel", modelMatrix);
        spearMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);
    }

    /** Vẽ vật phẩm 2D bất kỳ từ {@link ItemTextureAtlas} với hoạt ảnh nâng lên ăn/uống. */
    private void renderFirstPersonItem(ShaderProgram shader, ItemTextureAtlas itemAtlas, Item item,
                                       float bobX, float bobY, float swingSin, float swingSqrt,
                                       float useProgress, boolean consuming) {
        if (itemAtlas == null || item == null || item.isNone()) {
            return;
        }
        Mesh mesh = getOrCreateItemMesh(item);
        if (mesh == null) {
            return;
        }
        float lift = consuming ? Math.min(1.0f, useProgress * 4.5f) : 0.0f;
        float nibble = consuming ? (float) Math.abs(Math.sin(useProgress * Math.PI * 10.0f)) * 0.045f : 0.0f;
        modelMatrix.idt()
                .translate(0.52f + bobX - 0.28f * lift, -0.44f + bobY + 0.18f * lift + nibble, -0.76f + 0.12f * lift)
                .translate(-0.28f * swingSqrt, 0.16f * swingSin, -0.26f * swingSin)
                .rotate(Vector3.Y, -16.0f + 18.0f * lift - 20.0f * swingSqrt)
                .rotate(Vector3.X, -8.0f + 12.0f * lift - 45.0f * swingSin)
                .rotate(Vector3.Z, -8.0f + 22.0f * lift)
                .scale(0.46f, 0.46f, 0.46f);
        itemAtlas.bind();
        shader.setUniformMatrix4f("uModel", modelMatrix);
        mesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);
    }

    /** Vẽ vật phẩm đang cầm trên tay phải của Steve ở góc nhìn thứ 3. */
    private void renderThirdPersonHeldItem(ShaderProgram shader, Player player, ItemUseHandler useHandler,
                                           Texture blockAtlas, ItemTextureAtlas itemAtlas, Matrix4 rightArmTransform) {
        Hotbar hotbar = player.getHotbar();
        if (hotbar == null || hotbar.getSelectedCount() <= 0) {
            return;
        }
        Item held = hotbar.getSelectedItem();
        if (held == null || held.isNone()) {
            return;
        }

        if (held.isBlock() && blockAtlas != null) {
            Mesh mesh = getOrCreateBlockMesh(held.getBlock());
            heldThirdMatrix.set(rightArmTransform)
                    .translate(1.0f, -10.0f, -3.5f)
                    .rotate(Vector3.X, 45.0f)
                    .scale(6.0f, 6.0f, 6.0f);
            blockAtlas.bind();
            shader.setUniformMatrix4f("uModel", heldThirdMatrix);
            mesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);
            return;
        }

        if (held == Item.BOW) {
            float pull = useHandler != null ? useHandler.getBowPullProgress() : 0.0f;
            int frame = pull <= 0.0f ? 0 : (pull < 0.65f ? 1 : (pull < 0.90f ? 2 : 3));
            heldThirdMatrix.set(rightArmTransform)
                    .translate(1.0f, -10.0f, -3.0f)
                    .rotate(Vector3.Y, 90.0f)
                    .rotate(Vector3.Z, -40.0f)
                    .scale(12.0f, 12.0f, 12.0f);
            heldTexture.bind(0);
            shader.setUniformMatrix4f("uModel", heldThirdMatrix);
            bowMeshes[frame].render(shader.getGdxShader(), GL20.GL_TRIANGLES);
            return;
        }

        if (held == Item.IRON_SPEAR) {
            heldThirdMatrix.set(rightArmTransform)
                    .translate(1.0f, -10.0f, -3.0f)
                    .rotate(Vector3.Y, 90.0f)
                    .rotate(Vector3.X, 45.0f)
                    .scale(12.0f, 12.0f, 12.0f);
            heldTexture.bind(0);
            shader.setUniformMatrix4f("uModel", heldThirdMatrix);
            spearMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);
            return;
        }

        if (itemAtlas != null) {
            Mesh mesh = getOrCreateItemMesh(held);
            if (mesh != null) {
                heldThirdMatrix.set(rightArmTransform)
                        .translate(1.0f, -10.0f, -3.0f)
                        .rotate(Vector3.Y, 90.0f)
                        .rotate(Vector3.Z, -20.0f)
                        .scale(8.0f, 8.0f, 8.0f);
                itemAtlas.bind();
                shader.setUniformMatrix4f("uModel", heldThirdMatrix);
                mesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);
            }
        }
    }

    /** Dựng lưới 3D cho một bộ phận hộp chuẩn Minecraft từ skin 64×64 của Steve. */
    private static Mesh buildBoxMesh(float offsetX, float offsetY, float offsetZ,
                                     int sizeX, int sizeY, int sizeZ,
                                     int texU, int texV, boolean mirrored) {
        ModelPart.UvOrientation orientation = mirrored
                ? ModelPart.UvOrientation.MIRRORED : ModelPart.UvOrientation.MINECRAFT;
        ModelPart part = new ModelPart(0f, 0f, 0f, offsetX, offsetY, offsetZ,
                sizeX, sizeY, sizeZ, 0f, new ModelPart.CuboidUv(texU, texV, sizeX, sizeY, sizeZ, orientation));
        float[] vertices = part.buildVertices(STEVE_TEX_SIZE, STEVE_TEX_SIZE);
        Mesh mesh = new Mesh(Mesh.VertexDataType.VertexBufferObjectWithVAO, true,
                vertices.length / ModelPart.STRIDE, 0, VERTEX_ATTRIBUTES);
        try {
            mesh.setVertices(vertices);
            return mesh;
        } catch (RuntimeException | Error failure) {
            mesh.dispose();
            throw failure;
        }
    }

    /** Dựng quad 2D có hai mặt trước/sau chuẩn CCW (hiển thị từ cả hai phía mà vẫn giữ {@code GL_CULL_FACE}). */
    private static Mesh buildDoubleSidedQuadMesh(float u0, float v0, float u1, float v1) {
        float[] vertices = new float[12 * 6];
        int idx = putQuadFace(vertices, 0,
                -0.5f, -0.5f, 0.0f, u0, v1,
                 0.5f, -0.5f, 0.0f, u1, v1,
                 0.5f,  0.5f, 0.0f, u1, v0,
                -0.5f,  0.5f, 0.0f, u0, v0, 0.96f);
        putQuadFace(vertices, idx,
                 0.5f, -0.5f, 0.0f, u0, v1,
                -0.5f, -0.5f, 0.0f, u1, v1,
                -0.5f,  0.5f, 0.0f, u1, v0,
                 0.5f,  0.5f, 0.0f, u0, v0, 0.86f);
        Mesh mesh = new Mesh(Mesh.VertexDataType.VertexBufferObjectWithVAO, true, 12, 0, VERTEX_ATTRIBUTES);
        try {
            mesh.setVertices(vertices);
            return mesh;
        } catch (RuntimeException | Error failure) {
            mesh.dispose();
            throw failure;
        }
    }

    /** Lấy hoặc dựng cache lưới 2 mặt cho vật phẩm độc lập từ {@link ItemTextureAtlas}. */
    private Mesh getOrCreateItemMesh(Item item) {
        int tileIndex = item.getAtlasTileIndex();
        if (tileIndex < 0 || tileIndex >= itemMeshes.length) {
            return null;
        }
        Mesh cached = itemMeshes[tileIndex];
        if (cached == null) {
            float[] uv = item.getTileUV();
            cached = buildDoubleSidedQuadMesh(uv[0], uv[1], uv[2], uv[3]);
            itemMeshes[tileIndex] = cached;
        }
        return cached;
    }

    /** Lấy hoặc dựng cache lưới cho khối 3D thu nhỏ (hộp lập phương hoặc cây chữ X). */
    private Mesh getOrCreateBlockMesh(Block block) {
        int id = Byte.toUnsignedInt(block.getId());
        Mesh cached = blockMeshes[id];
        if (cached != null) {
            return cached;
        }
        if (block.getGeometryType() == Block.GeometryType.CROSS_PLANT) {
            float[] uv = block.getFaceUV(Block.Face.NORTH);
            float[] vertices = new float[24 * 6];
            int idx = putQuadFace(vertices, 0,
                    -0.35f, -0.5f, -0.35f, uv[0], uv[3],
                     0.35f, -0.5f,  0.35f, uv[2], uv[3],
                     0.35f,  0.5f,  0.35f, uv[2], uv[1],
                    -0.35f,  0.5f, -0.35f, uv[0], uv[1], 1.0f);
            idx = putQuadFace(vertices, idx,
                     0.35f, -0.5f,  0.35f, uv[0], uv[3],
                    -0.35f, -0.5f, -0.35f, uv[2], uv[3],
                    -0.35f,  0.5f, -0.35f, uv[2], uv[1],
                     0.35f,  0.5f,  0.35f, uv[0], uv[1], 1.0f);
            idx = putQuadFace(vertices, idx,
                    -0.35f, -0.5f,  0.35f, uv[0], uv[3],
                     0.35f, -0.5f, -0.35f, uv[2], uv[3],
                     0.35f,  0.5f, -0.35f, uv[2], uv[1],
                    -0.35f,  0.5f,  0.35f, uv[0], uv[1], 1.0f);
            putQuadFace(vertices, idx,
                     0.35f, -0.5f, -0.35f, uv[0], uv[3],
                    -0.35f, -0.5f,  0.35f, uv[2], uv[3],
                    -0.35f,  0.5f,  0.35f, uv[2], uv[1],
                     0.35f,  0.5f, -0.35f, uv[0], uv[1], 1.0f);
            Mesh mesh = new Mesh(Mesh.VertexDataType.VertexBufferObjectWithVAO, true, 24, 0, VERTEX_ATTRIBUTES);
            try {
                mesh.setVertices(vertices);
                blockMeshes[id] = mesh;
                return mesh;
            } catch (RuntimeException | Error failure) {
                mesh.dispose();
                throw failure;
            }
        }

        float[] topUV = block.getFaceUV(Block.Face.TOP);
        float[] botUV = block.getFaceUV(Block.Face.BOTTOM);
        float[] sideUV = block.getFaceUV(Block.Face.NORTH);
        float[] vertices = new float[36 * 6];
        int idx = putQuadFace(vertices, 0,
                -0.5f,  0.5f,  0.5f, topUV[0], topUV[3],
                 0.5f,  0.5f,  0.5f, topUV[2], topUV[3],
                 0.5f,  0.5f, -0.5f, topUV[2], topUV[1],
                -0.5f,  0.5f, -0.5f, topUV[0], topUV[1], 1.0f);
        idx = putQuadFace(vertices, idx,
                -0.5f, -0.5f, -0.5f, botUV[0], botUV[3],
                 0.5f, -0.5f, -0.5f, botUV[2], botUV[3],
                 0.5f, -0.5f,  0.5f, botUV[2], botUV[1],
                -0.5f, -0.5f,  0.5f, botUV[0], botUV[1], 0.55f);
        idx = putQuadFace(vertices, idx,
                -0.5f, -0.5f,  0.5f, sideUV[0], sideUV[3],
                 0.5f, -0.5f,  0.5f, sideUV[2], sideUV[3],
                 0.5f,  0.5f,  0.5f, sideUV[2], sideUV[1],
                -0.5f,  0.5f,  0.5f, sideUV[0], sideUV[1], 0.85f);
        idx = putQuadFace(vertices, idx,
                 0.5f, -0.5f, -0.5f, sideUV[0], sideUV[3],
                -0.5f, -0.5f, -0.5f, sideUV[2], sideUV[3],
                -0.5f,  0.5f, -0.5f, sideUV[2], sideUV[1],
                 0.5f,  0.5f, -0.5f, sideUV[0], sideUV[1], 0.85f);
        idx = putQuadFace(vertices, idx,
                 0.5f, -0.5f,  0.5f, sideUV[0], sideUV[3],
                 0.5f, -0.5f, -0.5f, sideUV[2], sideUV[3],
                 0.5f,  0.5f, -0.5f, sideUV[2], sideUV[1],
                 0.5f,  0.5f,  0.5f, sideUV[0], sideUV[1], 0.72f);
        putQuadFace(vertices, idx,
                -0.5f, -0.5f, -0.5f, sideUV[0], sideUV[3],
                -0.5f, -0.5f,  0.5f, sideUV[2], sideUV[3],
                -0.5f,  0.5f,  0.5f, sideUV[2], sideUV[1],
                -0.5f,  0.5f, -0.5f, sideUV[0], sideUV[1], 0.72f);

        Block.Bounds shape = block.getSelectionBounds(0);
        if (shape != null && shape != Block.FULL_BOUNDS) {
            float sx = shape.maxX() - shape.minX();
            float sy = shape.maxY() - shape.minY();
            float sz = shape.maxZ() - shape.minZ();
            for (int i = 0; i < vertices.length; i += 6) {
                vertices[i] *= sx;
                vertices[i + 1] = (vertices[i + 1] + 0.5f) * sy - 0.5f;
                vertices[i + 2] *= sz;
            }
        }

        Mesh mesh = new Mesh(Mesh.VertexDataType.VertexBufferObjectWithVAO, true, 36, 0, VERTEX_ATTRIBUTES);
        try {
            mesh.setVertices(vertices);
            blockMeshes[id] = mesh;
            return mesh;
        } catch (RuntimeException | Error failure) {
            mesh.dispose();
            throw failure;
        }
    }

    /** Ghi 2 tam giác của một mặt tứ giác theo thứ tự quấn đỉnh CCW. */
    private static int putQuadFace(float[] out, int offset,
                                   float x1, float y1, float z1, float u1, float v1,
                                   float x2, float y2, float z2, float u2, float v2,
                                   float x3, float y3, float z3, float u3, float v3,
                                   float x4, float y4, float z4, float u4, float v4,
                                   float shade) {
        offset = putVertex(out, offset, x1, y1, z1, u1, v1, shade);
        offset = putVertex(out, offset, x2, y2, z2, u2, v2, shade);
        offset = putVertex(out, offset, x3, y3, z3, u3, v3, shade);
        offset = putVertex(out, offset, x1, y1, z1, u1, v1, shade);
        offset = putVertex(out, offset, x3, y3, z3, u3, v3, shade);
        return putVertex(out, offset, x4, y4, z4, u4, v4, shade);
    }

    /** Ghi 6 float thuộc tính của một đỉnh vào mảng đệm. */
    private static int putVertex(float[] out, int offset, float x, float y, float z,
                                 float u, float v, float shade) {
        out[offset++] = x;
        out[offset++] = y;
        out[offset++] = z;
        out[offset++] = u;
        out[offset++] = v;
        out[offset++] = shade;
        return offset;
    }

    /** Nạp PNG từ classpath với định dạng RGBA8888, dùng màu dự phòng an toàn nếu thiếu tệp. */
    private static com.badlogic.gdx.graphics.Texture loadTextureSafe(String path, int fallbackRgb) {
        com.badlogic.gdx.graphics.Texture texture = null;
        try {
            FileHandle file = Gdx.files.classpath(path);
            if (!file.exists()) {
                throw new IllegalArgumentException("Thiếu tệp PNG: " + path);
            }
            texture = new com.badlogic.gdx.graphics.Texture(file, Pixmap.Format.RGBA8888, false);
            texture.setFilter(com.badlogic.gdx.graphics.Texture.TextureFilter.Nearest,
                    com.badlogic.gdx.graphics.Texture.TextureFilter.Nearest);
            texture.setWrap(com.badlogic.gdx.graphics.Texture.TextureWrap.ClampToEdge,
                    com.badlogic.gdx.graphics.Texture.TextureWrap.ClampToEdge);
            return texture;
        } catch (RuntimeException error) {
            if (texture != null) {
                texture.dispose();
            }
            Gdx.app.error("FirstPersonRenderer", "Dùng ảnh dự phòng cho " + path + ": " + error.getMessage());
            return createFallbackTexture(fallbackRgb);
        }
    }

    /** Tạo texture đơn sắc 16×16 dự phòng và luôn giải phóng {@link Pixmap} ngoài heap ngay sau tải. */
    private static com.badlogic.gdx.graphics.Texture createFallbackTexture(int rgb) {
        Pixmap image = new Pixmap(16, 16, Pixmap.Format.RGBA8888);
        com.badlogic.gdx.graphics.Texture texture = null;
        try {
            image.setColor((rgb << 8) | 0xFF);
            image.fill();
            texture = new com.badlogic.gdx.graphics.Texture(image, false);
            texture.setFilter(com.badlogic.gdx.graphics.Texture.TextureFilter.Nearest,
                    com.badlogic.gdx.graphics.Texture.TextureFilter.Nearest);
            texture.setWrap(com.badlogic.gdx.graphics.Texture.TextureWrap.ClampToEdge,
                    com.badlogic.gdx.graphics.Texture.TextureWrap.ClampToEdge);
            return texture;
        } catch (RuntimeException error) {
            if (texture != null) {
                texture.dispose();
            }
            throw error;
        } finally {
            image.dispose();
        }
    }

    /** Giải phóng an toàn một {@link Disposable} nếu khác {@code null}. */
    private static void disposeMesh(Mesh mesh) {
        if (mesh != null) {
            mesh.dispose();
        }
    }

    /**
     * Giải phóng toàn bộ {@link Mesh} (VAO/VBO) và {@link com.badlogic.gdx.graphics.Texture} trên VRAM.
     * An toàn khi gọi nhiều lần hoặc gọi khi quá trình khởi tạo chưa hoàn tất.
     */
    @Override
    public void dispose() {
        if (disposed) {
            return;
        }
        disposed = true;
        glInitialized = false;

        disposeMesh(armMesh);
        armMesh = null;

        for (int i = 0; i < bowMeshes.length; i++) {
            disposeMesh(bowMeshes[i]);
            bowMeshes[i] = null;
        }
        disposeMesh(spearMesh);
        spearMesh = null;

        disposeMesh(thirdHeadMesh);
        thirdHeadMesh = null;
        disposeMesh(thirdBodyMesh);
        thirdBodyMesh = null;
        disposeMesh(thirdRightArmMesh);
        thirdRightArmMesh = null;
        disposeMesh(thirdLeftArmMesh);
        thirdLeftArmMesh = null;
        disposeMesh(thirdRightLegMesh);
        thirdRightLegMesh = null;
        disposeMesh(thirdLeftLegMesh);
        thirdLeftLegMesh = null;

        for (int i = 0; i < itemMeshes.length; i++) {
            disposeMesh(itemMeshes[i]);
            itemMeshes[i] = null;
        }
        for (int i = 0; i < blockMeshes.length; i++) {
            disposeMesh(blockMeshes[i]);
            blockMeshes[i] = null;
        }

        if (steveTexture != null) {
            steveTexture.dispose();
            steveTexture = null;
        }
        if (heldTexture != null) {
            heldTexture.dispose();
            heldTexture = null;
        }
    }
}

package com.voxelgame.client.render;

import com.voxelgame.world.item.Item;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.Texture.TextureFilter;
import com.badlogic.gdx.graphics.Texture.TextureWrap;
import com.badlogic.gdx.utils.Disposable;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.util.List;

/**
 * Đóng gói toàn bộ 56 texture vật phẩm độc lập (16 × 16 RGBA) vào một tấm Texture Atlas
 * duy nhất kích thước 128 × 128 (8 × 8 ô) trên VRAM, triển khai {@link Disposable}.
 */
public final class ItemTextureAtlas implements Disposable {

    /** Kích thước mỗi ô vật phẩm và số cột/hàng của atlas vật phẩm. */
    public static final int TILE_SIZE = 16;
    public static final int ATLAS_COLS = 8;
    public static final int ATLAS_ROWS = 8;
    public static final int ATLAS_WIDTH = TILE_SIZE * ATLAS_COLS;
    public static final int ATLAS_HEIGHT = TILE_SIZE * ATLAS_ROWS;

    private final com.badlogic.gdx.graphics.Texture gdxTexture;

    /** Nạp toàn bộ PNG vật phẩm từ `textures/item/` vào atlas và giải phóng bộ đệm CPU ngay sau đó. */
    public ItemTextureAtlas() {
        Pixmap atlasPixmap = new Pixmap(ATLAS_WIDTH, ATLAS_HEIGHT, Pixmap.Format.RGBA8888);
        try {
            atlasPixmap.setBlending(Pixmap.Blending.None);
            List<Item> items = Item.allStandaloneItems();
            for (int i = 0; i < items.size(); i++) {
                Item item = items.get(i);
                loadItemIntoTile(atlasPixmap, item);
            }
            gdxTexture = new com.badlogic.gdx.graphics.Texture(atlasPixmap);
        } finally {
            atlasPixmap.dispose();
        }
        try {
            gdxTexture.setFilter(TextureFilter.Nearest, TextureFilter.Nearest);
            gdxTexture.setWrap(TextureWrap.ClampToEdge, TextureWrap.ClampToEdge);
        } catch (RuntimeException | Error failure) {
            gdxTexture.dispose();
            throw failure;
        }
    }

    /** Nạp PNG vật phẩm vào đúng ô của nó, dùng pixel art dự phòng nếu thiếu tệp. */
    private void loadItemIntoTile(Pixmap atlasPixmap, Item item) {
        String textureName = item.getTextureName();
        int tileIndex = item.getAtlasTileIndex();
        Pixmap source = textureName == null ? null : loadPixmap("textures/item/" + textureName + ".png");
        if (source != null) {
            try {
                int srcW = source.getWidth();
                int srcH = source.getHeight();
                for (int ty = 0; ty < TILE_SIZE; ty++) {
                    for (int tx = 0; tx < TILE_SIZE; tx++) {
                        int sx = Math.min(srcW - 1, (int) (((tx + 0.5f) / TILE_SIZE) * srcW));
                        int sy = Math.min(srcH - 1, (int) (((ty + 0.5f) / TILE_SIZE) * srcH));
                        putAtlasPixel(atlasPixmap, tileIndex, tx, ty, Texture.readNormalizedPixel(source, sx, sy));
                    }
                }
                return;
            } finally {
                source.dispose();
            }
        }
        drawFallbackTile(atlasPixmap, tileIndex, item.getFallbackRgb(), item.isCubeItem());
    }

    /** Vẽ ô màu dự phòng khi không tìm thấy PNG để game không bị lỗi hay tàng hình vật phẩm. */
    private void drawFallbackTile(Pixmap atlasPixmap, int tileIndex, int rgb, boolean fullCube) {
        int r = (rgb >>> 16) & 0xFF;
        int g = (rgb >>> 8) & 0xFF;
        int b = rgb & 0xFF;
        for (int ty = 0; ty < TILE_SIZE; ty++) {
            for (int tx = 0; tx < TILE_SIZE; tx++) {
                boolean visible = fullCube || (tx >= 3 && tx <= 12 && ty >= 3 && ty <= 12);
                int alpha = visible ? 255 : 0;
                int grain = ((tx * 11 + ty * 7 + tileIndex * 5) % 15) - 7;
                int rgba = (clamp(r + grain) << 24)
                        | (clamp(g + grain) << 16)
                        | (clamp(b + grain) << 8)
                        | alpha;
                putAtlasPixel(atlasPixmap, tileIndex, tx, ty, rgba);
            }
        }
    }

    /** Ghi một pixel RGBA8888 vào đúng tọa độ của ô trên atlas. */
    private void putAtlasPixel(Pixmap atlasPixmap, int tileIndex, int tx, int ty, int rgba) {
        int col = tileIndex % ATLAS_COLS;
        int row = tileIndex / ATLAS_COLS;
        atlasPixmap.drawPixel(col * TILE_SIZE + tx, row * TILE_SIZE + ty, rgba);
    }

    /** Tìm và giải mã PNG từ classpath hoặc thư mục tài nguyên cục bộ. */
    private Pixmap loadPixmap(String relativePath) {
        byte[] rawBytes = null;
        try (InputStream is = ItemTextureAtlas.class.getResourceAsStream("/" + relativePath)) {
            if (is != null) {
                rawBytes = is.readAllBytes();
            }
        } catch (IOException ignored) {
        }
        if (rawBytes == null) {
            File file = new File("src/main/resources/" + relativePath);
            if (file.exists() && file.isFile()) {
                try {
                    rawBytes = Files.readAllBytes(file.toPath());
                } catch (IOException ignored) {
                }
            }
        }
        if (rawBytes == null) {
            return null;
        }
        try {
            return new Pixmap(rawBytes, 0, rawBytes.length);
        } catch (Exception e) {
            System.err.println("[ItemTextureAtlas] Không giải mã được " + relativePath + ": " + e.getMessage());
            return null;
        }
    }

    private static int clamp(int value) {
        return Math.max(0, Math.min(255, value));
    }

    /** Gắn atlas vật phẩm vào Texture Unit 0 trên GPU. */
    public void bind() {
        gdxTexture.bind(0);
    }

    /** Hủy liên kết texture khỏi Texture Unit 0. */
    public void unbind() {
        Gdx.gl.glBindTexture(GL20.GL_TEXTURE_2D, 0);
    }

    /** Giải phóng tấm atlas trên VRAM khi đóng game. */
    @Override
    public void dispose() {
        if (gdxTexture != null) {
            gdxTexture.dispose();
        }
    }
}

package com.voxelgame.client.render;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.utils.Disposable;
import com.badlogic.gdx.utils.GdxNativesLoader;

/**
 * Quản lý hoạt ảnh cho khối Nước (32 frame) và Dung nham (20 frame) bằng cách nạp
 * dải ảnh nguồn một lần duy nhất lúc khởi tạo, cắt sẵn thành từng {@link Pixmap}
 * {@code 16x16} định dạng {@code RGBA8888}, và cập nhật từng ô tương ứng trên
 * {@link Texture} atlas qua {@code glTexSubImage2D} mỗi {@code 0.10s} mà không tạo rác GC.
 */
public class LiquidAnimator implements Disposable {

    /** Số lượng khung hình hoạt ảnh chuẩn của nước từ {@code water_still.png} (16x512). */
    public static final int WATER_FRAME_COUNT = 32;

    /** Số lượng khung hình hoạt ảnh chuẩn của dung nham từ {@code lava_still.png} (16x320). */
    public static final int LAVA_FRAME_COUNT = 20;

    /** Thời lượng hiển thị mỗi khung hình chất lỏng (giây). */
    public static final float FRAME_DURATION_SECONDS = 0.10f;

    /** Danh sách tên ứng viên để tìm texture nước, khớp thứ tự ưu tiên của {@link Texture}. */
    private static final String[] WATER_TEXTURE_CANDIDATES = {
            "textures/water_still.png",
            "water_still.png",
            "fliflight-clear-water-1.0.0-resourcepack-1.21.4/assets/minecraft/textures/block/water_still.png",
            "textures/fliflight-clear-water-1.0.0-resourcepack-1.21.4/assets/minecraft/textures/block/water_still.png"
    };

    /** Danh sách tên ứng viên để tìm texture dung nham, khớp thứ tự ưu tiên của {@link Texture}. */
    private static final String[] LAVA_TEXTURE_CANDIDATES = {
            "textures/lava_still.png",
            "download.jpg",
            "textures/download.jpg",
            "lava.jpg",
            "lava.png"
    };

    private final Pixmap[] waterFrames = new Pixmap[WATER_FRAME_COUNT];
    private final Pixmap[] lavaFrames = new Pixmap[LAVA_FRAME_COUNT];

    private int currentWaterFrame;
    private int currentLavaFrame;
    private float frameTimer;
    private boolean disposed;

    /**
     * Khởi tạo bộ phát hoạt ảnh chất lỏng, tự động nạp thư viện native libGDX nếu cần,
     * giải mã {@code water_still.png} và {@code lava_still.png} một lần thành bộ đệm
     * khung hình {@code RGBA8888} trên CPU sẵn sàng đẩy lên GPU.
     */
    public LiquidAnimator() {
        GdxNativesLoader.load();
        try {
            loadLiquidFrames(waterFrames, WATER_FRAME_COUNT, Texture.TileStyle.WATER, WATER_TEXTURE_CANDIDATES);
            loadLiquidFrames(lavaFrames, LAVA_FRAME_COUNT, Texture.TileStyle.LAVA, LAVA_TEXTURE_CANDIDATES);
        } catch (RuntimeException | Error failure) {
            dispose();
            throw failure;
        }
    }

    /**
     * Nạp dải ảnh chất lỏng từ tài nguyên một lần, tách thành các khung {@code 16x16 RGBA8888}
     * và áp dụng đúng quy tắc nhuộm màu/alpha của {@link Texture}. Nếu thiếu tệp nguồn,
     * sinh khung hình pixel dự phòng tất định để không bao giờ để rỗng bộ đệm.
     */
    private static void loadLiquidFrames(
            Pixmap[] outFrames,
            int targetFrameCount,
            Texture.TileStyle style,
            String... candidateNames
    ) {
        Pixmap source = Texture.loadPixmapFlexible(candidateNames);
        if (source == null) {
            populateProceduralLiquidFrames(outFrames, targetFrameCount, style);
            return;
        }
        try {
            int srcWidth = Math.max(1, source.getWidth());
            int srcHeight = Math.max(1, source.getHeight());
            // Mỗi khung trên dải dọc có chiều cao bằng chiều rộng (hoặc toàn ảnh nếu không đủ).
            int frameHeight = Math.min(srcWidth, srcHeight);
            int availableFrames = Math.max(1, srcHeight / frameHeight);

            for (int frameIndex = 0; frameIndex < targetFrameCount; frameIndex++) {
                int srcFrame = frameIndex % availableFrames;
                int srcY = Math.min(srcHeight - frameHeight, srcFrame * frameHeight);
                Pixmap frame = new Pixmap(Texture.TILE_SIZE, Texture.TILE_SIZE, Pixmap.Format.RGBA8888);
                frame.setBlending(Pixmap.Blending.None);

                for (int ty = 0; ty < Texture.TILE_SIZE; ty++) {
                    int sy = srcY + Math.min(frameHeight - 1, (int) (((ty + 0.5f) / Texture.TILE_SIZE) * frameHeight));
                    for (int tx = 0; tx < Texture.TILE_SIZE; tx++) {
                        int sx = Math.min(srcWidth - 1, (int) (((tx + 0.5f) / Texture.TILE_SIZE) * srcWidth));
                        int rgba = Texture.sampleStyledRgba(source, sx, sy, style);
                        frame.drawPixel(tx, ty, rgba);
                    }
                }
                outFrames[frameIndex] = frame;
            }
        } finally {
            source.dispose();
        }
    }

    /**
     * Sinh các khung hình pixel art dự phòng khi thiếu ảnh chất lỏng bên ngoài,
     * dịch pha theo chỉ số khung để vẫn có hiệu ứng chuyển động liên tục.
     */
    private static void populateProceduralLiquidFrames(
            Pixmap[] outFrames,
            int targetFrameCount,
            Texture.TileStyle style
    ) {
        boolean isWater = style == Texture.TileStyle.WATER;
        for (int frameIndex = 0; frameIndex < targetFrameCount; frameIndex++) {
            Pixmap frame = new Pixmap(Texture.TILE_SIZE, Texture.TILE_SIZE, Pixmap.Format.RGBA8888);
            frame.setBlending(Pixmap.Blending.None);
            for (int y = 0; y < Texture.TILE_SIZE; y++) {
                int shiftedY = (y + frameIndex) % Texture.TILE_SIZE;
                for (int x = 0; x < Texture.TILE_SIZE; x++) {
                    int rgba;
                    if (isWater) {
                        int wave = ((x + shiftedY * 2) % 5 == 0) ? 16 : (((x * 7 + shiftedY * 11) % 11) - 5);
                        rgba = Texture.packRgba(42 + wave, 112 + wave, 225 + wave, Texture.OPAQUE_WATER_ALPHA);
                    } else {
                        int glow = ((x * 3 + shiftedY * 5) % 7 == 0) ? 35 : (((x * 13 + shiftedY * 17) % 31) - 15);
                        rgba = Texture.packRgba(230 + glow, 108 + glow, 22 + glow / 2, 255);
                    }
                    frame.drawPixel(x, y, rgba);
                }
            }
            outFrames[frameIndex] = frame;
        }
    }

    /**
     * Cộng dồn thời gian trôi qua và chuyển sang khung hình kế tiếp mỗi {@code 0.10s}.
     * Khi khung hình thay đổi và có ngữ cảnh OpenGL cùng {@code atlas != null},
     * tải trực tiếp hai ô {@link Texture#TILE_WATER} và {@link Texture#TILE_LAVA} lên GPU
     * theo cơ chế zero-GC (không cấp phát bộ nhớ mới).
     *
     * @param dt    khoảng thời gian giữa hai frame (giây)
     * @param atlas atlas khối dùng chung (có thể {@code null} khi kiểm thử CPU)
     */
    public void update(float dt, Texture atlas) {
        if (disposed || dt <= 0.0f) {
            return;
        }
        frameTimer += dt;
        boolean frameChanged = false;
        while (frameTimer >= FRAME_DURATION_SECONDS) {
            frameTimer -= FRAME_DURATION_SECONDS;
            currentWaterFrame = (currentWaterFrame + 1) % WATER_FRAME_COUNT;
            currentLavaFrame = (currentLavaFrame + 1) % LAVA_FRAME_COUNT;
            frameChanged = true;
        }
        if (frameChanged && atlas != null && Gdx.gl != null) {
            atlas.updateTile(Texture.TILE_WATER, waterFrames[currentWaterFrame]);
            atlas.updateTile(Texture.TILE_LAVA, lavaFrames[currentLavaFrame]);
        }
    }

    /** Trả về tổng số khung hình hoạt ảnh của nước (32). */
    public int getWaterFrameCount() {
        return WATER_FRAME_COUNT;
    }

    /** Trả về tổng số khung hình hoạt ảnh của dung nham (20). */
    public int getLavaFrameCount() {
        return LAVA_FRAME_COUNT;
    }

    /** Trả về chỉ số khung hình nước hiện tại trong khoảng {@code 0..31}. */
    public int getCurrentWaterFrame() {
        return currentWaterFrame;
    }

    /** Trả về chỉ số khung hình dung nham hiện tại trong khoảng {@code 0..19}. */
    public int getCurrentLavaFrame() {
        return currentLavaFrame;
    }

    /** Trả về Pixmap của một khung hình nước đã chuẩn hóa RGBA8888 để kiểm tra hoặc đọc pixel. */
    public Pixmap getWaterFramePixmap(int index) {
        return waterFrames[index];
    }

    /** Trả về Pixmap của một khung hình dung nham đã chuẩn hóa RGBA8888 để kiểm tra hoặc đọc pixel. */
    public Pixmap getLavaFramePixmap(int index) {
        return lavaFrames[index];
    }

    /** Giải phóng 100% bộ đệm {@link Pixmap} off-heap của cả nước và dung nham. */
    @Override
    public void dispose() {
        if (disposed) {
            return;
        }
        disposed = true;
        disposeFrameArray(waterFrames);
        disposeFrameArray(lavaFrames);
    }

    /** Dọn sạch và gán null từng phần tử Pixmap trong mảng khung hình. */
    private static void disposeFrameArray(Pixmap[] frames) {
        for (int i = 0; i < frames.length; i++) {
            if (frames[i] != null) {
                frames[i].dispose();
                frames[i] = null;
            }
        }
    }
}

package com.voxelgame.client.render;

import com.voxelgame.world.level.block.Block;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Mesh;
import com.badlogic.gdx.graphics.VertexAttribute;
import com.badlogic.gdx.graphics.VertexAttributes;
import com.badlogic.gdx.math.Matrix4;
import com.badlogic.gdx.utils.Disposable;
import java.util.Arrays;
import java.util.Random;

/**
 * Hệ thống quản lý hạt 3D (Particles) với pool tĩnh {@link #MAX_PARTICLES} = 512 hạt,
 * lưu toàn bộ dữ liệu trong các mảng nguyên thủy cấp phát 1 lần để đảm bảo zero-GC trong Game Loop.
 * <p>
 * Hỗ trợ 4 loại hiệu ứng hạt: mảnh vỡ khi đào/phá block (cắt UV 4x4 từ tile của {@link Block}),
 * hạt lửa cháy tự phát sáng, hạt bắn nước và hạt thuốc nổ màu RGB.
 * Khi số hạt vượt ngưỡng 512, bộ đếm vòng sẽ tự động ghi đè hạt cũ nhất mà không tràn mảng.
 */
public class ParticleManager implements Disposable {

    /** Dung lượng tối đa cố định của pool hạt trong bộ nhớ. */
    public static final int MAX_PARTICLES = 512;

    /** Trọng lực cơ bản tác động lên các hạt (block/s^2). */
    private static final float PARTICLE_GRAVITY = -18.0f;

    /** Hệ số cản không khí ngang mỗi giây giúp hạt tản đều rồi rơi xuống. */
    private static final float HORIZONTAL_DRAG_PER_SEC = 1.5f;

    /** Định dạng 6 số thực mỗi đỉnh khớp với {@link ShaderProgram}: aPos(3), aTexCoord(2), aShade(1). */
    private static final int FLOATS_PER_VERTEX = 6;
    private static final int VERTICES_PER_QUAD = 6;
    private static final int MAX_VERTICES = MAX_PARTICLES * VERTICES_PER_QUAD;

    /** Số hạt sinh ra mỗi lần vỡ lọ thuốc. */
    private static final int POTION_SPLASH_COUNT = 20;

    /** Bảng các mặt khối dùng lại để lấy tile ngẫu nhiên mà không cấp phát mảng. */
    private static final Block.Face[] BLOCK_FACES = Block.Face.values();

    // Toàn bộ dữ liệu 512 hạt lưu trong các mảng nguyên thủy cấp phát 1 lần (zero-GC).
    private final float[] px = new float[MAX_PARTICLES];
    private final float[] py = new float[MAX_PARTICLES];
    private final float[] pz = new float[MAX_PARTICLES];
    private final float[] vx = new float[MAX_PARTICLES];
    private final float[] vy = new float[MAX_PARTICLES];
    private final float[] vz = new float[MAX_PARTICLES];
    private final float[] life = new float[MAX_PARTICLES];
    private final float[] maxLife = new float[MAX_PARTICLES];
    private final float[] u0 = new float[MAX_PARTICLES];
    private final float[] v0 = new float[MAX_PARTICLES];
    private final float[] u1 = new float[MAX_PARTICLES];
    private final float[] v1 = new float[MAX_PARTICLES];
    private final float[] size = new float[MAX_PARTICLES];
    private final float[] pr = new float[MAX_PARTICLES];
    private final float[] pg = new float[MAX_PARTICLES];
    private final float[] pb = new float[MAX_PARTICLES];
    private final float[] gravityFactor = new float[MAX_PARTICLES];
    private final float[] shade = new float[MAX_PARTICLES];
    private final boolean[] textured = new boolean[MAX_PARTICLES];
    private final boolean[] active = new boolean[MAX_PARTICLES];

    /** Bộ đệm đỉnh thành viên và danh sách khe hạt không texture phục vụ kết xuất zero-GC. */
    private final float[] vertices = new float[MAX_VERTICES * FLOATS_PER_VERTEX];
    private final int[] untexturedSlots = new int[MAX_PARTICLES];
    private final Matrix4 modelMatrix = new Matrix4();
    private final Random random = new Random(20261127L);

    /** Mesh động cấp phát đúng 1 lần trên GPU (null khi chạy kiểm thử CPU không có OpenGL). */
    private final Mesh mesh;

    private int writeCursor;
    private int activeCount;
    private boolean disposed;

    /**
     * Khởi tạo bộ quản lý hạt với pool tĩnh 512 hạt.
     * Khi có ngữ cảnh OpenGL ({@code Gdx.gl != null}), cấp phát sẵn 1 {@link Mesh} động
     * dùng định dạng 6 floats/đỉnh tương thích {@code uUseVertexColor = 0}.
     */
    public ParticleManager() {
        if (Gdx.gl != null) {
            this.mesh = new Mesh(
                    Mesh.VertexDataType.VertexBufferObjectWithVAO,
                    false,
                    MAX_VERTICES,
                    0,
                    new VertexAttribute(VertexAttributes.Usage.Position, 3, "aPos"),
                    new VertexAttribute(VertexAttributes.Usage.TextureCoordinates, 2, "aTexCoord"),
                    new VertexAttribute(VertexAttributes.Usage.Generic, 1, "aShade")
            );
        } else {
            this.mesh = null;
        }
    }

    /**
     * Cấp phát một khe hạt mới trong pool 512 phần tử.
     * Ưu tiên tái sử dụng khe đã hết hạn; khi toàn bộ 512 khe đang hoạt động,
     * bộ đếm vòng sẽ ghi đè khe cũ nhất mà không bao giờ vượt biên mảng.
     */
    private int allocateSlot() {
        if (activeCount < MAX_PARTICLES) {
            for (int probe = 0; probe < MAX_PARTICLES; probe++) {
                int idx = (writeCursor + probe) % MAX_PARTICLES;
                if (!active[idx]) {
                    active[idx] = true;
                    activeCount++;
                    writeCursor = (idx + 1) % MAX_PARTICLES;
                    return idx;
                }
            }
        }
        int overwriteIdx = writeCursor;
        if (!active[overwriteIdx]) {
            active[overwriteIdx] = true;
            activeCount++;
        }
        writeCursor = (overwriteIdx + 1) % MAX_PARTICLES;
        return overwriteIdx;
    }

    /**
     * Sinh các hạt mảnh vỡ từ khối {@link Block} tại tọa độ nguyên {@code (x, y, z)}.
     * Mỗi hạt tự động cắt một mảnh UV ngẫu nhiên kích thước {@code 4x4} pixel trong ô tile của khối.
     *
     * @param x     tọa độ X nguyên của block
     * @param y     tọa độ Y nguyên của block
     * @param z     tọa độ Z nguyên của block
     * @param block loại block nguồn mảnh vỡ
     * @param count số lượng hạt cần sinh
     */
    public void spawnBlockBreak(int x, int y, int z, Block block, int count) {
        if (disposed || block == null || block == Block.AIR || count <= 0) {
            return;
        }
        float tileWidth = 1.0f / Texture.ATLAS_COLS;
        float tileHeight = 1.0f / Texture.ATLAS_ROWS;
        float eps = 0.0008f;

        for (int i = 0; i < count; i++) {
            Block.Face face = BLOCK_FACES[random.nextInt(BLOCK_FACES.length)];
            int tileIndex = block.getTileIndex(face);
            int col = tileIndex % Texture.ATLAS_COLS;
            int row = tileIndex / Texture.ATLAS_COLS;

            boolean cactusCap = tileIndex == Texture.TILE_CACTUS_TOP || tileIndex == Texture.TILE_CACTUS_BOTTOM;
            float insetU = cactusCap || tileIndex == Texture.TILE_CACTUS_SIDE ? 1.0f / Texture.ATLAS_WIDTH : 0.0f;
            float insetV = cactusCap ? 1.0f / Texture.ATLAS_HEIGHT : 0.0f;

            float baseU0 = col * tileWidth + insetU + eps;
            float baseV0 = row * tileHeight + insetV + eps;
            float baseU1 = (col + 1) * tileWidth - insetU - eps;
            float baseV1 = (row + 1) * tileHeight - insetV - eps;

            // Cắt ngẫu nhiên một ô con 4x4 pixel trong lưới 16x16 của tile.
            float ox = random.nextInt(13) / (float) Texture.TILE_SIZE;
            float oy = random.nextInt(13) / (float) Texture.TILE_SIZE;
            float patchSpan = 4.0f / Texture.TILE_SIZE;
            float spanU = baseU1 - baseU0;
            float spanV = baseV1 - baseV0;

            int slot = allocateSlot();
            px[slot] = x + 0.15f + random.nextFloat() * 0.70f;
            py[slot] = y + 0.15f + random.nextFloat() * 0.70f;
            pz[slot] = z + 0.15f + random.nextFloat() * 0.70f;
            vx[slot] = (random.nextFloat() - 0.5f) * 3.2f;
            vy[slot] = 1.2f + random.nextFloat() * 2.8f;
            vz[slot] = (random.nextFloat() - 0.5f) * 3.2f;
            float duration = 0.45f + random.nextFloat() * 0.45f;
            life[slot] = duration;
            maxLife[slot] = duration;
            u0[slot] = baseU0 + ox * spanU;
            v0[slot] = baseV0 + oy * spanV;
            u1[slot] = baseU0 + (ox + patchSpan) * spanU;
            v1[slot] = baseV0 + (oy + patchSpan) * spanV;
            size[slot] = 0.10f + random.nextFloat() * 0.08f;
            pr[slot] = 1.0f;
            pg[slot] = 1.0f;
            pb[slot] = 1.0f;
            gravityFactor[slot] = 1.0f;
            shade[slot] = 1.0f;
            textured[slot] = true;
        }
    }

    /**
     * Sinh một hạt lửa tự phát sáng bay lơ lửng lên trên tại vị trí thực thể đang cháy.
     *
     * @param x tọa độ X thế giới
     * @param y tọa độ Y thế giới
     * @param z tọa độ Z thế giới
     */
    public void spawnFlame(float x, float y, float z) {
        if (disposed) {
            return;
        }
        int slot = allocateSlot();
        px[slot] = x + (random.nextFloat() - 0.5f) * 0.35f;
        py[slot] = y + (random.nextFloat() - 0.5f) * 0.35f;
        pz[slot] = z + (random.nextFloat() - 0.5f) * 0.35f;
        vx[slot] = (random.nextFloat() - 0.5f) * 0.45f;
        vy[slot] = 0.65f + random.nextFloat() * 0.85f;
        vz[slot] = (random.nextFloat() - 0.5f) * 0.45f;
        float duration = 0.35f + random.nextFloat() * 0.35f;
        life[slot] = duration;
        maxLife[slot] = duration;
        u0[slot] = 0.0f;
        v0[slot] = 0.0f;
        u1[slot] = 1.0f;
        v1[slot] = 1.0f;
        size[slot] = 0.12f + random.nextFloat() * 0.08f;
        pr[slot] = 1.0f;
        pg[slot] = 0.45f + random.nextFloat() * 0.40f;
        pb[slot] = 0.08f + random.nextFloat() * 0.12f;
        gravityFactor[slot] = -0.08f;
        shade[slot] = -1.0f;
        textured[slot] = false;
    }

    /**
     * Sinh các hạt giọt nước bắn tung tóe tại vị trí va chạm mặt nước.
     *
     * @param x     tọa độ X thế giới
     * @param y     tọa độ Y thế giới
     * @param z     tọa độ Z thế giới
     * @param count số lượng hạt cần sinh
     */
    public void spawnSplash(float x, float y, float z, int count) {
        if (disposed || count <= 0) {
            return;
        }
        for (int i = 0; i < count; i++) {
            int slot = allocateSlot();
            px[slot] = x + (random.nextFloat() - 0.5f) * 0.45f;
            py[slot] = y + random.nextFloat() * 0.20f;
            pz[slot] = z + (random.nextFloat() - 0.5f) * 0.45f;
            vx[slot] = (random.nextFloat() - 0.5f) * 2.8f;
            vy[slot] = 1.4f + random.nextFloat() * 2.4f;
            vz[slot] = (random.nextFloat() - 0.5f) * 2.8f;
            float duration = 0.35f + random.nextFloat() * 0.35f;
            life[slot] = duration;
            maxLife[slot] = duration;
            u0[slot] = 0.0f;
            v0[slot] = 0.0f;
            u1[slot] = 1.0f;
            v1[slot] = 1.0f;
            size[slot] = 0.09f + random.nextFloat() * 0.07f;
            pr[slot] = 0.35f + random.nextFloat() * 0.25f;
            pg[slot] = 0.65f + random.nextFloat() * 0.25f;
            pb[slot] = 0.95f + random.nextFloat() * 0.05f;
            gravityFactor[slot] = 0.85f;
            shade[slot] = 1.0f;
            textured[slot] = false;
        }
    }

    /**
     * Sinh chùm hạt hiệu ứng thuốc nổ theo mã màu RGB {@code 0xRRGGBB}.
     *
     * @param x   tọa độ X thế giới
     * @param y   tọa độ Y thế giới
     * @param z   tọa độ Z thế giới
     * @param rgb mã màu RGB đóng gói 24-bit
     */
    public void spawnPotionSplash(float x, float y, float z, int rgb) {
        if (disposed) {
            return;
        }
        float baseR = ((rgb >>> 16) & 0xFF) / 255.0f;
        float baseG = ((rgb >>> 8) & 0xFF) / 255.0f;
        float baseB = (rgb & 0xFF) / 255.0f;

        for (int i = 0; i < POTION_SPLASH_COUNT; i++) {
            float tone = 0.85f + random.nextFloat() * 0.15f;
            int slot = allocateSlot();
            px[slot] = x + (random.nextFloat() - 0.5f) * 0.60f;
            py[slot] = y + random.nextFloat() * 0.35f;
            pz[slot] = z + (random.nextFloat() - 0.5f) * 0.60f;
            vx[slot] = (random.nextFloat() - 0.5f) * 4.0f;
            vy[slot] = 0.8f + random.nextFloat() * 3.0f;
            vz[slot] = (random.nextFloat() - 0.5f) * 4.0f;
            float duration = 0.60f + random.nextFloat() * 0.50f;
            life[slot] = duration;
            maxLife[slot] = duration;
            u0[slot] = 0.0f;
            v0[slot] = 0.0f;
            u1[slot] = 1.0f;
            v1[slot] = 1.0f;
            size[slot] = 0.11f + random.nextFloat() * 0.09f;
            pr[slot] = Math.min(1.0f, baseR * tone);
            pg[slot] = Math.min(1.0f, baseG * tone);
            pb[slot] = Math.min(1.0f, baseB * tone);
            gravityFactor[slot] = 0.35f;
            shade[slot] = -1.0f;
            textured[slot] = false;
        }
    }

    /**
     * Cập nhật vị trí, vận tốc và tuổi thọ còn lại của toàn bộ hạt đang hoạt động theo cơ chế zero-GC.
     *
     * @param dt khoảng thời gian từ khung hình trước (giây)
     */
    public void update(float dt) {
        if (disposed || dt <= 0.0f || activeCount == 0) {
            return;
        }
        float drag = Math.max(0.0f, 1.0f - Math.min(0.5f, HORIZONTAL_DRAG_PER_SEC * dt));
        for (int i = 0; i < MAX_PARTICLES; i++) {
            if (!active[i]) {
                continue;
            }
            life[i] -= dt;
            if (life[i] <= 0.0f) {
                active[i] = false;
                activeCount--;
                continue;
            }
            vy[i] += PARTICLE_GRAVITY * gravityFactor[i] * dt;
            vx[i] *= drag;
            vz[i] *= drag;
            px[i] += vx[i] * dt;
            py[i] += vy[i] * dt;
            pz[i] += vz[i] * dt;
        }
    }

    /**
     * Dựng các quad billboard luôn xoay hướng về phía {@link Camera} từ ma trận View
     * và vẽ lên màn hình bằng {@link Mesh} động cấp phát 1 lần với {@code uUseVertexColor = 0}.
     *
     * @param shader     shader 3D đang bind sẵn {@code uProjection} và {@code uView}
     * @param camera     camera góc nhìn hiện tại dùng để lấy trục phải/lên cho billboard
     * @param blockAtlas texture atlas khối dùng cho các hạt mảnh vỡ block
     */
    public void render(ShaderProgram shader, Camera camera, Texture blockAtlas) {
        if (disposed || activeCount == 0 || shader == null || camera == null || Gdx.gl == null || mesh == null) {
            return;
        }

        // Trích trực tiếp vector Right (hàng 0) và Up (hàng 1) của camera từ ma trận View (zero-GC).
        float[] viewVal = camera.getViewMatrix().val;
        float rx = viewVal[Matrix4.M00];
        float ry = viewVal[Matrix4.M01];
        float rz = viewVal[Matrix4.M02];
        float ux = viewVal[Matrix4.M10];
        float uy = viewVal[Matrix4.M11];
        float uz = viewVal[Matrix4.M12];

        int floatOffset = 0;
        int texturedQuadCount = 0;
        int untexturedQuadCount = 0;

        // Lượt 1: gom toàn bộ hạt mảnh vỡ có texture để vẽ thành một lô duy nhất.
        for (int i = 0; i < MAX_PARTICLES; i++) {
            if (!active[i] || !textured[i]) {
                continue;
            }
            floatOffset = writeBillboardQuad(i, floatOffset, rx, ry, rz, ux, uy, uz);
            texturedQuadCount++;
        }

        // Lượt 2: gom các hạt màu thuần (lửa, bắn nước, thuốc) ngay phía sau trong cùng bộ đệm đỉnh.
        for (int i = 0; i < MAX_PARTICLES; i++) {
            if (!active[i] || textured[i]) {
                continue;
            }
            floatOffset = writeBillboardQuad(i, floatOffset, rx, ry, rz, ux, uy, uz);
            untexturedSlots[untexturedQuadCount++] = i;
        }

        int totalQuads = texturedQuadCount + untexturedQuadCount;
        if (totalQuads == 0) {
            return;
        }

        mesh.setVertices(vertices, 0, totalQuads * VERTICES_PER_QUAD * FLOATS_PER_VERTEX);

        modelMatrix.idt();
        shader.setUniformMatrix4f("uModel", modelMatrix);
        shader.setUniform1i("uEnvironmentMode", 0);
        shader.enableChunkColorMode(false);

        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        Gdx.gl.glEnable(GL20.GL_DEPTH_TEST);
        Gdx.gl.glDepthMask(false);
        Gdx.gl.glDisable(GL20.GL_CULL_FACE);

        try {
            if (texturedQuadCount > 0 && blockAtlas != null) {
                blockAtlas.bind();
                shader.setUniform1i("uUseTexture", 1);
                shader.setUniformVec4("uTintColor", 1.0f, 1.0f, 1.0f, 1.0f);
                mesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES, 0, texturedQuadCount * VERTICES_PER_QUAD);
            }
            if (untexturedQuadCount > 0) {
                shader.setUniform1i("uUseTexture", 0);
                for (int k = 0; k < untexturedQuadCount; k++) {
                    int slot = untexturedSlots[k];
                    float lifeRatio = maxLife[slot] > 0.0f ? life[slot] / maxLife[slot] : 0.0f;
                    float alpha = Math.max(0.0f, Math.min(1.0f, lifeRatio * 2.0f));
                    shader.setUniformVec4("uTintColor", pr[slot], pg[slot], pb[slot], alpha);
                    int vertexOffset = (texturedQuadCount + k) * VERTICES_PER_QUAD;
                    mesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES, vertexOffset, VERTICES_PER_QUAD);
                }
            }
        } finally {
            shader.setUniform1i("uUseTexture", 1);
            shader.setUniformVec4("uTintColor", 1.0f, 1.0f, 1.0f, 1.0f);
            Gdx.gl.glDepthMask(true);
            Gdx.gl.glEnable(GL20.GL_CULL_FACE);
            Gdx.gl.glDisable(GL20.GL_BLEND);
        }
    }

    /** Ghi 6 đỉnh của một quad billboard vào mảng {@link #vertices} tại chỗ (zero-GC). */
    private int writeBillboardQuad(int slot, int offset,
                                   float rx, float ry, float rz,
                                   float ux, float uy, float uz) {
        float half = size[slot] * 0.5f;
        float cx = px[slot];
        float cy = py[slot];
        float cz = pz[slot];

        float hrx = rx * half;
        float hry = ry * half;
        float hrz = rz * half;
        float hux = ux * half;
        float huy = uy * half;
        float huz = uz * half;

        // 4 góc của quad xoay hướng camera theo thứ tự BL, BR, TR, TL.
        float blX = cx - hrx - hux;
        float blY = cy - hry - huy;
        float blZ = cz - hrz - huz;

        float brX = cx + hrx - hux;
        float brY = cy + hry - huy;
        float brZ = cz + hrz - huz;

        float trX = cx + hrx + hux;
        float trY = cy + hry + huy;
        float trZ = cz + hrz + huz;

        float tlX = cx - hrx + hux;
        float tlY = cy - hry + huy;
        float tlZ = cz - hrz + huz;

        float pu0 = u0[slot];
        float pv0 = v0[slot];
        float pu1 = u1[slot];
        float pv1 = v1[slot];
        float s = shade[slot];

        offset = putVertex(offset, blX, blY, blZ, pu0, pv1, s);
        offset = putVertex(offset, brX, brY, brZ, pu1, pv1, s);
        offset = putVertex(offset, trX, trY, trZ, pu1, pv0, s);
        offset = putVertex(offset, blX, blY, blZ, pu0, pv1, s);
        offset = putVertex(offset, trX, trY, trZ, pu1, pv0, s);
        return putVertex(offset, tlX, tlY, tlZ, pu0, pv0, s);
    }

    /** Ghi 6 float của một đỉnh vào bộ đệm thành viên {@link #vertices}. */
    private int putVertex(int offset, float x, float y, float z, float u, float v, float s) {
        vertices[offset] = x;
        vertices[offset + 1] = y;
        vertices[offset + 2] = z;
        vertices[offset + 3] = u;
        vertices[offset + 4] = v;
        vertices[offset + 5] = s;
        return offset + FLOATS_PER_VERTEX;
    }

    /** Trả về số lượng hạt đang còn hoạt động trong pool (trong khoảng {@code 0..512}). */
    public int activeCount() {
        return activeCount;
    }

    /** Giải phóng {@link Mesh} trên GPU và đặt lại toàn bộ trạng thái hạt trong pool. */
    @Override
    public void dispose() {
        if (disposed) {
            return;
        }
        disposed = true;
        Arrays.fill(active, false);
        activeCount = 0;
        writeCursor = 0;
        if (mesh != null) {
            mesh.dispose();
        }
    }
}

package com.voxelgame.client.render;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.math.Matrix4;
import com.badlogic.gdx.math.Vector3;
import com.badlogic.gdx.utils.Disposable;

/**
 * Quản lý việc biên dịch (Compile), liên kết (Link) chương trình GLSL Shader 330 Core trên GPU
 * và truyền các biến Uniform từ Java xuống GPU thông qua libGDX, triển khai {@link Disposable}.
 *
 * THỂ HIỆN CÁC TÍNH CHẤT OOP:
 * 1. Tính Trừu tượng (Abstraction):
 *    - Ẩn toàn bộ thao tác GLSL cấp thấp đằng sau các phương thức trực quan như
 *      `enable3DWorldMode()`, `enable2DUIMode()`, `setUniformMatrix4f()`.
 * 2. Tính Đa hình lúc biên dịch (Compile-time Polymorphism / Method Overloading):
 *    - Nạp chồng phương thức `setUniformVec4(String, float, float, float, float)` và
 *      `setUniformVec3(String, Vector3)` giúp truyền màu sắc hoặc vector linh hoạt.
 * 3. Tính Đóng gói (Encapsulation):
 *    - Đóng gói đối tượng `com.badlogic.gdx.graphics.glutils.ShaderProgram` ở phạm vi `private final`.
 */
public class ShaderProgram implements Disposable {

    private final com.badlogic.gdx.graphics.glutils.ShaderProgram gdxShader;
    private final Matrix4 identityMatrix = new Matrix4();
    /** Giá trị {@code uWorldLight} hiện tại để các bộ vẽ tự phát sáng lưu và khôi phục an toàn. */
    private final Vector3 currentWorldLight = new Vector3(1f, 1f, 1f);

    /**
     * Mã nguồn Vertex Shader (GLSL 330 Core).
     */
    private static final String VERTEX_SHADER_SOURCE = """
            #version 330 core
            layout (location = 0) in vec3 aPos;
            layout (location = 1) in vec2 aTexCoord;
            layout (location = 2) in float aShade;
            layout (location = 3) in vec4 aColor;

            out vec2 vTexCoord;
            out float vShade;
            out vec3 vPosition;
            out vec3 vEyeOffset;
            out vec4 vColor;

            uniform mat4 uModel;
            uniform mat4 uView;
            uniform mat4 uProjection;
            uniform vec3 uFogEye;
            uniform int uUseVertexColor;

            void main() {
                vec4 worldPos = uModel * vec4(aPos, 1.0);
                vec4 viewPos = uView * worldPos;

                gl_Position = uProjection * viewPos;

                vTexCoord = aTexCoord;
                vShade = aShade;
                vPosition = aPos;
                // Dùng tọa độ sau biến đổi model để cả mesh chunk và thực thể nhận cùng khoảng cách.
                vEyeOffset = worldPos.xyz - uFogEye;
                // Chỉ đọc aColor khi vẽ chunk (7 floats/đỉnh); các mesh 6 floats mặc định dùng trắng (1, 1, 1, 1).
                if (uUseVertexColor == 1) {
                    vColor = aColor.a > 0.992
                            ? vec4(aColor.rgb, 1.0)
                            : vec4(aColor.rgb / max(aColor.a, 0.0039), 1.0);
                } else {
                    vColor = vec4(1.0);
                }
            }
            """;

    /**
     * Mã nguồn Fragment Shader (GLSL 330 Core).
     */
    private static final String FRAGMENT_SHADER_SOURCE = """
            #version 330 core
            in vec2 vTexCoord;
            in float vShade;
            in vec3 vPosition;
            in vec3 vEyeOffset;
            in vec4 vColor;

            out vec4 FragColor;

            uniform sampler2D uTexture;
            uniform int uUseTexture;
            uniform vec4 uTintColor;
            uniform float uMobWhiteFlash;
            uniform vec3 uWorldLight;
            uniform int uEnvironmentMode;
            uniform vec3 uSkyColor;
            uniform vec3 uHorizonColor;
            uniform vec3 uSunDirection;
            uniform float uHorizonGlow;
            uniform vec3 uCloudCenter;
            uniform int uFogEnabled;
            uniform vec2 uFogRange;
            uniform vec3 uLiquidFogColor;

            // Dùng chung màu theo hướng nhìn để địa hình xa nối liền với nền trời.
            vec3 atmosphereColor(vec3 direction) {
                float band = 1.0 - smoothstep(0.0, 0.33, abs(direction.y));
                float facing = smoothstep(-0.25, 1.0, dot(direction, uSunDirection));
                float glow = band * facing * uHorizonGlow;
                float zenith = smoothstep(0.0, 0.9, direction.y);
                vec3 sky = mix(uSkyColor, uSkyColor * vec3(0.70, 0.86, 0.98), zenith);
                return mix(sky, uHorizonColor, glow);
            }

            void main() {
                if (uEnvironmentMode == 1) {
                    // Mắt chìm thấy đúng màu nền, kể cả qua khoảng trống giữa các chunk.
                    vec3 sky = uFogEnabled == 2 ? uLiquidFogColor : atmosphereColor(normalize(vPosition));
                    FragColor = vec4(sky, 1.0);
                    return;
                }

                // Thiên thể dùng blend cộng, nên ẩn hẳn bên dưới mặt chất lỏng.
                if (uFogEnabled == 2 && uEnvironmentMode == 3) {
                    discard;
                }

                // 1. Xác định màu cơ sở (lấy từ Texture Atlas hoặc dùng màu thuần túy cho 2D UI)
                vec4 baseColor;
                if (uUseTexture == 1) {
                    baseColor = texture(uTexture, vTexCoord) * uTintColor * vColor;
                } else {
                    baseColor = uTintColor * vColor;
                }

                // Loại bỏ các điểm ảnh hoàn toàn trong suốt (Alpha Testing cơ bản)
                if (uEnvironmentMode == 2) {
                    // Làm mờ mép mặt phẳng mây ngoài vùng nhìn lân cận.
                    float distanceToEye = length(vPosition.xz - uCloudCenter.xz);
                    baseColor.a *= 1.0 - smoothstep(300.0, 500.0, distanceToEye);
                }
                if (uEnvironmentMode == 3) {
                    // Che phần thiên thể nằm dưới đường chân trời.
                    baseColor.a *= smoothstep(-1.0, 1.0, vPosition.y);
                }
                if (uEnvironmentMode == 4) {
                    // Với giáng thủy, hệ số đỉnh điều chỉnh alpha thay cho độ sáng theo mặt.
                    baseColor.a *= vShade;
                }
                if (baseColor.a < (uEnvironmentMode == 0 ? 0.05 : 0.015)) {
                    discard;
                }

                // 2. Nhân với hệ số độ sáng theo hướng mặt khối (Ambient/Directional Face Shading)
                // Dấu âm của hệ số mặt dành cho khối và mắt mob phát sáng tự thân.
                float faceShade = uEnvironmentMode == 4 ? 1.0 : abs(vShade);
                vec3 litColor = baseColor.rgb * faceShade * (vShade < 0.0 ? vec3(1.0) : uWorldLight);
                if (uMobWhiteFlash > 0.0) {
                    litColor = mix(litColor, vec3(1.0), uMobWhiteFlash);
                }

                if (uFogEnabled == 2 || (uEnvironmentMode == 0 && uFogEnabled == 1)) {
                    float distanceToEye = length(vEyeOffset);
                    if (distanceToEye > uFogRange.x) {
                        float fog = clamp((distanceToEye - uFogRange.x) / (uFogRange.y - uFogRange.x), 0.0, 1.0);
                        // Trộn RGB sau khi tính ánh sáng và giữ nguyên độ trong của mặt khối.
                        vec3 fogColor = uFogEnabled == 2 ? uLiquidFogColor
                                : atmosphereColor(vEyeOffset / distanceToEye);
                        litColor = mix(litColor, fogColor, fog);
                        // Mây và giáng thủy xa chìm hẳn vào nền, để giữ màu của hình học phía trước.
                        if (uFogEnabled == 2 && uEnvironmentMode != 0) {
                            baseColor.a *= 1.0 - fog;
                        }
                    }
                }

                FragColor = vec4(litColor, baseColor.a);
            }
            """;

    public ShaderProgram() {
        // Tắt chuỗi tiền tố mặc định của libGDX để giữ nguyên #version 330 core ở dòng 1
        com.badlogic.gdx.graphics.glutils.ShaderProgram.prependVertexCode = "";
        com.badlogic.gdx.graphics.glutils.ShaderProgram.prependFragmentCode = "";

        gdxShader = new com.badlogic.gdx.graphics.glutils.ShaderProgram(
                VERTEX_SHADER_SOURCE,
                FRAGMENT_SHADER_SOURCE
        );

        if (!gdxShader.isCompiled()) {
            throw new RuntimeException("Lỗi biên dịch GLSL Shader:\n" + gdxShader.getLog());
        }

        bind();
        setUniform1i("uTexture", 0);
        setUniform1i("uUseTexture", 1);
        setUniform1i("uUseVertexColor", 0);
        setUniformVec4("uTintColor", 1.0f, 1.0f, 1.0f, 1.0f);
        setUniform1f("uMobWhiteFlash", 0f);
        setUniformVec3("uWorldLight", 1f, 1f, 1f);
        setUniform1i("uEnvironmentMode", 0);
        disableDistanceFog();
        unbind();
    }

    public void setUniformMatrix4f(String name, Matrix4 matrix) {
        gdxShader.setUniformMatrix(name, matrix);
    }

    public void setUniformVec3(String name, Vector3 vec) {
        if ("uWorldLight".equals(name) && vec != null) {
            currentWorldLight.set(vec);
        }
        gdxShader.setUniformf(name, vec);
    }

    public void setUniformVec3(String name, float x, float y, float z) {
        if ("uWorldLight".equals(name)) {
            currentWorldLight.set(x, y, z);
        }
        gdxShader.setUniformf(name, x, y, z);
    }

    /** Sao chép giá trị {@code uWorldLight} hiện tại vào {@code out} mà không cấp phát bộ nhớ mới. */
    public void copyWorldLight(Vector3 out) {
        if (out != null) {
            out.set(currentWorldLight);
        }
    }

    public void setUniformVec4(String name, float r, float g, float b, float a) {
        gdxShader.setUniformf(name, r, g, b, a);
    }

    public void setUniform1f(String name, float value) {
        gdxShader.setUniformf(name, value);
    }

    public void setUniform1i(String name, int value) {
        gdxShader.setUniformi(name, value);
    }

    /**
     * Chuyển Shader sang chế độ vẽ thế giới 3D với Texture Atlas và màu gốc.
     */
    public void enable3DWorldMode() {
        setUniform1i("uUseTexture", 1);
        setUniform1i("uUseVertexColor", 0);
        setUniformVec4("uTintColor", 1.0f, 1.0f, 1.0f, 1.0f);
    }

    /**
     * Bật hoặc tắt chế độ đọc màu đỉnh {@code aColor} (location 3) khi vẽ mesh chunk.
     * Mặc định tắt ({@code false}) để các mesh 6 floats (UIRenderer, MobRenderer, EnvironmentMesh, ItemEntity)
     * luôn dùng màu trắng {@code vec4(1.0)} mà không bị lỗi định dạng đỉnh.
     */
    public void enableChunkColorMode(boolean enabled) {
        setUniform1i("uUseVertexColor", enabled ? 1 : 0);
    }

    /** Cập nhật vị trí mắt và hai mốc sương, tính bằng block thế giới. */
    public void enableDistanceFog(Vector3 eye, float start, float end) {
        setUniformVec3("uFogEye", eye);
        gdxShader.setUniformf("uFogRange", start, end);
        setUniform1i("uFogEnabled", 1);
    }

    /** Bật sương màu chất lỏng cho hình học, nền trời, mây và giáng thủy. */
    public void enableLiquidFog(Vector3 eye, Camera.LiquidView liquid) {
        setUniformVec3("uFogEye", eye);
        gdxShader.setUniformf("uFogRange", liquid.fogStart, liquid.fogEnd);
        setUniformVec3("uLiquidFogColor", liquid.red, liquid.green, liquid.blue);
        setUniform1i("uFogEnabled", 2);
    }

    /** Kết thúc sương thế giới trước khi chuyển sang lượt vẽ không dùng sương. */
    public void disableDistanceFog() {
        setUniform1i("uFogEnabled", 0);
    }

    /**
     * Chuyển Shader sang phép chiếu 2D và đặt View, Model về ma trận đơn vị.
     */
    public void enable2DUIMode(Matrix4 orthoProjectionMatrix) {
        setUniform1i("uUseVertexColor", 0);
        setUniformVec3("uWorldLight", 1f, 1f, 1f);
        setUniformMatrix4f("uProjection", orthoProjectionMatrix);
        setUniformMatrix4f("uView", identityMatrix);
        setUniformMatrix4f("uModel", identityMatrix);
    }

    public void bind() {
        gdxShader.bind();
    }

    public void unbind() {
        Gdx.gl.glUseProgram(0);
    }

    public com.badlogic.gdx.graphics.glutils.ShaderProgram getGdxShader() {
        return gdxShader;
    }

    @Override
    public void dispose() {
        if (gdxShader != null) {
            gdxShader.dispose();
        }
    }
}

package com.voxelgame.client.render;

import com.voxelgame.world.level.Chunk;
import com.voxelgame.world.level.WorldTime;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.Texture;
import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Matrix4;
import com.badlogic.gdx.math.Vector3;
import com.badlogic.gdx.utils.Disposable;
import com.badlogic.gdx.utils.GdxNativesLoader;
import static com.badlogic.gdx.graphics.Texture.TextureFilter.Nearest;
import static com.badlogic.gdx.graphics.Texture.TextureWrap.ClampToEdge;
import static com.badlogic.gdx.graphics.Texture.TextureWrap.Repeat;

/** Vẽ vòm trời, quỹ đạo thiên thể và tầng mây 3D dày 4 block, đồng thời tính ánh sáng môi trường. */
public final class SkyRenderer implements Disposable {
    /** Vòm và thiên thể đủ xa để dùng chung phép chiếu của camera. */
    private static final float SKY_RADIUS = 400f;
    private static final float ORBIT_RADIUS = 320f;
    /** Cao độ đáy tầng mây (Y=140) và độ dày khối mây 3D (4 block: Y=140..144). */
    public static final float CLOUD_HEIGHT = 140f;
    public static final float CLOUD_THICKNESS = 4.0f;
    /** Chu kỳ lặp lại lưới mây theo trục X/Z tính bằng block thế giới (256 texel × 3 block/texel). */
    private static final float CLOUD_PERIOD = 768f;
    private static final float CLOUD_RADIUS = 500f;
    /** Ngưỡng alpha để coi một ô trên {@code clouds.png} là khối mây đặc. */
    private static final int CLOUD_ALPHA_THRESHOLD = 128;
    /** Độ sáng tương đối theo 6 hướng mặt của khối mây 3D (âm để shader tự phát sáng không nhân uWorldLight). */
    private static final float CLOUD_SHADE_TOP = -1.00f;
    private static final float CLOUD_SHADE_BOTTOM = -0.72f;
    private static final float CLOUD_SHADE_NORTH_SOUTH = -0.85f;
    private static final float CLOUD_SHADE_EAST_WEST = -0.90f;

    /** Sương trời quang giữ được đường nét núi xa và hòa vào trời trước mặt phẳng cắt. */
    private static final float CLEAR_FOG_START = 288f;
    private static final float CLEAR_FOG_END = 640f;
    /** Khi giáng thủy đạt đỉnh, vùng chuyển màu tiến gần camera hơn. */
    private static final float STORM_FOG_START = 96f;
    private static final float STORM_FOG_END = 384f;
    /** Thứ tự tám pha từ trăng tròn đến lưỡi liềm cuối tháng. */
    private static final String[] MOON_PHASES = {
            "full_moon", "waning_gibbous", "third_quarter", "waning_crescent",
            "new_moon", "waxing_crescent", "first_quarter", "waxing_gibbous"
    };

    private final EnvironmentMesh dome;
    private final EnvironmentMesh quad;
    private final EnvironmentMesh cloudMesh;
    private final Matrix4 rotationView = new Matrix4();
    private final Matrix4 cloudModelMatrix = new Matrix4();
    private final Matrix4 identity = new Matrix4();
    private final Vector3 worldLight = new Vector3();
    private final Vector3 cloudCenterLocal = new Vector3();
    private Texture sunTexture;
    private Texture cloudTexture;
    private final Texture[] moonTextures = new Texture[MOON_PHASES.length];
    private final int exposedCloudQuads;
    private float daylight;
    private float twilight;
    private boolean disposed;

    /**
     * Nạp ảnh thiên thể, đọc {@code clouds.png} một lần để dựng lưới khối mây 3D dày 4 block
     * có loại bỏ mặt trong giữa các ô liền kề, và tải vòm tĩnh lên GPU khi có ngữ cảnh OpenGL.
     * Hỗ trợ khởi tạo an toàn trong kiểm thử CPU không có OpenGL ({@code Gdx.gl == null}).
     */
    public SkyRenderer() {
        GdxNativesLoader.load();
        Pixmap cloudsPixmap = null;
        EnvironmentMesh createdDome = null;
        EnvironmentMesh createdQuad = null;
        EnvironmentMesh createdCloudMesh = null;
        int quadCount = 0;

        try {
            cloudsPixmap = com.voxelgame.client.render.Texture.loadPixmapFlexible(
                    "textures/environment/clouds.png", "environment/clouds.png", "clouds.png");
            boolean[][] cloudMask = cloudsPixmap != null ? extractCloudMask(cloudsPixmap) : new boolean[0][0];
            quadCount = cloudsPixmap != null ? countExposedCloudQuads(cloudMask) : 0;

            if (Gdx.gl != null) {
                createdDome = new EnvironmentMesh(6);
                createdQuad = new EnvironmentMesh(1);
                sunTexture = EnvironmentMesh.loadTexture("celestial/sun.png", ClampToEdge, ClampToEdge);
                if (cloudsPixmap != null) {
                    cloudTexture = createCloudTexture(cloudsPixmap);
                } else {
                    cloudTexture = EnvironmentMesh.loadTexture("clouds.png", Repeat, Repeat);
                }
                for (int i = 0; i < MOON_PHASES.length; i++) {
                    moonTextures[i] = EnvironmentMesh.loadTexture(
                            "celestial/moon/" + MOON_PHASES[i] + ".png", ClampToEdge, ClampToEdge);
                }
                buildDome(createdDome);
                createdCloudMesh = new EnvironmentMesh(Math.max(1, quadCount));
                if (cloudsPixmap != null && quadCount > 0) {
                    buildCloudVolumeMesh(cloudsPixmap, cloudMask, createdCloudMesh);
                    createdCloudMesh.upload();
                }
            }
        } catch (RuntimeException | Error error) {
            if (createdDome != null) {
                createdDome.dispose();
            }
            if (createdQuad != null) {
                createdQuad.dispose();
            }
            if (createdCloudMesh != null) {
                createdCloudMesh.dispose();
            }
            disposeTextures();
            throw error;
        } finally {
            if (cloudsPixmap != null) {
                cloudsPixmap.dispose();
            }
        }

        this.dome = createdDome;
        this.quad = createdQuad;
        this.cloudMesh = createdCloudMesh;
        this.exposedCloudQuads = quadCount;
    }

    /** Tạo {@link Texture} lặp cạnh Nearest từ {@link Pixmap} của {@code clouds.png} đã đọc sẵn. */
    private static Texture createCloudTexture(Pixmap cloudsPixmap) {
        Texture texture = new Texture(cloudsPixmap);
        try {
            texture.setFilter(Nearest, Nearest);
            texture.setWrap(Repeat, Repeat);
            return texture;
        } catch (RuntimeException | Error failure) {
            texture.dispose();
            throw failure;
        }
    }

    /**
     * Trích xuất mặt nạ nhị phân {@code [x][z]} từ {@code clouds.png}: ô có {@code alpha > 128}
     * được đánh dấu là ô mây đặc.
     */
    public static boolean[][] extractCloudMask(Pixmap cloudsPixmap) {
        if (cloudsPixmap == null) {
            return new boolean[0][0];
        }
        int width = cloudsPixmap.getWidth();
        int height = cloudsPixmap.getHeight();
        boolean[][] mask = new boolean[width][height];
        for (int gx = 0; gx < width; gx++) {
            for (int gz = 0; gz < height; gz++) {
                int rgba = com.voxelgame.client.render.Texture.readNormalizedPixel(cloudsPixmap, gx, gz);
                int alpha = rgba & 0xFF;
                mask[gx][gz] = alpha > CLOUD_ALPHA_THRESHOLD;
            }
        }
        return mask;
    }

    /**
     * Đếm tổng số mặt tứ giác lộ thiên của tầng mây 3D sau khi loại bỏ mặt tiếp giáp giữa
     * hai ô mây liền kề (kể cả qua biên tuần hoàn của ảnh).
     */
    public static int countExposedCloudQuads(boolean[][] mask) {
        if (mask == null || mask.length == 0 || mask[0].length == 0) {
            return 0;
        }
        int width = mask.length;
        int height = mask[0].length;
        int count = 0;
        for (int gx = 0; gx < width; gx++) {
            int nextX = (gx + 1) % width;
            int prevX = (gx - 1 + width) % width;
            for (int gz = 0; gz < height; gz++) {
                if (!mask[gx][gz]) {
                    continue;
                }
                // Mặt trên (+Y) và mặt dưới (-Y) luôn lộ thiên vì tầng mây chỉ dày một lớp.
                count += 2;
                int nextZ = (gz + 1) % height;
                int prevZ = (gz - 1 + height) % height;
                if (!mask[nextX][gz]) {
                    count++;
                }
                if (!mask[prevX][gz]) {
                    count++;
                }
                if (!mask[gx][nextZ]) {
                    count++;
                }
                if (!mask[gx][prevZ]) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Trả về số lượng mặt tứ giác của mesh mây 3D đã tính khi khởi tạo. */
    public int getExposedCloudQuadCount() {
        return exposedCloudQuads;
    }

    /** Dựng mesh mây 3D dày {@link #CLOUD_THICKNESS} (Y=140..144) một lần vào {@link EnvironmentMesh}. */
    private static void buildCloudVolumeMesh(Pixmap cloudsPixmap, boolean[][] mask, EnvironmentMesh target) {
        int width = mask.length;
        int height = mask[0].length;
        float cellWidth = CLOUD_PERIOD / width;
        float cellDepth = CLOUD_PERIOD / height;
        float y0 = CLOUD_HEIGHT;
        float y1 = CLOUD_HEIGHT + CLOUD_THICKNESS;

        target.clear();
        for (int gx = 0; gx < width; gx++) {
            float x0 = gx * cellWidth;
            float x1 = (gx + 1) * cellWidth;
            float u = (gx + 0.5f) / width;
            int nextX = (gx + 1) % width;
            int prevX = (gx - 1 + width) % width;

            for (int gz = 0; gz < height; gz++) {
                if (!mask[gx][gz]) {
                    continue;
                }
                float z0 = gz * cellDepth;
                float z1 = (gz + 1) * cellDepth;
                float v = (gz + 0.5f) / height;
                int nextZ = (gz + 1) % height;
                int prevZ = (gz - 1 + height) % height;

                // Mặt trên (+Y) và mặt dưới (-Y) với thứ tự đỉnh ngược chiều kim đồng hồ nhìn từ ngoài.
                target.quad(x0, y1, z1, x1, y1, z1, x1, y1, z0, x0, y1, z0, u, v, u, v, CLOUD_SHADE_TOP);
                target.quad(x0, y0, z0, x1, y0, z0, x1, y0, z1, x0, y0, z1, u, v, u, v, CLOUD_SHADE_BOTTOM);

                // Bốn thành bên chỉ dựng khi ô kề theo hướng tương ứng không phải mây đặc.
                if (!mask[nextX][gz]) {
                    target.quad(x1, y0, z1, x1, y0, z0, x1, y1, z0, x1, y1, z1, u, v, u, v, CLOUD_SHADE_EAST_WEST);
                }
                if (!mask[prevX][gz]) {
                    target.quad(x0, y0, z0, x0, y0, z1, x0, y1, z1, x0, y1, z0, u, v, u, v, CLOUD_SHADE_EAST_WEST);
                }
                if (!mask[gx][nextZ]) {
                    target.quad(x0, y0, z1, x1, y0, z1, x1, y1, z1, x0, y1, z1, u, v, u, v, CLOUD_SHADE_NORTH_SOUTH);
                }
                if (!mask[gx][prevZ]) {
                    target.quad(x1, y0, z0, x0, y0, z0, x0, y1, z0, x1, y1, z0, u, v, u, v, CLOUD_SHADE_NORTH_SOUTH);
                }
            }
        }
    }

    /** Dựng hộp sáu mặt; shader chuẩn hóa vectơ nhìn để tạo màu trời theo hướng. */
    private static void buildDome(EnvironmentMesh target) {
        float a = -SKY_RADIUS;
        float b = SKY_RADIUS;
        target.quad(a, b, a, a, a, a, b, a, a, b, b, a, 0, 0, 1, 1, -1);
        target.quad(a, b, b, a, a, b, b, a, b, b, b, b, 0, 0, 1, 1, -1);
        target.quad(a, b, a, a, a, a, a, a, b, a, b, b, 0, 0, 1, 1, -1);
        target.quad(b, b, a, b, a, a, b, a, b, b, b, b, 0, 0, 1, 1, -1);
        target.quad(a, b, a, a, b, b, b, b, b, b, b, a, 0, 0, 1, 1, -1);
        target.quad(a, a, a, a, a, b, b, a, b, b, a, a, 0, 0, 1, 1, -1);
        target.upload();
    }

    /** Tính màu đêm, ngày và ánh ấm chuyển tiếp rồi vẽ nền trời không ghi chiều sâu. */
    public void renderSky(ShaderProgram shader, Matrix4 view, WorldTime time, float storm) {
        if (disposed || dome == null || quad == null) {
            return;
        }
        float sunX = time.sunX();
        float sunY = time.sunY();
        daylight = smoothStep(-0.20f, 0.33f, sunY);
        twilight = 1f - smoothStep(0f, 0.32f, Math.abs(sunY));
        float skyR = MathUtils.lerp(0.02f, 0.53f, daylight);
        float skyG = MathUtils.lerp(0.03f, 0.81f, daylight);
        float skyB = MathUtils.lerp(0.08f, 0.92f, daylight);
        shader.setUniformVec3("uSkyColor", MathUtils.lerp(skyR, 0.055f + daylight * 0.30f, storm),
                MathUtils.lerp(skyG, 0.066f + daylight * 0.34f, storm),
                MathUtils.lerp(skyB, 0.09f + daylight * 0.38f, storm));
        shader.setUniformVec3("uHorizonColor", 1f, 0.40f, 0.24f);
        shader.setUniformVec3("uSunDirection", sunX, 0, 0);
        shader.setUniform1f("uHorizonGlow", twilight * (1f - 0.82f * storm) * 0.85f);

        // Bỏ tịnh tiến để vòm và thiên thể chỉ chuyển khi góc nhìn thay đổi.
        rotationView.set(view);
        rotationView.val[Matrix4.M03] = 0;
        rotationView.val[Matrix4.M13] = 0;
        rotationView.val[Matrix4.M23] = 0;
        shader.setUniformMatrix4f("uView", rotationView);
        shader.setUniformMatrix4f("uModel", identity);
        Gdx.gl.glDisable(GL20.GL_DEPTH_TEST);
        Gdx.gl.glDisable(GL20.GL_CULL_FACE);
        Gdx.gl.glDepthMask(false);
        try {
            shader.setUniform1i("uEnvironmentMode", 1);
            dome.draw(shader);
            shader.setUniform1i("uEnvironmentMode", 3);
            Gdx.gl.glEnable(GL20.GL_BLEND);
            Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE);
            float visibility = 1f - storm;
            renderCelestial(shader, sunTexture, sunX, sunY, 26f, visibility);
            renderCelestial(shader, moonTextures[(int) (time.dayCount() % MOON_PHASES.length)],
                    -sunX, -sunY, 19f, visibility);
        } finally {
            shader.setUniform1i("uEnvironmentMode", 0);
            shader.setUniformMatrix4f("uView", view);
            shader.enable3DWorldMode();
            Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
            Gdx.gl.glDisable(GL20.GL_BLEND);
            Gdx.gl.glDepthMask(true);
            Gdx.gl.glEnable(GL20.GL_CULL_FACE);
            Gdx.gl.glEnable(GL20.GL_DEPTH_TEST);
        }

        // Hệ số mặt khối được nhân với ánh sáng nền; ánh đêm vẫn giữ chi tiết.
        float dim = 1f - 0.24f * storm;
        worldLight.set(MathUtils.lerp(0.22f, 1f, daylight) * dim,
                MathUtils.lerp(0.25f, 1f, daylight) * dim * (1f - 0.10f * twilight),
                MathUtils.lerp(0.34f, 1f, daylight) * dim * (1f - 0.20f * twilight));
        shader.setUniformVec3("uWorldLight", worldLight);
    }

    /** Bật sương trong lượt kết xuất thế giới, dùng màu vừa đặt cho vòm trời. */
    public float enableWorldFog(ShaderProgram shader, Vector3 eye, float storm) {
        float end = MathUtils.lerp(CLEAR_FOG_END, STORM_FOG_END, storm);
        shader.enableDistanceFog(eye, MathUtils.lerp(CLEAR_FOG_START, STORM_FOG_START, storm), end);
        // Vẫn giữ depth của địa hình trước toàn bộ vòng mây 3D dày 4 block còn nhìn thấy.
        float cloudDeltaY = Math.max(
                Math.abs(CLOUD_HEIGHT - eye.y),
                Math.abs((CLOUD_HEIGHT + CLOUD_THICKNESS) - eye.y));
        float cloudDistance = (float) Math.sqrt(CLOUD_RADIUS * CLOUD_RADIUS + cloudDeltaY * cloudDeltaY);
        return Math.max(end + 2 * Chunk.SIZE, cloudDistance);
    }

    /** Dựng ảnh trên mặt phẳng tiếp xúc quỹ đạo; trục Z giữ cạnh ngang của ảnh. */
    private void renderCelestial(ShaderProgram shader, Texture image, float x, float y,
                                 float size, float visibility) {
        if (visibility <= 0f || y * ORBIT_RADIUS < -size) {
            return;
        }
        float centerX = x * ORBIT_RADIUS;
        float centerY = y * ORBIT_RADIUS;
        float tangentX = -y * size;
        float tangentY = x * size;
        quad.clear();
        quad.quad(centerX + tangentX, centerY + tangentY, -size,
                centerX - tangentX, centerY - tangentY, -size,
                centerX - tangentX, centerY - tangentY, size,
                centerX + tangentX, centerY + tangentY, size, 0, 0, 1, 1, -1);
        quad.upload();
        image.bind(0);
        shader.setUniformVec4("uTintColor", 1f, 1f, 1f, visibility);
        quad.draw(shader);
    }

    /**
     * Vẽ mây 3D dày 4 block trong không gian thế giới bằng một {@link EnvironmentMesh} tĩnh,
     * chỉ dịch {@code uModel} theo chu kỳ và vị trí mắt (zero-GC), kết hợp depth pre-pass
     * để mây bán trong suốt không bị chồng mờ hai lớp.
     */
    public void renderClouds(ShaderProgram shader, Vector3 eye, double seconds, float storm) {
        if (disposed || cloudMesh == null || cloudTexture == null || exposedCloudQuads <= 0) {
            return;
        }

        float red = MathUtils.lerp(0.22f, 1f, daylight);
        float green = MathUtils.lerp(0.27f, 0.98f, daylight) * (1f - 0.13f * twilight);
        float blue = MathUtils.lerp(0.38f, 0.97f, daylight) * (1f - 0.22f * twilight);
        shader.setUniformVec4("uTintColor", MathUtils.lerp(red, red * 0.55f, storm),
                MathUtils.lerp(green, green * 0.60f, storm),
                MathUtils.lerp(blue, blue * 0.66f, storm), 0.85f + 0.13f * storm);
        shader.setUniform1i("uEnvironmentMode", 2);

        // Dịch lưới mây về phía -X theo thời gian, giữ phần dư trong [0, CLOUD_PERIOD).
        float driftBlocks = (float) (((seconds * 0.65) % CLOUD_PERIOD + CLOUD_PERIOD) % CLOUD_PERIOD);
        int minTx = (int) Math.floor((eye.x - CLOUD_RADIUS + driftBlocks) / CLOUD_PERIOD);
        int maxTx = (int) Math.floor((eye.x + CLOUD_RADIUS + driftBlocks) / CLOUD_PERIOD);
        int minTz = (int) Math.floor((eye.z - CLOUD_RADIUS) / CLOUD_PERIOD);
        int maxTz = (int) Math.floor((eye.z + CLOUD_RADIUS) / CLOUD_PERIOD);
        boolean insideCloudBand = eye.y >= CLOUD_HEIGHT - 0.5f && eye.y <= CLOUD_HEIGHT + CLOUD_THICKNESS + 0.5f;

        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        if (insideCloudBand) {
            Gdx.gl.glDisable(GL20.GL_CULL_FACE);
        } else {
            Gdx.gl.glEnable(GL20.GL_CULL_FACE);
        }
        try {
            cloudTexture.bind(0);
            // Lượt 1: ghi độ sâu bề mặt mây gần nhất để ngăn tự chồng alpha bên trong khối mây 3D.
            Gdx.gl.glColorMask(false, false, false, false);
            Gdx.gl.glDepthMask(true);
            drawVisibleCloudTiles(shader, eye, driftBlocks, minTx, maxTx, minTz, maxTz);

            // Lượt 2: chỉ tô màu những điểm ảnh khớp đúng độ sâu gần nhất vừa ghi.
            Gdx.gl.glColorMask(true, true, true, true);
            Gdx.gl.glDepthMask(false);
            Gdx.gl.glDepthFunc(GL20.GL_EQUAL);
            drawVisibleCloudTiles(shader, eye, driftBlocks, minTx, maxTx, minTz, maxTz);
        } finally {
            Gdx.gl.glColorMask(true, true, true, true);
            Gdx.gl.glDepthFunc(GL20.GL_LESS);
            Gdx.gl.glDepthMask(true);
            Gdx.gl.glEnable(GL20.GL_CULL_FACE);
            Gdx.gl.glDisable(GL20.GL_BLEND);
            shader.setUniformMatrix4f("uModel", identity);
            shader.setUniform1i("uEnvironmentMode", 0);
            shader.enable3DWorldMode();
        }
    }

    /** Vẽ các ô chu kỳ mây giao với vùng nhìn tròn bán kính {@link #CLOUD_RADIUS} quanh mắt. */
    private void drawVisibleCloudTiles(ShaderProgram shader, Vector3 eye, float driftBlocks,
                                       int minTx, int maxTx, int minTz, int maxTz) {
        float maxDistSq = CLOUD_RADIUS * CLOUD_RADIUS;
        for (int tx = minTx; tx <= maxTx; tx++) {
            float shiftX = tx * CLOUD_PERIOD - driftBlocks;
            float nearestX = MathUtils.clamp(eye.x, shiftX, shiftX + CLOUD_PERIOD);
            float dx = eye.x - nearestX;
            for (int tz = minTz; tz <= maxTz; tz++) {
                float shiftZ = tz * CLOUD_PERIOD;
                float nearestZ = MathUtils.clamp(eye.z, shiftZ, shiftZ + CLOUD_PERIOD);
                float dz = eye.z - nearestZ;
                if (dx * dx + dz * dz > maxDistSq) {
                    continue;
                }
                cloudModelMatrix.setToTranslation(shiftX, 0f, shiftZ);
                // Chuyển tâm mắt về hệ tọa độ cục bộ của mesh để phép tính khoảng cách mờ rìa khớp 100%.
                cloudCenterLocal.set(eye.x - shiftX, eye.y, eye.z - shiftZ);
                shader.setUniformMatrix4f("uModel", cloudModelMatrix);
                shader.setUniformVec3("uCloudCenter", cloudCenterLocal);
                cloudMesh.draw(shader);
            }
        }
    }

    /** Đường cong bậc ba có đạo hàm bằng 0 ở hai đầu vùng chuyển. */
    private static float smoothStep(float start, float end, float value) {
        float ratio = MathUtils.clamp((value - start) / (end - start), 0f, 1f);
        return ratio * ratio * (3f - 2f * ratio);
    }

    /** Giải phóng các ảnh thiên thể nếu đã tạo. */
    private void disposeTextures() {
        if (sunTexture != null) {
            sunTexture.dispose();
            sunTexture = null;
        }
        if (cloudTexture != null) {
            cloudTexture.dispose();
            cloudTexture = null;
        }
        for (int i = 0; i < moonTextures.length; i++) {
            if (moonTextures[i] != null) {
                moonTextures[i].dispose();
                moonTextures[i] = null;
            }
        }
    }

    /** Giải phóng toàn bộ ảnh pha trăng, mặt trời, mây và các mesh trên GPU. */
    @Override
    public void dispose() {
        if (disposed) {
            return;
        }
        disposed = true;
        if (dome != null) {
            dome.dispose();
        }
        if (quad != null) {
            quad.dispose();
        }
        if (cloudMesh != null) {
            cloudMesh.dispose();
        }
        disposeTextures();
    }
}

package com.voxelgame.client.render;

import com.voxelgame.world.level.block.Block;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.Texture.TextureFilter;
import com.badlogic.gdx.graphics.Texture.TextureWrap;
import com.badlogic.gdx.utils.Disposable;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Random;
import java.util.stream.Stream;

/**
 * Quản lý việc đọc các file ảnh (.png, .jpg), tự động chuẩn hóa về kích thước 16x16 pixel
 * và đóng gói thành một tấm ảnh "Texture Atlas" 128x96 duy nhất trên VRAM GPU thông qua
 * thư viện đồ họa libGDX, triển khai {@link Disposable}.
 *
 * THỂ HIỆN CÁC TÍNH CHẤT OOP:
 * 1. Tính Trừu tượng (Abstraction):
 *    - Che giấu toàn bộ quá trình đọc file linh hoạt đa tầng, giải mã ảnh CPU qua Pixmap,
 *      lấy mẫu điểm ảnh trung tâm (Nearest-Neighbor Resampling), sinh nền Procedural Pixel Art
 *      và cấu hình tham số OpenGL (Nearest, ClampToEdge).
 * 2. Tính Đóng gói (Encapsulation):
 *    - Đối tượng `com.badlogic.gdx.graphics.Texture` nội bộ được khóa `private final`, cung cấp
 *      các phương thức thao tác an toàn `bind()`, `unbind()`, `getGdxTexture()` và `dispose()`.
 */
public class Texture implements Disposable {

    // Kích thước của 1 ô chất liệu tiêu chuẩn (16x16 pixel)
    public static final int TILE_SIZE = 16;
    // Số cột và số hàng của lưới Texture Atlas (8x6 = 48 ô)
    public static final int ATLAS_COLS = 8;
    public static final int ATLAS_ROWS = 6;
    // Kích thước tổng thể của tấm ảnh Texture Atlas (128x96 pixel)
    public static final int ATLAS_WIDTH = TILE_SIZE * ATLAS_COLS;
    public static final int ATLAS_HEIGHT = TILE_SIZE * ATLAS_ROWS;

    // Định danh vị trí (Tile Index) của từng loại bề mặt trong Texture Atlas
    public static final int TILE_DIRT = 0;
    public static final int TILE_GRASS_TOP = 1;
    public static final int TILE_GRASS_SIDE = 2;
    public static final int TILE_STONE = 3;
    public static final int TILE_BEDROCK = 4;
    public static final int TILE_OAK_LOG_SIDE = 5;
    public static final int TILE_OAK_LOG_TOP = 6;
    public static final int TILE_OAK_LEAVES = 7;
    public static final int TILE_WATER = 8;
    public static final int TILE_LAVA = 9;

    // Ô có sẵn cho sa mạc và miền tuyết. Snow Block và Snow Layers dùng chung TILE_SNOW.
    public static final int TILE_SAND = 10;
    public static final int TILE_GRASS_SNOW_SIDE = 11;
    public static final int TILE_DEAD_BUSH = 12;
    public static final int TILE_CACTUS_SIDE = 13;
    public static final int TILE_CACTUS_TOP = 14;
    public static final int TILE_CACTUS_BOTTOM = 15;
    public static final int TILE_SPRUCE_WOOD = 16;
    public static final int TILE_SPRUCE_LEAVES = 17;
    public static final int TILE_ICE = 18;
    public static final int TILE_SNOW = 19;

    // Các ô mới theo thứ tự nhập PNG, giữ nguyên định danh của 20 ô trước.
    public static final int TILE_SANDSTONE = 20;
    public static final int TILE_SANDSTONE_TOP = 21;
    public static final int TILE_SANDSTONE_BOTTOM = 22;
    public static final int TILE_SPRUCE_LOG_TOP = 23;
    public static final int TILE_SHORT_GRASS = 24;
    public static final int TILE_TALL_GRASS_BOTTOM = 25;
    public static final int TILE_TALL_GRASS_TOP = 26;
    public static final int TILE_DANDELION = 27;
    public static final int TILE_POPPY = 28;
    public static final int TILE_CORNFLOWER = 29;
    public static final int TILE_OXEYE_DAISY = 30;
    public static final int TILE_SUGAR_CANE = 31;
    public static final int TILE_GRAVEL = 32;

    /** Mặt gỗ sơn có khóa đồng của rương trang trí. */
    public static final int TILE_CHEST_FRONT = 33;
    /** Mặt gỗ ghép có nẹp dọc của rương trang trí. */
    public static final int TILE_CHEST_SIDE = 34;
    /** Nắp rương với họa tiết khảm hình thoi. */
    public static final int TILE_CHEST_TOP = 35;

    /** Sáu ô chất liệu cho 6 màu len cừu trên hàng thứ 6 của Texture Atlas 8x6. */
    public static final int TILE_WHITE_WOOL = 36;
    public static final int TILE_LIGHT_GRAY_WOOL = 37;
    public static final int TILE_GRAY_WOOL = 38;
    public static final int TILE_BLACK_WOOL = 39;
    public static final int TILE_BROWN_WOOL = 40;
    public static final int TILE_PINK_WOOL = 41;

    // Hệ số nhân RGB cho thảm thực vật đồng bằng và lá vân sam, lần lượt theo mã màu RGB.
    private static final int PLAINS_TINT = 0x91BD59;
    private static final int SPRUCE_TINT = 0x619961;
    // Giá trị bán trong suốt cho ảnh nước thay thế vốn có alpha tối đa.
    static final int OPAQUE_WATER_ALPHA = 225;

    /** Quy tắc lấy mẫu và xử lý màu theo từng loại ảnh nguồn. */
    enum TileStyle {
        OPAQUE, // Giữ RGB và đặt alpha tối đa cho các mặt được vẽ đục.
        PLAINS, // Nhuộm cỏ, lá sồi và mía theo màu đồng bằng, giữ alpha gốc.
        SPRUCE, // Nhuộm lá vân sam theo màu xanh thông, giữ alpha gốc.
        RGBA,   // Giữ nguyên cả bốn kênh của ảnh nguồn.
        CUTOUT, // Giữ RGBA, dùng hình có khoảng rỗng khi thiếu PNG.
        ICE,    // Giữ RGBA, dùng alpha trung gian khi thiếu PNG.
        WATER,  // Lấy khung đầu và nhuộm xanh ảnh nước thang xám.
        LAVA    // Lấy khung đầu của ảnh dung nham và vẽ đục.
    }

    // Đối tượng Texture của libGDX đại diện cho Texture Atlas 128x80 trên VRAM.
    private final com.badlogic.gdx.graphics.Texture gdxTexture;

    /** Dựng atlas một lần khi khởi động và giải phóng bộ đệm ảnh CPU sau khi tải lên GPU. */
    public Texture() {
        Pixmap atlasPixmap = new Pixmap(ATLAS_WIDTH, ATLAS_HEIGHT, Pixmap.Format.RGBA8888);
        try {
            // Ghi đè trực tiếp để giữ alpha gốc, chỉ pha trộn ở lớp phủ cỏ.
            atlasPixmap.setBlending(Pixmap.Blending.None);
            loadExternalTexturesIntoAtlas(atlasPixmap);
            gdxTexture = new com.badlogic.gdx.graphics.Texture(atlasPixmap);
        } finally {
            atlasPixmap.dispose();
        }
        try {
            gdxTexture.setFilter(TextureFilter.Nearest, TextureFilter.Nearest);
            gdxTexture.setWrap(TextureWrap.ClampToEdge, TextureWrap.ClampToEdge);
        } catch (RuntimeException | Error failure) {
            gdxTexture.dispose();
            throw failure;
        }
    }

    /** Nạp các ảnh đóng gói vào đúng ô, ưu tiên tên PNG mới trước tên tệp cũ. */
    private void loadExternalTexturesIntoAtlas(Pixmap atlasPixmap) {
        // Các mặt cơ bản vẫn dùng tên thay thế cũ và hình dự phòng riêng nếu tải thất bại.
        boolean[] loaded = new boolean[TILE_LAVA + 1];
        loaded[TILE_GRASS_TOP] = loadTile(atlasPixmap, TILE_GRASS_TOP, TileStyle.PLAINS,
                "textures/grass_block_top.png");
        boolean grassSideLoaded = loadTile(atlasPixmap, TILE_GRASS_SIDE, TileStyle.OPAQUE,
                "textures/grass_block_side.png");
