    /** Vẽ rương theo bảng màu gỗ sơn xanh và đồng, ghi đè trực tiếp ba ô atlas. */
    private void drawDecorativeChest(Pixmap atlas) {
        for (int tile = TILE_CHEST_FRONT; tile <= TILE_CHEST_TOP; tile++) {
            for (int y = 0; y < TILE_SIZE; y++) {
                for (int x = 0; x < TILE_SIZE; x++) {
                    int distanceToEdge = Math.min(Math.min(x, TILE_SIZE - 1 - x),
                            Math.min(y, TILE_SIZE - 1 - y));
                    int centerDistance = Math.abs(2 * x - 15) + Math.abs(2 * y - 15);
                    int rgb;
                    if (distanceToEdge == 0) {
                        rgb = 0x223B37;
                    } else if (tile == TILE_CHEST_FRONT && Math.abs(2 * x - 15) + 2 * Math.abs(y - 6) <= 5) {
                        rgb = (x == 7 || y == 5) ? 0xF5D49B : 0xB36D3A;
                    } else if (tile != TILE_CHEST_TOP && y == 5) {
                        rgb = 0x223B37;
                    } else if (distanceToEdge == 1 || (tile == TILE_CHEST_TOP && centerDistance == 12)
                            || (tile != TILE_CHEST_TOP && (x == 3 || x == 12))) {
                        rgb = ((x + y) % 7 == 0) ? 0xE4AC72 : 0x90613C;
                    } else if (tile == TILE_CHEST_TOP && centerDistance < 8) {
                        rgb = 0x5E9B90;
                    } else {
                        rgb = y % 4 == 0 ? 0x375953 : 0x477971;
                    }
                    int grain = ((x * 13 + y * 7 + x * y * 3) % 11) - 5;
                    putAtlasPixel(atlas, tile, x, y, ((rgb >>> 16) & 255) + grain,
                            ((rgb >>> 8) & 255) + grain, (rgb & 255) + grain, 255);
                }
            }
        }
    }

    /** Tận dụng sheet cỏ cũ cho mặt còn thiếu và lấy ô đất của sheet làm dự phòng. */
    private void loadLegacyGrass(Pixmap atlasPixmap, boolean[] loaded) {
        Pixmap grass = loadPixmapFlexible("grass-block.png", "textures/grass-block.png", "grass_block.png");
        if (grass == null) {
            return;
        }
        try {
            if (grass.getWidth() == 32 && grass.getHeight() == 32) {
                if (!loaded[TILE_GRASS_TOP]) {
                    blitResizedToTile(atlasPixmap, grass, 16, 16, 16, 16, TILE_GRASS_TOP, TileStyle.OPAQUE);
                    loaded[TILE_GRASS_TOP] = true;
                }
                if (!loaded[TILE_GRASS_SIDE]) {
                    blitResizedToTile(atlasPixmap, grass, 0, 16, 16, 16, TILE_GRASS_SIDE, TileStyle.OPAQUE);
                    loaded[TILE_GRASS_SIDE] = true;
                }
                if (!loaded[TILE_DIRT]) {
                    blitResizedToTile(atlasPixmap, grass, 0, 0, 16, 16, TILE_DIRT, TileStyle.OPAQUE);
                    loaded[TILE_DIRT] = true;
                }
            } else if (!loaded[TILE_GRASS_TOP]) {
                blitResizedToTile(atlasPixmap, grass, 0, 0, grass.getWidth(), grass.getHeight(),
                        TILE_GRASS_TOP, TileStyle.OPAQUE);
                loaded[TILE_GRASS_TOP] = true;
            }
        } finally {
            grass.dispose();
        }
    }

    /** Nạp một ô atlas và lấy khung đầu đối với dải hoạt ảnh chất lỏng. */
    private boolean loadTile(Pixmap atlasPixmap, int tile, TileStyle style, String... names) {
        Pixmap source = loadPixmapFlexible(names);
        if (source == null) {
            return false;
        }
        try {
            int width = source.getWidth();
            int height = source.getHeight();
            if (style == TileStyle.WATER || style == TileStyle.LAVA) {
                width = Math.min(width, height);
                height = width;
            }
            blitResizedToTile(atlasPixmap, source, 0, 0, width, height, tile, style);
            return true;
        } finally {
            source.dispose();
        }
    }

    /** Dùng PNG đóng gói nếu đọc được, nếu thiếu thì tạo màu, vân và vùng alpha tại ô tương ứng. */
    private void loadTileOrFallback(Pixmap atlasPixmap, int tile, TileStyle style, int color, String name) {
        if (loadTile(atlasPixmap, tile, style, "textures/" + name + ".png")) {
            return;
        }
        for (int y = 0; y < TILE_SIZE; y++) {
            for (int x = 0; x < TILE_SIZE; x++) {
                int grain = ((x * 13 + y * 17 + x * y * 7 + tile * 5) % 21) - 10;
                int rgb = color;
                int alpha = 255;
                switch (style) {
                    case PLAINS, CUTOUT -> {
                        // Nét thân nghiêng và cụm lá tạo khoảng trống trên hai mặt phẳng chữ X.
                        int stem = 7 + (y / 4);
                        boolean plant = Math.abs(x - stem) <= 1
                                || (y >= 5 && y <= 12 && Math.abs(x - (16 - y)) <= 1)
                                || (y >= 2 && y <= 6 && Math.abs(x - 7) <= 2);
                        alpha = plant ? 255 : 0;
                    }
                    case SPRUCE -> alpha = (x * 11 + y * 13 + x * y) % 7 == 0 ? 0 : 255;
                    case ICE -> alpha = 190;
                    default -> {
                        if (tile == TILE_GRASS_SNOW_SIDE && y < 3 + (x % 3)) {
                            rgb = 0xE6F3F8;
                        }
                    }
                }
                putAtlasPixel(atlasPixmap, tile, x, y,
                        ((rgb >>> 16) & 255) + grain,
                        ((rgb >>> 8) & 255) + grain,
                        (rgb & 255) + grain, alpha);
            }
        }
    }

    /**
     * Đọc một pixel từ {@link Pixmap} nguồn và chuẩn hóa về định dạng 32-bit RGBA8888.
     * Sửa lỗi libGDX giải mã ảnh PNG thang xám 8-bit ({@code colorType = 0}) thành định dạng
     * {@code Alpha} hoặc {@code Intensity} khiến R=G=B=255 (hiển thị trắng tinh như Stone/Bedrock).
     *
     * @param src ảnh Pixmap nguồn
     * @param sx  tọa độ X trên ảnh nguồn
     * @param sy  tọa độ Y trên ảnh nguồn
     * @return màu 32-bit dạng RGBA8888 (R ở byte cao nhất, A ở byte thấp nhất)
     */
    public static int readNormalizedPixel(Pixmap src, int sx, int sy) {
        int pixel = src.getPixel(sx, sy);
        Pixmap.Format format = src.getFormat();
        if (format == Pixmap.Format.Alpha || format == Pixmap.Format.Intensity) {
            int lum = pixel & 0xFF;
            return (lum << 24) | (lum << 16) | (lum << 8) | 0xFF;
        }
        if (format == Pixmap.Format.LuminanceAlpha) {
            int lum = (pixel >>> 24) & 0xFF;
            int alpha = pixel & 0xFF;
            return (lum << 24) | (lum << 16) | (lum << 8) | alpha;
        }
        return pixel;
    }

    /**
     * Đọc một pixel tại {@code (sx, sy)} trên {@link Pixmap} nguồn, áp dụng quy tắc nhuộm màu
     * và kênh alpha theo {@link TileStyle}, rồi trả về màu 32-bit dạng {@code RGBA8888}.
     *
     * @param src   ảnh Pixmap nguồn
     * @param sx    tọa độ X trên ảnh nguồn
     * @param sy    tọa độ Y trên ảnh nguồn
     * @param style quy tắc xử lý màu và alpha của loại bề mặt
     * @return màu 32-bit đã chuẩn hóa và giới hạn kênh vào [0, 255]
     */
    static int sampleStyledRgba(Pixmap src, int sx, int sy, TileStyle style) {
        int pixel = readNormalizedPixel(src, sx, sy);
        int r = (pixel >>> 24) & 0xFF;
        int g = (pixel >>> 16) & 0xFF;
        int b = (pixel >>> 8) & 0xFF;
        int a = pixel & 0xFF;

        if (style == TileStyle.PLAINS || style == TileStyle.SPRUCE) {
            // Nhuộm riêng các kênh RGB, giữ nguyên khe alpha trên lá và cây.
            int tint = style == TileStyle.PLAINS ? PLAINS_TINT : SPRUCE_TINT;
            r = r * ((tint >>> 16) & 255) / 255;
            g = g * ((tint >>> 8) & 255) / 255;
            b = b * (tint & 255) / 255;
        } else if (style == TileStyle.WATER) {
            if (Math.abs(r - g) < 10 && Math.abs(g - b) < 10) {
                r = (int) (r * 0.22f + 18);
                g = (int) (g * 0.58f + 45);
                b = (int) (b * 0.98f + 70);
            }
            if (a == 255) {
                a = OPAQUE_WATER_ALPHA;
            }
        } else if (style == TileStyle.OPAQUE || style == TileStyle.LAVA) {
            a = 255;
        }

        return packRgba(r, g, b, a);
    }

    /** Đóng gói 4 kênh R, G, B, A (đã kẹp vào [0, 255]) thành số nguyên 32-bit RGBA8888. */
    public static int packRgba(int r, int g, int b, int a) {
        return (clamp(r) << 24) | (clamp(g) << 16) | (clamp(b) << 8) | clamp(a);
    }

    /** Lấy mẫu pixel gần nhất và xử lý màu, alpha trước khi ghi vào ô atlas. */
    private void blitResizedToTile(
            Pixmap atlasPixmap,
            Pixmap src,
            int srcX,
            int srcY,
            int srcW,
            int srcH,
            int tileIndex,
            TileStyle style
    ) {
        for (int ty = 0; ty < TILE_SIZE; ty++) {
            for (int tx = 0; tx < TILE_SIZE; tx++) {
                int sx = srcX + Math.min(srcW - 1, (int) (((tx + 0.5f) / TILE_SIZE) * srcW));
                int sy = srcY + Math.min(srcH - 1, (int) (((ty + 0.5f) / TILE_SIZE) * srcH));

                int rgba = sampleStyledRgba(src, sx, sy, style);
                putAtlasPixelRgba(atlasPixmap, tileIndex, tx, ty, rgba);
            }
        }
    }

    /** Chuyển tọa độ trong ô sang tọa độ pixel toàn atlas. */
    private void putAtlasPixel(Pixmap atlasPixmap, int tileIndex, int tx, int ty, int r, int g, int b, int a) {
        putAtlasPixelRgba(atlasPixmap, tileIndex, tx, ty, packRgba(r, g, b, a));
    }

    /** Ghi trực tiếp một pixel RGBA8888 đã đóng gói vào đúng tọa độ của ô trên atlas. */
    private void putAtlasPixelRgba(Pixmap atlasPixmap, int tileIndex, int tx, int ty, int rgba) {
        int tileCol = tileIndex % ATLAS_COLS;
        int tileRow = tileIndex / ATLAS_COLS;

        int atlasX = tileCol * TILE_SIZE + tx;
        int atlasY = tileRow * TILE_SIZE + ty;

        atlasPixmap.drawPixel(atlasX, atlasY, rgba);
    }

    /** Tìm và giải mã ảnh từ classpath, thư mục cục bộ hoặc kết quả quét sâu. */
    public static Pixmap loadPixmapFlexible(String... candidateNames) {
        byte[] rawBytes = null;
        String matchedPath = null;

        String[] baseDirs = {
                "",
                "src/main/resources/",
                "src/main/resources/textures/",
                "textures/",
                "texture/"
        };

        for (String candidate : candidateNames) {
            String resourcePath = candidate.startsWith("/") ? candidate : "/" + candidate;
            try (InputStream is = Texture.class.getResourceAsStream(resourcePath)) {
                if (is != null) {
                    rawBytes = is.readAllBytes();
                    matchedPath = "classpath:" + resourcePath;
                    break;
                }
            } catch (IOException ignored) {
            }

            for (String dir : baseDirs) {
                File f = new File(dir + candidate);
                if (f.exists() && f.isFile()) {
                    try {
                        rawBytes = Files.readAllBytes(f.toPath());
                        matchedPath = f.getPath();
                        break;
                    } catch (IOException ignored) {
                    }
                }
            }
            if (rawBytes != null) {
                break;
            }
        }

        if (rawBytes == null && candidateNames.length > 0) {
            String targetFileName = new File(candidateNames[0]).getName().toLowerCase();
            Path found = findFileByName(Path.of("."), targetFileName, 5);
            if (found != null) {
                try {
                    rawBytes = Files.readAllBytes(found);
                    matchedPath = found.toString();
                } catch (IOException ignored) {
                }
            }
        }

        if (rawBytes == null) {
            return null;
        }

        try {
            Pixmap pixmap = new Pixmap(rawBytes, 0, rawBytes.length);
            System.out.println("[Texture] Đã nạp thành công texture: " + matchedPath
                    + " (" + pixmap.getWidth() + "x" + pixmap.getHeight() + ")");
            return pixmap;
        } catch (Exception e) {
            System.err.println("[Texture] Không thể giải mã file ảnh '" + matchedPath + "': " + e.getMessage());
            return null;
        }
    }

    /** Quét có giới hạn theo tên ảnh và bỏ qua các thư mục quản lý Git, Gradle. */
    private static Path findFileByName(Path rootDir, String fileNameLower, int maxDepth) {
        if (!Files.exists(rootDir)) {
            return null;
        }
        try (Stream<Path> stream = Files.walk(rootDir, maxDepth)) {
            return stream
                    .filter(Files::isRegularFile)
                    .filter(p -> {
                        String pathStr = p.toString();
                        return !pathStr.contains(".gradle") && !pathStr.contains(".git");
                    })
                    .filter(p -> p.getFileName().toString().toLowerCase().equals(fileNameLower))
                    .findFirst()
                    .orElse(null);
        } catch (IOException e) {
            return null;
        }
    }

    /** Dựng các ô cơ bản còn thiếu bằng chuỗi ngẫu nhiên tất định của atlas ban đầu. */
    private void populateProceduralFallbacks(Pixmap atlasPixmap, boolean[] loaded) {
        Random rng = new Random(20261114L);

        for (int y = 0; y < TILE_SIZE; y++) {
            for (int x = 0; x < TILE_SIZE; x++) {
                int border = (x == 0 || y == 0 || x == TILE_SIZE - 1 || y == TILE_SIZE - 1) ? -8 : 0;

                // 0. DIRT
                int nDirt = rng.nextInt(31) - 15;
                putFallbackPixel(atlasPixmap, loaded, TILE_DIRT, x, y,
                        134 + nDirt + border, 96 + nDirt + border, 67 + nDirt + border, 255);

                // 1. GRASS_TOP
                int nGrass = rng.nextInt(27) - 13;
                putFallbackPixel(atlasPixmap, loaded, TILE_GRASS_TOP, x, y,
                        88 + nGrass + border, 168 + nGrass + border, 52 + nGrass + border, 255);

                // 2. GRASS_SIDE
                int grassEdgeHeight = 3 + ((x * 37 + 13) % 3);
                if (y < grassEdgeHeight) {
                    putFallbackPixel(atlasPixmap, loaded, TILE_GRASS_SIDE, x, y,
                            88 + nGrass + border, 168 + nGrass + border, 52 + nGrass + border, 255);
                } else {
                    putFallbackPixel(atlasPixmap, loaded, TILE_GRASS_SIDE, x, y,
                            134 + nDirt + border, 96 + nDirt + border, 67 + nDirt + border, 255);
                }

                // 3. STONE
                int nStone = rng.nextInt(25) - 12 + ((x + y * 3) % 5 == 0 ? -10 : 0);
                putFallbackPixel(atlasPixmap, loaded, TILE_STONE, x, y,
                        126 + nStone + border, 126 + nStone + border, 126 + nStone + border, 255);

                // 4. BEDROCK
                int nBedrock = ((x * 19 + y * 31 + rng.nextInt(20)) % 3 == 0) ? -35 : 22;
                putFallbackPixel(atlasPixmap, loaded, TILE_BEDROCK, x, y,
                        78 + nBedrock, 78 + nBedrock, 78 + nBedrock, 255);

                // 5. OAK_LOG_SIDE
                int barkStripe = (x % 4 == 0) ? -14 : ((x % 2 == 0) ? 8 : 0);
                int nLog = rng.nextInt(17) - 8 + barkStripe;
                putFallbackPixel(atlasPixmap, loaded, TILE_OAK_LOG_SIDE, x, y,
                        105 + nLog, 82 + nLog, 49 + nLog, 255);

                // 6. OAK_LOG_TOP
                int distFromEdge = Math.min(Math.min(x, TILE_SIZE - 1 - x), Math.min(y, TILE_SIZE - 1 - y));
                if (distFromEdge <= 1) {
                    putFallbackPixel(atlasPixmap, loaded, TILE_OAK_LOG_TOP, x, y,
                            102 + nLog, 80 + nLog, 48 + nLog, 255);
                } else {
                    int ring = (distFromEdge % 2 == 0) ? -10 : 6;
                    putFallbackPixel(atlasPixmap, loaded, TILE_OAK_LOG_TOP, x, y,
                            168 + ring, 137 + ring, 86 + ring, 255);
                }

                // 7. OAK_LEAVES
                int leafPattern = ((x * 7 + y * 13 + rng.nextInt(9)) % 4 == 0) ? -22 : 12;
                int leafAlpha = (x * 11 + y * 13 + x * y) % 7 == 0 ? 0 : 255;
                putFallbackPixel(atlasPixmap, loaded, TILE_OAK_LEAVES, x, y,
                        46 + leafPattern, 118 + leafPattern, 34 + leafPattern, leafAlpha);

                // 8. WATER
                int wave = ((x + y * 2) % 5 == 0) ? 16 : (rng.nextInt(11) - 5);
                putFallbackPixel(atlasPixmap, loaded, TILE_WATER, x, y,
                        42 + wave, 112 + wave, 225 + wave, OPAQUE_WATER_ALPHA);

                // 9. LAVA
                int lavaGlow = ((x * 3 + y * 5) % 7 == 0) ? 35 : (rng.nextInt(31) - 15);
                putFallbackPixel(atlasPixmap, loaded, TILE_LAVA, x, y,
                        230 + lavaGlow, 108 + lavaGlow, 22 + lavaGlow / 2, 255);
            }
        }
    }

    /** Ghi pixel dự phòng nếu ô đó chưa được nạp, giữ chuỗi vân của các ô khác ổn định. */
    private void putFallbackPixel(
            Pixmap atlasPixmap, boolean[] loaded, int tile, int x, int y, int r, int g, int b, int alpha
    ) {
        if (!loaded[tile]) {
            putAtlasPixel(atlasPixmap, tile, x, y, r, g, b, alpha);
        }
    }

    /** Giới hạn giá trị kênh màu vào phạm vi một byte. */
    private static int clamp(int val) {
        return Math.max(0, Math.min(255, val));
    }

    /**
     * Cập nhật trực tiếp một ô {@code 16x16} trên Texture Atlas ở VRAM GPU bằng dữ liệu pixel
     * {@code RGBA8888} từ {@link Pixmap} mà không cần cấp phát hay dựng lại toàn bộ atlas.
     * Bỏ qua an toàn khi chưa có ngữ cảnh OpenGL ({@code Gdx.gl == null}).
     *
     * @param tileIndex  chỉ số ô trong lưới atlas {@code 8x6} ({@code 0..47})
     * @param tilePixmap ảnh nguồn {@code 16x16} định dạng {@code RGBA8888}
     */
    public void updateTile(int tileIndex, Pixmap tilePixmap) {
        if (Gdx.gl == null || gdxTexture == null || tilePixmap == null) {
            return;
        }
        if (tileIndex < 0 || tileIndex >= ATLAS_COLS * ATLAS_ROWS) {
            throw new IllegalArgumentException("Chỉ số ô atlas không hợp lệ: " + tileIndex);
        }
        if (tilePixmap.getWidth() != TILE_SIZE || tilePixmap.getHeight() != TILE_SIZE) {
            throw new IllegalArgumentException("Kích thước tilePixmap phải là " + TILE_SIZE + "x" + TILE_SIZE
                    + ", nhận được: " + tilePixmap.getWidth() + "x" + tilePixmap.getHeight());
        }
        int col = tileIndex % ATLAS_COLS;
        int row = tileIndex / ATLAS_COLS;
        bind();
        ByteBuffer pixels = tilePixmap.getPixels();
        pixels.rewind();
        Gdx.gl.glTexSubImage2D(
                GL20.GL_TEXTURE_2D,
                0,
                col * TILE_SIZE,
                row * TILE_SIZE,
                TILE_SIZE,
                TILE_SIZE,
                GL20.GL_RGBA,
                GL20.GL_UNSIGNED_BYTE,
                pixels
        );
    }

    /**
     * Kích hoạt Texture Atlas vào Texture Unit 0 trên GPU.
     */
    public void bind() {
        gdxTexture.bind(0);
    }

    /**
     * Hủy liên kết Texture trên Texture Unit 0.
     */
    public void unbind() {
        Gdx.gl.glBindTexture(GL20.GL_TEXTURE_2D, 0);
    }

    /** Trả về atlas dùng chung để các bộ kết xuất có thể lấy texture libGDX. */
    public com.badlogic.gdx.graphics.Texture getGdxTexture() {
        return gdxTexture;
    }

    /** Giải phóng atlas trên GPU khi ứng dụng đóng. */
    @Override
    public void dispose() {
        if (gdxTexture != null) {
            gdxTexture.dispose();
        }
    }
}

package com.voxelgame.client.render;

import com.voxelgame.world.level.biome.BiomeType;
import com.voxelgame.world.level.weather.WeatherManager;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Texture;
import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Vector3;
import com.badlogic.gdx.utils.Disposable;
import static com.badlogic.gdx.graphics.Texture.TextureWrap.ClampToEdge;
import static com.badlogic.gdx.graphics.Texture.TextureWrap.Repeat;

/** Kết xuất hai lô giáng thủy theo cột, dùng chung bộ đệm qua mọi khung hình. */
public final class WeatherRenderer implements Disposable {
    /** Bán kính ngang và số dải tối đa của một lượt vẽ. */
    private static final int RADIUS = 14;
    private static final int MAX_COLUMNS = (RADIUS * 2 + 1) * (RADIUS * 2 + 1);
    /** Giới hạn số dải chồng trên mỗi pixel, nhất là khi nhìn ngang qua cả vùng mưa. */
    private static final float RAIN_DENSITY = 0.35f;
    private static final float SNOW_DENSITY = 0.29f;
    private final EnvironmentMesh rain = new EnvironmentMesh(MAX_COLUMNS);
    private final EnvironmentMesh snow = new EnvironmentMesh(MAX_COLUMNS);
    private Texture rainTexture;
    private Texture snowTexture;

    /** Nạp nguyên ảnh mưa và tuyết đã có sẵn trong dự án. */
    public WeatherRenderer() {
        try {
            rainTexture = EnvironmentMesh.loadTexture("rain.png", ClampToEdge, Repeat);
            snowTexture = EnvironmentMesh.loadTexture("snow.png", Repeat, Repeat);
        } catch (RuntimeException error) {
            dispose();
            throw error;
        }
    }

    /** Dựng dải tại các cột nhìn quanh camera, cắt chân dải theo bề mặt cao nhất. */
    public void render(ShaderProgram shader, World world, Vector3 eye, WeatherManager weather) {
        float strength = weather.strength();
        if (strength <= 0f) {
            return;
        }
        rain.clear();
        snow.clear();
        int centerX = MathUtils.floor(eye.x);
        int centerZ = MathUtils.floor(eye.z);
        double seconds = weather.animationSeconds();
        float rainScroll = (float) ((seconds * 2.25) % 1.0);
        float snowScroll = (float) ((seconds * 0.26) % 1.0);
        float snowSway = (float) ((seconds * 1.55) % (Math.PI * 2));
        float top = eye.y + 18f;
        for (int dz = -RADIUS; dz <= RADIUS; dz++) {
            for (int dx = -RADIUS; dx <= RADIUS; dx++) {
                if (dx * dx + dz * dz > RADIUS * RADIUS) {
                    continue;
                }
                int x = centerX + dx;
                int z = centerZ + dz;
                if (!world.isInsideWorld(x, 0, z)) {
                    continue;
                }
                BiomeType biome = world.getBiome(x, z);
                if (biome.isDry()) {
                    continue;
                }
                int hash = x * 374761393 + z * 668265263;
                hash = (hash ^ (hash >>> 13)) * 1274126177;
                boolean flakes = biome.hasSnow();
                float density = flakes ? SNOW_DENSITY : RAIN_DENSITY;
                // Các cột xuất hiện theo thứ tự cố định khi cường độ tăng.
                if (((hash >>> 12) & 255) / 256f >= density * strength) {
                    continue;
                }
                float columnX = x + 0.5f;
                float columnZ = z + 0.5f;
                float deltaX = columnX - eye.x;
                float deltaZ = columnZ - eye.z;
                float distance2 = deltaX * deltaX + deltaZ * deltaZ;
                // Bỏ dải quá sát mắt, nơi một tứ giác có thể phủ gần như cả màn hình.
                if (distance2 < 1f) {
                    continue;
                }
                float bottom = Math.max(eye.y - 16f, world.getPrecipitationSurface(x, z));
                if (bottom >= top) {
                    continue;
                }
                float phase = (hash & 255) / 256f;
                float uOffset = flakes ? MathUtils.sin(snowSway + phase * MathUtils.PI2) * 0.17f : 0f;
                float vOffset = phase - (flakes ? snowScroll : rainScroll);
                float distance = (float) Math.sqrt(distance2);
                // Mờ dần ở sát mắt và rìa vùng vẽ để tránh dải bật/tắt khi di chuyển.
                float opacity = Math.min(Math.min(distance - 1f, 1f), (RADIUS + 0.5f - distance) * 0.25f);
                if (opacity > 0f) {
                    addColumn(flakes ? snow : rain, columnX, columnZ,
                            bottom, top, deltaX, deltaZ, distance, uOffset, vOffset, opacity);
                }
            }
        }
        rain.upload();
        snow.upload();

        shader.setUniform1i("uEnvironmentMode", 4);
        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        Gdx.gl.glDisable(GL20.GL_CULL_FACE);
        Gdx.gl.glDepthMask(false);
        // Kiểm tra chiều sâu vẫn bật theo hợp đồng khung hình của thế giới.
        try {
            rainTexture.bind(0);
            shader.setUniformVec4("uTintColor", 0.88f, 0.93f, 1f, 0.80f * strength);
            rain.draw(shader);
            snowTexture.bind(0);
            shader.setUniformVec4("uTintColor", 1f, 1f, 1f, 0.90f * strength);
            snow.draw(shader);
        } finally {
            Gdx.gl.glDepthMask(true);
            Gdx.gl.glEnable(GL20.GL_CULL_FACE);
            Gdx.gl.glDisable(GL20.GL_BLEND);
            shader.setUniform1i("uEnvironmentMode", 0);
            shader.enable3DWorldMode();
        }
    }

    /** Quay dải về phía mắt; giữ toàn bộ chiều ngang bên trong cột để mái che không bị lọt hạt. */
    private static void addColumn(EnvironmentMesh mesh, float x, float z, float bottom, float top,
                                  float dx, float dz, float distance,
                                  float uOffset, float vOffset, float opacity) {
        float scale = 0.49f / distance;
        float sideX = dz * scale;
        float sideZ = -dx * scale;
        // Dùng tọa độ Y tuyệt đối để UV không đổi khi điểm cắt thay đổi.
        mesh.quad(x - sideX, top, z - sideZ, x - sideX, bottom, z - sideZ,
                x + sideX, bottom, z + sideZ, x + sideX, top, z + sideZ,
                uOffset, vOffset - top * 0.25f, 1f + uOffset, vOffset - bottom * 0.25f, opacity);
    }

    /** Hủy hai texture và hai bộ đệm lô. */
    @Override
    public void dispose() {
        rain.dispose();
        snow.dispose();
        if (rainTexture != null) {
            rainTexture.dispose();
        }
        if (snowTexture != null) {
            snowTexture.dispose();
        }
    }
}

