import com.voxelgame.client.render.ShaderProgram;
import com.voxelgame.client.render.Texture;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.ItemEntity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.level.block.Block;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Mesh;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.Texture.TextureFilter;
import com.badlogic.gdx.graphics.Texture.TextureWrap;
import com.badlogic.gdx.graphics.VertexAttribute;
import com.badlogic.gdx.graphics.VertexAttributes;
import com.badlogic.gdx.math.Frustum;
import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Matrix4;
import com.badlogic.gdx.math.Vector3;
import com.badlogic.gdx.utils.Disposable;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Lượt vẽ mô hình mob dùng chung mesh, ma trận khớp và cache vật liệu. */
public final class MobRenderer implements Disposable {
    /** Quy đổi đơn vị pixel của mô hình sang block thế giới. */
    private static final float PIXEL_TO_BLOCK = 1f / 16f;
    /** Cỡ bố cục gốc khi ảnh 16 × 16 dự phòng thay cho ảnh có UV chi tiết. */
    private static final int NOMINAL_WIDTH = 128;
    private static final int NOMINAL_HEIGHT = 128;
    /** Định dạng cần dùng chung với shader và mesh chunk. */
    private static final VertexAttributes FORMAT = new VertexAttributes(
            new VertexAttribute(VertexAttributes.Usage.Position, 3, "aPos"),
            new VertexAttribute(VertexAttributes.Usage.TextureCoordinates, 2, "aTexCoord"),
            new VertexAttribute(VertexAttributes.Usage.Generic, 1, "aShade"));
    /** Thời lượng mỗi khung hoạt ảnh lửa (20 FPS = 0.05s) và thông số hình học chữ X ôm hitbox. */
    private static final double FIRE_FRAME_SECONDS = 0.05;
    private static final int FIRE_STRIDE = 6;
    private static final int FIRE_VERTEX_COUNT = 12;
    private static final float FIRE_SELF_SHADE = -1.0f;
    private static final float FIRE_WIDTH_SCALE = 1.15f;
    private static final float FIRE_HEIGHT_SCALE = 1.05f;
    private static final float FIRE_LAYER_TIME_OFFSET = 0.25f;

    /** Hai bộ phận chỉ cần chung mesh khi hình học, kích thước UV và kiểu sáng trùng nhau. */
    private record MeshKey(ModelPart.Geometry geometry, boolean eyes, int width, int height) {}
    /** Tổ hợp mesh tĩnh và texture đã nạp dành cho một lượt vẽ. */
    private record Material(Mesh mesh, MobTextureManager.Skin skin) {}
    /** Một nhánh cây có vật liệu mặc định và các lớp hoa văn đã dựng từ đầu. */
    private record PreparedPart(ModelPart part, Material material, Material[] markings, PreparedPart[] children) {}
    /** Mẫu cùng các nhánh đã chuẩn bị trong ngữ cảnh OpenGL hiện tại. */
    private record PreparedModel(MobModel model, PreparedPart[] roots) {}

    private final Texture blockAtlas;
    private final Map<MeshKey, Mesh> meshes = new HashMap<>();
    private final PreparedModel[] models;
    private final Matrix4[] transforms;
    private final Matrix4 rootTransform = new Matrix4();
    /** Ma trận của vật được giữ ở miệng cáo hoặc tay Enderman, dùng lại giữa các lần vẽ. */
    private final Matrix4 heldBlockTransform = new Matrix4();
    /** Ma trận và bộ đệm dùng lại khi vẽ ngọn lửa chữ X ôm sát hitbox mob (zero-GC). */
    private final Matrix4 fireTransform = new Matrix4();
    private final Vector3 savedWorldLight = new Vector3();
    private final float[] fireVertices = new float[FIRE_VERTEX_COUNT * FIRE_STRIDE];
    private final float[] fireUv0 = new float[4];
    private final float[] fireUv1 = new float[4];
    private final Mesh fireMesh;
    private final com.badlogic.gdx.graphics.Texture fireTexture0;
    private final com.badlogic.gdx.graphics.Texture fireTexture1;
    private final int fireFrameCount0;
    private final int fireFrameCount1;
    private int lastFireFrame0 = -1;
    private int lastFireFrame1 = -1;
    private double fireAnimationSeconds;
    private final Vector3 center = new Vector3();
    private MobTextureManager.Skin boundSkin;
    private int tintMode;
    private int appliedTint;
    private int woolColor;
    private boolean hideOverlay;
    private Block heldBlock;
    private ModelPart heldBlockPart;
    private MobAppearance currentAppearance;
    private boolean blendEnabled;
    private boolean cullDisabled;
    private int deepestPart;
    private boolean disposed;

    /** Nạp vật liệu và dựng toàn bộ mesh một lần trên luồng có ngữ cảnh OpenGL. */
    public MobRenderer(MobTextureManager textures, Texture blockAtlas) {
        this.blockAtlas = blockAtlas;
        MobAppearance[] appearances = MobAppearance.values();
        models = new PreparedModel[appearances.length];
        MobAppearance.HorseMarkings[] markingTypes = MobAppearance.HorseMarkings.values();
        MobTextureManager.Skin[] markingSkins = new MobTextureManager.Skin[markingTypes.length];
        try {
            MobTextureManager.Skin equipment = textures.load(MobTextureManager.HELD_EQUIPMENT);
            MobModel horse = MobAppearance.HORSE_BROWN.model();
            for (MobAppearance.HorseMarkings marking : markingTypes) {
                markingSkins[marking.ordinal()] = loadLayer(textures, marking.texture(), horse, ModelPart.Layer.OVERLAY);
            }
            for (MobAppearance appearance : appearances) {
                MobModel model = appearance.model();
                MobTextureManager.Skin base = loadLayer(textures, appearance.texture(), model, ModelPart.Layer.BASE);
                MobTextureManager.Skin overlay = loadLayer(textures, appearance.overlay(), model, ModelPart.Layer.OVERLAY);
                MobTextureManager.Skin eyes = loadLayer(textures, appearance.eyes(), model, ModelPart.Layer.EYES);
                MobTextureManager.Skin[] optionalMarkings = appearance.name().startsWith("HORSE_")
                        ? markingSkins : null;
                PreparedPart[] roots = prepareParts(model.roots(), base, overlay, eyes, equipment, optionalMarkings, 1);
                models[appearance.ordinal()] = new PreparedModel(model, roots);
            }
            transforms = new Matrix4[deepestPart];
            for (int i = 0; i < transforms.length; i++) {
                transforms[i] = new Matrix4();
            }
            Pixmap firePixmap0 = loadNormalizedFirePixmap("textures/fire_0.png", "fire_0.png");
            try {
                fireFrameCount0 = Math.max(1, firePixmap0.getHeight() / Math.max(1, firePixmap0.getWidth()));
                fireTexture0 = uploadFireTexture(firePixmap0);
            } finally {
                firePixmap0.dispose();
            }
            Pixmap firePixmap1 = loadNormalizedFirePixmap("textures/fire_1.png", "fire_1.png");
            try {
                fireFrameCount1 = Math.max(1, firePixmap1.getHeight() / Math.max(1, firePixmap1.getWidth()));
                fireTexture1 = uploadFireTexture(firePixmap1);
            } finally {
                firePixmap1.dispose();
            }
            if (Gdx.gl != null) {
                fireMesh = new Mesh(Mesh.VertexDataType.VertexBufferObjectWithVAO, false, FIRE_VERTEX_COUNT, 0, FORMAT);
                updateFireMeshVertices(0.0);
            } else {
                fireMesh = null;
            }
        } catch (RuntimeException | Error error) {
            dispose();
            throw error;
        }
    }

    /**
     * Tính tọa độ UV {@code [u0, v0, u1, v1]} của khung lửa ở thời điểm {@code timeSeconds},
     * cuộn đều qua {@code 0..frameCount-1} mỗi {@code 0.05s} (20 FPS), ghi trực tiếp vào {@code outUv} (zero-GC).
     *
     * @param timeSeconds thời gian hoạt ảnh tính bằng giây
     * @param frameCount  tổng số khung hình vuông theo chiều dọc của dải ảnh lửa
     * @param outUv       mảng độ dài >= 4 nhận {@code [u0, v0, u1, v1]} trong khoảng {@code [0, 1]}
     */
    public static void fireFrameUV(double timeSeconds, int frameCount, float[] outUv) {
        if (outUv == null || outUv.length < 4) {
            throw new IllegalArgumentException("Mảng outUv phải có ít nhất 4 phần tử");
        }
        int safeCount = Math.max(1, frameCount);
        double safeTime = Math.max(0.0, timeSeconds);
        long step = (long) Math.floor(safeTime / FIRE_FRAME_SECONDS + 1e-7);
        int frame = (int) (step % safeCount);
        outUv[0] = 0.0f;
        outUv[1] = (float) frame / safeCount;
        outUv[2] = 1.0f;
        outUv[3] = (float) (frame + 1) / safeCount;
    }

    /** Cập nhật đồng hồ hoạt ảnh lửa dùng chung với lượt vẽ thế giới (không bị tăng tốc bởi F8). */
    public void setFireAnimationSeconds(double seconds) {
        fireAnimationSeconds = Math.max(0.0, seconds);
    }

    /** Trả texture GPU dải lửa {@code fire_0.png} để lớp phủ góc nhìn 1 tái sử dụng. */
    public com.badlogic.gdx.graphics.Texture getFireTexture0() {
        return fireTexture0;
    }

    /** Trả texture GPU dải lửa {@code fire_1.png} để lớp phủ góc nhìn 1 tái sử dụng. */
    public com.badlogic.gdx.graphics.Texture getFireTexture1() {
        return fireTexture1;
    }

    /** Trả số khung của dải {@code fire_0.png}. */
    public int getFireFrameCount0() {
        return fireFrameCount0;
    }

    /** Trả số khung của dải {@code fire_1.png}. */
    public int getFireFrameCount1() {
        return fireFrameCount1;
    }

    /** Đọc ảnh dải lửa và chuẩn hóa toàn bộ pixel về {@code RGBA8888} qua {@link Texture#readNormalizedPixel}. */
    private static Pixmap loadNormalizedFirePixmap(String... names) {
        Pixmap raw = Texture.loadPixmapFlexible(names);
        if (raw == null) {
            Pixmap fallback = new Pixmap(Texture.TILE_SIZE, Texture.TILE_SIZE * 16, Pixmap.Format.RGBA8888);
            fallback.setBlending(Pixmap.Blending.None);
            for (int y = 0; y < fallback.getHeight(); y++) {
                for (int x = 0; x < fallback.getWidth(); x++) {
                    int rgba = (y % Texture.TILE_SIZE > 5)
                            ? Texture.packRgba(255, 145, 24, 220)
                            : Texture.packRgba(255, 220, 90, 0);
                    fallback.drawPixel(x, y, rgba);
                }
            }
            return fallback;
        }
        try {
            int width = Math.max(1, raw.getWidth());
            int height = Math.max(1, raw.getHeight());
            Pixmap normalized = new Pixmap(width, height, Pixmap.Format.RGBA8888);
            normalized.setBlending(Pixmap.Blending.None);
            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    normalized.drawPixel(x, y, Texture.readNormalizedPixel(raw, x, y));
                }
            }
            return normalized;
        } finally {
            raw.dispose();
        }
    }

    /** Đưa {@link Pixmap} dải lửa đã chuẩn hóa lên GPU khi có ngữ cảnh OpenGL ({@code Gdx.gl != null}). */
    private static com.badlogic.gdx.graphics.Texture uploadFireTexture(Pixmap normalizedPixmap) {
        if (Gdx.gl == null) {
            return null;
        }
        com.badlogic.gdx.graphics.Texture texture = new com.badlogic.gdx.graphics.Texture(normalizedPixmap, false);
        try {
            texture.setFilter(TextureFilter.Nearest, TextureFilter.Nearest);
            texture.setWrap(TextureWrap.ClampToEdge, TextureWrap.ClampToEdge);
            return texture;
        } catch (RuntimeException | Error error) {
            texture.dispose();
            throw error;
        }
    }

    /** Giữ hình nền dự phòng và ẩn lớp phụ lỗi để lớp màu đục không che nhân vật. */
    private static MobTextureManager.Skin loadLayer(MobTextureManager textures, MobTextureKey key,
                                                    MobModel model, ModelPart.Layer layer) {
        MobTextureManager.Skin skin = textures.load(key);
        if (skin == null) {
            return null;
        }
        if (!skin.fallback() && !model.fitsLayer(layer, skin.width(), skin.height())) {
            skin = textures.layoutFallback(key);
        }
        return skin.fallback() && layer != ModelPart.Layer.BASE ? null : skin;
    }

    /** Chuẩn bị cùng cấu trúc khớp cho một biến thể; tận dụng mesh đã dựng của biến thể trước. */
    private PreparedPart[] prepareParts(ModelPart[] parts, MobTextureManager.Skin base,
                                       MobTextureManager.Skin overlay, MobTextureManager.Skin eyes,
                                       MobTextureManager.Skin equipment, MobTextureManager.Skin[] markingSkins, int depth) {
        PreparedPart[] prepared = new PreparedPart[parts.length];
        if (parts.length > 0) {
            deepestPart = Math.max(deepestPart, depth);
        }
        for (int i = 0; i < parts.length; i++) {
            ModelPart part = parts[i];
            Material material = switch (part.layer()) {
                case BASE -> prepareMaterial(part, base);
                case OVERLAY -> prepareMaterial(part, overlay);
                case EYES -> prepareMaterial(part, eyes);
                case EQUIPMENT -> prepareMaterial(part, equipment);
            };
            Material[] markings = null;
            if (part.layer() == ModelPart.Layer.OVERLAY && markingSkins != null) {
                markings = new Material[markingSkins.length];
                for (int mark = 0; mark < markings.length; mark++) {
                    markings[mark] = prepareMaterial(part, markingSkins[mark]);
                }
            }
            PreparedPart[] children = prepareParts(part.children(), base, overlay, eyes, equipment, markingSkins, depth + 1);
            prepared[i] = new PreparedPart(part, material, markings, children);
        }
        return prepared;
    }

    /** Tạo hoặc dùng lại mesh của một bộ phận với kích thước UV của ảnh tương ứng. */
    private Material prepareMaterial(ModelPart part, MobTextureManager.Skin skin) {
        if (skin == null) {
            return null;
        }
        int width = skin.fallback() ? NOMINAL_WIDTH : skin.width();
        int height = skin.fallback() ? NOMINAL_HEIGHT : skin.height();
        MeshKey key = new MeshKey(part.geometry(), part.layer() == ModelPart.Layer.EYES, width, height);
        Mesh mesh = meshes.get(key);
        if (mesh == null) {
            float[] vertices = part.buildVertices(width, height);
            int vertexCount = vertices.length / ModelPart.STRIDE;
            mesh = new Mesh(Mesh.VertexDataType.VertexBufferObjectWithVAO, true, vertexCount, 0, FORMAT);
            try {
                mesh.setVertices(vertices);
                meshes.put(key, mesh);
            } catch (RuntimeException | Error error) {
                mesh.dispose();
                throw error;
            }
        }
        return new Material(mesh, skin);
    }

    /** Vẽ các thực thể còn trong khung nhìn, giữ ánh sáng, sương và trạng thái OpenGL sạch sẽ. */
    public void render(List<Entity> entities, ShaderProgram shader, Frustum frustum, Vector3 eye, float drawDistance) {
        if (disposed) {
            return;
        }
        boundSkin = null;
        tintMode = -1;
        appliedTint = -1;
        blendEnabled = false;
        cullDisabled = false;
        try {
            for (int i = 0; i < entities.size(); i++) {
                Entity entity = entities.get(i);
                if (!(entity instanceof MobVisual visual)) {
                    continue;
                }
                MobVisualState state = visual.mobVisualState();
                currentAppearance = state.appearance();
                PreparedModel model = models[currentAppearance.ordinal()];
                float fuse = state.fuseProgress();
                float scale = state.scale() * currentAppearance.modelScale()
                        * PIXEL_TO_BLOCK * (1f + 0.25f * fuse * fuse);
                entity.copyCenterPosition(center);
                center.y -= entity.getHeight() * 0.5f;
                float radius = model.model.renderRadius() * scale * Math.max(1f, currentAppearance.heightScale());
                if (isInView(radius, frustum, eye, drawDistance)) {
                    drawMob(shader, entity, state, model, scale, fuse);
                }
            }
        } finally {
            setBlend(false);
            setDoubleSided(false);
            if (tintMode != -1) {
                shader.setUniformVec4("uTintColor", 1f, 1f, 1f, 1f);
                shader.setUniform1f("uMobWhiteFlash", 0f);
            }
            if (boundSkin != null) {
                blockAtlas.bind();
                boundSkin = null;
            }
        }
    }

    /** Bật hoặc tắt hòa trộn alpha cho lớp phủ đốm ngựa bán trong suốt. */
    private void setBlend(boolean enable) {
        if (blendEnabled == enable) {
            return;
        }
        blendEnabled = enable;
        if (enable) {
            Gdx.gl.glEnable(GL20.GL_BLEND);
            Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        } else {
            Gdx.gl.glDisable(GL20.GL_BLEND);
        }
    }

    /** Tắt hoặc bật face culling cho mặt phẳng hai chiều và các bộ phận hở hai mặt. */
    private void setDoubleSided(boolean doubleSided) {
        if (cullDisabled == doubleSided) {
            return;
        }
        cullDisabled = doubleSided;
        if (doubleSided) {
            Gdx.gl.glDisable(GL20.GL_CULL_FACE);
        } else {
            Gdx.gl.glEnable(GL20.GL_CULL_FACE);
        }
    }

    /** Dùng cầu bao hình học quanh chân để giữ sừng, tai và vũ khí còn giao khung nhìn. */
    private boolean isInView(float radius, Frustum frustum, Vector3 eye, float drawDistance) {
        float limit = drawDistance + radius;
        return center.dst2(eye) <= limit * limit && frustum.sphereInFrustum(center, radius);
    }

    /** Tính biến đổi gốc và áp dụng tư thế của cá thể trước khi vẽ các phần. */
    private void drawMob(ShaderProgram shader, Entity entity, MobVisualState state,
                         PreparedModel model, float scale, float fuse) {
        model.model.resetPose();
        LivingEntity living = entity instanceof LivingEntity mob ? mob : null;
        if (living != null) {
            model.model.setupAnimation(living, state.limbSwing(), state.limbSwingAmount(), state.ageInTicks(),
                    state.headYaw(), state.headPitch());
        }

        rootTransform.setToTranslation(center);
        if (state.bodyYaw() != 0f) {
            rootTransform.rotate(Vector3.Y, state.bodyYaw());
        }
        if (state.bodyPitch() != 0f) {
            rootTransform.rotate(Vector3.X, state.bodyPitch());
        }
        if (living != null && !living.isAlive()) {
            float progress = MathUtils.clamp(1f - living.getDeathTimer(), 0f, 1f);
            rootTransform.rotate(Vector3.Z, progress * 90f);
        }
        rootTransform.scale(scale, scale * currentAppearance.heightScale(), scale);

        // Màu len chỉ áp dụng cho lớp phủ, còn dấu đỏ áp dụng cho cả cá thể.
        boolean hurt = living != null && living.getHurtFlashTimer() > 0f;
        boolean whiteFlash = fuse > 0f && ((int) (12f * fuse * fuse) & 1) == 1;
        int mode = hurt ? 1 : whiteFlash ? 2 : 0;
        if (tintMode != mode) {
            tintMode = mode;
            shader.setUniform1f("uMobWhiteFlash", mode == 2 ? 0.85f : 0f);
        }
        woolColor = currentAppearance == MobAppearance.SHEEP ? state.sheepWoolColor() : 0xffffff;
        hideOverlay = currentAppearance == MobAppearance.SHEEP && state.isSheepSheared();
        heldBlock = state.heldBlock();
        heldBlockPart = heldBlock == null ? null : model.model.heldBlockPart();
        MobAppearance.HorseMarkings markings = state.horseMarkings();
        int markingId = markings == null ? -1 : markings.ordinal();
        for (PreparedPart root : model.roots) {
            renderPart(root, rootTransform, 0, markingId, shader);
        }
        if (living != null && living.isAlive() && living.getFireTimer() > 0f) {
            drawFireOnMob(shader, entity);
        }
    }

    /**
     * Vẽ 2 mặt lửa chéo dạng chữ X ôm sát hộp va chạm của mob đang cháy,
     * tự phát sáng ({@code uWorldLight = (1, 1, 1)} và {@code aShade = -1}),
     * tắt face culling cục bộ rồi khôi phục toàn bộ trạng thái OpenGL và shader.
     */
    private void drawFireOnMob(ShaderProgram shader, Entity entity) {
        if (Gdx.gl == null || fireMesh == null || fireTexture0 == null || fireTexture1 == null) {
            return;
        }
        updateFireMeshVertices(fireAnimationSeconds);

        float width = entity.getHalfWidth() * 2.0f;
        float height = entity.getHeight();
        fireTransform.setToTranslation(center)
                .scale(width * FIRE_WIDTH_SCALE, height * FIRE_HEIGHT_SCALE, width * FIRE_WIDTH_SCALE);

        shader.copyWorldLight(savedWorldLight);
        setBlend(true);
        setDoubleSided(true);
        if (tintMode != 0) {
            tintMode = 0;
            shader.setUniform1f("uMobWhiteFlash", 0f);
        }
        applyTint(shader, 0xffffff);
        shader.setUniformVec3("uWorldLight", 1f, 1f, 1f);
        shader.setUniformMatrix4f("uModel", fireTransform);
        try {
            fireTexture0.bind(0);
            boundSkin = null;
            fireMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES, 0, 6);

            fireTexture1.bind(0);
            fireMesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES, 6, 6);
        } finally {
            shader.setUniformVec3("uWorldLight", savedWorldLight);
            setDoubleSided(false);
            setBlend(false);
            blockAtlas.bind();
        }
    }

    /** Cập nhật tọa độ UV 2 mặt chữ X trong {@code [-0.5..0.5, 0..1, -0.5..0.5]} khi đổi khung hình. */
    private void updateFireMeshVertices(double timeSeconds) {
        double safeTime = Math.max(0.0, timeSeconds);
        int frame0 = (int) ((long) Math.floor(safeTime / FIRE_FRAME_SECONDS + 1e-7) % fireFrameCount0);
        int frame1 = (int) ((long) Math.floor((safeTime + FIRE_LAYER_TIME_OFFSET) / FIRE_FRAME_SECONDS + 1e-7)
                % fireFrameCount1);
        if (frame0 == lastFireFrame0 && frame1 == lastFireFrame1) {
            return;
        }
        lastFireFrame0 = frame0;
        lastFireFrame1 = frame1;
        fireFrameUV(safeTime, fireFrameCount0, fireUv0);
        fireFrameUV(safeTime + FIRE_LAYER_TIME_OFFSET, fireFrameCount1, fireUv1);

        int offset = 0;
        offset = writeFireQuad(fireVertices, offset,
                -0.5f, 0.0f, -0.5f,
                0.5f, 0.0f, 0.5f,
                0.5f, 1.0f, 0.5f,
                -0.5f, 1.0f, -0.5f,
                fireUv0);
        writeFireQuad(fireVertices, offset,
                0.5f, 0.0f, -0.5f,
                -0.5f, 0.0f, 0.5f,
                -0.5f, 1.0f, 0.5f,
                0.5f, 1.0f, -0.5f,
                fireUv1);
        if (fireMesh != null) {
            fireMesh.setVertices(fireVertices, 0, fireVertices.length);
        }
    }

    /** Ghi 1 mặt tứ giác lửa (6 đỉnh × 6 floats) vào mảng {@code out} với {@code aShade = -1.0f}. */
    private static int writeFireQuad(float[] out, int offset,
                                     float ax, float ay, float az,
                                     float bx, float by, float bz,
                                     float cx, float cy, float cz,
                                     float dx, float dy, float dz,
                                     float[] uv) {
        float u0 = uv[0];
        float v0 = uv[1];
        float u1 = uv[2];
        float v1 = uv[3];
        offset = writeFireVertex(out, offset, ax, ay, az, u0, v1);
        offset = writeFireVertex(out, offset, bx, by, bz, u1, v1);
        offset = writeFireVertex(out, offset, cx, cy, cz, u1, v0);
        offset = writeFireVertex(out, offset, ax, ay, az, u0, v1);
        offset = writeFireVertex(out, offset, cx, cy, cz, u1, v0);
        return writeFireVertex(out, offset, dx, dy, dz, u0, v0);
    }

    /** Ghi một đỉnh 6 số thực của ngọn lửa vào bộ đệm tái sử dụng. */
    private static int writeFireVertex(float[] out, int offset, float x, float y, float z, float u, float v) {
        out[offset] = x;
        out[offset + 1] = y;
        out[offset + 2] = z;
        out[offset + 3] = u;
        out[offset + 4] = v;
        out[offset + 5] = FIRE_SELF_SHADE;
        return offset + FIRE_STRIDE;
    }

    /** Đi sâu cây khớp bằng ngăn xếp ma trận cấp phát một lần lúc nạp. */
    private void renderPart(PreparedPart prepared, Matrix4 parent, int depth, int markingId, ShaderProgram shader) {
        ModelPart part = prepared.part;
        if (!part.isVisible()) {
            return;
        }
        Matrix4 transform = transforms[depth];
        part.writeTransform(parent, transform);
        Material material = prepared.markings != null && markingId >= 0
                ? prepared.markings[markingId] : prepared.material;
        if (hideOverlay && part.layer() == ModelPart.Layer.OVERLAY) {
            material = null;
        }
        if (material != null) {
            setBlend(part.layer() == ModelPart.Layer.OVERLAY);
            setDoubleSided(part.isDoubleSided());
            applyTint(shader, part.layer() == ModelPart.Layer.OVERLAY ? woolColor : 0xffffff);
            if (boundSkin != material.skin) {
                boundSkin = material.skin;
                boundSkin.bind();
            }
            shader.setUniformMatrix4f("uModel", transform);
            material.mesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES);
        }
        if (part == heldBlockPart) {
            drawHeldBlock(shader, transform);
        }
        for (PreparedPart child : prepared.children) {
            renderPart(child, transform, depth + 1, markingId, shader);
        }
    }

    /** Tái sử dụng uniform khi hai phần có chung màu len và trạng thái sát thương. */
    private void applyTint(ShaderProgram shader, int rgb) {
        int encoded = rgb | tintMode << 24;
        if (appliedTint != encoded) {
            appliedTint = encoded;
            float greenBlueScale = (tintMode == 1 ? 0.45f : 1f) / 255f;
            shader.setUniformVec4("uTintColor", ((rgb >> 16) & 255) / 255f,
                    ((rgb >> 8) & 255) * greenBlueScale, (rgb & 255) * greenBlueScale, 1f);
        }
    }

    /** Vẽ khối thu nhỏ theo khớp đầu cáo hoặc giữa hai tay Enderman bằng atlas khối. */
    private void drawHeldBlock(ShaderProgram shader, Matrix4 jointTransform) {
        setBlend(false);
        setDoubleSided(false);
        applyTint(shader, 0xffffff);
        blockAtlas.bind();
        boundSkin = null;
        if (currentAppearance == MobAppearance.ENDERMAN) {
            heldBlockTransform.set(jointTransform).translate(0f, 16f, -10f).scale(8f, 8f, 8f);
        } else {
            heldBlockTransform.set(jointTransform).translate(0f, -2.8f, -7.2f).scale(2.9f, 2.9f, 2.9f);
        }
        ItemEntity.renderBlockMesh(shader, heldBlock, heldBlockTransform);
    }

    /** Giải phóng toàn bộ VAO/VBO và texture lửa, kể cả khi quá trình khởi tạo chỉ hoàn thành một phần. */
    @Override
    public void dispose() {
        if (disposed) {
            return;
        }
        disposed = true;
        for (Mesh mesh : meshes.values()) {
            mesh.dispose();
        }
        meshes.clear();
        if (fireMesh != null) {
            fireMesh.dispose();
        }
        if (fireTexture0 != null) {
            fireTexture0.dispose();
        }
        if (fireTexture1 != null) {
            fireTexture1.dispose();
        }
    }
}

package com.voxelgame.client.render.entity;

/** Định danh một ảnh thực thể theo nhóm, tên tệp và màu khi ảnh thiếu. */
public record MobTextureKey(String group, String name, int fallbackRgb) {
    /** Dựng đường dẫn classpath khi nạp trước và kiểm tra tài nguyên. */
    public String path() {
        return "textures/entity/" + group + "/" + name + ".png";
    }
}

package com.voxelgame.client.render.entity;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.files.FileHandle;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.Texture;
import com.badlogic.gdx.utils.Disposable;
import java.util.HashMap;
import java.util.Map;

/** Sở hữu cache texture thực thể riêng, ngoài atlas của khối. */
public final class MobTextureManager implements Disposable {
    /** Ảnh GPU và kích thước thật dùng để đổi tọa độ pixel sang UV. */
    record Skin(Texture texture, int width, int height, boolean fallback) {
        /** Dùng đơn vị ảnh 0 chung với shader thế giới. */
        void bind() {
            texture.bind(0);
        }
    }

    /** Ảnh đơn sắc dùng khi tệp thiếu hoặc không giải mã được. */
    private static final int FALLBACK_SIZE = 16;
    /** Ảnh gốc Ourcraft cho cung, giáo và lọ cầm tay. */
    public static final MobTextureKey HELD_EQUIPMENT = new MobTextureKey("equipment", "held", 0x8a7059);

    private final Map<MobTextureKey, Skin> skins = new HashMap<>();
    private final Map<MobTextureKey, Skin> layoutFallbacks = new HashMap<>();
    private boolean disposed;

    /** Nạp một biến thể đúng một lần, trước khi bắt đầu lượt vẽ. */
    Skin load(MobTextureKey key) {
        if (key == null) {
            return null;
        }
        if (disposed) {
            throw new IllegalStateException("Cache texture mob đã được giải phóng");
        }
        return skins.computeIfAbsent(key, this::readSkin);
    }

    /** Dùng ảnh dự phòng có chia sẻ khi ảnh giải mã được nhưng bố cục quá nhỏ. */
    Skin layoutFallback(MobTextureKey key) {
        return layoutFallbacks.computeIfAbsent(key, incompatible -> {
            Gdx.app.error("MobTextureManager", "Bố cục ảnh không đủ cho mô hình " + incompatible.path());
            return createFallback(incompatible.fallbackRgb());
        });
    }

    /** Đọc PNG từ classpath để game có thể chạy từ thư mục hoặc JAR. */
    private Skin readSkin(MobTextureKey key) {
        String path = key.path();
        Texture texture = null;
        try {
            FileHandle file = Gdx.files.classpath(path);
            if (!file.exists()) {
                throw new IllegalArgumentException("Thiếu tệp PNG");
            }
            // Hoa văn ngựa có ảnh thang xám kèm alpha. Ép RGBA để OpenGL Core nhận định dạng tải lên.
            texture = new Texture(file, Pixmap.Format.RGBA8888, false);
            configure(texture);
            return new Skin(texture, texture.getWidth(), texture.getHeight(), false);
        } catch (RuntimeException error) {
            if (texture != null) {
                texture.dispose();
            }
            Gdx.app.error("MobTextureManager", "Dùng ảnh dự phòng cho " + path + ": " + error.getMessage());
            return createFallback(key.fallbackRgb());
        }
    }

    /** Tạo ảnh màu và luôn giải phóng bộ đệm pixel ngoài heap ngay sau tải. */
    private static Skin createFallback(int rgb) {
        Pixmap image = new Pixmap(FALLBACK_SIZE, FALLBACK_SIZE, Pixmap.Format.RGBA8888);
        Texture texture = null;
        try {
            image.setColor((rgb << 8) | 0xff);
            image.fill();
            texture = new Texture(image, false);
            configure(texture);
            return new Skin(texture, FALLBACK_SIZE, FALLBACK_SIZE, true);
        } catch (RuntimeException error) {
            if (texture != null) {
                texture.dispose();
            }
            throw error;
        } finally {
            image.dispose();
        }
    }

    /** Giữ rìa pixel sắc nét và ngăn lặp lại texture ở biên. */
    private static void configure(Texture texture) {
        texture.setFilter(Texture.TextureFilter.Nearest, Texture.TextureFilter.Nearest);
        texture.setWrap(Texture.TextureWrap.ClampToEdge, Texture.TextureWrap.ClampToEdge);
    }

    /** Giải phóng mỗi texture GPU đúng một lần khi đóng ứng dụng. */
    @Override
    public void dispose() {
        if (disposed) {
            return;
        }
        disposed = true;
        for (Skin skin : skins.values()) {
            skin.texture.dispose();
        }
        skins.clear();
        for (Skin skin : layoutFallbacks.values()) {
            skin.texture.dispose();
        }
        layoutFallbacks.clear();
    }
}

package com.voxelgame.client.render.entity;

/** Điểm nối giữa thực thể sống và lượt vẽ mob. */
public interface MobVisual {
    /** Trả trạng thái hiển thị đã cấp phát của cá thể. */
    MobVisualState mobVisualState();
}

package com.voxelgame.client.render.entity;

import com.voxelgame.world.level.block.Block;

import com.badlogic.gdx.math.MathUtils;
import java.util.Objects;

/** Trạng thái hiển thị của một cá thể, tách khỏi mẫu hình học dùng chung. */
public final class MobVisualState {
    /** Tư thế do hành vi của cá thể chọn trước khi vẽ. */
    public enum Pose {
        IDLE, UNDEAD, AIM_BOW, THRUST, GRAZE, RAM, REAR, FLAP, HOP, TILT_HEAD, POUNCE, SLEEP, SIT, ANGRY, DRINK,
        SHAKE, CROUCH, FACEPLANT
    }

    private MobAppearance appearance;
    private MobAppearance.HorseMarkings horseMarkings;
    private Pose pose = Pose.IDLE;
    private float poseAmount;
    /** Mức nâng hai vai khi chuyển qua lại giữa bước đi và tư thế ngắm. */
    private float bowAim;
    private float bodyYaw;
    private float bodyPitch;
    private float headYaw;
    private float headPitch;
    private float limbSwing;
    private float limbSwingAmount;
    private float ageInTicks;
    private float scale = 1f;
    private float fuseProgress;
    private int sheepWoolColor = 0xffffff;
    private boolean sheepSheared;
    private Block heldBlock;

    /** Tạo một trạng thái tái sử dụng cho cá thể với ngoại hình ban đầu. */
    public MobVisualState(MobAppearance appearance) {
        setAppearance(appearance);
    }

    /** Chọn model và biến thể texture đã nạp trước, ví dụ ngoại hình sói đang giận. */
    public void setAppearance(MobAppearance appearance) {
        this.appearance = Objects.requireNonNull(appearance);
    }

    /** Chọn hoa văn lông ngựa hoặc truyền null để bỏ lớp hoa văn. */
    public void setHorseMarkings(MobAppearance.HorseMarkings markings) {
        horseMarkings = markings;
    }

    /** Chọn tư thế và tỷ lệ nội suy từ tư thế thường tới tư thế đó. */
    public void setPose(Pose pose, float amount) {
        this.pose = Objects.requireNonNull(pose);
        poseAmount = MathUtils.clamp(amount, 0f, 1f);
    }

    /** Đặt hướng thân, góc đầu tương đối theo độ và nhịp chân theo radian. */
    public void setAnimation(float bodyYaw, float headYaw, float headPitch,
                             float limbSwing, float swingAmount, float ageInTicks) {
        this.bodyYaw = bodyYaw;
        this.headYaw = headYaw;
        this.headPitch = headPitch;
        this.limbSwing = limbSwing;
        limbSwingAmount = MathUtils.clamp(swingAmount, 0f, 1f);
        this.ageInTicks = ageInTicks;
    }

    /** Đặt kích thước hiển thị tương đối để dùng lại mẫu cho cá thể non. */
    public void setScale(float scale) {
        if (!(scale > 0f) || !Float.isFinite(scale)) {
            throw new IllegalArgumentException("Hệ số vẽ mob phải dương và hữu hạn");
        }
        this.scale = scale;
    }

    /** Xoay thân theo trục ngang, ví dụ để hướng mũi tên theo góc bay. */
    public void setBodyPitch(float pitch) {
        bodyPitch = pitch;
    }

    /** Đặt phần tiến độ phồng và chớp trước nổ từ 0 đến 1. */
    public void setFuseProgress(float progress) {
        fuseProgress = MathUtils.clamp(progress, 0f, 1f);
    }

    /** Nhuộm duy nhất lớp len, dùng giá trị RGB đóng gói để không tạo vật liệu mới. */
    public void setSheepWoolColor(int rgb) {
        sheepWoolColor = rgb & 0xffffff;
    }

    /** Đặt khối ngậm ở miệng cáo, hoặc null khi miệng trống. */
    public void setHeldBlock(Block block) {
        heldBlock = block;
    }

    /** Trả màu RGB của lớp len. */
    public int sheepWoolColor() { return sheepWoolColor; }
    /** Đánh dấu cừu đã bị cắt lông để ẩn lớp phủ len khi vẽ. */
    public void setSheepSheared(boolean sheared) { sheepSheared = sheared; }
    /** Trả trạng thái đã bị cắt lông của cừu. */
    public boolean isSheepSheared() { return sheepSheared; }
    /** Trả vật đang ngậm để gắn lưới dùng chung vào khớp đầu. */
    public Block heldBlock() { return heldBlock; }

    /** Đọc mẫu và biến thể vật liệu đang dùng. */
    public MobAppearance appearance() { return appearance; }
    /** Đọc hoa văn lông ngựa hiện tại. */
    public MobAppearance.HorseMarkings horseMarkings() { return horseMarkings; }
    /** Đọc tư thế hiện tại. */
    public Pose pose() { return pose; }
    /** Đọc tỷ lệ nội suy của tư thế. */
    public float poseAmount() { return poseAmount; }
    /** Nâng hoặc hạ vai trong ba tick, độc lập với tiến độ kéo dây. */
    public void updateBowAim(float dt) {
        float target = pose == Pose.AIM_BOW ? 1f : 0f;
        bowAim += MathUtils.clamp(target - bowAim, -dt / 0.15f, dt / 0.15f);
    }
    /** Trả mức nâng vai đã làm mượt của riêng cá thể. */
    public float bowAim() { return bowAim; }
    /** Đọc góc quay của thân theo trục đứng. */
    public float bodyYaw() { return bodyYaw; }
    /** Đọc góc dọc của thân theo độ. */
    public float bodyPitch() { return bodyPitch; }
    /** Đọc góc ngang của đầu so với thân. */
    public float headYaw() { return headYaw; }
    /** Đọc góc dọc của đầu. */
    public float headPitch() { return headPitch; }
    /** Đọc pha vung chân của bước hiện tại. */
    public float limbSwing() { return limbSwing; }
    /** Đọc biên độ vung chân đã chặn từ 0 đến 1. */
    public float limbSwingAmount() { return limbSwingAmount; }
    /** Đọc đồng hồ hoạt ảnh tính bằng tick. */
    public float ageInTicks() { return ageInTicks; }
    /** Đọc hệ số kích thước hiển thị. */
    public float scale() { return scale; }
    /** Đọc tiến độ phồng trước khi nổ. */
    public float fuseProgress() { return fuseProgress; }
}

package com.voxelgame.core;

import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.World;

/**
 * Giao diện hợp đồng chuẩn hóa tương tác chuột phải giữa người chơi và đối tượng trong thế giới.
 * Dùng để phân biệt hành vi "có thể tương tác" (can-do) khỏi cây kế thừa lớp (is-a),
 * ví dụ: cắt len Cừu, vắt sữa Bò/Dê, thuần hóa Sói, hoặc lên yên thú cưỡi.
 */
public interface Interactable {

    /**
     * Xử lý tương tác chuột phải từ người chơi với vật phẩm đang cầm trên tay.
     *
     * @param world    Thế giới hiện tại.
     * @param player   Người chơi thực hiện tương tác.
     * @param heldItem Vật phẩm đang cầm ở ô Hotbar hiện tại (có thể null nếu tay không).
     * @return {@code true} nếu tương tác đã được xử lý và tiêu thụ sự kiện; ngược lại {@code false}.
     */
    boolean onInteract(World world, Player player, Item heldItem);
}

package com.voxelgame.core;

import com.voxelgame.client.render.ShaderProgram;

/**
 * Giao diện hợp đồng chuẩn hóa khả năng kết xuất đồ họa 3D bằng ShaderProgram.
 * Cho phép các đối tượng trong thế giới được vẽ đa hình mà không phụ thuộc vào lớp cụ thể.
 */
public interface Renderable {

    /**
     * Kết xuất đối tượng lên màn hình bằng chương trình shader hiện hành.
     *
     * @param shader Chương trình GLSL đang được kích hoạt.
     */
    void render(ShaderProgram shader);
}

package com.voxelgame.core;

import com.voxelgame.world.level.World;

/**
 * Giao diện hợp đồng chuẩn hóa vòng cập nhật logic theo thời gian thực (deltaTime).
 * Mọi thực thể và hệ thống mô phỏng thế giới đều có thể triển khai giao diện này
 * để được điều phối đa hình trong Game Loop.
 */
public interface Tickable {

    /**
     * Cập nhật trạng thái logic sau một khoảng thời gian khung hình.
     *
     * @param world     Thế giới hiện tại chứa dữ liệu voxel và thực thể.
     * @param deltaTime Thời gian trôi qua giữa hai khung hình (tính bằng giây).
     */
    void tick(World world, float deltaTime);
}

package com.voxelgame.world.effect;

/** Khe hiệu ứng có thể tái sử dụng, với cấp I biểu diễn bằng amplifier 0. */
public final class StatusEffectInstance {
    private int amplifier;
    private float duration;

    /** Ghi cấp và thời lượng mới, tính bằng giây. */
    public void set(int amplifier, float duration) {
        this.amplifier = amplifier;
        this.duration = duration;
    }

    /** Trừ thời gian thực sự hiệu lực trong bước hiện tại và trả lại phần đó. */
    public float advance(float deltaTime) {
        float activeTime = Math.min(deltaTime, duration);
        duration -= activeTime;
        return activeTime;
    }

    /** Trả amplifier, trong đó 0 tương ứng cấp I. */
    public int amplifier() {
        return amplifier;
    }

    /** Trả thời lượng còn lại tính bằng giây. */
    public float duration() {
        return duration;
    }
}

package com.voxelgame.world.effect;

/** Các hiệu ứng sinh tồn và chiến đấu, theo thứ tự chỉ số trong mảng hiệu ứng. */
public enum StatusEffectType {
    HUNGER, WEAKNESS, SLOWNESS, POISON, FIRE_RESISTANCE, WATER_BREATHING, SWIFTNESS;

    /** Đếm loại hiệu ứng một lần khi nạp lớp để cấp phát các khe cố định. */
    public static final int COUNT = values().length;

    /** Trả loại hiệu ứng theo chỉ số để duyệt mà không sao chép mảng enum. */
    public static StatusEffectType at(int index) {
        return switch (index) {
            case 0 -> HUNGER;
            case 1 -> WEAKNESS;
            case 2 -> SLOWNESS;
            case 3 -> POISON;
            case 4 -> FIRE_RESISTANCE;
            case 5 -> WATER_BREATHING;
            case 6 -> SWIFTNESS;
            default -> throw new IndexOutOfBoundsException(index);
        };
    }
}

package com.voxelgame.world.entity;

/** Nguồn sát thương và khả năng được giảm bởi giáp tự nhiên. */
public enum DamageSource {
    MELEE(true), ARROW(true), POTION_MAGIC(false), EXPLOSION(true), FALL(false),
    CACTUS(true), LAVA(false), FIRE(false), SUNLIGHT(false), DROWNING(false), WATER(false);

    /** Cờ cho phép áp dụng công thức giáp vật lý. */
    private final boolean armorApplies;

    /** Gắn quy tắc giáp cho nguồn tương ứng. */
    DamageSource(boolean armorApplies) {
        this.armorApplies = armorApplies;
    }

    /** Cho biết nguồn này chịu ảnh hưởng của giáp. */
    public boolean armorApplies() {
        return armorApplies;
    }
}

package com.voxelgame.world.entity;

import com.voxelgame.client.render.ShaderProgram;
import com.voxelgame.core.Renderable;
import com.voxelgame.core.Tickable;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.Vector3;

/**
 * Lớp cha trừu tượng gốc (Abstract Base Class) đại diện cho mọi thực thể động tồn
 * tại trong không gian 3D, triển khai hai hợp đồng cốt lõi {@link Tickable} và {@link Renderable}.
 *
 * THỂ HIỆN 4 TÍNH CHẤT OOP:
 * 1. Tính Trừu tượng (Abstraction):
 * - Khai báo khái niệm tổng quát về một thực thể trong thế giới Voxel với 2
 *   hành vi trừu tượng bắt buộc các lớp con định nghĩa: `update(World, float)` và
 *   `render(ShaderProgram)`.
 * 2. Tính Kế thừa (Inheritance):
 * - Cung cấp các thuộc tính vật lý cốt lõi (`position`, `velocity`,
 *   `halfWidth`, `height`, `onGround`) và thuật toán kiểm tra giao cắt hộp va chạm AABB
 *   (`intersectsBlock`) cho mọi lớp con (`LivingEntity`, `ItemEntity`, `FallingBlockEntity`, `ProjectileEntity`).
 * 3. Tính Đa hình (Polymorphism):
 * - Đa hình lúc chạy (Runtime Polymorphism / Method Overriding): Cho phép `World` quản lý chung
 *   danh sách `List<Entity>` và gọi `entity.update(...)`, `entity.render(...)` đồng nhất.
 * 4. Tính Đóng gói (Encapsulation):
 * - Bảo vệ trạng thái tọa độ nội bộ bằng kỹ thuật sao chép phòng thủ (Defensive Copying) trong
 *   `getPosition()`, `getCenterPosition()` và `getVelocity()`, ngăn bên ngoài sửa trực tiếp vector gốc.
 */
public abstract class Entity implements Tickable, Renderable {

    /** Khe nhỏ để thực thể không dính vào bề mặt va chạm. */
    protected static final float CONTACT_EPSILON = 0.0001f;
    /** Đỉnh vật cản của lần quét gần nhất, dùng khi thử bước lên tuyết. */
    protected float obstacleTop;
    /** Kết quả gần nhất dùng chung giữa hộp thân và các hộp gắn kèm trong một lần quét. */
    private float sweepLimit;
    private Block sweepHit;

    // Tọa độ điểm chính giữa dưới đáy (Bottom-Center) của hộp va chạm AABB (sử dụng
    // Vector3 của libGDX)
    protected final Vector3 position;
    // Vector vận tốc chuyển động theo 3 trục (X, Y, Z)
    protected final Vector3 velocity;

    // Một nửa chiều rộng (bán kính ngang) và toàn bộ chiều cao của hộp va chạm AABB;
    // giữ khả năng thay đổi để đồng bộ hitbox khi mob chuyển đổi trạng thái non/trưởng thành.
    protected float halfWidth;
    /** Chiều cao thực của hộp, có thể đổi khi loài có tư thế ngồi hoặc trạng thái non. */
    protected float height;

    // Cờ trạng thái báo hiệu thực thể đang đứng chạm mặt đất rắn
    protected boolean onGround = false;

    /**
     * Constructor đầy đủ dành cho các thực thể động xuất hiện tại tọa độ cụ thể
     * trong thế giới
     * (ví dụ: Player hoặc ItemEntity văng ra khi đập vỡ Block).
     *
     * @param x         tọa độ khởi tạo trục X
     * @param y         tọa độ khởi tạo trục Y (đáy thực thể)
     * @param z         tọa độ khởi tạo trục Z
     * @param halfWidth một nửa chiều rộng (bán kính theo trục ngang)
     * @param height    tổng chiều cao thực thể theo trục đứng
     */
    protected Entity(float x, float y, float z, float halfWidth, float height) {
        this.position = new Vector3(x, y, z);
        this.velocity = new Vector3(0.0f, 0.0f, 0.0f);
        this.halfWidth = halfWidth;
        this.height = height;
    }

    /**
     * Kiểm tra xem hộp va chạm AABB của thực thể hiện tại có giao cắt với ô lưới
     * Block
     * tại tọa độ nguyên (blockX, blockY, blockZ) hay không.
     * Dùng để ngăn người chơi đặt Block mới đè vào chính cơ thể mình.
     *
     * @param blockX tọa độ X nguyên của block cần kiểm tra
     * @param blockY tọa độ Y nguyên của block cần kiểm tra
     * @param blockZ tọa độ Z nguyên của block cần kiểm tra
     * @return true nếu hộp va chạm của thực thể giao cắt với khối lập phương của
     *         block
     */
    public boolean intersectsBlock(int blockX, int blockY, int blockZ) {
        return intersectsBlock(blockX, blockY, blockZ, Block.FULL_BOUNDS);
    }

    /** Kiểm tra hộp tùy chỉnh của block tại tọa độ trong thế giới. */
    public boolean intersectsBlock(int blockX, int blockY, int blockZ, Block.Bounds bounds) {
        return bounds != null && bounds.intersects(blockX, blockY, blockZ,
                position.x - halfWidth, position.y, position.z - halfWidth,
                position.x + halfWidth, position.y + height, position.z + halfWidth);
    }

    /** Quét một trục của hộp thực thể qua địa hình và dừng tại mặt gần nhất. */
    protected Block moveAxis(World world, int axis, float distance) {
        if (distance == 0) {
            return null;
        }
        sweepLimit = distance;
        sweepHit = null;
        sweepTerrainBox(world, axis, distance, position.x, position.y, position.z, halfWidth, height);
        sweepAttachedTerrainBoxes(world, axis, distance);
        float limit = sweepLimit;
        if (sweepHit != null) {
            limit = distance > 0f ? Math.max(0, limit - CONTACT_EPSILON)
                    : Math.min(0, limit + (axis == 1 ? 0 : CONTACT_EPSILON));
        }
        if (axis == 0) {
            position.x += limit;
        } else if (axis == 1) {
            position.y += limit;
        } else {
            position.z += limit;
        }
        return sweepHit;
    }

    /** Cho thực thể mang hành khách bổ sung hộp của người ngồi vào cùng lượt quét. */
    protected void sweepAttachedTerrainBoxes(World world, int axis, float distance) {
    }

    /** Quét một hộp qua các hình va chạm chính xác và cập nhật mặt cản gần nhất. */
    protected final void sweepTerrainBox(World world, int axis, float distance,
                                         float centerX, float base, float centerZ, float radius, float boxHeight) {
        float left = centerX - radius;
        float right = centerX + radius;
        float top = base + boxHeight;
        float back = centerZ - radius;
        float front = centerZ + radius;
        float low = Math.min(0, distance);
        float high = Math.max(0, distance);
        int minX = (int) Math.floor(left + (axis == 0 ? low : 0));
        int maxX = (int) Math.floor(right + (axis == 0 ? high : 0));
        int minY = (int) Math.floor(base + (axis == 1 ? low : 0));
        int maxY = (int) Math.floor(top + (axis == 1 ? high : 0));
        int minZ = (int) Math.floor(back + (axis == 2 ? low : 0));
        int maxZ = (int) Math.floor(front + (axis == 2 ? high : 0));
        boolean positive = distance > 0;
        float entityEdge = axis == 0 ? (positive ? right : left)
                : axis == 1 ? (positive ? top : base) : (positive ? front : back);
        for (int x = minX; x <= maxX; x++) {
            for (int y = minY; y <= maxY; y++) {
                for (int z = minZ; z <= maxZ; z++) {
                    Block.Bounds b = world.getCollisionBounds(x, y, z);
                    if (b == null || (axis != 0 && (right <= x + b.minX() || left >= x + b.maxX()))
                            || (axis != 1 && (top <= y + b.minY() || base >= y + b.maxY()))
                            || (axis != 2 && (front <= z + b.minZ() || back >= z + b.maxZ()))) {
                        continue;
                    }
                    float edge = axis == 0 ? x + (positive ? b.minX() : b.maxX())
                            : axis == 1 ? y + (positive ? b.minY() : b.maxY())
                            : z + (positive ? b.minZ() : b.maxZ());
                    float gap = edge - entityEdge;
                    if (positive ? gap >= -CONTACT_EPSILON && gap <= sweepLimit
                            : gap <= CONTACT_EPSILON && gap >= sweepLimit) {
                        sweepLimit = gap;
                        sweepHit = Block.fromId(world.getBlock(x, y, z));
                        obstacleTop = y + b.maxY();
                    }
                }
            }
        }
    }

    /** Kiểm tra hộp thực thể tại vị trí hiện tại trước khi cam kết một bước. */
    protected boolean overlapsTerrain(World world) {
        for (int x = (int) Math.floor(position.x - halfWidth); x <= (int) Math.floor(position.x + halfWidth); x++) {
            for (int y = (int) Math.floor(position.y); y <= (int) Math.floor(position.y + height); y++) {
                for (int z = (int) Math.floor(position.z - halfWidth); z <= (int) Math.floor(position.z + halfWidth); z++) {
                    if (intersectsBlock(x, y, z, world.getCollisionBounds(x, y, z))) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Trả về bản sao (Defensive Copy) tọa độ chân của thực thể để bảo vệ dữ liệu
     * nội bộ.
     *
     * @return đối tượng Vector3 mới mang giá trị vị trí hiện tại
     */
    public Vector3 getPosition() {
        return new Vector3(position);
    }

    /** Chép tọa độ chân vào bộ đệm có sẵn để duyệt thực thể mà không cấp phát. */
    public Vector3 copyPosition(Vector3 target) {
        return target.set(position);
    }

    /** Chép tâm thực thể vào bộ đệm có sẵn để cập nhật vật lý mỗi khung hình. */
    public Vector3 copyCenterPosition(Vector3 target) {
        return target.set(position.x, position.y + height * 0.5f, position.z);
    }

    /**
     * Cập nhật tọa độ của thực thể một cách an toàn.
     *
     * @param x tọa độ mới trục X
     * @param y tọa độ mới trục Y
     * @param z tọa độ mới trục Z
     */
    public void setPosition(float x, float y, float z) {
        this.position.set(x, y, z);
    }

    /**
     * Trả về bản sao (Defensive Copy) tọa độ tâm hình học của thực thể.
     *
     * @return đối tượng Vector3 mới mang tọa độ tâm cơ thể
     */
    public Vector3 getCenterPosition() {
        return new Vector3(position.x, position.y + height * 0.5f, position.z);
    }

    /**
     * Trả về bản sao (Defensive Copy) vector vận tốc hiện tại của thực thể.
     *
     * @return đối tượng Vector3 mới mang giá trị vận tốc hiện tại
     */
    public Vector3 getVelocity() {
        return new Vector3(velocity);
    }

    /** Chép vận tốc vào bộ đệm của AI mà không tạo vector mỗi lượt cập nhật. */
    public Vector3 copyVelocity(Vector3 target) {
        return target.set(velocity);
    }

    public float getHalfWidth() {
        return halfWidth;
    }

    public float getHeight() {
        return height;
    }

    public boolean isOnGround() {
        return onGround;
    }

    /** Triển khai hợp đồng {@link Tickable} bằng cách ủy quyền về {@link #update(World, float)}. */
    @Override
    public void tick(World world, float deltaTime) {
        update(world, deltaTime);
    }

    /**
     * Phương thức trừu tượng cập nhật trạng thái logic và vật lý của thực thể ở mỗi
     * khung hình.
     *
     * @param world     thế giới voxel chứa thực thể
     * @param deltaTime khoảng thời gian trôi qua giữa hai khung hình (giây)
     */
    public abstract void update(World world, float deltaTime);

    /**
     * Phương thức trừu tượng kết xuất hình ảnh 3D của thực thể lên màn hình.
     *
     * @param shader chương trình Shader đang hoạt động
     */
    @Override
    public abstract void render(ShaderProgram shader);
}

package com.voxelgame.world.entity;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.client.render.ShaderProgram;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.Matrix4;

/** Đại diện một ô cát hoặc sỏi đang rơi trước khi được ghi lại vào thế giới. */
public final class FallingBlockEntity extends Entity {
    /** Cùng quy mô trọng lực với người chơi và giới hạn vận tốc rơi. */
    private static final float GRAVITY = 26.0f;
    private static final float TERMINAL_SPEED = 45.0f;

    private final int blockX;
    private final int blockZ;
    private final Block block;
    private final Matrix4 model = new Matrix4();
    private boolean finished;

    /** Giữ tâm ngang của ô nguồn và đặt đáy thực thể tại đáy ô. */
    public FallingBlockEntity(int x, int y, int z, Block block) {
        super(x + 0.5f, y, z + 0.5f, 0.5f, 1.0f);
        blockX = x;
        blockZ = z;
        this.block = block;
    }

    /** Quét dọc qua tất cả bề mặt mà đáy thực thể đi qua trong bước này. */
    @Override
    public void update(World world, float deltaTime) {
        if (finished) {
            return;
        }
        velocity.y = Math.max(-TERMINAL_SPEED, velocity.y - GRAVITY * deltaTime);
        float nextY = position.y + velocity.y * deltaTime;
        int floor = Math.max(0, (int) Math.floor(nextY) - 1);
        for (int y = (int) Math.floor(position.y); y >= floor; y--) {
            Block.Bounds support = world.getCollisionBounds(blockX, y, blockZ);
            if (support == null) {
                continue;
            }
            float top = y + support.maxY();
            if (top <= position.y && top >= nextY) {
                // Chỉ đặt lại khi đỉnh nền khớp lưới; mặt thấp làm rơi vật phẩm.
                if (support.maxY() < 1.0f || !world.tryPlaceBlock(blockX, y + 1, blockZ, block, world.getPlayer())) {
                    world.spawnDroppedItem(new ItemEntity(position.x, top, position.z, block));
                }
                // Dùng vật liệu đang rơi và vị trí tiếp xúc, kể cả khi phải rơi thành vật phẩm.
                AudioManager audio = world.getAudio();
                if (audio != null) {
                    audio.playLanding(block, world.getAudioGain(position.x, top, position.z));
                }
                finished = true;
                return;
            }
        }
        position.y = nextY;
        if (nextY < -25.0f) {
            finished = true;
        }
    }

    /** Vẽ ô đang rơi ở kích thước thật, không xoay hoặc nhấp nhô. */
    @Override
    public void render(ShaderProgram shader) {
        model.setToTranslation(position.x, position.y + 0.5f, position.z);
        ItemEntity.renderBlockMesh(shader, block, model);
    }

    /** Cho World thu hồi thực thể sau khi đặt lại hoặc rơi khỏi bản đồ. */
    public boolean isFinished() {
        return finished;
    }
}

package com.voxelgame.world.entity;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.client.render.ShaderProgram;
import com.voxelgame.world.entity.player.Hotbar;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Mesh;
import com.badlogic.gdx.graphics.VertexAttribute;
import com.badlogic.gdx.graphics.VertexAttributes;
import com.badlogic.gdx.graphics.VertexAttributes.Usage;
import com.badlogic.gdx.math.Matrix4;
import com.badlogic.gdx.math.Vector3;
import java.util.HashMap;
import java.util.Map;

/**
 * Thực thể Vật phẩm 3D nhỏ rơi ra ngoài thế giới sau khi người chơi đập vỡ Block hoặc tiêu diệt/tương tác Mob,
 * kế thừa từ {@link Entity}.
 */
public class ItemEntity extends Entity {

    /** Kích thước cạnh của vật phẩm thu nhỏ (0.28 block). */
    private static final float ITEM_SCALE = 0.28f;
    private static final float HALF_SIZE = ITEM_SCALE * 0.5f;

    /** Các hằng số vật lý của Item rơi. */
    private static final float ITEM_GRAVITY = -18.0f;
    private static final float DEFAULT_PICKUP_DELAY = 0.25f;
    private static final float MAGNET_DISTANCE = 1.85f;
    private static final float PICKUP_DISTANCE = 0.85f;
    private static final float MAX_LIFETIME = 300.0f;

    /** Bộ đệm cho tâm người chơi và hướng hút vật phẩm. */
    private final Vector3 pullDirection = new Vector3();

    private final Item item;
    private int count = 1;
    private float pickupDelay = DEFAULT_PICKUP_DELAY;
    private float age = 0.0f;
    private boolean collected = false;

    private final Matrix4 modelMatrix = new Matrix4();

    /** Bộ nhớ đệm lưu trữ lưới Mesh dùng chung cho từng loại Block và Item độc lập. */
    private static final Map<Block, Mesh> SHARED_MESHES = new HashMap<>();
    private static final Map<Item, Mesh> SHARED_ITEM_MESHES = new HashMap<>();

    /** Thuộc tính đỉnh của Mesh ItemEntity: aPos (3), aTexCoord (2), aShade (1). */
    private static final VertexAttributes VERTEX_ATTRIBUTES = new VertexAttributes(
            new VertexAttribute(Usage.Position, 3, "aPos"),
            new VertexAttribute(Usage.TextureCoordinates, 2, "aTexCoord"),
            new VertexAttribute(Usage.Generic, 1, "aShade")
    );

    /**
     * Constructor 1: Tự động tạo vận tốc nảy nhẹ ngẫu nhiên khi khối vừa vỡ ra.
     */
    public ItemEntity(float startX, float startY, float startZ, Block block) {
        this(startX, startY, startZ, Item.of(block));
    }

    /**
     * Constructor 2: Tự động tạo vận tốc nảy nhẹ ngẫu nhiên cho một {@link Item} bất kỳ.
     */
    public ItemEntity(float startX, float startY, float startZ, Item item) {
        this(
                startX,
                startY,
                startZ,
                new Vector3(
                        (float) ((Math.random() - 0.5) * 1.4),
                        3.2f,
                        (float) ((Math.random() - 0.5) * 1.4)
                ),
                item
        );
    }

    /**
     * Constructor 3: Cho phép chỉ định vector vận tốc văng cụ thể cho Block.
     */
    public ItemEntity(float startX, float startY, float startZ, Vector3 initialVelocity, Block block) {
        this(startX, startY, startZ, initialVelocity, Item.of(block));
    }

    /**
     * Constructor 4: Cho phép chỉ định vector vận tốc văng cụ thể cho {@link Item}.
     */
    public ItemEntity(float startX, float startY, float startZ, Vector3 initialVelocity, Item item) {
        this(startX, startY, startZ, initialVelocity, item, 1, DEFAULT_PICKUP_DELAY);
    }

    /**
     * Constructor 5: Cho phép chỉ định đầy đủ vận tốc, số lượng stack và thời gian trễ trước khi nhặt.
     */
    public ItemEntity(float startX, float startY, float startZ, Vector3 initialVelocity,
                      Item item, int count, float pickupDelay) {
        super(startX, startY, startZ, HALF_SIZE, ITEM_SCALE);
        if (initialVelocity != null) {
            this.velocity.set(initialVelocity);
        }
        this.item = (item != null) ? item : Item.NONE;
        this.count = Math.max(1, count);
        this.pickupDelay = Math.max(0.0f, pickupDelay);
    }

    /**
     * Cập nhật vật lý rơi, hiệu ứng lực hút nam châm về phía {@link Player} và tự động cộng vào {@link Hotbar}.
     */
    @Override
    public void update(World world, float deltaTime) {
        if (world == null) {
            return;
        }

        Player player = world.getPlayer();
        Hotbar hotbar = (player != null) ? player.getHotbar() : null;
        update(world, player, hotbar, deltaTime);
    }

    /**
     * Phương thức nạp chồng hỗ trợ cập nhật trực tiếp với đối tượng {@link Player} và {@link Hotbar}.
     */
    public void update(World world, Player player, Hotbar hotbar, float deltaTime) {
        if (collected) {
            return;
        }

        age += deltaTime;
        if (age >= MAX_LIFETIME) {
            collected = true;
            return;
        }

        // 1. Kiểm tra khoảng cách tới tâm cơ thể người chơi để kích hoạt lực hút nam châm
        if (player != null && hotbar != null) {
            Vector3 playerCenter = player.copyCenterPosition(pullDirection);
            float distSq = position.dst2(playerCenter);

            if (age >= pickupDelay && distSq <= MAGNET_DISTANCE * MAGNET_DISTANCE) {
                if (distSq <= PICKUP_DISTANCE * PICKUP_DISTANCE) {
                    int added = hotbar.addItemUpTo(item, count);
                    if (added > 0) {
                        count -= added;
                        if (count <= 0) {
                            count = 0;
                            collected = true;
                        }
                        AudioManager audio = world == null ? null : world.getAudio();
                        if (audio != null) {
                            audio.playEffect(AudioManager.Effect.PICKUP, 0.3f);
                        }
                        if (collected) {
                            return;
                        }
                    }
                }

                Vector3 pullDir = playerCenter.sub(position);
                if (pullDir.len2() > 0.0001f) {
                    pullDir.nor().scl(9.5f);
                    position.add(pullDir.x * deltaTime, pullDir.y * deltaTime, pullDir.z * deltaTime);
                    return;
                }
            }
        }

        // 2. Áp dụng trọng lực kéo xuống và ma sát ngang
        velocity.y += ITEM_GRAVITY * deltaTime;
        if (velocity.y < -25.0f) {
            velocity.y = -25.0f;
        }

        float damping = onGround ? 0.82f : 0.96f;
        velocity.x *= damping;
        velocity.z *= damping;

        // Tọa độ vẽ ở tâm vật phẩm, còn quét va chạm dùng đáy hộp.
        position.y -= HALF_SIZE;
        if (moveAxis(world, 0, velocity.x * deltaTime) != null) {
            velocity.x = 0.0f;
        }
        if (moveAxis(world, 2, velocity.z * deltaTime) != null) {
            velocity.z = 0.0f;
        }
        onGround = false;
        if (moveAxis(world, 1, velocity.y * deltaTime) != null) {
            onGround = velocity.y < 0;
            velocity.y = 0;
        }
        position.y += HALF_SIZE;
    }

    /**
     * Vẽ vật phẩm 3D thu nhỏ tại vị trí hiện tại kèm hiệu ứng tự xoay tròn và nhấp nhô.
     */
    @Override
    public void render(ShaderProgram shader) {
        if (collected || item == null || item.isNone() || count <= 0) {
            return;
        }

        float bobOffset = (float) Math.sin(age * 3.8f) * 0.07f + 0.08f;
        float rotationDegrees = age * 110.0f;

        if (item.isBlock()) {
            modelMatrix.idt()
                    .translate(position.x, position.y + bobOffset, position.z)
                    .rotate(Vector3.Y, rotationDegrees)
                    .scale(ITEM_SCALE, ITEM_SCALE, ITEM_SCALE);
            renderBlockMesh(shader, item.getBlock(), modelMatrix);
        } else {
            float scale = item.isCubeItem() ? ITEM_SCALE : 0.40f;
            modelMatrix.idt()
                    .translate(position.x, position.y + bobOffset, position.z)
                    .rotate(Vector3.Y, rotationDegrees)
                    .scale(scale, scale, scale);
            shader.setUniformMatrix4f("uModel", modelMatrix);
            getOrCreateItemMesh(item).render(shader.getGdxShader(), GL20.GL_TRIANGLES);
        }
    }

    /** Chia sẻ hình block giữa vật phẩm nhỏ và thực thể trọng lực kích thước thật. */
    public static void renderBlockMesh(ShaderProgram shader, Block block, Matrix4 model) {
        shader.setUniformMatrix4f("uModel", model);
        getOrCreateMesh(block).render(shader.getGdxShader(), GL20.GL_TRIANGLES);
    }

    public boolean isCollected() {
        return collected;
    }

    /** Trả về số lượng vật phẩm còn lại trong thực thể rơi này. */
    public int getCount() {
        return count;
    }

    /** Thiết lập số lượng vật phẩm trong thực thể rơi (tối thiểu 1). */
    public void setCount(int count) {
        this.count = Math.max(1, count);
    }

    /** Trả về thời gian chờ (giây) trước khi người chơi có thể nhặt vật phẩm này. */
    public float getPickupDelay() {
        return pickupDelay;
    }

    /** Thiết lập thời gian chờ (giây) trước khi người chơi có thể nhặt vật phẩm này. */
    public void setPickupDelay(float pickupDelay) {
        this.pickupDelay = Math.max(0.0f, pickupDelay);
    }

    /** Chuyển vật phẩm sang thực thể nhặt nếu đó là một Block, giữ tương thích cho các luật cũ. */
    public Block collectForMob() {
        if (collected || !item.isBlock()) {
            return null;
        }
        count--;
        if (count <= 0) {
            count = 0;
            collected = true;
        }
        return item.getBlock();
    }

    /** Chuyển vật phẩm bất kỳ (Block hoặc Item độc lập) sang thực thể nhặt. */
    public Item collectItemForMob() {
        if (collected || item.isNone()) {
            return null;
        }
        count--;
        if (count <= 0) {
            count = 0;
            collected = true;
        }
        return item;
    }

    public Item getItem() {
        return item;
    }

    public boolean isStandaloneItem() {
        return !item.isNone() && !item.isBlock();
    }

    public Block getBlock() {
        return item.getBlock();
    }

    public Block getBlockType() {
        return item.getBlock();
    }

    private static Mesh getOrCreateMesh(Block type) {
        return SHARED_MESHES.computeIfAbsent(type, t -> {
            if (t.getGeometryType() == Block.GeometryType.CROSS_PLANT) {
                return createPlantMesh(t);
            }
            float[] topUV = t.getFaceUV(Block.Face.TOP);
            float[] botUV = t.getFaceUV(Block.Face.BOTTOM);
            float[] sideUV = t.getFaceUV(Block.Face.NORTH);

            float[] vertices = createCubeVertices(topUV, botUV, sideUV);

            // Giữ mặt cắt của cactus và chiều cao mặc định của một lớp tuyết.
            Block.Bounds shape = t.getSelectionBounds(0);
            if (shape != null && shape != Block.FULL_BOUNDS) {
                for (int i = 0; i < vertices.length; i += 6) {
                    vertices[i] *= shape.maxX() - shape.minX();
                    vertices[i + 1] = (vertices[i + 1] + 0.5f) * (shape.maxY() - shape.minY()) - 0.5f;
                    vertices[i + 2] *= shape.maxZ() - shape.minZ();
                }
            }
            Mesh mesh = new Mesh(true, 36, 0, VERTEX_ATTRIBUTES);
            mesh.setVertices(vertices);
            return mesh;
        });
    }

    /** Dựng lưới dùng chung cho vật phẩm độc lập (khối lập phương mini với len, mặt phẳng 2 mặt với item 2D). */
    private static Mesh getOrCreateItemMesh(Item standaloneItem) {
        return SHARED_ITEM_MESHES.computeIfAbsent(standaloneItem, t -> {
            float[] uv = t.getTileUV();
            if (t.isCubeItem()) {
                float[] vertices = createCubeVertices(uv, uv, uv);
                Mesh mesh = new Mesh(true, 36, 0, VERTEX_ATTRIBUTES);
                mesh.setVertices(vertices);
                return mesh;
            }
            // Vật phẩm phẳng: hai mặt trước sau để nhìn rõ ở mọi góc xoay
            float[] vertices = new float[12 * 6];
            int idx = putFace(vertices, 0,
                    -0.5f, -0.5f, 0.0f, uv[0], uv[3],
                     0.5f, -0.5f, 0.0f, uv[2], uv[3],
                     0.5f,  0.5f, 0.0f, uv[2], uv[1],
                    -0.5f,  0.5f, 0.0f, uv[0], uv[1], 0.95f);
            putFace(vertices, idx,
                     0.5f, -0.5f, 0.0f, uv[0], uv[3],
                    -0.5f, -0.5f, 0.0f, uv[2], uv[3],
                    -0.5f,  0.5f, 0.0f, uv[2], uv[1],
                     0.5f,  0.5f, 0.0f, uv[0], uv[1], 0.85f);
            Mesh mesh = new Mesh(true, 12, 0, VERTEX_ATTRIBUTES);
            mesh.setVertices(vertices);
            return mesh;
        });
    }

    private static float[] createCubeVertices(float[] topUV, float[] botUV, float[] sideUV) {
        float[] vertices = new float[216];
        int idx = 0;

        // 1. Mặt Trên (+Y)
        idx = putFace(vertices, idx,
                -0.5f,  0.5f,  0.5f, topUV[0], topUV[3],
                 0.5f,  0.5f,  0.5f, topUV[2], topUV[3],
                 0.5f,  0.5f, -0.5f, topUV[2], topUV[1],
                -0.5f,  0.5f, -0.5f, topUV[0], topUV[1], 1.0f);

        // 2. Mặt Dưới (-Y)
        idx = putFace(vertices, idx,
                -0.5f, -0.5f, -0.5f, botUV[0], botUV[3],
                 0.5f, -0.5f, -0.5f, botUV[2], botUV[3],
                 0.5f, -0.5f,  0.5f, botUV[2], botUV[1],
                -0.5f, -0.5f,  0.5f, botUV[0], botUV[1], 0.55f);

        // 3. Mặt Trước (+Z)
        idx = putFace(vertices, idx,
                -0.5f, -0.5f,  0.5f, sideUV[0], sideUV[3],
                 0.5f, -0.5f,  0.5f, sideUV[2], sideUV[3],
                 0.5f,  0.5f,  0.5f, sideUV[2], sideUV[1],
                -0.5f,  0.5f,  0.5f, sideUV[0], sideUV[1], 0.85f);

        // 4. Mặt Sau (-Z)
        idx = putFace(vertices, idx,
                 0.5f, -0.5f, -0.5f, sideUV[0], sideUV[3],
                -0.5f, -0.5f, -0.5f, sideUV[2], sideUV[3],
                -0.5f,  0.5f, -0.5f, sideUV[2], sideUV[1],
                 0.5f,  0.5f, -0.5f, sideUV[0], sideUV[1], 0.85f);

        // 5. Mặt Phải (+X)
        idx = putFace(vertices, idx,
                 0.5f, -0.5f,  0.5f, sideUV[0], sideUV[3],
                 0.5f, -0.5f, -0.5f, sideUV[2], sideUV[3],
                 0.5f,  0.5f, -0.5f, sideUV[2], sideUV[1],
                 0.5f,  0.5f,  0.5f, sideUV[0], sideUV[1], 0.72f);

        // 6. Mặt Trái (-X)
        putFace(vertices, idx,
                -0.5f, -0.5f, -0.5f, sideUV[0], sideUV[3],
                -0.5f, -0.5f,  0.5f, sideUV[2], sideUV[3],
                -0.5f,  0.5f,  0.5f, sideUV[2], sideUV[1],
                -0.5f,  0.5f, -0.5f, sideUV[0], sideUV[1], 0.72f);

        return vertices;
    }

    /** Dựng hai mặt chéo với mặt trước và mặt sau để cây hiện ở mọi góc xoay. */
    private static Mesh createPlantMesh(Block block) {
        float[] uv = block.getFaceUV(Block.Face.NORTH);
        float[] vertices = new float[24 * 6];
        int offset = plantPlane(vertices, 0, -0.35f, -0.35f, 0.35f, 0.35f, uv);
        offset = plantPlane(vertices, offset, 0.35f, 0.35f, -0.35f, -0.35f, uv);
        offset = plantPlane(vertices, offset, -0.35f, 0.35f, 0.35f, -0.35f, uv);
        plantPlane(vertices, offset, 0.35f, -0.35f, -0.35f, 0.35f, uv);
        Mesh mesh = new Mesh(true, 24, 0, VERTEX_ATTRIBUTES);
        mesh.setVertices(vertices);
        return mesh;
    }

    /** Ghi hai tam giác của một phía mặt phẳng thẳng đứng. */
    private static int plantPlane(float[] vertices, int offset, float x1, float z1, float x2, float z2, float[] uv) {
        return putFace(vertices, offset, x1, -0.5f, z1, uv[0], uv[3], x2, -0.5f, z2, uv[2], uv[3],
                x2, 0.5f, z2, uv[2], uv[1], x1, 0.5f, z1, uv[0], uv[1], 1.0f);
    }

    private static int putFace(
            float[] arr, int offset,
            float x1, float y1, float z1, float u1, float v1,
            float x2, float y2, float z2, float u2, float v2,
            float x3, float y3, float z3, float u3, float v3,
            float x4, float y4, float z4, float u4, float v4,
            float shade
    ) {
        offset = putVert(arr, offset, x1, y1, z1, u1, v1, shade);
        offset = putVert(arr, offset, x2, y2, z2, u2, v2, shade);
        offset = putVert(arr, offset, x3, y3, z3, u3, v3, shade);

        offset = putVert(arr, offset, x1, y1, z1, u1, v1, shade);
        offset = putVert(arr, offset, x3, y3, z3, u3, v3, shade);
        offset = putVert(arr, offset, x4, y4, z4, u4, v4, shade);
        return offset;
    }

    private static int putVert(float[] arr, int offset, float x, float y, float z, float u, float v, float shade) {
        arr[offset++] = x;
        arr[offset++] = y;
        arr[offset++] = z;
        arr[offset++] = u;
        arr[offset++] = v;
        arr[offset++] = shade;
        return offset;
    }

    /**
     * Giải phóng toàn bộ các Mesh dùng chung của ItemEntity khi đóng game.
     */
    public static void cleanupSharedMeshes() {
        for (Mesh mesh : SHARED_MESHES.values()) {
            if (mesh != null) {
                mesh.dispose();
            }
        }
        SHARED_MESHES.clear();
        for (Mesh mesh : SHARED_ITEM_MESHES.values()) {
            if (mesh != null) {
                mesh.dispose();
            }
        }
        SHARED_ITEM_MESHES.clear();
    }
}

package com.voxelgame.world.entity;

import com.voxelgame.world.effect.StatusEffectInstance;
import com.voxelgame.world.effect.StatusEffectType;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.Vector3;

/** Thực thể vật lý có máu, hiệu ứng trạng thái và vòng đời chiến đấu. */
public abstract class LivingEntity extends Entity {
    /** Thời gian bảo vệ sau sát thương và thời gian hiển thị phản hồi bị đánh. */
    private static final float HURT_SECONDS = 0.5f;
    /** Thời gian giữ lại thực thể chết cho hoạt ảnh. */
    private static final float DEATH_SECONDS = 1.0f;
    /** Chu kỳ mất một HP vì trúng độc hoặc đang cháy. */
    private static final float POISON_INTERVAL = 1.25f;
    private static final float FIRE_INTERVAL = 1.0f;
    /** Sai số nhỏ để nhịp tích lũy theo frame chạm đúng mốc. */
    private static final float TIMER_EPSILON = 0.000001f;
    /** Dùng chung mảng rỗng cho thực thể không có ghế. */
    private static final LivingEntity[] NO_PASSENGERS = new LivingEntity[0];

    protected float maxHealth;
    protected final float armor;
    protected final boolean undead;
    private float health;
    private float invulnerabilityTimer;
    private float hurtFlashTimer;
    private float fireTimer;
    private float fireElapsed;
    private float poisonElapsed;
    private float fallStartY;
    private float fallDistance;
    private boolean dead;
    private float deathTimer;
    private final StatusEffectInstance[] effects = new StatusEffectInstance[StatusEffectType.COUNT];
    private LivingEntity mount;
    /** Chỉ số ghế trong thú đang cưỡi, hoặc -1 khi đứng độc lập. */
    private int mountedSeat = -1;
    private final LivingEntity[] passengers;

    /** Khởi tạo thực thể không có ghế ngồi. */
    protected LivingEntity(float x, float y, float z, float halfWidth, float height,
                           float maxHealth, float armor, boolean undead) {
        this(x, y, z, halfWidth, height, maxHealth, armor, undead, 0);
    }

    /** Khởi tạo chỉ số và cấp phát trước số ghế cùng các khe hiệu ứng. */
    protected LivingEntity(float x, float y, float z, float halfWidth, float height,
                           float maxHealth, float armor, boolean undead, int seatCount) {
        super(x, y, z, halfWidth, height);
        this.maxHealth = maxHealth;
        this.health = maxHealth;
        this.armor = armor;
        this.undead = undead;
        passengers = seatCount == 0 ? NO_PASSENGERS : new LivingEntity[seatCount];
        for (int i = 0; i < effects.length; i++) {
            effects[i] = new StatusEffectInstance();
        }
        resetFallTracking();
    }

    /** Cập nhật hồi chiêu, chuyển động và tác động môi trường theo thứ tự. */
    @Override
    public final void update(World world, float deltaTime) {
        if (world == null || !(deltaTime > 0f) || !Float.isFinite(deltaTime)) {
            return;
        }
        if (dead) {
            deathTimer = Math.max(0f, deathTimer - deltaTime);
            finishLivingUpdate(world);
            return;
        }

        invulnerabilityTimer = Math.max(0f, invulnerabilityTimer - deltaTime);
        hurtFlashTimer = Math.max(0f, hurtFlashTimer - deltaTime);
        boolean ignoreFallBeforeMove = ignoresFall();
        updateLiving(world, deltaTime);
        if (!dead) {
            if (ignoreFallBeforeMove || ignoresFall()) {
                resetFallTracking();
            } else {
                updateFall(world);
            }
        }
        if (!dead) {
            updateFire(world, deltaTime);
        }
        if (!dead) {
            updateEffects(world, deltaTime);
        }
        finishLivingUpdate(world);
    }

    /** Chạy điều khiển hoặc AI và cập nhật vật lý của thực thể còn sống. */
    protected abstract void updateLiving(World world, float deltaTime);

    /** Cho phép lớp con xử lý hồi sinh sau khi đã hoàn tất lượt vật lý. */
    protected void finishLivingUpdate(World world) {
    }

    /** Áp dụng giáp, miễn sát thương, phản hồi và đẩy lùi cho một đòn hợp lệ. */
    public boolean damage(World world, float amount, DamageSource source, Entity attacker,
                          float knockbackX, float knockbackZ) {
        if (dead || invulnerabilityTimer > TIMER_EPSILON || !(amount > 0f) || !Float.isFinite(amount)) {
            return false;
        }
        if (((source == DamageSource.FIRE || source == DamageSource.LAVA || source == DamageSource.SUNLIGHT)
                && isImmuneToFire())
                || source == DamageSource.DROWNING && hasEffect(StatusEffectType.WATER_BREATHING)) {
            return false;
        }
        if (source.armorApplies() && armor > 0f) {
            float effectiveArmor = Math.min(20f, Math.max(armor * 0.2f, armor - amount * 0.5f));
            amount *= 1f - effectiveArmor / 25f;
        }
        health = Math.max(0f, health - amount);
        invulnerabilityTimer = HURT_SECONDS;
        hurtFlashTimer = HURT_SECONDS;
        applyKnockback(knockbackX, knockbackZ);
        if (health <= 0f) {
            endLife(DEATH_SECONDS);
        }
        if (world != null && attacker != null) {
            world.playEntityHitSound(position.x, position.y, position.z);
        }
        return true;
    }

    /** Quyết định né đạn trước khi áp sát thương, mặc định mọi thực thể có thể bị đánh trúng. */
    public boolean dodgeProjectile(World world, Entity owner) {
        return false;
    }

    /** Kết thúc vòng đời ngay khi đã nổ hoặc được thay bằng một thực thể khác. */
    public final void discard() {
        endLife(0f);
    }

    /** Xóa các liên kết cưỡi theo cả hai hướng khi cá thể rời vòng đời. */
    private void endLife(float linger) {
        health = 0f;
        dead = true;
        deathTimer = linger;
        leaveMount();
        for (int seat = 0; seat < passengers.length; seat++) {
            if (passengers[seat] != null) {
                passengers[seat].leaveMount();
            }
        }
    }

    /** Thêm xung lực ngang, có thể ghi đè nếu điều khiển đặt lại vận tốc mỗi frame. */
    protected void applyKnockback(float x, float z) {
        velocity.x += x;
        velocity.z += z;
    }

    /** Phục hồi HP của thực thể còn sống, giới hạn theo máu tối đa. */
    public void heal(float amount) {
        if (!dead && amount > 0f && Float.isFinite(amount)) {
            health = Math.min(maxHealth, health + amount);
        }
    }

    /** Thay hiệu ứng hiện tại khi hiệu ứng mới mạnh hơn hoặc kéo dài hơn. */
    public boolean applyEffect(StatusEffectType type, int amplifier, float durationSeconds) {
        if (dead || amplifier < 0 || !(durationSeconds > 0f) || !Float.isFinite(durationSeconds)
                || isImmuneTo(type)) {
            return false;
        }
        StatusEffectInstance effect = effects[type.ordinal()];
        boolean active = effect.duration() > 0f;
        if (active && amplifier <= effect.amplifier() && durationSeconds <= effect.duration()) {
            return false;
        }
        effect.set(amplifier, durationSeconds);
        if (type == StatusEffectType.POISON && !active) {
            poisonElapsed = 0f;
        } else if (type == StatusEffectType.FIRE_RESISTANCE) {
            extinguish();
        }
        return true;
    }

    /** Trả trạng thái còn hiệu lực ở thời điểm truy vấn. */
    public boolean hasEffect(StatusEffectType type) {
        return effects[type.ordinal()].duration() > 0f;
    }

    /** Trả thời lượng còn lại cho HUD và AI. */
    public float getEffectDuration(StatusEffectType type) {
        return effects[type.ordinal()].duration();
    }

    /** Xóa toàn bộ hiệu ứng trạng thái hiện có (ví dụ khi uống Milk Bucket). */
    public void clearStatusEffects() {
        for (int i = 0; i < effects.length; i++) {
            effects[i].set(0, 0f);
        }
        poisonElapsed = 0f;
    }

    /** Thực thể có miễn nhiễm sát thương Lửa, Dung nham và Ánh nắng hay không. */
    public boolean isImmuneToFire() {
        return hasEffect(StatusEffectType.FIRE_RESISTANCE);
    }

    /** Thực thể undead miễn nhiễm độc. */
    public boolean isImmuneTo(StatusEffectType type) {
        return undead && type == StatusEffectType.POISON;
    }

    /** Tính hệ số vận tốc ngang, giới hạn ở 0 khi hiệu ứng quá mạnh. */
    public float getMovementSpeedMultiplier() {
        StatusEffectInstance slow = effects[StatusEffectType.SLOWNESS.ordinal()];
        StatusEffectInstance speed = effects[StatusEffectType.SWIFTNESS.ordinal()];
        float slowMultiplier = slow.duration() > 0f ? Math.max(0f, 1f - 0.15f * (slow.amplifier() + 1f)) : 1f;
        float speedMultiplier = speed.duration() > 0f ? 1f + 0.20f * (speed.amplifier() + 1f) : 1f;
        return slowMultiplier * speedMultiplier;
    }

    /** Trừ 4 HP sát thương cận chiến mỗi cấp Weakness; đòn ở mức 0 không gây sát thương. */
    public float getMeleeDamage(float baseDamage) {
        StatusEffectInstance weakness = effects[StatusEffectType.WEAKNESS.ordinal()];
        float penalty = weakness.duration() > 0f ? 4f * (weakness.amplifier() + 1f) : 0f;
        return Math.max(0f, baseDamage - penalty);
    }

    /** Giảm thời lượng hiệu ứng và xử lý các nhịp độc không gây chết. */
    private void updateEffects(World world, float deltaTime) {
        for (int i = 0; i < effects.length; i++) {
            StatusEffectInstance effect = effects[i];
            if (effect.duration() <= 0f) {
                continue;
            }
            float activeTime = effect.advance(deltaTime);
            if (i == StatusEffectType.POISON.ordinal()) {
                poisonElapsed += activeTime;
                while (poisonElapsed + TIMER_EPSILON >= POISON_INTERVAL) {
                    poisonElapsed = Math.max(0f, poisonElapsed - POISON_INTERVAL);
                    damage(world, Math.min(1f, health - 1f), DamageSource.POTION_MAGIC, null, 0f, 0f);
                }
            } else if (i == StatusEffectType.HUNGER.ordinal()) {
                onHungerEffect(effect.amplifier(), activeTime);
            }
        }
    }

    /** Cho phép thực thể có thanh đói xử lý thời gian bị Hunger. */
    protected void onHungerEffect(int amplifier, float activeTime) {
    }

    /** Bắt đầu hoặc nối dài thời gian cháy mà giữ nhịp sát thương hiện tại. */
    public void ignite(float durationSeconds) {
        if (!dead && durationSeconds > fireTimer && Float.isFinite(durationSeconds)
                && !isImmuneToFire()) {
            fireTimer = durationSeconds;
        }
    }

    /** Trả số giây cháy còn lại. */
    public float getFireTimer() {
        return fireTimer;
    }

    /** Dập lửa khi chạm nước hoặc mưa, nếu không thì xử lý 1 HP mỗi giây cháy. */
    private void updateFire(World world, float deltaTime) {
        if (fireTimer <= 0f) {
            return;
        }
        if (touchesLiquid(world, Block.WATER) || world.isRainingAt(position.x, position.y + height, position.z)) {
            extinguish();
            return;
        }
        float activeTime = Math.min(fireTimer, deltaTime);
        fireTimer -= activeTime;
        fireElapsed += activeTime;
        while (!dead && fireElapsed + TIMER_EPSILON >= FIRE_INTERVAL) {
            fireElapsed = Math.max(0f, fireElapsed - FIRE_INTERVAL);
            damage(world, 1f, DamageSource.FIRE, null, 0f, 0f);
        }
        if (fireTimer <= 0f) {
            extinguish();
        }
    }

    /** Xóa cả thời gian cháy lẫn phần lẻ của nhịp sát thương. */
    protected final void extinguish() {
        fireTimer = 0f;
        fireElapsed = 0f;
    }

    /** Thử các ô chất lỏng giao với hộp thân thể, loại biên chỉ vừa chạm mặt ô. */
    protected final boolean touchesLiquid(World world, Block liquid) {
        int minX = (int) Math.floor(position.x - halfWidth + CONTACT_EPSILON);
        int maxX = (int) Math.floor(position.x + halfWidth - CONTACT_EPSILON);
        int minY = (int) Math.floor(position.y + CONTACT_EPSILON);
        int maxY = (int) Math.floor(position.y + height - CONTACT_EPSILON);
        int minZ = (int) Math.floor(position.z - halfWidth + CONTACT_EPSILON);
        int maxZ = (int) Math.floor(position.z + halfWidth - CONTACT_EPSILON);
        for (int x = minX; x <= maxX; x++) {
            for (int y = minY; y <= maxY; y++) {
                for (int z = minZ; z <= maxZ; z++) {
                    if (world.getBlock(x, y, z) == liquid.getId()) {
                        if (world.getBlock(x, y + 1, z) != Block.AIR.getId() || position.y < y + 0.88f) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /** Theo dõi đỉnh quỹ đạo và chỉ tính sát thương khi tiếp đất ngoài nước. */
    protected final void updateFall(World world) {
        fallStartY = Math.max(fallStartY, position.y);
        fallDistance = fallStartY - position.y;
        if (fallDistance > 0f && touchesLiquid(world, Block.WATER)) {
            resetFallTracking();
        } else if (onGround) {
            damage(world, fallDistance - 3f - getFallReduction(), DamageSource.FALL, null, 0f, 0f);
            resetFallTracking();
        }
    }

    /** Cho phép bỏ theo dõi rơi khi đang cưỡi hoặc có khả năng bay. */
    protected boolean ignoresFall() {
        return mount != null;
    }

    /** Trả số block an toàn cộng thêm cho thực thể có khả năng giảm sát thương rơi. */
    protected float getFallReduction() {
        return 0f;
    }

    /** Bắt đầu lại quãng rơi tại tọa độ chân hiện tại. */
    protected final void resetFallTracking() {
        fallStartY = position.y;
        fallDistance = 0f;
    }

    /** Đặt tọa độ từ bên ngoài mà không tính dịch chuyển như một cú rơi. */
    @Override
    public void setPosition(float x, float y, float z) {
        super.setPosition(x, y, z);
        resetFallTracking();
    }

    /** Trả quãng rơi tích lũy hiện tại theo trục Y (block). */
    public float getFallDistance() {
        return fallDistance;
    }

    /** Xóa toàn bộ vận tốc hiện tại của thực thể (dùng khi dịch chuyển tức thời). */
    public void stopMotion() {
        velocity.setZero();
    }

    /** Đặt lại sinh tồn khi tái sinh. */
    protected final void restoreLife() {
        health = maxHealth;
        invulnerabilityTimer = 0f;
        hurtFlashTimer = 0f;
        dead = false;
        deathTimer = 0f;
        extinguish();
        poisonElapsed = 0f;
        for (int i = 0; i < effects.length; i++) {
            effects[i].set(0, 0f);
        }
        resetFallTracking();
    }

    /** Trả HP hiện tại. */
    public float getHealth() {
        return health;
    }

    /** Trả HP tối đa. */
    public float getMaxHealth() {
        return maxHealth;
    }

    /**
     * Cập nhật máu tối đa cho thực thể (ví dụ {@code Wolf} khi được thuần hóa tăng từ 8 lên 20 HP).
     *
     * @param newMaxHealth máu tối đa mới (phải dương và hữu hạn)
     * @param healToMax    {@code true} nếu hồi đầy HP lên mức tối đa mới ngay lập tức
     */
    protected final void setMaxHealth(float newMaxHealth, boolean healToMax) {
        if (Float.isFinite(newMaxHealth) && newMaxHealth > 0f) {
            this.maxHealth = newMaxHealth;
            if (healToMax && !dead) {
                this.health = newMaxHealth;
            } else {
                this.health = Math.min(this.health, newMaxHealth);
            }
        }
    }

    /** Trả lượng giáp tự nhiên. */
    public float getArmor() {
        return armor;
    }

    /** Trả tộc undead để AI và hiệu ứng nhận diện. */
    public boolean isUndead() {
        return undead;
    }

    /** Thời gian nháy khi bị thương còn lại, tính bằng giây. */
    public float getHurtFlashTimer() {
        return hurtFlashTimer;
    }

    /** Thời gian còn lại cho hoạt ảnh chết. */
    public float getDeathTimer() {
        return deathTimer;
    }

    /** Xác định thực thể còn có thể hành động và được chọn làm mục tiêu. */
    public boolean isAlive() {
        return !dead;
    }

    /** Xác định khi nào World có thể bỏ thực thể khỏi danh sách. */
    public boolean isReadyToRemove() {
        return dead && deathTimer <= TIMER_EPSILON;
    }

    /** Trả thú đang cưỡi, nếu có. */
    public final LivingEntity getMount() {
        return mount;
    }

    /** Đọc ghế hiện tại để đồng bộ người cưỡi với đúng khớp. */
    public final int getMountedSeat() {
        return mountedSeat;
    }

    /** Chép vị trí chân ghế mặc định ở đỉnh hộp va chạm, dùng cho kỵ sĩ nhện. */
    public Vector3 copySeatPosition(int seat, Vector3 out) {
        return out.set(position.x, position.y + height, position.z);
    }

    /** Trả hành khách của ghế được chỉ định. */
    public final LivingEntity getPassenger(int seat) {
        return passengers[seat];
    }

    /** Trả số ghế vật lý của thực thể. */
    public final int getSeatCount() {
        return passengers.length;
    }

    /** Đặt một người cưỡi vào ghế trống và tránh tạo chu trình cưỡi. */
    public final boolean tryMount(LivingEntity vehicle, int seat) {
        if (vehicle == null || mount != null || dead || vehicle.dead
                || seat < 0 || seat >= vehicle.passengers.length || vehicle.passengers[seat] != null) {
            return false;
        }
        for (LivingEntity current = vehicle; current != null; current = current.mount) {
            if (current == this) {
                return false;
            }
        }
        mount = vehicle;
        mountedSeat = seat;
        vehicle.passengers[seat] = this;
        resetFallTracking();
        return true;
    }

    /** Gỡ liên kết ghế hai chiều và bắt đầu theo dõi rơi tại vị trí mới. */
    public final void leaveMount() {
        if (mount == null) {
            return;
        }
        mount.passengers[mountedSeat] = null;
        mount = null;
        mountedSeat = -1;
        resetFallTracking();
    }

    /** Cho phép lớp con tiêu thụ thao tác chuột phải trước khi đặt block. */
    public boolean onPlayerInteract(World world, Player player) {
        return false;
    }
}

package com.voxelgame.world.entity.mob;

import java.util.random.RandomGenerator;

/**
 * Lớp trừu tượng đại diện cho nhóm thú cưỡi họ ngựa (tương đương {@code AbstractHorse} trong Minecraft),
 * gom chung cấu hình một ghế ngồi, bước lên bậc 1 block và phân bố máu ngẫu nhiên 15–30 HP.
 * {@link com.voxelgame.world.entity.mob.animal.Horse} và
 * {@link com.voxelgame.world.entity.mob.animal.Donkey} kế thừa ngang hàng từ lớp này để giữ đúng
 * nguyên lý thay thế Liskov (LSP).
 */
public abstract class EquineMob extends MountableMob {
    /** Số ghế đơn và chiều cao bước trực tiếp chuẩn của họ ngựa. */
    private static final int EQUINE_SEAT_COUNT = 1;
    private static final float EQUINE_STEP_HEIGHT = 1f;

    /**
     * Khởi tạo cá thể họ ngựa hoang dã với một ghế ngồi và chỉ số tốc độ/nhảy/máu riêng.
     *
     * @param type       loại mob ({@link MobType#HORSE} hoặc {@link MobType#DONKEY})
     * @param x          tọa độ X ban đầu
     * @param y          tọa độ Y ban đầu
     * @param z          tọa độ Z ban đầu
     * @param moveSpeed  tốc độ di chuyển cơ sở (block/giây)
     * @param jumpHeight chiều cao nhảy tối đa (block)
     * @param maxHealth  máu tối đa của cá thể (15–30 HP)
     */
    protected EquineMob(MobType type, float x, float y, float z,
                        float moveSpeed, float jumpHeight, float maxHealth) {
        super(type, x, y, z, EQUINE_SEAT_COUNT, EQUINE_STEP_HEIGHT, moveSpeed, jumpHeight, false, true, maxHealth);
    }

    /** Chọn máu nguyên từ 15 đến 30 với xác suất tập trung cao hơn quanh giá trị trung tâm. */
    protected static int randomHealth(RandomGenerator random) {
        return 15 + random.nextInt(8) + random.nextInt(9);
    }
}

