package com.voxelgame.world.entity.mob;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.client.render.entity.MobVisual;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.client.render.ShaderProgram;
import com.voxelgame.core.Interactable;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.ai.MobGoalSelector;
import com.voxelgame.world.entity.mob.ai.SimpleGridNavigator;
import com.voxelgame.world.entity.player.Hotbar;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.MathUtils;
import java.util.concurrent.ThreadLocalRandom;

/** Nền tảng trừu tượng quản lý vật lý, hoạt ảnh và AI goal dùng chung cho mọi loài mob sống. */
public abstract class MobEntity extends LivingEntity implements MobVisual {
    /** Gia tốc theo block/giây² và giới hạn vận tốc rơi theo từng môi trường. */
    private static final float GRAVITY = -26f;
    private static final float MAX_FALL_SPEED = -40f;
    private static final float WATER_GRAVITY = GRAVITY * 0.25f;
    private static final float WATER_FALL_SPEED = -2.8f;
    private static final float FLOAT_SPEED = 2.5f;
    /** Nhảy qua bậc một block và hỗ trợ bậc cao hơn bằng bước trực tiếp. */
    private static final float JUMP_SPEED = 8.6f;
    private static final float MAX_JUMP_STEP = 1f;
    /** Khoảng rơi an toàn mặc định và ngưỡng cho hai loài nhẹ chân. */
    private static final float NORMAL_SAFE_FALL = 3f;
    private static final float LONG_SAFE_FALL = 8f;
    /** Khoảng thời gian phản ứng và khoảng cách giữa hai tiếng chân. */
    private static final float NEUTRAL_ANGER_SECONDS = 15f;
    private static final float STEP_SOUND_SPACING = 0.9f;
    /** Tỷ lệ hitbox, tỷ lệ hiển thị và cao độ âm thanh cho cá thể non. */
    private static final float BABY_DIMENSIONS_SCALE = 0.5f;
    private static final float BABY_SCALE = 0.6f;
    private static final float BABY_PITCH = 1.5f;

    /** Cấu hình loài, trạng thái kết xuất, bộ điều hướng và goal cấp phát một lần. */
    private final MobType type;
    private final MobGoalSelector goals = new MobGoalSelector();
    private final SimpleGridNavigator navigator = new SimpleGridNavigator(this);
    private final MobVisualState visual;

    /** Sinh trưởng, lưu giữ cá thể, cấu hình chuyển động và trạng thái trong nước. */
    private boolean baby;
    private boolean persistent;
    private boolean autoFloat = true;
    private boolean canFloat = true;
    private boolean inWater;
    private boolean directStep;
    private float stepHeight = MAX_JUMP_STEP;
    private float maxSafeFall;
    private float moveSpeed;
    private float noActionTime;

    /** Đích sống, tác nhân gây đòn gần nhất và các bộ đếm phản ứng. */
    private LivingEntity target;
    private Entity lastAttacker;
    private int hurtSequence;
    private float angerTimer;
    private float panicTime;
    private boolean stoppedAfterDeath;
    private boolean lootDropped;

    /** Điều khiển ngắn hạn dùng giữa lượt goal và lượt quét vật lý. */
    private float wishX;
    private float wishZ;
    private float pushX;
    private float pushZ;
    private boolean requestJump;
    private boolean requestFloat;
    /** Lệnh bám tường và đà ngang cho cú vồ trong thời gian đang bay. */
    private boolean wallClimbRequested;
    private boolean climbing;
    private float leapRemaining;
    private float leapX;
    private float leapZ;
    private boolean lookRequested;
    private boolean faceRequested;
    private float faceX;
    private float faceZ;
    private float lookX;
    private float lookY;
    private float lookZ;

    /** Pha hoạt ảnh, hướng thân và đầu, quãng đường phát bước và nhịp tiếng chờ. */
    private float bodyYaw;
    private float headYaw;
    private float headPitch;
    private float limbSwing;
    private float limbSwingAmount;
    private double ageSeconds;
    private float stepSoundDistance;
    private float idleSoundTimer;

    /** Khởi tạo cá thể với hộp va chạm và chỉ số chung từ danh mục loài. */
    public MobEntity(MobType type, float x, float y, float z) {
        this(type, x, y, z, 0);
    }

    /** Khởi tạo mẫu cưỡi có số ghế đúng với lớp chuyên biệt. */
    protected MobEntity(MobType type, float x, float y, float z, int seatCount) {
        this(type, x, y, z, 0f, seatCount);
    }

    /** Cho phép lớp chuyên biệt thêm giáp tự nhiên và ghế, dùng nguyên vòng đời của LivingEntity. */
    protected MobEntity(MobType type, float x, float y, float z, float armor, int seatCount) {
        this(type, x, y, z, armor, seatCount, true);
    }

    /** Cho phép lớp chuyên biệt thay toàn bộ danh sách goal ngay lúc khởi tạo. */
    protected MobEntity(MobType type, float x, float y, float z, float armor, int seatCount,
                        boolean installDefaultGoals) {
        this(type, x, y, z, armor, seatCount, installDefaultGoals, 1f);
    }

    /** Dùng đúng kích thước thể chất ngay khi tạo cá thể non hoặc biến thể thu nhỏ. */
    protected MobEntity(MobType type, float x, float y, float z, float armor, int seatCount,
                        boolean installDefaultGoals, float dimensionsScale) {
        this(type, x, y, z, armor, seatCount, installDefaultGoals, dimensionsScale, type.health());
    }

    /** Tạo cá thể với chỉ số máu đã bốc và cùng quy tắc vật lý của loài. */
    protected MobEntity(MobType type, float x, float y, float z, float armor, int seatCount,
                        boolean installDefaultGoals, float dimensionsScale, float maxHealth) {
        super(x, y, z, type.width() * 0.5f * dimensionsScale, type.height() * dimensionsScale,
                maxHealth, armor, type.undead(), seatCount);
        this.type = type;
        visual = new MobVisualState(type.appearance());
        persistent = type.category() == MobCategory.CREATURE;
        maxSafeFall = type == MobType.CHICKEN || type == MobType.GOAT ? LONG_SAFE_FALL : NORMAL_SAFE_FALL;
        moveSpeed = type.attitude() == MobAttitude.HOSTILE ? 3f : 2.45f;
        idleSoundTimer = ThreadLocalRandom.current().nextFloat(2.5f, 5f);
        if (installDefaultGoals) {
            MobGoals.addDefaults(goals, type);
        }
    }

    /** Cập nhật AI, vật lý theo X → Z → Y và thông tin hoạt ảnh đã cấp phát. */
    @Override
    protected void updateLiving(World world, float dt) {
        ageSeconds += dt;
        updateReactionTimers(dt);
        inWater = touchesLiquid(world, Block.WATER);
        if (!persistent && hasPlayerPassenger()) {
            persistent = true;
        }
        LivingEntity mount = getMount();
        if (mount != null) {
            mount.copySeatPosition(getMountedSeat(), position);
            velocity.setZero();
            onGround = false;
            stopMoving();
            goals.stopAll(world, this);
            updateMounted(world, dt);
            updateAnimation(0f, 0f, dt);
        } else {
            updateGoals(world, dt);
            if (!isAlive()) {
                return;
            }
            float oldX = position.x;
            float oldZ = position.z;
            move(world, dt);
            updateAnimation(position.x - oldX, position.z - oldZ, dt);
        }
        wishX = 0f;
        wishZ = 0f;
        requestJump = false;
        requestFloat = false;
        wallClimbRequested = false;
        lookRequested = false;
        faceRequested = false;
        inWater = touchesLiquid(world, Block.WATER);
        if (burnsInSunlight() && isSunExposed(world)) {
            ignite(2f);
        }
        updateIdleSound(world, dt);
    }

    /** Điểm mở rộng cho lớp chuyên biệt thay đổi điều khiển trước khi quét vật lý. */
    protected void updateGoals(World world, float dt) {
        goals.tick(world, this, dt);
    }

    /** Cung cấp lượt tấn công hoặc ngắm bắn riêng cho kỵ sĩ sau khi đã đồng bộ ghế. */
    protected void updateMounted(World world, float dt) {
    }

    /** Giảm thời gian hốt hoảng, xóa mục tiêu đã chết, hết giận hoặc người chơi không thể bị nhắm (Creative). */
    private void updateReactionTimers(float dt) {
        panicTime = Math.max(0f, panicTime - dt);
        if (angerTimer > 0f) {
            angerTimer = Math.max(0f, angerTimer - dt);
            if (angerTimer == 0f && attitude() == MobAttitude.NEUTRAL) {
                target = null;
            }
        }
        if (target != null && !isValidTarget(target)) {
            target = null;
        }
    }

    /** Kiểm tra mục tiêu còn sống và hợp lệ theo quy tắc chế độ chơi (bỏ qua người chơi Creative). */
    private static boolean isValidTarget(LivingEntity candidate) {
        return candidate != null && candidate.isAlive()
                && (!(candidate instanceof Player player) || player.getGameMode().isTargetableByMobs());
    }

    /** Tách vận tốc điều khiển khỏi xung lực rồi quét từng trục của hộp va chạm. */
    private void move(World world, float dt) {
        climbing = false;
        if (leapRemaining > 0f) {
            leapRemaining = Math.max(0f, leapRemaining - dt);
            wishX = leapX;
            wishZ = leapZ;
        }
        float speedScale = getMovementSpeedMultiplier() * (inWater ? waterSpeedMultiplier() : 1f);
        float blend = Math.min(1f, dt * 18f);
        velocity.x = wishX == 0f ? 0f : MathUtils.lerp(velocity.x, wishX * speedScale, blend);
        velocity.z = wishZ == 0f ? 0f : MathUtils.lerp(velocity.z, wishZ * speedScale, blend);
        if (requestJump && onGround && !inWater && navigator.canRise(world, x(), y(), z(), 0.1f)) {
            beginJump();
        }
        moveHorizontal(world, 0, velocity.x * dt, pushX * dt);
        moveHorizontal(world, 2, velocity.z * dt, pushZ * dt);
        float pushDecay = Math.max(0f, 1f - dt * 6.5f);
        pushX *= pushDecay;
        pushZ *= pushDecay;

        if (climbing && !inWater) {
            velocity.y = 3.2f;
        } else if (inWater) {
            boolean rise = canFloat() && (autoFloat || requestFloat);
            velocity.y = rise ? Math.max(velocity.y, FLOAT_SPEED)
                    : Math.max(WATER_FALL_SPEED, velocity.y + WATER_GRAVITY * dt);
        } else {
            velocity.y = Math.max(terminalFallSpeed(), velocity.y + GRAVITY * dt);
        }
        Block hit = moveAxis(world, 1, velocity.y * dt);
        onGround = hit != null && velocity.y < 0f;
        if (hit != null) {
            velocity.y = 0f;
        }
        if (onGround) {
            leapRemaining = 0f;
        }
    }

    /** Chặn lệnh đi vào hố hoặc gai rồi thử nhảy/bước khi quét gặp bậc phù hợp. */
    private void moveHorizontal(World world, int axis, float requested, float pushed) {
        boolean xAxis = axis == 0;
        float destX = x() + (xAxis ? requested : 0f);
        float destZ = z() + (xAxis ? 0f : requested);
        if (requested != 0f) {
            boolean legal = onGround && !inWater
                    ? Float.isFinite(navigator.findFeetY(world, destX, y(), destZ))
                    : navigator.avoidsHazards(world, destX, y(), destZ);
            boolean approachesWall = !legal && wallClimbRequested && navigator.avoidsHazards(world, destX, y(), destZ)
                    && !navigator.canOccupy(world, destX, y(), destZ);
            boolean entersWater = !legal && this instanceof MountableMob mount
                    && mount.canWadeInto(world, destX, destZ);
            if (!legal && !approachesWall && !entersWater) {
                requested = 0f;
            }
        }
        float start = xAxis ? x() : z();
        float distance = requested + pushed;
        Block hit = moveAxis(world, axis, distance);
        if (hit == null) {
            return;
        }
        if (requested != 0f && !inWater && climbWall(world, hit)) {
            climbing = true;
        }
        float rise = obstacleTop - y();
        float stepLimit = directStep ? stepHeight : Math.min(stepHeight, MAX_JUMP_STEP);
        if (requested != 0f && onGround && !inWater && hit != Block.CACTUS
                && rise > CONTACT_EPSILON && rise <= stepLimit + CONTACT_EPSILON
                && navigator.canRise(world, x(), y(), z(), rise)
                && navigator.canOccupy(world, destX, y() + rise, destZ)) {
            if (!directStep) {
                beginJump();
                return;
            }
            position.y += rise;
            float reached = xAxis ? x() : z();
            if (moveAxis(world, axis, start + distance - reached) == null) {
                return;
            }
        }
        if (xAxis) {
            velocity.x = 0f;
        } else {
            velocity.z = 0f;
        }
    }

    /** Bật vận tốc hướng lên sau khi kiểm tra đủ chỗ theo độ cao bậc. */
    private void beginJump() {
        velocity.y = JUMP_SPEED;
        onGround = false;
    }

    /** Nhận một cú vồ ngắn với vận tốc ngang được giữ qua nhiều khung hình. */
    protected final void queueLeap(float vx, float vy, float vz) {
        queueLeap(vx, vy, vz, 0.46f);
    }

    /** Giữ động lượng ngang đến khi hết nhịp phóng hoặc chân chạm nền. */
    protected final void queueLeap(float vx, float vy, float vz, float seconds) {
        if (onGround && !inWater && vy > 0f) {
            leapX = vx;
            leapZ = vz;
            leapRemaining = seconds;
            velocity.y = vy;
            onGround = false;
        }
    }

    /** Hướng cú lao theo tọa độ đích, vẫn qua quét va chạm và kiểm tra nguy hiểm. */
    protected final void steerDirect(float x, float z, float speed) {
        float dx = x - position.x;
        float dz = z - position.z;
        float length = (float) Math.sqrt(dx * dx + dz * dz);
        if (length > CONTACT_EPSILON) {
            steer(dx / length, dz / length, speed);
        }
    }

    /** Giới hạn vận tốc rơi trong không khí, mặc định dùng vật lý chung của mob. */
    protected float terminalFallSpeed() {
        return MAX_FALL_SPEED;
    }

    /** Hệ số tốc độ ngang trong nước, có thể tăng cho loài bơi khỏe. */
    protected float waterSpeedMultiplier() {
        return 0.67f;
    }

    /** Tiếp tục ép nhẹ vào mặt vật cản để loài biết leo có tiếp xúc ngang với tường. */
    protected final void steerTowardWall(float x, float z) {
        float dx = x - position.x;
        float dz = z - position.z;
        float length = (float) Math.sqrt(dx * dx + dz * dz);
        if (length > CONTACT_EPSILON) {
            steer(dx / length, dz / length, moveSpeed);
            wallClimbRequested = true;
        }
    }

    /** Cho phép loài biết leo xác nhận loại khối đang va chạm ở mặt bên. */
    protected boolean climbWall(World world, Block wall) {
        return false;
    }

    /** Đặt lại quãng rơi khi đang bám tường hoặc khi được thú cưỡi đỡ. */
    @Override
    protected boolean ignoresFall() {
        return climbing || super.ignoresFall();
    }

    /** Dùng chuyển động thật và đích nhìn để xoay thân, xoay đầu và điều khiển pha chân. */
    private void updateAnimation(float dx, float dz, float dt) {
        float distance = (float) Math.sqrt(dx * dx + dz * dz);
        if (faceRequested) {
            bodyYaw = moveAngle(bodyYaw, yawOf(faceX - x(), faceZ - z()), dt * 420f);
        } else if (distance > CONTACT_EPSILON) {
            float heading = yawOf(dx, dz);
            bodyYaw = moveAngle(bodyYaw, heading, dt * 420f);
        }
        float wantHeadYaw = 0f;
        float wantHeadPitch = 0f;
        if (lookRequested) {
            float toX = lookX - x();
            float toZ = lookZ - z();
            float horizontal = (float) Math.sqrt(toX * toX + toZ * toZ);
            if (horizontal > CONTACT_EPSILON) {
                wantHeadYaw = MathUtils.clamp(wrapDegrees(yawOf(toX, toZ) - bodyYaw), -75f, 75f);
            }
            wantHeadPitch = MathUtils.clamp(MathUtils.atan2(lookY - (y() + height * 0.8f), horizontal)
                    * MathUtils.radiansToDegrees, -65f, 65f);
        }
        headYaw = moveAngle(headYaw, wantHeadYaw, dt * 300f);
        headPitch = moveAngle(headPitch, wantHeadPitch, dt * 240f);
        // Mỗi tick 1/20 giây lấy 40% biên độ mới. Quy đổi theo dt để bước đều ở mọi FPS.
        float ticks = dt * 20f;
        float targetSwing = Math.min(1f, distance * 4f / ticks);
        limbSwingAmount = MathUtils.lerp(limbSwingAmount, targetSwing, 1f - (float) Math.pow(0.6, ticks));
        limbSwing = (limbSwing + limbSwingAmount * ticks * 0.6662f * (baby ? 3f : 1f)) % MathUtils.PI2;
        float ageInTicks = (float) (ageSeconds * 20d);
        visual.updateBowAim(dt);
        visual.setAnimation(bodyYaw, headYaw, headPitch, limbSwing, limbSwingAmount, ageInTicks);
        if (onGround) {
            stepSoundDistance += distance;
        }
    }

    /** Trả góc quanh trục Y cho mẫu hướng về -Z ở tư thế gốc. */
    private static float yawOf(float dx, float dz) {
        return MathUtils.atan2(-dx, -dz) * MathUtils.radiansToDegrees;
    }

    /** Xoay theo hướng ngắn nhất và chặn theo tốc độ góc. */
    private static float moveAngle(float current, float goal, float limit) {
        return wrapDegrees(current + MathUtils.clamp(wrapDegrees(goal - current), -limit, limit));
    }

    /** Quy góc về khoảng -180 đến 180 độ để nội suy qua đường cắt. */
    private static float wrapDegrees(float angle) {
        return (angle + 540f) % 360f - 180f;
    }

    /** Phát bước theo quãng đường và giọng chờ theo khoảng nghỉ ngẫu nhiên. */
    private void updateIdleSound(World world, float dt) {
        if (stepSoundDistance >= STEP_SOUND_SPACING) {
            stepSoundDistance %= STEP_SOUND_SPACING;
            playSound(world, MobSoundEvent.STEP);
        }
        idleSoundTimer -= dt;
        if (idleSoundTimer <= 0f) {
            idleSoundTimer = ThreadLocalRandom.current().nextFloat(4f, 10f);
            playSound(world, MobSoundEvent.AMBIENT);
        }
    }

    /** Kiểm tra nắng trực tiếp tại đầu mob, loại trừ nước, mái và mưa cục bộ. */
    public boolean isSunExposed(World world) {
        if (world.worldTime().sunY() <= 0.05f || touchesLiquid(world, Block.WATER)) {
            return false;
        }
        float headY = y() + height;
        return !world.hasWeatherRoof(MathUtils.floor(x()), headY, MathUtils.floor(z()))
                && !world.isRainingAt(x(), headY, z());
    }

    /** Gửi một lệnh lái theo đích thế giới cho lượt vật lý kế tiếp. */
    public void moveToward(World world, float x, float y, float z, float speedMultiplier) {
        if (!Float.isFinite(y)) {
            stopMoving();
            return;
        }
        navigator.moveToward(world, x, z, moveSpeed * speedMultiplier);
    }

    /** Đặt hướng chạy đã chuẩn hóa, duy trì xung lực bị đánh độc lập. */
    public void steer(float dx, float dz, float speed) {
        wishX = dx * speed;
        wishZ = dz * speed;
    }

    /** Hủy điều khiển ngang của goal nhưng tiếp tục xử lý động lượng đẩy lùi. */
    public void stopMoving() {
        wishX = 0f;
        wishZ = 0f;
        navigator.stop();
    }

    /** Hướng mắt về một điểm thế giới trong lượt hoạt ảnh hiện tại. */
    public void lookAt(float x, float y, float z) {
        lookX = x;
        lookY = y;
        lookZ = z;
        lookRequested = true;
    }

    /** Giữ thân hướng về đích trong khi đi ngang, lùi hoặc ngắm từ trên lưng thú. */
    public final void faceBody(float x, float z) {
        faceX = x;
        faceZ = z;
        faceRequested = Math.abs(x - position.x) + Math.abs(z - position.z) > CONTACT_EPSILON;
    }

    /** Yêu cầu nhảy trên mặt đất trong lượt vật lý tiếp theo. */
    public void requestJump() {
        requestJump = true;
    }

    /** Yêu cầu bơi lên khi một goal giữ quyền chuyển động dọc. */
    public void requestFloat() {
        requestFloat = true;
    }

    /** Cho phép điều khiển lớp con tắt lực nổi nội tại và để goal chủ động yêu cầu bơi lên. */
    protected final void setAutoFloat(boolean enabled) {
        autoFloat = enabled;
    }

    /** Điều chỉnh khả năng nổi, áp dụng cả lực tự nổi lẫn lệnh của goal. */
    public void setCanFloat(boolean allowed) {
        canFloat = allowed;
    }

    /** Kiểm tra loại mob hiện cho phép nổi trong nước hay không. */
    public boolean canFloat() {
        return canFloat;
    }

    /** Trả về mặt đỡ hợp lệ gần cao độ tham chiếu tại tâm ô. */
    public boolean canStandAt(World world, int x, int y, int z) {
        return Float.isFinite(navigator.findStandableY(world, x, y, z));
    }

    /** Ghi nhận hit thành công, tạo phản ứng hoảng/giận và phát đúng tiếng bị thương hoặc chết. */
    @Override
    public boolean damage(World world, float amount, DamageSource source, Entity attacker,
                          float knockbackX, float knockbackZ) {
        if (!super.damage(world, amount, source, attacker, knockbackX, knockbackZ)) {
            return false;
        }
        hurtSequence++;
        lastAttacker = attacker;
        if (isAlive()) {
            if (attacker != null && attacker != this && attitude() == MobAttitude.PASSIVE) {
                panicTime = ThreadLocalRandom.current().nextFloat(3f, 5f);
            }
            if (attacker instanceof LivingEntity living && living != this && living.isAlive()
                    && attitude() != MobAttitude.PASSIVE) {
                target = living;
                angerTimer = NEUTRAL_ANGER_SECONDS;
            }
            playSound(world, MobSoundEvent.HURT);
        } else {
            target = null;
            playSound(world, MobSoundEvent.DEATH);
            if (!lootDropped) {
                lootDropped = true;
                boolean onFire = getFireTimer() > 0f || source == DamageSource.FIRE || source == DamageSource.LAVA;
                MobLootTable.dropDeathLoot(world, this, onFire, attacker);
            }
        }
        return true;
    }

    /**
     * Facade điều phối tương tác chuột phải giữa người chơi và mob theo đúng 2 lượt:
     * Lượt 1 gọi đa hình {@link Item#onInteractMob(World, Player, MobEntity)} cho công cụ phổ quát
     * (như {@link com.voxelgame.world.item.FlintAndSteelItem} đốt cháy mọi mob trong 8 giây);
     * Lượt 2 ủy quyền sang {@link Interactable#onInteract(World, Player, Item)} nếu loài có triển khai.
     */
    @Override
    public boolean onPlayerInteract(World world, Player player) {
        if (!isAlive() || player == null || !player.isAlive()) {
            return false;
        }
        Hotbar hotbar = player.getHotbar();
        Item heldItem = (hotbar != null && hotbar.getSelectedCount() > 0 && hotbar.getSelectedItem() != null)
                ? hotbar.getSelectedItem() : Item.NONE;
        if (heldItem.onInteractMob(world, player, this)) {
            return true;
        }
        if (this instanceof Interactable interactable) {
            return interactable.onInteract(world, player, heldItem);
        }
        return false;
    }

    /** Gây đòn đã qua kiểm tra tầm và hồi chiêu, cho phép loài thêm hiệu ứng sau khi trúng. */
    public boolean strikeMelee(World world, LivingEntity victim, float baseDamage, float knockbackX, float knockbackZ) {
        return victim.damage(world, getMeleeDamage(baseDamage), DamageSource.MELEE, this, knockbackX, knockbackZ);
    }

    /** Nhận diện đồng loại, thú cưỡi và kỵ sĩ của cùng một đội. */
    public boolean isAlliedTo(MobEntity other) {
        LivingEntity mount = getMount();
        return other == this || type == other.type || other == mount || other.getMount() == this
                || mount != null && mount == other.getMount();
    }

    /** Ghi mục tiêu mới khi đạn lạc trúng quái ngoài đội. */
    public final void retaliateAgainst(MobEntity other) {
        if (isAlive() && other.isAlive() && !isAlliedTo(other)) {
            enrage(other, NEUTRAL_ANGER_SECONDS);
        }
    }

    /** Tạo phản ứng giận dữ có thời hạn cho một đòn đánh hoặc kích thích riêng của loài. */
    protected final void enrage(LivingEntity victim, float seconds) {
        if (victim != this && isValidTarget(victim)) {
            target = victim;
            angerTimer = Math.max(angerTimer, seconds);
        }
    }

    /** Dừng các goal đúng một lần khi đã vào vòng đời chết. */
    @Override
    protected void finishLivingUpdate(World world) {
        if (!isAlive() && !stoppedAfterDeath) {
            goals.stopAll(world, this);
            stopMoving();
            stoppedAfterDeath = true;
        }
    }

    /** Giữ đẩy lùi riêng để lệnh AI kế tiếp không xóa xung lực, đồng thời bật nảy khi đứng trên mặt đất. */
    @Override
    protected void applyKnockback(float x, float z) {
        pushX += x;
        pushZ += z;
        if (onGround && !inWater && (x * x + z * z) > 0.0001f) {
            velocity.y = Math.max(velocity.y, 4.8f);
            onGround = false;
        }
    }

    /** Loài có giới hạn rơi lớn hơn cũng giảm sát thương theo phần ngưỡng được tăng. */
    @Override
    protected float getFallReduction() {
        return Math.max(0f, maxSafeFall - NORMAL_SAFE_FALL);
    }

    /** Phát sự kiện của loài theo vị trí và cao độ cá thể qua bộ âm thanh đã nạp. */
    public void playSound(World world, MobSoundEvent event) {
        AudioManager audio = world == null ? null : world.getAudio();
        if (audio != null) {
            if (event == MobSoundEvent.STEP && MobSoundEvent.usesBlockSteps(type.id())) {
                Block ground = Block.fromId(world.getBlock(MathUtils.floor(x()), MathUtils.floor(y() - 0.02f),
                        MathUtils.floor(z())));
                audio.playMobStep(ground, x(), y(), z());
                return;
            }
            audio.playMobSound(type.id(), event, x(), y() + height * 0.5f, z(), 0f, baby ? BABY_PITCH : 1f);
        }
    }

    /** Trả đối tượng trạng thái cố định để lượt vẽ mob dùng lại. */
    @Override
    public MobVisualState mobVisualState() { return visual; }

    /** Hình học mob được vẽ tập trung trong MobRenderer. */
    @Override
    public void render(ShaderProgram shader) {
    }

    /** Trả tên loài và các thuộc tính cố định trong danh mục. */
    public final MobType type() { return type; }
    /** Trả thái độ cơ bản để goal và lớp chuyên biệt chọn phản ứng. */
    public MobAttitude attitude() { return type.attitude(); }
    /** Trả hiệu lực cháy nắng của loài. */
    public boolean burnsInSunlight() { return type.burnsInSunlight(); }
    /** Trả bộ goal tái sử dụng để lớp con có thể đăng ký hành vi. */
    public final MobGoalSelector goals() { return goals; }
    /** Trả bộ điều hướng cố định của cá thể. */
    public final SimpleGridNavigator navigator() { return navigator; }
    /** Trả tọa độ chân theo trục X mà không tạo Vector3. */
    public final float x() { return position.x; }
    /** Trả tọa độ chân theo trục Y mà không tạo Vector3. */
    public final float y() { return position.y; }
    /** Trả tọa độ chân theo trục Z mà không tạo Vector3. */
    public final float z() { return position.z; }
    /** Trả trạng thái chạm nước tại phần thân của cá thể. */
    public final boolean inWater() { return inWater; }
    /** Trả vận tốc đẩy lùi ngang hiện tại theo trục X (block/giây). */
    public final float pushX() { return pushX; }
    /** Trả vận tốc đẩy lùi ngang hiện tại theo trục Z (block/giây). */
    public final float pushZ() { return pushZ; }
    /** Trả tốc độ cơ bản theo block/giây. */
    public final float moveSpeed() { return moveSpeed; }
    /** Trả số giây mô phỏng của cá thể, dùng làm mốc đơn điệu cho goal. */
    public final double ageSeconds() { return ageSeconds; }
    /** Gán tốc độ cơ bản không âm và hữu hạn cho lớp chuyên biệt. */
    public final void setMoveSpeed(float speed) { moveSpeed = Float.isFinite(speed) ? Math.max(0f, speed) : 0f; }
    /** Trả độ cao tối đa mà bộ điều hướng chấp nhận đi lên. */
    public final float stepHeight() { return stepHeight; }
    /** Đặt ngưỡng lên bậc, tối đa 1,5 block cho thú có khả năng bước. */
    public final void setStepHeight(float height) {
        if (Float.isFinite(height)) {
            stepHeight = MathUtils.clamp(height, 0f, 1.5f);
        }
    }
    /** Bật bước thẳng thay cho nhảy, dùng cho thú cưỡi. */
    public final void setDirectStep(boolean enabled) { directStep = enabled; }
    /** Trả quãng rơi lớn nhất ứng với một điểm đi xuống. */
    public final float maxSafeFall() { return maxSafeFall; }
    /** Đặt quãng rơi an toàn cho lớp chuyên biệt. */
    public final void setMaxSafeFall(float blocks) {
        if (Float.isFinite(blocks)) {
            maxSafeFall = MathUtils.clamp(blocks, 0f, World.WORLD_SIZE_Y);
        }
    }
    /** Trả mục tiêu hiện tại mà goal chiến đấu có thể bám theo. */
    public final LivingEntity target() { return target; }
    /** Đổi mục tiêu hoặc xóa khi không còn đối tượng phù hợp (từ chối người chơi ở Creative). */
    public final void setTarget(LivingEntity target) {
        this.target = (target == this || !isValidTarget(target)) ? null : target;
    }
    /** Trả tác nhân của lần bị thương gần nhất, nếu đòn có tác nhân. */
    public final Entity lastAttacker() { return lastAttacker; }
    /** Trả số thứ tự đòn trúng để goal phân biệt các lần gây sát thương. */
    public final int hurtSequence() { return hurtSequence; }
    /** Trả thời gian hoảng còn lại, tính bằng giây. */
    public final float panicTime() { return panicTime; }
    /** Trả thời gian giận còn lại, tính bằng giây. */
    public final float angerTimer() { return angerTimer; }
    /** Trả tỷ lệ hiển thị khi là cá thể trưởng thành (mặc định 1,0×, lớp con có thể ghi đè như Husk 1,06×). */
    protected float adultVisualScale() { return 1f; }
    /** Trả tỷ lệ hiển thị khi là cá thể non (0,6× tỷ lệ trưởng thành). */
    protected float babyVisualScale() { return BABY_SCALE * adultVisualScale(); }
    /** Trả trạng thái non để hành vi và âm thanh dùng cùng một giá trị. */
    public final boolean isBaby() { return baby; }
    /** Đặt trạng thái non, đồng bộ thu nhỏ hitbox 0,5× (hoặc khôi phục 1,0×) và tỷ lệ hình hiển thị. */
    public final void setBaby(boolean baby) {
        this.baby = baby;
        float dimensionScale = baby ? BABY_DIMENSIONS_SCALE : 1f;
        halfWidth = type.width() * 0.5f * dimensionScale;
        height = type.height() * dimensionScale;
        visual.setScale(baby ? babyVisualScale() : adultVisualScale());
    }
    /** Đánh dấu cá thể thuần hóa hoặc được giữ bằng quy tắc riêng của loài. */
    public final void setPersistent(boolean persistent) { this.persistent = persistent; }
    /** Giữ cá thể đã được đánh dấu hoặc đang chở người chơi. */
    public final boolean isPersistent() {
        return persistent || hasPlayerPassenger();
    }

    /** Phân biệt người cưỡi với mob ngồi trên thú trong một nhóm xuất hiện tự nhiên. */
    private boolean hasPlayerPassenger() {
        for (int seat = 0; seat < getSeatCount(); seat++) {
            if (getPassenger(seat) instanceof Player) {
                return true;
            }
        }
        return false;
    }
    /** Đọc số giây ở xa người chơi mà bộ spawn đã tích lũy. */
    public final float noActionTime() { return noActionTime; }
    /** Cập nhật thời lượng ở xa hoặc xóa khi trở về gần người chơi. */
    public final void setNoActionTime(float seconds) { noActionTime = Math.max(0f, seconds); }
}

package com.voxelgame.world.entity.mob;

import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.ItemEntity;
import com.voxelgame.world.entity.mob.animal.Sheep;
import com.voxelgame.world.entity.mob.monster.Enderman;
import com.voxelgame.world.entity.mob.monster.Husk;
import com.voxelgame.world.entity.mob.monster.Skeleton;
import com.voxelgame.world.entity.mob.monster.Witch;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import java.util.concurrent.ThreadLocalRandom;

/**
 * Bảng rơi vật phẩm chuẩn Minecraft 1.21.11 cho toàn bộ 23 loài mob khi chết,
 * hỗ trợ đầy đủ thịt chín khi cháy, điều kiện người chơi giết, đĩa nhạc từ Skeleton bắn Creeper,
 * thuốc phù thủy đang uống và khối đang cầm của Enderman.
 */
public final class MobLootTable {

    /** Sáu vật phẩm rơi ngẫu nhiên của Witch chuẩn Java 1.21+ (Redstone rơi riêng cố định 4–8). */
    private static final Item[] WITCH_DROPS = {
            Item.GLASS_BOTTLE,
            Item.GLOWSTONE_DUST,
            Item.GUNPOWDER,
            Item.SPIDER_EYE,
            Item.SUGAR,
            Item.STICK
    };

    /** Ba vật phẩm hiếm khi tiêu diệt Zombie, Zombie Villager hoặc Husk (2,5%). */
    private static final Item[] ZOMBIE_RARE_DROPS = {
            Item.IRON_INGOT,
            Item.CARROT,
            Item.POTATO
    };

    private MobLootTable() {
    }

    /**
     * Tính toán và sinh toàn bộ vật phẩm rơi ra tại vị trí mob chết.
     *
     * @param world thế giới voxel
     * @param mob cá thể vừa chết
     * @param onFire true nếu mob đang cháy hoặc chết bởi lửa/dung nham
     * @param killer thực thể gây ra đòn kết liễu (có thể là null)
     */
    public static void dropDeathLoot(World world, MobEntity mob, boolean onFire, Entity killer) {
        if (world == null || mob == null) {
            return;
        }
        ThreadLocalRandom random = ThreadLocalRandom.current();
        boolean killedByPlayer = killer instanceof Player;

        // Enderman vẫn rơi lại khối đang cầm dù ở trạng thái nào
        if (mob instanceof Enderman enderman) {
            Block carried = enderman.takeHeldBlockForLoot();
            if (carried != null && carried != Block.AIR) {
                spawnDrops(world, mob, Item.of(carried), 1);
            }
        }

        // Cá thể non trong Minecraft không rơi loot tiêu chuẩn khi chết
        if (mob.isBaby()) {
            return;
        }

        switch (mob.type()) {
            case COW -> {
                spawnDrops(world, mob, Item.LEATHER, random.nextInt(3));
                spawnDrops(world, mob, onFire ? Item.COOKED_BEEF : Item.BEEF, random.nextInt(1, 4));
            }
            case SHEEP -> {
                if (mob instanceof Sheep sheep && !sheep.isSheared()) {
                    spawnDrops(world, mob, sheep.woolColor().woolItem(), 1);
                }
                spawnDrops(world, mob, onFire ? Item.COOKED_MUTTON : Item.MUTTON, random.nextInt(1, 3));
            }
            case PIG -> spawnDrops(world, mob, onFire ? Item.COOKED_PORKCHOP : Item.PORKCHOP, random.nextInt(1, 4));
            case CHICKEN -> {
                spawnDrops(world, mob, Item.FEATHER, random.nextInt(3));
                spawnDrops(world, mob, onFire ? Item.COOKED_CHICKEN : Item.CHICKEN, 1);
            }
            case RABBIT, SNOW_RABBIT -> {
                spawnDrops(world, mob, Item.RABBIT_HIDE, random.nextInt(2));
                spawnDrops(world, mob, onFire ? Item.COOKED_RABBIT : Item.RABBIT, random.nextInt(2));
                if (killedByPlayer && random.nextFloat() < 0.10f) {
                    spawnDrops(world, mob, Item.RABBIT_FOOT, 1);
                }
            }
            case POLAR_BEAR -> {
                if (random.nextFloat() < 0.75f) {
                    spawnDrops(world, mob, onFire ? Item.COOKED_COD : Item.COD, random.nextInt(3));
                } else {
                    spawnDrops(world, mob, onFire ? Item.COOKED_SALMON : Item.SALMON, random.nextInt(3));
                }
            }
            case HORSE, DONKEY -> spawnDrops(world, mob, Item.LEATHER, random.nextInt(3));
            case CAMEL_HUSK -> spawnDrops(world, mob, Item.ROTTEN_FLESH, random.nextInt(2, 4));
            case ZOMBIE, ZOMBIE_VILLAGER, HUSK -> {
                spawnDrops(world, mob, Item.ROTTEN_FLESH, random.nextInt(3));
                if (killedByPlayer && random.nextFloat() < 0.025f) {
                    Item rare = ZOMBIE_RARE_DROPS[random.nextInt(ZOMBIE_RARE_DROPS.length)];
                    if (rare == Item.POTATO && onFire) {
                        rare = Item.BAKED_POTATO;
                    }
                    spawnDrops(world, mob, rare, 1);
                }
                if (mob instanceof Husk husk && husk.hasIronSpear() && killedByPlayer && random.nextFloat() < 0.085f) {
                    spawnDrops(world, mob, Item.IRON_SPEAR, 1);
                }
            }
            case SKELETON -> {
                spawnDrops(world, mob, Item.BONE, random.nextInt(3));
                spawnDrops(world, mob, Item.ARROW, random.nextInt(3));
                if (killedByPlayer && random.nextFloat() < 0.085f) {
                    spawnDrops(world, mob, Item.BOW, 1);
                }
            }
            case STRAY -> {
                spawnDrops(world, mob, Item.BONE, random.nextInt(3));
                spawnDrops(world, mob, Item.ARROW, random.nextInt(3));
                if (killedByPlayer && random.nextBoolean()) {
                    spawnDrops(world, mob, Item.TIPPED_ARROW_SLOWNESS, 1);
                }
                if (killedByPlayer && random.nextFloat() < 0.085f) {
                    spawnDrops(world, mob, Item.BOW, 1);
                }
            }
            case PARCHED -> {
                spawnDrops(world, mob, Item.BONE, random.nextInt(3));
                spawnDrops(world, mob, Item.ARROW, random.nextInt(3));
                if (killedByPlayer && random.nextBoolean()) {
                    spawnDrops(world, mob, Item.TIPPED_ARROW_WEAKNESS, 1);
                }
                if (killedByPlayer && random.nextFloat() < 0.085f) {
                    spawnDrops(world, mob, Item.BOW, 1);
                }
            }
            case CREEPER -> {
                spawnDrops(world, mob, Item.GUNPOWDER, random.nextInt(3));
                // Bất kỳ cung thủ họ Skeleton (Skeleton, Stray, Parched) bắn chết Creeper sẽ rơi đĩa nhạc
                if (killer instanceof Skeleton) {
                    Item disc = random.nextBoolean() ? Item.MUSIC_DISC_13 : Item.MUSIC_DISC_CAT;
                    spawnDrops(world, mob, disc, 1);
                }
            }
            case SPIDER -> {
                spawnDrops(world, mob, Item.STRING, random.nextInt(3));
                if (killedByPlayer && random.nextInt(3) == 0) {
                    spawnDrops(world, mob, Item.SPIDER_EYE, 1);
                }
            }
            case ENDERMAN -> spawnDrops(world, mob, Item.ENDER_PEARL, random.nextInt(2));
            case WITCH -> {
                // Chuẩn Minecraft Java 1.21+: luôn rơi 4–8 Redstone Dust cộng 1–3 lượt × 0–2 từ 6 món còn lại.
                spawnDrops(world, mob, Item.REDSTONE, random.nextInt(4, 9));
                int rolls = random.nextInt(1, 4);
                for (int i = 0; i < rolls; i++) {
                    Item chosen = WITCH_DROPS[random.nextInt(WITCH_DROPS.length)];
                    spawnDrops(world, mob, chosen, random.nextInt(3));
                }
                if (killedByPlayer && mob instanceof Witch witch) {
                    Item drinkingPotion = witch.drinkingPotionItem();
                    if (drinkingPotion != null && random.nextFloat() < 0.085f) {
                        spawnDrops(world, mob, drinkingPotion, 1);
                    }
                }
            }
            case GOAT, WOLF, SNOW_FOX, CAMEL -> {
                // Goat chỉ rơi sừng khi húc và sữa khi vắt; SnowFox tự thả vật ngậm trong finishLivingUpdate; Wolf & Camel không rơi khi chết.
            }
        }
    }

    /** Sinh từng ItemEntity riêng lẻ để tương thích với giới hạn 1 item/thực thể nhặt của World. */
    private static void spawnDrops(World world, MobEntity mob, Item item, int count) {
        if (item == null || item.isNone() || count <= 0) {
            return;
        }
        float dropY = mob.y() + Math.min(0.45f, mob.getHeight() * 0.4f);
        for (int i = 0; i < count; i++) {
            world.spawnDroppedItem(new ItemEntity(mob.x(), dropY, mob.z(), item));
        }
    }
}

package com.voxelgame.world.entity.mob;

import com.voxelgame.world.entity.mob.MobCategory;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.level.biome.Biome;
import com.voxelgame.world.level.biome.BiomeType;
import com.voxelgame.world.level.biome.SnowSubZone;

/** Bảng loài và trọng số cho mỗi biome, dùng chung giữa các lượt sinh. */
public final class MobSpawnTable {
    /** Một loài ứng viên, số ô xác suất và khoảng cỡ bầy tính cả hai đầu. */
    public record Entry(MobType type, int weight, int minPackSize, int maxPackSize) {
    }

    /** Trọng số và cỡ bầy của đồng bằng ôn hòa. */
    public static final MobSpawnTable PLAINS_CREATURES = new MobSpawnTable(
            new Entry(MobType.SHEEP, 12, 4, 4), new Entry(MobType.PIG, 10, 4, 4),
            new Entry(MobType.CHICKEN, 10, 4, 4), new Entry(MobType.COW, 8, 4, 4),
            new Entry(MobType.HORSE, 5, 2, 6), new Entry(MobType.DONKEY, 1, 1, 3));
    /** Rừng sồi có thêm bầy sói hoang thay cho ngựa/lừa. */
    public static final MobSpawnTable FOREST_CREATURES = new MobSpawnTable(
            new Entry(MobType.SHEEP, 12, 4, 4), new Entry(MobType.PIG, 10, 4, 4),
            new Entry(MobType.CHICKEN, 10, 4, 4), new Entry(MobType.COW, 8, 4, 4),
            new Entry(MobType.WOLF, 5, 4, 4));
    /** Rừng hoa dùng thảm thỏ thay cho sói và không có ngựa/lừa. */
    public static final MobSpawnTable FLOWER_FOREST_CREATURES = new MobSpawnTable(
            new Entry(MobType.SHEEP, 12, 4, 4), new Entry(MobType.PIG, 10, 4, 4),
            new Entry(MobType.CHICKEN, 10, 4, 4), new Entry(MobType.COW, 8, 4, 4),
            new Entry(MobType.SNOW_RABBIT, 4, 2, 3));
    public static final MobSpawnTable PLAINS_MONSTERS = new MobSpawnTable(
            new Entry(MobType.SPIDER, 100, 4, 4), new Entry(MobType.SKELETON, 100, 4, 4),
            new Entry(MobType.CREEPER, 100, 4, 4), new Entry(MobType.ZOMBIE, 95, 4, 4),
            new Entry(MobType.ENDERMAN, 10, 1, 4), new Entry(MobType.ZOMBIE_VILLAGER, 5, 1, 1),
            new Entry(MobType.WITCH, 5, 1, 1));

    /** Sa mạc sinh thỏ vàng (chuẩn desert.json); lạc đà hiền sinh cố định gần kim tự tháp. */
    public static final MobSpawnTable DESERT_CREATURES = new MobSpawnTable(
            new Entry(MobType.RABBIT, 4, 2, 3));
    public static final MobSpawnTable DESERT_MONSTERS = new MobSpawnTable(
            new Entry(MobType.SPIDER, 100, 4, 4), new Entry(MobType.CREEPER, 100, 4, 4),
            new Entry(MobType.HUSK, 80, 4, 4), new Entry(MobType.PARCHED, 50, 4, 4),
            new Entry(MobType.SKELETON, 50, 4, 4), new Entry(MobType.ZOMBIE, 19, 4, 4),
            new Entry(MobType.ENDERMAN, 10, 1, 4), new Entry(MobType.WITCH, 5, 1, 1),
            new Entry(MobType.ZOMBIE_VILLAGER, 1, 1, 1));

    /** Ba bảng thú tuyết theo địa hình và một bảng quái chung cho cả biome. */
    public static final MobSpawnTable SNOW_FLAT_CREATURES = new MobSpawnTable(
            new Entry(MobType.SNOW_RABBIT, 10, 2, 3), new Entry(MobType.POLAR_BEAR, 1, 1, 2));
    public static final MobSpawnTable SNOW_GROVE_CREATURES = new MobSpawnTable(
            new Entry(MobType.WOLF, 8, 4, 4), new Entry(MobType.SNOW_FOX, 8, 2, 4),
            new Entry(MobType.SNOW_RABBIT, 4, 2, 3));
    public static final MobSpawnTable SNOW_SLOPE_CREATURES = new MobSpawnTable(
            new Entry(MobType.GOAT, 5, 1, 3), new Entry(MobType.SNOW_RABBIT, 4, 2, 3));
    public static final MobSpawnTable SNOW_MONSTERS = new MobSpawnTable(
            new Entry(MobType.SPIDER, 100, 4, 4), new Entry(MobType.CREEPER, 100, 4, 4),
            new Entry(MobType.ZOMBIE, 95, 4, 4), new Entry(MobType.STRAY, 80, 4, 4),
            new Entry(MobType.SKELETON, 20, 4, 4), new Entry(MobType.ENDERMAN, 10, 1, 4),
            new Entry(MobType.ZOMBIE_VILLAGER, 5, 1, 1), new Entry(MobType.WITCH, 5, 1, 1));

    /** Danh mục cố định và tổng miền bốc thăm, tính một lần khi dựng bảng. */
    private final Entry[] entries;
    private final int totalWeight;

    /** Dùng mảng riêng tạo tại chỗ cho mỗi bảng để các lượt sinh chỉ đọc. */
    private MobSpawnTable(Entry... entries) {
        this.entries = entries;
        int sum = 0;
        for (Entry entry : entries) {
            sum += entry.weight();
        }
        totalWeight = sum;
    }

    /** Chọn bảng cố định thông qua lời gọi đa hình tới {@link Biome#getSpawnTable(MobCategory, SnowSubZone)}. */
    public static MobSpawnTable forBiome(BiomeType biome, MobCategory category, SnowSubZone zone) {
        return Biome.of(biome).getSpawnTable(category, zone);
    }

    /** Trả tổng trọng số làm giới hạn trên loại trừ của lần lấy số ngẫu nhiên. */
    public int totalWeight() {
        return totalWeight;
    }

    /** Cho biết biome đã có thú hoạt động để tránh đánh dấu khám phá quá sớm. */
    static boolean anyImplementedCreatures(BiomeType biome) {
        return switch (biome) {
            case PLAINS -> PLAINS_CREATURES.hasImplementedType();
            case FOREST -> FOREST_CREATURES.hasImplementedType();
            case FLOWER_FOREST -> FLOWER_FOREST_CREATURES.hasImplementedType();
            case DESERT -> DESERT_CREATURES.hasImplementedType();
            case SNOWY_PLAINS -> SNOW_FLAT_CREATURES.hasImplementedType()
                    || SNOW_GROVE_CREATURES.hasImplementedType() || SNOW_SLOPE_CREATURES.hasImplementedType();
        };
    }

    /** Tìm factory đã đăng ký trong một bảng nhỏ cố định. */
    private boolean hasImplementedType() {
        for (Entry entry : entries) {
            if (entry.type().implemented()) {
                return true;
            }
        }
        return false;
    }

    /** Trả mục có khoảng trọng số chứa số đã bốc, dùng lại đối tượng của bảng. */
    public Entry select(int roll) {
        if (roll < 0 || roll >= totalWeight) {
            throw new IllegalArgumentException("Giá trị chọn mob nằm ngoài miền trọng số");
        }
        for (Entry entry : entries) {
            roll -= entry.weight();
            if (roll < 0) {
                return entry;
            }
        }
        throw new AssertionError("Không tìm thấy mục mob trong miền trọng số đã xác thực");
    }
}

package com.voxelgame.world.entity.mob;

import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.world.entity.mob.animal.Donkey;
import com.voxelgame.world.entity.mob.animal.Horse;
import com.voxelgame.world.entity.mob.animal.PolarBear;
import com.voxelgame.world.entity.mob.MobCategory;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.monster.CamelHusk;
import com.voxelgame.world.entity.mob.monster.Husk;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.biome.BiomeType;
import com.voxelgame.world.level.biome.SnowSubZone;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.Chunk;
import com.voxelgame.world.level.gen.DesertPyramid;
import com.voxelgame.world.level.World;
import com.voxelgame.world.level.WorldTime;

import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Vector3;
import java.util.Random;

/**
 * Điều phối lượt sinh tự nhiên và loại quái quá xa trên luồng cập nhật World.
 */
public final class MobSpawner {
    /** So sánh bình phương khoảng cách 3D để tránh căn bậc hai khi kiểm tra. */
    private static final int MIN_SPAWN_DISTANCE = 24;
    private static final int MAX_DISTANCE = 128;
    private static final int MIN_SPAWN_DISTANCE_SQUARED = MIN_SPAWN_DISTANCE * MIN_SPAWN_DISTANCE;
    public static final int MAX_DISTANCE_SQUARED = MAX_DISTANCE * MAX_DISTANCE;
    private static final int MIN_DESPAWN_DISTANCE_SQUARED = 32 * 32;
    /**
     * Chu kỳ sinh tách riêng theo chuẩn Minecraft: quái 1 tick (0,05s), thú định kỳ
     * 400 tick (20s), quét chunk mới 0,25s.
     */
    public static final float MONSTER_INTERVAL = 0.05f;
    public static final float CREATURE_INTERVAL = 20.0f;
    private static final float POPULATION_INTERVAL = 0.25f;
    private static final double TIMER_EPSILON = 1e-5d;
    private static final int MONSTER_ATTEMPTS_PER_TICK = 1;
    private static final int CREATURE_ATTEMPTS = 4;
    private static final int POPULATION_COLUMNS = 6;
    private static final int POPULATION_ATTEMPTS = 4;
    private static final int PACK_ATTEMPTS = 16;
    private static final int CHUNK_SPAN = (MAX_DISTANCE / Chunk.SIZE + 1) * 2 + 1;
    /** Dung sai để chạm mặt đất mà không tính là đâm vào mặt đất. */
    private static final float EPSILON = 0.001f;
    /** Giới hạn các tầng thử ngầm và tầng tìm nền bên dưới tán. */
    private static final int UNDERGROUND_SPAN = 19;
    private static final int CANOPY_DEPTH = 14;
    /** Chiều cao trống gồm lưng lạc đà xác sống và không gian cho kỵ sĩ. */
    private static final float JOCKEY_HEIGHT = 4.38f;
    private static final int TICKS_PER_SECOND = 20;
    private static final int DESPAWN_DELAY_TICKS = 600;
    private static final int DESPAWN_CHANCE_DIVISOR = 800;

    private final long[] populated = new long[(World.WORLD_CHUNKS_X * World.WORLD_CHUNKS_Z + 63) >>> 6];
    private final Random spawnRandom;
    private final Random despawnRandom;
    /** Bộ đệm vị trí người chơi dùng lại trên luồng World. */
    private final Vector3 playerPosition = new Vector3();
    /** Bộ đệm tính từng điểm ngồi trước khi đăng ký bộ kỵ sĩ. */
    private final Vector3 jockeySeat = new Vector3();
    private int populationCursor;
    private double monsterElapsed;
    private double populationElapsed;
    private double creatureElapsed;
    private boolean pyramidCamelSpawned;

    /** Tách ngẫu nhiên biến mất khỏi lượt sinh và bầy khám phá. */
    public MobSpawner(long seed) {
        spawnRandom = new Random(seed);
        despawnRandom = new Random(seed ^ 0x643B7935L);
    }

    /**
     * Chạy từng nhịp sinh riêng biệt: quái 1 tick, khám phá chunk 0,25s, thú định
     * kỳ 400 tick (20s).
     */
    public void update(World world, WorldTime time, float dt) {
        Player player = world.getPlayer();
        if (player == null || !player.isAlive() || !(dt > 0) || !Float.isFinite(dt)) {
            return;
        }
        boolean creatures = MobType.anyImplemented(MobCategory.CREATURE);
        boolean monsters = MobType.anyImplemented(MobCategory.MONSTER);
        if (!creatures && !monsters) {
            return;
        }

        int monsterSteps = 0;
        if (monsters) {
            monsterElapsed += dt;
            if (monsterElapsed + TIMER_EPSILON >= MONSTER_INTERVAL) {
                monsterSteps = Math.min(5, (int) Math.floor((monsterElapsed + TIMER_EPSILON) / MONSTER_INTERVAL));
                monsterElapsed = Math.max(0d, monsterElapsed - monsterSteps * (double) MONSTER_INTERVAL);
            }
        }
        boolean runPopulation = false;
        boolean runCreature = false;
        if (creatures) {
            populationElapsed += dt;
            if (populationElapsed + TIMER_EPSILON >= POPULATION_INTERVAL) {
                populationElapsed %= POPULATION_INTERVAL;
                runPopulation = true;
            }
            creatureElapsed += dt;
            if (creatureElapsed + TIMER_EPSILON >= CREATURE_INTERVAL) {
                creatureElapsed %= CREATURE_INTERVAL;
                runCreature = true;
            }
        }
        if (monsterSteps == 0 && !runPopulation && !runCreature) {
            return;
        }

        int creatureCount = 0;
        int monsterCount = 0;
        for (int i = 0; i < world.entityCount(); i++) {
            if (world.entityAt(i) instanceof MobEntity mob && mob.isAlive()
                    && distanceSquared(mob, player) <= MAX_DISTANCE_SQUARED) {
                if (mob.type().category() == MobCategory.MONSTER) {
                    monsterCount++;
                } else {
                    creatureCount++;
                }
            }
        }

        if (monsterSteps > 0) {
            int monsterRoom = MobCategory.MONSTER.cap() - monsterCount;
            for (int step = 0; step < monsterSteps && monsterRoom > 0; step++) {
                for (int i = 0; i < MONSTER_ATTEMPTS_PER_TICK && monsterRoom > 0; i++) {
                    monsterRoom -= sampleAroundPlayer(world, time, MobCategory.MONSTER, monsterRoom);
                }
            }
        }

        if (runPopulation) {
            if (!pyramidCamelSpawned && MobType.CAMEL.implemented()) {
                if (trySpawnPyramidCamel(world)) {
                    creatureCount++;
                }
            }
            creatureCount += populateNearbyChunks(world, time);
        }
        if (runCreature) {
            int creatureRoom = MobCategory.CREATURE.cap() - creatureCount;
            for (int i = 0; i < CREATURE_ATTEMPTS && creatureRoom > 0; i++) {
                creatureRoom -= sampleAroundPlayer(world, time, MobCategory.CREATURE, creatureRoom);
            }
        }
    }

    /**
     * Sinh cố định một con Camel hiền lành gần kim tự tháp sa mạc khi người chơi
     * khám phá tới nơi.
     */
    private boolean trySpawnPyramidCamel(World world) {
        DesertPyramid pyramid = world.desertPyramid();
        if (pyramid == null) {
            return false;
        }
        Vector3 player = world.getPlayer().copyPosition(playerPosition);
        float dx = pyramid.centerX() + 0.5f - player.x;
        float dy = pyramid.baseY() + 1f - player.y;
        float dz = pyramid.centerZ() + 0.5f - player.z;
        if (dx * dx + dy * dy + dz * dz > MAX_DISTANCE_SQUARED) {
            return false;
        }
        // Ưu tiên phía cửa nam kim tự tháp trước, sau đó quét các vành xung quanh.
        for (int z = pyramid.centerZ() + 12; z <= pyramid.centerZ() + 20; z++) {
            for (int x = pyramid.centerX() - 6; x <= pyramid.centerX() + 6; x++) {
                if (spawnPyramidCamelAt(world, x, z, pyramid.baseY())) {
                    return true;
                }
            }
        }
        for (int radius = 12; radius <= 20; radius++) {
            for (int offsetX = -radius; offsetX <= radius; offsetX++) {
                for (int offsetZ = -radius; offsetZ <= radius; offsetZ++) {
                    if (Math.max(Math.abs(offsetX), Math.abs(offsetZ)) != radius) {
                        continue;
                    }
                    if (spawnPyramidCamelAt(world, pyramid.centerX() + offsetX, pyramid.centerZ() + offsetZ,
                            pyramid.baseY())) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Kiểm tra cột cát hoặc đá cát ngoài trời gần kim tự tháp và đặt Camel trưởng
     * thành.
     */
    private boolean spawnPyramidCamelAt(World world, int x, int z, int refY) {
        if (!world.isInsideWorld(x, 0, z) || world.getBiome(x, z) != BiomeType.DESERT) {
            return false;
        }
        int topY = Math.min(World.WORLD_SIZE_Y - 4, refY + 12);
        int bottomY = Math.max(1, refY - 12);
        for (int y = topY; y >= bottomY; y--) {
            Block ground = Block.fromId(world.getBlock(x, y, z));
            if (ground != Block.SAND && ground != Block.SANDSTONE) {
                continue;
            }
            Block.Bounds bounds = ground.getCollisionBounds(world.getBlockState(x, y, z));
            if (bounds == null) {
                continue;
            }
            float feet = y + bounds.maxY();
            if (hasClearance(world, x + 0.5f, feet, z + 0.5f, MobType.CAMEL.width(), MobType.CAMEL.height())) {
                MobEntity camel = MobType.CAMEL.create(x + 0.5f, feet, z + 0.5f);
                if (camel == null) {
                    return false;
                }
                camel.setBaby(false);
                camel.setPersistent(true);
                world.addEntity(camel);
                pyramidCamelSpawned = true;
                return true;
            }
        }
        return false;
    }

    /**
     * Duyệt dần tọa độ chunk mới trong vành hoạt động, ghi một bit sau lần xét đầu
     * tiên.
     */
    private int populateNearbyChunks(World world, WorldTime time) {
        Vector3 player = world.getPlayer().copyPosition(playerPosition);
        int centerChunkX = Math.floorDiv(MathUtils.floor(player.x), Chunk.SIZE);
        int centerChunkZ = Math.floorDiv(MathUtils.floor(player.z), Chunk.SIZE);
        int created = 0;
        for (int i = 0; i < POPULATION_COLUMNS; i++) {
            int chunkX = centerChunkX + populationCursor / CHUNK_SPAN - CHUNK_SPAN / 2;
            int chunkZ = centerChunkZ + populationCursor % CHUNK_SPAN - CHUNK_SPAN / 2;
            populationCursor = (populationCursor + 1) % (CHUNK_SPAN * CHUNK_SPAN);
            if (chunkX < 0 || chunkX >= World.WORLD_CHUNKS_X || chunkZ < 0 || chunkZ >= World.WORLD_CHUNKS_Z) {
                continue;
            }
            int x0 = chunkX * Chunk.SIZE;
            int z0 = chunkZ * Chunk.SIZE;
            int centerX = Math.min(World.WORLD_SIZE_X - 1, x0 + Chunk.SIZE / 2);
            int centerZ = z0 + Chunk.SIZE / 2;
            float dx = centerX + 0.5f - player.x;
            float dz = centerZ + 0.5f - player.z;
            float horizontal = dx * dx + dz * dz;
            if (horizontal > MAX_DISTANCE_SQUARED) {
                continue;
            }
            int bit = chunkX * World.WORLD_CHUNKS_Z + chunkZ;
            int index = bit >>> 6;
            long mask = 1L << (bit & 63);
            if ((populated[index] & mask) != 0L) {
                continue;
            }
            float surface = world.getPrecipitationSurface(centerX, centerZ);
            float dy = surface - player.y;
            float distance = horizontal + dy * dy;
            if (surface <= 0 || distance < MIN_SPAWN_DISTANCE_SQUARED || distance > MAX_DISTANCE_SQUARED) {
                continue;
            }
            BiomeType biome = world.getBiome(centerX, centerZ);
            if (!MobSpawnTable.anyImplementedCreatures(biome) || biome.hasRain() && !isDaylight(time)) {
                continue;
            }
            populated[index] |= mask;
            if (spawnRandom.nextInt(10) != 0) {
                continue;
            }
            for (int attempt = 0; attempt < POPULATION_ATTEMPTS; attempt++) {
                int x = x0 + spawnRandom.nextInt(Chunk.SIZE);
                int z = z0 + spawnRandom.nextInt(Chunk.SIZE);
                int count = spawnPack(world, time, MobCategory.CREATURE, x, z, Integer.MAX_VALUE);
                if (count > 0) {
                    created += count;
                    break;
                }
            }
        }
        return created;
    }

    /** Chọn ô ngang bằng lấy mẫu đều trên hình vuông rồi loại điểm ngoài vành. */
    private int sampleAroundPlayer(World world, WorldTime time, MobCategory category, int room) {
        Vector3 player = world.getPlayer().copyPosition(playerPosition);
        int dx = spawnRandom.nextInt(2 * MAX_DISTANCE + 1) - MAX_DISTANCE;
        int dz = spawnRandom.nextInt(2 * MAX_DISTANCE + 1) - MAX_DISTANCE;
        return spawnPack(world, time, category, MathUtils.floor(player.x) + dx, MathUtils.floor(player.z) + dz, room);
    }

    /**
     * Chọn loài một lần và thử sinh các thành viên gần điểm gốc cùng biome và phân
     * vùng.
     */
    int spawnPack(World world, WorldTime time, MobCategory category, int x, int z, int room) {
        if (!world.isInsideWorld(x, 0, z)) {
            return 0;
        }
        Vector3 player = world.getPlayer().copyPosition(playerPosition);
        float dx = x + 0.5f - player.x;
        float dz = z + 0.5f - player.z;
        if (dx * dx + dz * dz > MAX_DISTANCE_SQUARED) {
            return 0;
        }
        BiomeType biome = world.getBiome(x, z);
        if (category == MobCategory.CREATURE && biome.hasRain() && !isDaylight(time)) {
            return 0;
        }
        float surface = world.getPrecipitationSurface(x, z);
        boolean nearSurface = category == MobCategory.CREATURE || isNightDark(time) && spawnRandom.nextInt(4) != 0;
        int topY = MathUtils.floor(nearSurface ? surface - EPSILON
                : Math.min(surface - 1, MathUtils.floor(player.y) + spawnRandom.nextInt(11)));
        if (topY < 0) {
            return 0;
        }
        if (category == MobCategory.CREATURE) {
            topY = terrainBelowCanopy(world, x, topY, z);
        }
        SnowSubZone zone = category == MobCategory.CREATURE && biome == BiomeType.SNOWY_PLAINS
                ? SnowSubZone.classify(world, x, topY + 1, z)
                : null;
        MobSpawnTable table = MobSpawnTable.forBiome(biome, category, zone);
        MobSpawnTable.Entry entry = table.select(spawnRandom.nextInt(table.totalWeight()));
        MobType type = entry.type();
        if (!type.implemented()) {
            return 0;
        }

        float feet = findSpawnFeet(world, time, type, x, z, topY, nearSurface ? CANOPY_DEPTH : UNDERGROUND_SPAN);
        if (feet < 0 || !matchesSnowZone(world, zone, x, feet, z)) {
            return 0;
        }
        int desired = entry.minPackSize() + spawnRandom.nextInt(entry.maxPackSize() - entry.minPackSize() + 1);
        MobAppearance coat = type == MobType.HORSE ? Horse.randomCoat(spawnRandom) : null;
        int first = spawnMember(world, time, type, x + 0.5f, feet, z + 0.5f, room, false, coat);
        int created = first;
        int members = first == 0 ? 0 : 1;
        for (int attempt = 0; attempt < PACK_ATTEMPTS && members < desired && created < room; attempt++) {
            int packX = x + spawnRandom.nextInt(11) - 5;
            int packZ = z + spawnRandom.nextInt(11) - 5;
            if (!world.isInsideWorld(packX, 0, packZ) || world.getBiome(packX, packZ) != biome) {
                continue;
            }
            int packTop = MathUtils.floor(feet + 2 - EPSILON);
            float packFeet = findSpawnFeet(world, time, type, packX, packZ, packTop, 5);
            if (packFeet < 0 || !matchesSnowZone(world, zone, packX, packFeet, packZ)) {
                continue;
            }
            boolean bearCub = type == MobType.POLAR_BEAR && members == 1;
            int added = spawnMember(world, time, type, packX + 0.5f, packFeet, packZ + 0.5f,
                    room - created, bearCub, coat);
            if (added > 0) {
                created += added;
                members++;
            }
        }
        return created;
    }

    /** Bỏ qua tán hoặc thân cây khi lấy cao độ để phân vùng địa hình sinh thú. */
    private static int terrainBelowCanopy(World world, int x, int topY, int z) {
        for (int y = topY; y >= Math.max(0, topY - CANOPY_DEPTH); y--) {
            Block block = Block.fromId(world.getBlock(x, y, z));
            if (block != Block.OAK_LEAVES && block != Block.SPRUCE_LEAVES
                    && block != Block.OAK_LOG && block != Block.SPRUCE_LOG
                    && (block.isLiquid() || world.getCollisionBounds(x, y, z) != null)) {
                return y;
            }
        }
        return topY;
    }

    /** Chỉ áp dụng phân vùng tuyết cho các loại thú có bảng riêng. */
    private static boolean matchesSnowZone(World world, SnowSubZone zone, int x, float feet, int z) {
        return zone == null || zone == SnowSubZone.classify(world, x, MathUtils.ceil(feet), z);
    }

    /** Duyệt một đoạn cột ngắn cho mặt cỏ, dưới tán hoặc dải tầng hầm đã chọn. */
    private float findSpawnFeet(World world, WorldTime time, MobType type, int x, int z, int topY, int depth) {
        int bottom = Math.max(0, topY - depth + 1);
        for (int y = Math.min(topY, World.WORLD_SIZE_Y - 1); y >= bottom; y--) {
            Block ground = Block.fromId(world.getBlock(x, y, z));
            Block.Bounds bounds = ground.getCollisionBounds(world.getBlockState(x, y, z));
            if (bounds != null) {
                float feet = y + bounds.maxY();
                int feetCell = MathUtils.floor(feet + EPSILON);
                Block.Bounds above = feetCell == y ? null : world.getCollisionBounds(x, feetCell, z);
                if ((above == null || above.minY() > EPSILON)
                        && canSpawn(world, type, x + 0.5f, feet, z + 0.5f, time)) {
                    return feet;
                }
            }
        }
        return -1;
    }

    /**
     * Ghi một cá thể hoặc ba thành viên kỵ sĩ sau khi kiểm tra khoảng trống và hạn
     * mức.
     */
    private int spawnMember(World world, WorldTime time, MobType type, float x, float y, float z, int room,
            boolean bearCub, MobAppearance coat) {
        if (type == MobType.HUSK && room >= 3 && MobType.CAMEL_HUSK.implemented()
                && MobType.PARCHED.implemented() && isDesertSurfaceAtNight(world, time, x, y, z)
                && spawnRandom.nextInt(10) == 0
                && hasClearance(world, x, y, z, MobType.CAMEL_HUSK.width(), JOCKEY_HEIGHT)
                && spawnJockey(world, x, y, z)) {
            return 3;
        }
        if (type == MobType.SPIDER && room >= 2 && spawnRandom.nextInt(100) == 0
                && spawnSpiderJockey(world, x, y, z)) {
            return 2;
        }
        // Chỉ con thứ hai trong bầy gấu là con non, với hộp va chạm bằng nửa con trưởng
        // thành.
        MobEntity mob = bearCub ? new PolarBear(x, y, z, true) : type.create(x, y, z);
        if (mob == null) {
            return 0;
        }
        if (mob instanceof Horse horse) {
            horse.mobVisualState().setAppearance(coat);
        }
        // Áp dụng tỉ lệ cá thể non chuẩn Minecraft cho các loài thú sinh từ spawner.
        switch (type) {
            case HORSE, DONKEY -> mob.setBaby(spawnRandom.nextInt(5) == 0);
            case RABBIT, SNOW_RABBIT -> mob.setBaby(spawnRandom.nextInt(10) == 0);
            case COW, SHEEP, PIG, CHICKEN, WOLF, GOAT -> mob.setBaby(spawnRandom.nextInt(20) == 0);
            default -> {
            }
        }
        world.addEntity(mob);
        return 1;
    }

    /** Chọn cung thủ bản địa trên bề mặt và Skeleton thường trong phòng kín. */
    boolean spawnSpiderJockey(World world, float x, float y, float z) {
        int bx = MathUtils.floor(x);
        int bz = MathUtils.floor(z);
        MobType riderType = MobType.SKELETON;
        if (!world.hasWeatherRoof(bx, y + 1f, bz)) {
            riderType = switch (world.getBiome(bx, bz)) {
                case PLAINS, FOREST, FLOWER_FOREST -> MobType.SKELETON;
                case DESERT -> MobType.PARCHED;
                case SNOWY_PLAINS -> MobType.STRAY;
            };
        }
        float riderY = y + MobType.SPIDER.height();
        if (!riderType.implemented() || !hasClearance(world, x, y, z, MobType.SPIDER.width(),
                riderY - y + riderType.height())) {
            return false;
        }
        MobEntity mount = MobType.SPIDER.create(x, y, z);
        MobEntity rider = riderType.create(x, riderY, z);
        if (mount == null || rider == null || !rider.tryMount(mount, 0)) {
            return false;
        }
        world.addEntity(mount);
        world.addEntity(rider);
        return true;
    }

    /**
     * Dựng bộ kỵ sĩ đồng thời, chỉ đăng ký vào World khi cả hai ghế đã gắn thành
     * công.
     */
    private boolean spawnJockey(World world, float x, float y, float z) {
        MobEntity mount = MobType.CAMEL_HUSK.create(x, y, z);
        if (mount == null || mount.getSeatCount() < 2) {
            return false;
        }
        mount.copySeatPosition(0, jockeySeat);
        // Husk cầm giáo cưỡi Camel Husk luôn là cá thể trưởng thành.
        MobEntity front = mount instanceof CamelHusk ? new Husk(jockeySeat.x, jockeySeat.y, jockeySeat.z, true, false)
                : MobType.HUSK.create(jockeySeat.x, jockeySeat.y, jockeySeat.z);
        mount.copySeatPosition(1, jockeySeat);
        MobEntity back = MobType.PARCHED.create(jockeySeat.x, jockeySeat.y, jockeySeat.z);
        if (front == null || back == null || !front.tryMount(mount, 0) || !back.tryMount(mount, 1)) {
            return false;
        }
        world.addEntity(mount);
        world.addEntity(front);
        world.addEntity(back);
        return true;
    }

    /**
     * Một lượt Husk chỉ có thể đổi thành bộ kỵ sĩ ở mặt thoáng của Desert vào đêm.
     */
    private static boolean isDesertSurfaceAtNight(World world, WorldTime time, float x, float y, float z) {
        int bx = MathUtils.floor(x);
        int bz = MathUtils.floor(z);
        return isNightDark(time) && world.getBiome(bx, bz) == BiomeType.DESERT
                && Math.abs(world.getPrecipitationSurface(bx, bz) - y) < EPSILON;
    }

    /**
     * Kiểm tra khoảng cách, ánh sáng, nền và hộp va chạm ở vị trí chân được đề
     * xuất.
     */
    boolean canSpawn(World world, MobType type, float x, float y, float z, WorldTime time) {
        Player player = world.getPlayer();
        if (player == null) {
            return false;
        }
        float distance = player.copyPosition(playerPosition).dst2(x, y, z);
        if (distance < MIN_SPAWN_DISTANCE_SQUARED || distance > MAX_DISTANCE_SQUARED) {
            return false;
        }
        int blockX = MathUtils.floor(x);
        int blockY = MathUtils.floor(y - EPSILON);
        int blockZ = MathUtils.floor(z);
        if (!world.isInsideWorld(blockX, blockY, blockZ)) {
            return false;
        }
        Block ground = Block.fromId(world.getBlock(blockX, blockY, blockZ));
        Block.Bounds support = ground.getCollisionBounds(world.getBlockState(blockX, blockY, blockZ));
        if (support == null || Math.abs(blockY + support.maxY() - y) >= EPSILON) {
            return false;
        }
        Block base = ground == Block.SNOW_LAYER ? Block.fromId(world.getBlock(blockX, blockY - 1, blockZ)) : ground;
        if (base == Block.BEDROCK || base == Block.CACTUS || base == Block.OAK_LEAVES || base == Block.SPRUCE_LEAVES
                || base == Block.ICE && type != MobType.POLAR_BEAR) {
            return false;
        }
        if (type.category() == MobCategory.MONSTER) {
            if (!isNightDark(time) && !world.hasWeatherRoof(blockX, y + 0.5f, blockZ)) {
                return false;
            }
            if (requiresOpenSky(type) && world.hasWeatherRoof(blockX, y + 1, blockZ)) {
                return false;
            }
        } else if (!allowsCreatureGround(type, ground, world, blockX, blockY, blockZ, time)) {
            return false;
        }
        return hasClearance(world, x, y, z, type.width(), type.height());
    }

    /** Các biến thể khí hậu đêm chỉ sinh trực tiếp dưới bầu trời. */
    private static boolean requiresOpenSky(MobType type) {
        return type == MobType.HUSK || type == MobType.PARCHED || type == MobType.STRAY || type == MobType.CAMEL_HUSK;
    }

    /**
     * Kiểm tra nền của thú theo loài và khí hậu, kể cả tuyết mỏng nằm trên nền
     * cứng.
     */
    private static boolean allowsCreatureGround(MobType type, Block ground, World world, int x, int y, int z,
            WorldTime time) {
        BiomeType biome = world.getBiome(x, z);
        if (type == MobType.CAMEL) {
            return biome == BiomeType.DESERT && ground == Block.SAND;
        }
        if (biome.hasRain()) {
            return ground == Block.GRASS && isDaylight(time);
        }
        if (biome == BiomeType.DESERT) {
            return ground == Block.SAND || ground == Block.GRASS;
        }
        boolean snow = ground == Block.SNOW_BLOCK || ground == Block.SNOW_LAYER
                || world.getBlock(x, y + 1, z) == Block.SNOW_LAYER.getId();
        if (type == MobType.POLAR_BEAR) {
            return snow || ground == Block.ICE;
        }
        if (type == MobType.GOAT) {
            return snow || ground == Block.STONE || ground == Block.GRAVEL || ground == Block.GRASS;
        }
        return snow || ground == Block.GRASS;
    }

    /**
     * Quét hộp va chạm nguyên chiều rộng và cao, chặn cả chất lỏng và thực thể
     * sống.
     */
    private boolean hasClearance(World world, float x, float y, float z, float width, float height) {
        float half = width * 0.5f;
        float minX = x - half;
        float maxX = x + half;
        float minZ = z - half;
        float maxZ = z + half;
        float top = y + height;
        if (minX < 0 || maxX > World.WORLD_SIZE_X || minZ < 0 || maxZ > World.WORLD_SIZE_Z
                || top > World.WORLD_SIZE_Y) {
            return false;
        }
        int y1 = MathUtils.floor(top - EPSILON);
        int z0 = MathUtils.floor(minZ + EPSILON);
        int z1 = MathUtils.floor(maxZ - EPSILON);
        int x1 = MathUtils.floor(maxX - EPSILON);
        for (int bx = MathUtils.floor(minX + EPSILON); bx <= x1; bx++) {
            for (int by = MathUtils.floor(y + EPSILON); by <= y1; by++) {
                for (int bz = z0; bz <= z1; bz++) {
                    Block block = Block.fromId(world.getBlock(bx, by, bz));
                    Block.Bounds bounds = block.getCollisionBounds(world.getBlockState(bx, by, bz));
                    if (block.isLiquid() || block == Block.CACTUS || bounds != null
                            && bx + bounds.maxX() > minX + EPSILON && bx + bounds.minX() < maxX - EPSILON
                            && bz + bounds.maxZ() > minZ + EPSILON && bz + bounds.minZ() < maxZ - EPSILON
                            && by + bounds.maxY() > y + EPSILON && by + bounds.minY() < top - EPSILON) {
                        return false;
                    }
                }
            }
        }
        return !world.hasLivingOverlap(x, y, z, half, height, null);
    }

    /**
     * Đánh giá bóng đêm theo tick và cao độ mặt trời hiện có, không thêm lưới ánh
     * sáng.
     */
    public static boolean isNightDark(WorldTime time) {
        int tick = time.tickOfDay();
        return (tick >= 13_000 && tick <= 23_000) || time.sunY() < -0.15f;
    }

    /** Ban ngày từ bình minh tới hoàng hôn là điều kiện sinh thú đồng bằng. */
    private static boolean isDaylight(WorldTime time) {
        return time.tickOfDay() < 12_000;
    }

    /** Tính khoảng cách chân trong vành hoạt động mà không tạo bản sao tọa độ. */
    public float distanceSquared(MobEntity mob, Player player) {
        // Các ghế cùng vùng hoạt động với thú cưỡi, kể cả ở sát ranh 128 block.
        MobEntity origin = mob.getMount() instanceof MobEntity mount ? mount : mob;
        return player.copyPosition(playerPosition).dst2(origin.x(), origin.y(), origin.z());
    }

    /** Hai loại thú cưỡi tự nhiên được thu hồi cùng kỵ sĩ chưa lưu giữ. */
    public static boolean isNaturalJockeyMount(MobEntity mob) {
        return mob.type() == MobType.CAMEL_HUSK || mob.type() == MobType.SPIDER;
    }

    /** Kiểm tra tức thì ở xa và rút thăm ở từng tick 20 Hz đã trôi sau 30 giây. */
    public boolean shouldDespawn(MobEntity mob, float distance, float dt) {
        if (!mob.isAlive() || mob.type().category() != MobCategory.MONSTER || mob.isPersistent()) {
            return false;
        }
        // Lạc đà xác sống quyết định khi nào thu hồi cả bộ kỵ sĩ.
        if (mob.getMount() instanceof MobEntity mount && isNaturalJockeyMount(mount)) {
            return false;
        }
        if (distance > MAX_DISTANCE_SQUARED) {
            return true;
        }
        if (distance < MIN_DESPAWN_DISTANCE_SQUARED) {
            mob.setNoActionTime(0);
            return false;
        }
        if (!(dt > 0) || !Float.isFinite(dt)) {
            return false;
        }
        float previous = mob.noActionTime();
        float current = previous + dt;
        mob.setNoActionTime(current);
        int from = Math.max(DESPAWN_DELAY_TICKS, (int) (previous * TICKS_PER_SECOND));
        int to = (int) (current * TICKS_PER_SECOND);
        for (int tick = from; tick < to; tick++) {
            if (despawnRandom.nextInt(DESPAWN_CHANCE_DIVISOR) == 0) {
                return true;
            }
        }
        return false;
    }
}

package com.voxelgame.world.entity.mob;

