package com.voxelgame.world.entity.mob;

import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.ai.MobGoal;
import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.monster.Skeleton;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.World;
import com.voxelgame.world.physics.Raycast;

import com.badlogic.gdx.math.Vector3;

/** Dùng chung điểm ngắm, kiểm tra vật cản, giương vũ khí và hồi chiêu cho quái thù địch đánh xa. */
public abstract class RangedMob extends HostileMob {
    /** Bán kính giữ mục tiêu cũ rộng hơn vùng phát hiện để tránh mất mục tiêu ở ngay mép. */
    private static final float RETAIN_DISTANCE = 2f;
    /** Thời gian bay ngắn nhất khi hai thực thể gần như cùng một cột. */
    private static final float MIN_FLIGHT_TIME = 0.075f;

    private final float detectionRangeSquared;
    private final float retentionRangeSquared;
    private final float attackRangeSquared;
    private final float preparationSeconds;
    private final float shotSpeed;
    private final float shotGravity;

    /** Bộ đệm phục vụ giữ mục tiêu, thử tia và tính vận tốc đạn. */
    private final Vector3 aimPoint = new Vector3();
    private final Vector3 shotOrigin = new Vector3();
    private final Vector3 displacement = new Vector3();
    private final Raycast.HitResult occluder = Raycast.HitResult.miss();

    /** Hồi chiêu không bị xóa khi đổi mục tiêu hoặc chuyển giữa đứng và cưỡi. */
    private double shotReadyAt;
    private double chargeSince;
    private LivingEntity chargingTarget;

    /** Lắp các goal nền, bỏ cận chiến và dùng các giới hạn riêng của vũ khí. */
    protected RangedMob(MobType type, float x, float y, float z, float detectionRange, float attackRange,
              float preparationSeconds, float shotSpeed, float shotGravity) {
        super(type, x, y, z, 0f, 0, false);
        detectionRangeSquared = detectionRange * detectionRange;
        float retentionRange = detectionRange + RETAIN_DISTANCE;
        retentionRangeSquared = retentionRange * retentionRange;
        attackRangeSquared = attackRange * attackRange;
        this.preparationSeconds = preparationSeconds;
        this.shotSpeed = shotSpeed;
        this.shotGravity = shotGravity;
        setMoveSpeed(2.5f);
        MobGoals.addDefaults(goals(), type, false);
        goals().add(new RangedAttackGoal());
    }

    /** Chọn mục tiêu một lần trước khi bộ chọn phân quyền cho tháo chạy, phòng vệ hoặc bắn. */
    @Override
    protected final void updateGoals(World world, float dt) {
        refreshTarget(world);
        super.updateGoals(world, dt);
    }

    /** Khi đang cưỡi, tiếp tục ngắm và bắn; ghế vẫn quyết định toàn bộ vị trí của cá thể. */
    @Override
    protected final void updateMounted(World world, float dt) {
        refreshTarget(world);
        LivingEntity target = target();
        if (target != null) {
            updateAttack(world, target, true);
        } else {
            clearAim();
        }
    }

    /** Giữ mục tiêu trả đũa đã được gán và chỉ tự tìm người chơi khi chưa có mục tiêu. */
    private void refreshTarget(World world) {
        LivingEntity activeTarget = target();
        if (activeTarget != null && activeTarget.isAlive()
                && distanceSquared(activeTarget) <= retentionRangeSquared) {
            return;
        }
        setTarget(null);
        Player player = world.getPlayer();
        if (player != null && player.isAlive()
                && distanceSquared(player) <= detectionRangeSquared && lineClear(world)) {
            setTarget(player);
        }
    }

    /** Trả bình phương khoảng cách từ tâm mob đến mục tiêu và giữ tọa độ ngắm. */
    protected final float distanceSquared(LivingEntity target) {
        target.copyCenterPosition(aimPoint);
        float dx = aimPoint.x - x();
        float dy = aimPoint.y - (y() + getHeight() * 0.5f);
        float dz = aimPoint.z - z();
        return dx * dx + dy * dy + dz * dz;
    }

    /** Kiểm tra đá hoặc khối rắn khác chắn giữa vị trí phóng và tâm mục tiêu. */
    private boolean lineClear(World world) {
        shotOrigin.set(x(), y() + getHeight() * 0.78f, z());
        displacement.set(aimPoint).sub(shotOrigin);
        float distance = displacement.len();
        return distance <= 0.0001f
                || !Raycast.castOccluder(world, shotOrigin, displacement, distance, occluder).isHit();
    }

    /** Bám chân mục tiêu, giữ tư thế ngắm, và tạo đạn sau khi đủ thời gian chuẩn bị. */
    private void updateAttack(World world, LivingEntity target, boolean mounted) {
        float distanceSquared = distanceSquared(target);
        boolean canShoot = distanceSquared <= attackRangeSquared && lineClear(world);
        float targetFeetY = aimPoint.y - target.getHeight() * 0.5f;
        lookAt(aimPoint.x, targetFeetY + target.getHeight() * 0.8f, aimPoint.z);
        if (canShoot) {
            faceBody(aimPoint.x, aimPoint.z);
        }
        if (!mounted) {
            if (canShoot) {
                moveWhileAiming(world, aimPoint.x, aimPoint.z);
            } else {
                moveToward(world, aimPoint.x, targetFeetY, aimPoint.z, 1f);
            }
        }
        if (!canShoot) {
            clearAim();
            return;
        }
        double now = ageSeconds();
        if (chargingTarget != target) {
            chargingTarget = target;
            chargeSince = now;
        }
        float aimProgress = Math.max(0f, Math.min(1f, (float) (now - chargeSince) / preparationSeconds));
        if (now >= shotReadyAt && aimProgress >= 1f) {
            launch(world, target, (float) Math.sqrt(distanceSquared));
            shotReadyAt = now + intervalSeconds(distanceSquared);
            // Cung nhả dây ngay khi phóng tên, rồi bắt đầu kéo đủ 20 tick trước phát kế.
            if (this instanceof Skeleton) {
                chargeSince = Math.max(now, shotReadyAt - preparationSeconds);
                aimProgress = 0f;
            } else {
                chargeSince = now;
            }
        }
        applyAimPose(aimProgress);
    }

    /** Tính thời gian bay theo khoảng cách ngang và bù độ rơi của đạn trong đúng khoảng đó. */
    private void launch(World world, LivingEntity target, float distance) {
        float horizontalDistance = (float) Math.sqrt(displacement.x * displacement.x + displacement.z * displacement.z);
        float flightTime = Math.max(MIN_FLIGHT_TIME, horizontalDistance / shotSpeed);
        float vx = displacement.x / flightTime;
        float vy = displacement.y / flightTime + shotGravity * flightTime * 0.5f;
        float vz = displacement.z / flightTime;
        fire(world, target, distance, shotOrigin.x, shotOrigin.y, shotOrigin.z, vx, vy, vz);
    }

    /** Hạ vũ khí khi mất tầm ngắm hoặc bị một hành vi ưu tiên cao hơn ngắt. */
    private void clearAim() {
        chargingTarget = null;
        mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
    }

    /** Tùy chỉnh cách đứng hoặc đi trong lúc ngắm; mặc định dừng tại chỗ. */
    protected void moveWhileAiming(World world, float targetX, float targetZ) {
        stopMoving();
    }

    /** Áp tư thế tay cho từng kiểu đánh xa. Tiến độ bằng không khi chưa giương vũ khí. */
    protected abstract void applyAimPose(float progress);

    /** Trả khoảng nghỉ giữa hai phát đạn, có thể phụ thuộc độ xa của đích. */
    protected abstract float intervalSeconds(float distanceSquared);

    /** Dựng loại đạn cụ thể và phát âm thanh lúc tung đòn. */
    protected abstract void fire(World world, LivingEntity target, float distance,
                       float x, float y, float z, float vx, float vy, float vz);

    /** Giữ riêng kênh di chuyển và nhìn khi bám mục tiêu tấn công. */
    private final class RangedAttackGoal implements MobGoal {
        /** Tháo chạy và tìm nơi trú được giành quyền trước đòn đánh xa. */
        @Override
        public int priority() { return 4; }

        /** Đường chạy và hướng nhìn phải do cùng một mục tiêu quyết định. */
        @Override
        public int controls() { return MOVE | LOOK; }

        /** Vào hành vi khi đã thấy người chơi hoặc được gán mục tiêu trả đũa. */
        @Override
        public boolean canStart(World world, MobEntity mob) { return target() != null; }

        /** Giữ tấn công khi mục tiêu chưa chết và chưa vượt tầm bám. */
        @Override
        public boolean shouldContinue(World world, MobEntity mob) { return canStart(world, mob); }

        /** Tiến độ giương bắt đầu ở lần kiểm tra tầm bắn đầu tiên. */
        @Override
        public void start(World world, MobEntity mob) {
        }

        /** Bám hoặc bắn vào đích hiện tại theo điều kiện vật cản. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            LivingEntity target = target();
            if (target != null) {
                updateAttack(world, target, false);
            }
        }

        /** Bỏ chuyển động ngang và giương vũ khí khi hành vi khác tiếp quản. */
        @Override
        public void stop(World world, MobEntity mob) {
            stopMoving();
            clearAim();
        }
    }
}

package com.voxelgame.world.entity.mob.ai;

import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.level.World;

/** Hành vi AI được cấp phát riêng cho một mob và tái sử dụng qua nhiều nhịp cập nhật. */
public interface MobGoal {
    /** Kênh điều hướng ngang, điều khiển điểm đích hoặc dừng lại. */
    int MOVE = 1;
    /** Kênh điều khiển hướng nhìn của đầu. */
    int LOOK = 1 << 1;
    /** Kênh điều khiển nhảy chủ động và bơi nổi. */
    int JUMP = 1 << 2;

    /** Số nhỏ hơn được xét trước và có quyền thay mục tiêu có số lớn hơn. */
    int priority();

    /** Trả tổ hợp kênh cần giữ trong toàn bộ thời gian mục tiêu hoạt động. */
    int controls();

    /** Khoảng nghỉ trước khi thử lại một mục tiêu dùng truy vấn tương đối tốn chi phí. */
    default float retrySeconds() {
        return 0f;
    }

    /** Kiểm tra điều kiện và chuẩn bị dữ liệu khi tất cả kênh có thể tiếp quản. */
    boolean canStart(World world, MobEntity mob);

    /** Kiểm tra mục tiêu đang chạy còn phải tiếp tục ở nhịp hiện tại hay không. */
    boolean shouldContinue(World world, MobEntity mob);

    /** Nhận quyền điều khiển sau khi mọi mục tiêu bị thay đã dừng. */
    void start(World world, MobEntity mob);

    /** Áp dụng hành vi cho nhịp đã được cấp quyền điều khiển. */
    void tick(World world, MobEntity mob, float dt);

    /** Dừng hành vi và bỏ yêu cầu điều khiển để mục tiêu mới tiếp quản. */
    void stop(World world, MobEntity mob);
}

package com.voxelgame.world.entity.mob.ai;

import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.level.World;

import java.util.ArrayList;
import java.util.Objects;

/** Điều phối mục tiêu theo ưu tiên và quyền điều khiển, dùng bộ nhớ đã có trong vòng cập nhật. */
public final class MobGoalSelector {
    /** Dãy sắp theo ưu tiên, dùng thứ tự đăng ký để chọn giữa các ứng viên đồng hạng. */
    private final ArrayList<Entry> entries = new ArrayList<>();

    /** Khóa đăng ký trong lúc các callback đang được gọi. */
    private boolean updating;

    /** Đăng ký một đối tượng mục tiêu cho cá thể hiện tại. */
    public void add(MobGoal goal) {
        Objects.requireNonNull(goal);
        if (updating) {
            throw new IllegalStateException("Không thể đăng ký mục tiêu ngay trong nhịp cập nhật");
        }
        int priority = goal.priority();
        int insertion = entries.size();
        for (int i = 0; i < entries.size(); i++) {
            Entry entry = entries.get(i);
            if (entry.goal == goal) {
                return;
            }
            if (priority < entry.priority && insertion == entries.size()) {
                insertion = i;
            }
        }
        entries.add(insertion, new Entry(goal, priority));
    }

    /** Giải phóng kênh hết hạn, chọn mục tiêu đủ điều kiện, rồi cập nhật các mục tiêu đã chọn. */
    public void tick(World world, MobEntity mob, float dt) {
        if (!(dt > 0f) || !Float.isFinite(dt)) {
            return;
        }
        if (updating) {
            throw new IllegalStateException("Không thể lồng các nhịp cập nhật mục tiêu");
        }
        updating = true;
        try {
            int count = entries.size();
            for (int i = 0; i < count; i++) {
                Entry entry = entries.get(i);
                entry.retryRemaining = Math.max(0f, entry.retryRemaining - dt);
                if (entry.running && !entry.goal.shouldContinue(world, mob)) {
                    stop(entry, world, mob);
                }
            }
            for (int i = 0; i < count; i++) {
                Entry candidate = entries.get(i);
                if (candidate.running || candidate.retryRemaining > 0f || isBlocked(candidate)) {
                    continue;
                }
                candidate.retryRemaining = candidate.goal.retrySeconds();
                if (candidate.goal.canStart(world, mob)) {
                    for (int j = i + 1; j < count; j++) {
                        Entry running = entries.get(j);
                        if (running.running && (running.controls & candidate.controls) != 0) {
                            stop(running, world, mob);
                        }
                    }
                    candidate.running = true;
                    candidate.goal.start(world, mob);
                }
            }
            for (int i = 0; i < count; i++) {
                Entry entry = entries.get(i);
                if (entry.running) {
                    entry.goal.tick(world, mob, dt);
                }
            }
        } finally {
            updating = false;
        }
    }

    /** Dừng mọi mục tiêu hoạt động, ví dụ khi mob nhận điều khiển trực tiếp từ người cưỡi. */
    public void stopAll(World world, MobEntity mob) {
        if (updating) {
            throw new IllegalStateException("Không thể dừng bộ chọn ngay trong nhịp cập nhật");
        }
        updating = true;
        try {
            for (int i = 0; i < entries.size(); i++) {
                Entry entry = entries.get(i);
                if (entry.running) {
                    stop(entry, world, mob);
                }
            }
        } finally {
            updating = false;
        }
    }

    /** Mục tiêu ưu tiên bằng hoặc cao hơn đã giữ kênh thì ứng viên chờ đến nhịp khác. */
    private boolean isBlocked(Entry candidate) {
        for (int i = 0; i < entries.size(); i++) {
            Entry entry = entries.get(i);
            if (entry.priority > candidate.priority) {
                break;
            }
            if (entry.running && (entry.controls & candidate.controls) != 0) {
                return true;
            }
        }
        return false;
    }

    /** Xóa trạng thái đang chạy trước khi gọi hành vi kết thúc. */
    private static void stop(Entry entry, World world, MobEntity mob) {
        entry.running = false;
        entry.goal.stop(world, mob);
    }

    /** Siêu dữ liệu cố định và bộ đếm tái thử của mỗi mục tiêu. */
    private static final class Entry {
        private final MobGoal goal;
        private final int priority;
        private final int controls;
        private float retryRemaining;
        private boolean running;

        /** Chụp ưu tiên và các kênh khi đăng ký, dùng nguyên trạng đến khi bỏ bộ chọn. */
        private Entry(MobGoal goal, int priority) {
            this.goal = goal;
            this.priority = priority;
            controls = goal.controls();
        }
    }
}

package com.voxelgame.world.entity.mob.ai;

import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.MobAttitude;
import com.voxelgame.world.entity.mob.MobCategory;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.monster.Zombie;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;
import com.voxelgame.world.physics.Raycast;

import com.badlogic.gdx.math.Vector3;
import java.util.Arrays;
import java.util.Objects;
import java.util.concurrent.ThreadLocalRandom;
import java.util.function.Predicate;

/** Các mục tiêu nền tảng để lớp hành vi của từng loài ghép theo nhu cầu. */
public final class MobGoals {
    /** Số ô đích ngẫu nhiên được thử tối đa mỗi lần tìm đường đi lang thang hoặc bỏ chạy. */
    private static final int DESTINATION_ATTEMPTS = 12;
    /** Lớp tập hợp các mục tiêu không có trạng thái dùng chung giữa cá thể. */
    private MobGoals() {
    }

    /** Gắn các hành vi chung theo ưu tiên, để lớp cụ thể có thể bổ sung hành vi đặc thù. */
    public static void addDefaults(MobGoalSelector selector, MobType type) {
        addDefaults(selector, type, true);
    }

    /** Cho phép loài có cách tấn công riêng giữ hành vi chung và tự chọn mục tiêu chiến đấu. */
    public static void addDefaults(MobGoalSelector selector, MobType type, boolean includeMelee) {
        selector.add(new FloatInWaterGoal(0));
        if (type.burnsInSunlight()) {
            selector.add(new SunlightShelterGoal(1));
        }
        if (type.attitude() == MobAttitude.PASSIVE) {
            selector.add(new PanicGoal(2));
        } else if (includeMelee) {
            selector.add(new MeleeAttackGoal(4, 1.2f, 2f, 0.95f, 1f, 20f));
        }
        switch (type) {
            case SKELETON, STRAY -> selector.add(new FleeEntityGoal(3, 6f, 1.25f,
                    entity -> entity instanceof MobEntity animal && animal.type() == MobType.WOLF));
            case RABBIT, SNOW_RABBIT -> {
                selector.add(new FleeEntityGoal(3, 8f, 1.25f, entity ->
                        (entity instanceof Player player && !holdsItem(player, MobGoals::isRabbitLure))
                        || (entity instanceof MobEntity animal
                        && (animal.type() == MobType.WOLF || animal.type().category() == MobCategory.MONSTER))));
                selector.add(new TemptFollowGoal(5, MobGoals::isRabbitLure, 10f, 0.8f));
            }
            case SNOW_FOX -> selector.add(new FleeEntityGoal(3, 8f, 1.25f,
                    entity -> entity instanceof Player player && !player.isSneaking()));
            case CAMEL -> selector.add(new TemptFollowGoal(5, Block.CACTUS, 10f, 0.85f));
            default -> {
                // Các loài còn lại dùng nhóm mục tiêu chung ở trên.
            }
        }
        selector.add(new WanderGoal(6, 9, 0.7f));
        selector.add(new LookAtPlayerGoal(7, 8f));
        selector.add(new RandomLookAroundGoal(8));
    }

    /** Đọc khoảng cách bình phương đến tâm đã được chép vào bộ đệm. */
    private static float distanceSquared(MobEntity mob, Vector3 center) {
        float dx = center.x - mob.x();
        float dy = center.y - (mob.y() + mob.getHeight() * 0.5f);
        float dz = center.z - mob.z();
        return dx * dx + dy * dy + dz * dz;
    }

    /** Vật phẩm dụ thỏ mặc định: bồ công anh hoặc cà rốt. */
    private static boolean isRabbitLure(Item item) {
        return item == Item.CARROT || item == Item.of(Block.DANDELION);
    }

    /** Xem đúng ô Hotbar đang chọn của người chơi và chỉ nhận vật phẩm thỏa điều kiện còn số lượng. */
    private static boolean holdsItem(Player player, Predicate<Item> matches) {
        return player.getHotbar().getSelectedCount() > 0 && matches.test(player.getHotbar().getSelectedItem());
    }

    /** Đổi tọa độ sang ô voxel, kể cả phía ngoài mép đang kiểm tra. */
    private static int floor(float value) {
        return (int) Math.floor(value);
    }

    /** Cấu hình quyền điều khiển và móc vòng đời mặc định cho mục tiêu đơn giản. */
    private abstract static class Goal implements MobGoal {
        private final int priority;
        private final int controls;

        /** Lưu các thuộc tính cố định dùng trong bộ chọn. */
        private Goal(int priority, int controls) {
            this.priority = priority;
            this.controls = controls;
        }

        /** Đọc mức ưu tiên lúc đăng ký. */
        @Override
        public final int priority() {
            return priority;
        }

        /** Đọc nhóm kênh mục tiêu cần điều khiển. */
        @Override
        public final int controls() {
            return controls;
        }

        /** Hành vi đơn giản giữ quyền khi điều kiện kích hoạt vẫn đúng. */
        @Override
        public boolean shouldContinue(World world, MobEntity mob) {
            return canStart(world, mob);
        }

        /** Mục tiêu chỉ thay điều khiển trong tick có thể dùng móc khởi động rỗng. */
        @Override
        public void start(World world, MobEntity mob) {
        }

        /** Mục tiêu chỉ điều khiển một nhịp có thể dùng móc kết thúc rỗng. */
        @Override
        public void stop(World world, MobEntity mob) {
        }
    }

    /** Hành vi có sở hữu đường đi và bỏ yêu cầu điều hướng khi bị thay thế. */
    private abstract static class MovementGoal extends Goal {
        /** Giữ kênh di chuyển và các kênh bổ sung do hành vi sử dụng. */
        private MovementGoal(int priority, int extraControls) {
            super(priority, MOVE | extraControls);
        }

        /** Dọn điểm đích trước khi giao kênh di chuyển cho hành vi khác. */
        @Override
        public void stop(World world, MobEntity mob) {
            mob.stopMoving();
        }
    }

    /** Bộ đệm tọa độ đích và tập phép chọn ô hợp lệ dùng lại nhiều lượt. */
    private static final class Destination {
        private float x;
        private float y;
        private float z;

        /** Giữ tâm ngang và cao độ chân của ô đích. */
        private void set(int x, float y, int z) {
            this.x = x + 0.5f;
            this.y = y;
            this.z = z + 0.5f;
        }

        /** Chọn ô ngẫu nhiên hợp lệ, có thể ưu tiên hướng rời khỏi một mối đe dọa. */
        private boolean sample(World world, MobEntity mob, int radius, float awayX, float awayZ) {
            ThreadLocalRandom random = ThreadLocalRandom.current();
            int baseX = floor(mob.x());
            int baseY = floor(mob.y());
            int baseZ = floor(mob.z());
            boolean directional = Math.abs(awayX) + Math.abs(awayZ) > 0.001f;
            float bestAlignment = 0f;
            boolean found = false;
            for (int i = 0; i < DESTINATION_ATTEMPTS; i++) {
                int dx = random.nextInt(-radius, radius + 1);
                int dz = random.nextInt(-radius, radius + 1);
                int distance = dx * dx + dz * dz;
                if (distance < 4 || distance > radius * radius) {
                    continue;
                }
                float alignment = dx * awayX + dz * awayZ;
                if (directional && alignment <= bestAlignment) {
                    continue;
                }
                float feetY = mob.navigator().findStandableY(world, baseX + dx, baseY, baseZ + dz);
                if (Float.isFinite(feetY)) {
                    set(baseX + dx, feetY, baseZ + dz);
                    if (!directional) {
                        return true;
                    }
                    bestAlignment = alignment;
                    found = true;
                }
            }
            return found;
        }

        /** Nhận đích khi tâm đã vào gần ô và cao độ đã khớp địa hình của điểm đến. */
        private boolean reached(MobEntity mob) {
            float dx = x - mob.x();
            float dz = z - mob.z();
            return dx * dx + dz * dz <= 0.16f && Math.abs(y - mob.y()) <= 1f;
        }

        /** Giao tọa độ đích cho bộ điều hướng chịu trách nhiệm tránh vật cản. */
        private void move(World world, MobEntity mob, float speed) {
            mob.moveToward(world, x, y, z, speed);
        }
    }

    /** Nhấc người khi ở trong nước, đồng thời vẫn cho mục tiêu khác điều khiển hướng ngang. */
    public static final class FloatInWaterGoal extends Goal {
        /** Thiết lập ưu tiên của kênh bơi. */
        public FloatInWaterGoal(int priority) {
            super(priority, JUMP);
        }

        /** Bơi nổi khi phần cần kiểm tra của thực thể đang ngập nước. */
        @Override
        public boolean canStart(World world, MobEntity mob) {
            return mob.inWater();
        }

        /** Yêu cầu lực nổi trong đúng nhịp vật lý hiện tại của mob. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            mob.requestFloat();
        }
    }

    /** Tìm chỗ có mái hoặc nước gần nhất theo từng nhóm nhỏ ô đã sắp theo khoảng cách. */
    public static final class SunlightShelterGoal extends MovementGoal {
        /** Bán kính tìm kiếm, ngân sách mỗi lần xét và thời gian tối đa cho một đường chạy. */
        private static final int SEARCH_RADIUS = 7;
        private static final int CELLS_PER_SEARCH = 20;
        private static final float MAX_ROUTE_SECONDS = 5f;
        private static final float CLOSE_COMBAT_RANGE_SQUARED = 8f * 8f;
        private static final int[] OFFSETS = sortedOffsets();

        private final Destination destination = new Destination();
        private int originX;
        private int originY;
        private int originZ;
        private int nextOffset;
        private float remaining;
        private boolean searching;
        private final Vector3 combatTarget = new Vector3();

        /** Gắn hành vi tìm nơi trú tránh cháy nắng. */
        public SunlightShelterGoal(int priority) {
            super(priority, 0);
        }

        /** Chuẩn bị danh sách ô theo bình phương khoảng cách, chỉ cấp phát khi nạp lớp. */
        private static int[] sortedOffsets() {
            int limit = SEARCH_RADIUS * SEARCH_RADIUS;
            int[] pairs = new int[2 * ((2 * SEARCH_RADIUS + 1) * (2 * SEARCH_RADIUS + 1) - 1)];
            int size = 0;
            for (int distance = 1; distance <= limit; distance++) {
                for (int dx = -SEARCH_RADIUS; dx <= SEARCH_RADIUS; dx++) {
                    for (int dz = -SEARCH_RADIUS; dz <= SEARCH_RADIUS; dz++) {
                        if (dx * dx + dz * dz == distance) {
                            pairs[size++] = dx;
                            pairs[size++] = dz;
                        }
                    }
                }
            }
            return Arrays.copyOf(pairs, size);
        }

        /** Chia lượt tìm bóng râm ra nhiều nhịp, tránh quét cả vùng trong một frame. */
        @Override
        public float retrySeconds() {
            return 0.10f + ThreadLocalRandom.current().nextFloat() * 0.04f;
        }

        /** Chọn ô râm mát hoặc nước đầu tiên có thể dùng theo thứ tự gần đến xa. */
        @Override
        public boolean canStart(World world, MobEntity mob) {
            if (!needsShelter(world, mob)) {
                searching = false;
                return false;
            }
            int mobX = floor(mob.x());
            int mobY = floor(mob.y());
            int mobZ = floor(mob.z());
            if (!searching || Math.abs(mobX - originX) > 2 || Math.abs(mobY - originY) > 1
                    || Math.abs(mobZ - originZ) > 2) {
                originX = mobX;
                originY = mobY;
                originZ = mobZ;
                nextOffset = 0;
                searching = true;
            }
            for (int i = 0; i < CELLS_PER_SEARCH && nextOffset < OFFSETS.length; i++) {
                int x = originX + OFFSETS[nextOffset++];
                int z = originZ + OFFSETS[nextOffset++];
                float feetY = findShelter(world, mob, x, z);
                if (Float.isFinite(feetY)) {
                    destination.set(x, feetY, z);
                    return true;
                }
            }
            searching = nextOffset < OFFSETS.length;
            return false;
        }

        /** Bỏ cột trống sớm, rồi xác minh nước hoặc mái che tại cao độ đứng thực. */
        private float findShelter(World world, MobEntity mob, int x, int z) {
            boolean water = false;
            for (int y = originY; y >= originY - 3 && !water; y--) {
                water = world.getBlock(x, y, z) == Block.WATER.getId();
            }
            float headOffset = mob.getHeight();
            if (!water && !world.hasWeatherRoof(x, originY - 3 + headOffset, z)) {
                return Float.NaN;
            }
            float feetY = mob.navigator().findStandableY(world, x, originY, z);
            if (!Float.isFinite(feetY)) {
                return Float.NaN;
            }
            return world.getBlock(x, floor(feetY + 0.1f), z) == Block.WATER.getId()
                    || world.hasWeatherRoof(x, feetY + headOffset, z) ? feetY : Float.NaN;
        }

        /** Nhả kênh di chuyển ngay khi hết phơi nắng hoặc cần đánh mục tiêu ở gần. */
        @Override
        public boolean shouldContinue(World world, MobEntity mob) {
            return remaining > 0f && !destination.reached(mob) && needsShelter(world, mob);
        }

        /** Zombie đang áp sát mục tiêu ưu tiên cận chiến, kể cả khi còn ở ngoài nắng. */
        private boolean needsShelter(World world, MobEntity mob) {
            if (!mob.burnsInSunlight() || mob.getFireTimer() <= 0f || !mob.isSunExposed(world)) {
                return false;
            }
            LivingEntity target = mob.target();
            return !(mob instanceof Zombie) || target == null || !target.isAlive()
                    || distanceSquared(mob, target.copyCenterPosition(combatTarget)) > CLOSE_COMBAT_RANGE_SQUARED;
        }

        /** Giới hạn thời gian cố bám một chỗ trú bị chặn bởi địa hình. */
        @Override
        public void start(World world, MobEntity mob) {
            remaining = MAX_ROUTE_SECONDS;
        }

        /** Tiếp tục chạy tới bóng râm hoặc điểm nước đã chọn. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            remaining -= dt;
            destination.move(world, mob, 1.1f);
        }
    }

    /** Chạy nhanh hơn 25% trong cửa sổ hoảng loạn do MobEntity tạo khi trúng đòn. */
    public static final class PanicGoal extends MovementGoal {
        /** Bán kính điểm chạy tán loạn. */
        private static final int RADIUS = 7;
        private final Destination destination = new Destination();
        private final Vector3 attackerCenter = new Vector3();

        /** Gắn ưu tiên phản ứng bị thương cho mob hiền. */
        public PanicGoal(int priority) {
            super(priority, 0);
        }

        /** Cách một khoảng ngắn trước khi xét lại địa hình không có ô chạy hợp lệ. */
        @Override
        public float retrySeconds() {
            return 0.15f;
        }

        /** Chọn hướng tháo chạy sau một đòn đánh đã trúng. */
        @Override
        public boolean canStart(World world, MobEntity mob) {
            return mob.panicTime() > 0f && findEscape(world, mob);
        }

        /** Giữ trạng thái chạy trong suốt cửa sổ hoảng loạn. */
        @Override
        public boolean shouldContinue(World world, MobEntity mob) {
            return mob.panicTime() > 0f;
        }

        /** Đổi đích nếu đã đến nơi mà cửa sổ hoảng loạn vẫn còn. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            if (!destination.reached(mob) || findEscape(world, mob)) {
                destination.move(world, mob, 1.25f);
            } else {
                mob.stopMoving();
            }
        }

        /** Ưu tiên rời khỏi nguồn đánh và chọn hướng bất kỳ nếu đường đó bị chặn. */
        private boolean findEscape(World world, MobEntity mob) {
            Entity attacker = mob.lastAttacker();
            if (attacker != null) {
                attacker.copyCenterPosition(attackerCenter);
                if (destination.sample(world, mob, RADIUS, mob.x() - attackerCenter.x, mob.z() - attackerCenter.z)) {
                    return true;
                }
            }
            return destination.sample(world, mob, RADIUS, 0f, 0f);
        }
    }

    /** Bỏ chạy khỏi thực thể thỏa điều kiện của loài, kiểm tra đối tượng còn sống trong bán kính. */
    public static final class FleeEntityGoal extends MovementGoal {
        private final float rangeSquared;
        private final int escapeRadius;
        private final float speed;
        private final Predicate<LivingEntity> matches;
        private final Vector3 center = new Vector3();
        private final Destination destination = new Destination();
        private LivingEntity threat;
        private float repathDelay;

        /** Cấu hình loại thực thể bị sợ, bán kính phát hiện và hệ số tốc độ chạy. */
        public FleeEntityGoal(int priority, float range, float speedMultiplier, Predicate<LivingEntity> matches) {
            super(priority, 0);
            rangeSquared = range * range;
            escapeRadius = Math.max(3, Math.min(10, (int) Math.ceil(range)));
            speed = speedMultiplier;
            this.matches = Objects.requireNonNull(matches);
        }

        /** Giới hạn tần suất truy vấn danh sách thực thể khi đang ở trạng thái bình thường. */
        @Override
        public float retrySeconds() {
            return 0.20f + ThreadLocalRandom.current().nextFloat() * 0.10f;
        }

        /** Tìm mối đe dọa gần nhất và ô đích nằm về hướng ngược lại. */
        @Override
        public boolean canStart(World world, MobEntity mob) {
            LivingEntity closest = null;
            float bestDistance = rangeSquared;
            Player player = world.getPlayer();
            if (player != null && player.isAlive() && matches.test(player)) {
                player.copyCenterPosition(center);
                float distance = distanceSquared(mob, center);
                if (distance <= bestDistance) {
                    bestDistance = distance;
                    closest = player;
                }
            }
            for (int i = 0, count = world.entityCount(); i < count; i++) {
                if (!(world.entityAt(i) instanceof LivingEntity other) || other == mob || other == player
                        || !other.isAlive() || !matches.test(other)) {
                    continue;
                }
                other.copyCenterPosition(center);
                float distance = distanceSquared(mob, center);
                if (distance <= bestDistance) {
                    bestDistance = distance;
                    closest = other;
                }
            }
            if (closest == null) {
                return false;
            }
            closest.copyCenterPosition(center);
            if (!destination.sample(world, mob, escapeRadius, mob.x() - center.x, mob.z() - center.z)) {
                return false;
            }
            threat = closest;
            return true;
        }

        /** Dừng nếu thực thể không còn đáng sợ, ví dụ người chơi vừa bắt đầu cúi rón rén. */
        @Override
        public boolean shouldContinue(World world, MobEntity mob) {
            if (threat == null || !threat.isAlive() || !matches.test(threat)) {
                return false;
            }
            threat.copyCenterPosition(center);
            return distanceSquared(mob, center) <= rangeSquared;
        }

        /** Bắt đầu nhịp cập nhật lại đích thoát hiểm. */
        @Override
        public void start(World world, MobEntity mob) {
            repathDelay = 0.45f;
        }

        /** Làm mới hướng tháo chạy để tránh chạy về phía đối tượng đang tiếp cận. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            repathDelay -= dt;
            if (repathDelay <= 0f) {
                threat.copyCenterPosition(center);
                destination.sample(world, mob, escapeRadius, mob.x() - center.x, mob.z() - center.z);
                repathDelay = 0.45f;
            }
            if (destination.reached(mob)) {
                mob.stopMoving();
            } else {
                destination.move(world, mob, speed);
            }
        }

        /** Bỏ tham chiếu mục tiêu cũ và trả điều khiển cho bộ chọn. */
        @Override
        public void stop(World world, MobEntity mob) {
            threat = null;
            super.stop(world, mob);
        }
    }

    /** Bám mục tiêu đã chọn qua bộ điều hướng và đánh cận chiến khi có đường đánh thông. */
    public static final class MeleeAttackGoal extends MovementGoal {
        private final float speed;
        private final float damage;
        private final float reach;
        private final float cooldownSeconds;
        private final float rangeSquared;
        private final Vector3 targetCenter = new Vector3();
        private final Vector3 origin = new Vector3();
        private final Vector3 direction = new Vector3();
        private final Raycast.HitResult occluder = Raycast.HitResult.miss();
        private double nextAttack;

        /** Cấu hình tốc độ bám, sát thương, tầm từ mép hộp, hồi chiêu và giới hạn đuổi. */
        public MeleeAttackGoal(int priority, float speedMultiplier, float damage, float reach,
                               float cooldownSeconds, float maxPursuitRange) {
            super(priority, LOOK);
            speed = speedMultiplier;
            this.damage = damage;
            this.reach = reach;
            this.cooldownSeconds = cooldownSeconds;
            rangeSquared = maxPursuitRange * maxPursuitRange;
        }

        /** Nhận mục tiêu còn sống trong khoảng truy đuổi của hành vi hiện tại. */
        @Override
        public boolean canStart(World world, MobEntity mob) {
            LivingEntity target = mob.target();
            if (target == null || target == mob || !target.isAlive()) {
                return false;
            }
            target.copyCenterPosition(targetCenter);
            return distanceSquared(mob, targetCenter) <= rangeSquared;
        }

        /** Bám mục tiêu qua điểm chân và chỉ đánh khi tia không bị địa hình chắn. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            LivingEntity target = mob.target();
            if (target == null || !target.isAlive()) {
                return;
            }
            target.copyCenterPosition(targetCenter);
            float targetY = targetCenter.y - target.getHeight() * 0.5f;
            mob.lookAt(targetCenter.x, targetY + target.getHeight() * 0.8f, targetCenter.z);
            float dx = targetCenter.x - mob.x();
            float dz = targetCenter.z - mob.z();
            float horizontalSquared = dx * dx + dz * dz;
            float allowed = reach + mob.getHalfWidth() + target.getHalfWidth();
            if (horizontalSquared > allowed * allowed || !inVerticalReach(mob, target, targetY)
                    || !canHit(world, mob)) {
                mob.moveToward(world, targetCenter.x, targetY, targetCenter.z, speed);
                return;
            }
            mob.stopMoving();
            double now = mob.ageSeconds();
            if (now >= nextAttack) {
                nextAttack = now + cooldownSeconds;
                float push = horizontalSquared > 0.000001f ? 2f / (float) Math.sqrt(horizontalSquared) : 0f;
                mob.strikeMelee(world, target, damage, dx * push, dz * push);
            }
        }

        /** Giới hạn cận chiến theo khoảng cách dọc giữa hai mép hộp va chạm. */
        private boolean inVerticalReach(MobEntity mob, LivingEntity target, float targetY) {
            return targetY - (mob.y() + mob.getHeight()) <= reach
                    && mob.y() - (targetY + target.getHeight()) <= reach;
        }

        /** Dùng bộ đệm tia sẵn có để ngăn đòn đánh xuyên tường. */
        private boolean canHit(World world, MobEntity mob) {
            origin.set(mob.x(), mob.y() + mob.getHeight() * 0.62f, mob.z());
            direction.set(targetCenter).sub(origin);
            float length = direction.len();
            return length <= 0.0001f || !Raycast.castOccluder(world, origin, direction, length, occluder).isHit();
        }
    }

    /** Đi theo người chơi đang chọn một hoặc nhiều loại vật phẩm đã cấu hình. */
    public static final class TemptFollowGoal extends MovementGoal {
        /** Khoảng cách ngang mà mob dừng lại để giữ một khoảng trống trước người chơi. */
        private static final float STOP_DISTANCE_SQUARED = 2.25f;
        private final Predicate<Item> lureMatches;
        private final float rangeSquared;
        private final float speed;
        private final Vector3 center = new Vector3();

        /** Gắn vật phẩm khối dụ theo loài, bán kính phản ứng và tốc độ đi theo. */
        public TemptFollowGoal(int priority, Block lure, float range, float speedMultiplier) {
            this(priority, item -> item == Item.of(Objects.requireNonNull(lure)), range, speedMultiplier);
        }

        /** Gắn một vật phẩm {@link Item} cụ thể làm mồi dụ, bán kính phản ứng và tốc độ đi theo. */
        public TemptFollowGoal(int priority, Item lure, float range, float speedMultiplier) {
            this(priority, item -> item == Objects.requireNonNull(lure), range, speedMultiplier);
        }

        /** Gắn bộ lọc {@link Predicate} trên vật phẩm cầm tay để hỗ trợ nhiều loại mồi dụ cùng lúc. */
        public TemptFollowGoal(int priority, Predicate<Item> lureMatches, float range, float speedMultiplier) {
            super(priority, LOOK);
            this.lureMatches = Objects.requireNonNull(lureMatches);
            rangeSquared = range * range;
            speed = speedMultiplier;
        }

        /** Chỉ phản ứng với vật phẩm trên ô Hotbar đang được chọn của người chơi sống. */
        @Override
        public boolean canStart(World world, MobEntity mob) {
            Player player = world.getPlayer();
            if (player == null || !player.isAlive() || !holdsItem(player, lureMatches)) {
                return false;
            }
            player.copyCenterPosition(center);
            return distanceSquared(mob, center) <= rangeSquared;
        }

        /** Tiến tới người chơi, rồi dừng trong khoảng ngắn để tránh ép vào hộp va chạm. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            Player player = world.getPlayer();
            player.copyCenterPosition(center);
            float feetY = center.y - player.getHeight() * 0.5f;
            mob.lookAt(center.x, feetY + player.getHeight() * 0.8f, center.z);
            float dx = center.x - mob.x();
            float dz = center.z - mob.z();
            if (dx * dx + dz * dz <= STOP_DISTANCE_SQUARED && Math.abs(feetY - mob.y()) <= 1f) {
                mob.stopMoving();
            } else {
                mob.moveToward(world, center.x, feetY, center.z, speed);
            }
        }
    }

    /** Đi lang thang đến một ô hợp lệ và nghỉ ngẫu nhiên giữa những lượt đi. */
    public static final class WanderGoal extends MovementGoal {
        /** Khoảng nghỉ đầu lệch pha giữa các cá thể vừa được tạo trong cùng bầy. */
        private static final float MIN_INITIAL_WAIT = 0.75f;
        private final Destination destination = new Destination();
        private final int radius;
        private final float speed;
        private double nextMove = MIN_INITIAL_WAIT + ThreadLocalRandom.current().nextFloat() * 2f;
        private double deadline;

        /** Cấu hình bán kính chọn điểm và hệ số tốc độ của lượt đi. */
        public WanderGoal(int priority, int radius, float speedMultiplier) {
            super(priority, 0);
            this.radius = Math.max(2, radius);
            speed = speedMultiplier;
        }

        /** Thử tìm đường khi đã hết nghỉ, lùi lần thử sau nếu địa hình quá hẹp. */
        @Override
        public boolean canStart(World world, MobEntity mob) {
            double now = mob.ageSeconds();
            if (now < nextMove) {
                return false;
            }
            if (!destination.sample(world, mob, radius, 0f, 0f)) {
                nextMove = now + 2f;
                return false;
            }
            return true;
        }

        /** Tiếp tục tới điểm đã chọn cho đến lúc chạm đích hoặc hết thời hạn đi. */
        @Override
        public boolean shouldContinue(World world, MobEntity mob) {
            return mob.ageSeconds() < deadline && !destination.reached(mob);
        }

        /** Cho lượt đi đủ thời gian theo tốc độ và bán kính đã cấu hình. */
        @Override
        public void start(World world, MobEntity mob) {
            deadline = mob.ageSeconds() + radius / Math.max(0.5f, mob.moveSpeed() * speed) + 2f;
        }

        /** Chuyển yêu cầu tiến về đích cho bộ điều hướng nhẹ. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            destination.move(world, mob, speed);
        }

        /** Nghỉ từ hai đến năm giây sau khi dừng hoặc nhường chỗ cho hành vi khác. */
        @Override
        public void stop(World world, MobEntity mob) {
            nextMove = mob.ageSeconds() + 2f + ThreadLocalRandom.current().nextFloat() * 3f;
            super.stop(world, mob);
        }
    }

    /** Theo dõi người chơi trong khoảng ngắn, để hành vi nhìn quanh có thời gian hoạt động. */
    public static final class LookAtPlayerGoal extends Goal {
        private final float rangeSquared;
        private final Vector3 center = new Vector3();
        private float eyeY;
        private double lookUntil;
        private double nextLook;

        /** Đặt bán kính để mob có thể quan sát người chơi. */
        public LookAtPlayerGoal(int priority, float range) {
            super(priority, LOOK);
            rangeSquared = range * range;
        }

        /** Bắt đầu quan sát khi đã hết nghỉ và người chơi ở trong phạm vi. */
        @Override
        public boolean canStart(World world, MobEntity mob) {
            return mob.ageSeconds() >= nextLook && playerInRange(world, mob);
        }

        /** Dừng khi hết nhịp nhìn hoặc người chơi rời vùng quan sát. */
        @Override
        public boolean shouldContinue(World world, MobEntity mob) {
            return mob.ageSeconds() < lookUntil && playerInRange(world, mob);
        }

        /** Chép vị trí người chơi vào bộ đệm để dùng tiếp trong nhịp xoay đầu. */
        private boolean playerInRange(World world, MobEntity mob) {
            Player player = world.getPlayer();
            if (player == null || !player.isAlive()) {
                return false;
            }
            player.copyCenterPosition(center);
            eyeY = center.y + player.getHeight() * 0.3f;
            return distanceSquared(mob, center) <= rangeSquared;
        }

        /** Giới hạn một lượt quan sát trong hai đến năm giây. */
        @Override
        public void start(World world, MobEntity mob) {
            lookUntil = mob.ageSeconds() + 2f + ThreadLocalRandom.current().nextFloat() * 3f;
        }

        /** Nội suy đầu về phía người chơi qua kênh hướng nhìn của MobEntity. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            mob.lookAt(center.x, eyeY, center.z);
        }

        /** Chừa một khoảng nghỉ trước khi nhìn lại. */
        @Override
        public void stop(World world, MobEntity mob) {
            nextLook = mob.ageSeconds() + 1f + ThreadLocalRandom.current().nextFloat() * 2f;
        }
    }

    /** Chọn một hướng ngang tự nhiên và giữ ngắn hạn khi không theo dõi mục tiêu khác. */
    public static final class RandomLookAroundGoal extends Goal {
        private float lookX;
        private float lookY;
        private float lookZ;
        private double lookUntil;
        private double nextLook = 0.5f + ThreadLocalRandom.current().nextFloat() * 2f;

        /** Đặt mức ưu tiên thấp cho chuyển động nhìn quanh khi rảnh. */
        public RandomLookAroundGoal(int priority) {
            super(priority, LOOK);
        }

        /** Chỉ chọn hướng mới khi đã đến hết khoảng nghỉ. */
        @Override
        public boolean canStart(World world, MobEntity mob) {
            return mob.ageSeconds() >= nextLook;
        }

        /** Duy trì hướng ngẫu nhiên đến hết thời gian nhìn. */
        @Override
        public boolean shouldContinue(World world, MobEntity mob) {
            return mob.ageSeconds() < lookUntil;
        }

        /** Chọn một điểm xa vài block và hơi lệch độ cao đầu của mob. */
        @Override
        public void start(World world, MobEntity mob) {
            ThreadLocalRandom random = ThreadLocalRandom.current();
            double angle = random.nextDouble(2 * Math.PI);
            lookX = (float) Math.cos(angle) * 5f;
            lookY = mob.getHeight() * 0.8f + random.nextFloat() * 0.8f - 0.4f;
            lookZ = (float) Math.sin(angle) * 5f;
            lookUntil = mob.ageSeconds() + 0.75f + random.nextFloat() * 1.5f;
        }

        /** Giữ hướng tương đối khi mob đồng thời di chuyển đến điểm khác. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            mob.lookAt(mob.x() + lookX, mob.y() + lookY, mob.z() + lookZ);
        }

        /** Hoãn lượt nhìn mới trong một đến bốn giây sau khi dừng. */
        @Override
        public void stop(World world, MobEntity mob) {
            nextLook = mob.ageSeconds() + 1f + ThreadLocalRandom.current().nextFloat() * 3f;
        }
    }
}

package com.voxelgame.world.entity.mob.ai;

import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MountableMob;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.MathUtils;

/** Dò tối đa hai vị trí phía trước và thử đổi hướng quanh các góc gần mob. */
public final class SimpleGridNavigator {
    /** Dung sai cho các mặt tiếp xúc, góc đổi hướng và khoảng đến đích. */
    private static final float EPSILON = 0.0001f;
    private static final float DIAGONAL = 0.70710677f;
    private static final float ARRIVAL_DISTANCE_SQUARED = 0.22f * 0.22f;

    /** Mob cung cấp tọa độ, hộp va chạm và giới hạn lên xuống bậc. */
    private final MobEntity mob;
    /** Trạng thái đích và phía vừa đi vòng để giữ hướng ổn định qua góc. */
    private boolean done = true;
    private int turnSide = 1;

    /** Tạo bộ điều hướng riêng cho một cá thể, không cần danh sách đường đi. */
    public SimpleGridNavigator(MobEntity mob) {
        this.mob = mob;
    }

    /** Trả trạng thái đã đến gần đích hoặc lệnh di chuyển đã dừng. */
    public boolean isDone() {
        return done;
    }

    /** Xóa trạng thái đích để goal khác có thể nhận quyền di chuyển. */
    public void stop() {
        done = true;
    }

    /**
     * Ưu tiên hướng đích, rồi thử góc 45 và 90 độ ở hai phía.
     * Khi đường chỉ thoáng ở đoạn gần, vẫn tiến tới đó để có thể dò lại ở vị trí mới.
     */
    public void moveToward(World world, float x, float z, float speed) {
        float dx = x - mob.x();
        float dz = z - mob.z();
        float distanceSquared = dx * dx + dz * dz;
        if (!(distanceSquared > ARRIVAL_DISTANCE_SQUARED) || !Float.isFinite(distanceSquared)
                || !(speed > 0f) || !Float.isFinite(speed)) {
            mob.stopMoving();
            return;
        }
        done = false;
        float distance = (float) Math.sqrt(distanceSquared);
        dx /= distance;
        dz /= distance;
        if (!mob.isOnGround() || mob.inWater()) {
            mob.steer(dx, dz, speed);
            return;
        }

        float near = Math.min(distance, 0.65f);
        float far = Math.min(distance, 1.30f);
        int direct = clearance(world, dx, dz, near, far);
        if (direct == 2) {
            mob.steer(dx, dz, speed);
            return;
        }
        float bestX = dx;
        float bestZ = dz;
        int best = direct;
        int bestSide = turnSide;
        for (int i = 0; i < 4; i++) {
            int side = (i & 1) == 0 ? turnSide : -turnSide;
            float turnX = -side * dz;
            float turnZ = side * dx;
            if (i < 2) {
                turnX = (dx + turnX) * DIAGONAL;
                turnZ = (dz + turnZ) * DIAGONAL;
            }
            int clear = clearance(world, turnX, turnZ, near, far);
            // Nếu hướng thẳng còn dùng được, tránh đi ngang chỉ vì chân trời gần bị chắn.
            if (clear > best && (i < 2 || direct == 0)) {
                best = clear;
                bestX = turnX;
                bestZ = turnZ;
                bestSide = side;
                if (best == 2) {
                    break;
                }
            }
        }
        if (best > 0) {
            turnSide = bestSide;
            mob.steer(bestX, bestZ, speed);
        } else {
            mob.steer(0f, 0f, 0f);
        }
    }

    /** Trả 0 khi đoạn đầu bị chặn, 1 khi chỉ đoạn đầu hợp lệ, 2 khi cả hai hợp lệ. */
    private int clearance(World world, float dx, float dz, float near, float far) {
        float x = mob.x();
        float y = mob.y();
        float z = mob.z();
        float first = findFeetY(world, x + dx * near, y, z + dz * near);
        if (!Float.isFinite(first) || (first > y + EPSILON && !canRise(world, x, y, z, first - y))) {
            return 0;
        }
        if (far == near || Float.isFinite(findFeetY(world, x + dx * far, first, z + dz * far))) {
            return 2;
        }
        return 1;
    }

    /** Tìm cao độ mặt đỡ gần mốc y ở tâm ô, hoặc trả NaN nếu không đứng được. */
    public float findStandableY(World world, int x, int y, int z) {
        return findFeetY(world, x + 0.5f, y, z + 0.5f);
    }

    /** Tìm mặt đỡ dưới toàn bộ dấu chân trong ngưỡng bậc lên và quãng rơi an toàn. */
    public float findFeetY(World world, float x, float referenceY, float z) {
        float highest = referenceY + mob.stepHeight();
        float lowest = referenceY - mob.maxSafeFall();
        float radius = mob.getHalfWidth();
        int minX = MathUtils.floor(x - radius + EPSILON);
        int maxX = MathUtils.floor(x + radius - EPSILON);
        int minZ = MathUtils.floor(z - radius + EPSILON);
        int maxZ = MathUtils.floor(z + radius - EPSILON);
        int minY = Math.max(0, MathUtils.floor(lowest) - 1);
        int maxY = Math.min(World.WORLD_SIZE_Y - 1, MathUtils.floor(highest - EPSILON));
        if (!world.isInsideWorld(minX, 0, minZ) || !world.isInsideWorld(maxX, 0, maxZ)) {
            return Float.NaN;
        }

        for (int y = maxY; y >= minY; y--) {
            float top = Float.NEGATIVE_INFINITY;
            for (int blockX = minX; blockX <= maxX; blockX++) {
                for (int blockZ = minZ; blockZ <= maxZ; blockZ++) {
                    byte id = world.getBlock(blockX, y, blockZ);
                    if (id == Block.WATER.getId()) {
                        // Mặt nước là điểm điều hướng của mob bơi, thú cưỡi cần nền thật.
                        if (!(mob instanceof MountableMob)) {
                            top = Math.max(top, y + 0.87f);
                        }
                    } else if (id != Block.AIR.getId() && id != Block.CACTUS.getId() && id != Block.LAVA.getId()) {
                        Block.Bounds bounds = world.getCollisionBounds(blockX, y, blockZ);
                        if (bounds != null && x + radius > blockX + bounds.minX()
                                && x - radius < blockX + bounds.maxX()
                                && z + radius > blockZ + bounds.minZ() && z - radius < blockZ + bounds.maxZ()) {
                            top = Math.max(top, y + bounds.maxY());
                        }
                    }
                }
            }
            if (top >= lowest - EPSILON && top <= highest + EPSILON
                    && bodyClear(world, x, top, z, top + mob.getHeight(), true)) {
                return top;
            }
        }
        return Float.NaN;
    }

    /** Kiểm tra cả thể tích quét dọc, kể cả trần nằm giữa vị trí đầu và vị trí nâng. */
    public boolean canRise(World world, float x, float y, float z, float rise) {
        return bodyClear(world, x, y, z, y + mob.getHeight() + rise, true)
                && (!(mob instanceof MountableMob mount) || mount.seatsClear(world, x, y, z, rise));
    }

    /** Kiểm tra toàn thân ở vị trí dự kiến khi đặt chân trên bậc. */
    public boolean canOccupy(World world, float x, float y, float z) {
        return bodyClear(world, x, y, z, y + mob.getHeight(), true)
                && (!(mob instanceof MountableMob mount) || mount.seatsClear(world, x, y, z, 0f));
    }

    /** Tránh Lava và Cactus ngay cả ở quãng ngang giữa hai lần đáp đất. */
    public boolean avoidsHazards(World world, float x, float y, float z) {
        return bodyClear(world, x, y, z, y + mob.getHeight(), false);
    }

    /** Quét hộp thân thể, xét khối nguy hiểm và tùy chọn kiểm tra va chạm rắn. */
    private boolean bodyClear(World world, float x, float bottom, float z, float top, boolean checkSolids) {
        float radius = mob.getHalfWidth() - EPSILON;
        float left = x - radius;
        float right = x + radius;
        float back = z - radius;
        float front = z + radius;
        int minX = MathUtils.floor(left);
        int maxX = MathUtils.floor(right);
        int minY = MathUtils.floor(bottom + EPSILON);
        int maxY = MathUtils.floor(top - EPSILON);
        int minZ = MathUtils.floor(back);
        int maxZ = MathUtils.floor(front);
        if (!world.isInsideWorld(minX, minY, minZ) || !world.isInsideWorld(maxX, maxY, maxZ)) {
            return false;
        }
        for (int blockX = minX; blockX <= maxX; blockX++) {
            for (int y = minY; y <= maxY; y++) {
                for (int blockZ = minZ; blockZ <= maxZ; blockZ++) {
                    byte id = world.getBlock(blockX, y, blockZ);
                    if (id == Block.LAVA.getId() || id == Block.CACTUS.getId()) {
                        return false;
                    }
                    if (checkSolids && id != Block.AIR.getId()) {
                        Block.Bounds bounds = world.getCollisionBounds(blockX, y, blockZ);
                        if (bounds != null && bounds.intersects(blockX, y, blockZ,
                                left, bottom + EPSILON, back, right, top - EPSILON, front)) {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }
}

package com.voxelgame.world.entity.mob.animal;

import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.MobAttitude;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.MountableMob;
import com.voxelgame.world.entity.player.Hotbar;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Vector3;
import java.util.concurrent.ThreadLocalRandom;

/** Lạc đà sa mạc chở hai hành khách, ngồi nghỉ trên cát và lướt khi nhả phím nạp. */
public class Camel extends MountableMob {
    /** Chiều cao hộp va chạm khi gập chân và mặt đỡ ghế trên lưng khi đứng. */
    private static final float SITTING_HEIGHT = 0.945f;
    private static final float STANDING_SEAT_HEIGHT = 1.91f;
    /** Vận tốc cơ bản, vận tốc chạy và bước qua bậc cao. */
    private static final float WALK_SPEED = 4f;
    private static final float SPRINT_SPEED = 6.8f;
    private static final float STEP_HEIGHT = 1.5f;
    /** Hồi chiêu, thời gian duy trì xung và vận tốc khi thanh lướt đầy. */
    private static final float DASH_COOLDOWN = 2.75f;
    private static final float DASH_DURATION = 0.55f;
    private static final float DASH_HORIZONTAL_SPEED = 21f;
    private static final float DASH_VERTICAL_SPEED = 7.55f;
    /** Xương rồng chữa hai điểm sinh lực; dụ lạc đà từ mười block. */
    private static final float CACTUS_HEAL = 2f;
    private static final float TEMPT_RANGE = 10f;

    /** Bộ đệm vị trí người cầm mồi dùng lại qua các lượt cập nhật. */
    private final Vector3 feederPosition = new Vector3();
    private double nextRest;
    private double restUntil;
    private double dashReadyAt;
    private boolean sitting;

    /** Lạc đà sống được cưỡi ngay khi gặp. */
    public Camel(float x, float y, float z) {
        this(MobType.CAMEL, x, y, z);
    }

    /** Biến thể undead chia sẻ thể chất và chỉ dùng các hành vi hiền khi đã hết kỵ sĩ. */
    protected Camel(MobType type, float x, float y, float z) {
        super(type, x, y, z, 2, STEP_HEIGHT, WALK_SPEED, 1f, type == MobType.CAMEL, false);
        setMaxSafeFall(maxSafeFall() + 4f);
        scheduleRest();
        goals().add(new MobGoals.FloatInWaterGoal(0));
        goals().add(new MobGoals.PanicGoal(2));
        goals().add(new MobGoals.TemptFollowGoal(5, Block.CACTUS, TEMPT_RANGE, 0.85f));
        goals().add(new MobGoals.WanderGoal(6, 9, 0.7f));
        goals().add(new MobGoals.LookAtPlayerGoal(7, 8f));
        goals().add(new MobGoals.RandomLookAroundGoal(8));
    }

    /** Xử lý Lượt 2 (Interactable): cho lạc đà hiền ăn xương rồng hồi máu hoặc lên ghế cưỡi. */
    @Override
    public boolean onInteract(World world, Player player, Item heldItem) {
        if (!isAlive() || player == null || !player.isAlive() || attitude() != MobAttitude.PASSIVE) {
            return false;
        }
        Hotbar hotbar = player.getHotbar();
        if (hotbar != null && getHealth() < getMaxHealth() && hotbar.getSelectedBlock() == Block.CACTUS
                && hotbar.getSelectedCount() > 0) {
            hotbar.consumeSelectedItem();
            heal(CACTUS_HEAL);
            tryStand(world);
            return true;
        }
        return super.onInteract(world, player, heldItem);
    }

    /** Yêu cầu đủ khoảng trống để đứng lên trước khi nhận người lên yên. */
    @Override
    protected boolean canPlayerMount(World world, Player player) {
        return attitude() == MobAttitude.PASSIVE && super.canPlayerMount(world, player) && tryStand(world);
    }

    /** Lạc đà hiền hoặc lạc đà undead đã được giải thoát đều thuần hóa khi người chơi cưỡi. */
    @Override
    protected void onPlayerMounted(World world, Player player, int seat) {
        tame();
        scheduleRest();
    }

    /** Chân người cưỡi đi xuống cùng thân khi lạc đà ngồi. */
    @Override
    protected float seatHeight(int seat) {
        return STANDING_SEAT_HEIGHT + getHeight() - type().height();
    }

    /** Định vị hai ghế dọc sống lưng, ghế lái ở phía đầu. */
    @Override
    protected float seatForwardOffset(int seat) {
        return seat == 0 ? 0.45f : -0.55f;
    }

    /** Tốc độ chạy nước rút chỉ áp dụng khi người lái yêu cầu. */
    @Override
    protected float riddenSpeed(boolean sprint) {
        return sprint ? SPRINT_SPEED : WALK_SPEED;
    }

    /** Tránh điều khiển lạc đà sống khi chưa thể đứng, hoặc lạc đà còn bị phe địch chiếm. */
    @Override
    protected boolean canRiderDrive(World world) {
        return attitude() == MobAttitude.PASSIVE && tryStand(world);
    }

    /** Chọn thanh Dash trong giao diện thay vì thanh nhảy của ngựa hoặc lừa. */
    @Override
    public boolean isDashMount() {
        return true;
    }

    /** Đọc bộ đếm hồi chiêu từ cùng đồng hồ dùng để cấp quyền kích hoạt lướt. */
    @Override
    public float dashCooldownRemaining() {
        return Math.max(0f, (float) (dashReadyAt - ageSeconds()));
    }

    /** Lướt bắt đầu khi chân chạm đất, dưới điều khiển của người chơi và đã hết hồi. */
    @Override
    protected boolean canChargeAbility() {
        return !sitting && ageSeconds() >= dashReadyAt && super.canChargeAbility();
    }

    /** Nhả nạp để phóng lên một vòng cung, dùng cùng quét vật lý khi chạy và bước bậc. */
    @Override
    protected void onChargedAction(World world, float charge, float directionX, float directionZ) {
        if (!canChargeAbility() || !navigator().canRise(world, x(), y(), z(), 0.15f)) {
            return;
        }
        if (directionX == 0f && directionZ == 0f) {
            float bodyYaw = mobVisualState().bodyYaw();
            directionX = -MathUtils.sinDeg(bodyYaw);
            directionZ = -MathUtils.cosDeg(bodyYaw);
        }
        float horizontalSpeed = DASH_HORIZONTAL_SPEED * (0.28f + 0.72f * charge);
        float verticalSpeed = DASH_VERTICAL_SPEED * (0.7f + 0.3f * charge);
        float vx = horizontalSpeed * directionX;
        float vz = horizontalSpeed * directionZ;
        queueLeap(vx, verticalSpeed, vz, DASH_DURATION);
        velocity.x = vx;
        velocity.z = vz;
        faceBody(x() + directionX, z() + directionZ);
        dashReadyAt = ageSeconds() + DASH_COOLDOWN;
        playSound(world, MobSoundEvent.CAMEL_DASH);
    }

    /** Chọn nghỉ trên cát, hoặc đứng dậy khi gặp mồi, bị đánh, vào nước hay hết lượt nghỉ. */
    @Override
    protected void updateUnridden(World world, float dt) {
        if (attitude() != MobAttitude.PASSIVE) {
            return;
        }
        boolean needsToStand = getPassenger(0) != null || getPassenger(1) != null
                || inWater() || getHurtFlashTimer() > 0f || panicTime() > 0f || isTempted(world.getPlayer());
        if (sitting) {
            if ((!needsToStand && ageSeconds() < restUntil) || !tryStand(world)) {
                stopMoving();
                return;
            }
        } else if (!needsToStand && isOnGround() && ageSeconds() >= nextRest && isOnSand(world)) {
            goals().stopAll(world, this);
            stopMoving();
            height = SITTING_HEIGHT;
            sitting = true;
            restUntil = ageSeconds() + ThreadLocalRandom.current().nextFloat(3f, 6f);
            mobVisualState().setPose(MobVisualState.Pose.SIT, 1f);
            return;
        }
        super.updateUnridden(world, dt);
    }

    /** Đọc khối ngay dưới chân ở tâm thân để khởi động nghỉ đúng nền cát. */
    private boolean isOnSand(World world) {
        return world.getBlock((int) Math.floor(x()), (int) Math.floor(y() - 0.02f), (int) Math.floor(z()))
                == Block.SAND.getId();
    }

    /** Kiểm tra mồi cầm tay để đánh thức lạc đà trong tầm dụ. */
    private boolean isTempted(Player player) {
        if (player == null || !player.isAlive() || player.getHotbar().getSelectedBlock() != Block.CACTUS
                || player.getHotbar().getSelectedCount() <= 0) {
            return false;
        }
        return player.copyPosition(feederPosition).dst2(x(), y(), z()) <= TEMPT_RANGE * TEMPT_RANGE;
    }

    /** Mở rộng hộp va chạm ngay khi toàn bộ thể tích đứng không có vật cản. */
    private boolean tryStand(World world) {
        if (!sitting) {
            return true;
        }
        float standingHeight = type().height();
        if (!navigator().canRise(world, x(), y(), z(), standingHeight - height)) {
            return false;
        }
        height = standingHeight;
        sitting = false;
        mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
        scheduleRest();
        return true;
    }

    /** Rải thời điểm nghỉ để các cá thể cùng xuất hiện không ngồi đồng loạt. */
    private void scheduleRest() {
        nextRest = ageSeconds() + ThreadLocalRandom.current().nextFloat(8f, 18f);
    }
}

package com.voxelgame.world.entity.mob.animal;

import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.ItemEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.PassiveMob;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.World;

import java.util.concurrent.ThreadLocalRandom;

/** Gà đồng bằng vỗ cánh khi rơi, miễn sát thương rơi và định kỳ đẻ trứng. */
public final class Chicken extends PassiveMob {
    /** Giới hạn vận tốc rơi khô theo block/giây, chiều âm là đi xuống. */
    private static final float GLIDE_SPEED = -1.7f;
    /** Chu kỳ đẻ trứng chuẩn Minecraft: 300 đến 600 giây (5 đến 10 phút). */
    private static final float EGG_MIN_SECONDS = 300f;
    private static final float EGG_MAX_SECONDS = 600f;

    private float eggTimer = randomEggDelay();

    /** Dùng bộ goal hiền lành chung, gồm lang thang và chạy hoảng khi trúng đòn. */
    public Chicken(float x, float y, float z) {
        super(MobType.CHICKEN, x, y, z);
        setMoveSpeed(2.5f);
    }

    /** Vỗ cánh khi chuyển động xuống, thu cánh khi đáp đất và đẻ trứng khi hết chu kỳ. */
    @Override
    protected void updateLiving(World world, float dt) {
        super.updateLiving(world, dt);
        boolean descending = !isOnGround() && velocity.y < 0f;
        mobVisualState().setPose(descending ? MobVisualState.Pose.FLAP : MobVisualState.Pose.IDLE,
                descending ? 1f : 0f);
        if (!isBaby() && isAlive()) {
            eggTimer -= dt;
            if (eggTimer <= 0f) {
                eggTimer = randomEggDelay();
                world.spawnDroppedItem(new ItemEntity(x(), y() + 0.25f, z(), Item.EGG));
                playSound(world, MobSoundEvent.AMBIENT);
            }
        }
    }

    /** Đặt lại bộ đếm đẻ trứng trong khoảng 300–600 giây. */
    private static float randomEggDelay() {
        return ThreadLocalRandom.current().nextFloat(EGG_MIN_SECONDS, EGG_MAX_SECONDS);
    }

    /** Cho phép kiểm thử đặt nhanh thời gian chờ đẻ trứng. */
    public void setEggTimerForTest(float seconds) {
        eggTimer = seconds;
    }

    /** Đọc thời gian còn lại tới lần đẻ trứng tiếp theo. */
    public float eggTimer() {
        return eggTimer;
    }

    /** Giới hạn tốc độ ngay trước quét vật lý, kể cả nhịp rơi đầu tiên. */
    @Override
    protected float terminalFallSpeed() { return GLIDE_SPEED; }

    /** Bỏ tích lũy độ cao rơi của gà trong vòng sinh tồn. */
    @Override
    protected boolean ignoresFall() { return true; }

    /** Chặn cả nguồn FALL gửi trực tiếp, còn những nguồn khác theo luật chung. */
    @Override
    public boolean damage(World world, float amount, DamageSource source, Entity attacker,
                          float knockbackX, float knockbackZ) {
        return source != DamageSource.FALL && super.damage(world, amount, source, attacker, knockbackX, knockbackZ);
    }
}

package com.voxelgame.world.entity.mob.animal;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.core.Interactable;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.ItemEntity;
import com.voxelgame.world.entity.mob.ai.MobGoal;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.PassiveMob;
import com.voxelgame.world.entity.player.Hotbar;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.World;

/** Bò đồng bằng tự đi lang thang, quay lại gần đàn và cho vắt sữa bằng Bucket. */
public final class Cow extends PassiveMob implements Interactable {
    /** Lấy chỉ số và nhóm âm thanh của bò, cùng các goal hiền lành dùng chung. */
    public Cow(float x, float y, float z) {
        super(MobType.COW, x, y, z);
        setMoveSpeed(2f);
        goals().add(new HerdGoal());
    }

    /** Xử lý Lượt 2 (Interactable): vắt sữa khi người chơi cầm Bucket. */
    @Override
    public boolean onInteract(World world, Player player, Item heldItem) {
        if (!isAlive() || isBaby() || player == null || !player.isAlive()) {
            return false;
        }
        Hotbar hotbar = player.getHotbar();
        if (heldItem == Item.BUCKET && hotbar != null && hotbar.getSelectedCount() > 0) {
            hotbar.consumeSelectedItemStack();
            if (!hotbar.addItem(Item.MILK_BUCKET, 1) && world != null) {
                world.spawnDroppedItem(new ItemEntity(x(), y() + 0.6f, z(), Item.MILK_BUCKET));
            }
            AudioManager audio = world == null ? null : world.getAudio();
            if (audio != null) {
                audio.playEffect(AudioManager.Effect.PICKUP, 0.35f);
            }
            return true;
        }
        return false;
    }

    /** Dẫn bò về phía đồng loại trong tầm gần, nhường khi hoảng hoặc khi đã nhập đàn. */
    private static final class HerdGoal implements MobGoal {
        /** Khoảng bắt đầu, khoảng dừng và tầm tìm đồng loại, theo bình phương block. */
        private static final float SEPARATED_SQUARED = 4.5f * 4.5f;
        private static final float REJOINED_SQUARED = 2.5f * 2.5f;
        private static final float SEARCH_SQUARED = 12f * 12f;
        private MobEntity companion;

        /** Giữ kênh di chuyển trước Wander và sau Panic. */
        @Override public int priority() { return 5; }
        /** Để goal khác tiếp tục điều khiển hướng nhìn. */
        @Override public int controls() { return MOVE; }
        /** Chỉ quét đàn theo nhịp nửa giây khi chưa theo cá thể nào. */
        @Override public float retrySeconds() { return 0.5f; }

        /** Chọn đồng loại gần nhất, chỉ theo nếu khoảng trống giữa hai con đủ lớn. */
        @Override
        public boolean canStart(World world, MobEntity self) {
            if (!self.isOnGround() || self.panicTime() > 0f) {
                return false;
            }
            float closest = SEARCH_SQUARED;
            MobEntity nearest = null;
            for (int i = 0, count = world.entityCount(); i < count; i++) {
                Entity entity = world.entityAt(i);
                if (!(entity instanceof MobEntity cow) || cow == self || cow.type() != MobType.COW
                        || !cow.isAlive() || !cow.isOnGround()) {
                    continue;
                }
                float distance = distanceSquared(self, cow);
                if (distance < closest) {
                    closest = distance;
                    nearest = cow;
                }
            }
            companion = closest > SEPARATED_SQUARED ? nearest : null;
            return companion != null;
        }

        /** Tránh huých đồng loại khi đã nhập đàn, cũng bỏ đích đã chết hoặc đi quá xa. */
        @Override
        public boolean shouldContinue(World world, MobEntity self) {
            if (companion == null || !companion.isAlive() || self.panicTime() > 0f) {
                return false;
            }
            float distance = distanceSquared(self, companion);
            return distance > REJOINED_SQUARED && distance < SEARCH_SQUARED;
        }

        /** Đồng loại đã được chọn ngay trong lúc kiểm tra khởi động. */
        @Override public void start(World world, MobEntity self) { }

        /** Gửi đích mới nhất qua điều hướng tránh vực, gai và dung nham dùng chung. */
        @Override
        public void tick(World world, MobEntity self, float dt) {
            self.moveToward(world, companion.x(), companion.y(), companion.z(), 0.85f);
        }

        /** Bỏ tham chiếu tới đồng loại và trả kênh di chuyển cho goal kế tiếp. */
        @Override
        public void stop(World world, MobEntity self) {
            self.stopMoving();
            companion = null;
        }

        /** Khoảng cách chân ba chiều, không tạo bản sao tọa độ. */
        private static float distanceSquared(MobEntity a, MobEntity b) {
            float dx = a.x() - b.x();
            float dy = a.y() - b.y();
            float dz = a.z() - b.z();
            return dx * dx + dy * dy + dz * dz;
        }
    }
}

