package com.voxelgame.world.entity.mob.animal;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.core.Interactable;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.ItemEntity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.NeutralMob;
import com.voxelgame.world.entity.player.Hotbar;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Vector3;
import java.util.concurrent.ThreadLocalRandom;

/** Dê núi có thể lấy đà nhảy vượt địa hình hoặc lao húc mục tiêu đứng gần. */
public final class Goat extends NeutralMob implements Interactable {
    /** Tốc độ, tầm chọn đích và thời lượng chuẩn bị cho cú húc. */
    private static final float RAM_SPEED = 13f;
    private static final float RAM_RANGE = 9f;
    private static final float RAM_PREPARE = 0.8f;
    private static final float RAM_TIMEOUT = 1.1f;
    /** Gia tốc rơi và giới hạn bán kính, chênh cao của một cú nhảy núi. */
    private static final float GRAVITY_MAGNITUDE = 26f;
    private static final float JUMP_RANGE = 10f;
    private static final float JUMP_PREPARE = 0.4f;

    /** Phân biệt lấy đà, lao và nhảy để các hành vi không giành quyền điều khiển. */
    private enum Action {
        IDLE, RAM_WINDUP, RAM_CHARGE, JUMP_WINDUP, JUMP_FLIGHT
    }

    private final boolean screaming;
    private int horns = 2;
    private final Vector3 targetCenter = new Vector3();
    private final Vector3 targetVelocity = new Vector3();
    private final Vector3 jumpDestination = new Vector3();
    private LivingEntity ramTarget;
    private Action action = Action.IDLE;
    private float actionRemaining;
    private float ramDelay;
    private float jumpDelay = ThreadLocalRandom.current().nextFloat(9f, 23f);
    private float ramX;
    private float ramZ;
    private float ramDirectionX;
    private float ramDirectionZ;

    /** Tạo dê trưởng thành với xác suất 2% thuộc biến thể dê hét. */
    public Goat(float x, float y, float z) {
        this(x, y, z, ThreadLocalRandom.current().nextInt(50) == 0);
    }

    /** Khởi tạo biến thể và đặt sẵn khoảng chờ cú húc đầu tiên. */
    public Goat(float x, float y, float z, boolean screaming) {
        super(MobType.GOAT, x, y, z, 0f, 0, false);
        this.screaming = screaming;
        setMoveSpeed(2.5f);
        setMaxSafeFall(13f);
        MobGoals.addDefaults(goals(), type(), false);
        scheduleRam();
    }

    /** Cập nhật va chạm của cú húc vào mục tiêu hoặc khối cứng (rơi sừng) sau khi vật lý quét xong. */
    @Override
    protected void updateLiving(World world, float dt) {
        float fromX = x();
        float fromZ = z();
        super.updateLiving(world, dt);
        if (action != Action.RAM_CHARGE || !isAlive()) {
            return;
        }
        if (hitRamTarget(world, fromX, fromZ)) {
            finishAction();
            return;
        }
        if (hitHardBlock(world, fromX, fromZ, dt)) {
            dropGoatHorn(world);
            finishAction();
            return;
        }
        if (inWater()
                || (x() - ramX) * ramDirectionX + (z() - ramZ) * ramDirectionZ >= 0f
                || actionRemaining <= 0f) {
            finishAction();
        }
    }

    /** Xử lý Lượt 2 (Interactable): vắt sữa dê khi người chơi cầm Bucket. */
    @Override
    public boolean onInteract(World world, Player player, Item heldItem) {
        if (!isAlive() || isBaby() || player == null || !player.isAlive()) {
            return false;
        }
        Hotbar hotbar = player.getHotbar();
        if (heldItem == Item.BUCKET && hotbar != null && hotbar.getSelectedCount() > 0) {
            hotbar.consumeSelectedItemStack();
            if (!hotbar.addItem(Item.MILK_BUCKET, 1) && world != null) {
                world.spawnDroppedItem(new ItemEntity(x(), y() + 0.6f, z(), Item.MILK_BUCKET));
            }
            AudioManager audio = world == null ? null : world.getAudio();
            if (audio != null) {
                audio.playEffect(AudioManager.Effect.PICKUP, 0.35f);
            }
            return true;
        }
        return false;
    }

    /** Trả số sừng còn lại trên đầu dê (tối đa 2). */
    public int hornCount() {
        return horns;
    }

    /** Kiểm tra dê đang lao có bị chặn bởi đá, gỗ tự nhiên hoặc băng phía trước không. */
    private boolean hitHardBlock(World world, float fromX, float fromZ, float dt) {
        float moved = (x() - fromX) * ramDirectionX + (z() - fromZ) * ramDirectionZ;
        if (moved > 0.02f) {
            return false;
        }
        float probe = halfWidth + Math.max(0.18f, RAM_SPEED * dt + 0.05f);
        float probeX = x() + ramDirectionX * probe;
        float probeZ = z() + ramDirectionZ * probe;
        int bx = MathUtils.floor(probeX);
        int bz = MathUtils.floor(probeZ);
        return isHornDropBlock(Block.fromId(world.getBlock(bx, MathUtils.floor(y() + 0.3f), bz)))
                || isHornDropBlock(Block.fromId(world.getBlock(bx, MathUtils.floor(y() + 0.9f), bz)));
    }

    /** Các loại khối tự nhiên làm rơi Goat Horn chuẩn Minecraft khi dê húc vào. */
    private static boolean isHornDropBlock(Block block) {
        return block == Block.STONE || block == Block.OAK_LOG || block == Block.SPRUCE_LOG || block == Block.ICE;
    }

    /** Rơi tối đa 2 sừng dê tại vị trí húc trúng khối cứng. */
    private void dropGoatHorn(World world) {
        if (horns <= 0 || isBaby()) {
            return;
        }
        horns--;
        world.spawnDroppedItem(new ItemEntity(x(), y() + height * 0.7f, z(), Item.GOAT_HORN));
        playSound(world, MobSoundEvent.HURT);
    }

    /** Ưu tiên cú húc đến hạn, sau đó mới thử tìm bãi đáp an toàn để nhảy. */
    @Override
    protected void updateGoals(World world, float dt) {
        ramDelay -= dt;
        jumpDelay -= dt;
        if (action != Action.IDLE) {
            updateAction(world, dt);
            return;
        }
        if (onGround && !inWater()) {
            if (ramDelay <= 0f) {
                ramTarget = findRamTarget(world);
                if (ramTarget != null) {
                    action = Action.RAM_WINDUP;
                    actionRemaining = RAM_PREPARE;
                    goals().stopAll(world, this);
                    playSound(world, screaming ? MobSoundEvent.GOAT_SCREAM : MobSoundEvent.GOAT_RAM);
                    updateAction(world, dt);
                    return;
                }
                ramDelay = 1.5f;
            }
            if (jumpDelay <= 0f) {
                jumpDelay = ThreadLocalRandom.current().nextFloat(9f, 23f);
                if (findJumpDestination(world)) {
                    action = Action.JUMP_WINDUP;
                    actionRemaining = JUMP_PREPARE;
                    goals().stopAll(world, this);
                    updateAction(world, dt);
                    return;
                }
            }
        }
        super.updateGoals(world, dt);
    }

    /** Thực hiện pha lấy đà hoặc lao hiện tại và nhường lại điều khiển khi kết thúc. */
    private void updateAction(World world, float dt) {
        actionRemaining -= dt;
        switch (action) {
            case RAM_WINDUP -> prepareRam(dt);
            case RAM_CHARGE -> steerDirect(x() + ramDirectionX, z() + ramDirectionZ, RAM_SPEED);
            case JUMP_WINDUP -> prepareJump(world, dt);
            case JUMP_FLIGHT -> {
                if (onGround || inWater() || actionRemaining <= 0f) {
                    finishAction();
                }
            }
            case IDLE -> {
                // Chỉ gọi khi một hành vi đang giữ quyền điều khiển.
            }
        }
    }

    /** Dê chỉ lấy đà vào thực thể sống đang đứng yên hoặc di chuyển chậm ở gần. */
    private LivingEntity findRamTarget(World world) {
        LivingEntity nearest = null;
        float best = RAM_RANGE * RAM_RANGE;
        for (int index = 0, count = world.entityCount(); index < count; index++) {
            if (world.entityAt(index) instanceof LivingEntity candidate && candidate != this && candidate.isAlive()
                    && isSlow(candidate)) {
                candidate.copyCenterPosition(targetCenter);
                float distance = targetCenter.dst2(x(), y() + height * 0.5f, z());
                if (distance <= best && distance >= 1f && Math.abs(targetCenter.y - y() - height * 0.5f) < 1.5f) {
                    nearest = candidate;
                    best = distance;
                }
            }
        }
        return nearest;
    }

    /** Đọc vận tốc vào bộ đệm tái sử dụng để loại mục tiêu đang chạy hoặc rơi nhanh. */
    private boolean isSlow(LivingEntity candidate) {
        return candidate.copyVelocity(targetVelocity).len2() <= 1.5f * 1.5f;
    }

    /** Hạ đầu trong lúc nhìn đích, rồi khóa hướng húc để mục tiêu có thể né sang bên. */
    private void prepareRam(float dt) {
        stopMoving();
        if (!onGround || inWater() || ramTarget == null || !ramTarget.isAlive()) {
            finishAction();
            return;
        }
        ramTarget.copyCenterPosition(targetCenter);
        lookAt(targetCenter.x, targetCenter.y, targetCenter.z);
        faceBody(targetCenter.x, targetCenter.z);
        mobVisualState().setPose(MobVisualState.Pose.RAM, Math.min(1f, 1f - actionRemaining / RAM_PREPARE + 0.15f));
        if (actionRemaining <= 0f) {
            float dx = targetCenter.x - x();
            float dz = targetCenter.z - z();
            float distance = (float) Math.sqrt(dx * dx + dz * dz);
            if (distance < CONTACT_EPSILON || distance > RAM_RANGE + 1f || !isSlow(ramTarget)) {
                finishAction();
                return;
            }
            ramDirectionX = dx / distance;
            ramDirectionZ = dz / distance;
            ramX = targetCenter.x + ramDirectionX * 0.9f;
            ramZ = targetCenter.z + ramDirectionZ * 0.9f;
            action = Action.RAM_CHARGE;
            actionRemaining = RAM_TIMEOUT + dt;
            steerDirect(x() + ramDirectionX, z() + ramDirectionZ, RAM_SPEED);
        }
    }

    /** Kiểm tra đoạn đường vừa quét và truyền xung lực mạnh theo hướng húc. */
    private boolean hitRamTarget(World world, float fromX, float fromZ) {
        if (ramTarget == null || !ramTarget.isAlive()) {
            return true;
        }
        ramTarget.copyPosition(targetCenter);
        if (targetCenter.y >= y() + height || targetCenter.y + ramTarget.getHeight() <= y()) {
            return false;
        }
        float dx = x() - fromX;
        float dz = z() - fromZ;
        float distance = dx * dx + dz * dz;
        float t = distance > 0f ? MathUtils.clamp(((targetCenter.x - fromX) * dx
                + (targetCenter.z - fromZ) * dz) / distance, 0f, 1f) : 0f;
        float reach = halfWidth + ramTarget.getHalfWidth();
        float missX = targetCenter.x - (fromX + t * dx);
        float missZ = targetCenter.z - (fromZ + t * dz);
        if (missX * missX + missZ * missZ > reach * reach) {
            return false;
        }
        ramTarget.damage(world, getMeleeDamage(2f), DamageSource.MELEE, this,
                ramDirectionX * 17f, ramDirectionZ * 17f);
        return true;
    }

    /** Thử các bãi đáp có nền, ưu tiên bề mặt cao trước mặt phẳng hiện tại. */
    private boolean findJumpDestination(World world) {
        ThreadLocalRandom random = ThreadLocalRandom.current();
        for (int attempt = 0; attempt < 12; attempt++) {
            float angle = random.nextFloat(MathUtils.PI2);
            float distance = random.nextFloat(4.5f, JUMP_RANGE);
            int bx = MathUtils.floor(x() + MathUtils.cos(angle) * distance);
            int bz = MathUtils.floor(z() + MathUtils.sin(angle) * distance);
            float dx = bx + 0.5f - x();
            float dz = bz + 0.5f - z();
            if (dx * dx + dz * dz > JUMP_RANGE * JUMP_RANGE) {
                continue;
            }
            float feet = navigator().findStandableY(world, bx, MathUtils.floor(y() + JUMP_RANGE), bz);
            if (!Float.isFinite(feet)) {
                feet = navigator().findStandableY(world, bx, MathUtils.floor(y()), bz);
            }
            if (Float.isFinite(feet) && Math.abs(feet - y()) <= JUMP_RANGE) {
                jumpDestination.set(bx + 0.5f, feet, bz + 0.5f);
                if (canTraverseJump(world)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Giữ tư thế lấy đà, kiểm tra lại quỹ đạo rồi phóng theo vận tốc giải từ phương trình rơi. */
    private void prepareJump(World world, float dt) {
        stopMoving();
        faceBody(jumpDestination.x, jumpDestination.z);
        mobVisualState().setPose(MobVisualState.Pose.HOP, Math.min(1f, 1f - actionRemaining / JUMP_PREPARE));
        if (actionRemaining <= 0f) {
            if (!onGround || inWater() || !canTraverseJump(world)) {
                finishAction();
                return;
            }
            float rise = jumpDestination.y - y();
            float apex = jumpApex(rise);
            float speed = jumpSpeed(apex);
            float seconds = jumpTime(speed, apex, rise);
            float powered = Math.max(0.25f, seconds - 0.04f);
            queueLeap((jumpDestination.x - x()) / powered, speed + GRAVITY_MAGNITUDE * dt * 0.5f,
                    (jumpDestination.z - z()) / powered, seconds + 0.06f);
            action = Action.JUMP_FLIGHT;
            actionRemaining = seconds + 0.5f;
        }
    }

    /** Dò thể tích thân qua quỹ đạo để tránh nhảy vào vách, trần hoặc khối nguy hiểm. */
    private boolean canTraverseJump(World world) {
        float rise = jumpDestination.y - y();
        float apex = jumpApex(rise);
        float speed = jumpSpeed(apex);
        float seconds = jumpTime(speed, apex, rise);
        for (int step = 1; step <= 20; step++) {
            float fraction = step / 20f;
            float time = seconds * fraction;
            float feet = y() + speed * time - 0.5f * GRAVITY_MAGNITUDE * time * time;
            if (!navigator().canOccupy(world, MathUtils.lerp(x(), jumpDestination.x, fraction),
                    step == 20 ? jumpDestination.y : feet,
                    MathUtils.lerp(z(), jumpDestination.z, fraction))) {
                return false;
            }
        }
        return true;
    }

    /** Chọn độ cao đủ qua mép bãi đáp trong giới hạn 10 block. */
    private static float jumpApex(float rise) {
        return Math.min(JUMP_RANGE, Math.max(2.75f, rise + 1.5f));
    }

    /** Đổi độ cao đỉnh thành vận tốc dọc lúc bật. */
    private static float jumpSpeed(float apex) {
        return (float) Math.sqrt(2f * GRAVITY_MAGNITUDE * apex);
    }

    /** Tính thời gian lên đỉnh rồi rơi tới đúng cao độ bãi đáp. */
    private static float jumpTime(float speed, float apex, float rise) {
        return speed / GRAVITY_MAGNITUDE + (float) Math.sqrt(2f * (apex - rise) / GRAVITY_MAGNITUDE);
    }

    /** Xóa tư thế riêng và tính lại hồi chiêu sau mỗi lượt húc. */
    private void finishAction() {
        if (action == Action.RAM_WINDUP || action == Action.RAM_CHARGE) {
            ramTarget = null;
            scheduleRam();
        }
        action = Action.IDLE;
        mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
    }

    /** Dê hét dùng khoảng 5–15 giây, các cá thể còn lại dùng 30–300 giây. */
    private void scheduleRam() {
        ThreadLocalRandom random = ThreadLocalRandom.current();
        ramDelay = screaming ? random.nextFloat(5f, 15f) : random.nextFloat(30f, 300f);
    }
}

package com.voxelgame.world.entity.mob.animal;

import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.world.entity.mob.EquineMob;
import com.voxelgame.world.entity.mob.MobType;

import java.util.concurrent.ThreadLocalRandom;
import java.util.random.RandomGenerator;

/** Ngựa Plains có thể thuần hóa, với chỉ số và vân lông riêng của mỗi cá thể. */
public final class Horse extends EquineMob {
    /** Bảy sắc lông nền dùng khi chọn màu chung cho một đàn. */
    private static final MobAppearance[] COATS = {
            MobAppearance.HORSE_WHITE, MobAppearance.HORSE_CREAMY, MobAppearance.HORSE_CHESTNUT,
            MobAppearance.HORSE_BROWN, MobAppearance.HORSE_BLACK, MobAppearance.HORSE_GRAY,
            MobAppearance.HORSE_DARKBROWN
    };
    /** Mỗi cá thể chọn vân riêng, kể cả lựa chọn lông trơn. */
    private static final MobAppearance.HorseMarkings[] MARKINGS = MobAppearance.HorseMarkings.values();

    /** Tạo cá thể đơn với đầy đủ lựa chọn màu lông. */
    public Horse(float x, float y, float z) {
        this(x, y, z, randomCoat(ThreadLocalRandom.current()));
    }

    /** Tạo cá thể trưởng thành với sắc lông được chọn cho cả đàn. */
    public Horse(float x, float y, float z, MobAppearance coat) {
        this(x, y, z, coat, ThreadLocalRandom.current());
    }

    /** Lấy trung bình ba mẫu để đa số cá thể có tốc độ và sức nhảy gần trung tâm khoảng. */
    private Horse(float x, float y, float z, MobAppearance coat, RandomGenerator random) {
        super(MobType.HORSE, x, y, z, 4.8f + 9.7f * meanOfThree(random),
                1.25f + 4f * meanOfThree(random), randomHealth(random));
        mobVisualState().setAppearance(coat);
        mobVisualState().setHorseMarkings(MARKINGS[random.nextInt(MARKINGS.length)]);
    }

    /** Chọn một màu nền ngẫu nhiên để bộ sinh tái sử dụng trong cả đàn. */
    public static MobAppearance randomCoat(RandomGenerator random) {
        return COATS[random.nextInt(COATS.length)];
    }

    /** Lấy trung bình của ba số thực phân bố đều từ 0 đến gần 1. */
    private static float meanOfThree(RandomGenerator random) {
        return (random.nextFloat() + random.nextFloat() + random.nextFloat()) / 3f;
    }
}

package com.voxelgame.world.entity.mob.animal;

import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.PassiveMob;
import com.voxelgame.world.item.Item;

/** Lợn đồng bằng dùng goal lang thang, chạy hoảng, đi theo cà rốt/khoai tây và mẫu tiếng ủn ỉn của loài. */
public final class Pig extends PassiveMob {
    /** Bán kính phát hiện người chơi cầm mồi và hệ số tốc độ khi đi theo. */
    private static final float TEMPT_RANGE = 10f;
    private static final float TEMPT_SPEED = 1.0f;

    /** Áp dụng tốc độ của lợn cùng cấu hình hiền lành trong danh mục và goal dụ bằng Carrot/Potato. */
    public Pig(float x, float y, float z) {
        super(MobType.PIG, x, y, z);
        setMoveSpeed(2.5f);
        goals().add(new MobGoals.TemptFollowGoal(5, Pig::isTemptItem, TEMPT_RANGE, TEMPT_SPEED));
    }

    /** Kiểm tra vật phẩm có phải mồi dụ hợp lệ của lợn ({@link Item#CARROT} hoặc {@link Item#POTATO}). */
    private static boolean isTemptItem(Item item) {
        return item == Item.CARROT || item == Item.POTATO;
    }
}

package com.voxelgame.world.entity.mob.animal;

import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.NeutralMob;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.Vector3;
import java.util.concurrent.ThreadLocalRandom;

/** Gấu Bắc Cực bảo vệ gấu con, trả đũa theo nhóm và bơi với tốc độ đầy đủ. */
public final class PolarBear extends NeutralMob {
    /** Khoảng cách bảo vệ bầy và khoảng cách người chơi làm gấu con gặp nguy hiểm. */
    private static final float FAMILY_RANGE_SQUARED = 16f * 16f;
    private static final float CUB_THREAT_SQUARED = 4f * 4f;
    /** Thời gian cảnh báo bằng tư thế dựng hai chân, và thời gian trả đũa. */
    private static final float REAR_SECONDS = 0.85f;
    private static final float ANGER_SECONDS = 20f;
    /** Đệm vị trí dùng lại trong các lượt kiểm tra và quan sát. */
    private final Vector3 nearby = new Vector3();
    private final Vector3 playerCenter = new Vector3();
    private float rearRemaining;
    private float fleeRemaining;
    private float familyDelay;
    private float foxDelay = ThreadLocalRandom.current().nextFloat(7f, 18f);

    /** Tạo gấu trưởng thành thông qua danh mục loài. */
    public PolarBear(float x, float y, float z) {
        this(x, y, z, false);
    }

    /** Khởi tạo gấu con với chiều rộng và chiều cao bằng nửa gấu trưởng thành. */
    public PolarBear(float x, float y, float z, boolean baby) {
        super(MobType.POLAR_BEAR, x, y, z, 0f, 0, false, baby ? 0.5f : 1f);
        setBaby(baby);
        mobVisualState().setScale(baby ? 0.5f : 1f);
        setMoveSpeed(2.5f);
        MobGoals.addDefaults(goals(), type(), false);
        if (baby) {
            goals().add(new MobGoals.FleeEntityGoal(2, 16f, 1.45f,
                    other -> fleeRemaining > 0f && other instanceof Player));
        } else {
            goals().add(new MobGoals.MeleeAttackGoal(4, 1.4f, 6f, 1.65f, 1.15f, 20f));
        }
    }

    /** Gấu con chỉ tìm lối chạy, còn gấu trưởng thành cảnh báo trước khi tiếp cận. */
    @Override
    protected void updateGoals(World world, float dt) {
        if (isBaby()) {
            fleeRemaining = Math.max(0f, fleeRemaining - dt);
            setTarget(null);
            super.updateGoals(world, dt);
            return;
        }

        familyDelay -= dt;
        Player player = world.getPlayer();
        if (familyDelay <= 0f) {
            familyDelay = 0.25f;
            if (player != null && player.isAlive() && target() != player && cubInDanger(world, player)) {
                protectFamily(world, player);
            }
        }
        foxDelay -= dt;
        if (foxDelay <= 0f && target() == null) {
            foxDelay = ThreadLocalRandom.current().nextFloat(7f, 18f);
            lookForFox(world);
        }
        if (rearRemaining > 0f && target() != null && !inWater()) {
            goals().stopAll(world, this);
            stopMoving();
            target().copyCenterPosition(nearby);
            lookAt(nearby.x, nearby.y, nearby.z);
            faceBody(nearby.x, nearby.z);
            mobVisualState().setPose(MobVisualState.Pose.REAR, Math.min(1f, (REAR_SECONDS - rearRemaining) * 8f + 0.2f));
            rearRemaining = Math.max(0f, rearRemaining - dt);
            return;
        }
        rearRemaining = 0f;
        mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
        super.updateGoals(world, dt);
    }

    /** Bảo toàn tốc độ bơi của gấu so với tốc độ điều khiển trên cạn. */
    @Override
    protected float waterSpeedMultiplier() {
        return 1f;
    }

    /** Tìm gấu con ở gần cả gấu trưởng thành lẫn người chơi. */
    private boolean cubInDanger(World world, Player player) {
        player.copyCenterPosition(playerCenter);
        for (int index = 0, count = world.entityCount(); index < count; index++) {
            if (world.entityAt(index) instanceof PolarBear cub && cub.isBaby() && cub.isAlive()
                    && distanceSquared(cub) <= FAMILY_RANGE_SQUARED && nearby.dst2(playerCenter) <= CUB_THREAT_SQUARED) {
                return true;
            }
        }
        return false;
    }

    /** Thỉnh thoảng săn một con cáo tuyết đi ngang qua gần gấu. */
    private void lookForFox(World world) {
        for (int index = 0, count = world.entityCount(); index < count; index++) {
            if (world.entityAt(index) instanceof MobEntity fox && fox.type() == MobType.SNOW_FOX
                    && fox.isAlive() && distanceSquared(fox) <= 36f) {
                enrage(fox, 6f);
                return;
            }
        }
    }

    /** Báo động cho gấu trưởng thành và gấu con trong vùng khi người chơi đánh một con gấu. */
    @Override
    public boolean damage(World world, float amount, DamageSource source, Entity attacker,
                          float knockbackX, float knockbackZ) {
        boolean applied = super.damage(world, amount, source, attacker, knockbackX, knockbackZ);
        if (applied && world != null && attacker instanceof Player player && player.isAlive()) {
            if (isAlive()) {
                protectFamily(world, player);
            }
            for (int index = 0, count = world.entityCount(); index < count; index++) {
                if (world.entityAt(index) instanceof PolarBear bear && bear != this && bear.isAlive()
                        && distanceSquared(bear) <= FAMILY_RANGE_SQUARED) {
                    bear.protectFamily(world, player);
                }
            }
        }
        return applied;
    }

    /** Kích hoạt cảnh báo hai chân ở gấu trưởng thành hoặc bỏ chạy ở gấu con. */
    private void protectFamily(World world, Player player) {
        if (isBaby()) {
            setTarget(null);
            fleeRemaining = 7f;
        } else {
            enrage(player, ANGER_SECONDS);
            if (rearRemaining == 0f && !inWater()) {
                rearRemaining = REAR_SECONDS;
                playSound(world, MobSoundEvent.AMBIENT);
            }
        }
    }

    /** Chép tâm vào bộ đệm và trả bình phương khoảng cách tới gấu. */
    private float distanceSquared(LivingEntity other) {
        return other.copyCenterPosition(nearby).dst2(x(), y() + height * 0.5f, z());
    }
}

package com.voxelgame.world.entity.mob.animal;

import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.MobAttitude;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.PassiveMob;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import java.util.concurrent.ThreadLocalRandom;

/** Thỏ sa mạc và thỏ tuyết dùng chung cách di chuyển nhảy cóc và các phản ứng tháo chạy. */
public final class Rabbit extends PassiveMob {
    /** Xác suất lông trắng ở vùng tuyết, còn lại dùng lông trắng có đốm. */
    private static final float SNOW_WHITE_PROBABILITY = 0.8f;
    /** Vận tốc đứng đầu nhịp nhảy cho độ cao gần hai block với trọng lực của mob. */
    private static final float HOP_UP_SPEED = 10.3f;
    /** Giữ vận tốc ngang cho cả vòng cung và nghỉ ngắn giữa hai lần bật. */
    private static final float HOP_FLIGHT_SECONDS = 0.80f;
    private static final float HOP_INTERVAL_SECONDS = 0.87f;
    private double nextHop;
    private double hoppingUntil;

    /** Dựng thỏ vàng cát khi factory sa mạc được gọi. */
    public Rabbit(float x, float y, float z) {
        this(MobType.RABBIT, x, y, z);
    }

    /** Dựng thỏ tuyết, chọn ngẫu nhiên màu tại thời điểm cá thể được tạo. */
    public static Rabbit snow(float x, float y, float z) {
        return new Rabbit(MobType.SNOW_RABBIT, x, y, z);
    }

    /** Ánh xạ kết quả bốc trong [0,1) sang biến thể thích hợp với nơi sinh. */
    public static MobAppearance appearanceFor(MobType type, float roll) {
        if (type == MobType.RABBIT) {
            return MobAppearance.RABBIT_GOLD;
        }
        if (type != MobType.SNOW_RABBIT) {
            throw new IllegalArgumentException("Cấu hình màu phải thuộc loài thỏ");
        }
        return roll < SNOW_WHITE_PROBABILITY ? MobAppearance.RABBIT_WHITE : MobAppearance.RABBIT_WHITE_SPLOTCHED;
    }

    /** Lắp ba bán kính tránh riêng và cho bồ công anh thay đổi cách thỏ nhận diện người chơi. */
    private Rabbit(MobType type, float x, float y, float z) {
        super(type, x, y, z, 0f, 0, false);
        mobVisualState().setAppearance(appearanceFor(type, ThreadLocalRandom.current().nextFloat()));
        setMoveSpeed(2.7f);
        goals().add(new MobGoals.FloatInWaterGoal(0));
        goals().add(new MobGoals.PanicGoal(1));
        goals().add(new MobGoals.FleeEntityGoal(2, 10f, 1.85f,
                entity -> entity instanceof MobEntity animal && animal.type() == MobType.WOLF));
        goals().add(new MobGoals.FleeEntityGoal(3, 8f, 1.65f,
                entity -> entity instanceof Player player && !holdsTemptItem(player)));
        goals().add(new MobGoals.FleeEntityGoal(4, 4f, 1.65f,
                entity -> entity instanceof MobEntity monster && monster.attitude() == MobAttitude.HOSTILE));
        goals().add(new MobGoals.TemptFollowGoal(5, Rabbit::isTemptItem, 10f, 0.8f));
        goals().add(new MobGoals.WanderGoal(6, 9, 0.65f));
        goals().add(new MobGoals.LookAtPlayerGoal(7, 8f));
        goals().add(new MobGoals.RandomLookAroundGoal(8));
    }

    /** Chỉ vật phẩm còn trong chính ô đang chọn được dùng để dụ thỏ (Carrot hoặc Dandelion). */
    private static boolean holdsTemptItem(Player player) {
        return player.getHotbar().getSelectedCount() > 0 && isTemptItem(player.getHotbar().getSelectedItem());
    }

    /** Nhận diện mồi dụ của thỏ: {@link Item#CARROT} hoặc {@link Block#DANDELION}. */
    private static boolean isTemptItem(Item item) {
        return item == Item.CARROT || item == Item.of(Block.DANDELION);
    }

    /** Đổi hướng đã được điều hướng kiểm tra thành một vòng nhảy, không kéo thỏ đi bộ trên cạn. */
    @Override
    public void steer(float dx, float dz, float speed) {
        if (inWater()) {
            super.steer(dx, dz, speed);
        } else if (speed > 0f && isOnGround() && ageSeconds() >= nextHop) {
            double now = ageSeconds();
            queueLeap(dx * speed, HOP_UP_SPEED, dz * speed, HOP_FLIGHT_SECONDS);
            hoppingUntil = now + HOP_FLIGHT_SECONDS;
            nextHop = now + HOP_INTERVAL_SECONDS;
        }
    }

    /** Cập nhật dáng thu chân theo vận tốc đứng thật và trả pose thường khi đã đáp xuống. */
    @Override
    protected void updateLiving(World world, float dt) {
        super.updateLiving(world, dt);
        if (!isOnGround() && !inWater() && ageSeconds() < hoppingUntil) {
            float tuck = 1f - Math.min(1f, Math.abs(velocity.y) / HOP_UP_SPEED) * 0.6f;
            mobVisualState().setPose(MobVisualState.Pose.HOP, tuck);
        } else {
            mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
        }
    }
}

package com.voxelgame.world.entity.mob.animal;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.core.Interactable;
import com.voxelgame.world.entity.ItemEntity;
import com.voxelgame.world.entity.mob.ai.MobGoal;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.PassiveMob;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import java.util.Objects;
import java.util.concurrent.ThreadLocalRandom;

/** Cừu đồng bằng có một màu len cố định, cắt lông bằng Shears và mọc lại lông khi ăn cỏ. */
public final class Sheep extends PassiveMob implements Interactable {
    /** Sáu màu len tự nhiên và biên trên không bao gồm của mỗi khoảng sinh. */
    public enum WoolColor {
        WHITE(0xffffff, 81_836, Item.WHITE_WOOL),
        LIGHT_GRAY(0xb5b7ad, 86_836, Item.LIGHT_GRAY_WOOL),
        GRAY(0x575953, 91_836, Item.GRAY_WOOL),
        BLACK(0x26252a, 96_836, Item.BLACK_WOOL),
        BROWN(0x85543a, 99_836, Item.BROWN_WOOL),
        PINK(0xed96af, 100_000, Item.PINK_WOOL);

        /** Bảng khoảng cố định và miền của bộ chọn, không sao chép mảng khi chọn màu. */
        private static final WoolColor[] COLORS = values();
        private static final int TOTAL_ROLLS = 100_000;
        private final int rgb;
        private final int upperBound;
        private final Item woolItem;

        /** Gắn màu nhân lên len, khoảng tích lũy và vật phẩm len tương ứng. */
        WoolColor(int rgb, int upperBound, Item woolItem) {
            this.rgb = rgb;
            this.upperBound = upperBound;
            this.woolItem = woolItem;
        }

        /** Đổi một giá trị đều trong 100.000 phần sang màu tự nhiên của cừu. */
        public static WoolColor fromRoll(int roll) {
            if (roll < 0 || roll >= TOTAL_ROLLS) {
                throw new IllegalArgumentException("Giá trị chọn màu len ngoài miền");
            }
            for (WoolColor color : COLORS) {
                if (roll < color.upperBound) {
                    return color;
                }
            }
            throw new IllegalStateException("Bảng màu len thiếu khoảng cuối");
        }

        /** Trả màu RGB chỉ dùng cho lớp len. */
        public int rgb() { return rgb; }

        /** Trả vật phẩm len tương ứng khi cắt lông hoặc khi cừu chết. */
        public Item woolItem() { return woolItem; }
    }

    /** Xác suất ăn cỏ mỗi tick (1/20s) chuẩn Minecraft: 1/1000 cho cừu lớn và 1/50 cho cừu con. */
    public static final int ADULT_GRAZE_CHANCE_DIVISOR = 1000;
    public static final int BABY_GRAZE_CHANCE_DIVISOR = 50;

    /** Màu len và trạng thái đã bị cắt lông theo cá thể, model vẫn được chia sẻ. */
    private final WoolColor woolColor;
    private boolean sheared;

    /** Chọn màu len khi sinh theo các xác suất tự nhiên. */
    public Sheep(float x, float y, float z) {
        this(x, y, z, WoolColor.fromRoll(ThreadLocalRandom.current().nextInt(WoolColor.TOTAL_ROLLS)));
    }

    /** Tạo một cá thể có màu được chỉ định, dùng cùng luồng hành vi và kết xuất. */
    public Sheep(float x, float y, float z, WoolColor woolColor) {
        super(MobType.SHEEP, x, y, z);
        this.woolColor = Objects.requireNonNull(woolColor);
        setMoveSpeed(2.3f);
        mobVisualState().setSheepWoolColor(woolColor.rgb());
        goals().add(new GrazeGoal());
    }

    /** Trả màu len tự nhiên đã chọn cho cá thể. */
    public WoolColor woolColor() { return woolColor; }

    /** Cho biết cừu đã bị cắt lông và đang chờ ăn cỏ để mọc lại hay chưa. */
    public boolean isSheared() { return sheared; }

    /** Xử lý Lượt 2 (Interactable): cắt 1–3 khối len khi người chơi cầm Shears. */
    @Override
    public boolean onInteract(World world, Player player, Item heldItem) {
        if (!isAlive() || isBaby() || sheared || player == null || !player.isAlive()) {
            return false;
        }
        if (heldItem == Item.SHEARS) {
            shear(world);
            return true;
        }
        return false;
    }

    /** Cắt lông cừu, ẩn lớp phủ len và rơi 1–3 khối len đúng màu tự nhiên. */
    public void shear(World world) {
        if (sheared) {
            return;
        }
        sheared = true;
        mobVisualState().setSheepSheared(true);
        if (world != null) {
            int count = ThreadLocalRandom.current().nextInt(1, 4);
            for (int i = 0; i < count; i++) {
                world.spawnDroppedItem(new ItemEntity(x(), y() + 0.5f, z(), woolColor.woolItem()));
            }
            AudioManager audio = world.getAudio();
            if (audio != null) {
                audio.playEffect(AudioManager.Effect.CLICK, 0.45f);
            }
            playSound(world, MobSoundEvent.AMBIENT);
        }
    }

    /** Mọc lại lớp lông sau khi cừu ăn cỏ thành công. */
    public void regrowWool() {
        if (sheared) {
            sheared = false;
            mobVisualState().setSheepSheared(false);
        }
    }

    /** Giữ tư thế cúi đầu tới lúc ăn, dùng đường thay block bình thường để cập nhật cây cạnh. */
    private static final class GrazeGoal implements MobGoal {
        /** Nhịp kiểm tra 1 tick (0,05s) và các mốc thời gian cúi đầu ăn cỏ. */
        private static final float TICK_SECONDS = 0.05f;
        private static final float EASE_SECONDS = 0.35f;
        private static final float EAT_SECONDS = 0.9f;
        private static final float DURATION = 1.45f;
        /** Sai số nhỏ khi đọc mặt đỡ ở biên độ cao nguyên. */
        private static final float GROUND_EPSILON = 0.001f;
        private float elapsed;
        private int foodX;
        private int foodY;
        private int foodZ;
        private Block food;

        /** Đặt ăn trước Wander nhưng cho phép chạy hoảng thay quyền. */
        @Override public int priority() { return 5; }
        /** Giữ cả chuyển động ngang và đầu để tránh tư thế xung đột. */
        @Override public int controls() { return MOVE | LOOK; }
        /** Rút thăm đúng theo nhịp 20 Hz chuẩn Minecraft, không phụ thuộc 60 FPS. */
        @Override public float retrySeconds() { return TICK_SECONDS; }

        /** Rút thăm 1/1000 (trưởng thành) hoặc 1/50 (con non), rồi kiểm tra Short Grass hoặc Grass Block dưới chân. */
        @Override
        public boolean canStart(World world, MobEntity sheep) {
            if (!sheep.isOnGround() || sheep.inWater() || sheep.panicTime() > 0f) {
                return false;
            }
            int divisor = sheep.isBaby() ? BABY_GRAZE_CHANCE_DIVISOR : ADULT_GRAZE_CHANCE_DIVISOR;
            if (ThreadLocalRandom.current().nextInt(divisor) != 0) {
                return false;
            }
            foodX = floor(sheep.x());
            foodY = floor(sheep.y() + GROUND_EPSILON);
            foodZ = floor(sheep.z());
            if (world.getBlock(foodX, foodY, foodZ) == Block.SHORT_GRASS.getId()) {
                food = Block.SHORT_GRASS;
                return true;
            }
            foodY = floor(sheep.y() - GROUND_EPSILON);
            if (world.getBlock(foodX, foodY, foodZ) == Block.GRASS.getId()) {
                food = Block.GRASS;
                return true;
            }
            return false;
        }

        /** Hủy tư thế nếu cừu bị xô khỏi ô ăn hoặc đang cần thoát hiểm. */
        @Override
        public boolean shouldContinue(World world, MobEntity sheep) {
            return elapsed < DURATION && sheep.isOnGround() && !sheep.inWater() && sheep.panicTime() <= 0f
                    && floor(sheep.x()) == foodX && floor(sheep.z()) == foodZ;
        }

        /** Bắt đầu cúi từ tư thế đứng và dừng lệnh di chuyển còn lại. */
        @Override
        public void start(World world, MobEntity sheep) {
            elapsed = 0f;
            sheep.stopMoving();
        }

        /** Nội suy góc cúi, xác nhận đúng khối tại mốc ăn rồi đổi trạng thái và mọc lại lông. */
        @Override
        public void tick(World world, MobEntity sheep, float dt) {
            float previous = elapsed;
            elapsed = Math.min(DURATION, elapsed + dt);
            float lower = Math.min(1f, elapsed / EASE_SECONDS);
            float raise = Math.min(1f, (DURATION - elapsed) / EASE_SECONDS);
            sheep.mobVisualState().setPose(MobVisualState.Pose.GRAZE, lower * raise);
            if (previous < EAT_SECONDS && elapsed >= EAT_SECONDS
                    && world.getBlock(foodX, foodY, foodZ) == food.getId()) {
                Block replacement = food == Block.SHORT_GRASS ? Block.AIR : Block.DIRT;
                world.setBlock(foodX, foodY, foodZ, replacement.getId());
                if (sheep instanceof Sheep actualSheep) {
                    actualSheep.regrowWool();
                }
            }
        }

        /** Đưa đầu về tư thế thường lúc ăn xong hoặc bị goal ưu tiên hơn ngắt. */
        @Override
        public void stop(World world, MobEntity sheep) {
            sheep.mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
        }

        /** Đổi tọa độ thành ô voxel. */
        private static int floor(float coordinate) {
            return (int) Math.floor(coordinate);
        }
    }
}

package com.voxelgame.world.entity.mob.animal;

import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.ItemEntity;
import com.voxelgame.world.entity.mob.ai.MobGoal;
import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.NeutralMob;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;
import com.voxelgame.world.physics.Raycast;

import com.badlogic.gdx.math.Vector3;
import java.util.Arrays;
import java.util.concurrent.ThreadLocalRandom;

/** Cáo tuyết nghỉ ở nơi an toàn ban ngày, săn ban đêm và tránh người không rón rén. */
public final class SnowFox extends NeutralMob {
    /** Tầm phát hiện người, tầm tìm con mồi và nhịp xét tầm nhìn và vật phẩm. */
    private static final float PLAYER_RANGE = 12f;
    private static final float PREY_RANGE = 16f;
    private static final float SIGHT_INTERVAL = 0.12f;
    private static final float PICKUP_INTERVAL = 0.3f;
    private static final float PICKUP_RANGE = 1.2f;
    /** Xác suất cáo con trong bầy. */
    private static final float BABY_PROBABILITY = 0.05f;

    /** Bộ đệm tia dùng cả cho nhận diện người và săn mồi. */
    private final Vector3 sightOrigin = new Vector3();
    private final Vector3 sightDirection = new Vector3();
    private final Vector3 playerCenter = new Vector3();
    private final Raycast.HitResult occluder = Raycast.HitResult.miss();
    private Player seenPlayer;
    private Player sightCandidate;
    private double nextSight;
    private double nextPickup;
    private boolean sleeping;

    /** Dựng cáo lông tuyết, chọn ngẫu nhiên cá thể non và thiết lập ưu tiên né người rồi mới săn. */
    public SnowFox(float x, float y, float z) {
        super(MobType.SNOW_FOX, x, y, z, 0f, 0, false);
        setMoveSpeed(3.5f);
        setBaby(ThreadLocalRandom.current().nextFloat() < BABY_PROBABILITY);
        goals().add(new MobGoals.FloatInWaterGoal(0));
        goals().add(new MobGoals.FleeEntityGoal(1, PLAYER_RANGE, 1.55f, entity -> entity == seenPlayer));
        goals().add(new MobGoals.MeleeAttackGoal(2, 1.1f, 2f, 0.75f, 1f, 16f));
        goals().add(new FoxPounceGoal());
        goals().add(new SleepGoal());
        goals().add(new MobGoals.WanderGoal(6, 9, 0.7f));
        goals().add(new MobGoals.LookAtPlayerGoal(7, 8f));
        goals().add(new MobGoals.RandomLookAroundGoal(8));
    }

    /** Cho biết cá thể đã đến nơi trú và đang cuộn tròn ngủ. */
    public boolean isSleeping() {
        return sleeping;
    }

    /** Cập nhật người gây sợ trước khi bộ chọn dừng ngủ hoặc hủy việc tiếp cận con mồi. */
    @Override
    protected void updateGoals(World world, float dt) {
        updatePlayerSight(world);
        super.updateGoals(world, dt);
        if (!sleeping && seenPlayer == null && mobVisualState().heldBlock() == null && ageSeconds() >= nextPickup) {
            nextPickup = ageSeconds() + PICKUP_INTERVAL;
            Block carried = world.takeNearbyDroppedBlock(x(), y() + getHeight() * 0.5f, z(), PICKUP_RANGE);
            if (carried != null) {
                mobVisualState().setHeldBlock(carried);
            }
        }
    }

    /** Trả vật phẩm trong miệng về thế giới khi chết, kể cả khi vòng đời kết thúc ngay. */
    @Override
    protected void finishLivingUpdate(World world) {
        if (!isAlive()) {
            setSleeping(false);
            Block carried = mobVisualState().heldBlock();
            if (carried != null) {
                mobVisualState().setHeldBlock(null);
                world.spawnDroppedItem(new ItemEntity(x(), y() + 0.25f, z(), carried));
            }
        }
        super.finishLivingUpdate(world);
    }

    /** Bỏ người đang rón rén ngay lập tức; kiểm tra tia định kỳ đối với người đã vào tầm. */
    private void updatePlayerSight(World world) {
        Player player = world.getPlayer();
        if (player == null || !player.isAlive() || player.isSneaking()) {
            sightCandidate = null;
            seenPlayer = null;
            return;
        }
        player.copyCenterPosition(playerCenter);
        float dx = playerCenter.x - x();
        float dy = playerCenter.y - (y() + getHeight() * 0.5f);
        float dz = playerCenter.z - z();
        if (dx * dx + dy * dy + dz * dz > PLAYER_RANGE * PLAYER_RANGE) {
            sightCandidate = null;
            seenPlayer = null;
            return;
        }
        if (player != sightCandidate || ageSeconds() >= nextSight) {
            sightCandidate = player;
            nextSight = ageSeconds() + SIGHT_INTERVAL;
            seenPlayer = canSee(world, playerCenter.x, playerCenter.y, playerCenter.z) ? player : null;
        }
    }

    /** Kiểm tra đường nhìn từ cao độ đầu cáo đến mục tiêu. */
    private boolean canSee(World world, float x, float y, float z) {
        sightOrigin.set(x(), y() + getHeight() * 0.75f, z());
        sightDirection.set(x, y, z).sub(sightOrigin);
        float distance = sightDirection.len();
        return distance < 0.0001f
                || !Raycast.castOccluder(world, sightOrigin, sightDirection, distance, occluder).isHit();
    }

    /** Dùng cùng ngưỡng độ cao mặt trời với hành vi tiếp xúc ánh nắng. */
    private static boolean daylight(World world) {
        return world.worldTime().sunY() > 0.05f;
    }

    /** Chuyển đồng thời tư thế ngủ và tấm ảnh da, giữ hình thể của cá thể hiện tại. */
    private void setSleeping(boolean sleeping) {
        if (this.sleeping == sleeping) {
            return;
        }
        this.sleeping = sleeping;
        mobVisualState().setAppearance(sleeping ? MobAppearance.SNOW_FOX_SLEEP : MobAppearance.SNOW_FOX);
        mobVisualState().setPose(sleeping ? MobVisualState.Pose.SLEEP : MobVisualState.Pose.IDLE, sleeping ? 1f : 0f);
    }

    /** Cho phép ngủ trên tuyết hoặc ngay dưới tán vân sam trong độ cao hữu hạn. */
    private static boolean shelteredBySnowOrSpruce(World world, int x, float feetY, int z) {
        int feet = (int) Math.floor(feetY + 0.08f);
        int ground = (int) Math.floor(feetY - 0.08f);
        byte surface = world.getBlock(x, ground, z);
        if (surface == Block.SNOW_BLOCK.getId() || surface == Block.SNOW_LAYER.getId()
                || world.getBlock(x, feet, z) == Block.SNOW_LAYER.getId()) {
            return true;
        }
        for (int y = feet + 1; y <= feet + 7; y++) {
            if (world.getBlock(x, y, z) == Block.SPRUCE_LEAVES.getId()) {
                return true;
            }
        }
        return false;
    }

    /** Tìm chỗ ngủ theo khoảng cách; mục tiêu chỉ quét một phần nhỏ bán kính trong mỗi nhịp. */
    private final class SleepGoal implements MobGoal {
        /** Bán kính ô có thể ngủ và ngân sách xét trong một lượt. */
        private static final int RADIUS = 6;
        private static final int SEARCH_BUDGET = 20;
        private static final int[] OFFSETS = nearbyOffsets();
        private int searchX = Integer.MIN_VALUE;
        private int searchY;
        private int searchZ;
        private int cursor;
        private float restX;
        private float restY;
        private float restZ;
        private double arriveBefore;

        /** Chuẩn bị thứ tự ô từ gần đến xa khi lớp mục tiêu được nạp. */
        private static int[] nearbyOffsets() {
            int diameter = 2 * RADIUS + 1;
            int[] pairs = new int[diameter * diameter * 2];
            int length = 0;
            for (int distance = 1; distance <= RADIUS * RADIUS; distance++) {
                for (int dx = -RADIUS; dx <= RADIUS; dx++) {
                    for (int dz = -RADIUS; dz <= RADIUS; dz++) {
                        if (dx * dx + dz * dz == distance) {
                            pairs[length++] = dx;
                            pairs[length++] = dz;
                        }
                    }
                }
            }
            return Arrays.copyOf(pairs, length);
        }

        /** Ngủ có quyền trước đi lang thang và nhìn ngẫu nhiên. */
        @Override
        public int priority() { return 4; }

        /** Đường đi, tư thế và hướng đầu được giành từ lúc tìm được vị trí. */
        @Override
        public int controls() { return MOVE | LOOK; }

        /** Phân tán chi phí tìm chỗ ngủ của các cá thể cùng bầy. */
        @Override
        public float retrySeconds() { return 0.16f + ThreadLocalRandom.current().nextFloat() * 0.07f; }

        /** Cáo chỉ ngủ ban ngày khi không có nguy hiểm hoặc mục tiêu đang đối đầu. */
        private boolean safeToRest(World world) {
            return daylight(world) && seenPlayer == null && target() == null && !inWater()
                    && getHurtFlashTimer() <= 0f && getFireTimer() <= 0f;
        }

        /** Thử chỗ hiện tại trước, sau đó dùng thứ tự ô lân cận đã tính sẵn. */
        @Override
        public boolean canStart(World world, MobEntity mob) {
            if (!safeToRest(world)) {
                searchX = Integer.MIN_VALUE;
                return false;
            }
            int x = (int) Math.floor(x());
            int y = (int) Math.floor(y());
            int z = (int) Math.floor(z());
            if (shelteredBySnowOrSpruce(world, x, y(), z)) {
                restX = x();
                restY = y();
                restZ = z();
                return true;
            }
            if (searchX != x || searchY != y || searchZ != z || cursor >= OFFSETS.length) {
                searchX = x;
                searchY = y;
                searchZ = z;
                cursor = 0;
            }
            for (int i = 0; i < SEARCH_BUDGET && cursor < OFFSETS.length; i++) {
                int candidateX = searchX + OFFSETS[cursor++];
                int candidateZ = searchZ + OFFSETS[cursor++];
                if (!shelteredBySnowOrSpruce(world, candidateX, searchY, candidateZ)) {
                    continue;
                }
                float feet = navigator().findStandableY(world, candidateX, searchY, candidateZ);
                if (Float.isFinite(feet) && shelteredBySnowOrSpruce(world, candidateX, feet, candidateZ)) {
                    restX = candidateX + 0.5f;
                    restY = feet;
                    restZ = candidateZ + 0.5f;
                    return true;
                }
            }
            return false;
        }

        /** Dừng ngủ khi trời tối, có người gây sợ hoặc nơi trú không còn hợp lệ. */
        @Override
        public boolean shouldContinue(World world, MobEntity mob) {
            return safeToRest(world) && (sleeping
                    ? isOnGround() && shelteredBySnowOrSpruce(world, (int) Math.floor(x()), y(), (int) Math.floor(z()))
                    : ageSeconds() < arriveBefore);
        }

        /** Giới hạn thời gian thử tới vị trí có mái, để không chạy mãi vào một góc bít. */
        @Override
        public void start(World world, MobEntity mob) {
            arriveBefore = ageSeconds() + 5;
        }

        /** Di chuyển về nơi trú rồi dừng lại và cuộn tròn ngay khi đất đã đỡ chân. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            if (isOnGround() && shelteredBySnowOrSpruce(world, (int) Math.floor(x()), y(), (int) Math.floor(z()))) {
                stopMoving();
                setSleeping(true);
            } else {
                moveToward(world, restX, restY, restZ, 0.8f);
            }
        }

        /** Bỏ pose ngủ để trả quyền cho mục tiêu chạy trốn hoặc hoạt động ban đêm. */
        @Override
        public void stop(World world, MobEntity mob) {
            setSleeping(false);
            stopMoving();
        }
    }

    /** Pha tiến lại gần, lấy đà, nhảy và hồi lại sau khi trượt xuống tuyết mỏng. */
    private enum PouncePhase { APPROACH, CROUCH, AIRBORNE, FACEPLANT, DONE }

    /** Nhắm thỏ hoặc gà, thu người lấy đà và đánh khi vồ chạm con mồi trong lúc hạ xuống. */
    private final class FoxPounceGoal implements MobGoal {
        /** Vận tốc đứng, trọng lực và giới hạn quãng ngang của vòng cung ngắn. */
        private static final float LAUNCH_Y = 10.6f;
        private static final float GRAVITY = 26f;
        private static final float LAUNCH_RANGE_SQUARED = 5.6f * 5.6f;
        /** Giới hạn đuổi tới tầm bật khi con mồi ở sau vật cản. */
        private static final float APPROACH_SECONDS = 6f;
        private static final float CROUCH_SECONDS = 0.35f;
        private static final float FACEPLANT_SECONDS = 0.6f;
        private static final float RECOVERY_SECONDS = 1.35f;
        private MobEntity prey;
        private PouncePhase phase = PouncePhase.DONE;
        private double phaseUntil;
        private double nextPounce;
        private boolean struck;

        /** Săn mồi đứng sau hành vi trốn và tự vệ. */
        @Override
        public int priority() { return 3; }

        /** Tiến gần, ngắm và bật nhảy thuộc cùng một vòng vồ. */
        @Override
        public int controls() { return MOVE | LOOK | JUMP; }

        /** Giới hạn tần suất quét con mồi xung quanh. */
        @Override
        public float retrySeconds() { return 0.28f + ThreadLocalRandom.current().nextFloat() * 0.12f; }

        /** Chọn con mồi còn sống, gần nhất và nhìn thấy trong bán kính mười sáu block. */
        @Override
        public boolean canStart(World world, MobEntity mob) {
            if (ageSeconds() < nextPounce || daylight(world) || seenPlayer != null || target() != null || inWater()) {
                return false;
            }
            prey = null;
            float best = PREY_RANGE * PREY_RANGE;
            for (int i = 0, count = world.entityCount(); i < count; i++) {
                if (!(world.entityAt(i) instanceof MobEntity candidate) || !isPrey(candidate) || !candidate.isAlive()) {
                    continue;
                }
                float dx = candidate.x() - x();
                float dy = candidate.y() - y();
                float dz = candidate.z() - z();
                float distance = dx * dx + dy * dy + dz * dz;
                if (distance <= best && canSee(world, candidate.x(),
                        candidate.y() + candidate.getHeight() * 0.5f, candidate.z())) {
                    best = distance;
                    prey = candidate;
                }
            }
            return prey != null;
        }

        /** Nhận hai cấu hình thỏ và gà, không phụ thuộc lớp triển khai cụ thể của con mồi. */
        private boolean isPrey(MobEntity candidate) {
            MobType type = candidate.type();
            return type == MobType.RABBIT || type == MobType.SNOW_RABBIT || type == MobType.CHICKEN;
        }

        /** Giữ quyền cho đến khi đáp đất, ngay cả khi con mồi vừa chết giữa vòng cung. */
        @Override
        public boolean shouldContinue(World world, MobEntity mob) {
            if (phase == PouncePhase.AIRBORNE) {
                return ageSeconds() < phaseUntil;
            }
            if (phase == PouncePhase.FACEPLANT) {
                return true;
            }
            if (phase == PouncePhase.DONE || prey == null || !prey.isAlive() || daylight(world) || inWater()) {
                return false;
            }
            if (phase == PouncePhase.APPROACH && ageSeconds() >= phaseUntil) {
                return false;
            }
            float dx = prey.x() - x();
            float dz = prey.z() - z();
            return dx * dx + dz * dz <= (PREY_RANGE + 2f) * (PREY_RANGE + 2f);
        }

        /** Bắt đầu bằng bước tiếp cận; có thể lấy đà ngay nếu đã đứng đủ gần. */
        @Override
        public void start(World world, MobEntity mob) {
            phase = PouncePhase.APPROACH;
            phaseUntil = ageSeconds() + APPROACH_SECONDS;
            struck = false;
        }

        /** Chuyển pha lấy đà, phóng, ghi đòn trúng và xử lý tuyết khi đáp. */
        @Override
        public void tick(World world, MobEntity mob, float dt) {
            switch (phase) {
                case APPROACH -> approach(world);
                case CROUCH -> aimAndLaunch(world);
                case AIRBORNE -> finishLeap(world);
                case FACEPLANT -> {
                    stopMoving();
                    if (ageSeconds() >= phaseUntil) {
                        phase = PouncePhase.DONE;
                    }
                }
                case DONE -> stopMoving();
            }
        }

        /** Tiến tới tầm bật; chỉ hạ thân lấy đà trên mặt đất có đường nhìn. */
        private void approach(World world) {
            float dx = prey.x() - x();
            float dz = prey.z() - z();
            if (isOnGround() && dx * dx + dz * dz <= LAUNCH_RANGE_SQUARED && Math.abs(prey.y() - y()) <= 1.6f
                    && canSee(world, prey.x(), prey.y() + prey.getHeight() * 0.5f, prey.z())) {
                phase = PouncePhase.CROUCH;
                phaseUntil = ageSeconds() + CROUCH_SECONDS;
                stopMoving();
                mobVisualState().setPose(MobVisualState.Pose.CROUCH, 0f);
            } else {
                moveToward(world, prey.x(), prey.y(), prey.z(), 0.85f);
            }
        }

        /** Hướng thân vào con mồi và tính vận tốc ngang để vòng cung gặp chỗ đứng dự kiến. */
        private void aimAndLaunch(World world) {
            stopMoving();
            lookAt(prey.x(), prey.y() + prey.getHeight() * 0.5f, prey.z());
            faceBody(prey.x(), prey.z());
            float remaining = (float) (phaseUntil - ageSeconds());
            if (remaining > 0f) {
                mobVisualState().setPose(MobVisualState.Pose.CROUCH, 1f - remaining / CROUCH_SECONDS);
                return;
            }
            float dx = prey.x() - x();
            float dz = prey.z() - z();
            float landing = navigator().findStandableY(world, (int) Math.floor(prey.x()),
                    (int) Math.floor(y()), (int) Math.floor(prey.z()));
            float discriminant = LAUNCH_Y * LAUNCH_Y - 2f * GRAVITY * (landing - y());
            if (!isOnGround() || !(discriminant > 0f) || dx * dx + dz * dz > LAUNCH_RANGE_SQUARED
                    || !canSee(world, prey.x(), prey.y() + prey.getHeight() * 0.5f, prey.z())) {
                phase = PouncePhase.DONE;
                return;
            }
            float flight = (LAUNCH_Y + (float) Math.sqrt(discriminant)) / GRAVITY;
            float horizontalTime = flight - 0.025f;
            queueLeap(dx / horizontalTime, LAUNCH_Y, dz / horizontalTime, flight);
            phase = PouncePhase.AIRBORNE;
            phaseUntil = ageSeconds() + flight + 0.65f;
            mobVisualState().setPose(MobVisualState.Pose.POUNCE, 1f);
        }

        /** Ghi sát thương một lần ở phần đi xuống và cho trượt vào tuyết khi cú vồ hụt. */
        private void finishLeap(World world) {
            boolean landed = isOnGround();
            if (!struck && prey != null && prey.isAlive() && velocity.y <= 0f) {
                float dx = prey.x() - x();
                float dz = prey.z() - z();
                float reach = getHalfWidth() + prey.getHalfWidth() + 0.18f;
                if (dx * dx + dz * dz <= reach * reach && y() <= prey.y() + prey.getHeight() + 0.2f
                        && y() + getHeight() >= prey.y()
                        && canSee(world, prey.x(), prey.y() + prey.getHeight() * 0.5f, prey.z())) {
                    struck = strikeMelee(world, prey, 2f, dx * 3f, dz * 3f);
                }
            }
            if (landed || inWater()) {
                int blockX = (int) Math.floor(x());
                int blockY = (int) Math.floor(y() + 0.08f);
                int blockZ = (int) Math.floor(z());
                if (landed && !struck && world.getBlock(blockX, blockY, blockZ) == Block.SNOW_LAYER.getId()
                        && world.getBlockState(blockX, blockY, blockZ) < 3) {
                    phase = PouncePhase.FACEPLANT;
                    phaseUntil = ageSeconds() + FACEPLANT_SECONDS;
                    mobVisualState().setPose(MobVisualState.Pose.FACEPLANT, 1f);
                } else {
                    phase = PouncePhase.DONE;
                }
            }
        }

        /** Hạ tư thế đặc biệt và chừa khoảng lấy lại thăng bằng trước lần vồ kế tiếp. */
        @Override
        public void stop(World world, MobEntity mob) {
            prey = null;
            phase = PouncePhase.DONE;
            nextPounce = ageSeconds() + RECOVERY_SECONDS;
            stopMoving();
            mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
        }
    }
}

package com.voxelgame.world.entity.mob.animal;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.core.Interactable;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.ai.MobGoal;
import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.NeutralMob;
import com.voxelgame.world.entity.player.Hotbar;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.item.FoodRegistry;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.Vector3;
import java.util.concurrent.ThreadLocalRandom;

/**
 * Sói tuyết:
 * - Khi hoang dã ({@code !tamed}): săn mồi tự nhiên và gọi đàn trong 16 block khi bị người chơi tấn công.
 * - Khi đã thuần hóa ({@code tamed}) bằng {@link Item#BONE} (tỷ lệ 1/3): nâng máu tối đa lên 20 HP,
 *   lưu giữ lâu dài ({@code persistent}), cho phép ngồi/đứng, đi theo chủ (hoặc dịch chuyển nếu cách > 24 block),
 *   không bao giờ tấn công chủ và bảo vệ chủ qua {@link #onOwnerAttackOrHurt(LivingEntity)}.
 */
public final class Wolf extends NeutralMob implements Interactable {
    /** Phạm vi gọi đàn và tìm mồi, dùng khoảng cách ba chiều. */
    private static final float PACK_RANGE_SQUARED = 16f * 16f;
    /** Cho sói ở rìa đàn đủ tầm đánh trả, giữ tầm săn cũ cho mồi tự nhiên. */
    private static final float PLAYER_PURSUIT_RANGE = 32f;
    private static final float PREY_PURSUIT_RANGE = 20f;
    /** Khoảng giận lấy ngẫu nhiên theo từng cá thể khi người chơi đánh trúng. */
    private static final int MIN_ANGER_SECONDS = 20;
    private static final int MAX_ANGER_SECONDS = 39;
    /** Thông số thuần hóa chuẩn Minecraft: xác suất 1/3 mỗi Bone, tối đa 20 HP và khoảng cách theo chủ. */
    private static final float TAME_CHANCE = 1f / 3f;
    private static final float TAMED_MAX_HEALTH = 20f;
    private static final float FOLLOW_START_DISTANCE_SQUARED = 10f * 10f;
    private static final float FOLLOW_STOP_DISTANCE_SQUARED = 3f * 3f;
    private static final float TELEPORT_DISTANCE_SQUARED = 24f * 24f;
    private static final float FOLLOW_SPEED_MULTIPLIER = 1.15f;

    /** Đệm vị trí dùng lại trong lượt ngắm, tìm mồi và dịch chuyển theo chủ (zero-GC). */
    private final Vector3 nearby = new Vector3();
    private float huntDelay;
    private float shakeRemaining;
    private boolean wasWet;
    /** Trạng thái thuần hóa, tư thế ngồi và tham chiếu chủ sở hữu. */
    private boolean tamed;
    private boolean sitting;
    private Player owner;

    /** Tạo sói tuyết trưởng thành, dùng 4 HP mỗi cú cắn. */
    public Wolf(float x, float y, float z) {
        super(MobType.WOLF, x, y, z, 0f, 0, false);
        setMoveSpeed(3f);
        MobGoals.addDefaults(goals(), type(), false);
        goals().add(new SitGoal());
        goals().add(new MobGoals.MeleeAttackGoal(4, 1.35f, 4f, 1.55f, 1f, PLAYER_PURSUIT_RANGE));
        goals().add(new FollowOwnerGoal());
    }

    /** Tìm mồi theo nhịp riêng khi hoang dã; đi theo, ngồi hoặc dịch chuyển theo chủ khi đã thuần hóa. */
    @Override
    protected void updateGoals(World world, float dt) {
        if (tamed) {
            // Bảo vệ tuyệt đối: không bao giờ giữ chủ hoặc đồng đội cùng chủ làm mục tiêu
            LivingEntity currentTarget = target();
            if (currentTarget == owner || (currentTarget instanceof Wolf otherWolf
                    && otherWolf.isTamed() && otherWolf.owner == owner)) {
                setTarget(null);
            }
            if (sitting) {
                setTarget(null);
                stopMoving();
            } else {
                LivingEntity prey = target();
                float range = prey instanceof Player ? PLAYER_PURSUIT_RANGE : PREY_PURSUIT_RANGE;
                if (prey != null && distanceSquared(prey) > range * range) {
                    setTarget(null);
                }
                if (owner != null && owner.isAlive() && distanceSquared(owner) > TELEPORT_DISTANCE_SQUARED) {
                    teleportNearOwner(world);
                }
            }
        } else {
            huntDelay -= dt;
            LivingEntity prey = target();
            float range = prey instanceof Player ? PLAYER_PURSUIT_RANGE : PREY_PURSUIT_RANGE;
            if (prey != null && distanceSquared(prey) > range * range) {
                setTarget(null);
            }
            if (target() == null && huntDelay <= 0f) {
                huntDelay = 0.5f;
                setTarget(findPrey(world));
            }
        }
        super.updateGoals(world, dt);

        if (inWater()) {
            wasWet = true;
            shakeRemaining = 0f;
        } else if (wasWet && onGround) {
            wasWet = false;
            shakeRemaining = 0.85f;
        }
        updateAppearance();
        Player player = world.getPlayer();
        if (tamed && sitting) {
            shakeRemaining = 0f;
            mobVisualState().setPose(MobVisualState.Pose.SIT, 1f);
        } else if (target() instanceof Player) {
            shakeRemaining = 0f;
            mobVisualState().setPose(MobVisualState.Pose.ANGRY, 1f);
        } else if (shakeRemaining > 0f) {
            stopMoving();
            shakeRemaining = Math.max(0f, shakeRemaining - dt);
            mobVisualState().setPose(MobVisualState.Pose.SHAKE, shakeRemaining / 0.85f);
        } else if (target() == null && player != null && player.isAlive() && distanceSquared(player) <= 25f) {
            lookAt(nearby.x, nearby.y, nearby.z);
            mobVisualState().setPose(MobVisualState.Pose.TILT_HEAD, 1f);
        } else {
            mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
        }
    }

    /**
     * Xử lý Lượt 2 (Interactable): thuần hóa bằng Bone, cho ăn hồi máu hoặc bật/tắt ngồi.
     */
    @Override
    public boolean onInteract(World world, Player player, Item heldItem) {
        if (!isAlive() || player == null || !player.isAlive()) {
            return false;
        }
        boolean handled = interactWithPlayer(player, heldItem == null ? Item.NONE : heldItem);
        if (handled && world != null && world.getAudio() != null) {
            world.getAudio().playEffect(AudioManager.Effect.CLICK, 0.35f);
        }
        return handled;
    }

    /**
     * Tương tác giữa người chơi và sói bằng vật phẩm đang cầm ({@link Item#BONE} để thuần hóa,
     * tay không hoặc vật phẩm thường để bật/tắt ngồi sau khi thuần hóa).
     *
     * @param player   người chơi tương tác
     * @param heldItem vật phẩm đang cầm (có thể là {@link Item#NONE} hoặc {@code null})
     * @return {@code true} nếu tương tác đã được xử lý
     */
    public boolean interactWithPlayer(Player player, Item heldItem) {
        return interactWithPlayer(player, heldItem, ThreadLocalRandom.current().nextFloat());
    }

    /**
     * Phiên bản xác định trước kết quả ngẫu nhiên trong {@code [0, 1)} phục vụ kiểm thử đơn vị.
     *
     * @param player      người chơi tương tác
     * @param heldItem    vật phẩm đang cầm
     * @param rollForTest giá trị tung xác suất thuần hóa (thành công khi {@code rollForTest < 1/3f})
     * @return {@code true} nếu tương tác đã được xử lý
     */
    public boolean interactWithPlayer(Player player, Item heldItem, float rollForTest) {
        if (!isAlive() || player == null || !player.isAlive()) {
            return false;
        }
        Hotbar hotbar = player.getHotbar();
        if (!tamed) {
            // Sói hoang đang tấn công chính người chơi này thì không cho phép thuần hóa
            if (heldItem != Item.BONE || target() == player) {
                return false;
            }
            if (hotbar != null && hotbar.getSelectedItem() == Item.BONE && hotbar.getSelectedCount() > 0) {
                hotbar.consumeSelectedItemStack();
            }
            if (rollForTest < TAME_CHANCE) {
                tamed = true;
                owner = player;
                sitting = false;
                setPersistent(true);
                setTarget(null);
                stopMoving();
                setMaxHealth(TAMED_MAX_HEALTH, true);
                updateAppearance();
                mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
            }
            return true;
        }

        // Sau khi thuần hóa, chỉ chủ sở hữu mới có quyền ra lệnh ngồi/đứng hoặc cho ăn hồi máu
        if (owner != null && player != owner) {
            return false;
        }
        if (heldItem == Item.FLINT_AND_STEEL) {
            return false;
        }
        if (getHealth() < getMaxHealth() && isWolfFood(heldItem)) {
            FoodRegistry.FoodSpec spec = FoodRegistry.of(heldItem);
            if (spec != null) {
                if (hotbar != null && hotbar.getSelectedItem() == heldItem && hotbar.getSelectedCount() > 0) {
                    hotbar.consumeSelectedItemStack();
                }
                heal(spec.nutrition());
                return true;
            }
        }
        sitting = !sitting;
        if (sitting) {
            setTarget(null);
            stopMoving();
            mobVisualState().setPose(MobVisualState.Pose.SIT, 1f);
        } else {
            mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
        }
        return true;
    }

    /**
     * Thông báo cho sói đã thuần hóa về kẻ tấn công chủ hoặc mục tiêu mà chủ vừa đánh.
     * Bỏ qua nếu sói chưa thuần hóa, đang ngồi, đã chết, hoặc mục tiêu chính là chủ/đồng đội cùng chủ.
     *
     * @param threat thực thể thù địch liên quan đến chủ sở hữu
     */
    public void onOwnerAttackOrHurt(LivingEntity threat) {
        if (!tamed || !isAlive() || sitting || threat == null || !threat.isAlive()
                || threat == this || threat == owner) {
            return;
        }
        if (threat instanceof Wolf otherWolf && otherWolf.isTamed() && otherWolf.owner == owner) {
            return;
        }
        enrage(threat, MAX_ANGER_SECONDS);
    }

    /** Trả {@code true} nếu sói đã được thuần hóa. */
    public boolean isTamed() {
        return tamed;
    }

    /** Trả {@code true} nếu sói đang ở tư thế ngồi chờ lệnh. */
    public boolean isSitting() {
        return sitting;
    }

    /** Trả người chơi sở hữu sói này, hoặc {@code null} nếu còn hoang dã. */
    public Player getOwner() {
        return owner;
    }

    /** Chọn cá thể sống gần nhất trong các loài sói tuyết săn. */
    private MobEntity findPrey(World world) {
        MobEntity nearest = null;
        float best = PACK_RANGE_SQUARED;
        for (int index = 0, count = world.entityCount(); index < count; index++) {
            if (!(world.entityAt(index) instanceof MobEntity mob) || !mob.isAlive()) {
                continue;
            }
            boolean prey = switch (mob.type()) {
                case RABBIT, SNOW_RABBIT, SNOW_FOX, SHEEP, SKELETON, STRAY -> true;
                default -> false;
            };
            if (prey) {
                float distance = distanceSquared(mob);
                if (distance <= best) {
                    nearest = mob;
                    best = distance;
                }
            }
        }
        return nearest;
    }

    /**
     * Xử lý khi bị đánh trúng:
     * - Sói thuần hóa không bao giờ đánh trả chủ hoặc đồng đội cùng chủ, và đứng dậy đánh trả kẻ khác.
     * - Sói hoang giữ nguyên phản ứng gọi cả đàn trong 16 block tấn công người chơi.
     */
    @Override
    public boolean damage(World world, float amount, DamageSource source, Entity attacker,
                          float knockbackX, float knockbackZ) {
        boolean applied = super.damage(world, amount, source, attacker, knockbackX, knockbackZ);
        if (!applied) {
            return false;
        }
        if (tamed) {
            if (attacker == owner || (attacker instanceof Wolf otherWolf
                    && otherWolf.isTamed() && otherWolf.owner == owner)) {
                if (target() == attacker) {
                    setTarget(null);
                }
                updateAppearance();
                return true;
            }
            if (isAlive() && attacker instanceof LivingEntity living && living.isAlive()) {
                if (sitting) {
                    sitting = false;
                    mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
                }
                enrage(living, ThreadLocalRandom.current().nextInt(MIN_ANGER_SECONDS, MAX_ANGER_SECONDS + 1));
            }
            updateAppearance();
            return true;
        }
        if (world != null && attacker instanceof Player player && player.isAlive()) {
            if (isAlive()) {
                defendPack(world, player);
            }
            for (int index = 0, count = world.entityCount(); index < count; index++) {
                if (world.entityAt(index) instanceof Wolf wolf && wolf != this && !wolf.isTamed()
                        && wolf.isAlive() && distanceSquared(wolf) <= PACK_RANGE_SQUARED) {
                    wolf.defendPack(world, player);
                }
            }
        }
        return true;
    }

    /** Cập nhật đồng thời mục tiêu, texture và tiếng gầm khi cả đàn đáp trả. */
    private void defendPack(World world, Player player) {
        if (mobVisualState().appearance() != MobAppearance.WOLF_SNOWY_ANGRY) {
            playSound(world, MobSoundEvent.WOLF_GROWL);
        }
        enrage(player, ThreadLocalRandom.current().nextInt(MIN_ANGER_SECONDS, MAX_ANGER_SECONDS + 1));
        mobVisualState().setPose(MobVisualState.Pose.ANGRY, 1f);
        updateAppearance();
    }

    /** Chỉ dùng hình mắt đỏ trong lúc đang truy đuổi người chơi. */
    private void updateAppearance() {
        boolean angryAtPlayer = target() instanceof Player && (!tamed || target() != owner);
        mobVisualState().setAppearance(angryAtPlayer
                ? MobAppearance.WOLF_SNOWY_ANGRY : MobAppearance.WOLF_SNOWY);
    }

    /** Dịch chuyển sói đã thuần hóa tới một ô trống vững chắc gần chủ sở hữu khi bị bỏ lại > 24 block. */
    private void teleportNearOwner(World world) {
        if (world == null || owner == null || !owner.isAlive()) {
            return;
        }
        owner.copyPosition(nearby);
        int baseX = (int) Math.floor(nearby.x);
        int baseY = (int) Math.floor(nearby.y);
        int baseZ = (int) Math.floor(nearby.z);

        for (int radius = 1; radius <= 3; radius++) {
            for (int dx = -radius; dx <= radius; dx++) {
                for (int dz = -radius; dz <= radius; dz++) {
                    if (Math.max(Math.abs(dx), Math.abs(dz)) != radius) {
                        continue;
                    }
                    if (tryTeleportToColumn(world, baseX + dx, baseY, baseZ + dz)) {
                        return;
                    }
                }
            }
        }
        tryTeleportToColumn(world, baseX, baseY, baseZ);
    }

    /** Kiểm tra cột đích có mặt đứng khô ráo an toàn và đặt sói vào tâm ô nếu hợp lệ. */
    private boolean tryTeleportToColumn(World world, int tx, int baseY, int tz) {
        if (!world.isInsideWorld(tx, 0, tz)) {
            return false;
        }
        float feetY = navigator().findStandableY(world, tx, baseY, tz);
        if (!Float.isFinite(feetY)) {
            return false;
        }
        int belowY = (int) Math.floor(feetY - 0.05f);
        int footBlockY = (int) Math.floor(feetY + 0.1f);
        if (world.getBlock(tx, belowY, tz) == Block.WATER.getId()
                || world.getBlock(tx, footBlockY, tz) == Block.WATER.getId()) {
            return false;
        }
        setPosition(tx + 0.5f, feetY, tz + 0.5f);
        stopMotion();
        stopMoving();
        LivingEntity prey = target();
        if (prey != null && distanceSquared(prey) > PREY_PURSUIT_RANGE * PREY_PURSUIT_RANGE) {
            setTarget(null);
        }
        return true;
    }

    /** Các loại thịt giúp hồi máu cho sói đã thuần hóa khi bị thương. */
    private static boolean isWolfFood(Item item) {
        return item == Item.BEEF || item == Item.COOKED_BEEF
                || item == Item.PORKCHOP || item == Item.COOKED_PORKCHOP
                || item == Item.MUTTON || item == Item.COOKED_MUTTON
                || item == Item.CHICKEN || item == Item.COOKED_CHICKEN
                || item == Item.RABBIT || item == Item.COOKED_RABBIT
                || item == Item.ROTTEN_FLESH;
    }

    /** Chép tâm vào bộ đệm và trả bình phương khoảng cách. */
    private float distanceSquared(LivingEntity other) {
        return other.copyCenterPosition(nearby).dst2(x(), y() + height * 0.5f, z());
    }

    /** Goal ưu tiên cao giữ sói đứng yên tại chỗ khi đang ở trạng thái ngồi. */
    private final class SitGoal implements MobGoal {
        @Override
        public int priority() {
            return 1;
        }

        @Override
        public int controls() {
            return MOVE;
        }

        @Override
        public boolean canStart(World world, MobEntity mob) {
            return tamed && sitting;
        }

        @Override
        public boolean shouldContinue(World world, MobEntity mob) {
            return tamed && sitting;
        }

        @Override
        public void start(World world, MobEntity mob) {
            mob.stopMoving();
        }

        @Override
        public void tick(World world, MobEntity mob, float dt) {
            mob.stopMoving();
        }

        @Override
        public void stop(World world, MobEntity mob) {
        }
    }

    /** Goal dẫn sói đã thuần hóa chạy theo chủ khi đứng cách chủ quá 10 block và không chiến đấu. */
    private final class FollowOwnerGoal implements MobGoal {
        private final Vector3 ownerCenter = new Vector3();

        @Override
        public int priority() {
            return 5;
        }

        @Override
        public int controls() {
            return MOVE | LOOK;
        }

        @Override
        public boolean canStart(World world, MobEntity mob) {
            return tamed && !sitting && owner != null && owner.isAlive()
                    && target() == null && distanceSquared(owner) > FOLLOW_START_DISTANCE_SQUARED;
        }

        @Override
        public boolean shouldContinue(World world, MobEntity mob) {
            return tamed && !sitting && owner != null && owner.isAlive()
                    && target() == null && distanceSquared(owner) > FOLLOW_STOP_DISTANCE_SQUARED;
        }

        @Override
        public void start(World world, MobEntity mob) {
        }

        @Override
        public void tick(World world, MobEntity mob, float dt) {
            if (owner == null || !owner.isAlive()) {
                return;
            }
            owner.copyCenterPosition(ownerCenter);
            float feetY = ownerCenter.y - owner.getHeight() * 0.5f;
            mob.lookAt(ownerCenter.x, feetY + owner.getHeight() * 0.8f, ownerCenter.z);
            mob.moveToward(world, ownerCenter.x, feetY, ownerCenter.z, FOLLOW_SPEED_MULTIPLIER);
        }

        @Override
        public void stop(World world, MobEntity mob) {
            mob.stopMoving();
        }
    }
}

package com.voxelgame.world.entity.mob.monster;

import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.animal.Camel;
import com.voxelgame.world.entity.mob.MobAttitude;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.World;
import com.voxelgame.world.physics.Raycast;

import com.badlogic.gdx.math.Vector3;

/** Lạc đà xác sống đáp lệnh hai kỵ sĩ và trở thành thú cưỡi khi họ rời cả hai ghế. */
public final class CamelHusk extends Camel {
    /** Giới hạn phát hiện, hành lang lấy đà và tốc độ khi Husk hạ giáo. */
    private static final float DETECTION_RANGE = 30f;
    private static final float RUN_UP_START = 6.5f;
    private static final float RUN_UP_END = 11f;
    private static final float CHARGE_SPEED = 10.5f;
    private static final float CHARGE_TIMEOUT = 1.4f;
    /** Tầm đâm ngoài mép hộp thân và ngưỡng vận tốc tạo một đòn lao thực sự. */
    private static final float SPEAR_REACH = 2.4f;
    private static final float MIN_CHARGE_SPEED = 4f;
    private static final float THRUST_SECONDS = 0.23f;
    /** Giữ đủ khoảng cách để Parched ngắm bắn bên dưới tầm phát hiện 16 block. */
    private static final float ARCHER_NEAR = 7.5f;
    private static final float ARCHER_FAR = 12f;

    /** Bộ đệm dùng lại cho vị trí người chơi, đoạn tia và hướng lao. */
    private final Vector3 enemy = new Vector3();
    private final Vector3 spearOrigin = new Vector3();
    private final Vector3 spearPath = new Vector3();
    private final Raycast.HitResult obstacle = Raycast.HitResult.miss();
    private float chargeX;
    private float chargeZ;
    private float chargeRemaining;
    private float thrustRemaining;
    private boolean takingDistance;
    private boolean underEnemyControl;

    /** Tạo thú cưỡi hai chỗ để bộ sinh gắn các kỵ sĩ trước khi đưa vào thế giới. */
    public CamelHusk(float x, float y, float z) {
        super(MobType.CAMEL_HUSK, x, y, z);
    }

    /** Giữ ghế trước ưu tiên lãnh đạo, rồi dùng cung thủ còn sống ở ghế sau. */
    public LivingEntity activeDriver() {
        if (getPassenger(0) instanceof Husk husk && husk.hasIronSpear() && husk.isAlive()) {
            return husk;
        }
        if (getPassenger(1) instanceof Parched parched && parched.isAlive()) {
            return parched;
        }
        return null;
    }

    /** Phản ánh ghế hiện tại ngay cả trước tick kế tiếp sau khi một kỵ sĩ rời đi hoặc chết. */
    @Override
    public MobAttitude attitude() {
        return activeDriver() == null ? MobAttitude.PASSIVE : MobAttitude.HOSTILE;
    }

    /** Chặn thao tác cưỡi và cho ăn trong thời gian còn tay lái địch. */
    @Override
    protected boolean canPlayerMount(World world, Player player) {
        return activeDriver() == null && super.canPlayerMount(world, player);
    }

    /** Cập nhật đòn đánh sau va chạm để sát thương tăng theo tốc độ thật, kể cả lúc gặp bậc đá. */
    @Override
    protected void updateLiving(World world, float dt) {
        if (underEnemyControl && activeDriver() == null) {
            clearEnemyControl(world);
        }
        float startX = x();
        float startZ = z();
        super.updateLiving(world, dt);
        if (!isAlive() || chargeRemaining <= 0f || !(activeDriver() instanceof Husk husk)
                || target() == null || !target().isAlive()) {
            return;
        }
        float speed = ((x() - startX) * chargeX + (z() - startZ) * chargeZ) / dt;
        if (speed >= MIN_CHARGE_SPEED && trySpearHit(world, husk, target(), startX, startZ, speed)) {
            thrustRemaining = THRUST_SECONDS;
            resetCharge(true);
        }
    }

    /** Thay phiên điều khiển theo kỵ sĩ đang có mặt và trở lại hành vi lạc đà thường khi trống. */
    @Override
    protected void updateUnridden(World world, float dt) {
        LivingEntity driver = activeDriver();
        if (driver == null) {
            super.updateUnridden(world, dt);
            return;
        }
        if (!underEnemyControl) {
            underEnemyControl = true;
            goals().stopAll(world, this);
        }
        thrustRemaining = Math.max(0f, thrustRemaining - dt);
        Player player = world.getPlayer();
        if (player == null || !player.isAlive() || player.copyPosition(enemy).dst2(x(), y(), z())
                > DETECTION_RANGE * DETECTION_RANGE) {
            stopMoving();
            setTarget(null);
            resetCharge(false);
            return;
        }

        setTarget(player);
        if (getPassenger(1) instanceof Parched parched && parched.isAlive()) {
            parched.setTarget(player);
        }
        if (inWater()) {
            requestFloat();
        }
        float dx = enemy.x - x();
        float dz = enemy.z - z();
        float distance = (float) Math.sqrt(dx * dx + dz * dz);
        if (driver instanceof Husk husk) {
            driveWithSpear(world, husk, player, distance, dx, dz, dt);
        } else {
            resetCharge(false);
            driveWithArcher(world, player, distance, dx, dz);
        }
    }

    /** Mất người lái địch thì bỏ mục tiêu cũ và giải phóng mọi lệnh truy đuổi. */
    private void clearEnemyControl(World world) {
        underEnemyControl = false;
        setTarget(null);
        resetCharge(false);
        thrustRemaining = 0f;
        goals().stopAll(world, this);
        stopMoving();
    }

    /** Lùi để lấy đà khi quá gần, rồi khóa hướng lao và cho phép đối thủ né sang bên. */
    private void driveWithSpear(World world, Husk husk, Player player, float distance, float dx, float dz, float dt) {
        if (chargeRemaining > 0f) {
            chargeRemaining = Math.max(0f, chargeRemaining - dt);
            if (chargeRemaining > 0f && !inWater()
                    && dx * chargeX + dz * chargeZ >= -0.4f) {
                commandCharge();
                return;
            }
            resetCharge(true);
        }

        if (distance < RUN_UP_START) {
            takingDistance = true;
        }
        if (takingDistance && distance < RUN_UP_START + 0.75f) {
            retreat(world, dx, dz, 1.25f);
            return;
        }
        takingDistance = false;
        if (distance <= RUN_UP_END && onGround && !inWater() && spearPathClear(world, player)) {
            chargeX = dx / distance;
            chargeZ = dz / distance;
            chargeRemaining = CHARGE_TIMEOUT;
            husk.playSound(world, MobSoundEvent.SPEAR_CHARGE);
            commandCharge();
        } else {
            moveToward(world, enemy.x, enemy.y, enemy.z, 1.45f);
        }
    }

    /** Xin lệnh lao ngang tốc độ cao, vẫn qua quét vật lý và bước bậc của thú. */
    private void commandCharge() {
        float aimX = x() + chargeX;
        float aimZ = z() + chargeZ;
        faceBody(aimX, aimZ);
        steerDirect(aimX, aimZ, CHARGE_SPEED);
    }

    /** Giữ cự ly bắn và vòng sang bên nếu địa hình chắn giữa cung thủ và người chơi. */
    private void driveWithArcher(World world, Player player, float distance, float dx, float dz) {
        if (distance < ARCHER_NEAR) {
            retreat(world, dx, dz, 1.2f);
        } else if (distance > ARCHER_FAR) {
            moveToward(world, enemy.x, enemy.y, enemy.z, 1.1f);
        } else {
            copySeatPosition(1, spearOrigin);
            spearOrigin.y += getPassenger(1).getHeight() * 0.78f;
            if (!lineClear(world, player)) {
                float side = ((long) (ageSeconds() / 2d) & 1L) == 0L ? 3f / distance : -3f / distance;
                moveToward(world, x() - dz * side, y(), z() + dx * side, 1f);
            } else {
                stopMoving();
                faceBody(enemy.x, enemy.z);
            }
        }
    }

    /** Lùi ra xa điểm chân của mục tiêu với đường tránh địa hình. */
    private void retreat(World world, float dx, float dz, float speedMultiplier) {
        float distance = (float) Math.sqrt(dx * dx + dz * dz);
        if (distance <= CONTACT_EPSILON) {
            moveToward(world, x() + 4f, y(), z(), speedMultiplier);
        } else {
            moveToward(world, x() - dx * (4f / distance), y(), z() - dz * (4f / distance), speedMultiplier);
        }
    }

    /** Quét tầm đâm trên hướng lao và chỉ ghi sát thương khi tia từ lưng thú thông thoáng. */
    private boolean trySpearHit(World world, Husk husk, LivingEntity target, float startX, float startZ, float speed) {
        target.copyPosition(enemy);
        if (enemy.y >= y() + height + 0.65f || enemy.y + target.getHeight() <= y() - 0.25f) {
            return false;
        }
        float dx = enemy.x - startX;
        float dz = enemy.z - startZ;
        float forward = dx * chargeX + dz * chargeZ;
        float side = Math.abs(dx * chargeZ - dz * chargeX);
        float traveled = (x() - startX) * chargeX + (z() - startZ) * chargeZ;
        float width = halfWidth + target.getHalfWidth();
        if (forward < 0f || forward > traveled + SPEAR_REACH + width || side > width
                || !spearPathClear(world, target)) {
            return false;
        }
        float damage = 4.5f + Math.min(4.5f, speed * 0.43f);
        float push = 4f + speed * 0.85f;
        husk.thrustSpear(world, target, damage, chargeX * push, chargeZ * push);
        return true;
    }

    /** Từ gần yên tới thân mục tiêu, không cho giáo đi xuyên vật cản. */
    private boolean spearPathClear(World world, LivingEntity target) {
        spearOrigin.set(x() + chargeX * 0.42f, y() + height * 0.93f, z() + chargeZ * 0.42f);
        return lineClear(world, target);
    }

    /** Kiểm tra đoạn từ tay cầm vũ khí tới thân đối thủ bằng bộ đệm chia sẻ. */
    private boolean lineClear(World world, LivingEntity target) {
        target.copyCenterPosition(spearPath).sub(spearOrigin);
        float distance = spearPath.len();
        return distance <= CONTACT_EPSILON
                || !Raycast.castOccluder(world, spearOrigin, spearPath, distance, obstacle).isHit();
    }

    /** Giữ một nhịp đâm hoàn chỉnh, giảm độ vươn khi tay lái đang lùi để lấy đà. */
    float spearExtension() {
        return thrustRemaining > 0f ? 1f : chargeRemaining > 0f ? 0.55f : 0f;
    }

    /** Kết thúc lượt lao và quyết định có phải lùi ra trước lượt kế tiếp không. */
    private void resetCharge(boolean retreat) {
        chargeRemaining = 0f;
        chargeX = 0f;
        chargeZ = 0f;
        takingDistance = retreat;
    }
}

package com.voxelgame.world.entity.mob.monster;

import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.HostileMob;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.Vector3;

/** Kẻ săn im lặng có mồi nổ, hiệu ứng phồng và vụ nổ ảnh hưởng địa hình. */
public final class Creeper extends HostileMob {
    private static final float WALK_SPEED = 2.5f;
    private static final float DETECT_RANGE_SQUARED = 16f * 16f;
    private static final float PRIME_RANGE_SQUARED = 3f * 3f;
    private static final float CANCEL_RANGE_SQUARED = 7f * 7f;
    private static final double FUSE_SECONDS = 1.5d;
    private static final float BLAST_RADIUS = 3f;
    private static final float BLAST_DAMAGE = 43f;

    /** Tái sử dụng vị trí đích và giữ đúng mục tiêu đã kích hoạt từng lượt mồi. */
    private final Vector3 targetCenter = new Vector3();
    private LivingEntity fuseTarget;
    private double fuseSeconds;

    /** Tạo Creeper dùng các goal nghỉ và bơi chung, với quy trình tấn công riêng. */
    public Creeper(float x, float y, float z) {
        super(MobType.CREEPER, x, y, z, 0f, 0, false);
        setMoveSpeed(WALK_SPEED);
        MobGoals.addDefaults(goals(), type(), false);
    }

    /** Tiếp cận mục tiêu rồi dừng lại cho tới khi mồi cháy hết hoặc mục tiêu thoát. */
    @Override
    protected void updateGoals(World world, float dt) {
        if (fuseTarget != null) {
            if (distanceSquared(fuseTarget) <= CANCEL_RANGE_SQUARED) {
                tickFuse(world, dt);
                return;
            }
            fuseTarget = null;
            fuseSeconds = 0d;
            mobVisualState().setFuseProgress(0f);
        }
        LivingEntity target = target();
        float distance = distanceSquared(target);
        if (distance > DETECT_RANGE_SQUARED) {
            Player player = world.getPlayer();
            distance = distanceSquared(player);
            target = distance <= DETECT_RANGE_SQUARED ? player : null;
            setTarget(target);
        }
        if (target == null) {
            super.updateGoals(world, dt);
            return;
        }
        goals().stopAll(world, this);
        if (distance <= PRIME_RANGE_SQUARED) {
            fuseTarget = target;
            playSound(world, MobSoundEvent.CREEPER_PRIMED);
            tickFuse(world, dt);
        } else {
            lookAt(targetCenter.x, targetCenter.y, targetCenter.z);
            moveToward(world, targetCenter.x, targetCenter.y - target.getHeight() * 0.5f, targetCenter.z, 1f);
        }
    }

    /** Giữ tư thế tại chỗ, cập nhật tiến độ vẽ rồi thực hiện và rời thế giới ngay khi nổ. */
    private void tickFuse(World world, float dt) {
        stopMoving();
        lookAt(targetCenter.x, targetCenter.y, targetCenter.z);
        fuseSeconds += dt;
        mobVisualState().setFuseProgress((float) (fuseSeconds / FUSE_SECONDS));
        if (fuseSeconds >= FUSE_SECONDS) {
            playSound(world, MobSoundEvent.EXPLODE);
            world.explode(this, x(), y() + getHeight() * 0.5f, z(), BLAST_RADIUS, BLAST_DAMAGE);
            discard();
        }
    }

    /** Dùng chung điểm tâm cho khoảng cách kích nổ và hướng quan sát. */
    private float distanceSquared(LivingEntity candidate) {
        if (candidate == null || !candidate.isAlive()) {
            return Float.POSITIVE_INFINITY;
        }
        candidate.copyCenterPosition(targetCenter);
        return targetCenter.dst2(x(), y() + getHeight() * 0.5f, z());
    }

    /** Creeper chỉ bỏ tiếng chờ, còn tiếng bước chân phụ thuộc khối dưới chân. */
    @Override
    public void playSound(World world, MobSoundEvent event) {
        if (event != MobSoundEvent.AMBIENT) {
            super.playSound(world, event);
        }
    }
}

package com.voxelgame.world.entity.mob.monster;

import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.NeutralMob;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;
import com.voxelgame.world.physics.Raycast;

import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Vector3;
import java.util.concurrent.ThreadLocalRandom;

/** Quái trung lập phản ứng với ngắm vào mắt, nước và đạn đạo. */
public final class Enderman extends NeutralMob {
    /** Tầm ngắm mắt, kích thước vùng mắt và bán kính tối đa tìm điểm dịch chuyển. */
    private static final float SIGHT_RANGE = 64f;
    private static final float EYE_RADIUS = 0.28f;
    private static final int TELEPORT_RADIUS = 32;
    private static final int TELEPORT_ATTEMPTS = 24;
    private static final int NEAR_FALLBACK_RADIUS = 4;
    /** Chu kỳ 2 tick (0,10s) và xác suất nhặt (1/20) / đặt (1/2000) block chuẩn Minecraft. */
    public static final float BLOCK_CHECK_INTERVAL = 0.10f;
    public static final int PICKUP_CHANCE_DIVISOR = 20;
    public static final int PLACE_CHANCE_DIVISOR = 2000;

    /** Bộ đệm tia mắt và trạng thái đích dịch chuyển được tái sử dụng. */
    private final Vector3 eye = new Vector3();
    private final Vector3 direction = new Vector3();
    private final Vector3 placement = new Vector3();
    private final Vector3 wetFallback = new Vector3();
    private final Raycast.HitResult obstruction = Raycast.HitResult.miss();
    private float gazeDelay;
    private float wetDelay;
    private float combatTeleportDelay = 2.8f;
    private float blockDelay = BLOCK_CHECK_INTERVAL;
    private Block heldBlock = Block.AIR;

    /** Dùng goal chung và đòn cận chiến 7 HP khi đang giận. */
    public Enderman(float x, float y, float z) {
        super(MobType.ENDERMAN, x, y, z, 0f, 0, false);
        setMoveSpeed(3f);
        MobGoals.addDefaults(goals(), type(), false);
        goals().add(new MobGoals.MeleeAttackGoal(4, 1f, 7f, 0.85f, 1f, SIGHT_RANGE));
    }

    /** Kiểm tra kích thích tại đầu lượt trước khi bộ goal chọn đường đi. */
    @Override
    protected void updateGoals(World world, float dt) {
        wetDelay -= dt;
        if (wetDelay <= 0f && (inWater() || world.isRainingAt(x(), y() + getHeight(), z()))) {
            wetDelay = 1f;
            damage(world, 1f, DamageSource.WATER, null, 0f, 0f);
            if (!isAlive()) {
                return;
            }
            teleport(world, NEAR_FALLBACK_RADIUS);
        }

        gazeDelay -= dt;
        Player player = world.getPlayer();
        if (target() == null && gazeDelay <= 0f) {
            gazeDelay = 0.10f;
            if (player != null && player.isAlive() && seesEyes(world, player)) {
                enrage(player, 25f);
                playSound(world, MobSoundEvent.ENDERMAN_STARE);
            }
        }

        LivingEntity victim = target();
        if (victim != null) {
            mobVisualState().setPose(MobVisualState.Pose.ANGRY, 1f);
            setMoveSpeed(4.1f);
            combatTeleportDelay -= dt;
            if (combatTeleportDelay <= 0f) {
                ThreadLocalRandom random = ThreadLocalRandom.current();
                combatTeleportDelay = random.nextFloat(2.5f, 4.5f);
                victim.copyPosition(placement);
                if (placement.dst2(x(), y(), z()) > 36f && random.nextInt(4) == 0) {
                    teleport(world, NEAR_FALLBACK_RADIUS);
                }
            }
        } else {
            mobVisualState().setPose(MobVisualState.Pose.IDLE, 0f);
            setMoveSpeed(3f);
            blockDelay -= dt;
            if (blockDelay <= 0.0001f) {
                blockDelay = BLOCK_CHECK_INTERVAL;
                moveNaturalBlock(world);
            }
        }
        super.updateGoals(world, dt);
    }

    /** So tia thật từ mắt người chơi với vùng mắt nhỏ, rồi thử vật cản voxel. */
    private boolean seesEyes(World world, Player player) {
        if (!player.copyAim(eye, direction)) {
            return false;
        }
        float dx = x() - eye.x;
        float dy = y() + getHeight() * 0.92f - eye.y;
        float dz = z() - eye.z;
        float distance = dx * dx + dy * dy + dz * dz;
        float along = direction.dot(dx, dy, dz);
        return distance <= SIGHT_RANGE * SIGHT_RANGE && along > 0f
                && distance - along * along <= EYE_RADIUS * EYE_RADIUS
                && !Raycast.castOccluder(world, eye, direction, along, obstruction).isHit();
    }

    /** Phát tiếng hét khi lần đầu chuyển từ trung lập sang giận vì bị tấn công. */
    @Override
    public boolean damage(World world, float amount, DamageSource source, Entity attacker, float knockbackX,
                          float knockbackZ) {
        boolean newAttacker = attacker instanceof LivingEntity && target() != attacker;
        boolean applied = super.damage(world, amount, source, attacker, knockbackX, knockbackZ);
        if (applied && isAlive() && newAttacker && target() == attacker) {
            playSound(world, MobSoundEvent.ENDERMAN_SCREAM);
        }
        return applied;
    }

    /** Tên không gây sát thương, kể cả khi địa hình quanh mob không có chỗ đáp hợp lệ. */
    @Override
    public boolean dodgeProjectile(World world, Entity owner) {
        teleport(world, TELEPORT_RADIUS);
        return true;
    }

    /** Ưu tiên vị trí khô có mái; khi cả vùng đang mưa vẫn chọn được nền chắc để thoát nước. */
    private boolean teleport(World world, int fallbackRadius) {
        int bx = MathUtils.floor(x());
        int bz = MathUtils.floor(z());
        ThreadLocalRandom random = ThreadLocalRandom.current();
        wetFallback.y = Float.NaN;
        for (int i = 0; i < TELEPORT_ATTEMPTS; i++) {
            int tx = bx + random.nextInt(-TELEPORT_RADIUS, TELEPORT_RADIUS + 1);
            int tz = bz + random.nextInt(-TELEPORT_RADIUS, TELEPORT_RADIUS + 1);
            if (findLanding(world, tx, tz)) {
                finishTeleport(world, placement);
                return true;
            }
        }
        if (Float.isNaN(wetFallback.y) && findFallbackLanding(world, bx, bz, fallbackRadius)) {
            finishTeleport(world, placement);
            return true;
        }
        if (!Float.isNaN(wetFallback.y)) {
            finishTeleport(world, wetFallback);
            return true;
        }
        return false;
    }

    /** Duyệt các vành từ gần tới xa khi lần né tên cần tìm được cả điểm đáp lẻ. */
    private boolean findFallbackLanding(World world, int bx, int bz, int radius) {
        for (int ring = 1; ring <= radius; ring++) {
            for (int delta = -ring; delta <= ring; delta++) {
                if (findLanding(world, bx + delta, bz - ring) || findLanding(world, bx + delta, bz + ring)
                        || (Math.abs(delta) < ring && (findLanding(world, bx - ring, bz + delta)
                        || findLanding(world, bx + ring, bz + delta)))) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Tìm điểm đứng khô trong bán kính 3D và lưu một phương án dưới mưa để dự phòng. */
    private boolean findLanding(World world, int bx, int bz) {
        if (!world.isInsideWorld(bx, 0, bz)) {
            return false;
        }
        float tx = bx + 0.5f;
        float tz = bz + 0.5f;
        float dx = tx - x();
        float dz = tz - z();
        float horizontal = dx * dx + dz * dz;
        if (horizontal < 1f || horizontal > TELEPORT_RADIUS * TELEPORT_RADIUS) {
            return false;
        }
        float ty = navigator().findStandableY(world, bx, MathUtils.floor(y()), bz);
        if (!Float.isFinite(ty)) {
            int surface = MathUtils.floor(world.getPrecipitationSurface(bx, bz));
            ty = navigator().findStandableY(world, bx, surface, bz);
        }
        float dy = ty - y();
        if (!Float.isFinite(ty) || horizontal + dy * dy > TELEPORT_RADIUS * TELEPORT_RADIUS) {
            return false;
        }
        for (int by = MathUtils.floor(ty); by <= MathUtils.floor(ty + getHeight()); by++) {
            if (Block.fromId(world.getBlock(bx, by, bz)).isLiquid()) {
                return false;
            }
        }
        if (world.hasLivingOverlap(tx, ty, tz, getHalfWidth(), getHeight(), this)) {
            return false;
        }
        if (world.isRainingAt(tx, ty + getHeight(), tz)) {
            if (Float.isNaN(wetFallback.y)) {
                wetFallback.set(tx, ty, tz);
            }
            return false;
        }
        placement.set(tx, ty, tz);
        return true;
    }

    /** Đồng bộ vận tốc, quãng rơi và âm thanh sau khi chọn điểm đáp. */
    private void finishTeleport(World world, Vector3 landing) {
        setPosition(landing.x, landing.y, landing.z);
        velocity.setZero();
        stopMoving();
        playSound(world, MobSoundEvent.ENDERMAN_TELEPORT);
    }

    /** Nhặt (1/20) hoặc đặt (1/2000) đúng 1 ô ngẫu nhiên quanh người mỗi 2 tick chuẩn Minecraft. */
    private void moveNaturalBlock(World world) {
        ThreadLocalRandom random = ThreadLocalRandom.current();
        if (heldBlock == Block.AIR) {
            if (random.nextInt(PICKUP_CHANCE_DIVISOR) != 0) {
                return;
            }
        } else if (random.nextInt(PLACE_CHANCE_DIVISOR) != 0) {
            return;
        }
        int bx = MathUtils.floor(x());
        int by = MathUtils.floor(y());
        int bz = MathUtils.floor(z());
        int tx = bx + random.nextInt(-2, 3);
        int ty = by + random.nextInt(-1, 2);
        int tz = bz + random.nextInt(-2, 3);
        if ((tx == bx && tz == bz) || !world.isInsideWorld(tx, ty, tz)) {
            return;
        }
        Block block = Block.fromId(world.getBlock(tx, ty, tz));
        if (heldBlock == Block.AIR) {
            if (canCarry(block)) {
                heldBlock = block;
                mobVisualState().setHeldBlock(heldBlock);
                world.setBlock(tx, ty, tz, Block.AIR.getId());
            }
        } else if (block == Block.AIR && world.isSolidBlock(tx, ty - 1, tz)
                && !intersectsBlock(tx, ty, tz) && world.tryPlaceBlock(tx, ty, tz, heldBlock, world.getPlayer())) {
            heldBlock = Block.AIR;
            mobVisualState().setHeldBlock(null);
        }
    }

    /** Trả khối Enderman đang cầm trên tay (Block.AIR nếu tay trống). */
    public Block heldBlock() {
        return heldBlock;
    }

    /** Lấy và xóa khối đang cầm để rơi ra ngoài thế giới khi Enderman bị tiêu diệt. */
    public Block takeHeldBlockForLoot() {
        Block carried = heldBlock;
        heldBlock = Block.AIR;
        mobVisualState().setHeldBlock(null);
        return carried;
    }

    /** Chỉ cho phép nhặt các khối tự nhiên được quy định cho loài. */
    private static boolean canCarry(Block block) {
        return block == Block.DIRT || block == Block.GRASS || block == Block.SAND || block == Block.GRAVEL
                || block == Block.DANDELION || block == Block.POPPY || block == Block.CORNFLOWER
                || block == Block.OXEYE_DAISY;
    }
}

package com.voxelgame.world.entity.mob.monster;

import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.effect.StatusEffectType;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Vector3;
import java.util.concurrent.ThreadLocalRandom;

/** Zombie sa mạc áp Hunger khi đánh và đổi thành Zombie thường sau khi chìm đầu. */
public final class Husk extends Zombie {
    /** Tỷ lệ hiển thị người lớn của Husk (cao hơn Zombie thường 6%). */
    private static final float ADULT_VISUAL_SCALE = 1.06f;
    /** Chìm đầu 30 giây liên tục trước pha chuyển hóa dài 15 giây. */
    private static final double SUBMERGE_SECONDS = 30d;
    private static final double CONVERSION_SECONDS = 15d;
    private static final float HUNGER_MIN_SECONDS = 7f;
    private static final float HUNGER_MAX_SECONDS = 14f;

    /** Trang bị của kỵ sĩ được giữ nguyên nếu nó rời ghế. */
    private final boolean ironSpear;
    private final Vector3 spearTarget;

    private double submergedSeconds;
    private double convertingSeconds;
    private boolean converting;
    private boolean converted;

    /** Tạo Husk tự nhiên với 5% cơ hội là cá thể non (theo Zombie.rollsBaby). */
    public Husk(float x, float y, float z) {
        this(x, y, z, false, rollsBaby());
    }

    /** Trang bị giáo cho Husk ghế lái của bộ kỵ sĩ sa mạc (luôn là người lớn). */
    public Husk(float x, float y, float z, boolean ironSpear) {
        this(x, y, z, ironSpear, false);
    }

    /** Khởi tạo Husk với trang bị giáo và trạng thái non/trưởng thành tường minh. */
    public Husk(float x, float y, float z, boolean ironSpear, boolean baby) {
        super(MobType.HUSK, x, y, z, baby);
        this.ironSpear = ironSpear;
        spearTarget = ironSpear ? new Vector3() : null;
        if (ironSpear) {
            mobVisualState().setPose(MobVisualState.Pose.THRUST, 0f);
        }
    }

    /** Giữ tỷ lệ hiển thị 1,06× cho Husk trưởng thành (và 0,6 × 1,06 cho Husk con). */
    @Override
    protected float adultVisualScale() {
        return ADULT_VISUAL_SCALE;
    }

    /** Nhận diện Husk có thể chỉ huy cú lao bằng giáo. */
    public boolean hasIronSpear() {
        return ironSpear;
    }

    /** Giữ giáo trên tay và ngắm theo đích mà thú cưỡi đang tiếp cận. */
    @Override
    protected void updateMounted(World world, float dt) {
        if (ironSpear && getMount() instanceof CamelHusk camel && camel.activeDriver() == this) {
            LivingEntity target = camel.target();
            if (target != null) {
                target.copyCenterPosition(spearTarget);
                lookAt(spearTarget.x, spearTarget.y, spearTarget.z);
                faceBody(spearTarget.x, spearTarget.z);
            }
            mobVisualState().setPose(MobVisualState.Pose.THRUST, camel.spearExtension());
        }
    }

    /** Thực hiện đòn giáo từ ghế lái, giữ hiệu ứng Hunger vốn có của Husk. */
    boolean thrustSpear(World world, LivingEntity target, float damage, float knockbackX, float knockbackZ) {
        return ironSpear && strikeMelee(world, target, damage, knockbackX, knockbackZ);
    }

    /** Chỉ áp Hunger I khi sát thương cận chiến được mục tiêu chấp nhận. */
    @Override
    public boolean strikeMelee(World world, LivingEntity target, float baseDamage, float knockbackX, float knockbackZ) {
        if (!super.strikeMelee(world, target, baseDamage, knockbackX, knockbackZ)) {
            return false;
        }
        target.applyEffect(StatusEffectType.HUNGER, 0,
                ThreadLocalRandom.current().nextFloat(HUNGER_MIN_SECONDS, HUNGER_MAX_SECONDS));
        return true;
    }

    /** Đếm thời gian theo bước mô phỏng, cập nhật hiệu ứng rung và thay cá thể đúng một lần. */
    @Override
    protected void updateLiving(World world, float dt) {
        if (ironSpear && !(getMount() instanceof CamelHusk)) {
            mobVisualState().setPose(MobVisualState.Pose.THRUST, 0f);
        }
        super.updateLiving(world, dt);
        if (converted) {
            return;
        }
        if (!converting) {
            submergedSeconds = headUnderwater(world) ? submergedSeconds + dt : 0d;
            if (submergedSeconds < SUBMERGE_SECONDS) {
                return;
            }
            converting = true;
            // Dồn phần dư của nhịp vượt ngưỡng vào pha rung để giữ đủ 45 giây tổng cộng.
            convertingSeconds = submergedSeconds - SUBMERGE_SECONDS;
        } else {
            convertingSeconds += dt;
        }
        if (convertingSeconds < CONVERSION_SECONDS) {
            shake();
            return;
        }
        converted = true;
        playSound(world, MobSoundEvent.HUSK_CONVERT);
        world.replaceLivingEntity(this, new Zombie(x(), y(), z(), isBaby()));
    }

    /** Điểm ở phần mặt phải thấp hơn bề mặt chất lỏng trong chính ô chứa đầu. */
    private boolean headUnderwater(World world) {
        float headY = y() + getHeight() * 0.9f;
        int blockX = MathUtils.floor(x());
        int blockY = MathUtils.floor(headY);
        int blockZ = MathUtils.floor(z());
        return world.getBlock(blockX, blockY, blockZ) == Block.WATER.getId()
                && headY < blockY + Block.WATER.getTopHeight(world, blockX, blockY, blockZ);
    }

    /** Cộng dao động vẽ mỗi lượt mà không thay đổi hướng di chuyển hoặc cấp phát đối tượng. */
    private void shake() {
        MobVisualState visual = mobVisualState();
        float shake = MathUtils.sin((float) (convertingSeconds * 33d)) * 8f;
        visual.setAnimation(visual.bodyYaw() + shake * 0.4f, visual.headYaw() + shake, visual.headPitch(),
                visual.limbSwing(), visual.limbSwingAmount(), visual.ageInTicks());
    }
}

