package com.voxelgame.world.entity.mob.monster;

import com.voxelgame.client.audio.MobSoundEvent;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.RangedMob;
import com.voxelgame.world.entity.projectile.ArrowEntity;
import com.voxelgame.world.entity.projectile.ArrowType;
import com.voxelgame.world.level.World;

import java.util.concurrent.ThreadLocalRandom;

/** Cung thủ theo sát mục tiêu, đi ngang khi ngắm và lùi khi bị áp sát. */
public class Skeleton extends RangedMob {
    /** Tầm phát hiện và bắn, thời gian giương cung, và tốc độ ngang của mũi tên. */
    private static final float RANGE = 16f;
    private static final float DRAW_SECONDS = 1f;
    private static final float ARROW_SPEED = 19f;
    /** Khoảng cách lùi và ngưỡng rút ngắn nhịp nạp tên khi đánh gần. */
    private static final float RETREAT_DISTANCE_SQUARED = 4f * 4f;
    private static final float FAST_SHOT_DISTANCE_SQUARED = 6f * 6f;

    private final ArrowType arrowType;
    private final float minimumDamage;
    private final float shotInterval;
    private float strafeSide = ThreadLocalRandom.current().nextBoolean() ? 1f : -1f;
    private double reverseStrafeAt = 1.35;

    /** Dựng Skeleton thường với tên gây từ ba đến bốn HP, nhịp bắn hai giây. */
    public Skeleton(float x, float y, float z) {
        this(MobType.SKELETON, x, y, z, ArrowType.NORMAL, 3f, 2f);
    }

    /** Cho biến thể thay mũi tên và nhịp bắn, dùng lại toàn bộ hành vi di chuyển và ngắm. */
    protected Skeleton(MobType type, float x, float y, float z, ArrowType arrowType, float minimumDamage,
                       float shotInterval) {
        super(type, x, y, z, RANGE, RANGE, DRAW_SECONDS, ARROW_SPEED, ArrowEntity.GRAVITY);
        this.arrowType = arrowType;
        this.minimumDamage = minimumDamage;
        this.shotInterval = shotInterval;
    }

    /** Lùi thẳng khi đối thủ áp sát, còn ở khoảng bắn thì đổi phía đi ngang theo nhịp. */
    @Override
    protected void moveWhileAiming(World world, float targetX, float targetZ) {
        float dx = targetX - x();
        float dz = targetZ - z();
        float horizontalSquared = dx * dx + dz * dz;
        if (horizontalSquared < 0.0001f) {
            moveToward(world, x() + strafeSide * 2f, y(), z(), 0.9f);
            return;
        }
        float scale = 2f / (float) Math.sqrt(horizontalSquared);
        if (horizontalSquared < RETREAT_DISTANCE_SQUARED) {
            moveToward(world, x() - dx * scale, y(), z() - dz * scale, 0.9f);
            return;
        }
        if (ageSeconds() >= reverseStrafeAt) {
            strafeSide = -strafeSide;
            reverseStrafeAt = ageSeconds() + 1f + ThreadLocalRandom.current().nextFloat() * 0.65f;
        }
        float step = scale * strafeSide;
        moveToward(world, x() - dz * step, y(), z() + dx * step, 0.75f);
    }

    /** Cung theo hướng đầu trong toàn bộ thời gian đang lên dây. */
    @Override
    protected void applyAimPose(float progress) {
        mobVisualState().setPose(MobVisualState.Pose.AIM_BOW, progress);
    }

    /** Ở gần, giảm khoảng nghỉ nhưng giữ khác biệt tốc độ giữa các loại cung thủ. */
    @Override
    protected float intervalSeconds(float distanceSquared) {
        return distanceSquared < FAST_SHOT_DISTANCE_SQUARED ? shotInterval * 0.8f : shotInterval;
    }

    /** Phóng mũi tên của loài, chọn sát thương trong dải một HP và phát tiếng nhả dây. */
    @Override
    protected void fire(World world, LivingEntity target, float distance,
              float x, float y, float z, float vx, float vy, float vz) {
        float damage = minimumDamage + ThreadLocalRandom.current().nextFloat();
        world.addEntity(new ArrowEntity(this, x, y, z, vx, vy, vz, arrowType, damage));
        playSound(world, MobSoundEvent.BOW_SHOOT);
    }
}

package com.voxelgame.world.entity.mob.monster;

import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.ai.MobGoals;
import com.voxelgame.world.entity.mob.MobAttitude;
import com.voxelgame.world.entity.mob.MobSpawner;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.NeutralMob;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;
import com.voxelgame.world.physics.Raycast;

import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Vector3;

/** Nhện đổi thái độ theo ánh sáng, vồ từ xa và bám vách để truy đuổi. */
public final class Spider extends NeutralMob {
    private static final float WALK_SPEED = 3f;
    private static final float TARGET_RANGE = 16f;
    private static final float LEAP_MIN_DISTANCE_SQUARED = 2f * 2f;
    private static final float LEAP_MAX_DISTANCE_SQUARED = 4f * 4f;
    private static final float LEAP_HORIZONTAL_SPEED = 5.1f;
    private static final float LEAP_VERTICAL_SPEED = 6.7f;
    private static final float LEAP_RECOVERY_SECONDS = 1.4f;

    /** Các bộ đệm tia và vị trí đích tồn tại cùng cá thể, dùng lại cho mỗi lần cập nhật. */
    private final Vector3 targetCenter = new Vector3();
    private final Vector3 wallRayOrigin = new Vector3();
    private final Vector3 wallRayDirection = new Vector3();
    private final Raycast.HitResult wallHit = Raycast.HitResult.miss();
    private boolean dark;
    private double nextLeap;

    /** Dựng nhện với một ghế cho Spider Jockey và bộ cận chiến theo chỉ số loài. */
    public Spider(float x, float y, float z) {
        super(MobType.SPIDER, x, y, z, 0f, 1, false);
        setMoveSpeed(WALK_SPEED);
        MobGoals.addDefaults(goals(), type(), false);
        goals().add(new MobGoals.MeleeAttackGoal(4, 1f, 2f, 0.85f, 1f, TARGET_RANGE));
    }

    /** Thái độ nền là trung lập ngoài trời và thù địch dưới mái hoặc khi trời tối. */
    @Override
    public MobAttitude attitude() {
        return dark ? MobAttitude.HOSTILE : MobAttitude.NEUTRAL;
    }

    /** Chọn mục tiêu theo ánh sáng rồi bổ sung vồ và leo vào đường di chuyển chung. */
    @Override
    protected void updateGoals(World world, float dt) {
        dark = MobSpawner.isNightDark(world.worldTime())
                || world.hasWeatherRoof(MathUtils.floor(x()), y() + getHeight(), MathUtils.floor(z()));
        LivingEntity current = target();
        if (!dark && angerTimer() <= 0f) {
            current = null;
        } else if (!inRange(current) && dark) {
            LivingEntity player = world.getPlayer();
            current = inRange(player) ? player : null;
        }
        setTarget(current);
        super.updateGoals(world, dt);
        if (!inWater() && inRange(current)) {
            attackMovement(world);
        }
    }

    /** Khi vách ở sát hướng đuổi thì đưa nhện tới tiếp xúc, nếu thông thì thử vồ. */
    private void attackMovement(World world) {
        float dx = targetCenter.x - x();
        float dy = targetCenter.y - (y() + getHeight() * 0.5f);
        float dz = targetCenter.z - z();
        float horizontal = dx * dx + dz * dz;
        if (!(horizontal > 0.001f)) {
            return;
        }
        float distanceSquared = horizontal + dy * dy;
        if (hasWallAhead(world, dx, dz)) {
            steerTowardWall(targetCenter.x, targetCenter.z);
        } else if (onGround && ageSeconds() >= nextLeap && distanceSquared >= LEAP_MIN_DISTANCE_SQUARED
                && distanceSquared <= LEAP_MAX_DISTANCE_SQUARED) {
            float speed = LEAP_HORIZONTAL_SPEED / (float) Math.sqrt(horizontal);
            nextLeap = ageSeconds() + LEAP_RECOVERY_SECONDS;
            queueLeap(dx * speed, LEAP_VERTICAL_SPEED, dz * speed);
        }
    }

    /** Dò ngay trước mép thân để xác minh đường đi thực sự chạm một vách rắn. */
    private boolean hasWallAhead(World world, float dx, float dz) {
        wallRayOrigin.set(x(), y() + getHeight() * 0.55f, z());
        wallRayDirection.set(dx, 0f, dz);
        return Raycast.castOccluder(world, wallRayOrigin, wallRayDirection, getHalfWidth() + 0.55f, wallHit).isHit();
    }

    /** Hộp quét đã xác nhận nhện ép vào mặt bên, chỉ leo mặt rắn an toàn. */
    @Override
    protected boolean climbWall(World world, Block wall) {
        return !inWater() && wall.isSolid() && wall != Block.CACTUS;
    }

    /** Tính khoảng cách tâm ba chiều và ghi đích nhìn vào bộ đệm khi đối thủ còn sống. */
    private boolean inRange(LivingEntity candidate) {
        if (candidate == null || !candidate.isAlive()) {
            return false;
        }
        candidate.copyCenterPosition(targetCenter);
        return targetCenter.dst2(x(), y() + getHeight() * 0.5f, z()) <= TARGET_RANGE * TARGET_RANGE;
    }
}

