    /** Cập nhật pha View Bobbing (chỉ khi {@code onGround && !isFlying}) và pha bước chân góc nhìn 3. */
    private void updateViewBobbingAndLimbSwing(float dt, float movedX, float movedZ) {
        float horizDist = (float) Math.sqrt(movedX * movedX + movedZ * movedZ);
        float horizSpeed = dt > 0.0001f ? horizDist / dt : 0.0f;
        float targetStrength;
        if (onGround && !isFlying && horizDist > 0.0001f) {
            bobPhase += horizDist * 2.4f;
            targetStrength = Math.min(1.25f, horizSpeed / MOVE_SPEED);
        } else {
            targetStrength = 0.0f;
        }
        float lerp = Math.min(1.0f, dt * 10.0f);
        bobStrength += (targetStrength - bobStrength) * lerp;

        if (horizDist > 0.0001f) {
            limbSwing += horizDist * 2.4f;
        }
        float targetLimbAmount = Math.min(1.0f, horizSpeed / MOVE_SPEED);
        limbSwingAmount += (targetLimbAmount - limbSwingAmount) * lerp;
    }

    /** Đặt lại toàn bộ trạng thái dao động tay chân khi chết hoặc dịch chuyển sang biome mới. */
    private void resetViewmodelMotion() {
        bobPhase = 0.0f;
        bobStrength = 0.0f;
        limbSwing = 0.0f;
        limbSwingAmount = 0.0f;
        swinging = false;
        swingElapsed = 0.0f;
    }

    /**
     * Tính tọa độ đặt camera ở góc nhìn thứ 3 dựa trên {@link Camera} gắn sẵn của người chơi,
     * có bắn tia {@link Raycast#castOccluder} để không xuyên vào khối rắn.
     */
    public Vector3 computeThirdPersonCameraPos(World world, Vector3 out) {
        return computeThirdPersonCameraPos(world, this.camera, out);
    }

    /**
     * Tính tọa độ đặt camera ở góc nhìn thứ 3 dựa trên hướng nhìn của {@code cam},
     * có bắn tia {@link Raycast#castOccluder} để rút ngắn khoảng cách trước tường rắn.
     */
    public Vector3 computeThirdPersonCameraPos(World world, Camera cam, Vector3 out) {
        if (cam != null) {
            cam.copyFront(tmpCamDir);
        } else {
            tmpCamDir.set(0.0f, 0.0f, -1.0f);
        }
        return computeThirdPersonCameraPos(
                world,
                position.x,
                position.y + currentEyeHeight,
                position.z,
                tmpCamDir.x,
                tmpCamDir.y,
                tmpCamDir.z,
                cameraMode,
                THIRD_PERSON_DISTANCE,
                out
        );
    }

    /**
     * Tính tọa độ camera góc nhìn thứ 3 từ tâm mắt và hướng nhìn chỉ định,
     * rút ngắn khoảng cách khi có khối va chạm rắn nằm trên đường nối.
     *
     * @param world       thế giới voxel để kiểm tra vật cản (có thể {@code null})
     * @param eyeX        tọa độ X tâm mắt người chơi
     * @param eyeY        tọa độ Y tâm mắt người chơi
     * @param eyeZ        tọa độ Z tâm mắt người chơi
     * @param dirX        thành phần X hướng nhìn phía trước
     * @param dirY        thành phần Y hướng nhìn phía trước
     * @param dirZ        thành phần Z hướng nhìn phía trước
     * @param mode        chế độ camera mục tiêu
     * @param maxDistance khoảng cách tối đa (mặc định 4.0 block)
     * @param out         vector nhận kết quả (tái sử dụng zero-GC)
     * @return {@code out} chứa vị trí đặt camera an toàn
     */
    public Vector3 computeThirdPersonCameraPos(World world,
                                               float eyeX, float eyeY, float eyeZ,
                                               float dirX, float dirY, float dirZ,
                                               CameraMode mode, float maxDistance, Vector3 out) {
        out.set(eyeX, eyeY, eyeZ);
        if (mode == null || mode == CameraMode.FIRST_PERSON || !(maxDistance > 0.0f)) {
            return out;
        }
        float sign = mode == CameraMode.THIRD_BACK ? -1.0f : 1.0f;
        tmpCamDir.set(dirX * sign, dirY * sign, dirZ * sign);
        float lenSq = tmpCamDir.len2();
        if (lenSq < 1e-8f || !Float.isFinite(lenSq)) {
            return out;
        }
        tmpCamDir.scl(1.0f / (float) Math.sqrt(lenSq));

        float distance = maxDistance;
        if (world != null) {
            tmpCamOrigin.set(eyeX, eyeY, eyeZ);
            Raycast.castOccluder(world, tmpCamOrigin, tmpCamDir, maxDistance + THIRD_PERSON_CLIP_PADDING, tmpCamHit);
            if (tmpCamHit.isHit()) {
                distance = Math.max(0.0f, Math.min(maxDistance, tmpCamHit.getDistance() - THIRD_PERSON_CLIP_PADDING));
            }
        }
        out.set(
                eyeX + tmpCamDir.x * distance,
                eyeY + tmpCamDir.y * distance,
                eyeZ + tmpCamDir.z * distance
        );
        return out;
    }

    /**
     * Áp dụng tạm thời vị trí camera cho lượt kết xuất (View Bobbing ở góc nhìn 1 hoặc vị trí lùi/tiến ở góc nhìn 3)
     * mà không làm thay đổi {@link Entity#position} hay kết quả Raycast sau khi khôi phục cuối lượt vẽ.
     *
     * @param world        thế giới để tránh xuyên tường ở góc nhìn thứ 3
     * @param cam          camera cần tạm đặt vị trí kết xuất
     * @param outRenderPos bộ đệm nhận tọa độ kết xuất đã áp dụng
     */
    public void applyRenderCameraPosition(World world, Camera cam, Vector3 outRenderPos) {
        if (cam == null) {
            outRenderPos.set(position.x, position.y + currentEyeHeight, position.z);
            return;
        }
        if (cameraMode == CameraMode.FIRST_PERSON) {
            outRenderPos.set(position.x, position.y + currentEyeHeight, position.z);
            if (bobStrength > 0.0001f) {
                cam.copyFront(tmpCamDir);
                tmpCamRight.set(tmpCamDir).crs(Vector3.Y);
                if (tmpCamRight.len2() > 1e-6f) {
                    tmpCamRight.nor();
                    tmpCamUp.set(tmpCamRight).crs(tmpCamDir).nor();
                } else {
                    tmpCamRight.set(1.0f, 0.0f, 0.0f);
                    tmpCamUp.set(0.0f, 1.0f, 0.0f);
                }
                float swayX = (float) Math.sin(bobPhase) * BOB_CAMERA_SWAY_X * bobStrength;
                float bounceY = -(float) Math.abs(Math.cos(bobPhase)) * BOB_CAMERA_BOUNCE_Y * bobStrength;
                outRenderPos.add(
                        tmpCamRight.x * swayX + tmpCamUp.x * bounceY,
                        tmpCamRight.y * swayX + tmpCamUp.y * bounceY,
                        tmpCamRight.z * swayX + tmpCamUp.z * bounceY
                );
            }
            cam.setPosition(outRenderPos.x, outRenderPos.y, outRenderPos.z);
            return;
        }
        computeThirdPersonCameraPos(world, cam, outRenderPos);
        cam.setPosition(outRenderPos.x, outRenderPos.y, outRenderPos.z);
    }

    /**
     * Tính ma trận nhìn cho lượt kết xuất hiện tại: dùng {@code lookAt} ngược từ vị trí trước mặt
     * về tầm mắt người chơi khi ở {@link CameraMode#THIRD_FRONT} mà không làm trôi {@code yaw}/{@code pitch}.
     *
     * @param cam       camera hiện tại (đã đặt tại vị trí kết xuất)
     * @param eyeTarget tọa độ tầm mắt người chơi để camera nhìn về ở {@code THIRD_FRONT}
     * @param outView   ma trận đích tái sử dụng (zero-GC)
     * @return {@code outView} đã cập nhật
     */
    public Matrix4 computeRenderViewMatrix(Camera cam, Vector3 eyeTarget, Matrix4 outView) {
        if (cam == null) {
            return outView.idt();
        }
        if (cameraMode == CameraMode.THIRD_FRONT) {
            cam.copyPosition(tmpCamOrigin);
            return outView.setToLookAt(tmpCamOrigin, eyeTarget, Vector3.Y);
        }
        return outView.set(cam.getViewMatrix());
    }
    // === END HOOK: TRACK A - METHODS ===

    // === HOOK: TRACK C - METHODS ===
    // Getter/setter PlayerInventory 36 ô, Oxygen và Hunger của Track C tại đây.

    /**
     * Trả về túi đồ đầy đủ 36 ô (0..8 Hotbar, 9..35 balo) thuộc sở hữu của người chơi.
     *
     * @return đối tượng {@link PlayerInventory}
     */
    public PlayerInventory getInventory() {
        return inventory;
    }

    /**
     * Vứt 1 đơn vị (Q) hoặc toàn bộ stack (Ctrl+Q) ở ô Hotbar đang chọn ra phía trước mặt người chơi.
     * Vật phẩm rơi có {@code pickupDelay = 1.0f} giây để không bị nam châm hút ngược lại ngay lập tức.
     *
     * @param world thế giới để thả thực thể {@link ItemEntity}
     * @param wholeStack true nếu vứt cả stack, false nếu chỉ vứt 1 đơn vị
     * @return thực thể {@link ItemEntity} vừa sinh ra, hoặc {@code null} nếu ô trống hoặc thiếu world
     */
    public ItemEntity dropSelectedItem(World world, boolean wholeStack) {
        if (world == null) {
            return null;
        }
        int selectedSlot = hotbar.getSelectedSlot();
        Item selectedItem = hotbar.getSelectedItem();
        int selectedCount = hotbar.getSelectedCount();
        if (selectedItem == null || selectedItem.isNone() || selectedCount <= 0) {
            return null;
        }

        int dropAmount = wholeStack ? selectedCount : 1;
        int consumed = inventory.consumeFromSlot(selectedSlot, dropAmount);
        if (consumed <= 0) {
            return null;
        }

        if (!copyAim(dropOriginBuffer, dropDirectionBuffer)) {
            dropOriginBuffer.set(position.x, position.y + currentEyeHeight, position.z);
            dropDirectionBuffer.set(0f, 0f, -1f);
        }

        // Sinh vật phẩm ở phía trước tầm mắt để bay ra ngoài tự nhiên
        float spawnX = dropOriginBuffer.x + dropDirectionBuffer.x * 0.45f;
        float spawnY = dropOriginBuffer.y - 0.25f + dropDirectionBuffer.y * 0.25f;
        float spawnZ = dropOriginBuffer.z + dropDirectionBuffer.z * 0.45f;

        dropVelocityBuffer.set(
                dropDirectionBuffer.x * 5.2f,
                dropDirectionBuffer.y * 5.2f + 1.8f,
                dropDirectionBuffer.z * 5.2f
        );

        ItemEntity dropped = new ItemEntity(spawnX, spawnY, spawnZ, dropVelocityBuffer,
                selectedItem, consumed, 1.0f);
        world.spawnDroppedItem(dropped);
        return dropped;
    }

    /**
     * Cập nhật thanh Oxy dưới nước (giảm 20 tick/giây khi mắt ngập nước và không có Water Breathing),
     * gây 2.0 HP sát thương ngạt mỗi 1.0 giây khi cạn Oxy, hoặc hồi nhanh về 300 khi lên khỏi nước.
     */
    private void updateOxygen(World world, float deltaTime) {
        eyeInWater = isEyeInWater(world);
        if (gameMode.isInvulnerable()) {
            airTicksExact = AIR_MAX_TICKS;
            drownTimer = 0.0f;
            return;
        }
        if (!eyeInWater) {
            airTicksExact = Math.min(AIR_MAX_TICKS, airTicksExact + AIR_RECOVER_PER_SECOND * deltaTime);
            drownTimer = 0.0f;
            return;
        }
        if (hasEffect(StatusEffectType.WATER_BREATHING)) {
            drownTimer = 0.0f;
            return;
        }

        float remainingTime = deltaTime;
        if (airTicksExact > OXYGEN_EPSILON) {
            float timeToEmpty = airTicksExact / AIR_DRAIN_PER_SECOND;
            if (remainingTime <= timeToEmpty + OXYGEN_EPSILON) {
                airTicksExact = Math.max(0.0f, airTicksExact - AIR_DRAIN_PER_SECOND * remainingTime);
                if (airTicksExact <= OXYGEN_EPSILON) {
                    airTicksExact = 0.0f;
                }
                return;
            }
            remainingTime -= timeToEmpty;
            airTicksExact = 0.0f;
        } else {
            airTicksExact = 0.0f;
        }

        drownTimer += remainingTime;
        while (isAlive() && drownTimer + OXYGEN_EPSILON >= DROWN_DAMAGE_INTERVAL) {
            drownTimer = Math.max(0.0f, drownTimer - DROWN_DAMAGE_INTERVAL);
            damage(world, DROWN_DAMAGE_AMOUNT, DamageSource.DROWNING, null, 0.0f, 0.0f);
        }
    }

    /**
     * Trả về lượng Oxy hiện tại (0..{@link #AIR_MAX_TICKS}).
     *
     * @return số tick Oxy còn lại
     */
    public int getAirTicks() {
        return Math.round(airTicksExact);
    }

    /**
     * Kiểm tra tầm mắt của người chơi có đang ngập trong {@link Block#WATER} hay không.
     *
     * @param world thế giới chứa dữ liệu chất lỏng
     * @return {@code true} nếu cao độ mắt đang nằm dưới mặt thoáng khối nước
     */
    public boolean isEyeInWater(World world) {
        if (world == null) {
            return false;
        }
        return world.liquidAt(position.x, position.y + currentEyeHeight, position.z) == Block.WATER;
    }

    /**
     * Trả về cờ mắt đang ngập nước đã lưu từ lượt cập nhật sinh tồn gần nhất (dùng cho HUD).
     *
     * @return {@code true} nếu mắt người chơi đang ở dưới nước
     */
    public boolean isEyeInWater() {
        return eyeInWater;
    }

    /**
     * Cho biết người chơi có đang ở trạng thái Sprint-Swimming (giữ Left Ctrl + di chuyển trong nước).
     *
     * @return {@code true} nếu đang bơi nhanh trong nước
     */
    public boolean isSwimSprinting() {
        return isSwimSprinting;
    }
    // === END HOOK: TRACK C - METHODS ===
}

package com.voxelgame.world.entity.player;

import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;

/**
 * Quản lý túi đồ đầy đủ 36 ô của {@link Player}:
 * - Các ô {@code 0..8} liên kết trực tiếp với thanh {@link Hotbar} 9 ô.
 * - Các ô {@code 9..35} là 27 ô balo mở rộng (3 hàng × 9 cột).
 *
 * Bảo toàn 100% tương thích ngược với các hệ thống chỉ gọi {@code player.getHotbar()}.
 */
public class PlayerInventory {

    /** Số ô thuộc thanh công cụ nhanh Hotbar (chỉ số 0..8). */
    public static final int HOTBAR_SLOTS = Hotbar.SLOT_COUNT;
    /** Số ô thuộc phần balo mở rộng (chỉ số 9..35). */
    public static final int BACKPACK_SLOTS = 27;
    /** Tổng số ô của toàn bộ túi đồ người chơi (36 ô). */
    public static final int TOTAL_SLOTS = HOTBAR_SLOTS + BACKPACK_SLOTS;

    private final Hotbar hotbar;
    private final Item[] backpackItems = new Item[BACKPACK_SLOTS];
    private final int[] backpackCounts = new int[BACKPACK_SLOTS];

    /**
     * Khởi tạo túi đồ 36 ô cùng một {@link Hotbar} mới gắn kèm.
     */
    public PlayerInventory() {
        this(new Hotbar());
    }

    /**
     * Khởi tạo túi đồ 36 ô bao bọc một {@link Hotbar} có sẵn cho 9 ô đầu tiên.
     *
     * @param hotbar thanh công cụ 9 ô cần liên kết
     */
    public PlayerInventory(Hotbar hotbar) {
        this.hotbar = (hotbar != null) ? hotbar : new Hotbar();
        for (int i = 0; i < BACKPACK_SLOTS; i++) {
            backpackItems[i] = Item.NONE;
            backpackCounts[i] = 0;
        }
        this.hotbar.attachOwner(this);
    }

    /**
     * Trả về thanh {@link Hotbar} 9 ô đang chia sẻ dữ liệu với các ô {@code 0..8}.
     *
     * @return đối tượng Hotbar của túi đồ
     */
    public Hotbar getHotbar() {
        return hotbar;
    }

    /**
     * Đọc loại vật phẩm tại một ô bất kỳ trong 36 ô túi đồ.
     *
     * @param slot chỉ số ô (0..35)
     * @return {@link Item} tại ô đó, hoặc {@link Item#NONE} nếu trống / ngoài phạm vi
     */
    public Item getItem(int slot) {
        if (slot < 0 || slot >= TOTAL_SLOTS) {
            return Item.NONE;
        }
        if (slot < HOTBAR_SLOTS) {
            return hotbar.getSlotItem(slot);
        }
        return backpackItems[slot - HOTBAR_SLOTS];
    }

    /**
     * Đọc số lượng vật phẩm tại một ô bất kỳ trong 36 ô túi đồ.
     *
     * @param slot chỉ số ô (0..35)
     * @return số lượng hiện có, hoặc 0 nếu trống / ngoài phạm vi
     */
    public int getCount(int slot) {
        if (slot < 0 || slot >= TOTAL_SLOTS) {
            return 0;
        }
        if (slot < HOTBAR_SLOTS) {
            return hotbar.getSlotCount(slot);
        }
        return backpackCounts[slot - HOTBAR_SLOTS];
    }

    /**
     * Thiết lập trực tiếp loại {@link Block} và số lượng cho một ô trong 36 ô túi đồ.
     *
     * @param slot chỉ số ô (0..35)
     * @param block loại khối cần đặt
     * @param count số lượng cần đặt
     */
    public void setSlot(int slot, Block block, int count) {
        setSlot(slot, Item.of(block), count);
    }

    /**
     * Thiết lập trực tiếp {@link Item} và số lượng cho một ô trong 36 ô túi đồ.
     *
     * @param slot chỉ số ô (0..35)
     * @param item vật phẩm cần đặt
     * @param count số lượng (tự giới hạn theo {@code maxStackSize})
     */
    public void setSlot(int slot, Item item, int count) {
        if (slot < 0 || slot >= TOTAL_SLOTS) {
            return;
        }
        if (slot < HOTBAR_SLOTS) {
            hotbar.setSlot(slot, item, count);
            return;
        }
        int backpackIndex = slot - HOTBAR_SLOTS;
        if (item == null || item.isNone() || count <= 0) {
            backpackItems[backpackIndex] = Item.NONE;
            backpackCounts[backpackIndex] = 0;
        } else {
            backpackItems[backpackIndex] = item;
            backpackCounts[backpackIndex] = Math.min(item.getMaxStackSize(), count);
        }
    }

    /**
     * Thêm một lượng {@link Block} vào túi đồ 36 ô (ưu tiên Hotbar trước rồi tới 27 ô balo).
     *
     * @param block loại khối cần thêm
     * @param amount số lượng cần thêm
     * @return true nếu thêm được ít nhất 1 đơn vị
     */
    public boolean addItem(Block block, int amount) {
        return addItem(Item.of(block), amount);
    }

    /**
     * Thêm một lượng {@link Item} vào túi đồ 36 ô:
     * ưu tiên gộp vào các ô cùng loại chưa đầy stack, sau đó đặt vào ô trống đầu tiên.
     *
     * @param item vật phẩm cần thêm
     * @param amount số lượng cần thêm
     * @return true nếu thêm được ít nhất 1 đơn vị
     */
    public boolean addItem(Item item, int amount) {
        return addItemUpTo(item, amount) > 0;
    }

    /**
     * Thêm tối đa {@code amount} đơn vị {@link Item} vào túi đồ 36 ô và trả về số lượng thực tế đã nhận.
     * Giúp {@link ItemEntity} xử lý nhặt từng phần khi túi gần đầy mà không làm mất vật phẩm dư.
     *
     * @param item vật phẩm cần thêm
     * @param amount số lượng mong muốn thêm
     * @return số đơn vị đã được nạp vào túi (0 nếu túi không còn chỗ)
     */
    public int addItemUpTo(Item item, int amount) {
        if (item == null || item.isNone() || amount <= 0) {
            return 0;
        }

        int maxStack = item.getMaxStackSize();
        if (maxStack <= 0) {
            return 0;
        }

        int remaining = amount;

        // Bước 1: Cộng dồn vào các ô cùng loại chưa đầy giới hạn stack (từ ô 0..35)
        for (int i = 0; i < TOTAL_SLOTS; i++) {
            if (getItem(i) == item) {
                int current = getCount(i);
                if (current < maxStack) {
                    int spaceLeft = maxStack - current;
                    int toAdd = Math.min(spaceLeft, remaining);
                    setSlot(i, item, current + toAdd);
                    remaining -= toAdd;
                    if (remaining == 0) {
                        return amount;
                    }
                }
            }
        }

        // Bước 2: Đặt phần còn lại vào các ô trống từ trái sang phải (0..8 Hotbar rồi 9..35 balo)
        for (int i = 0; i < TOTAL_SLOTS; i++) {
            if (getItem(i).isNone() || getCount(i) <= 0) {
                int toAdd = Math.min(maxStack, remaining);
                setSlot(i, item, toAdd);
                remaining -= toAdd;
                if (remaining == 0) {
                    return amount;
                }
            }
        }

        return amount - remaining;
    }

    /**
     * Tiêu thụ tối đa {@code amount} đơn vị vật phẩm tại ô chỉ định.
     *
     * @param slot chỉ số ô (0..35)
     * @param amount số lượng cần lấy ra
     * @return số đơn vị thực tế đã tiêu thụ (0 nếu ô trống hoặc không hợp lệ)
     */
    public int consumeFromSlot(int slot, int amount) {
        if (slot < 0 || slot >= TOTAL_SLOTS || amount <= 0) {
            return 0;
        }
        Item current = getItem(slot);
        int currentCount = getCount(slot);
        if (current.isNone() || currentCount <= 0) {
            return 0;
        }
        int taken = Math.min(amount, currentCount);
        int remaining = currentCount - taken;
        setSlot(slot, remaining > 0 ? current : Item.NONE, remaining);
        return taken;
    }
}

package com.voxelgame.world.entity.projectile;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.MobCategory;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Vector3;
import java.util.Objects;

/**
 * Mũi tên gây sát thương vật lý, có thể mang hiệu ứng, tự cắm cố định vào đất (cho phép người chơi nhặt lại
 * và rơi tiếp khi khối đỡ bị đào mất) hoặc cắm theo thân mob khi bắn trúng.
 */
public final class ArrowEntity extends ProjectileEntity {
    /** Gia tốc rơi dương để bộ bắn tính độ cao ngắm. */
    public static final float GRAVITY = 20f;
    /** Kích thước, thời gian bay tối đa và độ đẩy ngang của tên. */
    private static final float RADIUS = 0.045f;
    private static final float LIFETIME = 8f;
    private static final float KNOCKBACK_SPEED = 1.4f;
    /** Thời gian mũi tên cắm trên đất hoặc trên mob trước khi tự biến mất (giây). */
    private static final float GROUND_DESPAWN_SECONDS = 60f;
    private static final float MOB_STICK_DESPAWN_SECONDS = 30f;
    /** Trễ ngắn trước khi cho phép nhặt lại mũi tên cắm trên đất và bán kính nhặt. */
    private static final float PICKUP_DELAY_SECONDS = 0.2f;
    private static final float PICKUP_RADIUS = 1.15f;
    private static final float PICKUP_RADIUS_SQUARED = PICKUP_RADIUS * PICKUP_RADIUS;

    private final ArrowType type;
    private final float damage;
    /** Chỉ mũi tên do người chơi bắn mới cho phép nhặt lại từ mặt đất. */
    private final boolean pickupable;

    /** Trạng thái mũi tên đang cắm vào một khối rắn trên địa hình. */
    private boolean inGround;
    private int stuckBlockX;
    private int stuckBlockY;
    private int stuckBlockZ;
    private float stuckTimeRemaining;
    private float pickupDelay;

    /** Trạng thái mũi tên đang cắm trên thân một mob sống (zero-GC với vector đệm dùng lại). */
    private MobEntity stuckMob;
    private float stuckLocalX;
    private float stuckLocalY;
    private float stuckLocalZ;
    private float stuckRelativeYaw;
    private float stuckPitch;
    private final Vector3 tmpAnchor = new Vector3();

    /** Tạo tên tại điểm bắn và nhận lượng sát thương HP từ cấu hình cung thủ. */
    public ArrowEntity(Entity owner, float x, float y, float z, float vx, float vy, float vz,
                       ArrowType type, float damage) {
        super(owner, x, y, z, vx, vy, vz, RADIUS, GRAVITY, LIFETIME, MobAppearance.ARROW);
        this.type = Objects.requireNonNull(type);
        if (!(damage > 0f) || !Float.isFinite(damage)) {
            throw new IllegalArgumentException("Sát thương tên phải dương và hữu hạn");
        }
        this.damage = damage;
        this.pickupable = owner instanceof Player;
    }

    /** Trả về {@code true} khi mũi tên đang cắm trên đất hoặc bám trên thân mob. */
    @Override
    protected boolean isAnchored() {
        return inGround || stuckMob != null;
    }

    /** Cập nhật mũi tên đang cắm trên khối (kiểm tra đào khối, nhặt lại, hết hạn) hoặc bám theo mob. */
    @Override
    protected boolean updateAnchored(World world, float dt) {
        if (inGround) {
            stuckTimeRemaining -= dt;
            if (stuckTimeRemaining <= 0f) {
                inGround = false;
                markFinished();
                return true;
            }
            // Nếu khối mà mũi tên đang cắm vào bị phá vỡ, mũi tên rơi xuống trở lại theo trọng lực
            if (world.getCollisionBounds(stuckBlockX, stuckBlockY, stuckBlockZ) == null) {
                inGround = false;
                velocity.set(0f, -0.5f, 0f);
                resumeFlight(LIFETIME);
                return false;
            }
            if (pickupDelay > 0f) {
                pickupDelay = Math.max(0f, pickupDelay - dt);
            } else if (pickupable) {
                tryPickup(world);
            }
            return true;
        }

        if (stuckMob != null) {
            stuckTimeRemaining -= dt;
            if (stuckTimeRemaining <= 0f || !stuckMob.isAlive() || stuckMob.isReadyToRemove()) {
                stuckMob = null;
                markFinished();
                return true;
            }
            syncStuckMobTransform();
            return true;
        }

        return false;
    }

    /** Cho phép né trước khi ghi sát thương; cắm vào khối khi hụt mục tiêu hoặc cắm vào mob khi trúng. */
    @Override
    protected void onImpact(World world, LivingEntity target) {
        if (target == null) {
            inGround = true;
            stuckMob = null;
            stuckBlockX = hitBlockX();
            stuckBlockY = hitBlockY();
            stuckBlockZ = hitBlockZ();
            stuckTimeRemaining = GROUND_DESPAWN_SECONDS;
            pickupDelay = PICKUP_DELAY_SECONDS;
            velocity.setZero();
            keepAliveAfterImpact();
            return;
        }
        if (target.dodgeProjectile(world, owner())) {
            return;
        }
        float horizontalSpeed = (float) Math.sqrt(velocity.x * velocity.x + velocity.z * velocity.z);
        float scale = horizontalSpeed > 0f ? KNOCKBACK_SPEED / horizontalSpeed : 0f;
        if (!target.damage(world, damage, DamageSource.ARROW, owner(), velocity.x * scale, velocity.z * scale)) {
            return;
        }
        type.apply(target);
        if (target.isAlive() && owner() instanceof MobEntity shooter && shooter.isAlive()
                && target instanceof MobEntity victim && shooter.type().category() == MobCategory.MONSTER
                && victim.type().category() == MobCategory.MONSTER) {
            shooter.retaliateAgainst(victim);
            victim.retaliateAgainst(shooter);
        }
        if (target.isAlive() && target instanceof MobEntity mob) {
            attachToMob(mob);
            velocity.setZero();
            keepAliveAfterImpact();
        }
    }

    /** Lưu tọa độ và góc tương đối của mũi tên trong hệ quy chiếu cục bộ của mob vừa bị bắn trúng. */
    private void attachToMob(MobEntity mob) {
        mob.copyPosition(tmpAnchor);
        float dx = position.x - tmpAnchor.x;
        float dy = MathUtils.clamp(position.y - tmpAnchor.y, 0.1f, Math.max(0.2f, mob.getHeight() - 0.1f));
        float dz = position.z - tmpAnchor.z;
        float mobYaw = mob.mobVisualState().bodyYaw();
        float cos = MathUtils.cosDeg(mobYaw);
        float sin = MathUtils.sinDeg(mobYaw);
        stuckLocalX = dx * cos - dz * sin;
        stuckLocalY = dy;
        stuckLocalZ = dx * sin + dz * cos;
        stuckRelativeYaw = mobVisualState().bodyYaw() - mobYaw;
        stuckPitch = mobVisualState().bodyPitch();
        stuckMob = mob;
        inGround = false;
        stuckTimeRemaining = MOB_STICK_DESPAWN_SECONDS;
    }

    /** Đồng bộ vị trí và góc xoay của mũi tên theo vị trí và hướng thân mới nhất của mob. */
    private void syncStuckMobTransform() {
        stuckMob.copyPosition(tmpAnchor);
        float mobYaw = stuckMob.mobVisualState().bodyYaw();
        float cos = MathUtils.cosDeg(mobYaw);
        float sin = MathUtils.sinDeg(mobYaw);
        float worldDx = stuckLocalX * cos + stuckLocalZ * sin;
        float worldDz = -stuckLocalX * sin + stuckLocalZ * cos;
        position.set(tmpAnchor.x + worldDx, tmpAnchor.y + stuckLocalY, tmpAnchor.z + worldDz);
        mobVisualState().setAnimation(mobYaw + stuckRelativeYaw, 0f, 0f, 0f, 0f, 0f);
        mobVisualState().setBodyPitch(stuckPitch);
    }

    /** Cho phép người chơi đi lại gần nhặt lại mũi tên cắm trên đất vào túi đồ 36 ô. */
    private void tryPickup(World world) {
        Player player = world.getPlayer();
        if (player == null || !player.isAlive()) {
            return;
        }
        player.copyCenterPosition(tmpAnchor);
        if (tmpAnchor.dst2(position) > PICKUP_RADIUS_SQUARED) {
            return;
        }
        if (player.getInventory().addItem(type.toItem(), 1)) {
            if (world.getAudio() != null) {
                world.getAudio().playEffect(AudioManager.Effect.PICKUP, 0.25f);
            }
            inGround = false;
            markFinished();
        }
    }

    /** Cho biết mũi tên hiện có đang cắm cố định vào địa hình hay không. */
    public boolean isInGround() {
        return inGround;
    }

    /** Cho biết mũi tên hiện có đang cắm trên thân một mob hay không. */
    public boolean isStuckInMob() {
        return stuckMob != null;
    }

    /** Trả về mob đang bị mũi tên cắm vào, hoặc {@code null} nếu không cắm trên mob. */
    public MobEntity getStuckMob() {
        return stuckMob;
    }

    /** Cho biết mũi tên này có thể được người chơi nhặt lại khi cắm trên đất hay không. */
    public boolean isPickupable() {
        return pickupable;
    }

    /** Trả về loại đầu mũi tên (thường, Slowness hoặc Weakness). */
    public ArrowType getType() {
        return type;
    }
}

package com.voxelgame.world.entity.projectile;

import com.voxelgame.world.effect.StatusEffectType;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.item.Item;

/** Đầu tên và hiệu ứng có thể gắn trên một hit thành công. */
public enum ArrowType {
    NORMAL(null), SLOWNESS(StatusEffectType.SLOWNESS), WEAKNESS(StatusEffectType.WEAKNESS);

    /** Đầu tên có hiệu ứng dùng cùng thời lượng và cấp I. */
    private static final float EFFECT_SECONDS = 30f;
    private final StatusEffectType effect;

    /** Khai báo trạng thái của mẫu tên, null dành cho tên thường. */
    ArrowType(StatusEffectType effect) {
        this.effect = effect;
    }

    /** Gắn hiệu ứng qua luật miễn nhiễm của LivingEntity. */
    void apply(LivingEntity target) {
        if (effect != null) {
            target.applyEffect(effect, 0, EFFECT_SECONDS);
        }
    }

    /** Trả về vật phẩm mũi tên tương ứng khi người chơi nhặt lại mũi tên cắm trên mặt đất. */
    public Item toItem() {
        return switch (this) {
            case NORMAL -> Item.ARROW;
            case SLOWNESS -> Item.TIPPED_ARROW_SLOWNESS;
            case WEAKNESS -> Item.TIPPED_ARROW_WEAKNESS;
        };
    }
}

package com.voxelgame.world.entity.projectile;

import com.voxelgame.world.effect.StatusEffectType;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.level.World;

/** Tác động của dung dịch văng từ lọ thuốc. */
public enum PotionType {
    SLOWNESS(StatusEffectType.SLOWNESS, 90f),
    POISON(StatusEffectType.POISON, 45f),
    WEAKNESS(StatusEffectType.WEAKNESS, 90f),
    HARMING(null, 0f),
    HEALING(null, 0f);

    /** Mức HP tức thời trước khi nhân theo suy giảm bán kính. */
    private static final float MAGIC_DAMAGE = 6f;
    private static final float HEAL_AMOUNT = 4f;
    private final StatusEffectType effect;
    private final float duration;

    /** Lưu trạng thái và số giây từ loại thuốc có thời lượng. */
    PotionType(StatusEffectType effect, float duration) {
        this.effect = effect;
        this.duration = duration;
    }

    /** Áp dụng hiệu ứng cấp I hoặc đảo chiều hồi máu và sát thương cho undead. */
    void apply(World world, LivingEntity target, Entity owner, float strength) {
        if (effect != null) {
            target.applyEffect(effect, 0, duration);
        } else if (target.isUndead() == (this == HEALING)) {
            target.damage(world, MAGIC_DAMAGE * strength, DamageSource.POTION_MAGIC, owner, 0f, 0f);
        } else {
            target.heal(HEAL_AMOUNT * strength);
        }
    }
}

package com.voxelgame.world.entity.projectile;

import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.client.render.entity.MobVisual;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.client.render.ShaderProgram;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Vector3;

/** Quản lý quỹ đạo có trọng lực, quét va chạm và kết xuất dùng chung của đạn. */
public abstract class ProjectileEntity extends Entity implements MobVisual {
    /** Chia biến thiên quỹ đạo thành đoạn tối đa một tick mô phỏng 20 Hz. */
    private static final float MAX_SWEEP_SECONDS = 0.05f;
    /** Giữ góc ngang cũ khi đạn bay gần như thẳng đứng. */
    private static final float FACING_EPSILON = 0.0000001f;

    /** Chủ sở hữu và cấu hình vật lý cố định của phát bắn. */
    private final Entity owner;
    private final float gravity;
    private float lifeRemaining;
    private boolean finished;
    /** Tọa độ khối gần nhất bị cắt trúng trong bước quét va chạm hiện tại. */
    private int hitBlockX;
    private int hitBlockY;
    private int hitBlockZ;

    /** Tái sử dụng đoạn dịch chuyển và bộ đọc tâm mục tiêu. */
    private final Vector3 segment = new Vector3();
    private final Vector3 targetCenter = new Vector3();
    private final MobVisualState visual;

    /** Tạo đạn tại tâm phát, với vận tốc theo block/giây và thời gian sống tính theo giây. */
    protected ProjectileEntity(Entity owner, float x, float y, float z, float vx, float vy, float vz,
                               float radius, float gravity, float lifetime, MobAppearance appearance) {
        super(x, y, z, radius, 0f);
        if (!Float.isFinite(vx) || !Float.isFinite(vy) || !Float.isFinite(vz)) {
            throw new IllegalArgumentException("Vận tốc đạn phải hữu hạn");
        }
        this.owner = owner;
        this.gravity = gravity;
        lifeRemaining = lifetime;
        velocity.set(vx, vy, vz);
        visual = new MobVisualState(appearance);
        updateFacing();
    }

    /** Tích phân parabol từng đoạn ngắn, kết thúc khi chạm, hết hạn hoặc ra ngoài thế giới. */
    @Override
    public final void update(World world, float dt) {
        if (finished || world == null || !(dt > 0f) || !Float.isFinite(dt)) {
            return;
        }
        if (updateAnchored(world, dt)) {
            return;
        }
        float remaining = Math.min(dt, lifeRemaining);
        while (remaining > 0f && !finished && !isAnchored()) {
            if (!isInWorld(world)) {
                finished = true;
                return;
            }
            float step = Math.min(remaining, MAX_SWEEP_SECONDS);
            segment.set(velocity.x * step, (velocity.y - 0.5f * gravity * step) * step, velocity.z * step);
            sweep(world);
            if (finished || isAnchored()) {
                break;
            }
            velocity.y -= gravity * step;
            remaining -= step;
        }
        if (isAnchored()) {
            return;
        }
        lifeRemaining -= Math.min(dt, lifeRemaining);
        finished |= lifeRemaining <= 0f || !isInWorld(world);
        if (!finished) {
            updateFacing();
        }
    }

    /** Chặn tọa độ không hữu hạn hoặc tâm đạn đã rời lưới thế giới. */
    private boolean isInWorld(World world) {
        return Float.isFinite(position.x) && Float.isFinite(position.y) && Float.isFinite(position.z)
                && world.isInsideWorld(floorCell(position.x), floorCell(position.y), floorCell(position.z));
    }

    /** Chọn giao điểm sớm nhất trong đoạn, ưu tiên khối nếu khoảng cách bằng nhau. */
    private void sweep(World world) {
        float lengthSquared = segment.len2();
        if (!(lengthSquared > 0f) || !Float.isFinite(lengthSquared)) {
            finished = !Float.isFinite(lengthSquared);
            return;
        }
        float closest = blockEntry(world);
        LivingEntity directHit = null;
        for (int i = 0; i < world.entityCount(); i++) {
            Entity entity = world.entityAt(i);
            if (entity instanceof LivingEntity living && canAffect(living)) {
                float entry = intersect(living, Math.min(1f, closest));
                if (entry < closest) {
                    closest = entry;
                    directHit = living;
                }
            }
        }
        if (Float.isFinite(closest)) {
            position.mulAdd(segment, closest);
            updateFacing();
            finished = true;
            onImpact(world, directHit);
        } else {
            position.add(segment);
        }
    }

    /** Duyệt ô dọc đường tâm và dừng tại đoạn đầu tiên có va chạm với hộp đạn. */
    private float blockEntry(World world) {
        int x = floorCell(position.x);
        int y = floorCell(position.y);
        int z = floorCell(position.z);
        int sx = segment.x >= 0f ? 1 : -1;
        int sy = segment.y >= 0f ? 1 : -1;
        int sz = segment.z >= 0f ? 1 : -1;
        float nextX = boundaryTime(position.x, x, sx, segment.x);
        float nextY = boundaryTime(position.y, y, sy, segment.y);
        float nextZ = boundaryTime(position.z, z, sz, segment.z);
        float strideX = Math.abs(1f / segment.x);
        float strideY = Math.abs(1f / segment.y);
        float strideZ = Math.abs(1f / segment.z);

        float from = 0f;
        while (world.isInsideWorld(x, y, z)) {
            float to = Math.min(1f, Math.min(nextX, Math.min(nextY, nextZ)));
            float hit = blockEntryInInterval(world, from, to);
            if (Float.isFinite(hit) || to >= 1f) {
                return hit;
            }
            from = to;
            if (nextX == to) {
                x += sx;
                nextX += strideX;
            }
            if (nextY == to) {
                y += sy;
                nextY += strideY;
            }
            if (nextZ == to) {
                z += sz;
                nextZ += strideZ;
            }
        }
        return Float.POSITIVE_INFINITY;
    }

    /** Chỉ kiểm tra những ô mà hộp đạn có thể chạm trong khoảng đang duyệt. */
    private float blockEntryInInterval(World world, float from, float to) {
        float startX = position.x + segment.x * from;
        float startY = position.y + segment.y * from;
        float startZ = position.z + segment.z * from;
        float endX = position.x + segment.x * to;
        float endY = position.y + segment.y * to;
        float endZ = position.z + segment.z * to;
        // Lấy cả ô ở phía dưới nếu mặt đáy hộp vừa trùng với biên nguyên.
        int minX = floorCell(Math.nextDown(Math.min(startX, endX) - halfWidth));
        int minY = floorCell(Math.nextDown(Math.min(startY, endY) - halfWidth));
        int minZ = floorCell(Math.nextDown(Math.min(startZ, endZ) - halfWidth));
        int maxX = floorCell(Math.nextUp(Math.max(startX, endX) + halfWidth));
        int maxY = floorCell(Math.nextUp(Math.max(startY, endY) + halfWidth));
        int maxZ = floorCell(Math.nextUp(Math.max(startZ, endZ) + halfWidth));
        float closest = Float.POSITIVE_INFINITY;
        for (int x = minX; x <= maxX; x++) {
            for (int y = minY; y <= maxY; y++) {
                for (int z = minZ; z <= maxZ; z++) {
                    Block.Bounds bounds = world.getCollisionBounds(x, y, z);
                    if (bounds == null) {
                        continue;
                    }
                    float entry = intersect(x + bounds.minX() - halfWidth, y + bounds.minY() - halfWidth,
                            z + bounds.minZ() - halfWidth, x + bounds.maxX() + halfWidth,
                            y + bounds.maxY() + halfWidth, z + bounds.maxZ() + halfWidth,
                            from, Math.min(to, closest));
                    if (entry < closest) {
                        closest = entry;
                        hitBlockX = x;
                        hitBlockY = y;
                        hitBlockZ = z;
                    }
                }
            }
        }
        return closest;
    }

    /** Làm tròn xuống chính xác cho cả tọa độ sát mặt nguyên của voxel. */
    private static int floorCell(float coordinate) {
        return (int) Math.floor(coordinate);
    }

    /** Tính tỷ lệ tới biên ô, hoặc vô cực khi đoạn bay song song với biên. */
    private static float boundaryTime(float origin, int cell, int direction, float travel) {
        return travel == 0f ? Float.POSITIVE_INFINITY
                : (cell + (direction > 0 ? 1f : 0f) - origin) / travel;
    }

    /** Cắt tâm đạn chuyển động với AABB mục tiêu nới theo bán kính đạn. */
    private float intersect(LivingEntity living, float limit) {
        living.copyCenterPosition(targetCenter);
        float horizontal = living.getHalfWidth() + halfWidth;
        float vertical = living.getHeight() * 0.5f + halfWidth;
        return intersect(targetCenter.x - horizontal, targetCenter.y - vertical, targetCenter.z - horizontal,
                targetCenter.x + horizontal, targetCenter.y + vertical, targetCenter.z + horizontal, 0f, limit);
    }

    /** Giao ba khoảng theo trục của đoạn bay với một hộp đã nới theo bán kính. */
    private float intersect(float minX, float minY, float minZ, float maxX, float maxY, float maxZ,
                            float near, float far) {
        for (int axis = 0; axis < 3; axis++) {
            float origin = axis == 0 ? position.x : axis == 1 ? position.y : position.z;
            float travel = axis == 0 ? segment.x : axis == 1 ? segment.y : segment.z;
            float low = axis == 0 ? minX : axis == 1 ? minY : minZ;
            float high = axis == 0 ? maxX : axis == 1 ? maxY : maxZ;
            if (travel == 0f) {
                if (origin < low || origin > high) {
                    return Float.POSITIVE_INFINITY;
                }
                continue;
            }
            float first = (low - origin) / travel;
            float last = (high - origin) / travel;
            near = Math.max(near, Math.min(first, last));
            far = Math.min(far, Math.max(first, last));
            if (far < near) {
                return Float.POSITIVE_INFINITY;
            }
        }
        return near;
    }

    /** Tránh chủ, các cá thể cùng chuỗi ghế và đồng phe trước khi nhận va chạm hoặc hiệu ứng. */
    protected final boolean canAffect(LivingEntity candidate) {
        if (!candidate.isAlive() || candidate == owner) {
            return false;
        }
        if (owner instanceof LivingEntity shooter && (shooter.getMount() != null || candidate.getMount() != null)
                && mountRoot(shooter) == mountRoot(candidate)) {
            return false;
        }
        return !(owner instanceof MobEntity source && candidate instanceof MobEntity mob && source.isAlliedTo(mob));
    }

    /** Lần theo chuỗi ghế đã được LivingEntity đảm bảo không có chu trình. */
    private static LivingEntity mountRoot(LivingEntity entity) {
        LivingEntity mount;
        while ((mount = entity.getMount()) != null) {
            entity = mount;
        }
        return entity;
    }

    /** Tính khoảng cách từ điểm trúng đến tâm AABB mà không tạo vector mới. */
    protected final float squaredDistanceTo(LivingEntity living) {
        return living.copyCenterPosition(targetCenter).dst2(position);
    }

    /** Phản ứng khi trúng mục tiêu, hoặc khi trúng địa hình nếu target null. */
    protected abstract void onImpact(World world, LivingEntity target);

    /** Báo đạn đang ở trạng thái bám cố định (cắm vào khối hoặc mob) thay vì đang bay tự do. */
    protected boolean isAnchored() {
        return false;
    }

    /** Cập nhật trạng thái bám cố định nếu có; trả về {@code true} để bỏ qua lượt bay parabol. */
    protected boolean updateAnchored(World world, float dt) {
        return false;
    }

    /** Giữ đạn tồn tại trong World sau va chạm (dùng cho mũi tên cắm vào khối hoặc mob). */
    protected final void keepAliveAfterImpact() {
        finished = false;
    }

    /** Đánh dấu đạn đã hoàn tất vòng đời để World thu hồi. */
    protected final void markFinished() {
        finished = true;
    }

    /** Đưa đạn quay lại trạng thái bay với thời gian sống mới (khi khối đỡ bị phá vỡ). */
    protected final void resumeFlight(float lifetime) {
        lifeRemaining = lifetime;
        finished = false;
        updateFacing();
    }

    /** Tọa độ X của khối gần nhất mà đạn vừa chạm vào. */
    protected final int hitBlockX() { return hitBlockX; }

    /** Tọa độ Y của khối gần nhất mà đạn vừa chạm vào. */
    protected final int hitBlockY() { return hitBlockY; }

    /** Tọa độ Z của khối gần nhất mà đạn vừa chạm vào. */
    protected final int hitBlockZ() { return hitBlockZ; }

    /** Hướng mẫu về phía vận tốc tức thời, dùng trục -Z của mẫu làm hướng trước. */
    private void updateFacing() {
        float horizontal = (float) Math.sqrt(velocity.x * velocity.x + velocity.z * velocity.z);
        float yaw = horizontal <= FACING_EPSILON ? visual.bodyYaw()
                : MathUtils.atan2(-velocity.x, -velocity.z) * MathUtils.radiansToDegrees;
        float pitch = MathUtils.atan2(velocity.y, horizontal) * MathUtils.radiansToDegrees;
        visual.setAnimation(yaw, 0f, 0f, 0f, 0f, 0f);
        visual.setBodyPitch(pitch);
    }

    /** Cho phép World thu hồi một đạn đã kết thúc. */
    public final boolean isFinished() { return finished; }

    /** Trả thực thể chịu trách nhiệm đối với tác động của đạn. */
    public final Entity owner() { return owner; }

    /** Dùng lại ảnh, hình học và trạng thái hướng qua MobRenderer. */
    @Override
    public final MobVisualState mobVisualState() { return visual; }

    /** Phần hình của đạn nằm trong lượt MobRenderer. */
    @Override
    public final void render(ShaderProgram shader) {
    }
}

package com.voxelgame.world.entity.projectile;

import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.animal.Chicken;
import com.voxelgame.world.level.World;

import java.util.concurrent.ThreadLocalRandom;

/**
 * Quả trứng ném bay theo parabol và có xác suất nở ra gà con ({@link Chicken#setBaby(boolean)})
 * khi vỡ tại điểm va chạm: xác suất {@code 1/8} nở 1 con, và trong số đó {@code 1/32} nở 4 con.
 */
public final class ThrownEggEntity extends ProjectileEntity {
    /** Gia tốc trọng trường dương (block/giây²) dùng chung với đạn ném bằng tay. */
    public static final float GRAVITY = 14f;
    /** Không gian mẫu chuẩn {@code [0, 255]} để biểu diễn chính xác xác suất {@code 1/8} và {@code 1/256}. */
    public static final int ROLL_RANGE = 256;
    /** Bán kính va chạm và thời gian bay tối đa của trứng ném. */
    private static final float RADIUS = 0.125f;
    private static final float LIFETIME = 10f;

    /** Giá trị tung xúc xắc cố định dùng cho kiểm thử đơn vị ({@code -1} nghĩa là ngẫu nhiên). */
    private int forcedRollForTest = -1;

    /**
     * Tạo quả trứng ném từ chủ sở hữu trong thế giới hiện tại.
     *
     * @param world thế giới nơi ném đạn (tham số ngữ cảnh thống nhất giao diện Track A)
     * @param owner thực thể sống ném trứng
     * @param x     tọa độ xuất phát X
     * @param y     tọa độ xuất phát Y
     * @param z     tọa độ xuất phát Z
     * @param vx    vận tốc ban đầu theo trục X
     * @param vy    vận tốc ban đầu theo trục Y
     * @param vz    vận tốc ban đầu theo trục Z
     */
    public ThrownEggEntity(World world, LivingEntity owner, float x, float y, float z,
                           float vx, float vy, float vz) {
        this((Entity) owner, x, y, z, vx, vy, vz);
    }

    /**
     * Tạo quả trứng ném với chữ ký đồng nhất cùng {@link ArrowEntity} và {@link ThrownPotionEntity}.
     *
     * @param owner thực thể ném trứng
     * @param x     tọa độ xuất phát X
     * @param y     tọa độ xuất phát Y
     * @param z     tọa độ xuất phát Z
     * @param vx    vận tốc ban đầu theo trục X
     * @param vy    vận tốc ban đầu theo trục Y
     * @param vz    vận tốc ban đầu theo trục Z
     */
    public ThrownEggEntity(Entity owner, float x, float y, float z, float vx, float vy, float vz) {
        super(owner, x, y, z, vx, vy, vz, RADIUS, GRAVITY, LIFETIME, MobAppearance.POTION);
    }

    /**
     * Tính số lượng gà con nở ra từ một giá trị tung xúc xắc nguyên theo đúng xác suất Minecraft:
     * <ul>
     *   <li>{@code roll % 8 != 0}: không nở ({@code 0} con, 224/256 = {@code 7/8}).</li>
     *   <li>{@code roll % 8 == 0} nhưng {@code normalized != 0}: nở {@code 1} con (31/256).</li>
     *   <li>{@code normalized == 0}: nở {@code 4} con (1/256, tức {@code 1/32} trong số các lần nở {@code 1/8}).</li>
     * </ul>
     *
     * @param roll giá trị nguyên bất kỳ (được chuẩn hóa về {@code [0, 255]})
     * @return số gà con nở ra ({@code 0}, {@code 1} hoặc {@code 4})
     */
    public static int rollChickCount(int roll) {
        int normalized = Math.floorMod(roll, ROLL_RANGE);
        if (normalized % 8 != 0) {
            return 0;
        }
        return normalized == 0 ? 4 : 1;
    }

    /** Cho phép kiểm thử hồi quy ấn định giá trị tung xúc xắc xác định trước. */
    public void setHatchRollForTest(int roll) {
        forcedRollForTest = roll;
    }

    /**
     * Khi trứng chạm khối hoặc thực thể, tung xác suất nở gà con tại vị trí vỡ.
     */
    @Override
    protected void onImpact(World world, LivingEntity target) {
        if (world == null) {
            return;
        }
        int roll = forcedRollForTest >= 0 ? forcedRollForTest : ThreadLocalRandom.current().nextInt(ROLL_RANGE);
        int chickCount = rollChickCount(roll);
        for (int i = 0; i < chickCount; i++) {
            Chicken chick = new Chicken(position.x, position.y, position.z);
            chick.setBaby(true);
            world.addEntity(chick);
        }
    }
}

package com.voxelgame.world.entity.projectile;

import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.Vector3;

/**
 * Ngọc Ender (Ender Pearl) bay theo quỹ đạo parabol và dịch chuyển chủ sở hữu tới điểm chạm an toàn,
 * đồng thời đặt lại quãng rơi tích lũy và gây {@code 5.0f} sát thương rơi chuẩn Minecraft.
 */
public final class ThrownEnderPearlEntity extends ProjectileEntity {
    /** Gia tốc trọng trường dương (block/giây²) dùng chung với đạn ném bằng tay. */
    public static final float GRAVITY = 14f;
    /** Lượng sát thương dịch chuyển gây cho chủ sở hữu khi ngọc chạm đích. */
    public static final float TELEPORT_DAMAGE = 5.0f;
    /** Bán kính va chạm và thời gian bay tối đa của ngọc Ender. */
    private static final float RADIUS = 0.125f;
    private static final float LIFETIME = 10f;
    /** Các bước lùi dọc ngược hướng bay khi ngọc đâm vào mặt bên hoặc trần khối. */
    private static final float[] BACKOFF_DISTANCES = {0.35f, 0.6f, 0.9f};
    /** Độ lệch tìm ô trống 2 block cao quanh điểm va chạm làm phương án dự phòng. */
    private static final int[] SEARCH_XZ = {0, -1, 1};
    private static final int[] SEARCH_Y = {0, 1, -1, 2};
    /** Sai số nhỏ để tránh chạm biên AABB khi đứng sát mặt khối. */
    private static final float CLEARANCE_EPSILON = 0.001f;

    /** Bộ đệm tọa độ đích được cấp phát một lần trên mỗi viên ngọc (zero-GC). */
    private final Vector3 safeLanding = new Vector3();

    /**
     * Tạo ngọc Ender được ném từ chủ sở hữu trong thế giới hiện tại.
     *
     * @param world thế giới nơi ném đạn (tham số ngữ cảnh thống nhất giao diện Track A)
     * @param owner thực thể sống sẽ được dịch chuyển khi ngọc chạm đích
     * @param x     tọa độ xuất phát X
     * @param y     tọa độ xuất phát Y
     * @param z     tọa độ xuất phát Z
     * @param vx    vận tốc ban đầu theo trục X
     * @param vy    vận tốc ban đầu theo trục Y
     * @param vz    vận tốc ban đầu theo trục Z
     */
    public ThrownEnderPearlEntity(World world, LivingEntity owner, float x, float y, float z,
                                  float vx, float vy, float vz) {
        this((Entity) owner, x, y, z, vx, vy, vz);
    }

    /**
     * Tạo ngọc Ender với chữ ký đồng nhất cùng {@link ArrowEntity} và {@link ThrownPotionEntity}.
     *
     * @param owner thực thể ném đạn
     * @param x     tọa độ xuất phát X
     * @param y     tọa độ xuất phát Y
     * @param z     tọa độ xuất phát Z
     * @param vx    vận tốc ban đầu theo trục X
     * @param vy    vận tốc ban đầu theo trục Y
     * @param vz    vận tốc ban đầu theo trục Z
     */
    public ThrownEnderPearlEntity(Entity owner, float x, float y, float z, float vx, float vy, float vz) {
        super(owner, x, y, z, vx, vy, vz, RADIUS, GRAVITY, LIFETIME, MobAppearance.ENDER_PEARL);
    }

    /**
     * Dịch chuyển chủ sở hữu còn sống tới vị trí đứng an toàn gần điểm va chạm,
     * xóa quãng rơi ({@code fallDistance = 0}) và gây {@code 5.0f} sát thương.
     */
    @Override
    protected void onImpact(World world, LivingEntity target) {
        if (world == null || !(owner() instanceof LivingEntity livingOwner) || !livingOwner.isAlive()) {
            return;
        }
        // Tách khỏi thú cưỡi nếu chủ sở hữu đang cưỡi trước khi dịch chuyển tới điểm mới
        livingOwner.leaveMount();
        findSafeTeleportPosition(world, livingOwner, safeLanding);
        livingOwner.setPosition(safeLanding.x, safeLanding.y, safeLanding.z);
        livingOwner.stopMotion();
        livingOwner.damage(world, TELEPORT_DAMAGE, DamageSource.FALL, null, 0f, 0f);
    }

    /**
     * Tìm tọa độ đứng có đủ chiều cao cho thân và đầu thực thể quanh điểm va chạm,
     * ưu tiên vị trí chạm trực tiếp rồi lùi nhẹ ngược hướng bay nếu va vào mặt bên.
     */
    private void findSafeTeleportPosition(World world, LivingEntity owner, Vector3 out) {
        float halfWidth = owner.getHalfWidth();
        float height = owner.getHeight();
        float impactX = position.x;
        float impactY = position.y;
        float impactZ = position.z;

        // 1. Thử ngay tại điểm chạm (hợp lệ ngay khi ngọc rơi xuống mặt trên sàn)
        if (canStandAt(world, impactX, impactY, impactZ, halfWidth, height)) {
            out.set(impactX, impactY, impactZ);
            return;
        }

        // 2. Lùi nhẹ ngược theo hướng bay 3D và hướng bay ngang XZ nếu đâm vào mặt bên/trần
        float speed = velocity.len();
        if (speed > CLEARANCE_EPSILON) {
            float dirX = velocity.x / speed;
            float dirY = velocity.y / speed;
            float dirZ = velocity.z / speed;
            for (float backoff : BACKOFF_DISTANCES) {
                float cx = impactX - dirX * backoff;
                float cy = impactY - dirY * backoff;
                float cz = impactZ - dirZ * backoff;
                if (canStandAt(world, cx, cy, cz, halfWidth, height)) {
                    out.set(cx, cy, cz);
                    return;
                }
            }
        }

        float horizSpeed = (float) Math.sqrt(velocity.x * velocity.x + velocity.z * velocity.z);
        if (horizSpeed > CLEARANCE_EPSILON) {
            float hDirX = velocity.x / horizSpeed;
            float hDirZ = velocity.z / horizSpeed;
            for (float backoff : BACKOFF_DISTANCES) {
                float cx = impactX - hDirX * backoff;
                float cz = impactZ - hDirZ * backoff;
                if (canStandAt(world, cx, impactY, cz, halfWidth, height)) {
                    out.set(cx, impactY, cz);
                    return;
                }
                float snappedY = (float) Math.floor(impactY);
                if (canStandAt(world, cx, snappedY, cz, halfWidth, height)) {
                    out.set(cx, snappedY, cz);
                    return;
                }
                if (canStandAt(world, cx, snappedY + 1.0f, cz, halfWidth, height)) {
                    out.set(cx, snappedY + 1.0f, cz);
                    return;
                }
            }
        }

        // 3. Quét các ô lân cận có khoảng trống 2 block cho chân và đầu
        int baseX = (int) Math.floor(impactX);
        int baseY = (int) Math.floor(impactY);
        int baseZ = (int) Math.floor(impactZ);
        for (int dy : SEARCH_Y) {
            for (int dx : SEARCH_XZ) {
                for (int dz : SEARCH_XZ) {
                    float cx = baseX + dx + 0.5f;
                    float cy = baseY + dy;
                    float cz = baseZ + dz + 0.5f;
                    if (canStandAt(world, cx, cy, cz, halfWidth, height)) {
                        out.set(cx, cy, cz);
                        return;
                    }
                }
            }
        }

        // 4. Phương án cuối nếu toàn bộ vùng xung quanh đều bị chặn kín
        out.set(impactX, impactY, impactZ);
    }

    /**
     * Kiểm tra hộp va chạm AABB của chủ sở hữu tại {@code (x, y, z)} có nằm trong thế giới
     * và hoàn toàn không giao cắt với bất kỳ khối rắn nào hay không.
     */
    private static boolean canStandAt(World world, float x, float y, float z, float halfWidth, float height) {
        if (!world.isInsideWorld((int) Math.floor(x), (int) Math.floor(y), (int) Math.floor(z))) {
            return false;
        }
        float minX = x - halfWidth + CLEARANCE_EPSILON;
        float maxX = x + halfWidth - CLEARANCE_EPSILON;
        float minY = y + CLEARANCE_EPSILON;
        float maxY = y + height - CLEARANCE_EPSILON;
        float minZ = z - halfWidth + CLEARANCE_EPSILON;
        float maxZ = z + halfWidth - CLEARANCE_EPSILON;

        int bx0 = (int) Math.floor(minX);
        int bx1 = (int) Math.floor(maxX);
        int by0 = (int) Math.floor(minY);
        int by1 = (int) Math.floor(maxY);
        int bz0 = (int) Math.floor(minZ);
        int bz1 = (int) Math.floor(maxZ);

        for (int bx = bx0; bx <= bx1; bx++) {
            for (int by = by0; by <= by1; by++) {
                for (int bz = bz0; bz <= bz1; bz++) {
                    if (!world.isInsideWorld(bx, by, bz)) {
                        return false;
                    }
                    Block.Bounds bounds = world.getCollisionBounds(bx, by, bz);
                    if (bounds != null && bounds.intersects(bx, by, bz,
                            minX, minY, minZ, maxX, maxY, maxZ)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

package com.voxelgame.world.entity.projectile;

import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.level.World;

import java.util.Objects;

/** Lọ thuốc bay theo parabol và tạo vùng ảnh hưởng ngay khi vỡ. */
public final class ThrownPotionEntity extends ProjectileEntity {
    /** Gia tốc rơi dương để bộ ném tính độ nâng parabol. */
    public static final float GRAVITY = 14f;
    /** Bán kính chạm đích, khoảng ảnh hưởng và tuổi thọ khi vẫn đang bay. */
    private static final float RADIUS = 0.12f;
    private static final float SPLASH_RADIUS = 4f;
    private static final float SPLASH_RADIUS_SQUARED = SPLASH_RADIUS * SPLASH_RADIUS;
    private static final float LIFETIME = 6f;

    private final PotionType type;

    /** Tạo lọ đang bay với dung dịch cố định cho lần vỡ duy nhất. */
    public ThrownPotionEntity(Entity owner, float x, float y, float z, float vx, float vy, float vz,
                              PotionType type) {
        super(owner, x, y, z, vx, vy, vz, RADIUS, GRAVITY, LIFETIME, MobAppearance.POTION);
        this.type = Objects.requireNonNull(type);
    }

    /** Quét mục tiêu trong hình cầu tại điểm vỡ, giữ toàn lực cho lần trúng trực tiếp. */
    @Override
    protected void onImpact(World world, LivingEntity target) {
        for (int i = 0; i < world.entityCount(); i++) {
            if (!(world.entityAt(i) instanceof LivingEntity nearby) || !canAffect(nearby)) {
                continue;
            }
            if (nearby == target) {
                type.apply(world, nearby, owner(), 1f);
                continue;
            }
            float distanceSquared = squaredDistanceTo(nearby);
            if (distanceSquared < SPLASH_RADIUS_SQUARED) {
                float strength = 1f - (float) Math.sqrt(distanceSquared) / SPLASH_RADIUS;
                type.apply(world, nearby, owner(), strength);
            }
        }
    }
}

package com.voxelgame.world.gamemode;

import com.voxelgame.world.entity.player.Player;
