package com.voxelgame.world.item;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.World;
import com.voxelgame.world.level.block.Block;

/**
 * Lớp trừu tượng áp dụng mẫu Template Method cho nhóm vật phẩm tiêu thụ bằng cách giữ chuột phải 1,6 giây
 * (gồm {@link FoodItem} và {@link PotionItem}).
 */
public abstract class ConsumableItem extends Item {

    /** Khởi tạo vật phẩm tiêu thụ độc lập. */
    protected ConsumableItem(int id, String displayName, int maxStackSize, String textureName,
                             int atlasTileIndex, int fallbackRgb) {
        super(id, displayName, maxStackSize, Block.AIR, textureName, atlasTileIndex, false, fallbackRgb);
    }

    /** Thời lượng giữ chuột phải tiêu chuẩn để ăn hoặc uống xong (1,6 giây). */
    @Override
    public float getUseDurationSeconds() {
        return ItemUseHandler.CONSUME_DURATION_SECONDS;
    }

    /** Âm thanh lặp định kỳ mỗi 0,25 giây trong lúc đang ăn hoặc uống. */
    public abstract AudioManager.Effect getConsumeTickSound();

    /** Âm thanh phát ra khi hoàn tất tiêu thụ vật phẩm. */
    public abstract AudioManager.Effect getConsumeFinishSound();

    /** Âm lượng của âm thanh hoàn tất tiêu thụ. */
    public float getConsumeFinishGain() {
        return 0.45f;
    }

    /**
     * Template Method hoàn tất quá trình tiêu thụ: áp dụng tác dụng cụ thể của lớp con
     * rồi phát âm thanh kết thúc tương ứng.
     */
    @Override
    public final void onConsumeComplete(World world, Player player) {
        applyConsumeEffect(world, player);
        AudioManager audio = world != null ? world.getAudio() : null;
        if (audio != null) {
            audio.playEffect(getConsumeFinishSound(), getConsumeFinishGain());
        }
    }

    /** Hook cho lớp con thực thi hiệu ứng hồi đói, hồi máu, áp trạng thái và hoàn trả vật chứa. */
    protected abstract void applyConsumeEffect(World world, Player player);
}

package com.voxelgame.world.item;

import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.block.WoolBlock;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * Danh mục tĩnh bất biến tổng hợp toàn bộ khối và vật phẩm có thể lấy trong chế độ Creative,
 * phục vụ {@code CreativeInventoryScreen} để người chơi minh họa mọi nội dung của trò chơi.
 *
 * <p>Thiết kế Zero-GC:</p>
 * <ul>
 *   <li>Toàn bộ mảng vật phẩm của 5 tab ({@link Tab#ALL}, {@link Tab#BLOCKS}, {@link Tab#COMBAT},
 *       {@link Tab#FOOD}, {@link Tab#ITEMS}) được dựng một lần duy nhất trong khối {@code static}.</li>
 *   <li>Tự động loại bỏ {@link Block#AIR}, chất lỏng ({@link Block#WATER}, {@link Block#LAVA}) và
 *       khử trùng lặp 6 khối {@link WoolBlock} (vì 6 vật phẩm {@code Item.*_WOOL} đã liên kết 2 chiều).</li>
 *   <li>Bao gồm cả {@link Block#BEDROCK} và đầy đủ 56 vật phẩm độc lập chuẩn Minecraft 1.21.11.</li>
 * </ul>
 */
public final class CreativeCatalog {

    /** Năm nhóm danh mục hiển thị trên thanh tab của Kho Creative. */
    public enum Tab {
        /** Toàn bộ khối và vật phẩm trong trò chơi. */
        ALL("ALL"),
        /** Toàn bộ khối xây dựng, địa hình, thực vật, rương và 6 màu len. */
        BLOCKS("BLOCKS"),
        /** Vũ khí, cung tên, công cụ tương tác và lọ thuốc chiến đấu/tiện ích. */
        COMBAT("COMBAT"),
        /** Toàn bộ 19 loại thức ăn chuẩn Minecraft. */
        FOOD("FOOD"),
        /** Nguyên liệu rơi từ mob, đạn ném, đĩa nhạc, sừng dê và các vật phẩm khác. */
        ITEMS("ITEMS");

        /** Nhãn in hoa ngắn tương thích trực tiếp với font 5×7 của {@code BitmapFont}. */
        private final String label;

        Tab(String label) {
            this.label = label;
        }

        /** Trả về nhãn hiển thị trên nút tab. */
        public String getLabel() {
            return label;
        }
    }

    /** Bảng mảng tĩnh bất biến ánh xạ từng {@link Tab} sang danh sách vật phẩm (O(1), zero-GC). */
    private static final Map<Tab, Item[]> BY_TAB = buildCatalog();

    private CreativeCatalog() {
    }

    /** Trả về mảng tĩnh các vật phẩm thuộc {@code tab} (không cấp phát mới). */
    public static Item[] getItems(Tab tab) {
        if (tab == null) {
            return BY_TAB.get(Tab.ALL);
        }
        return BY_TAB.get(tab);
    }

    /** Trả về tổng số vật phẩm trong {@code tab}. */
    public static int getItemCount(Tab tab) {
        return getItems(tab).length;
    }

    /** Trả về vật phẩm tại chỉ số {@code index} trong {@code tab}, hoặc {@link Item#NONE} nếu ngoài biên. */
    public static Item getItem(Tab tab, int index) {
        Item[] items = getItems(tab);
        if (index < 0 || index >= items.length) {
            return Item.NONE;
        }
        return items[index];
    }

    /** Dựng một lần duy nhất toàn bộ 5 danh mục từ registry {@link Block} và {@link Item}. */
    private static Map<Tab, Item[]> buildCatalog() {
        List<Item> all = new ArrayList<>(96);
        List<Item> blocks = new ArrayList<>(36);
        List<Item> combat = new ArrayList<>(20);
        List<Item> food = new ArrayList<>(24);
        List<Item> misc = new ArrayList<>(32);

        // 1. Toàn bộ khối hợp lệ (bao gồm Bedrock; bỏ Air, Water, Lava và 6 WoolBlock tránh trùng với Item.*_WOOL)
        for (int id = 1; id < 256; id++) {
            Block block = Block.fromId((byte) id);
            if (block == null || block == Block.AIR || block.isLiquid() || block instanceof WoolBlock) {
                continue;
            }
            Item blockItem = Item.of(block);
            if (blockItem != null && !blockItem.isNone()) {
                all.add(blockItem);
                blocks.add(blockItem);
            }
        }

        // 2. Toàn bộ 56 vật phẩm độc lập (gồm 6 màu len đặt được thành khối)
        List<Item> standalone = Item.allStandaloneItems();
        for (int i = 0; i < standalone.size(); i++) {
            Item item = standalone.get(i);
            if (item == null || item.isNone()) {
                continue;
            }
            all.add(item);
            if (item.isBlock()) {
                blocks.add(item);
            } else if (item instanceof FoodItem) {
                food.add(item);
            } else if (isCombatOrTool(item)) {
                combat.add(item);
            } else {
                misc.add(item);
            }
        }

        EnumMap<Tab, Item[]> map = new EnumMap<>(Tab.class);
        map.put(Tab.ALL, all.toArray(new Item[0]));
        map.put(Tab.BLOCKS, blocks.toArray(new Item[0]));
        map.put(Tab.COMBAT, combat.toArray(new Item[0]));
        map.put(Tab.FOOD, food.toArray(new Item[0]));
        map.put(Tab.ITEMS, misc.toArray(new Item[0]));
        return map;
    }

    /** Phân loại nhóm vũ khí, cung tên, công cụ và thuốc uống cho tab {@link Tab#COMBAT}. */
    private static boolean isCombatOrTool(Item item) {
        return item instanceof BowItem
                || item instanceof SpearItem
                || item instanceof ToolItem
                || item instanceof PotionItem
                || item == Item.ARROW
                || item == Item.TIPPED_ARROW_SLOWNESS
                || item == Item.TIPPED_ARROW_WEAKNESS;
    }
}

package com.voxelgame.world.item;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.World;

/**
 * Công cụ Bật lửa ({@link Item#FLINT_AND_STEEL}): ghi đè hành vi Lượt 1 {@link #onInteractMob}
 * để đốt cháy bất kỳ {@link MobEntity} nào trong 8 giây trước các tương tác đặc thù của từng loài.
 */
public final class FlintAndSteelItem extends ToolItem {

    /** Thời lượng đốt cháy mob khi châm lửa bằng Flint and Steel (giây). */
    public static final float IGNITE_DURATION_SECONDS = 8.0f;

    /** Khởi tạo vật phẩm Bật lửa. */
    FlintAndSteelItem(int id, String displayName, int maxStackSize, String textureName,
                      int atlasTileIndex, int fallbackRgb) {
        super(id, displayName, maxStackSize, textureName, atlasTileIndex, fallbackRgb);
    }

    /** Lượt 1 điều phối tương tác mob: đốt cháy mọi mob còn sống trong 8 giây và phát âm thanh đánh lửa. */
    @Override
    public boolean onInteractMob(World world, Player player, MobEntity target) {
        if (target == null || !target.isAlive() || player == null || !player.isAlive()) {
            return false;
        }
        target.ignite(IGNITE_DURATION_SECONDS);
        AudioManager audio = world != null ? world.getAudio() : null;
        if (audio != null) {
            audio.playEffect(AudioManager.Effect.CLICK, 0.45f);
        }
        return true;
    }
}

package com.voxelgame.world.item;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.world.entity.player.Hotbar;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.World;

/**
 * Vật phẩm thức ăn đóng gói trực tiếp {@link FoodRegistry.FoodSpec} (nguồn chân lý duy nhất cho 19 món ăn).
 */
public final class FoodItem extends ConsumableItem {

    /** Thông số dinh dưỡng và hiệu ứng phụ bất biến của món ăn. */
    private final FoodRegistry.FoodSpec foodSpec;

    /** Khởi tạo món ăn kèm thông số dinh dưỡng và hiệu ứng phụ chuẩn Minecraft. */
    FoodItem(int id, String displayName, int maxStackSize, String textureName,
             int atlasTileIndex, int fallbackRgb, FoodRegistry.FoodSpec foodSpec) {
        super(id, displayName, maxStackSize, textureName, atlasTileIndex, fallbackRgb);
        this.foodSpec = foodSpec;
    }

    /** Trả về thông số dinh dưỡng và hiệu ứng phụ của món ăn. */
    public FoodRegistry.FoodSpec getFoodSpec() {
        return foodSpec;
    }

    @Override
    public UseAction getUseAction() {
        return UseAction.EAT;
    }

    /** Chỉ cho phép bắt đầu ăn khi thanh đói chưa đầy. */
    @Override
    public boolean canStartContinuousUse(World world, Player player) {
        return player != null && player.getHunger() < player.getMaxHunger();
    }

    @Override
    public AudioManager.Effect getConsumeTickSound() {
        return AudioManager.Effect.EAT;
    }

    @Override
    public AudioManager.Effect getConsumeFinishSound() {
        return AudioManager.Effect.BURP;
    }

    /** Áp dụng hồi đói, độ bão hòa và hiệu ứng phụ (nếu có), sau đó trừ 1 đơn vị trên Hotbar. */
    @Override
    protected void applyConsumeEffect(World world, Player player) {
        if (player == null) {
            return;
        }
        Hotbar hotbar = player.getHotbar();
        if (player.consumeFood(this) && hotbar != null && player.getGameMode().consumesItems()) {
            hotbar.consumeSelectedItemStack();
        }
    }
}

package com.voxelgame.world.item;

import com.voxelgame.world.effect.StatusEffectType;

import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Map;

/**
 * Bảng tra cứu bất biến cho toàn bộ 19 loại thức ăn chuẩn Minecraft 1.21.11.
 * Dữ liệu được đồng bộ tự động từ chính các thực thể {@link FoodItem} đăng ký trong {@link Item}
 * (nguồn chân lý duy nhất, zero-GC khi tra cứu O(1)).
 */
public final class FoodRegistry {

    /**
     * Thông số dinh dưỡng và hiệu ứng phụ có thể kích hoạt khi ăn xong một món ăn.
     *
     * @param nutrition       điểm đói hồi phục (1..20)
     * @param saturation      điểm bão hòa cộng thêm (bị chặn tối đa bằng hunger sau khi ăn)
     * @param effect          hiệu ứng trạng thái phụ (null nếu không có)
     * @param durationSeconds thời lượng hiệu ứng phụ tính bằng giây
     * @param amplifier       cấp hiệu ứng phụ (0 = cấp I)
     * @param effectChance    xác suất kích hoạt hiệu ứng phụ trong [0, 1]
     */
    public record FoodSpec(
            int nutrition,
            float saturation,
            StatusEffectType effect,
            float durationSeconds,
            int amplifier,
            float effectChance
    ) {
    }

    /** Bảng ánh xạ tĩnh từ Item sang FoodSpec, tự động thu thập từ các {@link FoodItem} trong {@link Item}. */
    private static final Map<Item, FoodSpec> FOODS;

    static {
        IdentityHashMap<Item, FoodSpec> map = new IdentityHashMap<>(24);
        for (Item item : Item.allStandaloneItems()) {
            if (item instanceof FoodItem foodItem) {
                map.put(foodItem, foodItem.getFoodSpec());
            }
        }
        FOODS = Collections.unmodifiableMap(map);
    }

    /** Ngăn khởi tạo thể hiện của lớp tiện ích tĩnh. */
    private FoodRegistry() {
    }

    /**
     * Tra cứu thông số thức ăn của một {@link Item}.
     *
     * @param item vật phẩm cần kiểm tra
     * @return {@link FoodSpec} tương ứng, hoặc {@code null} nếu không thuộc 19 món ăn
     */
    public static FoodSpec of(Item item) {
        if (item == null) {
            return null;
        }
        if (item instanceof FoodItem foodItem) {
            return foodItem.getFoodSpec();
        }
        return FOODS.get(item);
    }

    /** Kiểm tra nhanh một vật phẩm có nằm trong 19 món ăn được hỗ trợ hay không. */
    public static boolean isFood(Item item) {
        return item instanceof FoodItem;
    }

    /** Trả về tổng số món ăn đã đăng ký trong bảng. */
    public static int count() {
        return FOODS.size();
    }
}

