package com.voxelgame.world.level;

import com.badlogic.gdx.utils.IntArray;
import com.badlogic.gdx.utils.IntSet;

/** Hàng đợi FIFO tọa độ voxel, dùng lại bộ đệm và gộp các ô còn đang chờ. */
final class BlockUpdateQueue {
    private final IntArray entries = new IntArray(64);
    private final IntSet pending = new IntSet(64);
    private int head;

    /** Chỉ thêm tọa độ hợp lệ chưa có trong phần hàng đợi đang chờ. */
    void add(int x, int y, int z) {
        if (x >= 0 && x < World.WORLD_SIZE_X && y >= 0 && y < World.WORLD_SIZE_Y
                && z >= 0 && z < World.WORLD_SIZE_Z) {
            int packed = (x << 19) | (z << 8) | y;
            if (pending.add(packed)) {
                entries.add(packed);
            }
        }
    }

    /** Báo còn ô cần cập nhật. */
    boolean hasNext() {
        return head < entries.size;
    }

    /** Bỏ cờ đang chờ để ô được xét lại nếu một luật vừa thay đổi hàng xóm. */
    int next() {
        int packed = entries.get(head++);
        pending.remove(packed);
        return packed;
    }

    /** Giữ dung lượng đã cấp khi kết thúc lô cập nhật. */
    void clear() {
        head = 0;
        entries.clear();
        pending.clear();
    }
}

package com.voxelgame.world.level;

import com.voxelgame.client.render.ShaderProgram;
import com.voxelgame.client.render.Texture;
import com.voxelgame.world.level.biome.BiomeTint;
import com.voxelgame.world.level.block.Block.Face;
import com.voxelgame.world.level.block.Block.GeometryType;
import com.voxelgame.world.level.block.Block.RenderLayer;
import com.voxelgame.world.level.block.Block;

import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Mesh;
import com.badlogic.gdx.graphics.VertexAttribute;
import com.badlogic.gdx.graphics.VertexAttributes;
import com.badlogic.gdx.graphics.VertexAttributes.Usage;
import com.badlogic.gdx.math.Frustum;
import com.badlogic.gdx.math.Plane;
import com.badlogic.gdx.math.Vector3;
import com.badlogic.gdx.utils.Disposable;
import com.badlogic.gdx.utils.FloatArray;
import java.util.Arrays;

/** Lưu block trong ô lưới 16³, dựng hình học và sở hữu hai mesh của vùng. */
public class Chunk implements Disposable {
    // Số ô theo mỗi trục và bán kích thước hộp bao của chunk.
    public static final int SIZE = 16;
    private static final float HALF_SIZE = SIZE / 2.0f;

    // Thứ tự thuộc tính mỗi đỉnh: x, y, z, u, v, hệ số ánh sáng, màu đỉnh đóng gói
    // (aColor).
    public static final int FLOATS_PER_VERTEX = 7;
    /** Vị trí offset của thuộc tính {@code aShade} trong một đỉnh. */
    static final int SHADE_OFFSET = 5;
    /** Vị trí offset của thuộc tính {@code aColor} đóng gói trong một đỉnh. */
    static final int COLOR_OFFSET = 6;
    private static final VertexAttributes VERTEX_ATTRIBUTES = new VertexAttributes(
            new VertexAttribute(Usage.Position, 3, "aPos"),
            new VertexAttribute(Usage.TextureCoordinates, 2, "aTexCoord"),
            new VertexAttribute(Usage.Generic, 1, "aShade"),
            new VertexAttribute(Usage.ColorPacked, 4, "aColor"));

    // Tọa độ UV và giá trị enum được tính một lần cho tất cả lần dựng.
    private static final float[][] TILE_UVS = createTileUvs();
    private static final Face[] FACES = Face.values();
    /** Giới hạn của chỉ số đỉnh 16 bit mà Mesh libGDX gửi lên GPU. */
    private static final int MAX_INDEXED_QUADS = 65_536 / 4;
    private static final short[] QUAD_INDICES = createQuadIndices();

    // Hệ số độ sáng theo hướng mặt.
    private static final float SHADE_TOP = 1.0f;
    private static final float SHADE_BOTTOM = 0.55f;
    private static final float SHADE_NORTH_SOUTH = 0.85f;
    private static final float SHADE_EAST_WEST = 0.72f;
    /** Mức giảm độ sáng ở mỗi bậc che góc và độ che một phần của lá khoét alpha. */
    private static final float AO_STEP = 0.17f;
    private static final float LEAF_OCCLUSION = 0.5f;
    /**
     * Ánh sáng mặc định 4-bit đóng gói: Sky Light = 15 (nibble cao), Block Light =
     * 0 (nibble thấp).
     */
    static final byte DEFAULT_LIGHT = (byte) 0xF0;

    // Tọa độ góc nhỏ nhất của chunk trong thế giới.
    private final int baseWorldX;
    private final int baseWorldY;
    private final int baseWorldZ;

    // Mỗi ID chiếm một byte. Mảng metadata và light chỉ xuất hiện khi có dữ liệu
    // khác mặc định.
    private final byte[] blocks = new byte[SIZE * SIZE * SIZE];
    private byte[] metadata;
    private byte defaultLight = DEFAULT_LIGHT;
    private byte[] light;
    private int blockCount;

    private Mesh opaqueMesh;
    private Mesh translucentMesh;
    private boolean dirty = true;

    // Bộ đệm RGB dùng lại khi tính màu biome trong buildVertices để tránh cấp phát
    // rác GC.
    private final float[] biomeTintBuffer = new float[3];

    // Khung hình gần nhất mà hộp bao chunk giao khung nhìn.
    long lastVisibleFrame;

    /** Tính trước tọa độ dùng để dựng mesh và kiểm tra khung nhìn. */
    public Chunk(int chunkX, int chunkY, int chunkZ) {
        baseWorldX = chunkX * SIZE;
        baseWorldY = chunkY * SIZE;
        baseWorldZ = chunkZ * SIZE;
    }

    /** Tính chỉ số mảng phẳng với trục Z liên tiếp trong bộ nhớ. */
    private static int blockIndex(int x, int y, int z) {
        return (x * SIZE + y) * SIZE + z;
    }

    /** Kiểm tra tọa độ cục bộ trước khi đọc dữ liệu, kể cả ở mép bản đồ. */
    private static boolean contains(int x, int y, int z) {
        return x >= 0 && x < SIZE && y >= 0 && y < SIZE && z >= 0 && z < SIZE;
    }

    /** Chuẩn bị bảng UV từ công thức atlas dùng chung của các loại block. */
    private static float[][] createTileUvs() {
        float[][] tileUvs = new float[Texture.ATLAS_COLS * Texture.ATLAS_ROWS][];
        for (int tile = 0; tile < tileUvs.length; tile++) {
            tileUvs[tile] = Block.getTileUV(tile);
        }
        return tileUvs;
    }

    /** Lấy UV dùng chung để đọc, tránh cấp phát khi vẽ biểu tượng Hotbar. */
    public static float[] tileUv(int tile) {
        return TILE_UVS[tile];
    }

    /** Đọc ID khối, trả Air cho tọa độ nằm ngoài chunk. */
    byte getBlockLocal(int x, int y, int z) {
        return contains(x, y, z) ? blocks[blockIndex(x, y, z)] : Block.AIR.getId();
    }

    /** Đọc metadata dạng không dấu. Ô chưa từng lưu trạng thái trả 0. */
    int getStateLocal(int x, int y, int z) {
        return metadata != null && contains(x, y, z)
                ? Byte.toUnsignedInt(metadata[blockIndex(x, y, z)])
                : 0;
    }

    /** Đọc Sky Light cục bộ (0..15) từ nibble cao của byte ánh sáng. */
    int getSkyLightLocal(int x, int y, int z) {
        if (!contains(x, y, z)) {
            return ChunkLighting.MAX_LIGHT;
        }
        int packed = light != null
                ? Byte.toUnsignedInt(light[blockIndex(x, y, z)])
                : Byte.toUnsignedInt(defaultLight);
        return packed >>> 4;
    }

    /** Đọc Block Light cục bộ (0..15) từ nibble thấp của byte ánh sáng. */
    int getBlockLightLocal(int x, int y, int z) {
        if (!contains(x, y, z)) {
            return 0;
        }
        int packed = light != null
                ? Byte.toUnsignedInt(light[blockIndex(x, y, z)])
                : Byte.toUnsignedInt(defaultLight);
        return packed & 0x0F;
    }

    /**
     * Ghi Sky Light cục bộ (0..15), cấp phát lười mảng byte[4096] khi khác mặc
     * định.
     */
    boolean setSkyLightLocal(int x, int y, int z, int level) {
        if (!contains(x, y, z)) {
            return false;
        }
        int clamped = Math.max(0, Math.min(ChunkLighting.MAX_LIGHT, level));
        int index = blockIndex(x, y, z);
        int current = light != null ? Byte.toUnsignedInt(light[index]) : Byte.toUnsignedInt(defaultLight);
        if ((current >>> 4) == clamped) {
            return false;
        }
        if (light == null) {
            light = new byte[SIZE * SIZE * SIZE];
            Arrays.fill(light, defaultLight);
        }
        light[index] = (byte) ((clamped << 4) | (current & 0x0F));
        return true;
    }

    /**
     * Ghi Block Light cục bộ (0..15), cấp phát lười mảng byte[4096] khi khác mặc
     * định.
     */
    boolean setBlockLightLocal(int x, int y, int z, int level) {
        if (!contains(x, y, z)) {
            return false;
        }
        int clamped = Math.max(0, Math.min(ChunkLighting.MAX_LIGHT, level));
        int index = blockIndex(x, y, z);
        int current = light != null ? Byte.toUnsignedInt(light[index]) : Byte.toUnsignedInt(defaultLight);
        if ((current & 0x0F) == clamped) {
            return false;
        }
        if (light == null) {
            light = new byte[SIZE * SIZE * SIZE];
            Arrays.fill(light, defaultLight);
        }
        light[index] = (byte) ((current & 0xF0) | clamped);
        return true;
    }

    /**
     * Đặt ánh sáng đồng nhất cho cả chunk để giữ `light = null` (tiết kiệm RAM ở
     * vùng đồng nhất).
     */
    void setUniformLight(byte packedLight) {
        defaultLight = packedLight;
        light = null;
    }

    /** Nạp mảng ánh sáng 4096 byte đã tính sẵn từ bộ đệm cột của ChunkLighting. */
    void applyLightArray(byte[] source) {
        if (light == null) {
            light = new byte[SIZE * SIZE * SIZE];
        }
        System.arraycopy(source, 0, light, 0, light.length);
    }

    /**
     * Kiểm tra chunk có lưu dữ liệu ánh sáng khác mặc định (sky=15, block=0) hay
     * không.
     */
    boolean hasNonDefaultLight() {
        if (light == null) {
            return defaultLight != DEFAULT_LIGHT;
        }
        for (byte value : light) {
            if (value != DEFAULT_LIGHT) {
                return true;
            }
        }
        return false;
    }

    /** Ghi ID với trạng thái mặc định, đồng thời loại bỏ metadata của ô cũ. */
    boolean setBlockLocal(int x, int y, int z, byte blockId) {
        return setBlockLocal(x, y, z, blockId, 0);
    }

    /**
     * Ghi ID và trạng thái cùng lúc. ID hoặc metadata thay đổi đều làm bẩn mesh.
     */
    boolean setBlockLocal(int x, int y, int z, byte blockId, int state) {
        int index = blockIndex(x, y, z);
        byte previous = blocks[index];
        byte nextState = blockId == 0 ? 0 : (byte) state;
        byte previousState = metadata == null ? 0 : metadata[index];
        if (previous == blockId && previousState == nextState) {
            return false;
        }
        if (nextState != 0 && metadata == null) {
            metadata = new byte[blocks.length];
        }
        if (metadata != null) {
            metadata[index] = nextState;
        }
        if (previous == 0) {
            blockCount++;
        } else if (blockId == 0) {
            blockCount--;
        }
        blocks[index] = blockId;
        dirty = true;
        return true;
    }

    /**
     * Ghi dải địa tầng khác Air trong một cột đã được World cắt theo biên chunk.
     */
    void fillGeneratedColumnSegment(int x, int z, int firstY, int endY, byte blockId) {
        int position = blockIndex(x, firstY, z);
        for (int y = firstY; y < endY; y++, position += SIZE) {
            if (blocks[position] == 0) {
                blockCount++;
            }
            blocks[position] = blockId;
            if (metadata != null) {
                metadata[position] = 0;
            }
        }
        dirty = true;
    }

    /** Kiểm tra chunk chỉ còn không khí. */
    boolean isEmpty() {
        return blockCount == 0;
    }

    /** Với mỗi mặt phẳng, thử đúng góc hộp xa nhất về phía trong của khung nhìn. */
    boolean intersectsFrustum(Frustum frustum) {
        for (Plane plane : frustum.planes) {
            Vector3 normal = plane.normal;
            int x = normal.x >= 0f ? baseWorldX + SIZE : baseWorldX;
            int y = normal.y >= 0f ? baseWorldY + SIZE : baseWorldY;
            int z = normal.z >= 0f ? baseWorldZ + SIZE : baseWorldZ;
            if (plane.testPoint(x, y, z) == Plane.PlaneSide.Back) {
                return false;
            }
        }
        return true;
    }

    /** Tính khoảng cách bình phương đến hộp bao để ưu tiên dựng các chunk gần. */
    float distanceSquaredTo(Vector3 point) {
        float dx = Math.max(0, Math.max(baseWorldX - point.x, point.x - (baseWorldX + SIZE)));
        float dy = Math.max(0, Math.max(baseWorldY - point.y, point.y - (baseWorldY + SIZE)));
        float dz = Math.max(0, Math.max(baseWorldZ - point.z, point.z - (baseWorldZ + SIZE)));
        return dx * dx + dy * dy + dz * dz;
    }

    /** Tính khoảng cách bình phương đến tâm chunk cho thứ tự vẽ pha trong suốt. */
    float centerDistanceSquaredTo(Vector3 point) {
        float dx = baseWorldX + HALF_SIZE - point.x;
        float dy = baseWorldY + HALF_SIZE - point.y;
        float dz = baseWorldZ + HALF_SIZE - point.z;
        return dx * dx + dy * dy + dz * dz;
    }

    /** Kiểm tra bộ đệm mesh của ít nhất một pha kết xuất đang tồn tại. */
    boolean hasMesh() {
        return opaqueMesh != null || translucentMesh != null;
    }

    /** Kiểm tra chunk có hình học ghi chiều sâu trong lượt đầu. */
    boolean hasOpaqueMesh() {
        return opaqueMesh != null;
    }

    /** Kiểm tra chunk có đỉnh để vẽ trong pha hòa màu. */
    boolean hasTranslucentMesh() {
        return translucentMesh != null;
    }

    /** Thu hồi cả hai mesh và cho phép dựng lại khi chunk quay vào tầm nhìn. */
    void releaseCachedMesh() {
        dispose();
        markDirty();
    }

    /** Báo dữ liệu block đã thay đổi kể từ lần dựng gần nhất. */
    boolean isDirty() {
        return dirty;
    }

    /**
     * Đánh dấu cần dựng lại khi hình học hoặc ánh sáng phụ thuộc chunk bên cạnh
     * thay đổi.
     */
    void markDirty() {
        dirty = true;
    }

    /**
     * Dựng lại hai mesh từ các bộ đệm số thực được thế giới dùng lại giữa các
     * chunk.
     */
    void rebuildMesh(World world, FloatArray opaqueVertices, FloatArray translucentVertices) {
        buildVertices(world, opaqueVertices, translucentVertices);
        opaqueMesh = uploadMesh(opaqueMesh, opaqueVertices);
        translucentMesh = uploadMesh(translucentMesh, translucentVertices);
        dirty = false;
    }

    /** Tính các mặt lộ ra của khối và ghi đỉnh vào đúng pha kết xuất. */
    void buildVertices(World world, FloatArray opaqueVertices, FloatArray translucentVertices) {
        opaqueVertices.clear();
        translucentVertices.clear();

        int index = 0;
        for (int x = 0; x < SIZE; x++) {
            for (int y = 0; y < SIZE; y++) {
                for (int z = 0; z < SIZE; z++, index++) {
                    byte id = blocks[index];
                    if (id == 0) {
                        continue;
                    }
                    Block block = Block.fromId(id);
                    if (block == Block.AIR) {
                        continue;
                    }

                    int wx = baseWorldX + x;
                    int wy = baseWorldY + y;
                    int wz = baseWorldZ + z;
                    int state = metadata == null ? 0 : Byte.toUnsignedInt(metadata[index]);
                    Block above = Block.fromId(world.getBlock(wx, wy + 1, wz));
                    FloatArray vertices = block.getRenderLayer() == RenderLayer.TRANSLUCENT
                            ? translucentVertices
                            : opaqueVertices;
                    if (block.getGeometryType() == GeometryType.CROSS_PLANT) {
                        float[] uv = tileUv(block.getTileIndex(Face.SOUTH, state, above));
                        float plantLight = computeLightFactor(world, wx, wy, wz);
                        float plantColor = BiomeTint.WHITE_PACKED_COLOR;
                        if (block == Block.SHORT_GRASS || block == Block.TALL_GRASS) {
                            BiomeTint.grassMultiplier(world, wx, wz, biomeTintBuffer);
                            plantColor = BiomeTint.packMultiplier(biomeTintBuffer);
                        }
                        addCross(vertices, wx, wy, wz, block.getSelectionBounds(state), uv, plantLight, plantColor);
                    } else {
                        int firstVertex = vertices.size;
                        addBox(world, vertices, block, state, above, wx, wy, wz, biomeTintBuffer);
                        // Dùng dấu của hệ số mặt để đánh dấu phát sáng mà không tăng kích thước đỉnh.
                        if (block == Block.LAVA) {
                            for (int shade = firstVertex
                                    + SHADE_OFFSET; shade < vertices.size; shade += FLOATS_PER_VERTEX) {
                                vertices.items[shade] = -vertices.items[shade];
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Cập nhật bộ đệm hiện có hoặc thay bằng mesh lớn hơn khi số đỉnh vượt dung
     * lượng.
     */
    private static Mesh uploadMesh(Mesh current, FloatArray vertices) {
        if (vertices.size == 0) {
            if (current != null) {
                current.dispose();
            }
            return null;
        }

        int quads = vertices.size / (6 * FLOATS_PER_VERTEX);
        boolean indexed = quads <= MAX_INDEXED_QUADS;
        int indexCount = indexed ? quads * 6 : 0;
        if (indexed) {
            compactQuads(vertices, quads);
        }
        int vertexCount = vertices.size / FLOATS_PER_VERTEX;
        if (current != null && current.getMaxVertices() >= vertexCount
                && (current.getMaxIndices() > 0) == indexed && current.getMaxIndices() >= indexCount) {
            uploadVertices(current, vertices, indexCount);
            return current;
        }

        Mesh replacement = new Mesh(true, vertexCount, indexCount, VERTEX_ATTRIBUTES);
        try {
            uploadVertices(replacement, vertices, indexCount);
        } catch (RuntimeException | Error failure) {
            replacement.dispose();
            throw failure;
        }
        if (current != null) {
            current.dispose();
        }
        return replacement;
    }

    /**
     * Ưu tiên bốn đỉnh mỗi mặt để giảm kích thước tải và công việc của vertex
     * shader.
     */
    static void compactQuads(FloatArray vertices, int quads) {
        for (int quad = 0; quad < quads; quad++) {
            int from = quad * 6 * FLOATS_PER_VERTEX;
            int to = quad * 4 * FLOATS_PER_VERTEX;
            System.arraycopy(vertices.items, from, vertices.items, to, 3 * FLOATS_PER_VERTEX);
            System.arraycopy(vertices.items, from + 5 * FLOATS_PER_VERTEX,
                    vertices.items, to + 3 * FLOATS_PER_VERTEX, FLOATS_PER_VERTEX);
        }
        vertices.size = quads * 4 * FLOATS_PER_VERTEX;
    }

    /** Dùng lại dãy hai tam giác 0–1–2, 0–2–3 cho tất cả các mesh có chỉ số. */
    private static short[] createQuadIndices() {
        short[] indices = new short[MAX_INDEXED_QUADS * 6];
        for (int quad = 0; quad < MAX_INDEXED_QUADS; quad++) {
            int vertex = quad * 4;
            int index = quad * 6;
            indices[index] = (short) vertex;
            indices[index + 1] = (short) (vertex + 1);
            indices[index + 2] = (short) (vertex + 2);
            indices[index + 3] = (short) vertex;
            indices[index + 4] = (short) (vertex + 2);
            indices[index + 5] = (short) (vertex + 3);
        }
        return indices;
    }

    /** Cập nhật chỉ số khi số mặt thay đổi và tải phần đỉnh có dữ liệu. */
    private static void uploadVertices(Mesh mesh, FloatArray vertices, int indexCount) {
        mesh.setVertices(vertices.items, 0, vertices.size);
        if (indexCount != 0 && mesh.getNumIndices() != indexCount) {
            mesh.setIndices(QUAD_INDICES, 0, indexCount);
        }
    }

    /** Vẽ chung các mặt đục và mặt khoét alpha trong pha ghi độ sâu. */
    void render(ShaderProgram shader) {
        renderMesh(opaqueMesh, shader);
    }

    /** Vẽ nước và băng trong pha hòa màu do World điều phối. */
    void renderTranslucent(ShaderProgram shader) {
        renderMesh(translucentMesh, shader);
    }

    /** Gửi các tam giác đã tải của một mesh sang shader. */
    private static void renderMesh(Mesh mesh, ShaderProgram shader) {
        if (mesh != null) {
            int indices = mesh.getNumIndices();
            mesh.render(shader.getGdxShader(), GL20.GL_TRIANGLES, 0,
                    indices == 0 ? mesh.getNumVertices() : indices);
        }
    }

    /** Giải phóng cả hai bộ đệm libGDX và cho phép gọi lại khi đã thu hồi. */
    @Override
    public void dispose() {
        if (opaqueMesh != null) {
            opaqueMesh.dispose();
            opaqueMesh = null;
        }
        if (translucentMesh != null) {
            translucentMesh.dispose();
            translucentMesh = null;
        }
    }

    /**
     * Dựng tối đa sáu mặt cho hình hộp, cắt phần bên cạnh đã bị phủ kín và áp dụng
     * nhuộm biome phù hợp.
     */
    private static void addBox(World world, FloatArray v, Block block, int state, Block above,
            int x, int y, int z, float[] tintRgb) {
        float inset = horizontalInset(block);
        float height = renderHeight(world, block, state, x, y, z);
        float leavesColor = BiomeTint.WHITE_PACKED_COLOR;
        if (block == Block.OAK_LEAVES) {
            BiomeTint.foliageMultiplier(world, x, z, tintRgb);
            leavesColor = BiomeTint.packMultiplier(tintRgb);
        }
        for (Face face : FACES) {
            int first = v.size;
            int nx = x + (face == Face.EAST ? 1 : face == Face.WEST ? -1 : 0);
            int ny = y + (face == Face.TOP ? 1 : face == Face.BOTTOM ? -1 : 0);
            int nz = z + (face == Face.SOUTH ? 1 : face == Face.NORTH ? -1 : 0);
            Block neighbor = face == Face.TOP ? above : Block.fromId(world.getBlock(nx, ny, nz));

            // Dung nham giữ quy tắc cũ: chỉ vẽ những mặt giáp không khí.
            if (block == Block.LAVA && neighbor != Block.AIR) {
                continue;
            }
            boolean covers = canCover(block, neighbor);
            if (face == Face.TOP || face == Face.BOTTOM) {
                float coverInset = 0.5f;
                if (covers && (face == Face.TOP ? height == 1.0f
                        : neighborHeight(world, neighbor, nx, ny, nz) == 1.0f)) {
                    coverInset = horizontalInset(neighbor);
                }
                if (coverInset > inset) {
                    int tile = block.getTileIndex(face, state, above);
                    float faceColor = leavesColor;
                    if (block == Block.GRASS && face == Face.TOP && tile == Texture.TILE_GRASS_TOP) {
                        BiomeTint.grassMultiplier(world, x, z, tintRgb);
                        faceColor = BiomeTint.packMultiplier(tintRgb);
                    }
                    float[] uv = tileUv(tile);
                    addHorizontalFace(v, face, x, face == Face.TOP ? y + height : y, z,
                            inset, coverInset, uv, faceColor);
                }
            } else {
                // Chỉ hai hình chạm đến ranh giới ô mới có thể che thành bên của nhau.
                float visibleFrom = 0.0f;
                if (covers && inset == 0.0f && horizontalInset(neighbor) == 0.0f) {
                    visibleFrom = neighborHeight(world, neighbor, nx, ny, nz);
                }
                if (visibleFrom < height) {
                    float[] uv = tileUv(block.getTileIndex(face, state, above));
                    // Mặt bên GRASS có phần đất bên dưới nên giữ trắng 0xFFFFFFFF để không nhuộm
                    // sai màu đất.
                    addSideFace(v, face, x, y, z, inset, visibleFrom, height, uv, leavesColor);
                }
            }
            if (v.size != first && block != Block.LAVA) {
                // Với mặt trên thấp, các góc nhìn vào lớp ô ngang mặt thay vì lớp cao hơn.
                int sampleY = face == Face.TOP && height < 1.0f ? y : ny;
                shadeFace(world, v, first, face, x, y, z, nx, sampleY, nz);
            }
        }
    }

    /**
     * Kết hợp ánh sáng bầu trời / ánh sáng khối theo công thức
     * {@code max(skyLight/15f * skyFactor, blockLight/15f)} với sàn tối thiểu
     * 0.04f.
     */
    private static float computeLightFactor(World world, int x, int y, int z) {
        int sky = world.getSkyLight(x, y, z);
        int blockLight = world.getBlockLight(x, y, z);
        float skyFactor = world.getSkyLightFactor();
        float combined = Math.max((sky / 15.0f) * skyFactor, blockLight / 15.0f);
        return Math.max(ChunkLighting.MIN_LIGHT_LEVEL, combined);
    }

    /**
     * Lấy độ che ở bốn góc của mặt và nhân thêm cường độ Sky/Block Light lên đỉnh.
     */
    private static void shadeFace(World world, FloatArray vertices, int first, Face face,
            int x, int y, int z, int sampleX, int sampleY, int sampleZ) {
        // Nếu ô lấy mẫu bị khối đục chiếm (ví dụ mặt cạnh Cactus sát tường), đọc ánh
        // sáng ngay trong ô khối.
        boolean sampleOpaque = Block.fromId(world.getBlock(sampleX, sampleY, sampleZ)).isOpaque();
        float lightFactor = sampleOpaque
                ? computeLightFactor(world, x, y, z)
                : computeLightFactor(world, sampleX, sampleY, sampleZ);

        boolean alongZ = face == Face.EAST || face == Face.WEST;
        boolean horizontal = face == Face.TOP || face == Face.BOTTOM;
        int ux = alongZ ? 0 : 1;
        int uz = alongZ ? 1 : 0;
        int vy = horizontal ? 0 : 1;
        int vz = horizontal ? 1 : 0;
        float sideU0 = occlusionAt(world, sampleX - ux, sampleY, sampleZ - uz);
        float sideU1 = occlusionAt(world, sampleX + ux, sampleY, sampleZ + uz);
        float sideV0 = occlusionAt(world, sampleX, sampleY - vy, sampleZ - vz);
        float sideV1 = occlusionAt(world, sampleX, sampleY + vy, sampleZ + vz);
        float light00 = cornerLight(sideU0, sideV0, occlusionAt(world, sampleX - ux, sampleY - vy, sampleZ - uz - vz));
        float light01 = cornerLight(sideU0, sideV1, occlusionAt(world, sampleX - ux, sampleY + vy, sampleZ - uz + vz));
        float light10 = cornerLight(sideU1, sideV0, occlusionAt(world, sampleX + ux, sampleY - vy, sampleZ + uz - vz));
        float light11 = cornerLight(sideU1, sideV1, occlusionAt(world, sampleX + ux, sampleY + vy, sampleZ + uz + vz));
        boolean noAo = light00 == 1.0f && light01 == 1.0f && light10 == 1.0f && light11 == 1.0f;
        if (noAo && lightFactor == 1.0f) {
            return;
        }

        int axisU = alongZ ? 2 : 0;
        int axisV = horizontal ? 2 : 1;
        int originU = alongZ ? z : x;
        int originV = horizontal ? z : y;
        float[] items = vertices.items;
        for (int quad = first; quad < vertices.size; quad += 6 * FLOATS_PER_VERTEX) {
            if (noAo) {
                for (int i = quad; i < quad + 6 * FLOATS_PER_VERTEX; i += FLOATS_PER_VERTEX) {
                    items[i + SHADE_OFFSET] *= lightFactor;
                }
            } else {
                for (int i = quad; i < quad + 6 * FLOATS_PER_VERTEX; i += FLOATS_PER_VERTEX) {
                    float u = items[i + axisU] - originU;
                    float v = items[i + axisV] - originV;
                    items[i + SHADE_OFFSET] *= lightFactor
                            * lerp(lerp(light00, light10, u), lerp(light01, light11, u), v);
                }
                rotateIfDarkerDiagonal(items, quad);
            }
        }
    }

    /**
     * Đọc ô từ thế giới để tính che khuất cả qua mặt, cạnh và đỉnh chung của chunk.
     */
    private static float occlusionAt(World world, int x, int y, int z) {
        Block block = Block.fromId(world.getBlock(x, y, z));
        if (block.isOpaque() || (block == Block.SNOW_LAYER && world.getBlockState(x, y, z) == 7)) {
            return 1.0f;
        }
        return block == Block.OAK_LEAVES || block == Block.SPRUCE_LEAVES ? LEAF_OCCLUSION : 0.0f;
    }

    /** Hai ô đặc cạnh nhau che trọn góc, bất kể có thêm khối chéo. */
    private static float cornerLight(float sideU, float sideV, float diagonal) {
        float covered = sideU == 1.0f && sideV == 1.0f ? 3.0f : sideU + sideV + diagonal;
        return 1.0f - AO_STEP * covered;
    }

    /** Chọn đường chéo tối hơn và giữ mẫu hai tam giác 0–1–2, 0–2–3 sau khi nén. */
    private static void rotateIfDarkerDiagonal(float[] items, int first) {
        int vertex = FLOATS_PER_VERTEX;
        int shade = first + SHADE_OFFSET;
        if (items[shade] + items[shade + 2 * vertex] <= items[shade + vertex] + items[shade + 5 * vertex]) {
            return;
        }

        // Đổi A B C A C D thành B C D B D A, dùng hai đỉnh trùng làm chỗ lưu tạm.
        System.arraycopy(items, first + 5 * vertex, items, first + 4 * vertex, vertex);
        System.arraycopy(items, first, items, first + 5 * vertex, vertex);
        System.arraycopy(items, first + vertex, items, first + 3 * vertex, vertex);
        System.arraycopy(items, first + 2 * vertex, items, first + vertex, vertex);
        System.arraycopy(items, first + 4 * vertex, items, first + 2 * vertex, vertex);
        System.arraycopy(items, first + 3 * vertex, items, first, vertex);
    }

    /**
     * Lá và cây khoét alpha không che kín mặt kề. Nước hoặc băng che mặt tiếp xúc
     * cùng loại.
     */
    private static boolean canCover(Block current, Block neighbor) {
        if (neighbor == Block.AIR) {
            return false;
        }
        GeometryType shape = neighbor.getGeometryType();
        return neighbor.isOpaque() || shape == GeometryType.SNOW_LAYER || shape == GeometryType.CACTUS
                || (current == neighbor && current.getRenderLayer() == RenderLayer.TRANSLUCENT);
    }

    /** Lấy độ lùi ngang theo hình hộp xương rồng đã dùng cho hộp chọn. */
    private static float horizontalInset(Block block) {
        return block.getGeometryType() == GeometryType.CACTUS ? block.getSelectionBounds(0).minX() : 0.0f;
    }

    /** Đọc trạng thái ô bên chỉ khi chiều cao hình học phụ thuộc số lớp tuyết. */
    private static float neighborHeight(World world, Block block, int x, int y, int z) {
        int state = block.getGeometryType() == GeometryType.SNOW_LAYER ? world.getBlockState(x, y, z) : 0;
        return renderHeight(world, block, state, x, y, z);
    }

    /**
     * Dùng chiều cao hiển thị của khối lỏng và tuyết, các hộp còn lại cao một ô.
     */
    private static float renderHeight(World world, Block block, int state, int x, int y, int z) {
        return switch (block.getGeometryType()) {
            case LIQUID -> block.getTopHeight(world, x, y, z);
            case SNOW_LAYER -> block.getSelectionBounds(state).maxY();
            default -> 1.0f;
        };
    }

    /** Vẽ nguyên mặt ngang hoặc bốn dải viền còn lộ quanh hình hộp hẹp kề bên. */
    private static void addHorizontalFace(FloatArray v, Face face, float x, float y, float z,
            float inset, float coverInset, float[] uv, float color) {
        float edge = 1.0f - inset;
        if (coverInset == 0.5f) {
            addHorizontalRect(v, face, x, y, z, inset, edge, inset, edge, inset, uv, color);
            return;
        }
        float coverEdge = 1.0f - coverInset;
        addHorizontalRect(v, face, x, y, z, inset, coverInset, inset, edge, inset, uv, color);
        addHorizontalRect(v, face, x, y, z, coverEdge, edge, inset, edge, inset, uv, color);
        addHorizontalRect(v, face, x, y, z, coverInset, coverEdge, inset, coverInset, inset, uv, color);
        addHorizontalRect(v, face, x, y, z, coverInset, coverEdge, coverEdge, edge, inset, uv, color);
    }

    /** Quy đổi hình chữ nhật ngang sang tọa độ thế giới và UV của mặt gốc. */
    private static void addHorizontalRect(FloatArray v, Face face, float x, float y, float z,
            float minX, float maxX, float minZ, float maxZ,
            float inset, float[] uv, float color) {
        // Tọa độ UV đã bỏ viền PNG. Quy đổi phần lộ ra theo bề rộng thực của mặt.
        float width = 1.0f - 2.0f * inset;
        float u0 = lerp(uv[0], uv[2], (minX - inset) / width);
        float u1 = lerp(uv[0], uv[2], (maxX - inset) / width);
        float near = (minZ - inset) / width;
        float far = (maxZ - inset) / width;
        if (face == Face.TOP) {
            addQuad(v, x + minX, y, z + maxZ, x + maxX, y, z + maxZ,
                    x + maxX, y, z + minZ, x + minX, y, z + minZ,
                    u0, lerp(uv[1], uv[3], near), u1, lerp(uv[1], uv[3], far), SHADE_TOP, color);
        } else {
            addQuad(v, x + minX, y, z + minZ, x + maxX, y, z + minZ,
                    x + maxX, y, z + maxZ, x + minX, y, z + maxZ,
                    u0, lerp(uv[1], uv[3], 1.0f - far), u1, lerp(uv[1], uv[3], 1.0f - near), SHADE_BOTTOM, color);
        }
    }

    /** Dựng một thành bên từ độ cao bắt đầu thấy cho đến mép trên của khối. */
    private static void addSideFace(FloatArray v, Face face, float x, float y, float z,
            float inset, float visibleFrom, float height, float[] uv, float color) {
        float x0 = x + inset;
        float x1 = x + 1.0f - inset;
        float z0 = z + inset;
        float z1 = z + 1.0f - inset;
        float y0 = y + visibleFrom;
        float y1 = y + height;
        float vBottom = lerp(uv[3], uv[1], visibleFrom / height);
        switch (face) {
            case SOUTH -> addQuad(v, x0, y0, z1, x1, y0, z1, x1, y1, z1, x0, y1, z1,
                    uv[0], uv[1], uv[2], vBottom, SHADE_NORTH_SOUTH, color);
            case NORTH -> addQuad(v, x1, y0, z0, x0, y0, z0, x0, y1, z0, x1, y1, z0,
                    uv[0], uv[1], uv[2], vBottom, SHADE_NORTH_SOUTH, color);
            case EAST -> addQuad(v, x1, y0, z1, x1, y0, z0, x1, y1, z0, x1, y1, z1,
                    uv[0], uv[1], uv[2], vBottom, SHADE_EAST_WEST, color);
            case WEST -> addQuad(v, x0, y0, z0, x0, y0, z1, x0, y1, z1, x0, y1, z0,
                    uv[0], uv[1], uv[2], vBottom, SHADE_EAST_WEST, color);
            default -> throw new IllegalArgumentException("Thành bên cần mặt theo trục ngang");
        }
    }

    /**
     * Tạo hai tấm chéo nằm trong hộp chọn để vùng vẽ và vùng ngắm cùng kích thước.
     */
    private static void addCross(FloatArray v, float x, float y, float z, Block.Bounds bounds, float[] uv,
            float lightFactor, float color) {
        float minX = x + bounds.minX();
        float maxX = x + bounds.maxX();
        float minZ = z + bounds.minZ();
        float maxZ = z + bounds.maxZ();
        float bottom = y + bounds.minY();
        float top = y + bounds.maxY();
        float shade = SHADE_TOP * lightFactor;
        addPlantPlane(v, minX, bottom, minZ, maxX, top, maxZ, uv, shade, color);
        addPlantPlane(v, maxX, bottom, minZ, minX, top, maxZ, uv, shade, color);
    }

    /** Thêm hai mặt quay ngược nhau của một tấm chéo để vẫn dùng culling chung. */
    private static void addPlantPlane(FloatArray v, float x0, float bottom, float z0,
            float x1, float top, float z1, float[] uv, float shade, float color) {
        addQuad(v, x0, bottom, z0, x1, bottom, z1, x1, top, z1, x0, top, z0,
                uv[0], uv[1], uv[2], uv[3], shade, color);
        addQuad(v, x1, bottom, z1, x0, bottom, z0, x0, top, z0, x1, top, z1,
                uv[2], uv[1], uv[0], uv[3], shade, color);
    }

    /** Nội suy UV để phần hình đã bị cắt vẫn giữ đúng tỷ lệ chất liệu gốc. */
    private static float lerp(float from, float to, float fraction) {
        return from + (to - from) * fraction;
    }

    /** Nối bốn góc theo hai tam giác cùng chiều để OpenGL có thể bỏ mặt sau. */
    private static void addQuad(FloatArray v, float ax, float ay, float az, float bx, float by, float bz,
            float cx, float cy, float cz, float dx, float dy, float dz,
            float u0, float v0, float u1, float v1, float shade, float color) {
        putVertex(v, ax, ay, az, u0, v1, shade, color);
        putVertex(v, bx, by, bz, u1, v1, shade, color);
        putVertex(v, cx, cy, cz, u1, v0, shade, color);
        putVertex(v, ax, ay, az, u0, v1, shade, color);
        putVertex(v, cx, cy, cz, u1, v0, shade, color);
        putVertex(v, dx, dy, dz, u0, v0, shade, color);
    }

    /**
     * Ghi một đỉnh theo thứ tự thuộc tính 7 floats của shader chunk (không cấp phát
     * varargs).
     */
    private static void putVertex(FloatArray vertices, float x, float y, float z,
            float u, float v, float shade, float color) {
        vertices.add(x, y, z);
        vertices.add(u, v, shade, color);
    }
}

package com.voxelgame.world.level;

import com.voxelgame.world.level.block.Block;

/**
 * Hệ thống tính toán ánh sáng 4-bit cho thế giới Voxel gồm hai kênh độc lập:
 * <ul>
 *   <li><b>Sky Light (0–15):</b> Ánh sáng bầu trời chiếu thẳng đứng từ đỉnh thế giới xuống,
 *       không suy giảm qua không khí, suy giảm -1 qua lá cây, bị chặn về 0 bởi khối đục
 *       ({@link Block#isOpaque()}), và lan truyền 6 hướng qua BFS.</li>
 *   <li><b>Block Light (0–15):</b> Ánh sáng phát ra từ nguồn sáng khối ({@link Block#LAVA} mức 15),
 *       lan truyền 6 hướng giảm 1 mỗi bước qua các ô không đục.</li>
 * </ul>
 * Thuật toán sử dụng hàng đợi vòng (ring-buffer) mảng nguyên thủy {@code int[]} cấp phát sẵn
 * và bộ đệm cột tái sử dụng để đạt <b>zero-GC</b> trong vòng lặp cập nhật gameplay.
 */
public final class ChunkLighting {

    /** Mức sáng tối đa của mỗi kênh (4-bit: 0..15). */
    public static final int MAX_LIGHT = 15;
    /** Ngưỡng sáng tối thiểu để các mặt trong hang tối vẫn nhìn rõ đường nét khối. */
    public static final float MIN_LIGHT_LEVEL = 0.04f;

    /** Dung lượng khởi tạo của hàng đợi vòng BFS (lũy thừa của 2 để chia lấy dư bằng bitmask). */
    private static final int INITIAL_QUEUE_CAPACITY = 65_536;

    // Hàng đợi vòng dùng chung cho pha lan truyền tăng sáng (Sky và Block chạy nối tiếp nhau).
    private int[] addQueue = new int[INITIAL_QUEUE_CAPACITY];
    private int addHead;
    private int addTail;
    private int addCount;

    // Hàng đợi vòng dùng cho pha xóa sáng khi đặt khối cản sáng hoặc phá nguồn sáng.
    private int[] removePosQueue = new int[INITIAL_QUEUE_CAPACITY];
    private byte[] removeValQueue = new byte[INITIAL_QUEUE_CAPACITY];
    private int removeHead;
    private int removeTail;
    private int removeCount;

    // Bộ đệm tái sử dụng khi quét ánh sáng dọc cho một cột chunk 16x256x16 (zero-GC).
    private final byte[][] columnScratch = new byte[World.WORLD_CHUNKS_Y][Chunk.SIZE * Chunk.SIZE * Chunk.SIZE];
    private final byte[] uniformLightValue = new byte[World.WORLD_CHUNKS_Y];
    private final boolean[] uniformChunkFlags = new boolean[World.WORLD_CHUNKS_Y];

    /** Theo dõi các cột chunk (cx, cz) đã được tính ánh sáng cột + nguồn sáng lân cận. */
    private final boolean[][] columnLit = new boolean[World.WORLD_CHUNKS_X][World.WORLD_CHUNKS_Z];

    /** Trả mức Sky Light (0..15) tại tọa độ thế giới, tự động khởi tạo lười cột chunk nếu cần. */
    public int getSkyLight(World world, int x, int y, int z) {
        if (y >= World.WORLD_SIZE_Y) {
            return MAX_LIGHT;
        }
        if (y < 0) {
            return 0;
        }
        if (x < 0 || x >= World.WORLD_SIZE_X || z < 0 || z >= World.WORLD_SIZE_Z) {
            return MAX_LIGHT;
        }
        ensureColumnLit(world, x / Chunk.SIZE, z / Chunk.SIZE);
        return getSkyLightRaw(world, x, y, z);
    }

    /** Trả mức Block Light (0..15) tại tọa độ thế giới, tự động khởi tạo lười cột chunk nếu cần. */
    public int getBlockLight(World world, int x, int y, int z) {
        if (!world.isInsideWorld(x, y, z)) {
            return 0;
        }
        ensureColumnLit(world, x / Chunk.SIZE, z / Chunk.SIZE);
        return getBlockLightRaw(world, x, y, z);
    }

    /** Ghi mức Sky Light (0..15) tại tọa độ thế giới và đánh dấu bẩn các chunk bị ảnh hưởng. */
    public boolean setSkyLight(World world, int x, int y, int z, int level) {
        if (!world.isInsideWorld(x, y, z)) {
            return false;
        }
        ensureColumnLit(world, x / Chunk.SIZE, z / Chunk.SIZE);
        return setSkyLightRaw(world, x, y, z, clampLight(level));
    }

    /** Ghi mức Block Light (0..15) tại tọa độ thế giới và đánh dấu bẩn các chunk bị ảnh hưởng. */
    public boolean setBlockLight(World world, int x, int y, int z, int level) {
        if (!world.isInsideWorld(x, y, z)) {
            return false;
        }
        ensureColumnLit(world, x / Chunk.SIZE, z / Chunk.SIZE);
        return setBlockLightRaw(world, x, y, z, clampLight(level));
    }

    /**
     * Tính lại Sky Light chiếu thẳng cho cột (wx, wz) từ đỉnh thế giới xuống và lan truyền BFS.
     */
    public void recomputeColumnSkyLight(World world, int wx, int wz) {
        if (!world.isInsideWorld(wx, 0, wz)) {
            return;
        }
        int cx = wx / Chunk.SIZE;
        int cz = wz / Chunk.SIZE;
        ensureColumnLit(world, cx, cz);
        int topCy = highestNonNullChunkY(world, cx, cz);
        if (topCy >= 0) {
            int startY = Math.min(World.WORLD_SIZE_Y - 1, (topCy + 1) * Chunk.SIZE - 1);
            updateSkyColumnAndBfs(world, wx, startY, wz);
        }
    }

    /**
     * Lan truyền lại ánh sáng xung quanh tọa độ thế giới (wx, wy, wz) bằng hàng đợi vòng BFS.
     */
    public void propagateLight(World world, int wx, int wy, int wz) {
        if (!world.isInsideWorld(wx, wy, wz)) {
            return;
        }
        int cx = wx / Chunk.SIZE;
        int cz = wz / Chunk.SIZE;
        ensureColumnLit(world, cx, cz);
        Block block = Block.fromId(world.getBlock(wx, wy, wz));
        int emit = emissionOf(block);
        if (emit > 0) {
            setBlockLightRaw(world, wx, wy, wz, emit);
            pushAdd(wx, wy, wz);
        } else if (!block.isOpaque()) {
            enqueueBrighterBlockNeighbors(world, wx, wy, wz);
        }
        drainBlockIncreaseQueue(world);
        updateSkyColumnAndBfs(world, wx, wy, wz);
    }

    /** Kiểm tra xem cột chunk (cx, cz) đã được khởi tạo dữ liệu ánh sáng hay chưa. */
    boolean isColumnLit(int cx, int cz) {
        return cx >= 0 && cx < World.WORLD_CHUNKS_X
                && cz >= 0 && cz < World.WORLD_CHUNKS_Z
                && columnLit[cx][cz];
    }

    /** Đánh dấu cột chunk cần tính lại ánh sáng khi dữ liệu bị sửa trực tiếp ngoài gameplay. */
    void invalidateColumn(int cx, int cz) {
        if (cx >= 0 && cx < World.WORLD_CHUNKS_X && cz >= 0 && cz < World.WORLD_CHUNKS_Z) {
            columnLit[cx][cz] = false;
        }
    }

    /**
     * Đảm bảo cột chunk (cx, cz) và vành đai 8 cột lân cận (cx±1, cz±1) đã khởi tạo ánh sáng
     * và hoàn tất lan truyền qua biên chunk. Vì tầm lan tối đa là 15 (< 16), vành đai 1 chunk
     * đảm bảo mọi nguồn sáng có thể chạm tới (cx, cz) đều đã hội tụ.
     */
    void ensureColumnLit(World world, int cx, int cz) {
        int minCx = Math.max(0, cx - 1);
        int maxCx = Math.min(World.WORLD_CHUNKS_X - 1, cx + 1);
        int minCz = Math.max(0, cz - 1);
        int maxCz = Math.min(World.WORLD_CHUNKS_Z - 1, cz + 1);

        boolean allLit = true;
        for (int nx = minCx; nx <= maxCx && allLit; nx++) {
            for (int nz = minCz; nz <= maxCz; nz++) {
                if (!columnLit[nx][nz]) {
                    allLit = false;
                    break;
                }
            }
        }
        if (allLit) {
            return;
        }

        // Bitmask 9 bit đánh dấu cột nào trong vùng 3x3 vừa được khởi tạo mới ở lượt này.
        int newlyLitMask = 0;
        for (int nx = minCx; nx <= maxCx; nx++) {
            for (int nz = minCz; nz <= maxCz; nz++) {
                if (!columnLit[nx][nz]) {
                    initColumnVerticalAndSources(world, nx, nz);
                    columnLit[nx][nz] = true;
                    int bit = (nx - minCx) * 3 + (nz - minCz);
                    newlyLitMask |= (1 << bit);
                }
            }
        }

        // Gieo hạt BFS Sky Light cho các cột vừa khởi tạo và mép tiếp giáp cột đã sáng trước đó.
        clearAddQueue();
        for (int nx = minCx; nx <= maxCx; nx++) {
            for (int nz = minCz; nz <= maxCz; nz++) {
                int bit = (nx - minCx) * 3 + (nz - minCz);
                if ((newlyLitMask & (1 << bit)) != 0) {
                    seedSkyBfsForColumn(world, nx, nz);
                }
            }
        }
        drainSkyIncreaseQueue(world);

        // Gieo hạt BFS Block Light từ các khối Lava và mép tiếp giáp cột đã sáng trước đó.
        clearAddQueue();
        for (int nx = minCx; nx <= maxCx; nx++) {
            for (int nz = minCz; nz <= maxCz; nz++) {
                int bit = (nx - minCx) * 3 + (nz - minCz);
                if ((newlyLitMask & (1 << bit)) != 0) {
                    seedBlockBfsForColumn(world, nx, nz);
                }
            }
        }
        drainBlockIncreaseQueue(world);
    }

    /**
     * Cập nhật ánh sáng tăng/giảm cục bộ khi một ô tại (wx, wy, wz) thay đổi loại block.
     */
    void onBlockChanged(World world, int wx, int wy, int wz, byte oldId, byte newId) {
        int cx = wx / Chunk.SIZE;
        int cz = wz / Chunk.SIZE;
        if (!isColumnLit(cx, cz)) {
            return;
        }
        ensureColumnLit(world, cx, cz);

        if (oldId != newId) {
            updateSkyColumnAndBfs(world, wx, wy, wz);
            updateBlockLightOnChange(world, wx, wy, wz, newId);
        }
    }

    /**
     * Khởi tạo chiếu thẳng Sky Light và phát hiện nguồn Lava trên toàn cột chunk (cx, cz),
     * giữ `light = null` cho các section đồng nhất để tiết kiệm bộ nhớ RAM.
     */
    private void initColumnVerticalAndSources(World world, int cx, int cz) {
        int topCy = highestNonNullChunkY(world, cx, cz);
        if (topCy < 0) {
            return;
        }

        for (int cy = 0; cy <= topCy; cy++) {
            uniformChunkFlags[cy] = true;
        }

        for (int lx = 0; lx < Chunk.SIZE; lx++) {
            for (int lz = 0; lz < Chunk.SIZE; lz++) {
                int sky = MAX_LIGHT;
                for (int cy = topCy; cy >= 0; cy--) {
                    Chunk chunk = world.getChunkRaw(cx, cy, cz);
                    for (int ly = Chunk.SIZE - 1; ly >= 0; ly--) {
                        byte id = chunk != null ? chunk.getBlockLocal(lx, ly, lz) : 0;
                        int emit = 0;
                        if (id != 0) {
                            Block block = Block.fromId(id);
                            if (block.isOpaque()) {
                                sky = 0;
                            } else if (isLeaves(block)) {
                                if (sky > 0) {
                                    sky--;
                                }
                            }
                            if (block == Block.LAVA) {
                                emit = MAX_LIGHT;
                            }
                        }
                        byte packed = (byte) ((sky << 4) | emit);
                        int index = (lx * Chunk.SIZE + ly) * Chunk.SIZE + lz;
                        columnScratch[cy][index] = packed;
                        if (lx == 0 && lz == 0 && ly == Chunk.SIZE - 1) {
                            uniformLightValue[cy] = packed;
                        } else if (packed != uniformLightValue[cy]) {
                            uniformChunkFlags[cy] = false;
                        }
                    }
                }
            }
        }

        for (int cy = 0; cy <= topCy; cy++) {
            Chunk chunk = world.getChunkRaw(cx, cy, cz);
            if (uniformChunkFlags[cy]) {
                if (chunk == null) {
                    if (uniformLightValue[cy] != Chunk.DEFAULT_LIGHT) {
                        chunk = world.getOrCreateLightChunk(cx, cy, cz, true);
                        chunk.setUniformLight(uniformLightValue[cy]);
                    }
                } else {
                    chunk.setUniformLight(uniformLightValue[cy]);
                }
            } else {
                if (chunk == null) {
                    chunk = world.getOrCreateLightChunk(cx, cy, cz, true);
                }
                chunk.applyLightArray(columnScratch[cy]);
            }
        }
    }

    /** Đưa các ô biên có độ sáng lớn hơn hàng xóm vào hàng đợi BFS Sky Light. */
    private void seedSkyBfsForColumn(World world, int cx, int cz) {
        int maxCy = maxLitNeighborhoodChunkY(world, cx, cz);
        if (maxCy < 0) {
            return;
        }
        int maxY = Math.min(World.WORLD_SIZE_Y - 1, (maxCy + 1) * Chunk.SIZE - 1);
        int baseX = cx * Chunk.SIZE;
        int baseZ = cz * Chunk.SIZE;
        int endX = Math.min(World.WORLD_SIZE_X, baseX + Chunk.SIZE);
        int endZ = Math.min(World.WORLD_SIZE_Z, baseZ + Chunk.SIZE);

        for (int wx = baseX; wx < endX; wx++) {
            for (int wz = baseZ; wz < endZ; wz++) {
                boolean onEdgeX = (wx == baseX || wx == endX - 1);
                boolean onEdgeZ = (wz == baseZ || wz == endZ - 1);
                for (int y = 0; y <= maxY; y++) {
                    int sky = getSkyLightRaw(world, wx, y, wz);
                    if (sky > 1 && hasDarkerSkyNeighbor(world, wx, y, wz, sky)) {
                        pushAdd(wx, y, wz);
                    }
                    // Nếu đang đứng ở mép cột mới khởi tạo, kiểm tra ánh sáng từ cột đã sáng kề bên tràn vào.
                    if ((onEdgeX || onEdgeZ) && !Block.fromId(world.getBlock(wx, y, wz)).isOpaque()) {
                        enqueueBrighterEdgeSkyNeighbor(world, wx, y, wz, sky, baseX, endX, baseZ, endZ);
                    }
                }
            }
        }
    }

    /** Đưa các nguồn Lava và ánh sáng Block Light ở biên cột đã sáng vào hàng đợi BFS. */
    private void seedBlockBfsForColumn(World world, int cx, int cz) {
        int maxCy = maxLitNeighborhoodChunkY(world, cx, cz);
        if (maxCy < 0) {
            return;
        }
        int maxY = Math.min(World.WORLD_SIZE_Y - 1, (maxCy + 1) * Chunk.SIZE - 1);
        int baseX = cx * Chunk.SIZE;
        int baseZ = cz * Chunk.SIZE;
        int endX = Math.min(World.WORLD_SIZE_X, baseX + Chunk.SIZE);
        int endZ = Math.min(World.WORLD_SIZE_Z, baseZ + Chunk.SIZE);

        for (int wx = baseX; wx < endX; wx++) {
            for (int wz = baseZ; wz < endZ; wz++) {
                boolean onEdgeX = (wx == baseX || wx == endX - 1);
                boolean onEdgeZ = (wz == baseZ || wz == endZ - 1);
                for (int y = 0; y <= maxY; y++) {
                    int blockLight = getBlockLightRaw(world, wx, y, wz);
                    if (blockLight > 1) {
                        pushAdd(wx, y, wz);
                    }
                    if ((onEdgeX || onEdgeZ) && !Block.fromId(world.getBlock(wx, y, wz)).isOpaque()) {
                        enqueueBrighterEdgeBlockNeighbor(world, wx, y, wz, blockLight, baseX, endX, baseZ, endZ);
                    }
                }
            }
        }
    }

    /** Kiểm tra 6 hướng xem có ô nào nhận được thêm Sky Light từ (x, y, z) không. */
    private boolean hasDarkerSkyNeighbor(World world, int x, int y, int z, int sky) {
        int threshold = sky - 1;
        return canAcceptSky(world, x - 1, y, z, threshold)
                || canAcceptSky(world, x + 1, y, z, threshold)
                || canAcceptSky(world, x, y - 1, z, sky == MAX_LIGHT ? MAX_LIGHT : threshold)
                || canAcceptSky(world, x, y + 1, z, threshold)
                || canAcceptSky(world, x, y, z - 1, threshold)
                || canAcceptSky(world, x, y, z + 1, threshold);
    }

    /** Kiểm tra ô lân cận nằm trong vùng đã khởi tạo và có thể nhận mức Sky Light mục tiêu. */
    private boolean canAcceptSky(World world, int nx, int ny, int nz, int targetSky) {
        if (!world.isInsideWorld(nx, ny, nz) || !isColumnLit(nx / Chunk.SIZE, nz / Chunk.SIZE)) {
            return false;
        }
        Block block = Block.fromId(world.getBlock(nx, ny, nz));
        if (block.isOpaque()) {
            return false;
        }
        int effectiveTarget = (targetSky == MAX_LIGHT && isLeaves(block)) ? MAX_LIGHT - 1 : targetSky;
        return getSkyLightRaw(world, nx, ny, nz) < effectiveTarget;
    }

    /** Gieo hạt từ hàng xóm ngoài biên cột chunk nếu hàng xóm có Sky Light lớn hơn. */
    private void enqueueBrighterEdgeSkyNeighbor(World world, int wx, int y, int wz, int sky,
                                                int baseX, int endX, int baseZ, int endZ) {
        int needed = sky + 2;
        if (wx == baseX && wx > 0 && isColumnLit((wx - 1) / Chunk.SIZE, wz / Chunk.SIZE)
                && getSkyLightRaw(world, wx - 1, y, wz) >= needed) {
            pushAdd(wx - 1, y, wz);
        }
        if (wx == endX - 1 && wx + 1 < World.WORLD_SIZE_X && isColumnLit((wx + 1) / Chunk.SIZE, wz / Chunk.SIZE)
                && getSkyLightRaw(world, wx + 1, y, wz) >= needed) {
            pushAdd(wx + 1, y, wz);
        }
        if (wz == baseZ && wz > 0 && isColumnLit(wx / Chunk.SIZE, (wz - 1) / Chunk.SIZE)
                && getSkyLightRaw(world, wx, y, wz - 1) >= needed) {
            pushAdd(wx, y, wz - 1);
        }
        if (wz == endZ - 1 && wz + 1 < World.WORLD_SIZE_Z && isColumnLit(wx / Chunk.SIZE, (wz + 1) / Chunk.SIZE)
                && getSkyLightRaw(world, wx, y, wz + 1) >= needed) {
            pushAdd(wx, y, wz + 1);
        }
    }

    /** Gieo hạt từ hàng xóm ngoài biên cột chunk nếu hàng xóm có Block Light lớn hơn. */
    private void enqueueBrighterEdgeBlockNeighbor(World world, int wx, int y, int wz, int blockLight,
                                                  int baseX, int endX, int baseZ, int endZ) {
        int needed = blockLight + 2;
        if (wx == baseX && wx > 0 && isColumnLit((wx - 1) / Chunk.SIZE, wz / Chunk.SIZE)
                && getBlockLightRaw(world, wx - 1, y, wz) >= needed) {
            pushAdd(wx - 1, y, wz);
        }
        if (wx == endX - 1 && wx + 1 < World.WORLD_SIZE_X && isColumnLit((wx + 1) / Chunk.SIZE, wz / Chunk.SIZE)
                && getBlockLightRaw(world, wx + 1, y, wz) >= needed) {
            pushAdd(wx + 1, y, wz);
        }
        if (wz == baseZ && wz > 0 && isColumnLit(wx / Chunk.SIZE, (wz - 1) / Chunk.SIZE)
                && getBlockLightRaw(world, wx, y, wz - 1) >= needed) {
            pushAdd(wx, y, wz - 1);
        }
        if (wz == endZ - 1 && wz + 1 < World.WORLD_SIZE_Z && isColumnLit(wx / Chunk.SIZE, (wz + 1) / Chunk.SIZE)
                && getBlockLightRaw(world, wx, y, wz + 1) >= needed) {
            pushAdd(wx, y, wz + 1);
        }
    }

    /** Cập nhật lại đường chiếu thẳng Sky Light của cột (wx, wz) từ wy trở xuống và chạy BFS xóa/tăng sáng. */
    private void updateSkyColumnAndBfs(World world, int wx, int wy, int wz) {
        clearAddQueue();
        clearRemoveQueue();

        // Tính lượng Sky Light chiếu thẳng từ đỉnh thế giới xuống tới ngay phía trên wy.
        int topCy = highestNonNullChunkY(world, wx / Chunk.SIZE, wz / Chunk.SIZE);
        int topY = topCy < 0 ? -1 : Math.min(World.WORLD_SIZE_Y - 1, (topCy + 1) * Chunk.SIZE - 1);
        int directSky = MAX_LIGHT;
        for (int y = topY; y > wy; y--) {
            Block b = Block.fromId(world.getBlock(wx, y, wz));
            if (b.isOpaque()) {
                directSky = 0;
                break;
            }
            if (isLeaves(b) && directSky > 0) {
                directSky--;
            }
        }

        // Quét từ wy đi xuống cho tới khi gặp khối đục nằm dưới wy.
        int lowestAffectedY = wy;
        int curDirectSky = directSky;
        for (int y = wy; y >= 0; y--) {
            Block b = Block.fromId(world.getBlock(wx, y, wz));
            boolean opaque = b.isOpaque();
            if (opaque) {
                curDirectSky = 0;
            } else if (isLeaves(b) && curDirectSky > 0) {
                curDirectSky--;
            }

            int oldSky = getSkyLightRaw(world, wx, y, wz);
            if (oldSky > curDirectSky) {
                pushRemove(wx, y, wz, oldSky);
                setSkyLightRaw(world, wx, y, wz, 0);
            } else if (curDirectSky > oldSky) {
                setSkyLightRaw(world, wx, y, wz, curDirectSky);
                pushAdd(wx, y, wz);
            }

            lowestAffectedY = y;
            if (opaque && y < wy) {
                break;
            }
        }

        // Chạy BFS xóa bỏ ánh sáng cũ phụ thuộc vào phần cột vừa bị che tối.
        drainSkyRemoveQueue(world);

        // Khôi phục lại mức chiếu thẳng (ví dụ khi đặt lá lên cột có sẵn ánh sáng yếu hơn 15).
        curDirectSky = directSky;
        for (int y = wy; y >= lowestAffectedY; y--) {
            Block b = Block.fromId(world.getBlock(wx, y, wz));
            if (b.isOpaque()) {
                break;
            }
            if (isLeaves(b) && curDirectSky > 0) {
                curDirectSky--;
            }
            if (curDirectSky > getSkyLightRaw(world, wx, y, wz)) {
                setSkyLightRaw(world, wx, y, wz, curDirectSky);
                pushAdd(wx, y, wz);
            }
        }

        // Nếu ô tại (wx, wy, wz) vừa mở thông và không nhận sáng trực tiếp, kéo sáng từ 6 hàng xóm vào.
        if (!Block.fromId(world.getBlock(wx, wy, wz)).isOpaque()) {
            enqueueBrighterSkyNeighbors(world, wx, wy, wz);
        }

        drainSkyIncreaseQueue(world);
    }

    /** Cập nhật Block Light khi khối tại (wx, wy, wz) thay đổi (đặt/phá Lava hoặc đặt khối chắn sáng). */
    private void updateBlockLightOnChange(World world, int wx, int wy, int wz, byte newId) {
        clearAddQueue();
        clearRemoveQueue();

        int oldLight = getBlockLightRaw(world, wx, wy, wz);
        Block newBlock = Block.fromId(newId);
        int newEmit = emissionOf(newBlock);

        if (oldLight > newEmit) {
            pushRemove(wx, wy, wz, oldLight);
            setBlockLightRaw(world, wx, wy, wz, 0);
            drainBlockRemoveQueue(world);
        }

        if (newEmit > 0) {
            setBlockLightRaw(world, wx, wy, wz, newEmit);
            pushAdd(wx, wy, wz);
        } else if (!newBlock.isOpaque()) {
            enqueueBrighterBlockNeighbors(world, wx, wy, wz);
        }

        drainBlockIncreaseQueue(world);
    }

    /** Rút cạn hàng đợi xóa Sky Light và ghi nhận các hàng xóm đủ sáng để chiếu bù lại. */
    private void drainSkyRemoveQueue(World world) {
        while (removeCount > 0) {
            int packed = popRemovePos();
            int oldVal = popRemoveVal();
            int x = packed >>> 19;
            int y = packed & 0xFF;
            int z = (packed >>> 8) & 0x7FF;

            removeSkyNeighbor(world, x - 1, y, z, oldVal);
            removeSkyNeighbor(world, x + 1, y, z, oldVal);
            removeSkyNeighbor(world, x, y - 1, z, oldVal);
            removeSkyNeighbor(world, x, y + 1, z, oldVal);
            removeSkyNeighbor(world, x, y, z - 1, oldVal);
            removeSkyNeighbor(world, x, y, z + 1, oldVal);
        }
    }

    /** Xử lý một ô lân cận trong pha xóa Sky Light. */
    private void removeSkyNeighbor(World world, int nx, int ny, int nz, int oldVal) {
        if (!world.isInsideWorld(nx, ny, nz) || !isColumnLit(nx / Chunk.SIZE, nz / Chunk.SIZE)) {
            return;
        }
        int nVal = getSkyLightRaw(world, nx, ny, nz);
        if (nVal == 0) {
            return;
        }
        if (nVal < oldVal) {
            setSkyLightRaw(world, nx, ny, nz, 0);
            pushRemove(nx, ny, nz, nVal);
        } else {
            pushAdd(nx, ny, nz);
        }
    }

    /** Rút cạn hàng đợi xóa Block Light và ghi nhận các nguồn sáng còn lại để lan truyền bù. */
    private void drainBlockRemoveQueue(World world) {
        while (removeCount > 0) {
            int packed = popRemovePos();
            int oldVal = popRemoveVal();
            int x = packed >>> 19;
            int y = packed & 0xFF;
            int z = (packed >>> 8) & 0x7FF;

            removeBlockNeighbor(world, x - 1, y, z, oldVal);
            removeBlockNeighbor(world, x + 1, y, z, oldVal);
            removeBlockNeighbor(world, x, y - 1, z, oldVal);
            removeBlockNeighbor(world, x, y + 1, z, oldVal);
            removeBlockNeighbor(world, x, y, z - 1, oldVal);
            removeBlockNeighbor(world, x, y, z + 1, oldVal);
        }
    }

    /** Xử lý một ô lân cận trong pha xóa Block Light. */
    private void removeBlockNeighbor(World world, int nx, int ny, int nz, int oldVal) {
        if (!world.isInsideWorld(nx, ny, nz) || !isColumnLit(nx / Chunk.SIZE, nz / Chunk.SIZE)) {
            return;
        }
        int nVal = getBlockLightRaw(world, nx, ny, nz);
        if (nVal == 0) {
            return;
        }
        if (nVal < oldVal) {
            setBlockLightRaw(world, nx, ny, nz, 0);
            pushRemove(nx, ny, nz, nVal);
        } else {
            pushAdd(nx, ny, nz);
        }
    }

    /** Lan truyền tăng Sky Light theo BFS 6 hướng dùng hàng đợi vòng. */
    private void drainSkyIncreaseQueue(World world) {
        while (addCount > 0) {
            int packed = popAdd();
            int x = packed >>> 19;
            int y = packed & 0xFF;
            int z = (packed >>> 8) & 0x7FF;
            int level = getSkyLightRaw(world, x, y, z);
            if (level <= 1) {
                continue;
            }
            propagateSkyNeighbor(world, x - 1, y, z, level, false);
            propagateSkyNeighbor(world, x + 1, y, z, level, false);
            propagateSkyNeighbor(world, x, y - 1, z, level, true);
            propagateSkyNeighbor(world, x, y + 1, z, level, false);
            propagateSkyNeighbor(world, x, y, z - 1, level, false);
            propagateSkyNeighbor(world, x, y, z + 1, level, false);
        }
    }

    /** Lan truyền Sky Light sang một ô kề nếu không bị khối đục cản lại. */
    private void propagateSkyNeighbor(World world, int nx, int ny, int nz, int sourceLevel, boolean downward) {
        if (!world.isInsideWorld(nx, ny, nz) || !isColumnLit(nx / Chunk.SIZE, nz / Chunk.SIZE)) {
            return;
        }
        Block block = Block.fromId(world.getBlock(nx, ny, nz));
        if (block.isOpaque()) {
            return;
        }
        int targetLevel;
        if (downward && sourceLevel == MAX_LIGHT && !isLeaves(block)) {
            targetLevel = MAX_LIGHT;
        } else {
            targetLevel = sourceLevel - 1;
        }
        if (targetLevel <= 0) {
            return;
        }
        if (getSkyLightRaw(world, nx, ny, nz) < targetLevel) {
            setSkyLightRaw(world, nx, ny, nz, targetLevel);
            pushAdd(nx, ny, nz);
        }
    }

    /** Lan truyền tăng Block Light theo BFS 6 hướng dùng hàng đợi vòng. */
    private void drainBlockIncreaseQueue(World world) {
        while (addCount > 0) {
            int packed = popAdd();
            int x = packed >>> 19;
            int y = packed & 0xFF;
            int z = (packed >>> 8) & 0x7FF;
            int level = getBlockLightRaw(world, x, y, z);
            if (level <= 1) {
                continue;
            }
            int nextLevel = level - 1;
            propagateBlockNeighbor(world, x - 1, y, z, nextLevel);
            propagateBlockNeighbor(world, x + 1, y, z, nextLevel);
            propagateBlockNeighbor(world, x, y - 1, z, nextLevel);
            propagateBlockNeighbor(world, x, y + 1, z, nextLevel);
            propagateBlockNeighbor(world, x, y, z - 1, nextLevel);
            propagateBlockNeighbor(world, x, y, z + 1, nextLevel);
        }
    }

    /** Lan truyền Block Light sang một ô kề nếu không bị khối đục cản lại. */
    private void propagateBlockNeighbor(World world, int nx, int ny, int nz, int targetLevel) {
        if (!world.isInsideWorld(nx, ny, nz) || !isColumnLit(nx / Chunk.SIZE, nz / Chunk.SIZE)) {
            return;
        }
        if (Block.fromId(world.getBlock(nx, ny, nz)).isOpaque()) {
            return;
        }
        if (getBlockLightRaw(world, nx, ny, nz) < targetLevel) {
            setBlockLightRaw(world, nx, ny, nz, targetLevel);
            pushAdd(nx, ny, nz);
        }
    }

    /** Đưa các hàng xóm có Sky Light > 1 vào hàng đợi khi vừa đục thông một ô. */
    private void enqueueBrighterSkyNeighbors(World world, int x, int y, int z) {
        enqueueSkyIfBrighter(world, x - 1, y, z);
        enqueueSkyIfBrighter(world, x + 1, y, z);
        enqueueSkyIfBrighter(world, x, y - 1, z);
        enqueueSkyIfBrighter(world, x, y + 1, z);
        enqueueSkyIfBrighter(world, x, y, z - 1);
        enqueueSkyIfBrighter(world, x, y, z + 1);
    }

    private void enqueueSkyIfBrighter(World world, int nx, int ny, int nz) {
        if (world.isInsideWorld(nx, ny, nz) && isColumnLit(nx / Chunk.SIZE, nz / Chunk.SIZE)
                && getSkyLightRaw(world, nx, ny, nz) > 1) {
            pushAdd(nx, ny, nz);
        }
    }

    /** Đưa các hàng xóm có Block Light > 1 vào hàng đợi khi vừa đục thông một ô. */
    private void enqueueBrighterBlockNeighbors(World world, int x, int y, int z) {
        enqueueBlockIfBrighter(world, x - 1, y, z);
        enqueueBlockIfBrighter(world, x + 1, y, z);
        enqueueBlockIfBrighter(world, x, y - 1, z);
        enqueueBlockIfBrighter(world, x, y + 1, z);
        enqueueBlockIfBrighter(world, x, y, z - 1);
        enqueueBlockIfBrighter(world, x, y, z + 1);
    }

    private void enqueueBlockIfBrighter(World world, int nx, int ny, int nz) {
        if (world.isInsideWorld(nx, ny, nz) && isColumnLit(nx / Chunk.SIZE, nz / Chunk.SIZE)
                && getBlockLightRaw(world, nx, ny, nz) > 1) {
            pushAdd(nx, ny, nz);
        }
    }

    /** Đọc trực tiếp Sky Light từ Chunk mà không kích hoạt khởi tạo lười. */
    private static int getSkyLightRaw(World world, int x, int y, int z) {
        Chunk chunk = world.getChunkRaw(x / Chunk.SIZE, y / Chunk.SIZE, z / Chunk.SIZE);
        return chunk == null ? MAX_LIGHT : chunk.getSkyLightLocal(x % Chunk.SIZE, y % Chunk.SIZE, z % Chunk.SIZE);
    }

    /** Đọc trực tiếp Block Light từ Chunk mà không kích hoạt khởi tạo lười. */
    private static int getBlockLightRaw(World world, int x, int y, int z) {
        Chunk chunk = world.getChunkRaw(x / Chunk.SIZE, y / Chunk.SIZE, z / Chunk.SIZE);
        return chunk == null ? 0 : chunk.getBlockLightLocal(x % Chunk.SIZE, y % Chunk.SIZE, z % Chunk.SIZE);
    }

    /** Ghi trực tiếp Sky Light vào Chunk và đánh dấu bẩn chunk cùng chunk biên kề. */
    private static boolean setSkyLightRaw(World world, int x, int y, int z, int level) {
        int cx = x / Chunk.SIZE;
        int cy = y / Chunk.SIZE;
        int cz = z / Chunk.SIZE;
        Chunk chunk = world.getOrCreateLightChunk(cx, cy, cz, level != MAX_LIGHT);
        if (chunk == null) {
            return false;
        }
        if (chunk.setSkyLightLocal(x % Chunk.SIZE, y % Chunk.SIZE, z % Chunk.SIZE, level)) {
            markLightDirty(world, x, y, z);
            return true;
        }
        return false;
    }

    /** Ghi trực tiếp Block Light vào Chunk và đánh dấu bẩn chunk cùng chunk biên kề. */
    private static boolean setBlockLightRaw(World world, int x, int y, int z, int level) {
        int cx = x / Chunk.SIZE;
        int cy = y / Chunk.SIZE;
        int cz = z / Chunk.SIZE;
        Chunk chunk = world.getOrCreateLightChunk(cx, cy, cz, level != 0);
        if (chunk == null) {
            return false;
        }
        if (chunk.setBlockLightLocal(x % Chunk.SIZE, y % Chunk.SIZE, z % Chunk.SIZE, level)) {
            markLightDirty(world, x, y, z);
            return true;
        }
        return false;
    }

    /** Đánh dấu chunk chứa (x, y, z) và các chunk lân cận qua biên cần dựng lại mesh. */
    private static void markLightDirty(World world, int x, int y, int z) {
        int cx = x / Chunk.SIZE;
        int cy = y / Chunk.SIZE;
        int cz = z / Chunk.SIZE;
        world.markChunkDirtyIfExists(cx, cy, cz);

        int lx = x % Chunk.SIZE;
        int ly = y % Chunk.SIZE;
        int lz = z % Chunk.SIZE;
        if (lx == 0 && cx > 0) {
            world.markChunkDirtyIfExists(cx - 1, cy, cz);
        } else if (lx == Chunk.SIZE - 1 && cx + 1 < World.WORLD_CHUNKS_X) {
            world.markChunkDirtyIfExists(cx + 1, cy, cz);
        }
        if (ly == 0 && cy > 0) {
            world.markChunkDirtyIfExists(cx, cy - 1, cz);
        } else if (ly == Chunk.SIZE - 1 && cy + 1 < World.WORLD_CHUNKS_Y) {
            world.markChunkDirtyIfExists(cx, cy + 1, cz);
        }
        if (lz == 0 && cz > 0) {
            world.markChunkDirtyIfExists(cx, cy, cz - 1);
        } else if (lz == Chunk.SIZE - 1 && cz + 1 < World.WORLD_CHUNKS_Z) {
            world.markChunkDirtyIfExists(cx, cy, cz + 1);
        }
    }

    /** Tìm section chunk cao nhất đang tồn tại trong cột (cx, cz). */
    private static int highestNonNullChunkY(World world, int cx, int cz) {
        for (int cy = World.WORLD_CHUNKS_Y - 1; cy >= 0; cy--) {
            if (world.getChunkRaw(cx, cy, cz) != null) {
                return cy;
            }
        }
        return -1;
    }

    /** Tìm section chunk cao nhất trong cột (cx, cz) và 4 cột kề mặt để quét đủ vùng giáp ranh. */
    private static int maxLitNeighborhoodChunkY(World world, int cx, int cz) {
        int maxCy = highestNonNullChunkY(world, cx, cz);
        if (cx > 0) {
            maxCy = Math.max(maxCy, highestNonNullChunkY(world, cx - 1, cz));
        }
        if (cx + 1 < World.WORLD_CHUNKS_X) {
            maxCy = Math.max(maxCy, highestNonNullChunkY(world, cx + 1, cz));
        }
        if (cz > 0) {
            maxCy = Math.max(maxCy, highestNonNullChunkY(world, cx, cz - 1));
        }
        if (cz + 1 < World.WORLD_CHUNKS_Z) {
            maxCy = Math.max(maxCy, highestNonNullChunkY(world, cx, cz + 1));
        }
        return maxCy;
    }

    private static int emissionOf(Block block) {
        return block == Block.LAVA ? MAX_LIGHT : 0;
    }

    private static boolean isLeaves(Block block) {
        return block == Block.OAK_LEAVES || block == Block.SPRUCE_LEAVES;
    }

    private static int clampLight(int level) {
        return Math.max(0, Math.min(MAX_LIGHT, level));
    }

    // =========================================================================
    // QUẢN LÝ HÀNG ĐỢI VÒNG (RING BUFFER) ZERO-GC
    // =========================================================================

    private static int pack(int x, int y, int z) {
        return (x << 19) | (z << 8) | y;
    }

    private void clearAddQueue() {
        addHead = 0;
        addTail = 0;
        addCount = 0;
    }

    private void pushAdd(int x, int y, int z) {
        if (addCount == addQueue.length) {
            growAddQueue();
        }
        addQueue[addTail] = pack(x, y, z);
        addTail = (addTail + 1) & (addQueue.length - 1);
        addCount++;
    }

    private int popAdd() {
        int value = addQueue[addHead];
        addHead = (addHead + 1) & (addQueue.length - 1);
        addCount--;
        return value;
    }

    /** Chỉ mở rộng gấp đôi trong tình huống cực hiếm vượt quá 65.536 ô cùng lúc. */
    private void growAddQueue() {
        int oldCap = addQueue.length;
        int[] expanded = new int[oldCap * 2];
        int firstPart = oldCap - addHead;
        System.arraycopy(addQueue, addHead, expanded, 0, firstPart);
        System.arraycopy(addQueue, 0, expanded, firstPart, addHead);
        addQueue = expanded;
        addHead = 0;
        addTail = oldCap;
    }

    private void clearRemoveQueue() {
        removeHead = 0;
        removeTail = 0;
        removeCount = 0;
    }

    private void pushRemove(int x, int y, int z, int oldVal) {
        if (removeCount == removePosQueue.length) {
            growRemoveQueue();
        }
        removePosQueue[removeTail] = pack(x, y, z);
        removeValQueue[removeTail] = (byte) oldVal;
        removeTail = (removeTail + 1) & (removePosQueue.length - 1);
        removeCount++;
    }

    private int popRemovePos() {
        return removePosQueue[removeHead];
    }

    private int popRemoveVal() {
        int value = Byte.toUnsignedInt(removeValQueue[removeHead]);
        removeHead = (removeHead + 1) & (removePosQueue.length - 1);
        removeCount--;
        return value;
    }

    private void growRemoveQueue() {
        int oldCap = removePosQueue.length;
        int[] expandedPos = new int[oldCap * 2];
        byte[] expandedVal = new byte[oldCap * 2];
        int firstPart = oldCap - removeHead;
        System.arraycopy(removePosQueue, removeHead, expandedPos, 0, firstPart);
        System.arraycopy(removePosQueue, 0, expandedPos, firstPart, removeHead);
        System.arraycopy(removeValQueue, removeHead, expandedVal, 0, firstPart);
        System.arraycopy(removeValQueue, 0, expandedVal, firstPart, removeHead);
        removePosQueue = expandedPos;
        removeValQueue = expandedVal;
        removeHead = 0;
        removeTail = oldCap;
    }
}

package com.voxelgame.world.level;

import com.voxelgame.core.Tickable;
import com.voxelgame.world.entity.ItemEntity;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.block.WoolBlock;

import com.badlogic.gdx.utils.IntSet;
import java.util.Arrays;
import java.util.Random;

/**
 * Hệ thống quản lý phân hủy lá cây tự nhiên ({@code Oak Leaves}, {@code Spruce Leaves})
 * và hệ số tốc độ đào của công cụ {@link Item#SHEARS} trên lá và 6 khối len {@link WoolBlock}.
 *
 * Thiết kế Zero-GC:
 * - Thuật toán BFS kiểm tra kết nối tới thân gỗ ({@link #isConnectedToLog}) dùng chung hai mảng
 *   kích thước cố định ({@code 13×13×13 = 2197} ô) cấp phát sẵn một lần duy nhất, kết hợp bộ đếm
 *   nhãn {@code currentVisitStamp} để tránh cấp phát rác hoặc dọn toàn mảng mỗi lần gọi.
 * - Hàng đợi kiểm tra trễ khi chặt gỗ/lá dùng ring-buffer cố định và {@link IntSet} cấp phát dư
 *   dung lượng ngay khi khởi tạo để bảo đảm ổn định 60 FPS.
 */
public final class LeafDecaySystem implements Tickable {

    /** Bit metadata đánh dấu lá do người chơi tự đặt, không bao giờ tự phân hủy. */
    public static final int PERSISTENT_LEAF_STATE = 1;

    /** Khoảng cách Manhattan tối đa (6 ô) từ lá tới thân gỗ để duy trì tán lá. */
    public static final int MAX_LOG_DISTANCE = 6;

    /** Hệ số tăng tốc độ đào khi dùng kéo (Shears) trên lá cây và 6 màu len cừu. */
    public static final float SHEARS_MINING_MULTIPLIER = 5.0f;

    /** Kích thước cạnh lưới cục bộ (2 × 6 + 1 = 13) và thể tích lưới BFS (2197 ô). */
    private static final int GRID_SPAN = MAX_LOG_DISTANCE * 2 + 1;
    private static final int GRID_VOLUME = GRID_SPAN * GRID_SPAN * GRID_SPAN;

    /** Xác suất rơi gậy gỗ (2%) khi một khối lá tự nhiên phân hủy. */
    private static final float STICK_DROP_CHANCE = 0.02f;

    /** Chu kỳ xử lý hàng đợi lá chờ kiểm tra và giới hạn số ô mỗi nhịp để giữ 60 FPS. */
    private static final float DECAY_STEP_SECONDS = 0.15f;
    private static final int MAX_CHECKS_PER_STEP = 16;
    private static final int PENDING_CAPACITY = 2048;

    /** 6 hướng kề mặt theo trục X, Y, Z dùng chung cho BFS và lan truyền hàng xóm. */
    private static final int[] DX = {1, -1, 0, 0, 0, 0};
    private static final int[] DY = {0, 0, 1, -1, 0, 0};
    private static final int[] DZ = {0, 0, 0, 0, 1, -1};

    /** Hàng đợi BFS cố định: mỗi phần tử đóng gói (localIndex << 4) | distance. */
    private static final int[] BFS_QUEUE = new int[GRID_VOLUME];

    /** Mảng đóng dấu lượt duyệt theo {@code currentVisitStamp} để kiểm tra đã thăm trong O(1). */
    private static final int[] VISITED_STAMP = new int[GRID_VOLUME];
    private static int currentVisitStamp = 1;

    /** Bộ sinh số ngẫu nhiên dùng lại cho tỷ lệ rơi Stick khi lá phân hủy. */
    private static final Random DROP_RANDOM = new Random(World.WORLD_SEED ^ 0x4C454146L);

    /** Ring-buffer cố định lưu tọa độ đóng gói (x << 19) | (z << 8) | y các lá chờ kiểm tra. */
    private final int[] pendingQueue = new int[PENDING_CAPACITY];
    private final IntSet pendingSet = new IntSet(PENDING_CAPACITY * 2);
    private int head;
    private int tail;
    private int count;
    private float elapsed;

    /**
     * Kiểm tra một khối có phải là khối lá hỗ trợ phân hủy ({@code OAK_LEAVES} / {@code SPRUCE_LEAVES}).
     *
     * @param block thực thể Block cần kiểm tra
     * @return true nếu là lá sồi hoặc lá vân sam
     */
    public static boolean isLeaf(Block block) {
        return block == Block.OAK_LEAVES || block == Block.SPRUCE_LEAVES;
    }

    /**
     * Kiểm tra mã byte ID có phải khối lá sồi hoặc lá vân sam.
     *
     * @param blockId mã ID block
     * @return true nếu là lá
     */
    public static boolean isLeafId(byte blockId) {
        return blockId == Block.OAK_LEAVES.getId() || blockId == Block.SPRUCE_LEAVES.getId();
    }

    /**
     * Kiểm tra mã byte ID có phải khối thân gỗ ({@code OAK_LOG} / {@code SPRUCE_LOG}).
     *
     * @param blockId mã ID block
     * @return true nếu là thân gỗ
     */
    public static boolean isLogId(byte blockId) {
        return blockId == Block.OAK_LOG.getId() || blockId == Block.SPRUCE_LOG.getId();
    }

    /**
     * Kiểm tra tại tọa độ thế giới có phải là lá tự nhiên (không mang bit {@link #PERSISTENT_LEAF_STATE}).
     *
     * @param world thế giới voxel
     * @param x     tọa độ X
     * @param y     tọa độ Y
     * @param z     tọa độ Z
     * @return true nếu ô là lá và có thể phân hủy
     */
    public static boolean isDecayableLeaf(World world, int x, int y, int z) {
        if (world == null || !world.isInsideWorld(x, y, z)) {
            return false;
        }
        return isLeafId(world.getBlock(x, y, z))
                && (world.getBlockState(x, y, z) & PERSISTENT_LEAF_STATE) == 0;
    }

    /**
     * Tính hệ số nhân tốc độ đào dựa trên vật phẩm đang cầm và khối mục tiêu.
     * Cầm {@link Item#SHEARS} đào lá cây hoặc 6 loại {@link WoolBlock} đạt tốc độ {@code 5.0f};
     * mọi trường hợp khác giữ nguyên {@code 1.0f}.
     *
     * @param heldItem vật phẩm trên tay người chơi (có thể là {@link Item#NONE})
     * @param target   khối đang bị đào
     * @return hệ số nhân tốc độ đào ({@code 5.0f} hoặc {@code 1.0f})
     */
    public static float miningSpeedMultiplier(Item heldItem, Block target) {
        return heldItem != null ? heldItem.getMiningSpeedMultiplier(target) : 1.0f;
    }

    /**
     * Duyệt BFS trong bán kính Manhattan tối đa {@value #MAX_LOG_DISTANCE} ô quanh vị trí lá
     * để kiểm tra lá có còn kết nối qua chuỗi lá liền kề tới thân gỗ ({@code OAK_LOG} / {@code SPRUCE_LOG}) không.
     *
     * @param world  thế giới voxel
     * @param startX tọa độ X của lá cần kiểm tra
     * @param startY tọa độ Y của lá cần kiểm tra
     * @param startZ tọa độ Z của lá cần kiểm tra
     * @return true nếu tìm thấy đường nối tới thân gỗ trong bán kính 6 ô
     */
    public static boolean isConnectedToLog(World world, int startX, int startY, int startZ) {
        if (world == null || !world.isInsideWorld(startX, startY, startZ)) {
            return false;
        }
        if (!isLeafId(world.getBlock(startX, startY, startZ))) {
            return false;
        }

        // Tăng nhãn lượt duyệt để đánh dấu đã thăm mà không cấp phát mảng boolean mới
        currentVisitStamp++;
        if (currentVisitStamp <= 0) {
            Arrays.fill(VISITED_STAMP, 0);
            currentVisitStamp = 1;
        }
        int stamp = currentVisitStamp;

        int centerIdx = (MAX_LOG_DISTANCE * GRID_SPAN + MAX_LOG_DISTANCE) * GRID_SPAN + MAX_LOG_DISTANCE;
        VISITED_STAMP[centerIdx] = stamp;

        int qHead = 0;
        int qTail = 0;
        BFS_QUEUE[qTail++] = centerIdx << 4;

        while (qHead < qTail) {
            int entry = BFS_QUEUE[qHead++];
            int idx = entry >>> 4;
            int dist = entry & 0xF;

            // Giải mã tọa độ cục bộ trong hộp 13×13×13
            int lz = idx % GRID_SPAN;
            int tmp = idx / GRID_SPAN;
            int ly = tmp % GRID_SPAN;
            int lx = tmp / GRID_SPAN;

            int wx = startX + (lx - MAX_LOG_DISTANCE);
            int wy = startY + (ly - MAX_LOG_DISTANCE);
            int wz = startZ + (lz - MAX_LOG_DISTANCE);
            int nextDist = dist + 1;

            for (int dir = 0; dir < 6; dir++) {
                int nlx = lx + DX[dir];
                int nly = ly + DY[dir];
                int nlz = lz + DZ[dir];
                if (nlx < 0 || nlx >= GRID_SPAN || nly < 0 || nly >= GRID_SPAN || nlz < 0 || nlz >= GRID_SPAN) {
                    continue;
                }

                int nIdx = (nlx * GRID_SPAN + nly) * GRID_SPAN + nlz;
                if (VISITED_STAMP[nIdx] == stamp) {
                    continue;
                }

                int nwx = wx + DX[dir];
                int nwy = wy + DY[dir];
                int nwz = wz + DZ[dir];
                if (!world.isInsideWorld(nwx, nwy, nwz)) {
                    continue;
                }

                byte neighborId = world.getBlock(nwx, nwy, nwz);
                if (isLogId(neighborId)) {
                    return true;
                }

                VISITED_STAMP[nIdx] = stamp;
                // Chỉ mở rộng tiếp qua lá khi bước kế tiếp vẫn còn khả năng chạm gỗ trong <= 6 bước
                if (isLeafId(neighborId) && nextDist < MAX_LOG_DISTANCE) {
                    BFS_QUEUE[qTail++] = (nIdx << 4) | nextDist;
                }
            }
        }
        return false;
    }

    /**
     * Thực hiện kiểm tra phân hủy cho một khối lá tại {@code (x, y, z)}.
     * Nếu lá không phải lá đặt tay ({@link #PERSISTENT_LEAF_STATE}) và không nối tới gỗ trong
     * bán kính 6 ô, khối lá biến thành {@link Block#AIR} và có 2% cơ hội rơi {@link Item#STICK}.
     *
     * @param world thế giới voxel
     * @param x     tọa độ X
     * @param y     tọa độ Y
     * @param z     tọa độ Z
     */
    public static void tickLeaf(World world, int x, int y, int z) {
        if (world == null || !world.isInsideWorld(x, y, z)) {
            return;
        }
        byte blockId = world.getBlock(x, y, z);
        if (!isLeafId(blockId)) {
            return;
        }
        if ((world.getBlockState(x, y, z) & PERSISTENT_LEAF_STATE) != 0) {
            return;
        }
        if (isConnectedToLog(world, x, y, z)) {
            return;
        }

        // Xóa lá qua đường cập nhật gameplay để đánh dấu dirty mesh và lan truyền hàng xóm
        world.setBlock(x, y, z, Block.AIR.getId());
        if (DROP_RANDOM.nextFloat() < STICK_DROP_CHANCE) {
            world.spawnDroppedItem(new ItemEntity(x + 0.5f, y + 0.5f, z + 0.5f, Item.STICK));
        }
    }

    /**
     * Thông báo 6 ô kề mặt quanh khối gỗ hoặc lá vừa bị phá để xếp lịch kiểm tra phân hủy
     * cho các khối lá tự nhiên lân cận mà không gây tụt khung hình hoặc đệ quy tức thời.
     *
     * @param world thế giới voxel
     * @param x     tọa độ X của khối vừa bị phá
     * @param y     tọa độ Y của khối vừa bị phá
     * @param z     tọa độ Z của khối vừa bị phá
     */
    public static void notifyNeighbors(World world, int x, int y, int z) {
        if (world == null) {
            return;
        }
        for (int dir = 0; dir < 6; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];
            int nz = z + DZ[dir];
            if (isDecayableLeaf(world, nx, ny, nz)) {
                world.scheduleLeafDecayCheck(nx, ny, nz);
            }
        }
    }

    /**
     * Đưa tọa độ lá vào hàng đợi vòng kích thước cố định (không trùng lặp, không cấp phát rác).
     *
     * @param x tọa độ X thế giới
     * @param y tọa độ Y thế giới
     * @param z tọa độ Z thế giới
     */
    void schedule(int x, int y, int z) {
        if (x < 0 || x >= World.WORLD_SIZE_X || y < 0 || y >= World.WORLD_SIZE_Y
                || z < 0 || z >= World.WORLD_SIZE_Z) {
            return;
        }
        int packed = (x << 19) | (z << 8) | y;
        if (count < pendingQueue.length && pendingSet.add(packed)) {
            pendingQueue[tail] = packed;
            tail = (tail + 1) % pendingQueue.length;
            count++;
        }
    }

    /**
     * Rút dần tối đa {@value #MAX_CHECKS_PER_STEP} ô lá chờ kiểm tra sau mỗi chu kỳ
     * {@value #DECAY_STEP_SECONDS} giây để tán cây phân hủy tự nhiên mượt mà ở 60 FPS.
     *
     * @param world     thế giới voxel
     * @param deltaTime khoảng thời gian giữa hai khung hình (giây)
     */
    /** Triển khai hợp đồng {@link Tickable} để đồng bộ nhịp cập nhật phân hủy lá cây. */
    @Override
    public void tick(World world, float deltaTime) {
        update(world, deltaTime);
    }

    void update(World world, float deltaTime) {
        if (world == null || count == 0) {
            elapsed = 0.0f;
            return;
        }
        elapsed += deltaTime;
        while (elapsed >= DECAY_STEP_SECONDS && count > 0) {
            elapsed -= DECAY_STEP_SECONDS;
            int processed = 0;
            while (count > 0 && processed < MAX_CHECKS_PER_STEP) {
                int packed = pendingQueue[head];
                head = (head + 1) % pendingQueue.length;
                count--;
                pendingSet.remove(packed);

                int x = packed >>> 19;
                int y = packed & 0xFF;
                int z = (packed >>> 8) & 0x7FF;
                tickLeaf(world, x, y, z);
                processed++;
            }
        }
        if (count == 0) {
            elapsed = 0.0f;
        }
    }
}

package com.voxelgame.world.level;

import com.voxelgame.client.audio.AudioManager;
import com.voxelgame.core.Tickable;
import com.voxelgame.world.level.block.Block;

import com.badlogic.gdx.utils.IntSet;

/**
 * Hệ thống mô phỏng dòng chảy chất lỏng ({@link Block#WATER} và {@link Block#LAVA})
 * và phản ứng hóa đá {@link Block#STONE} khi hai chất lỏng tiếp xúc nhau.
 *
 * Thiết kế tối ưu 60 FPS (Zero-GC):
 * - Sử dụng hai hàng đợi vòng (ring-buffer) kích thước cố định tách biệt cho Nước và Dung nham,
 *   kết hợp {@link IntSet} cấp phát dư dung lượng một lần duy nhất để chống trùng lặp trong O(1).
 * - Giới hạn tối đa {@value #MAX_UPDATES_PER_TICK} ô xử lý mỗi nhịp cập nhật để bảo toàn
 *   tốc độ khung hình ngay cả khi người chơi phá vỡ bờ hồ lớn.
 * - Chỉ kích hoạt cho các ô thay đổi trong gameplay ({@link #onBlockChanged}), tuyệt đối không
 *   chạy hàng loạt khi sinh địa hình chunk ban đầu.
 */
public final class LiquidFlowSimulator implements Tickable {

    /** Số ô chất lỏng tối đa được xử lý trong mỗi bước tick để chống tụt FPS. */
    public static final int MAX_UPDATES_PER_TICK = 64;

    /** Chu kỳ lan truyền của nước (0.25 giây/bước) và bước tăng mức độ cản (tối đa 7 ô ngang). */
    public static final float WATER_FLOW_INTERVAL = 0.25f;
    public static final int WATER_FLOW_STEP = 1;

    /** Chu kỳ lan truyền của dung nham (1.50 giây/bước) và bước tăng +2 (tối đa 3 ô ngang: 2, 4, 6). */
    public static final float LAVA_FLOW_INTERVAL = 1.50f;
    public static final int LAVA_FLOW_STEP = 2;

    /** Mức metadata tối đa của dòng chảy (0 = nguồn, 1..7 = dòng chảy yếu dần). */
    public static final int MAX_FLOW_LEVEL = 7;

    /** Dung lượng cố định của mỗi hàng đợi vòng chất lỏng. */
    private static final int QUEUE_CAPACITY = 4096;

    /** Âm lượng cơ bản khi phát tiếng xì hơi nước lúc Water gặp Lava tạo Stone. */
    private static final float FIZZ_VOLUME = 0.45f;

    /** 6 hướng kề mặt dùng kiểm tra tiếp xúc Water/Lava và đánh thức hàng xóm. */
    private static final int[] DX = {0, 0, 1, -1, 0, 0};
    private static final int[] DY = {-1, 1, 0, 0, 0, 0};
    private static final int[] DZ = {0, 0, 0, 0, 1, -1};

    /** 4 hướng lan truyền trên mặt phẳng ngang XZ. */
    private static final int[] HDX = {1, -1, 0, 0};
    private static final int[] HDZ = {0, 0, 1, -1};

    /** Hàng đợi vòng và tập chống trùng cho dòng chảy Nước. */
    private final int[] waterQueue = new int[QUEUE_CAPACITY];
    private final IntSet waterSet = new IntSet(QUEUE_CAPACITY * 2);
    private int waterHead;
    private int waterTail;
    private int waterCount;
    private float waterElapsed;

    /** Hàng đợi vòng và tập chống trùng cho dòng chảy Dung nham. */
    private final int[] lavaQueue = new int[QUEUE_CAPACITY];
    private final IntSet lavaSet = new IntSet(QUEUE_CAPACITY * 2);
    private int lavaHead;
    private int lavaTail;
    private int lavaCount;
    private float lavaElapsed;

    /**
     * Xếp lịch cập nhật cho một ô chất lỏng cụ thể vào hàng đợi tương ứng (không cấp phát rác).
     *
     * @param x      tọa độ X thế giới
     * @param y      tọa độ Y thế giới
     * @param z      tọa độ Z thế giới
     * @param liquid loại chất lỏng ({@link Block#WATER} hoặc {@link Block#LAVA})
     */
    public void scheduleUpdate(int x, int y, int z, Block liquid) {
        if (x < 0 || x >= World.WORLD_SIZE_X || y < 0 || y >= World.WORLD_SIZE_Y
                || z < 0 || z >= World.WORLD_SIZE_Z) {
            return;
        }
        int packed = (x << 19) | (z << 8) | y;
        if (liquid == Block.WATER) {
            if (waterCount < waterQueue.length && waterSet.add(packed)) {
                waterQueue[waterTail] = packed;
                waterTail = (waterTail + 1) % waterQueue.length;
                waterCount++;
            }
        } else if (liquid == Block.LAVA) {
            if (lavaCount < lavaQueue.length && lavaSet.add(packed)) {
                lavaQueue[lavaTail] = packed;
                lavaTail = (lavaTail + 1) % lavaQueue.length;
                lavaCount++;
            }
        }
    }

    /**
     * Được gọi khi một ô trong thế giới thay đổi trong quá trình chơi (đặt/phá/nổ):
     * chỉ đánh thức các khối chất lỏng lân cận khi thay đổi có ảnh hưởng tới dòng chảy
     * (đặt/xóa chất lỏng, tạo khoảng trống {@code AIR}/{@code CROSS_PLANT}), tránh đánh thức
     * nhầm nước tĩnh sinh sẵn khi cỏ dưới đáy hồ chuyển thành đất.
     *
     * @param world thế giới voxel
     * @param x     tọa độ X của ô vừa đổi
     * @param y     tọa độ Y của ô vừa đổi
     * @param z     tọa độ Z của ô vừa đổi
     * @param oldId mã block trước khi đổi
     * @param newId mã block sau khi đổi
     */
    public void onBlockChanged(World world, int x, int y, int z, byte oldId, byte newId) {
        if (world == null) {
            return;
        }
        boolean involvesLiquid = isLiquidId(oldId) || isLiquidId(newId);
        boolean becameFlowable = canFlowInto(Block.fromId(newId));
        if (!involvesLiquid && !becameFlowable) {
            return;
        }
        scheduleIfLiquid(world, x, y, z);
        for (int dir = 0; dir < 6; dir++) {
            scheduleIfLiquid(world, x + DX[dir], y + DY[dir], z + DZ[dir]);
        }
    }

    /** Kiểm tra mã byte ID có phải Water hoặc Lava. */
    private static boolean isLiquidId(byte id) {
        return id == Block.WATER.getId() || id == Block.LAVA.getId();
    }

    /** Kiểm tra tọa độ hợp lệ và đưa vào hàng đợi nếu ô đang chứa Water hoặc Lava. */
    private void scheduleIfLiquid(World world, int x, int y, int z) {
        if (!world.isInsideWorld(x, y, z)) {
            return;
        }
        byte id = world.getBlock(x, y, z);
        if (id == Block.WATER.getId()) {
            scheduleUpdate(x, y, z, Block.WATER);
        } else if (id == Block.LAVA.getId()) {
            scheduleUpdate(x, y, z, Block.LAVA);
        }
    }

    /**
     * Cập nhật tiến trình chảy của Nước (mỗi 0.25s) và Dung nham (mỗi 1.50s) theo bước thời gian.
     * Mỗi nhịp chỉ xử lý tối đa {@value #MAX_UPDATES_PER_TICK} ô ở đầu hàng đợi; các ô mới sinh ra
     * sẽ nằm ở cuối hàng đợi để chờ tới chu kỳ kế tiếp.
     *
     * @param world thế giới voxel
     * @param dt    khoảng thời gian trôi qua (giây)
     */
    public void tick(World world, float dt) {
        if (world == null || dt <= 0.0f) {
            return;
        }

        // 1. Nhịp cập nhật dòng chảy Nước (0.25s)
        if (waterCount == 0) {
            waterElapsed = 0.0f;
        } else {
            waterElapsed += dt;
            while (waterElapsed >= WATER_FLOW_INTERVAL && waterCount > 0) {
                waterElapsed -= WATER_FLOW_INTERVAL;
                int batchCount = Math.min(waterCount, MAX_UPDATES_PER_TICK);
                for (int i = 0; i < batchCount; i++) {
                    int packed = waterQueue[waterHead];
                    waterHead = (waterHead + 1) % waterQueue.length;
                    waterCount--;
                    waterSet.remove(packed);

                    int x = packed >>> 19;
                    int y = packed & 0xFF;
                    int z = (packed >>> 8) & 0x7FF;
                    processLiquidCell(world, x, y, z, Block.WATER, WATER_FLOW_STEP);
                }
            }
            if (waterCount == 0) {
                waterElapsed = 0.0f;
            }
        }

        // 2. Nhịp cập nhật dòng chảy Dung nham (1.50s)
        if (lavaCount == 0) {
            lavaElapsed = 0.0f;
        } else {
            lavaElapsed += dt;
            while (lavaElapsed >= LAVA_FLOW_INTERVAL && lavaCount > 0) {
                lavaElapsed -= LAVA_FLOW_INTERVAL;
                int batchCount = Math.min(lavaCount, MAX_UPDATES_PER_TICK);
                for (int i = 0; i < batchCount; i++) {
                    int packed = lavaQueue[lavaHead];
                    lavaHead = (lavaHead + 1) % lavaQueue.length;
                    lavaCount--;
                    lavaSet.remove(packed);

                    int x = packed >>> 19;
                    int y = packed & 0xFF;
                    int z = (packed >>> 8) & 0x7FF;
                    processLiquidCell(world, x, y, z, Block.LAVA, LAVA_FLOW_STEP);
                }
            }
            if (lavaCount == 0) {
                lavaElapsed = 0.0f;
            }
        }
    }

    /** Xử lý phản ứng tạo Stone, suy giảm khi mất nguồn, chảy xuống dưới và lan ngang tại một ô. */
    private void processLiquidCell(World world, int x, int y, int z, Block liquid, int flowStep) {
        if (world.getBlock(x, y, z) != liquid.getId()) {
            return;
        }
        int state = liquid.normalizeState(world.getBlockState(x, y, z));
        Block opposite = (liquid == Block.WATER) ? Block.LAVA : Block.WATER;

        // 1. Kiểm tra tiếp xúc giữa Water và Lava ở 6 mặt kề nhau để tạo Block.STONE + tiếng xì
        for (int dir = 0; dir < 6; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];
            int nz = z + DZ[dir];
            if (!world.isInsideWorld(nx, ny, nz)) {
                continue;
            }
            if (world.getBlock(nx, ny, nz) == opposite.getId()) {
                if (DY[dir] > 0) {
                    // Chất lỏng đối nghịch ở ngay phía trên -> hóa đá tại chính ô đang xét
                    world.setBlock(x, y, z, Block.STONE.getId(), 0);
                    playFizzSound(world, x, y, z);
                    return;
                }
                world.setBlock(nx, ny, nz, Block.STONE.getId(), 0);
                playFizzSound(world, nx, ny, nz);
            }
        }

        // 2. Nếu là dòng chảy (state > 0), kiểm tra còn được cấp nước/nham từ trên hoặc từ ô nguồn gần hơn
        if (state > 0) {
            boolean hasAboveLiquid = y + 1 < World.WORLD_SIZE_Y && world.getBlock(x, y + 1, z) == liquid.getId();
            if (hasAboveLiquid) {
                if (state != 1) {
                    state = 1;
                    world.setBlock(x, y, z, liquid.getId(), 1);
                }
            } else {
                int minNeighborState = Integer.MAX_VALUE;
                for (int dir = 0; dir < 4; dir++) {
                    int nx = x + HDX[dir];
                    int nz = z + HDZ[dir];
                    if (!world.isInsideWorld(nx, y, nz) || world.getBlock(nx, y, nz) != liquid.getId()) {
                        continue;
                    }
                    int neighborState = liquid.normalizeState(world.getBlockState(nx, y, nz));
                    if (neighborState < minNeighborState) {
                        minNeighborState = neighborState;
                    }
                }
                int expectedState = (minNeighborState == Integer.MAX_VALUE)
                        ? (MAX_FLOW_LEVEL + 1)
                        : (minNeighborState + flowStep);
                if (expectedState > state) {
                    // Đã mất nguồn cấp đủ gần -> rút cạn ô này về AIR và lan truyền cho hạ nguồn
                    world.setBlock(x, y, z, Block.AIR.getId(), 0);
                    return;
                }
                if (expectedState < state) {
                    state = expectedState;
                    world.setBlock(x, y, z, liquid.getId(), state);
                }
            }
        }

        // 3. Ưu tiên chảy thẳng xuống dưới nếu ô dưới là AIR hoặc cây chữ X (CROSS_PLANT)
        if (y > 0) {
            Block below = Block.fromId(world.getBlock(x, y - 1, z));
            if (canFlowInto(below)) {
                flowInto(world, x, y - 1, z, liquid, 1, below);
                return;
            }
            if (below == liquid) {
                int belowState = liquid.normalizeState(world.getBlockState(x, y - 1, z));
                if (belowState > 1) {
                    world.setBlock(x, y - 1, z, liquid.getId(), 1);
                    return;
                }
                if (belowState == 1) {
                    // Đang là cột chảy thẳng xuống dưới -> không lan ngang giữa không trung
                    return;
                }
            }
        }

        // 4. Lan theo 4 hướng ngang trên bề mặt đỡ
        int nextState = state + flowStep;
        if (nextState > MAX_FLOW_LEVEL) {
            return;
        }
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + HDX[dir];
            int nz = z + HDZ[dir];
            if (!world.isInsideWorld(nx, y, nz)) {
                continue;
            }
            Block neighbor = Block.fromId(world.getBlock(nx, y, nz));
            if (canFlowInto(neighbor)) {
                flowInto(world, nx, y, nz, liquid, nextState, neighbor);
            } else if (neighbor == liquid && liquid.normalizeState(world.getBlockState(nx, y, nz)) > nextState) {
                world.setBlock(nx, y, nz, liquid.getId(), nextState);
            }
        }
    }

    /** Kiểm tra chất lỏng có thể chiếm chỗ ô mục tiêu hay không (AIR hoặc thực vật chữ X). */
    private static boolean canFlowInto(Block target) {
        return target == Block.AIR || target.getGeometryType() == Block.GeometryType.CROSS_PLANT;
    }

    /** Đổ chất lỏng vào ô mục tiêu; riêng Water sẽ rửa trôi cây chữ X thành ItemEntity rơi. */
    private static void flowInto(World world, int x, int y, int z, Block liquid, int nextState, Block replaced) {
        if (liquid == Block.WATER && replaced.getGeometryType() == Block.GeometryType.CROSS_PLANT) {
            replaced.onBreak(world, x, y, z);
        }
        world.setBlock(x, y, z, liquid.getId(), nextState);
    }

    /** Phát âm thanh xì hơi nước theo khoảng cách khi Water + Lava hóa thành Stone. */
    private static void playFizzSound(World world, int x, int y, int z) {
        AudioManager audio = world.getAudio();
        if (audio != null) {
            float gain = world.getAudioGain(x + 0.5f, y + 0.5f, z + 0.5f);
            if (gain > 0.0f) {
                audio.playEffect(AudioManager.Effect.FIZZ, FIZZ_VOLUME * gain);
            }
        }
    }
}

package com.voxelgame.world.level;

/** Sắp thứ tự chunk trong suốt ngay trên các mảng dùng lại giữa các khung hình. */
public final class TranslucentChunkSort {
    /** Tiện ích sắp xếp không lưu trạng thái giữa các lần gọi. */
    private TranslucentChunkSort() {
    }

    /** Dùng heapsort để đưa chunk xa lên trước, phá hòa bằng khóa tọa độ tăng dần. */
    public static void sort(Chunk[] chunks, float[] distances, int[] keys, int count) {
        // Gốc heap là phần tử cần được vẽ muộn nhất trong vùng còn lại.
        for (int root = count / 2 - 1; root >= 0; root--) {
            siftDown(chunks, distances, keys, root, count);
        }
        for (int end = count - 1; end > 0; end--) {
            swap(chunks, distances, keys, 0, end);
            siftDown(chunks, distances, keys, 0, end);
        }
    }

    /** Hạ phần tử gốc cho đến khi mỗi nút đứng sau các nút con trong thứ tự vẽ. */
    private static void siftDown(Chunk[] chunks, float[] distances, int[] keys, int root, int end) {
        int child = root * 2 + 1;
        while (child < end) {
            int right = child + 1;
            if (right < end && drawsLater(distances, keys, right, child)) {
                child = right;
            }
            if (!drawsLater(distances, keys, child, root)) {
                break;
            }
            swap(chunks, distances, keys, root, child);
            root = child;
            child = root * 2 + 1;
        }
    }

    /** Ưu tiên chunk gần hơn hoặc có khóa tọa độ lớn hơn để đặt cuối vùng chưa sắp. */
    private static boolean drawsLater(float[] distances, int[] keys, int first, int second) {
        return distances[first] < distances[second]
                || (distances[first] == distances[second] && keys[first] > keys[second]);
    }

    /** Hoán đổi cả tham chiếu chunk, khoảng cách và khóa để giữ ba mảng đồng bộ. */
    private static void swap(Chunk[] chunks, float[] distances, int[] keys, int first, int second) {
        Chunk chunk = chunks[first];
        chunks[first] = chunks[second];
        chunks[second] = chunk;

        float distance = distances[first];
        distances[first] = distances[second];
        distances[second] = distance;

        int key = keys[first];
        keys[first] = keys[second];
        keys[second] = key;
    }
}

