    /** Truy cập trực tiếp Chunk thô theo tọa độ chunk cho {@link ChunkLighting}. */
    Chunk getChunkRaw(int cx, int cy, int cz) {
        if (cx < 0 || cx >= WORLD_CHUNKS_X || cy < 0 || cy >= WORLD_CHUNKS_Y
                || cz < 0 || cz >= WORLD_CHUNKS_Z) {
            return null;
        }
        return chunks[cx][cy][cz];
    }

    /** Lấy hoặc tạo mới section chunk để lưu dữ liệu ánh sáng khác mặc định. */
    Chunk getOrCreateLightChunk(int cx, int cy, int cz, boolean createIfMissing) {
        if (cx < 0 || cx >= WORLD_CHUNKS_X || cy < 0 || cy >= WORLD_CHUNKS_Y
                || cz < 0 || cz >= WORLD_CHUNKS_Z) {
            return null;
        }
        Chunk chunk = chunks[cx][cy][cz];
        if (chunk == null && createIfMissing) {
            chunk = new Chunk(cx, cy, cz);
            chunk.markDirty();
            chunks[cx][cy][cz] = chunk;
        }
        return chunk;
    }

    /** Đánh dấu chunk bẩn nếu section chunk đang tồn tại trong bộ nhớ. */
    void markChunkDirtyIfExists(int cx, int cy, int cz) {
        Chunk chunk = getChunkRaw(cx, cy, cz);
        if (chunk != null) {
            chunk.markDirty();
        }
    }

    public boolean isInsideWorld(int worldX, int worldY, int worldZ) {
        return worldX >= 0 && worldX < WORLD_SIZE_X &&
                worldY >= 0 && worldY < WORLD_SIZE_Y &&
                worldZ >= 0 && worldZ < WORLD_SIZE_Z;
    }

    public byte getBlock(int worldX, int worldY, int worldZ) {
        if (!isInsideWorld(worldX, worldY, worldZ)) {
            return 0;
        }
        int cx = worldX / Chunk.SIZE;
        int cy = worldY / Chunk.SIZE;
        int cz = worldZ / Chunk.SIZE;

        int lx = worldX % Chunk.SIZE;
        int ly = worldY % Chunk.SIZE;
        int lz = worldZ % Chunk.SIZE;

        Chunk chunk = chunks[cx][cy][cz];
        return chunk == null ? Block.AIR.getId() : chunk.getBlockLocal(lx, ly, lz);
    }

    public boolean isSolidBlock(int worldX, int worldY, int worldZ) {
        return getCollisionBounds(worldX, worldY, worldZ) != null;
    }

    /**
     * Lấy mẫu đều trong mỗi section đã có dữ liệu, độc lập với cache mesh và tốc độ
     * khung hình.
     */
    private void updateRandomBlocks(float deltaTime) {
        if (player == null) {
            return;
        }
        randomTickElapsed += deltaTime;
        while (randomTickElapsed >= RANDOM_TICK_SECONDS) {
            randomTickElapsed -= RANDOM_TICK_SECONDS;
            player.copyPosition(randomTickPlayerPosition);
            int centerX = Math.floorDiv((int) Math.floor(randomTickPlayerPosition.x), Chunk.SIZE);
            int centerZ = Math.floorDiv((int) Math.floor(randomTickPlayerPosition.z), Chunk.SIZE);
            for (int dx = -RANDOM_TICK_RADIUS; dx <= RANDOM_TICK_RADIUS; dx++) {
                int cx = centerX + dx;
                if (cx < 0 || cx >= WORLD_CHUNKS_X) {
                    continue;
                }
                for (int dz = -RANDOM_TICK_RADIUS; dz <= RANDOM_TICK_RADIUS; dz++) {
                    int cz = centerZ + dz;
                    if (cz < 0 || cz >= WORLD_CHUNKS_Z
                            || dx * dx + dz * dz > RANDOM_TICK_RADIUS * RANDOM_TICK_RADIUS) {
                        continue;
                    }
                    for (int cy = 0; cy < WORLD_CHUNKS_Y; cy++) {
                        Chunk chunk = chunks[cx][cy][cz];
                        if (chunk == null) {
                            continue;
                        }
                        for (int sample = 0; sample < RANDOM_TICK_SAMPLES; sample++) {
                            int x = blockRandom.nextInt(Chunk.SIZE);
                            int y = blockRandom.nextInt(Chunk.SIZE);
                            int z = blockRandom.nextInt(Chunk.SIZE);
                            byte localId = chunk.getBlockLocal(x, y, z);
                            if (localId == Block.GRASS.getId()) {
                                ((GrassBlock) Block.GRASS).randomTick(this, cx * Chunk.SIZE + x,
                                        cy * Chunk.SIZE + y, cz * Chunk.SIZE + z, blockRandom);
                            } else if (LeafDecaySystem.isLeafId(localId)
                                    && (chunk.getStateLocal(x, y, z) & LeafDecaySystem.PERSISTENT_LEAF_STATE) == 0) {
                                LeafDecaySystem.tickLeaf(this, cx * Chunk.SIZE + x,
                                        cy * Chunk.SIZE + y, cz * Chunk.SIZE + z);
                                if (chunks[cx][cy][cz] == null) {
                                    break;
                                }
                            }
                        }
                    }
                    // Chuẩn Minecraft: khi đang giáng thủy, mỗi cột chunk có xác suất 1/16 mỗi tick
                    // để đóng băng hoặc phủ 1 lớp tuyết.
                    if (weather != null && weather.strength() > 0.5f && blockRandom.nextInt(16) == 0) {
                        int sampleX = cx * Chunk.SIZE + blockRandom.nextInt(Chunk.SIZE);
                        int sampleZ = cz * Chunk.SIZE + blockRandom.nextInt(Chunk.SIZE);
                        if (sampleX < WORLD_SIZE_X) {
                            accumulateSnow(sampleX, sampleZ, player, false);
                        }
                    }
                }
            }
        }
    }

    /** Trả chất lỏng chứa điểm thế giới, xét đúng mặt thoáng của voxel. */
    public Block liquidAt(float x, float y, float z) {
        int blockX = (int) Math.floor(x);
        int blockY = (int) Math.floor(y);
        int blockZ = (int) Math.floor(z);
        Block block = Block.fromId(getBlock(blockX, blockY, blockZ));
        return block.isLiquid() && y < blockY + block.getTopHeight(this, blockX, blockY, blockZ)
                ? block
                : Block.AIR;
    }

    /** Trả độ cao bề mặt chặn giáng thủy, kể cả mặt chất lỏng và lớp tuyết thấp. */
    public float getPrecipitationSurface(int x, int z) {
        int y = findWeatherSurface(x, z, true);
        if (y < 0) {
            return 0f;
        }
        Block block = Block.fromId(getBlock(x, y, z));
        if (block.isLiquid()) {
            return y + block.getTopHeight(this, x, y, z);
        }
        return y + block.getSelectionBounds(getBlockState(x, y, z)).maxY();
    }

    /** Tán lá và các khối rắn che tai người chơi, kể cả khi mắt đang dưới nước. */
    public boolean hasWeatherRoof(int x, float eyeY, int z) {
        int y = findWeatherSurface(x, z, false);
        return y >= 0 && y + Block.fromId(getBlock(x, y, z))
                .getSelectionBounds(getBlockState(x, y, z)).maxY() > eyeY;
    }

    /** Duyệt từ trên xuống, bỏ qua cả chunk rỗng trước khi xem các ô trong cột. */
    private int findWeatherSurface(int x, int z, boolean includeLiquids) {
        if (!isInsideWorld(x, 0, z)) {
            return -1;
        }
        Chunk[][] column = chunks[x / Chunk.SIZE];
        int localX = x % Chunk.SIZE;
        int localZ = z % Chunk.SIZE;
        int chunkZ = z / Chunk.SIZE;
        for (int chunkY = WORLD_CHUNKS_Y - 1; chunkY >= 0; chunkY--) {
            Chunk chunk = column[chunkY][chunkZ];
            if (chunk == null) {
                continue;
            }
            for (int localY = Chunk.SIZE - 1; localY >= 0; localY--) {
                Block block = Block.fromId(chunk.getBlockLocal(localX, localY, localZ));
                if (block.isSolid() || (includeLiquids && block.isLiquid())) {
                    return chunkY * Chunk.SIZE + localY;
                }
            }
        }
        return -1;
    }

    /**
     * Thử đóng băng hoặc phủ 1 lớp tuyết trên bề mặt lộ thiên theo chuẩn
     * snowAccumulationHeight = 1.
     */
    void accumulateSnow(int x, int z, Player player, boolean thicken) {
        if (!isInsideWorld(x, 0, z) || !getBiome(x, z).hasSnow()) {
            return;
        }
        int y = findWeatherSurface(x, z, true);
        if (y < 0) {
            return;
        }
        Block top = Block.fromId(getBlock(x, y, z));
        if (top == Block.WATER) {
            if (getBlock(x, y + 1, z) == Block.AIR.getId() && !hasLavaNear(x, y, z)
                    && !intersectsPlayer(player, Block.ICE, 0, x, y, z)) {
                setBlock(x, y, z, Block.ICE.getId());
            }
        } else if (top != Block.SNOW_LAYER && top != Block.SNOW_BLOCK && !hasLavaNear(x, y + 1, z)) {
            tryPlaceBlock(x, y + 1, z, Block.SNOW_LAYER, player);
        }
    }

    /** Đọc metadata dạng không dấu. Ô mặc định và chunk rỗng trả về 0. */
    public int getBlockState(int x, int y, int z) {
        if (!isInsideWorld(x, y, z)) {
            return 0;
        }
        Chunk chunk = chunks[x / Chunk.SIZE][y / Chunk.SIZE][z / Chunk.SIZE];
        return chunk == null ? 0 : chunk.getStateLocal(x % Chunk.SIZE, y % Chunk.SIZE, z % Chunk.SIZE);
    }

    /** Lấy hộp cục bộ đúng theo loại block và trạng thái hiện tại. */
    public Block.Bounds getCollisionBounds(int x, int y, int z) {
        return Block.fromId(getBlock(x, y, z)).getCollisionBounds(getBlockState(x, y, z));
    }

    /** Ghi block mặc định khi chơi rồi xử lý chuỗi thay đổi. */
    public void setBlock(int worldX, int worldY, int worldZ, byte blockId) {
        setBlock(worldX, worldY, worldZ, blockId, 0);
    }

    /** Ghi block có metadata rồi xử lý lân cận sau khi các ô đã nhất quán. */
    public void setBlock(int x, int y, int z, byte blockId, int state) {
        writeGameplayBlock(x, y, z, blockId, state);
        drainBlockUpdates();
    }

    /**
     * Ghi một ô, dọn nửa cỏ cũ nếu có, cập nhật ánh sáng BFS và xếp lịch các luật
     * phụ thuộc.
     */
    private void writeGameplayBlock(int x, int y, int z, byte blockId, int state) {
        byte oldId = getBlock(x, y, z);
        int oldState = getBlockState(x, y, z);
        int normalizedState = Block.fromId(blockId).normalizeState(state);
        boolean lit = isInsideWorld(x, y, z) && lighting.isColumnLit(x / Chunk.SIZE, z / Chunk.SIZE);
        if (lit) {
            lighting.ensureColumnLit(this, x / Chunk.SIZE, z / Chunk.SIZE);
        }
        boolean changed;
        incrementalLightingUpdate = lit;
        try {
            changed = setBlockInternal(x, y, z, blockId, normalizedState);
        } finally {
            incrementalLightingUpdate = false;
        }
        if (!changed) {
            return;
        }
        if (lit) {
            lighting.onBlockChanged(this, x, y, z, oldId, blockId);
        }
        scheduleChangedBlock(x, y, z, oldId, blockId);
        if (oldId == Block.TALL_GRASS.getId() && (blockId != oldId || oldState != state)) {
            int otherY = oldState == 0 ? y + 1 : y - 1;
            if (getBlock(x, otherY, z) == oldId && getBlockState(x, otherY, z) == 1 - oldState) {
                boolean otherLit = isInsideWorld(x, otherY, z)
                        && lighting.isColumnLit(x / Chunk.SIZE, z / Chunk.SIZE);
                if (otherLit) {
                    lighting.ensureColumnLit(this, x / Chunk.SIZE, z / Chunk.SIZE);
                }
                boolean otherChanged;
                incrementalLightingUpdate = otherLit;
                try {
                    otherChanged = setBlockInternal(x, otherY, z, Block.AIR.getId(), 0);
                } finally {
                    incrementalLightingUpdate = false;
                }
                if (otherChanged) {
                    if (otherLit) {
                        lighting.onBlockChanged(this, x, otherY, z, oldId, Block.AIR.getId());
                    }
                    scheduleChangedBlock(x, otherY, z, oldId, Block.AIR.getId());
                }
            }
        }
    }

    /** Đánh dấu mesh và đưa các ô phụ thuộc vào hàng đợi FIFO. */
    private void scheduleChangedBlock(int worldX, int worldY, int worldZ, byte oldId, byte newId) {
        int cx = worldX / Chunk.SIZE;
        int cy = worldY / Chunk.SIZE;
        int cz = worldZ / Chunk.SIZE;

        int lx = worldX % Chunk.SIZE;
        int ly = worldY % Chunk.SIZE;
        int lz = worldZ % Chunk.SIZE;

        // AO và mặt chất lỏng có thể phụ thuộc ô ở chunk chung mặt, cạnh hoặc góc.
        int minX = lx == 0 && cx > 0 ? -1 : 0;
        int maxX = lx == Chunk.SIZE - 1 && cx + 1 < WORLD_CHUNKS_X ? 1 : 0;
        int minY = ly == 0 && cy > 0 ? -1 : 0;
        int maxY = ly == Chunk.SIZE - 1 && cy + 1 < WORLD_CHUNKS_Y ? 1 : 0;
        int minZ = lz == 0 && cz > 0 ? -1 : 0;
        int maxZ = lz == Chunk.SIZE - 1 && cz + 1 < WORLD_CHUNKS_Z ? 1 : 0;
        for (int dx = minX; dx <= maxX; dx++) {
            for (int dy = minY; dy <= maxY; dy++) {
                for (int dz = minZ; dz <= maxZ; dz++) {
                    if (dx != 0 || dy != 0 || dz != 0) {
                        markChunkDirty(cx + dx, cy + dy, cz + dz);
                    }
                }
            }
        }

        blockUpdates.add(worldX, worldY, worldZ);
        blockUpdates.add(worldX - 1, worldY, worldZ);
        blockUpdates.add(worldX + 1, worldY, worldZ);
        blockUpdates.add(worldX, worldY - 1, worldZ);
        blockUpdates.add(worldX, worldY + 1, worldZ);
        blockUpdates.add(worldX, worldY, worldZ - 1);
        blockUpdates.add(worldX, worldY, worldZ + 1);
        if (oldId == Block.WATER.getId() || newId == Block.WATER.getId()) {
            // Nước cạnh ô nền nằm thấp hơn gốc mía một ô.
            blockUpdates.add(worldX - 1, worldY + 1, worldZ);
            blockUpdates.add(worldX + 1, worldY + 1, worldZ);
            blockUpdates.add(worldX, worldY + 1, worldZ - 1);
            blockUpdates.add(worldX, worldY + 1, worldZ + 1);
        }
        if (newId == Block.LAVA.getId()) {
            for (int dx = -2; dx <= 2; dx++) {
                for (int dy = -2; dy <= 2; dy++) {
                    int reach = 2 - Math.abs(dx) - Math.abs(dy);
                    for (int dz = -reach; dz <= reach; dz++) {
                        blockUpdates.add(worldX + dx, worldY + dy, worldZ + dz);
                    }
                }
            }
        }
        if ((LeafDecaySystem.isLogId(oldId) || LeafDecaySystem.isLeafId(oldId)) && newId != oldId) {
            LeafDecaySystem.notifyNeighbors(this, worldX, worldY, worldZ);
        }
        liquidFlow.onBlockChanged(this, worldX, worldY, worldZ, oldId, newId);
    }

    /** Trả về bộ mô phỏng dòng chảy chất lỏng gắn với thế giới hiện tại. */
    public LiquidFlowSimulator getLiquidFlow() {
        return liquidFlow;
    }

    /**
     * Xếp lịch kiểm tra phân hủy trễ cho lá tự nhiên bằng hàng đợi không cấp phát
     * rác.
     */
    void scheduleLeafDecayCheck(int x, int y, int z) {
        leafDecay.schedule(x, y, z);
    }

    /** Xử lý cho đến khi các thay đổi dây chuyền kết thúc, tránh gọi đệ quy. */
    private void drainBlockUpdates() {
        if (drainingBlockUpdates) {
            return;
        }
        drainingBlockUpdates = true;
        try {
            while (blockUpdates.hasNext()) {
                int packed = blockUpdates.next();
                int x = packed >>> 19;
                int y = packed & 0xff;
                int z = (packed >>> 8) & 0x7ff;
                Block block = Block.fromId(getBlock(x, y, z));
                if ((block == Block.ICE || block == Block.SNOW_LAYER) && hasLavaNear(x, y, z)) {
                    Block melted = block == Block.ICE ? Block.WATER : Block.AIR;
                    writeGameplayBlock(x, y, z, melted.getId(), 0);
                } else if (block.isGravityBlock() && getCollisionBounds(x, y - 1, z) == null) {
                    writeGameplayBlock(x, y, z, Block.AIR.getId(), 0);
                    entities.add(new FallingBlockEntity(x, y, z, block));
                } else if (block != Block.AIR) {
                    block.onNeighborChange(this, x, y, z);
                }
            }
        } finally {
            blockUpdates.clear();
            drainingBlockUpdates = false;
        }
    }

    /** Tìm dung nham trong bán kính Manhattan hai ô. */
    public boolean hasLavaNear(int x, int y, int z) {
        for (int dx = -2; dx <= 2; dx++) {
            for (int dy = -2; dy <= 2; dy++) {
                int reach = 2 - Math.abs(dx) - Math.abs(dy);
                for (int dz = -reach; dz <= reach; dz++) {
                    if (getBlock(x + dx, y + dy, z + dz) == Block.LAVA.getId()) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Kiểm tra và cam kết thao tác đặt, kể cả hai ô đồng thời của cỏ cao. */
    public boolean tryPlaceBlock(int x, int y, int z, Block block, Player placingPlayer) {
        return tryPlaceBlock(x, y, z, block, 0, placingPlayer);
    }

    /**
     * Kiểm tra và cam kết thao tác đặt với metadata ban đầu (như state = 1 cho lá
     * đặt tay).
     */
    public boolean tryPlaceBlock(int x, int y, int z, Block block, int state, Player placingPlayer) {
        int normalizedState = block.normalizeState(state);
        if (!isInsideWorld(x, y, z) || block == Block.AIR || !block.canPlaceAt(this, x, y, z)
                || !canReplace(x, y, z, block) || intersectsPlayer(placingPlayer, block, normalizedState, x, y, z)) {
            return false;
        }
        if (block == Block.TALL_GRASS && (!isInsideWorld(x, y + 1, z)
                || getBlock(x, y + 1, z) != Block.AIR.getId())) {
            return false;
        }
        writeGameplayBlock(x, y, z, block.getId(), block == Block.TALL_GRASS ? 0 : normalizedState);
        if (block == Block.TALL_GRASS) {
            writeGameplayBlock(x, y + 1, z, block.getId(), 1);
        }
        drainBlockUpdates();
        return true;
    }

    /** Chỉ lớp tuyết mỏng và thực vật có thể nhường chỗ cho khối rắn. */
    private boolean canReplace(int x, int y, int z, Block placed) {
        Block existing = Block.fromId(getBlock(x, y, z));
        return existing == Block.AIR || existing != placed
                && existing.isReplaceable(getBlockState(x, y, z))
                && (existing.isLiquid() || placed.getCollisionBounds(0) != null);
    }

    /** Tăng độ dày của lớp tuyết hiện có nếu còn chỗ. */
    public boolean tryStackSnow(int x, int y, int z, Player placingPlayer) {
        if (getBlock(x, y, z) != Block.SNOW_LAYER.getId()) {
            return false;
        }
        int state = getBlockState(x, y, z);
        if (state == 7 || intersectsPlayer(placingPlayer, Block.SNOW_LAYER, state + 1, x, y, z)) {
            return false;
        }
        setBlock(x, y, z, Block.SNOW_LAYER.getId(), state + 1);
        return true;
    }

    /** Chỉ hộp va chạm của block mới có thể cản người chơi. */
    private boolean intersectsPlayer(Player placingPlayer, Block block, int state, int x, int y, int z) {
        Block.Bounds bounds = block.getCollisionBounds(state);
        return placingPlayer != null && bounds != null && placingPlayer.intersectsBlock(x, y, z, bounds);
    }

    /** Đánh dấu mesh lân cận cần dựng lại, giữ nguyên các ô chỉ chứa không khí. */
    private void markChunkDirty(int cx, int cy, int cz) {
        Chunk chunk = chunks[cx][cy][cz];
        if (chunk != null) {
            chunk.markDirty();
        }
    }

    /**
     * Đập vỡ hoàn toàn một Block tại `(worldX, worldY, worldZ)` và kích hoạt hành
     * vi đa hình `target.onBreak(...)`.
     *
     * @param worldX tọa độ X thế giới
     * @param worldY tọa độ Y thế giới
     * @param worldZ tọa độ Z thế giới
     */
    public void breakBlockAndSpawnDrop(int worldX, int worldY, int worldZ) {
        Block target = Block.fromId(getBlock(worldX, worldY, worldZ));
        if (!target.isBreakable()) {
            return;
        }

        Block replacement = target.getBreakReplacement(this, worldX, worldY, worldZ);
        writeGameplayBlock(worldX, worldY, worldZ, replacement.getId(), 0);
        if (audio != null) {
            audio.playBreak(target, getAudioGain(worldX + 0.5f, worldY + 0.5f, worldZ + 0.5f));
        }
        target.onBreak(this, worldX, worldY, worldZ);
        drainBlockUpdates();
    }

    /**
     * Phá vỡ tức thì một khối trong chế độ Creative (cho phép phá cả
     * {@link Block#BEDROCK})
     * mà không sinh {@link ItemEntity}, vẫn phát âm thanh và kích hoạt cập nhật
     * khối lân cận.
     *
     * @param worldX tọa độ X thế giới
     * @param worldY tọa độ Y thế giới
     * @param worldZ tọa độ Z thế giới
     * @return {@code true} nếu khối đã được phá vỡ
     */
    public boolean breakBlockWithoutDrop(int worldX, int worldY, int worldZ) {
        Block target = Block.fromId(getBlock(worldX, worldY, worldZ));
        if (target == Block.AIR || target.isLiquid()) {
            return false;
        }
        writeGameplayBlock(worldX, worldY, worldZ, Block.AIR.getId(), 0);
        if (audio != null) {
            audio.playBreak(target, getAudioGain(worldX + 0.5f, worldY + 0.5f, worldZ + 0.5f));
        }
        drainBlockUpdates();
        return true;
    }

    /**
     * Gây sát thương tỏa tròn và ghi các ô phá được bằng cùng đường cập nhật block
     * lúc chơi.
     */
    public void explode(Entity source, float x, float y, float z, float radius, float maxDamage) {
        float radiusSquared = radius * radius;
        for (int i = 0, count = entities.size(); i < count; i++) {
            if (!(entities.get(i) instanceof LivingEntity living) || living == source || !living.isAlive()) {
                continue;
            }
            living.copyCenterPosition(blastTarget);
            float dx = blastTarget.x - x;
            float dz = blastTarget.z - z;
            float distanceSquared = blastTarget.dst2(x, y, z);
            if (distanceSquared < radiusSquared) {
                float power = 1f - (float) Math.sqrt(distanceSquared) / radius;
                float horizontal = (float) Math.sqrt(dx * dx + dz * dz);
                float push = horizontal > 0.0001f ? 12f * power / horizontal : 0f;
                living.damage(this, maxDamage * power, DamageSource.EXPLOSION, source, dx * push, dz * push);
            }
        }
        int minX = Math.max(0, (int) Math.floor(x - radius));
        int minY = Math.max(0, (int) Math.floor(y - radius));
        int minZ = Math.max(0, (int) Math.floor(z - radius));
        int maxX = Math.min(WORLD_SIZE_X - 1, (int) Math.floor(x + radius));
        int maxY = Math.min(WORLD_SIZE_Y - 1, (int) Math.floor(y + radius));
        int maxZ = Math.min(WORLD_SIZE_Z - 1, (int) Math.floor(z + radius));
        for (int bx = minX; bx <= maxX; bx++) {
            float dx = bx + 0.5f - x;
            for (int by = minY; by <= maxY; by++) {
                float dy = by + 0.5f - y;
                for (int bz = minZ; bz <= maxZ; bz++) {
                    float dz = bz + 0.5f - z;
                    if (dx * dx + dy * dy + dz * dz <= radiusSquared
                            && Block.fromId(getBlock(bx, by, bz)).isBreakable()) {
                        writeGameplayBlock(bx, by, bz, Block.AIR.getId(), 0);
                    }
                }
            }
        }
        // Chạy một đợt sau khi tất cả ô đã đổi để cát, sỏi và cây bên rìa phản ứng theo
        // nền cuối.
        drainBlockUpdates();
    }

    /**
     * Vẽ các chunk giao khung nhìn và duyệt danh sách đa hình để vẽ các thực thể
     * 3D.
     *
     * @param shader     chương trình Shader đang kích hoạt
     * @param projection ma trận chiếu phối cảnh đã truyền vào shader
     * @param view       ma trận nhìn đã truyền vào shader
     */
    public void render(ShaderProgram shader, Matrix4 projection, Matrix4 view) {
        render(shader, projection, view, null);
    }

    /** Dựng các chunk gần camera rồi vẽ pha đục và pha trong suốt theo thứ tự. */
    public void render(ShaderProgram shader, Matrix4 projection, Matrix4 view, Vector3 cameraPosition) {
        render(shader, projection, view, cameraPosition, null);
    }

    /**
     * Cho phép vẽ tầng mây sau pha ghi chiều sâu và trước khi hòa màu nước/băng.
     */
    public void render(ShaderProgram shader, Matrix4 projection, Matrix4 view, Vector3 cameraPosition,
            Runnable beforeTranslucent) {
        render(shader, projection, view, cameraPosition, beforeTranslucent, Float.POSITIVE_INFINITY);
    }

    /**
     * Bỏ các chunk nằm hoàn toàn ngoài tầm nhìn màu sắc khi sương đạt độ đậm tối
     * đa.
     */
    public void render(ShaderProgram shader, Matrix4 projection, Matrix4 view, Vector3 cameraPosition,
            Runnable beforeTranslucent, float drawDistance) {
        // libGDX dùng nghịch đảo của Projection × View để dựng sáu mặt phẳng khung
        // nhìn.
        inverseViewProjection.set(projection).mul(view).inv();
        frustum.update(inverseViewProjection);
        // Tâm mặt phẳng gần xấp xỉ vị trí mắt và ưu tiên được cả các chunk theo độ cao.
        nearCenter.set(0, 0, -1).prj(inverseViewProjection);
        renderFrame++;
        pendingMeshCount = 0;
        visibleChunkCount = 0;

        Vector3 eye = cameraPosition == null ? nearCenter : cameraPosition;
        collectVisibleChunks(eye, drawDistance);
        for (int i = 0; i < pendingMeshCount; i++) {
            Chunk chunk = pendingMeshes[i];
            pendingMeshes[i] = null;
            rebuildChunkMesh(chunk);
        }
        releaseOffscreenMeshes();

        int translucentCount = 0;
        Arrays.fill(opaqueHead, -1);
        for (int i = 0; i < visibleChunkCount; i++) {
            Chunk chunk = visibleChunks[i];
            float distance = chunk.centerDistanceSquaredTo(eye);
            if (chunk.hasOpaqueMesh()) {
                int bin = Math.min(OPAQUE_BINS - 1, (int) Math.sqrt(distance) / Chunk.SIZE);
                if (opaqueHead[bin] < 0) {
                    opaqueHead[bin] = i;
                } else {
                    opaqueNext[opaqueTail[bin]] = i;
                }
                opaqueTail[bin] = i;
                opaqueNext[i] = -1;
            }
            if (chunk.hasTranslucentMesh()) {
                translucentChunks[translucentCount] = chunk;
                translucentDistances[translucentCount] = distance;
                translucentKeys[translucentCount] = i;
                translucentCount++;
            }
        }
        shader.setUniformMatrix4f("uModel", identityMatrix);
        shader.enableChunkColorMode(true);
        try {
            for (int head : opaqueHead) {
                for (int i = head; i >= 0; i = opaqueNext[i]) {
                    visibleChunks[i].render(shader);
                }
            }
        } finally {
            shader.enableChunkColorMode(false);
        }
        Arrays.fill(visibleChunks, 0, visibleChunkCount, null);
        // Thực thể đục phải ghi chiều sâu trước khi vẽ nước và băng.
        boolean hasVisualMob = false;
        boolean boundItemAtlas = false;
        for (int i = 0; i < entities.size(); i++) {
            Entity entity = entities.get(i);
            if (mobRenderer != null && entity instanceof MobVisual) {
                hasVisualMob = true;
            } else if (entity instanceof ItemEntity itemEntity && itemEntity.isStandaloneItem()) {
                if (itemAtlas != null) {
                    if (!boundItemAtlas) {
                        itemAtlas.bind();
                        boundItemAtlas = true;
                    }
                    itemEntity.render(shader);
                }
            } else {
                if (boundItemAtlas && blockAtlas != null) {
                    blockAtlas.bind();
                    boundItemAtlas = false;
                }
                entity.render(shader);
            }
        }
        if (boundItemAtlas && blockAtlas != null) {
            blockAtlas.bind();
        }
        if (hasVisualMob) {
            mobRenderer.render(entities, shader, frustum, eye, drawDistance);
        }
        shader.setUniformMatrix4f("uModel", identityMatrix);
        if (beforeTranslucent != null) {
            beforeTranslucent.run();
        }
        renderTranslucent(shader, translucentCount);
    }

    /** Sắp xếp xa tới gần và vẽ pha trong suốt bằng các mảng dùng lại. */
    private void renderTranslucent(ShaderProgram shader, int count) {
        if (count == 0) {
            return;
        }
        TranslucentChunkSort.sort(translucentChunks, translucentDistances, translucentKeys, count);
        Gdx.gl.glDepthMask(false);
        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        shader.enableChunkColorMode(true);
        try {
            for (int i = 0; i < count; i++) {
                translucentChunks[i].renderTranslucent(shader);
            }
        } finally {
            shader.enableChunkColorMode(false);
            Gdx.gl.glDepthMask(true);
            Gdx.gl.glDisable(GL20.GL_BLEND);
            for (int i = 0; i < count; i++) {
                translucentChunks[i] = null;
            }
        }
    }

    /** Duyệt khung nhìn theo thứ tự tọa độ X, Y, Z để khóa hòa ổn định. */
    private void collectVisibleChunks(Vector3 eye, float range) {
        float minX = Float.POSITIVE_INFINITY;
        float minZ = Float.POSITIVE_INFINITY;
        float maxX = Float.NEGATIVE_INFINITY;
        float maxZ = Float.NEGATIVE_INFINITY;
        for (Vector3 corner : frustum.planePoints) {
            minX = Math.min(minX, corner.x);
            minZ = Math.min(minZ, corner.z);
            maxX = Math.max(maxX, corner.x);
            maxZ = Math.max(maxZ, corner.z);
        }
        minX = Math.max(minX, eye.x - range);
        minZ = Math.max(minZ, eye.z - range);
        maxX = Math.min(maxX, eye.x + range);
        maxZ = Math.min(maxZ, eye.z + range);
        float rangeSquared = range * range;
        // Mở rộng thêm một ô ở mép dưới để tính cả chunk tiếp xúc mặt hộp bao.
        int firstX = Math.max(0, (int) Math.floor(minX / Chunk.SIZE) - 1);
        int firstZ = Math.max(0, (int) Math.floor(minZ / Chunk.SIZE) - 1);
        int lastX = Math.min(WORLD_CHUNKS_X - 1, (int) Math.floor(maxX / Chunk.SIZE));
        int lastZ = Math.min(WORLD_CHUNKS_Z - 1, (int) Math.floor(maxZ / Chunk.SIZE));
        for (int cx = firstX; cx <= lastX; cx++) {
            for (int cy = 0; cy < WORLD_CHUNKS_Y; cy++) {
                for (int cz = firstZ; cz <= lastZ; cz++) {
                    Chunk chunk = chunks[cx][cy][cz];
                    // Chunk sạch từng dựng mà không có mặt lộ chỉ cần xét lại khi được đánh dấu
                    // bẩn.
                    if (chunk != null && (chunk.isDirty() || chunk.hasMesh())
                            && chunk.distanceSquaredTo(eye) <= rangeSquared && chunk.intersectsFrustum(frustum)) {
                        chunk.lastVisibleFrame = renderFrame;
                        if (chunk.isDirty()) {
                            queueMeshBuild(chunk);
                        }
                        visibleChunks[visibleChunkCount++] = chunk;
                    }
                }
            }
        }
    }

    /** Giữ danh sách hữu hạn các mesh cần dựng, sắp theo khoảng cách tới camera. */
    private void queueMeshBuild(Chunk chunk) {
        float distance = chunk.distanceSquaredTo(nearCenter);
        int index = pendingMeshCount;
        if (index == pendingMeshes.length) {
            index--;
            if (distance >= pendingDistances[index]) {
                return;
            }
        } else {
            pendingMeshCount++;
        }
        while (index > 0 && distance < pendingDistances[index - 1]) {
            pendingMeshes[index] = pendingMeshes[index - 1];
            pendingDistances[index] = pendingDistances[index - 1];
            index--;
        }
        pendingMeshes[index] = chunk;
        pendingDistances[index] = distance;
    }

    /** Dựng mesh và đồng bộ danh sách tài nguyên đang được giữ. */
    private void rebuildChunkMesh(Chunk chunk) {
        boolean hadMesh = chunk.hasMesh();
        chunk.rebuildMesh(this, meshVertices, translucentVertices);
        if (!hadMesh && chunk.hasMesh()) {
            residentMeshes.add(chunk);
        } else if (hadMesh && !chunk.hasMesh()) {
            residentMeshes.removeValue(chunk, true);
        }
    }

    /**
     * Thu hồi mesh đã ở ngoài khung nhìn đủ lâu, giữ dữ liệu block và các sửa đổi.
     */
    private void releaseOffscreenMeshes() {
        for (int i = residentMeshes.size - 1; i >= 0; i--) {
            Chunk chunk = residentMeshes.get(i);
            if (renderFrame - chunk.lastVisibleFrame >= MESH_RETENTION_FRAMES) {
                chunk.releaseCachedMesh();
                residentMeshes.removeIndex(i);
            }
        }
    }

    /**
     * Giải phóng các mesh đang còn trong bộ nhớ và tài nguyên dùng chung của vật
     * phẩm.
     */
    @Override
    public void dispose() {
        for (int i = 0; i < residentMeshes.size; i++) {
            residentMeshes.get(i).dispose();
        }
        residentMeshes.clear();
        ItemEntity.cleanupSharedMeshes();
    }
}

package com.voxelgame.world.level;

/** Đồng hồ thế giới chạy liên tục, với 24.000 tick mỗi ngày và 20 tick mỗi giây. */
public final class WorldTime {
    /** Bốn mốc quỹ đạo cách nhau đúng một phần tư ngày. */
    private static final int TICKS_PER_DAY = 24_000;
    private static final int TICKS_PER_QUARTER = TICKS_PER_DAY / 4;
    private static final double FULL_TURN = Math.PI * 2.0;

    /** Dùng tick lẻ cho chuyển động mượt giữa hai khung hình. */
    private double tick = 1_000;
    private long dayCount;
    private boolean fastForward;
    private boolean visitedMilestone;
    private float sunX;
    private float sunY;

    /** Cập nhật ngay quỹ đạo theo giờ sáng khi khởi tạo. */
    public WorldTime() {
        updateOrbit();
    }

    /** Tiến đồng hồ khi đang chơi và đếm số lần qua bình minh. */
    public void update(double seconds) {
        tick += seconds * (fastForward ? 400 : 20);
        long elapsedDays = (long) (tick / TICKS_PER_DAY);
        dayCount += elapsedDays;
        tick -= elapsedDays * TICKS_PER_DAY;
        updateOrbit();
    }

    /** Lần đầu đưa về bình minh; các lần tiếp theo nhảy tới mốc chuẩn kế tiếp. */
    public void nextMilestone() {
        tick = visitedMilestone ? ((int) tick / TICKS_PER_QUARTER + 1) * TICKS_PER_QUARTER : 0;
        visitedMilestone = true;
        update(0);
    }

    /** Chuyển tốc độ đồng hồ giữa 1× và 20×. */
    public void toggleFastForward() {
        fastForward = !fastForward;
    }

    /** Làm chậm quỹ đạo gần chân trời, giữ nguyên bốn hướng tại các mốc chuẩn. */
    private void updateOrbit() {
        double angle = tick / TICKS_PER_DAY * FULL_TURN;
        double curved = angle - 0.08 * Math.sin(2 * angle);
        sunX = (float) Math.cos(curved);
        sunY = (float) Math.sin(curved);
    }

    /** Thành phần Đông–Tây của hướng mặt trời, dương về Đông. */
    public float sunX() {
        return sunX;
    }

    /** Thành phần độ cao của mặt trời, dương phía trên chân trời. */
    public float sunY() {
        return sunY;
    }

    /** Số ngày đã trôi qua kể từ lần vào thế giới đầu tiên. */
    public long dayCount() {
        return dayCount;
    }

    /** Trả chỉ số tick trong ngày, dùng để đánh giá khoảng tối của bầu trời. */
    public int tickOfDay() {
        return (int) tick;
    }

    /** Giờ dân dụng bắt đầu ở 06:00 khi tick trong ngày bằng 0. */
    public int minuteOfDay() {
        return ((int) (tick * 1_440 / TICKS_PER_DAY) + 360) % 1_440;
    }
}

package com.voxelgame.world.level.biome;

import com.voxelgame.world.entity.mob.MobCategory;
import com.voxelgame.world.entity.mob.MobSpawnTable;
import com.voxelgame.world.level.weather.Weather;

/**
 * Lớp trừu tượng gốc đại diện cho một quần xã sinh học (Biome) theo mẫu thiết kế Flyweight / Strategy.
 * Mỗi lớp con đóng gói toàn bộ đặc tính khí hậu, bảng màu cỏ/lá, thời tiết giáng thủy
 * và bảng sinh mob đặc thù của riêng mình, đồng thời ánh xạ O(1) với khóa hiệu năng {@link BiomeType}.
 */
public abstract class Biome {

    /** Bảng tra cứu O(1) bất biến nối 5 giá trị {@link BiomeType} tới đúng 5 singleton {@link Biome}. */
    private static final Biome[] BY_TYPE = new Biome[BiomeType.values().length];

    static {
        register(SnowyPlainsBiome.INSTANCE);
        register(ForestBiome.INSTANCE);
        register(PlainsBiome.INSTANCE);
        register(FlowerForestBiome.INSTANCE);
        register(DesertBiome.INSTANCE);
    }

    /** Constructor bảo vệ chỉ cho 5 lớp con cụ thể khởi tạo singleton. */
    protected Biome() {
    }

    /** Đăng ký singleton biome vào mảng tra cứu theo ordinal của {@link BiomeType}. */
    private static void register(Biome biome) {
        BY_TYPE[biome.getType().ordinal()] = biome;
    }

    /**
     * Tra cứu thực thể {@link Biome} bất biến tương ứng với {@link BiomeType} trong O(1), không cấp phát rác.
     *
     * @param type khóa enum của biome
     * @return singleton {@link Biome} tương ứng
     */
    public static Biome of(BiomeType type) {
        return BY_TYPE[type.ordinal()];
    }

    /** Trả khóa enum {@link BiomeType} gắn với biome này. */
    public abstract BiomeType getType();

    /** Trả tên hiển thị thân thiện của biome. */
    public abstract String getDisplayName();

    /** Trả mã màu cỏ RGB 24-bit chuẩn của biome. */
    public abstract int getGrassColorRgb();

    /** Trả mã màu tán lá RGB 24-bit chuẩn của biome. */
    public abstract int getFoliageColorRgb();

    /** Cho biết biome có xuất hiện mưa khi giáng thủy hay không. */
    public abstract boolean hasRain();

    /** Cho biết biome có tuyết rơi và đóng băng mặt nước khi giáng thủy hay không. */
    public abstract boolean hasSnow();

    /** Cho biết biome thuộc khí hậu khô hạn, không có mưa hay tuyết. */
    public abstract boolean isDry();

    /**
     * Phân giải đa hình trạng thái thời tiết cục bộ khi chu kỳ giáng thủy toàn cục đang hoạt động.
     *
     * @return {@code RainWeather}, {@code SnowWeather} hoặc {@code ClearWeather}
     */
    public abstract Weather resolvePrecipitationWeather();

    /**
     * Trả bảng chọn loài mob của biome theo nhóm sinh vật và phân vùng tuyết (nếu có).
     *
     * @param category nhóm sinh vật ({@code CREATURE} hoặc {@code MONSTER})
     * @param zone     phân vùng địa hình tuyết (dùng cho {@code SnowyPlainsBiome})
     * @return bảng trọng số sinh mob tương ứng
     */
    public abstract MobSpawnTable getSpawnTable(MobCategory category, SnowSubZone zone);
}

package com.voxelgame.world.level.biome;

import com.voxelgame.world.level.World;

import com.badlogic.gdx.graphics.Color;
import com.badlogic.gdx.utils.NumberUtils;

/**
 * Tính hệ số nhuộm màu động cho thảm cỏ và tán lá sồi theo 5 {@link BiomeType}
 * với cơ chế lấy mẫu trung bình 3×3 quanh cột để chuyển màu mượt tại ranh giới biome.
 * <p>
 * Lớp thuần tĩnh và không cấp phát bộ nhớ (zero-GC): toàn bộ kết quả được ghi trực tiếp
 * vào mảng {@code float[3] outRgb} do bên gọi tái sử dụng.
 */
public final class BiomeTint {

    /**
     * Màu trắng chuẩn đóng gói dạng float (0xFEFFFFFF theo quy ước {@link Color#WHITE_FLOAT_BITS})
     * dùng cho các khối/mặt không nhuộm biome nhằm tránh giá trị IEEE-754 NaN của 0xFFFFFFFF.
     */
    public static final float WHITE_PACKED_COLOR = Color.WHITE_FLOAT_BITS;

    /** Màu cỏ chuẩn của Plains đã được nhân sẵn vào atlas trong {@code Texture.PLAINS_TINT}. */
    private static final int PLAINS_GRASS_TINT = 0x91BD59;
    /** Màu lá chuẩn của Plains dùng làm gốc chuẩn hóa cho hệ số lá sồi tại Plains bằng (1, 1, 1). */
    private static final int PLAINS_FOLIAGE_TINT = 0x77AB2F;

    private static final float PLAINS_GRASS_R = ((PLAINS_GRASS_TINT >>> 16) & 0xFF);
    private static final float PLAINS_GRASS_G = ((PLAINS_GRASS_TINT >>> 8) & 0xFF);
    private static final float PLAINS_GRASS_B = (PLAINS_GRASS_TINT & 0xFF);

    private static final float PLAINS_FOLIAGE_R = ((PLAINS_FOLIAGE_TINT >>> 16) & 0xFF);
    private static final float PLAINS_FOLIAGE_G = ((PLAINS_FOLIAGE_TINT >>> 8) & 0xFF);
    private static final float PLAINS_FOLIAGE_B = (PLAINS_FOLIAGE_TINT & 0xFF);

    /** Bảng màu cỏ RGB 24-bit cho 5 biome, đánh chỉ số theo {@link BiomeType#ordinal()}. */
    private static final int[] GRASS_COLORS = new int[BiomeType.values().length];
    /** Bảng màu lá RGB 24-bit cho 5 biome, đánh chỉ số theo {@link BiomeType#ordinal()}. */
    private static final int[] FOLIAGE_COLORS = new int[BiomeType.values().length];

    static {
        for (BiomeType type : BiomeType.values()) {
            Biome biome = Biome.of(type);
            registerBiomeColors(type, biome.getGrassColorRgb(), biome.getFoliageColorRgb());
        }
    }

    private BiomeTint() {
    }

    /** Đăng ký cặp màu cỏ/lá cho một biome vào bảng tra tĩnh. */
    private static void registerBiomeColors(BiomeType biome, int grassRgb, int foliageRgb) {
        int index = biome.ordinal();
        GRASS_COLORS[index] = grassRgb;
        FOLIAGE_COLORS[index] = foliageRgb;
    }

    /**
     * Tính hệ số nhân màu cỏ tại cột {@code (x, z)} bằng lấy mẫu 3×3 qua {@link World#getBiome(int, int)},
     * chia bù theo {@code PLAINS_TINT (0x91BD59)} sao cho tại trung tâm Plains kết quả là {@code (1, 1, 1)}.
     *
     * @param world  thế giới nguồn dữ liệu biome (nếu {@code null} trả về {@code (1, 1, 1)})
     * @param x      tọa độ X thế giới
     * @param z      tọa độ Z thế giới
     * @param outRgb mảng {@code float[3]} nhận các kênh R, G, B
     */
    public static void grassMultiplier(World world, int x, int z, float[] outRgb) {
        sampleBlendedMultiplier(world, x, z, GRASS_COLORS,
                PLAINS_GRASS_R, PLAINS_GRASS_G, PLAINS_GRASS_B, outRgb);
    }

    /**
     * Tính hệ số nhân màu lá sồi tại cột {@code (x, z)} bằng lấy mẫu 3×3 qua {@link World#getBiome(int, int)},
     * chia bù theo màu lá Plains {@code (0x77AB2F)} sao cho tại trung tâm Plains kết quả là {@code (1, 1, 1)}.
     *
     * @param world  thế giới nguồn dữ liệu biome (nếu {@code null} trả về {@code (1, 1, 1)})
     * @param x      tọa độ X thế giới
     * @param z      tọa độ Z thế giới
     * @param outRgb mảng {@code float[3]} nhận các kênh R, G, B
     */
    public static void foliageMultiplier(World world, int x, int z, float[] outRgb) {
        sampleBlendedMultiplier(world, x, z, FOLIAGE_COLORS,
                PLAINS_FOLIAGE_R, PLAINS_FOLIAGE_G, PLAINS_FOLIAGE_B, outRgb);
    }

    /** Lấy trung bình 9 cột trong vùng 3×3 và chuẩn hóa theo màu gốc của Plains. */
    private static void sampleBlendedMultiplier(World world, int x, int z, int[] palette,
                                                float baseR, float baseG, float baseB, float[] outRgb) {
        if (world == null) {
            outRgb[0] = 1.0f;
            outRgb[1] = 1.0f;
            outRgb[2] = 1.0f;
            return;
        }
        int sumR = 0;
        int sumG = 0;
        int sumB = 0;
        for (int dx = -1; dx <= 1; dx++) {
            for (int dz = -1; dz <= 1; dz++) {
                int rgb = palette[world.getBiome(x + dx, z + dz).ordinal()];
                sumR += (rgb >>> 16) & 0xFF;
                sumG += (rgb >>> 8) & 0xFF;
                sumB += rgb & 0xFF;
            }
        }
        outRgb[0] = sumR / (9.0f * baseR);
        outRgb[1] = sumG / (9.0f * baseG);
        outRgb[2] = sumB / (9.0f * baseB);
    }

    /**
     * Đóng gói hệ số nhân RGB (có thể lớn hơn 1.0 ở Desert/Snowy Plains) thành 1 float
     * tương thích thuộc tính {@code Usage.ColorPacked} (4 byte RGBA chuẩn hóa).
     * <p>
     * Khi cả 3 kênh {@code <= 1.0f}, kênh alpha giữ mức tối đa ({@code >= 254/255}) để shader đọc trực tiếp RGB.
     * Khi có kênh {@code > 1.0f}, RGB được chia theo tỷ lệ lưu vào kênh alpha ({@code <= 252/255}) để shader
     * khôi phục chính xác {@code aColor.rgb / aColor.a} mà không bị kẹp mất sắc vàng Desert hay lam Snowy.
     *
     * @param rgb mảng {@code float[3]} chứa hệ số R, G, B
     * @return giá trị float đã đóng gói sẵn sàng ghi vào bộ đệm đỉnh
     */
    public static float packMultiplier(float[] rgb) {
        return packMultiplier(rgb[0], rgb[1], rgb[2]);
    }

    /** Đóng gói 3 kênh hệ số nhân R, G, B thành 1 float cho {@code aColor}. */
    public static float packMultiplier(float r, float g, float b) {
        float cr = Math.max(0.0f, r);
        float cg = Math.max(0.0f, g);
        float cb = Math.max(0.0f, b);
        float maxChannel = Math.max(cr, Math.max(cg, cb));

        if (maxChannel <= 1.0f) {
            int rByte = Math.round(cr * 255.0f);
            int gByte = Math.round(cg * 255.0f);
            int bByte = Math.round(cb * 255.0f);
            if (rByte >= 255 && gByte >= 255 && bByte >= 255) {
                return WHITE_PACKED_COLOR;
            }
            int packed = (255 << 24) | (bByte << 16) | (gByte << 8) | rByte;
            return NumberUtils.intToFloatColor(packed);
        }

        // Dùng kênh alpha <= 252 để mã hóa hệ số phóng đại (scale = 255 / aByte >= maxChannel).
        int aByte = Math.min(252, Math.max(1, (int) Math.floor(255.0f / maxChannel)));
        int rByte = Math.min(255, Math.round(cr * aByte));
        int gByte = Math.min(255, Math.round(cg * aByte));
        int bByte = Math.min(255, Math.round(cb * aByte));
        int packed = (aByte << 24) | (bByte << 16) | (gByte << 8) | rByte;
        return NumberUtils.intToFloatColor(packed);
    }
}

package com.voxelgame.world.level.biome;

/** Kiểu khí hậu quyết định địa tầng, thảm thực vật, thời tiết và hệ sinh thái của từng cột. */
public enum BiomeType {
    /** Đồng bằng lạnh ở rìa tây, có tuyết, hồ/sông đóng băng và cây vân sam. */
    SNOWY_PLAINS,
    /** Rừng sồi ôn hòa có mật độ cây dày và mưa. */
    FOREST,
    /** Đồng bằng ôn hòa thoáng đãng, có cỏ, hoa và mưa. */
    PLAINS,
    /** Rừng hoa ôn hòa rực rỡ nhiều loài hoa đan xen và mưa. */
    FLOWER_FOREST,
    /** Vùng nóng khô ở rìa đông, có cồn cát, xương rồng và bụi khô. */
    DESERT;

    /** Trả về đối tượng {@link Biome} Flyweight bất biến tương ứng (O(1), Zero-GC). */
    public Biome toBiome() {
        return Biome.of(this);
    }

    /** Cho biết biome có xuất hiện mưa và dập lửa ngoài trời khi giáng thủy hay không. */
    public boolean hasRain() {
        return toBiome().hasRain();
    }

    /** Cho biết biome có tuyết rơi và tích tuyết, đóng băng nước mặt thoáng hay không. */
    public boolean hasSnow() {
        return toBiome().hasSnow();
    }

    /** Cho biết biome thuộc khí hậu khô hạn, hoàn toàn không có giáng thủy. */
    public boolean isDry() {
        return toBiome().isDry();
    }
}

