package com.voxelgame.world.level.block;

import com.voxelgame.world.level.LeafDecaySystem;

/**
 * Lớp trừu tượng trung gian cho các khối tán lá ({@code Oak Leaves}, {@code Spruce Leaves}).
 * Gom chung cấu hình không che khuất hoàn toàn ({@code opaque = false}), kết xuất ở lớp
 * {@link RenderLayer#CUTOUT} và lưu bit metadata {@link LeafDecaySystem#PERSISTENT_LEAF_STATE}
 * để phân biệt lá do người chơi đặt với lá tự nhiên có thể tự phân hủy.
 */
public abstract class LeavesBlock extends Block {

    /** Chỉ số tile lá cây trong Texture Atlas. */
    private final int tileIndex;

    /**
     * Khởi tạo khối tán lá.
     *
     * @param id          mã định danh block
     * @param displayName tên hiển thị trên giao diện
     * @param hardness    độ cứng khi đào tay (giây)
     * @param tileIndex   chỉ số tile trong Texture Atlas
     * @param iconColor   màu RGB đại diện
     */
    protected LeavesBlock(byte id, String displayName, float hardness, int tileIndex, float[] iconColor) {
        super(id, displayName, hardness, true, false, false, iconColor);
        this.tileIndex = tileIndex;
    }

    /** Dùng chung một tile tán lá cho cả 6 mặt. */
    @Override
    public int getTileIndex(Face face) {
        return tileIndex;
    }

    /** Lá cây kết xuất ở lớp CUTOUT để giữ các khoảng hở trong suốt giữa các cành. */
    @Override
    public RenderLayer getRenderLayer() {
        return RenderLayer.CUTOUT;
    }

    /** Giữ lại bit 0 đánh dấu lá do người chơi tự đặt ({@link LeafDecaySystem#PERSISTENT_LEAF_STATE}). */
    @Override
    public int normalizeState(int state) {
        return state & LeafDecaySystem.PERSISTENT_LEAF_STATE;
    }
}

package com.voxelgame.world.level.block;

import com.voxelgame.world.level.World;

/**
 * Lớp trừu tượng trung gian cho các khối chất lỏng ({@code Water}, {@code Lava}).
 * Gom chung cấu hình vật lý ({@code solid = false}, {@code liquid = true}, {@code opaque = false}),
 * chuẩn hóa mức dòng chảy {@code 0..7}, hạ mặt thoáng {@code 0.88f} khi phía trên là không khí
 * và ngăn rơi vật phẩm khi đào tay.
 */
public abstract class LiquidBlock extends Block {

    /** Chỉ số ô texture đại diện cho chất lỏng trên Texture Atlas. */
    private final int tileIndex;

    /**
     * Khởi tạo khối chất lỏng không thể phá hủy bằng tay không.
     *
     * @param id          mã định danh block
     * @param displayName tên hiển thị
     * @param tileIndex   chỉ số tile trong Texture Atlas
     * @param iconColor   màu RGB đại diện
     */
    protected LiquidBlock(byte id, String displayName, int tileIndex, float[] iconColor) {
        super(id, displayName, -1.0f, false, true, false, iconColor);
        this.tileIndex = tileIndex;
    }

    /** Dùng chung một tile hoạt ảnh cho cả 6 mặt chất lỏng. */
    @Override
    public int getTileIndex(Face face) {
        return tileIndex;
    }

    /** Chất lỏng không thể bị đập vỡ thành vật phẩm bằng tay không. */
    @Override
    public void onBreak(World world, int x, int y, int z) {
        // Không rơi vật phẩm khi tương tác đào trên chất lỏng
    }

    /** Giới hạn mức dòng chảy hợp lệ trong khoảng 0 (nguồn) đến 7 (mỏng nhất). */
    @Override
    public int normalizeState(int state) {
        return Math.max(0, Math.min(7, state));
    }

    /** Hạ mặt thoáng xuống 0.88f cho ô nguồn và giảm dần theo mức chảy khi phía trên là không khí. */
    @Override
    public float getTopHeight(World world, int wx, int wy, int wz) {
        if (world != null && world.getBlock(wx, wy + 1, wz) == Block.AIR.getId()) {
            int level = normalizeState(world.getBlockState(wx, wy, wz));
            if (level == 0) {
                return 0.88f;
            }
            return Math.max(0.125f, 0.88f - level * 0.105f);
        }
        return 1.0f;
    }
}

package com.voxelgame.world.level.block;

/**
 * Lớp trừu tượng trung gian cho các khối thân gỗ ({@code Oak Log}, {@code Spruce Log}).
 * Gom chung ánh xạ 2 họa tiết: vân gỗ tròn cho mặt trên/đáy và vỏ cây dọc cho 4 mặt bên.
 */
public abstract class LogBlock extends SolidBlock {

    /** Chỉ số tile mặt cắt gỗ (TOP và BOTTOM). */
    private final int topBottomTile;
    /** Chỉ số tile vỏ cây 4 mặt bên (NORTH, SOUTH, EAST, WEST). */
    private final int sideTile;

    /**
     * Khởi tạo khối thân gỗ với độ cứng và cặp tile mặt cắt / vỏ cây.
     *
     * @param id            mã định danh block
     * @param displayName   tên hiển thị trên giao diện
     * @param hardness      độ cứng khi đào tay (giây)
     * @param topBottomTile chỉ số tile mặt trên và mặt đáy
     * @param sideTile      chỉ số tile 4 mặt bên
     * @param iconColor     màu RGB đại diện
     */
    protected LogBlock(byte id, String displayName, float hardness,
                       int topBottomTile, int sideTile, float[] iconColor) {
        super(id, displayName, hardness, iconColor);
        this.topBottomTile = topBottomTile;
        this.sideTile = sideTile;
    }

    /** Trả về tile vân gỗ cho mặt trên/đáy và tile vỏ cây cho 4 mặt bên. */
    @Override
    public int getTileIndex(Face face) {
        return switch (face) {
            case TOP, BOTTOM -> topBottomTile;
            case NORTH, SOUTH, EAST, WEST -> sideTile;
        };
    }
}

