/**
 * Lớp trừu tượng gốc đại diện cho một trạng thái thời tiết cục bộ theo mẫu thiết kế State / Strategy.
 * Các lớp con ({@link ClearWeather}, {@link RainWeather}, {@link SnowWeather}) là các Flyweight bất biến
 * nhằm bảo đảm Zero-GC trên vòng lặp cập nhật 60 FPS.
 */
public abstract class Weather {

    /** Constructor bảo vệ chỉ cho các trạng thái thời tiết con khởi tạo singleton. */
    protected Weather() {
    }

    /** Nhãn hiển thị trạng thái thời tiết trên giao diện HUD ({@code CLEAR}, {@code RAIN}, {@code SNOW}). */
    public abstract String getLabel();

    /**
     * Tính cường độ âm u mục tiêu của bầu trời dựa trên cường độ giáng thủy toàn cục.
     *
     * @param globalStrength cường độ giáng thủy toàn cục trong đoạn {@code [0, 1]}
     * @return cường độ âm u mục tiêu cho bầu trời
     */
    public abstract float targetSkyStrength(float globalStrength);

    /**
     * Tính âm lượng mục tiêu của tiếng mưa dựa trên cường độ giáng thủy toàn cục.
     *
     * @param globalStrength cường độ giáng thủy toàn cục trong đoạn {@code [0, 1]}
     * @return âm lượng mục tiêu cho luồng âm thanh mưa
     */
    public abstract float targetRainGain(float globalStrength);

    /** Cho biết trạng thái thời tiết này có dập tắt lửa trên thực thể ngoài trời hay không. */
    public abstract boolean extinguishesFire();

    /** Cho biết trạng thái thời tiết này có tích lũy lớp tuyết trên bề mặt lộ thiên hay không. */
    public abstract boolean accumulatesSnow();
}

package com.voxelgame.world.level.weather;

import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.biome.BiomeType;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.math.Vector3;
import java.util.Random;

/** Quản lý chu kỳ giáng thủy chuẩn Minecraft, khí hậu cục bộ và âm lượng mưa. */
public final class WeatherManager {
    /** Mỗi lần chuyển cường độ mất năm giây từ đầu đến cuối. */
    private static final float FADE_SECONDS = 5f;
    /** Chu kỳ trời quang chuẩn Minecraft Java: 12.000–180.000 tick (10–150 phút). */
    public static final int CLEAR_MIN_SECONDS = 600;
    public static final int CLEAR_MAX_SECONDS = 9_000;
    /** Chu kỳ giáng thủy chuẩn Minecraft Java: 12.000–24.000 tick (10–20 phút). */
    public static final int PRECIP_MIN_SECONDS = 600;
    public static final int PRECIP_MAX_SECONDS = 1_200;

    private final Random cycleRandom;
    private boolean precipitation;
    private float remaining;
    private float strength;
    private float skyStrength;
    private float rainGain;
    private float shelter = 1f;
    private BiomeType biome = BiomeType.PLAINS;
    /** Trạng thái thời tiết cục bộ hiện hành theo mẫu State/Strategy (singleton Zero-GC). */
    private Weather currentWeather = ClearWeather.INSTANCE;
    private double animationSeconds;

    /** Khởi tạo chu kỳ thời tiết tất định theo seed thế giới. */
    public WeatherManager(long seed) {
        cycleRandom = new Random(seed);
        scheduleNext();
    }

    /** Tự chuyển sau 10–150 phút quang đãng hoặc 10–20 phút giáng thủy theo chuẩn Minecraft. */
    private void scheduleNext() {
        remaining = precipitation
                ? PRECIP_MIN_SECONDS + cycleRandom.nextInt(PRECIP_MAX_SECONDS - PRECIP_MIN_SECONDS + 1)
                : CLEAR_MIN_SECONDS + cycleRandom.nextInt(CLEAR_MAX_SECONDS - CLEAR_MIN_SECONDS + 1);
    }

    /** Đảo thời tiết và bắt đầu một khoảng tự động mới. */
    public void toggle() {
        precipitation = !precipitation;
        scheduleNext();
    }

    /** Tính cường độ liên tục, kể cả khi vượt qua mốc chuyển tự động giữa hai frame. */
    public void update(float seconds) {
        animationSeconds += seconds;
        while (seconds >= remaining) {
            fade(remaining);
            seconds -= remaining;
            toggle();
        }
        remaining -= seconds;
        fade(seconds);
        currentWeather = strength > 0f ? biome.toBiome().resolvePrecipitationWeather() : ClearWeather.INSTANCE;
    }

    /** Tiến cường độ về mục tiêu mà không vượt qua hai đầu. */
    private void fade(float seconds) {
        strength = approach(strength, precipitation ? 1f : 0f, seconds / FADE_SECONDS);
    }

    /** Cập nhật khí hậu quanh người chơi; tích tuyết thực hiện theo random tick 1/16 của World. */
    public void update(float seconds, World world, Vector3 eye, Player player) {
        update(seconds);
        int x = MathUtils.floor(eye.x);
        int z = MathUtils.floor(eye.z);
        biome = world.getBiome(x, z);
        currentWeather = strength > 0f ? biome.toBiome().resolvePrecipitationWeather() : ClearWeather.INSTANCE;
        skyStrength = approach(skyStrength, currentWeather.targetSkyStrength(strength), seconds * 0.6f);
        rainGain = approach(rainGain, currentWeather.targetRainGain(strength), seconds * 0.65f);
        shelter = approach(shelter, world.hasWeatherRoof(x, eye.y, z) ? 0.4f : 1f, seconds * 1.5f);
    }

    /** Bước tuyến tính có chặn để các giá trị nhỏ về đúng 0. */
    private static float approach(float current, float target, float step) {
        return current < target ? Math.min(target, current + step) : Math.max(target, current - step);
    }

    /** Thời gian còn lại của pha thời tiết hiện tại (giây), phục vụ kiểm thử chu kỳ. */
    public float remainingSeconds() {
        return remaining;
    }

    /** Cường độ toàn cục áp dụng khi dựng các cột mưa và tuyết. */
    public float strength() {
        return strength;
    }

    /** Tỷ lệ âm u tại vùng đang đứng, chuyển êm ở ranh giới sa mạc. */
    public float skyStrength() {
        return skyStrength;
    }

    /** Hệ số luồng mưa trước khi áp dụng âm lượng từ Pause Menu. */
    public float rainVolume() {
        return rainGain * shelter;
    }

    /** Biome hiện tại dùng cho HUD. */
    public BiomeType biome() {
        return biome;
    }

    /** Trạng thái thời tiết đa hình hiện hành ({@link ClearWeather}, {@link RainWeather} hoặc {@link SnowWeather}). */
    public Weather currentWeather() {
        return currentWeather;
    }

    /** Nhãn HUD phản ánh cường độ thực tế và khí hậu ở cột hiện tại qua lời gọi đa hình. */
    public String label() {
        return currentWeather.getLabel();
    }

    /** Thời gian hoạt ảnh không bị nhân tốc độ bởi F8 và dừng khi Pause. */
    public double animationSeconds() {
        return animationSeconds;
    }
}

package com.voxelgame.world.physics;

import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.Vector3;

/** Duyệt ô theo DDA và kiểm tra phần hình học có thể ngắm trong mỗi ô. */
public final class Raycast {
    /** Thành phần nhỏ hơn giá trị này được xem như song song với mặt hộp. */
    private static final float PARALLEL_EPSILON = 1e-8f;

    /** Giữ tọa độ block trúng và ô kề theo pháp tuyến của mặt trúng. */
    public static final class HitResult {
        private boolean hit;
        private int blockX;
        private int blockY;
        private int blockZ;
        private int prevBlockX;
        private int prevBlockY;
        private int prevBlockZ;
        private Block block;
        private float distance = Float.POSITIVE_INFINITY;

        /** Khởi tạo kết quả có thể dùng lại trong các lần bắn tia. */
        public HitResult(boolean hit, int x, int y, int z, int prevX, int prevY, int prevZ, Block block) {
            set(hit, x, y, z, prevX, prevY, prevZ, block == null ? Block.AIR : block);
        }

        /** Tạo kết quả mặc định cho lần không trúng. */
        public static HitResult miss() {
            return new HitResult(false, 0, 0, 0, 0, 0, 0, Block.AIR);
        }

        /** Cập nhật đồng bộ mọi trường, kể cả khi kết quả bị đặt lại. */
        private void set(boolean hit, int x, int y, int z, int prevX, int prevY, int prevZ, Block block) {
            this.hit = hit;
            blockX = x;
            blockY = y;
            blockZ = z;
            prevBlockX = prevX;
            prevBlockY = prevY;
            prevBlockZ = prevZ;
            this.block = block;
        }

        /** Báo tia đã chạm hộp chọn. */
        public boolean isHit() { return hit; }
        /** Trả tọa độ X của ô trúng. */
        public int getBlockX() { return blockX; }
        /** Trả tọa độ Y của ô trúng. */
        public int getBlockY() { return blockY; }
        /** Trả tọa độ Z của ô trúng. */
        public int getBlockZ() { return blockZ; }
        /** Trả tọa độ X của ô tiếp giáp mặt trúng. */
        public int getPrevBlockX() { return prevBlockX; }
        /** Trả tọa độ Y của ô tiếp giáp mặt trúng. */
        public int getPrevBlockY() { return prevBlockY; }
        /** Trả tọa độ Z của ô tiếp giáp mặt trúng. */
        public int getPrevBlockZ() { return prevBlockZ; }
        /** Trả khối được ngắm hoặc Air. */
        public Block getBlock() { return block; }
        /** Trả khối được ngắm qua tên truy vấn tương thích. */
        public Block getBlockType() { return block; }
        /** Trả khoảng cách từ đầu tia đến mặt trúng hoặc vô cực nếu không trúng. */
        public float getDistance() { return distance; }
    }

    /** Kết quả tia thực thể và bộ đệm tâm hộp dùng qua nhiều lần chọn. */
    public static final class EntityHitResult {
        private final Vector3 center = new Vector3();
        private LivingEntity entity;
        private float distance = Float.POSITIVE_INFINITY;

        /** Trả mục tiêu còn sống gần nhất, hoặc null khi tia không trúng. */
        public LivingEntity getEntity() { return entity; }
        /** Trả khoảng cách mặt hộp hoặc vô cực khi tia không trúng. */
        public float getDistance() { return distance; }
        /** Báo tia đã chọn được mục tiêu. */
        public boolean isHit() { return entity != null; }
    }

    /** Bắn tia và trả một kết quả mới cho nơi gọi cần lưu độc lập. */
    public static HitResult cast(World world, Vector3 origin, Vector3 direction, float maxDistance) {
        return cast(world, origin, direction, maxDistance, HitResult.miss());
    }

    /** Bắn tia vào bộ kết quả có sẵn, không đổi hai vector đầu vào. */
    public static HitResult cast(World world, Vector3 origin, Vector3 direction, float maxDistance, HitResult result) {
        return castBlocks(world, origin, direction, maxDistance, result, false);
    }

    /** Tìm hộp va chạm gần nhất để chặn đánh xuyên khối mà vẫn cho tia đi qua cây chữ X. */
    public static HitResult castOccluder(World world, Vector3 origin, Vector3 direction, float maxDistance,
                                         HitResult result) {
        return castBlocks(world, origin, direction, maxDistance, result, true);
    }

    /** Dùng cùng bước DDA cho hộp chọn block và hộp cản đường chiến đấu. */
    private static HitResult castBlocks(World world, Vector3 origin, Vector3 direction, float maxDistance,
                                        HitResult result, boolean collisionOnly) {
        result.set(false, 0, 0, 0, 0, 0, 0, Block.AIR);
        result.distance = Float.POSITIVE_INFINITY;
        float lengthSquared = direction.len2();
        if (!validRay(origin, lengthSquared, maxDistance)) {
            return result;
        }

        float inverseLength = 1.0f / (float) Math.sqrt(lengthSquared);
        float dx = direction.x * inverseLength;
        float dy = direction.y * inverseLength;
        float dz = direction.z * inverseLength;
        int x = (int) Math.floor(origin.x);
        int y = (int) Math.floor(origin.y);
        int z = (int) Math.floor(origin.z);
        int sx = dx >= 0 ? 1 : -1;
        int sy = dy >= 0 ? 1 : -1;
        int sz = dz >= 0 ? 1 : -1;
        float nextX = timeToBoundary(origin.x, x, sx, dx);
        float nextY = timeToBoundary(origin.y, y, sy, dy);
        float nextZ = timeToBoundary(origin.z, z, sz, dz);
        float stepX = Math.abs(1.0f / dx);
        float stepY = Math.abs(1.0f / dy);
        float stepZ = Math.abs(1.0f / dz);

        float entered = 0;
        while (entered <= maxDistance) {
            float leaves = Math.min(nextX, Math.min(nextY, nextZ));
            Block block = Block.fromId(world.getBlock(x, y, z));
            if (block.isSelectable() || collisionOnly) {
                int state = world.getBlockState(x, y, z);
                Block.Bounds bounds = collisionOnly ? block.getCollisionBounds(state) : block.getSelectionBounds(state);
                if (bounds != null && hitBounds(result, block, bounds, x, y, z, origin, dx, dy, dz,
                        entered, Math.min(leaves, maxDistance))) {
                    return result;
                }
            }

            if (nextX < nextY && nextX < nextZ) {
                x += sx;
                entered = nextX;
                nextX += stepX;
            } else if (nextY < nextZ) {
                y += sy;
                entered = nextY;
                nextY += stepY;
            } else {
                z += sz;
                entered = nextZ;
                nextZ += stepZ;
            }
        }
        return result;
    }

    /** Chọn hộp thực thể gần nhất trong tầm và nằm trước mặt khối cản. */
    public static EntityHitResult castEntity(World world, Vector3 origin, Vector3 direction, float maxDistance,
                                             float blockDistanceLimit, Entity exclude, EntityHitResult out) {
        out.entity = null;
        out.distance = Float.POSITIVE_INFINITY;
        float lengthSquared = direction.len2();
        if (!validRay(origin, lengthSquared, maxDistance) || !(blockDistanceLimit > 0f)) {
            return out;
        }
        float inverseLength = 1f / (float) Math.sqrt(lengthSquared);
        float dx = direction.x * inverseLength;
        float dy = direction.y * inverseLength;
        float dz = direction.z * inverseLength;
        float limit = Math.min(maxDistance, blockDistanceLimit);
        for (int i = 0; i < world.entityCount(); i++) {
            Entity candidate = world.entityAt(i);
            if (candidate == exclude || !(candidate instanceof LivingEntity living) || !living.isAlive()) {
                continue;
            }
            Vector3 center = living.copyCenterPosition(out.center);
            float distance = entityEntry(origin, dx, dy, dz, center, living.getHalfWidth(),
                    living.getHeight() * 0.5f, limit);
            if (distance < blockDistanceLimit && distance < out.distance) {
                out.entity = living;
                out.distance = distance;
                limit = distance;
            }
        }
        return out;
    }

    /** Kiểm tra đầu tia hữu hạn, hướng đủ dài và tầm với hợp lệ. */
    private static boolean validRay(Vector3 origin, float lengthSquared, float maxDistance) {
        return lengthSquared >= 1e-8f && Float.isFinite(lengthSquared)
                && Float.isFinite(maxDistance) && maxDistance >= 0f
                && Float.isFinite(origin.x) && Float.isFinite(origin.y) && Float.isFinite(origin.z);
    }

    /** Giao ba khoảng chiếu trên các trục, lấy khoảng cách vào hộp hoặc vô cực. */
    private static float entityEntry(Vector3 origin, float dx, float dy, float dz, Vector3 center,
                                     float halfWidth, float halfHeight, float limit) {
        float near = 0f;
        float far = limit;
        for (int axis = 0; axis < 3; axis++) {
            float relative = axis == 0 ? center.x - origin.x : axis == 1 ? center.y - origin.y : center.z - origin.z;
            float direction = axis == 0 ? dx : axis == 1 ? dy : dz;
            float halfExtent = axis == 1 ? halfHeight : halfWidth;
            if (Math.abs(direction) < PARALLEL_EPSILON) {
                if (Math.abs(relative) > halfExtent) {
                    return Float.POSITIVE_INFINITY;
                }
                continue;
            }
            float centerDistance = relative / direction;
            float radius = halfExtent / Math.abs(direction);
            near = Math.max(near, centerDistance - radius);
            far = Math.min(far, centerDistance + radius);
            if (far < near) {
                return Float.POSITIVE_INFINITY;
            }
        }
        return near;
    }

    /** Tính thời điểm tới biên ô, tránh chia cho thành phần hướng gần 0. */
    private static float timeToBoundary(float origin, int cell, int step, float direction) {
        return Math.abs(direction) < PARALLEL_EPSILON
                ? Float.POSITIVE_INFINITY : (cell + (step > 0 ? 1.0f : 0.0f) - origin) / direction;
    }

    /** Cắt tia với ba khoảng hộp trong đoạn DDA hiện tại và lấy pháp tuyến mặt vào. */
    private static boolean hitBounds(HitResult out, Block block, Block.Bounds b, int x, int y, int z,
                                     Vector3 origin, float dx, float dy, float dz, float from, float to) {
        float near = Float.NEGATIVE_INFINITY;
        float far = to;
        int nx = 0;
        int ny = 0;
        int nz = 0;
        for (int axis = 0; axis < 3; axis++) {
            float o = axis == 0 ? origin.x : axis == 1 ? origin.y : origin.z;
            float d = axis == 0 ? dx : axis == 1 ? dy : dz;
            float min = axis == 0 ? x + b.minX() : axis == 1 ? y + b.minY() : z + b.minZ();
            float max = axis == 0 ? x + b.maxX() : axis == 1 ? y + b.maxY() : z + b.maxZ();
            if (Math.abs(d) < PARALLEL_EPSILON) {
                if (o < min || o > max) {
                    return false;
                }
                continue;
            }
            float first = ((d > 0 ? min : max) - o) / d;
            float last = ((d > 0 ? max : min) - o) / d;
            if (first > near) {
                near = first;
                int sign = d > 0 ? -1 : 1;
                nx = axis == 0 ? sign : 0;
                ny = axis == 1 ? sign : 0;
                nz = axis == 2 ? sign : 0;
            }
            far = Math.min(far, last);
            if (far < Math.max(near, from)) {
                return false;
            }
        }
        if (near < 0) {
            nx = 0;
            ny = 0;
            nz = 0;
        }
        out.set(true, x, y, z, x + nx, y + ny, z + nz, block);
        out.distance = Math.max(near, from);
        return true;
    }
}

package com.voxelgame.engine;

import com.voxelgame.world.effect.StatusEffectType;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.mob.animal.Camel;
import com.voxelgame.world.entity.mob.MobAttitude;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.monster.CamelHusk;
import com.voxelgame.world.entity.mob.monster.Husk;
import com.voxelgame.world.entity.mob.monster.Parched;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.entity.projectile.ProjectileEntity;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

/** Kiểm tra bộ kỵ sĩ sa mạc, tấn công bằng giáo và trao lại quyền điều khiển. */
final class CamelHuskBehaviorChecks {
    /** Nhịp CPU cố định theo tick gameplay. */
    private static final float TICK = 0.05f;

    /** Chạy các tình huống chiến đấu và tiếp quản thú cưỡi. */
    static void run() {
        checkMountedCombat();
        checkDriverHandoverAndCapture();
    }

    /** Giáo dùng tốc độ thật của thú cưỡi để gây thêm sát thương, và cung thủ bắn từ ghế sau. */
    private static void checkMountedCombat() {
        World world = desertArena();
        try {
            Player player = new Player(19.5f, 1f, 12.5f);
            world.registerPlayer(player);
            CamelHusk camel = createCamel();
            Husk front = new Husk(12.5f, 3.38f, 12.5f, true);
            Parched back = new Parched(12.5f, 3.38f, 12.5f);
            require(front.hasIronSpear() && front.tryMount(camel, 0) && back.tryMount(camel, 1)
                            && camel.activeDriver() == front,
                    "Bộ kỵ sĩ cần hai ghế độc lập và Husk cầm giáo trên ghế lái");
            require(!camel.burnsInSunlight() && !front.burnsInSunlight() && !back.burnsInSunlight(),
                    "Cả ba thành viên chịu được nắng");
            for (int tick = 0; tick < 120 && !player.hasEffect(StatusEffectType.HUNGER); tick++) {
                camel.update(world, TICK);
                front.update(world, TICK);
            }
            require(player.hasEffect(StatusEffectType.HUNGER) && player.getHealth() <= 14f,
                    "Husk trên ghế trước phải lao tới đâm giáo, gây ít nhất 6 HP và Hunger");

            // Cố định thú sau khi đổi người lái để kiểm tra riêng quỹ đạo của cung thủ.
            front.discard();
            camel.setPosition(12.5f, 1f, 12.5f);
            for (int tick = 0; tick < 100 && !player.hasEffect(StatusEffectType.WEAKNESS); tick++) {
                player.update(world, TICK);
                back.update(world, TICK);
                for (int index = 0, count = world.entityCount(); index < count; index++) {
                    if (world.entityAt(index) instanceof ProjectileEntity projectile) {
                        projectile.update(world, TICK);
                    }
                }
            }
            require(player.getEffectDuration(StatusEffectType.WEAKNESS) > 29f,
                    "Parched trên ghế sau phải bắn trúng tên Weakness I 30 giây");
        } finally {
            world.dispose();
        }
    }

    /** Giữ ghế sau và lùi tầm cung khi mất ghế lái, rồi cho phép thuần hóa khi hết tay lái địch. */
    private static void checkDriverHandoverAndCapture() {
        World world = desertArena();
        try {
            Player player = new Player(16.5f, 1f, 12.5f);
            world.registerPlayer(player);
            CamelHusk camel = createCamel();
            Husk front = new Husk(12.5f, 3.38f, 12.5f, true);
            Parched back = new Parched(12.5f, 3.38f, 12.5f);
            require(front.tryMount(camel, 0) && back.tryMount(camel, 1), "Không gắn được bộ kỵ sĩ");
            require(camel.attitude() == MobAttitude.HOSTILE && !camel.onPlayerInteract(world, player),
                    "Người chơi không được cưỡi khi có kỵ sĩ địch");
            require(front.damage(world, 100f, DamageSource.MELEE, player, 0f, 0f), "Husk phải bị hạ");
            require(camel.attitude() == MobAttitude.HOSTILE && camel.getPassenger(0) == null
                            && camel.getPassenger(1) == back && camel.activeDriver() == back
                            && !camel.isTamed() && !camel.onPlayerInteract(world, player),
                    "Parched còn sống phải giữ ghế sau và quyền điều khiển");
            for (int tick = 0; tick < 30; tick++) {
                camel.update(world, TICK);
            }
            require(camel.x() < 10.5f, "Lạc đà do Parched lái phải lùi ra khỏi đối thủ đứng gần");
            back.leaveMount();
            require(camel.attitude() == MobAttitude.PASSIVE, "Kỵ sĩ cuối tự rời ghế cũng phải giải phóng thú cưỡi");
            require(back.tryMount(camel, 1) && back.damage(world, 100f, DamageSource.MELEE, player, 0f, 0f),
                    "Parched phải rời ghế ngay khi bị hạ");
            require(camel.attitude() == MobAttitude.PASSIVE && camel.onPlayerInteract(world, player)
                            && player.getMount() == camel && camel.isTamed() && camel.isPersistent(),
                    "Hết kỵ sĩ địch phải lập tức cho người chơi thuần hóa và cưỡi");
            camel.update(world, TICK);
            require(camel.target() == null, "Thú cưỡi đã thuần hóa phải bỏ mục tiêu truy đuổi trước đó");
            for (int tick = 0; tick < 20; tick++) {
                camel.updateRiderInput(player, 1f, 0f, false, true, TICK);
                camel.update(world, TICK);
            }
            camel.updateRiderInput(player, 1f, 0f, false, false, TICK);
            camel.update(world, TICK);
            require(camel.isDashMount() && Math.abs(camel.dashCooldownRemaining() - 2.75f) < 0.001f,
                    "Camel Husk đã thuần hóa phải bắt đầu Dash với 2,75 giây hồi chiêu");
        } finally {
            world.dispose();
        }
    }

    /** Dựng Camel Husk thông qua danh mục để xác minh factory. */
    private static CamelHusk createCamel() {
        MobEntity camel = MobType.CAMEL_HUSK.create(12.5f, 1f, 12.5f);
        require(camel instanceof CamelHusk && camel.getSeatCount() == 2 && camel.isUndead(),
                "Camel Husk phải có factory, tộc xác sống và hai chỗ ngồi");
        return (CamelHusk) camel;
    }

    /** Lót mặt cát để mô phỏng đi, lùi và gây đòn ở ngoài trời. */
    private static World desertArena() {
        World world = World.empty();
        for (int x = 3; x <= 32; x++) {
            for (int z = 3; z <= 28; z++) {
                world.setBlockInternal(x, 0, z, Block.SAND.getId(), 0);
            }
        }
        return world;
    }

    /** Nêu đúng yêu cầu bị vi phạm nếu kiểm tra không đạt. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

package com.voxelgame.engine;

import com.voxelgame.client.render.Camera;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.mob.animal.Camel;
import com.voxelgame.world.entity.player.Hotbar;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.Vector3;

/** Kiểm tra lạc đà với địa hình và giao diện tương tác cũng dùng trong trò chơi. */
final class CamelMountChecks {
    /** Chạy các ca hình thể, tương tác, điều khiển và nổi dưới nước. */
    static void run() {
        checkDimensionsAndFeeding();
        checkRestAndClearance();
        checkStepAndDash();
        checkMountedWadingAndDismount();
    }

    /** Đo hộp thấp khi nghỉ và kiểm tra mái thấp ngăn lạc đà đứng dậy. */
    private static void checkRestAndClearance() {
        World world = arena(Block.SAND);
        try {
            Camel camel = new Camel(100.5f, 20f, 100.5f);
            for (int i = 0; i < 720 && camel.getHeight() > 1f; i++) {
                camel.update(world, 0.05f);
            }
            require(Math.abs(camel.getHeight() - 0.945f) < 0.0001f
                    && camel.mobVisualState().pose() == MobVisualState.Pose.SIT,
                    "Ngồi nghỉ trên cát phải hạ cả hộp va chạm lẫn tư thế");
            int roofX = (int) Math.floor(camel.x());
            int roofZ = (int) Math.floor(camel.z());
            world.setBlock(roofX, 21, roofZ, Block.STONE.getId());
            Player player = new Player(camel.x() + 2f, 20f, camel.z());
            camel.onPlayerInteract(world, player);
            require(camel.getHeight() < 1f && player.getMount() == null,
                    "Không được đứng vào khối rắn hay nhận hành khách khi đang kẹt dưới mái");
            world.setBlock(roofX, 21, roofZ, Block.AIR.getId());
            require(camel.onPlayerInteract(world, player) && player.getMount() == camel && camel.getHeight() > 2.37f,
                    "Lạc đà phải đứng và nhận người cưỡi ngay khi đã thông chỗ");
        } finally {
            world.dispose();
        }
    }

    /** Điều khiển qua API nạp thật, kiểm tra bậc 1,5 block, vòng cung và đúng thời gian hồi. */
    private static void checkStepAndDash() {
        World world = arena(Block.STONE);
        try {
            for (int x = 104; x <= 129; x++) {
                for (int z = 97; z <= 103; z++) {
                    world.setBlock(x, 20, z, Block.STONE.getId());
                    world.setBlock(x, 21, z, Block.SNOW_LAYER.getId(), 4);
                }
            }
            Camel camel = new Camel(100.5f, 20f, 100.5f);
            Player player = new Player(102.5f, 20f, 100.5f);
            require(camel.onPlayerInteract(world, player) && player.getMount() == camel,
                    "Lạc đà hiền cho phép cưỡi ngay");
            Player passenger = new Player(99.5f, 20f, 101.5f);
            require(camel.onPlayerInteract(world, passenger) && passenger.getMountedSeat() == 1
                    && player.getMountedSeat() == 0 && camel.copySeatPosition(0, new Vector3())
                    .dst2(camel.copySeatPosition(1, new Vector3())) > 0.9f,
                    "Hai hành khách phải ở hai điểm ghế riêng và ghế trước được giữ quyền lái");
            steer(world, camel, player, 1, false, false, 100);
            require(camel.x() > 105f && Math.abs(camel.y() - 21.5f) < 0.02f,
                    "Lạc đà phải bước trực tiếp lên bậc một block rưỡi");
            steer(world, camel, player, 0, false, true, 60);
            require(camel.chargeProgress() >= 0.99f, "Phải nạp đầy thanh khi giữ Space");
            float startX = camel.x();
            float startY = camel.y();
            steer(world, camel, player, 0, false, false, 1);
            require(Math.abs(camel.dashCooldownRemaining() - 2.75f) < 0.05f,
                    "Nhả Space phải khởi động hồi chiêu 2,75 giây");
            float highest = camel.y();
            for (int i = 0; i < 40; i++) {
                steer(world, camel, player, 0, false, false, 1);
                highest = Math.max(highest, camel.y());
            }
            require(camel.x() - startX > 10f && camel.x() - startX < 12.8f
                    && highest - startY > 0.8f && highest - startY < 1.3f,
                    "Lướt đầy nạp phải đi gần mười hai block và nâng chân gần một block");
            steer(world, camel, player, 0, false, true, 45);
            require(camel.chargeProgress() == 0f, "Không được nạp lại trong hồi chiêu");
            steer(world, camel, player, 0, false, false, 90);
            require(camel.dashCooldownRemaining() == 0f, "Hồi chiêu phải tự hết sau đúng thời gian");
        } finally {
            world.dispose();
        }
    }

    /** Lạc đà lội hồ hai lớp, hất người khi ngập sâu rồi mới nổi. */
    private static void checkMountedWadingAndDismount() {
        World world = arena(Block.STONE);
        try {
            for (int x = 98; x <= 128; x++) {
                for (int z = 98; z <= 102; z++) {
                    for (int y = 20; y <= (x < 112 ? 21 : 22); y++) {
                        world.setBlock(x, y, z, Block.WATER.getId());
                    }
                }
            }
            Camel camel = new Camel(100.5f, 22f, 100.5f);
            Player player = new Player(97f, 22f, 100.5f);
            Camera camera = new Camera();
            player.attachControls(camera);
            require(camel.onPlayerInteract(world, player), "Cần ghế lái để kiểm tra lội nước");
            steer(world, camel, player, 1, false, false, 100);
            player.syncMountedPosition();
            require(player.getMount() == camel && camel.x() > 102f && camel.x() < 109f
                            && Math.abs(camel.y() - 20f) < 0.01f
                            && Math.abs(camera.copyPosition(new Vector3()).y - player.getPosition().y - 1.62f) < 0.01f,
                    "Lạc đà phải chạm đáy, đi chậm và giữ đồng bộ ghế với mắt");
            for (int tick = 0; tick < 320 && player.getMount() != null; tick++) {
                steer(world, camel, player, 1, false, false, 1);
            }
            require(player.getMount() == null && camel.getPassenger(0) == null,
                    "Nước sâu phải gỡ liên kết ở cả hai phía tại X=" + camel.x());
            float dismountY = camel.y();
            for (int tick = 0; tick < 12; tick++) {
                camel.update(world, 0.025f);
            }
            require(camel.y() > dismountY + 0.5f, "Lạc đà phải bắt đầu nổi khi trống ghế");
        } finally {
            world.dispose();
        }
    }

    /** Dựng mặt phẳng đủ rộng để kiểm tra cát, bước bậc và không gian lướt. */
    private static World arena(Block surface) {
        World world = World.empty();
        for (int x = 75; x <= 132; x++) {
            for (int z = 75; z <= 128; z++) {
                world.setBlock(x, 18, z, Block.STONE.getId());
                world.setBlock(x, 19, z, surface.getId());
            }
        }
        return world;
    }

    /** Cập nhật lệnh ghế trước và vật lý theo bước cố định 20 vị trí mỗi nửa giây. */
    private static void steer(World world, Camel camel, Player player, float x, boolean sprint, boolean space, int frames) {
        for (int i = 0; i < frames; i++) {
            camel.updateRiderInput(player, x, 0f, sprint, space, 0.025f);
            camel.update(world, 0.025f);
        }
    }

    /** Xương rồng hồi máu cho lạc đà bị thương và tiêu thụ đúng một vật phẩm. */
    private static void checkDimensionsAndFeeding() {
        World world = arena(Block.STONE);
        try {
            Camel camel = new Camel(100.5f, 20f, 100.5f);
            Player player = new Player(106.5f, 20f, 100.5f);
            world.registerPlayer(player);
            require(camel.getHealth() == 32f && camel.stepHeight() == 1.5f
                    && camel.maxSafeFall() == 7f && camel.getSeatCount() == 2
                    && Math.abs(camel.getHeight() - 2.38f) < 0.0001f
                    && Math.abs(camel.getHalfWidth() - 0.85f) < 0.0001f,
                    "Lạc đà đứng phải có đúng kích thước, tầm bước bậc và máu");
            camel.damage(world, 8f, DamageSource.MELEE, null, 0f, 0f);
            require(player.getHotbar().addItem(Block.CACTUS, 2), "Cần xương rồng trong Hotbar");
            player.getHotbar().selectSlot(0);
            require(camel.onPlayerInteract(world, player) && camel.getHealth() > 24f
                    && player.getHotbar().getSelectedCount() == 1 && player.getMount() == null,
                    "Tương tác khi cầm xương rồng phải cho ăn và hồi máu trước khi cưỡi");
            for (int i = 0; i < 40; i++) {
                camel.update(world, 0.025f);
            }
            require(camel.x() > 101.5f, "Lạc đà phải tiến về người đang cầm xương rồng");
        } finally {
            world.dispose();
        }
    }

    /** Báo mô tả cụ thể khi hành vi khác với mong đợi. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

package com.voxelgame.engine;

import com.voxelgame.world.effect.StatusEffectType;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.mob.animal.Camel;
import com.voxelgame.world.entity.mob.MobAttitude;
import com.voxelgame.world.entity.mob.monster.Creeper;
import com.voxelgame.world.entity.mob.monster.Enderman;
import com.voxelgame.world.entity.mob.monster.Husk;
import com.voxelgame.world.entity.mob.monster.Spider;
import com.voxelgame.world.entity.mob.monster.Zombie;
import com.voxelgame.world.entity.mob.monster.ZombieVillager;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

/** Kiểm tra hành vi của nhóm quái cận chiến bằng dữ liệu voxel và nhịp mô phỏng thật. */
final class CloseHostileChecks {
    /** Bước mô phỏng dùng chung cho các kiểm tra thời gian ở 20 Hz. */
    private static final float TICK = 0.05f;

    /** Chạy các kiểm tra chỉ số, điều kiện tấn công và phá khối. */
    static void run() {
        checkZombieAttributesAndReinforcements();
        checkHuskBabyAndDimensions();
        checkHuskHunger();
        checkHuskUnderwaterConversion();
        checkEndermanBlockRates();
        checkCreeperFuseAndBlockDamage();
        checkCreeperCancelsFuse();
        checkSpiderStanceAndLeap();
        checkSpiderClimbsWall();
    }

    /** Zombie con có đúng kích thước vật lý, và Zombie gần đó nhận mục tiêu khi đồng loại bị đánh. */
    private static void checkZombieAttributesAndReinforcements() {
        World world = World.empty();
        try {
            Zombie zombie = new Zombie(10.5f, 1f, 10.5f, false);
            Zombie baby = new Zombie(12.5f, 1f, 10.5f, true);
            ZombieVillager villager = new ZombieVillager(11.5f, 1f, 10.5f, false);
            require(zombie.getArmor() == 2 && villager.getArmor() == 2 && zombie.getMaxHealth() == 20,
                    "Zombie và Zombie Villager dùng 20 HP và 2 giáp");
            near(baby.getHalfWidth() * 2f, 0.3f, "Chiều rộng hitbox Zombie con");
            near(baby.getHeight(), 0.975f, "Chiều cao hitbox Zombie con");
            near(baby.moveSpeed(), zombie.moveSpeed() * 1.5f, "Tốc độ Zombie con");
            require(baby.burnsInSunlight() && villager.burnsInSunlight(), "Zombie con và Zombie Villager cháy nắng");

            Player player = new Player(43.5f, 1f, 10.5f);
            world.registerPlayer(player);
            world.addLivingEntity(zombie);
            world.addLivingEntity(baby);
            zombie.update(world, TICK);
            require(zombie.target() == player, "Zombie nhận ra người chơi trong phạm vi 35 block");
            require(zombie.damage(world, 1f, DamageSource.MELEE, player, 0f, 0f) && baby.target() == player,
                    "Zombie vừa bị đánh gọi đồng loại gần đó cùng truy đuổi");
        } finally {
            world.dispose();
        }
    }

    /** Husk có 5% cơ hội là con non với hitbox 0,5×, tốc độ 1,5×, giữ scale 1,06× ở trưởng thành và kỵ sĩ luôn lớn. */
    private static void checkHuskBabyAndDimensions() {
        Husk adult = new Husk(10.5f, 1f, 10.5f, false, false);
        Husk baby = new Husk(10.5f, 1f, 10.5f, false, true);
        near(adult.getHalfWidth() * 2f, 0.6f, "Chiều rộng hitbox Husk trưởng thành");
        near(adult.getHeight(), 1.95f, "Chiều cao hitbox Husk trưởng thành");
        near(adult.mobVisualState().scale(), 1.06f, "Tỷ lệ hình hiển thị Husk trưởng thành");
        near(baby.getHalfWidth() * 2f, 0.3f, "Chiều rộng hitbox Husk con");
        near(baby.getHeight(), 0.975f, "Chiều cao hitbox Husk con");
        near(baby.moveSpeed(), adult.moveSpeed() * 1.5f, "Tốc độ Husk con");
        near(baby.mobVisualState().scale(), 0.6f * 1.06f, "Tỷ lệ hình hiển thị Husk con");

        // Kiểm tra khôi phục kích thước 1,0× và visual 1,06× khi chuyển baby true -> false.
        baby.setBaby(false);
        near(baby.getHalfWidth() * 2f, 0.6f, "Khôi phục chiều rộng hitbox Husk");
        near(baby.getHeight(), 1.95f, "Khôi phục chiều cao hitbox Husk");
        near(baby.mobVisualState().scale(), 1.06f, "Khôi phục tỷ lệ hiển thị Husk trưởng thành");

        for (int i = 0; i < 64; i++) {
            Husk jockey = new Husk(0f, 1f, 0f, true);
            require(!jockey.isBaby() && jockey.hasIronSpear(), "Husk cầm giáo cưỡi Camel Husk luôn là người lớn");
        }

        int babyCount = 0;
        for (int i = 0; i < 2000; i++) {
            if (new Husk(0f, 1f, 0f).isBaby()) {
                babyCount++;
            }
        }
        require(babyCount > 40 && babyCount < 180,
                "Tỉ lệ Husk con tự nhiên phải dao động quanh 5% (nhận " + babyCount + "/2000)");
    }

    /** Một đòn cận chiến thật của Husk gây 3 HP và áp Hunger I đúng thời lượng. */
    private static void checkHuskHunger() {
        World world = World.empty();
        try {
            floor(world, 0);
            Player player = new Player(11.5f, 1f, 10.5f);
            world.registerPlayer(player);
            Husk husk = new Husk(10.5f, 1f, 10.5f, false, false);
            husk.update(world, TICK);
            near(player.getHealth(), 17f, "Sát thương cận chiến của Husk");
            float hunger = player.getEffectDuration(StatusEffectType.HUNGER);
            require(hunger >= 7f && hunger <= 14f, "Husk phải áp Hunger I từ 7 đến 14 giây");
            require(!husk.burnsInSunlight(), "Husk không bắt lửa ngoài nắng");
        } finally {
            world.dispose();
        }
    }

    /** Buồng ngập kín giữ đầu Husk dưới nước đủ 30 giây, sau đó chờ pha rung 15 giây. */
    private static void checkHuskUnderwaterConversion() {
        World world = World.empty();
        try {
            for (int x = 9; x <= 11; x++) {
                for (int z = 9; z <= 11; z++) {
                    world.setBlockInternal(x, 0, z, Block.STONE.getId(), 0);
                    world.setBlockInternal(x, 4, z, Block.STONE.getId(), 0);
                    for (int y = 1; y <= 3; y++) {
                        boolean center = x == 10 && z == 10;
                        world.setBlockInternal(x, y, z, (center ? Block.WATER : Block.STONE).getId(), 0);
                    }
                }
            }
            Husk husk = new Husk(10.5f, 1f, 10.5f, false, false);
            world.addLivingEntity(husk);
            for (int tick = 0; tick < 899; tick++) {
                world.updateEntities(TICK);
            }
            require(world.entityCount() == 1 && world.entityAt(0) == husk,
                    "Chưa đủ 45 giây thì chưa thể đổi Husk thành Zombie");
            for (int tick = 0; tick < 3; tick++) {
                world.updateEntities(TICK);
            }
            require(world.entityCount() == 1 && world.entityAt(0).getClass() == Zombie.class,
                    "Husk chìm đầu đủ lâu phải được thay bằng một Zombie trưởng thành");
        } finally {
            world.dispose();
        }
    }

    /** Enderman dùng chu kỳ 2 tick (0,10s) với xác suất nhặt 1/20 và đặt 1/2000 trên 1 ô ngẫu nhiên. */
    private static void checkEndermanBlockRates() {
        require(Enderman.PICKUP_CHANCE_DIVISOR == 20 && Enderman.PLACE_CHANCE_DIVISOR == 2000
                        && Math.abs(Enderman.BLOCK_CHECK_INTERVAL - 0.10f) < 0.0001f,
                "Hằng số nhặt/đặt khối của Enderman phải khớp chuẩn 1/20 và 1/2000 mỗi 2 tick");
        World world = World.empty();
        try {
            // Bao tường đá ở bán kính 3 để Enderman đứng yên và mọi ô -2..+2 quanh chân đều hợp lệ.
            for (int x = 7; x <= 13; x++) {
                for (int z = 7; z <= 13; z++) {
                    world.setBlockInternal(x, 0, z, Block.STONE.getId(), 0);
                    boolean rim = x == 7 || x == 13 || z == 7 || z == 13;
                    if (rim) {
                        for (int y = 1; y <= 4; y++) {
                            world.setBlockInternal(x, y, z, Block.STONE.getId(), 0);
                        }
                    } else if (!(x == 10 && z == 10)) {
                        world.setBlockInternal(x, 1, z, Block.GRASS.getId(), 0);
                    }
                }
            }
            Enderman enderman = new Enderman(10.5f, 1f, 10.5f);
            for (int tick = 0; tick < 4000 && enderman.heldBlock() == Block.AIR; tick++) {
                enderman.update(world, TICK);
            }
            require(enderman.heldBlock() == Block.GRASS, "Enderman phải nhặt được khối cỏ quanh chân");

            // Dọn sạch cỏ còn lại để có nền đá trống cho phép đặt khối (giữ khoảng trống -2..+2).
            for (int x = 8; x <= 12; x++) {
                for (int z = 8; z <= 12; z++) {
                    world.setBlockInternal(x, 1, z, Block.AIR.getId(), 0);
                }
            }
            for (int tick = 0; tick < 120_000 && enderman.heldBlock() != Block.AIR; tick++) {
                enderman.update(world, TICK);
            }
            require(enderman.heldBlock() == Block.AIR,
                    "Enderman đang cầm khối phải đặt lại được xuống nền rắn theo xác suất 1/2000 mỗi 2 tick");
        } finally {
            world.dispose();
        }
    }

    /** Vụ nổ theo mồi 1,5 giây làm mất khối có thể phá nhưng giữ nền bất hoại và chất lỏng. */
    private static void checkCreeperFuseAndBlockDamage() {
        World world = World.empty();
        try {
            floor(world, 0);
            world.registerPlayer(new Player(13.1f, 1f, 10.5f));
            world.setBlockInternal(10, 1, 9, Block.STONE.getId(), 0);
            world.setBlockInternal(9, 1, 10, Block.BEDROCK.getId(), 0);
            world.setBlockInternal(10, 1, 11, Block.WATER.getId(), 0);
            world.setBlockInternal(11, 1, 11, Block.LAVA.getId(), 0);
            Creeper creeper = new Creeper(10.5f, 1f, 10.5f);
            for (int tick = 0; tick < 29; tick++) {
                creeper.update(world, TICK);
            }
            require(creeper.isAlive() && creeper.mobVisualState().fuseProgress() > 0f
                            && world.getBlock(10, 1, 9) == Block.STONE.getId(), "Mồi cháy đủ 1,5 giây mới nổ");
            creeper.update(world, TICK);
            require(!creeper.isAlive() && world.getBlock(10, 1, 9) == Block.AIR.getId(),
                    "Creeper tự hủy và nổ vỡ đá gần tâm đúng nhịp");
            require(world.getBlock(9, 1, 10) == Block.BEDROCK.getId()
                            && world.getBlock(10, 1, 11) == Block.WATER.getId()
                            && world.getBlock(11, 1, 11) == Block.LAVA.getId(),
                    "Vụ nổ giữ Bedrock, Water và Lava");
        } finally {
            world.dispose();
        }
    }

    /** Mục tiêu rời bán kính 7 block trước khi hết mồi làm Creeper xẹp và ngừng nổ. */
    private static void checkCreeperCancelsFuse() {
        World world = World.empty();
        try {
            floor(world, 0);
            Player player = new Player(13.1f, 1f, 10.5f);
            world.registerPlayer(player);
            Creeper creeper = new Creeper(10.5f, 1f, 10.5f);
            creeper.update(world, TICK);
            require(creeper.mobVisualState().fuseProgress() > 0f, "Áp sát trong 3 block phải bắt đầu mồi");
            player.setPosition(19.5f, 1f, 10.5f);
            creeper.update(world, TICK);
            require(creeper.isAlive() && creeper.mobVisualState().fuseProgress() == 0f,
                    "Ra ngoài 7 block phải hủy mồi trong lượt kế tiếp");
        } finally {
            world.dispose();
        }
    }

    /** Nhện chỉ phát hiện người chơi khi trở trời tối và nhảy vồ hướng mục tiêu từ khoảng 3 block. */
    private static void checkSpiderStanceAndLeap() {
        World world = World.empty();
        try {
            floor(world, 0);
            Player player = new Player(13.5f, 1f, 10.5f);
            world.registerPlayer(player);
            Spider spider = new Spider(10.5f, 1f, 10.5f);
            spider.update(world, TICK);
            require(spider.attitude() == MobAttitude.NEUTRAL && spider.target() == null,
                    "Nhện ngoài trời ban ngày phải trung lập");
            world.worldTime().update(850);
            spider.update(world, TICK);
            require(spider.attitude() == MobAttitude.HOSTILE && spider.target() == player,
                    "Nhện ban đêm phải phát hiện người chơi");
            require(spider.y() > 1.05f && spider.x() > 10.5f, "Nhện ở cự ly 3 block phải bật nhảy về phía đích");
        } finally {
            world.dispose();
        }
    }

    /** Nhện đang di chuyển vào một vách cao vượt khả năng nhảy phải leo lên vách. */
    private static void checkSpiderClimbsWall() {
        World world = World.empty();
        try {
            floor(world, 0);
            for (int y = 1; y <= 5; y++) {
                for (int z = 8; z <= 12; z++) {
                    world.setBlockInternal(12, y, z, Block.STONE.getId(), 0);
                }
            }
            world.worldTime().update(850);
            world.registerPlayer(new Player(13.5f, 5f, 10.5f));
            Spider spider = new Spider(11.2f, 1f, 10.5f);
            for (int tick = 0; tick < 20; tick++) {
                spider.update(world, TICK);
            }
            require(spider.y() > 2f, "Nhện phải leo vách hơn một block khi ép sát để đuổi mục tiêu");
        } finally {
            world.dispose();
        }
    }

    /** Dựng nền phẳng dưới khu vực đấu và đuổi thử. */
    private static void floor(World world, int y) {
        for (int x = 4; x <= 48; x++) {
            for (int z = 5; z <= 15; z++) {
                world.setBlockInternal(x, y, z, Block.GRASS.getId(), 0);
            }
        }
    }

    /** So sánh kích thước hoặc chỉ số với sai số dấu phẩy động nhỏ. */
    private static void near(float actual, float expected, String message) {
        require(Math.abs(actual - expected) < 0.001f, message + " (" + actual + ")");
    }

    /** Nêu đúng trạng thái sai khi bộ kiểm tra thất bại. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

package com.voxelgame.engine;

import com.voxelgame.client.render.Camera;
import com.voxelgame.client.render.ShaderProgram;
import com.voxelgame.world.effect.StatusEffectType;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.gamemode.CreativeGameMode;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.weather.WeatherManager;
import com.voxelgame.world.level.World;
import com.voxelgame.world.physics.Raycast;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.Input;
import com.badlogic.gdx.math.Vector3;
import java.lang.reflect.Proxy;

/** Kiểm tra nền tảng sinh tồn và chiến đấu trên CPU. */
final class CombatAndLivingChecks {
    /** Chạy các phép kiểm tra của mốc chiến đấu. */
    static void run() {
        World world = World.empty();
        try {
            checkDamageAndDeath(world);
            checkStatusEffects(world);
            checkEntityRay(world);
            checkFireAndRain(world);
            checkPlayerSurvival(world);
            checkVoidRespawnControls(world);
            checkAttack(world);
        } finally {
            world.dispose();
        }
    }

    /** Nhấn đúp Space qua một lần rơi khỏi bản đồ vẫn phải bật bay như trước. */
    private static void checkVoidRespawnControls(World world) {
        Input previous = Gdx.input;
        boolean[] space = {true};
        Gdx.input = (Input) Proxy.newProxyInstance(Input.class.getClassLoader(), new Class<?>[]{Input.class},
                (proxy, method, args) -> method.getName().equals("isKeyPressed")
                        && space[0] && (int) args[0] == Input.Keys.SPACE);
        try {
            Player player = new Player(64.5f, -26f, 60.5f);
            // Chế độ bay bằng Space x2 thuộc CreativeGameMode
            player.setGameMode(CreativeGameMode.INSTANCE);
            player.attachControls(new Camera());
            player.update(world, 0.05f);
            near(player.getPosition().y, 20f, "Rơi dưới Y = -25 phải về mặt đỡ an toàn");
            near(player.getHealth(), 20f, "Dịch chuyển khỏi đáy bản đồ không tính sát thương rơi");
            space[0] = false;
            player.update(world, 0.05f);
            space[0] = true;
            player.update(world, 0.05f);
            require(player.isFlying(), "Hồi sinh từ đáy bản đồ phải giữ chuỗi nhấn đúp Space");
        } finally {
            Gdx.input = previous;
        }
    }

    /** Kiểm tra giáp, miễn sát thương, đẩy lùi, ghế và dọn thực thể sau hoạt ảnh. */
    private static void checkDamageAndDeath(World world) {
        Target target = new Target(30.5f, 15f, 30.5f, 10f, false, 1);
        Target rider = new Target(30.5f, 16f, 30.5f, 0f, false, 1);
        world.addLivingEntity(target);
        world.addLivingEntity(target);
        require(world.entityCount() == 1, "Đăng ký lại không được tạo bản sao");
        require(rider.tryMount(target, 0) && target.getPassenger(0) == rider
                && !target.tryMount(rider, 0), "Liên kết ghế phải hai chiều và không tạo chu trình");
        require(target.damage(world, 5f, DamageSource.MELEE, null, 2f, -1f), "Đòn đầu phải trúng");
        near(target.getHealth(), 16.5f, "Giáp phải giảm sát thương đòn vật lý");
        near(target.getHurtFlashTimer(), 0.5f, "Nháy bị thương phải dài nửa giây");
        require(target.getVelocity().epsilonEquals(2f, 0f, -1f, 0.0001f), "Đòn trúng phải đẩy lùi");
        world.updateEntities(0.49f);
        require(!target.damage(world, 30f, DamageSource.FALL, null, 0f, 0f),
                "Đòn trong cửa sổ bảo vệ phải bị chặn");
        world.updateEntities(0.01f);
        require(target.damage(world, 30f, DamageSource.FALL, null, 0f, 0f) && !target.isAlive(),
                "Sát thương rơi sau cửa sổ phải hạ mục tiêu và bỏ qua giáp");
        require(rider.getMount() == null && target.getPassenger(0) == null, "Thú chết phải giải phóng ghế");
        world.updateEntities(0.99f);
        require(!target.isReadyToRemove() && world.entityCount() == 1, "World phải giữ thực thể đủ thời gian chết");
        world.updateEntities(0.01f);
        require(target.isReadyToRemove() && world.entityCount() == 0, "World phải dọn thực thể đã chết");
    }

    /** Kiểm tra hệ số hiệu ứng, thay mới, thời gian hiệu lực và độc không gây chết. */
    private static void checkStatusEffects(World world) {
        Target target = new Target(32.5f, 15f, 30.5f, 0f, false, 0);
        target.applyEffect(StatusEffectType.SLOWNESS, 0, 2f);
        near(target.getMovementSpeedMultiplier(), 0.85f, "Slowness I giảm 15% tốc độ ngang");
        require(!target.applyEffect(StatusEffectType.SLOWNESS, 0, 1f), "Hiệu ứng ngắn hơn không ghi đè cùng cấp");
        require(target.applyEffect(StatusEffectType.SLOWNESS, 1, 1f), "Cấp mạnh hơn phải ghi đè");
        near(target.getMovementSpeedMultiplier(), 0.7f, "Slowness II giảm 30% tốc độ ngang");
        target.applyEffect(StatusEffectType.WEAKNESS, 0, 2f);
        near(target.getMeleeDamage(1f), 0f, "Tay không với Weakness I không gây sát thương");
        near(target.getMeleeDamage(6f), 2f, "Weakness I trừ 4 HP khỏi đòn");
        target.damage(world, 18.5f, DamageSource.MELEE, null, 0f, 0f);
        target.applyEffect(StatusEffectType.POISON, 0, 4f);
        target.update(world, 1f);
        require(!target.hasEffect(StatusEffectType.SLOWNESS), "Slowness hết hạn phải ngừng tác động");
        near(target.getHealth(), 1.5f, "Độc chưa được gây sát thương trước 1,25 giây");
        target.update(world, 0.25f);
        near(target.getHealth(), 1f, "Độc phải dừng ở đúng 1 HP");
        target.update(world, 2.75f);
        require(target.isAlive() && !target.hasEffect(StatusEffectType.POISON), "Độc hết hạn và không làm chết");
        Target undead = new Target(33.5f, 15f, 30.5f, 0f, true, 0);
        require(undead.isImmuneTo(StatusEffectType.POISON)
                && !undead.applyEffect(StatusEffectType.POISON, 1, 4f), "Undead phải miễn nhiễm độc");
    }

    /** Kiểm tra mục tiêu gần nhất, bỏ qua người bắn và chặn tia bằng hộp địa hình. */
    private static void checkEntityRay(World world) {
        Vector3 origin = new Vector3(50.5f, 15.5f, 50.5f);
        Vector3 direction = new Vector3(3f, 0f, 0f);
        Target shooter = new Target(50.5f, 15f, 50.5f, 0f, false, 0);
        Target far = new Target(53.5f, 15f, 50.5f, 0f, false, 0);
        Target near = new Target(52.5f, 15f, 50.5f, 0f, false, 0);
        world.addLivingEntity(shooter);
        world.addLivingEntity(far);
        world.addLivingEntity(near);
        Raycast.EntityHitResult result = new Raycast.EntityHitResult();
        Raycast.HitResult wall = Raycast.HitResult.miss();
        Raycast.castEntity(world, origin, direction, 3f, Float.POSITIVE_INFINITY, shooter, result);
        require(result.getEntity() == near, "Tia phải chọn thực thể gần nhất và bỏ qua chính người bắn");
        near(result.getDistance(), 1.7f, "Khoảng cách đo tới mặt AABB theo block");
        world.setBlockInternal(51, 15, 50, Block.STONE.getId(), 0);
        Raycast.castOccluder(world, origin, direction, 3f, wall);
        near(wall.getDistance(), 0.5f, "Vật cản phải trả khoảng cách đến mặt gần");
        Raycast.castEntity(world, origin, direction, 3f, wall.getDistance(), shooter, result);
        require(!result.isHit() && Float.isInfinite(result.getDistance()), "Không được đánh xuyên tường");
        world.setBlockInternal(51, 15, 50, Block.SHORT_GRASS.getId(), 0);
        Raycast.castOccluder(world, origin, direction, 3f, wall);
        require(!wall.isHit(), "Cỏ chữ X không được chặn đòn đánh");
        near.damage(world, 20f, DamageSource.MELEE, shooter, 0f, 0f);
        Raycast.castEntity(world, origin, direction, 3f, wall.getDistance(), shooter, result);
        require(result.getEntity() == far, "Tia phải bỏ qua thực thể chết");
    }

    /** Lửa mất một HP mỗi giây, tắt trong nước và chỉ tắt dưới mưa khi lộ thiên. */
    private static void checkFireAndRain(World world) {
        Target target = new Target(1500.5f, 12f, 60.5f, 8f, false, 0);
        target.ignite(4f);
        target.update(world, 1f);
        near(target.getHealth(), 19f, "Sát thương lửa không giảm bởi giáp");
        world.setBlockInternal(1500, 12, 60, Block.WATER.getId(), 0);
        target.update(world, 1f);
        near(target.getFireTimer(), 0f, "Nước phải dập lửa");
        near(target.getHealth(), 19f, "Dập lửa trước khi gây thêm sát thương");
        world.setBlockInternal(1500, 12, 60, Block.AIR.getId(), 0);

        WeatherManager weather = new WeatherManager(1L);
        world.setWeather(weather);
        weather.toggle();
        weather.update(1f);
        world.setBlockInternal(1500, 15, 60, Block.STONE.getId(), 0);
        target.ignite(4f);
        target.update(world, 1f);
        near(target.getHealth(), 18f, "Mái che phải ngăn mưa dập lửa");
        world.setBlockInternal(1500, 15, 60, Block.AIR.getId(), 0);
        target.update(world, 1f);
        near(target.getFireTimer(), 0f, "Mưa ngoài trời phải dập lửa");
        world.setWeather(null);
    }

    /** Kiểm tra vật lý thật của Player, hồi HP, giảm đói và hồi sinh an toàn. */
    private static void checkPlayerSurvival(World world) {
        world.setBlockInternal(60, 10, 60, Block.STONE.getId(), 0);
        world.setBlockInternal(61, 10, 60, Block.STONE.getId(), 0);
        world.setBlockInternal(World.RESPAWN_X, 19, World.RESPAWN_Z, Block.STONE.getId(), 0);
        Player player = new Player(60.5f, 19f, 60.5f);
        player.attachControls(new Camera());
        tick(player, world, 60);
        near(player.getHealth(), 15f, "Rơi 8 block phải mất 5 HP khi đáp đất");

        world.setBlockInternal(61, 11, 60, Block.WATER.getId(), 0);
        world.setBlockInternal(61, 12, 60, Block.WATER.getId(), 0);
        Player swimmer = new Player(61.5f, 19f, 60.5f);
        swimmer.attachControls(new Camera());
        tick(swimmer, world, 120);
        near(swimmer.getHealth(), 20f, "Đáp trong nước không mất HP do rơi");

        world.setBlockInternal(60, 10, 60, Block.SAND.getId(), 0);
        world.setBlockInternal(60, 11, 60, Block.CACTUS.getId(), 0);
        Player cactus = new Player(60.5f, 13f, 60.5f);
        cactus.attachControls(new Camera());
        tick(cactus, world, 20);
        near(cactus.getHealth(), 19f, "Chạm gai mất đúng 1 HP trong cửa sổ 0,5 giây");
        require(cactus.getCactusFlash() > 0f, "Chạm gai vẫn phải hiện viền đỏ");
        Player cactusLanding = new Player(60.5f, 20f, 60.5f);
        cactusLanding.attachControls(new Camera());
        tick(cactusLanding, world, 50);
        near(cactusLanding.getHealth(), 15f, "Rơi xa xuống gai phải tính sát thương rơi trước khi bật nảy");

        world.setBlockInternal(62, 12, 60, Block.LAVA.getId(), 0);
        Player lava = new Player(62.5f, 12f, 60.5f);
        lava.update(world, 0.05f);
        near(lava.getHealth(), 16f, "Người chơi chạm dung nham mất 4 HP");
        require(lava.getFireTimer() > 0f, "Dung nham phải làm cháy");
        lava.update(world, 0.45f);
        near(lava.getHealth(), 16f, "Lava vẫn tuân thủ miễn sát thương");
        lava.update(world, 0.05f);
        near(lava.getHealth(), 12f, "Lava tiếp tục gây sát thương sau nửa giây");

        Player hungry = new Player(63.5f, 13f, 60.5f);
        hungry.damage(world, 3f, DamageSource.MELEE, null, 0f, 0f);
        hungry.update(world, 4f);
        near(hungry.getHealth(), 18f, "Đủ độ đói phải hồi một HP sau bốn giây");
        near(hungry.getHunger(), 19f, "Hồi máu phải tiêu hao một điểm đói");
        hungry.applyEffect(StatusEffectType.HUNGER, 1, 2f);
        hungry.update(world, 2f);
        near(hungry.getHunger(), 17f, "Hunger II phải tiêu hao một điểm đói mỗi giây");
        hungry.ignite(3f);
        hungry.applyEffect(StatusEffectType.SLOWNESS, 0, 2f);
        hungry.damage(world, 20f, DamageSource.FALL, null, 2f, 0f);
        hungry.update(world, 0.05f);
        require(hungry.getPosition().epsilonEquals(World.RESPAWN_X, 20f, World.RESPAWN_Z, 0.001f),
                "Hết HP phải hồi sinh tại mặt đỡ an toàn");
        require(hungry.isAlive() && !hungry.hasEffect(StatusEffectType.SLOWNESS)
                && hungry.getFireTimer() == 0f && !hungry.isFlying() && hungry.getVelocity().isZero(),
                "Hồi sinh phải dọn trạng thái chiến đấu và chuyển động");
        near(hungry.getHealth(), 20f, "Hồi sinh đầy HP");
        near(hungry.getHunger(), 20f, "Hồi sinh đầy độ đói");
    }

    /** Kiểm tra cú đánh thường, hồi chiêu, đòn giữa lúc rơi và tốc độ Slowness thực tế. */
    private static void checkAttack(World world) {
        Player attacker = new Player(70.5f, 15f, 70.5f);
        Target first = new Target(72.5f, 15f, 70.5f, 0f, false, 0);
        Target second = new Target(73.5f, 15f, 70.5f, 0f, false, 0);
        Vector3 direction = new Vector3(2f, 1f, 0f);
        attacker.attack(world, first, direction);
        attacker.attack(world, second, direction);
        near(first.getHealth(), 19f, "Đòn tay không gây 1 HP");
        near(second.getHealth(), 20f, "Hồi chiêu theo người đánh, kể cả khi đổi mục tiêu");
        attacker.attachControls(new Camera());
        attacker.update(world, 0.6f);
        attacker.attack(world, second, direction);
        near(second.getHealth(), 18.5f, "Đòn trong lúc rơi gây Critical Hit 1,5 HP");
        near(second.getVelocity().x, 2f, "Đòn đánh đẩy theo hướng nhìn chiếu ngang");

        Input previous = Gdx.input;
        Gdx.input = (Input) Proxy.newProxyInstance(Input.class.getClassLoader(), new Class<?>[]{Input.class},
                (proxy, method, args) -> method.getName().equals("isKeyPressed") && (int) args[0] == Input.Keys.W);
        try {
            Camera camera = new Camera();
            camera.rotate(90f, 0f);
            Player moving = new Player(75.5f, 15f, 70.5f);
            moving.attachControls(camera);
            moving.applyEffect(StatusEffectType.SLOWNESS, 0, 2f);
            moving.update(world, 0.05f);
            near(moving.getVelocity().x, 5.5f * 0.85f, "Slowness phải tác động lên vận tốc điều khiển");
        } finally {
            Gdx.input = previous;
        }
    }

    /** Tiến vật lý theo bước thời gian của vòng lặp thật. */
    private static void tick(Player player, World world, int steps) {
        for (int i = 0; i < steps; i++) {
            player.update(world, 1f / 60f);
        }
    }

    /** So sánh điểm sinh tồn với sai số dấu phẩy động nhỏ. */
    private static void near(float actual, float expected, String message) {
        require(Math.abs(actual - expected) < 0.001f, message + " (" + actual + " thay vì " + expected + ")");
    }

    /** Báo lỗi kèm hành vi chưa đáp ứng. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    /** Mục tiêu đứng yên cho kiểm tra quy tắc chiến đấu ngoài OpenGL. */
    private static final class Target extends LivingEntity {
        /** Đặt mục tiêu với AABB cố định và các tùy chọn giáp, tộc và ghế. */
        private Target(float x, float y, float z, float armor, boolean undead, int seats) {
            super(x, y, z, 0.3f, 1.8f, 20f, armor, undead, seats);
        }

        /** Giữ nguyên vị trí để cô lập luật chiến đấu khỏi AI. */
        @Override
        protected void updateLiving(World world, float deltaTime) {
        }

        /** Mục tiêu kiểm thử chạy trên CPU. */
        @Override
        public void render(ShaderProgram shader) {
        }
    }
}

