/**
 * Kiểm tra hồi quy toàn bộ hệ thống rơi vật phẩm mob, tương tác đặc biệt (đẻ trứng, cắt lông,
 * vắt sữa, húc rơi sừng, đốt cháy ra thịt chín), texture vật phẩm và texture/SFX Skeleton gốc.
 */
final class MobLootChecks {

    private MobLootChecks() {
    }

    static void run() {
        checkItemTexturesAndNames();
        checkSkeletonAssetsAndSfx();
        checkHotbarAndItemEntity();
        checkFireCookedAndPassiveDrops();
        checkChickenEggLaying();
        checkSheepShearingAndRegrowth();
        checkCowAndGoatMilkingAndHorn();
        checkHostileAndSpecialDrops();
    }

    /** Xác nhận đủ 56 PNG vật phẩm 16 × 16 hợp lệ và tên hiển thị khớp font 5 × 7. */
    private static void checkItemTexturesAndNames() {
        List<Item> items = Item.allStandaloneItems();
        require(items.size() == 56, "Phải có đủ 56 vật phẩm độc lập (" + items.size() + ")");
        for (Item item : items) {
            String path = "textures/item/" + item.getTextureName() + ".png";
            try (InputStream stream = openAsset(path)) {
                BufferedImage img = ImageIO.read(stream);
                require(img != null && img.getWidth() == 16 && img.getHeight() == 16,
                        "Ảnh vật phẩm phải đúng 16x16: " + path);
                boolean hasOpaquePixel = false;
                for (int y = 0; y < 16 && !hasOpaquePixel; y++) {
                    for (int x = 0; x < 16; x++) {
                        if (((img.getRGB(x, y) >>> 24) & 0xFF) >= 13) {
                            hasOpaquePixel = true;
                            break;
                        }
                    }
                }
                require(hasOpaquePixel, "Ảnh vật phẩm không được rỗng: " + path);
            } catch (IOException error) {
                throw new AssertionError("Không đọc được " + path, error);
            }
            for (int i = 0; i < item.getDisplayName().length(); i++) {
                char c = Character.toUpperCase(item.getDisplayName().charAt(i));
                require(c == ' ' || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9'),
                        "Tên vật phẩm chứa ký tự không có trong font 5x7: " + item.getDisplayName());
            }
        }
    }

    /** Xác nhận texture Skeleton 64 × 32 và đầy đủ biến thể SFX Skeleton chuẩn Minecraft gốc. */
    private static void checkSkeletonAssetsAndSfx() {
        try (InputStream stream = openAsset("textures/entity/skeleton/skeleton.png")) {
            BufferedImage img = ImageIO.read(stream);
            require(img != null && img.getWidth() == 64 && img.getHeight() == 32,
                    "Texture skeleton.png phải có kích thước 64x32 chuẩn Minecraft");
        } catch (IOException error) {
            throw new AssertionError("Không đọc được skeleton.png", error);
        }

        checkDistinctWavSet("ambient", 3);
        checkDistinctWavSet("hurt", 4);
        checkDistinctWavSet("step", 4);
        checkDistinctWavSet("death", 2);
    }

    private static void checkDistinctWavSet(String eventName, int count) {
        Set<String> hashes = new HashSet<>();
        for (int i = 1; i <= count; i++) {
            String path = "audio/sfx/mob/skeleton/" + eventName + i + ".wav";
            try (InputStream raw = openAsset(path)) {
                byte[] bytes = raw.readAllBytes();
                try (var audio = AudioSystem.getAudioInputStream(new BufferedInputStream(
                        new java.io.ByteArrayInputStream(bytes)))) {
                    AudioFormat format = audio.getFormat();
                    require(format.getEncoding().equals(AudioFormat.Encoding.PCM_SIGNED)
                            && format.getSampleSizeInBits() == 16
                            && format.getChannels() == 1
                            && Math.abs(format.getSampleRate() - 22050f) < 1f
                            && audio.getFrameLength() > 0,
                            "Sai định dạng WAV Skeleton: " + path);
                }
                hashes.add(sha1Hex(bytes));
            } catch (UnsupportedAudioFileException | IOException error) {
                throw new AssertionError("Lỗi kiểm tra âm thanh " + path, error);
            }
        }
        if (!"death".equals(eventName)) {
            require(hashes.size() == count, "Các biến thể " + eventName + " của Skeleton phải khác nhau");
        }
    }

    /** Kiểm tra Hotbar trống khi khởi tạo, giới hạn xếp chồng và nhặt ItemEntity cho vật phẩm độc lập. */
    private static void checkHotbarAndItemEntity() {
        Hotbar hotbar = new Hotbar();
        for (int i = 0; i < Hotbar.SLOT_COUNT; i++) {
            require(hotbar.getSlotItem(i).isNone() && hotbar.getSlotCount(i) == 0,
                    "Hotbar mới khởi tạo phải trống hoàn toàn tại ô " + i);
        }

        hotbar.setSlot(1, Item.SHEARS, 1);
        require(hotbar.addItem(Item.EGG, 18), "Phải thêm được trứng");
        require(hotbar.getSlotItem(0) == Item.EGG && hotbar.getSlotCount(0) == 16, "Trứng chỉ xếp tối đa 16/ô");
        require(hotbar.getSlotItem(2) == Item.EGG && hotbar.getSlotCount(2) == 2, "Trứng dư tràn sang ô trống kế tiếp");
        require(hotbar.getSlotCount(1) == 1 && hotbar.getSlotItem(1) == Item.SHEARS, "Không ghi đè ô có sẵn");

        World world = World.empty();
        try {
            Player player = new Player(10.5f, 11f, 10.5f);
            world.registerPlayer(player);
            ItemEntity pearl = new ItemEntity(10.5f, 11.2f, 10.5f, Item.ENDER_PEARL);
            world.spawnDroppedItem(pearl);
            for (int i = 0; i < 30; i++) {
                pearl.update(world, player, player.getHotbar(), 0.025f);
            }
            require(pearl.isCollected() && player.getHotbar().getSlotItem(0) == Item.ENDER_PEARL,
                    "Người chơi phải nhặt được ItemEntity độc lập vào Hotbar");
        } finally {
            world.dispose();
        }
    }

    /** Kiểm tra rơi đồ thường và chín khi mob bị đốt bởi Flint and Steel hoặc lửa. */
    private static void checkFireCookedAndPassiveDrops() {
        World world = arena();
        try {
            Player player = new Player(100.5f, 20f, 100.5f);
            world.registerPlayer(player);

            // Đốt lợn bằng Flint and Steel rồi kết liễu -> phải rơi thịt chín
            Pig pig = new Pig(102.5f, 20f, 100.5f);
            player.getHotbar().setSlot(7, Item.FLINT_AND_STEEL, 1);
            player.getHotbar().selectSlot(7);
            require(pig.onPlayerInteract(world, player) && pig.getFireTimer() > 0f,
                    "Flint and Steel phải đốt cháy mob");
            pig.damage(world, 20f, DamageSource.MELEE, player, 0f, 0f);
            List<Item> pigDrops = collectGroundItems(world);
            require(!pigDrops.isEmpty() && allMatch(pigDrops, Item.COOKED_PORKCHOP),
                    "Lợn chết khi đang cháy phải rơi Cooked Porkchop");

            // Bò thường -> thịt bò sống (+ da tùy ngẫu nhiên)
            Cow cow = new Cow(102.5f, 20f, 100.5f);
            cow.damage(world, 20f, DamageSource.MELEE, player, 0f, 0f);
            List<Item> cowDrops = collectGroundItems(world);
            require(countItem(cowDrops, Item.BEEF) >= 1, "Bò chết thường phải rơi Raw Beef");

            // Bò cháy -> Steak
            Cow fireCow = new Cow(102.5f, 20f, 100.5f);
            fireCow.damage(world, 20f, DamageSource.FIRE, player, 0f, 0f);
            List<Item> fireCowDrops = collectGroundItems(world);
            require(countItem(fireCowDrops, Item.COOKED_BEEF) >= 1, "Bò chết cháy phải rơi Steak");

            // Gà cháy -> Cooked Chicken
            Chicken chicken = new Chicken(102.5f, 20f, 100.5f);
            chicken.damage(world, 20f, DamageSource.LAVA, player, 0f, 0f);
            List<Item> chickenDrops = collectGroundItems(world);
            require(countItem(chickenDrops, Item.COOKED_CHICKEN) == 1, "Gà chết cháy phải rơi 1 Cooked Chicken");

            // Gấu con không rơi đồ; gấu lớn cháy rơi cá chín
            PolarBear cub = new PolarBear(102.5f, 20f, 100.5f, true);
            cub.damage(world, 50f, DamageSource.MELEE, player, 0f, 0f);
            require(collectGroundItems(world).isEmpty(), "Gấu con không được rơi vật phẩm");

            boolean bearDroppedFish = false;
            for (int attempt = 0; attempt < 20; attempt++) {
                PolarBear adultBear = new PolarBear(102.5f, 20f, 100.5f, false);
                adultBear.damage(world, 50f, DamageSource.FIRE, player, 0f, 0f);
                List<Item> drops = collectGroundItems(world);
                for (Item drop : drops) {
                    require(drop == Item.COOKED_COD || drop == Item.COOKED_SALMON,
                            "Gấu cháy chỉ được rơi cá tuyết hoặc cá hồi chín");
                    bearDroppedFish = true;
                }
            }
            require(bearDroppedFish, "Gấu trưởng thành phải có lượt rơi cá chín");

            // Ngựa, Lừa, Lạc đà, Camel Husk, Sói
            Camel camel = new Camel(102.5f, 20f, 100.5f);
            camel.damage(world, 50f, DamageSource.MELEE, player, 0f, 0f);
            require(collectGroundItems(world).isEmpty(), "Camel không rơi đồ khi chết");

            CamelHusk camelHusk = new CamelHusk(102.5f, 20f, 100.5f);
            camelHusk.damage(world, 50f, DamageSource.MELEE, player, 0f, 0f);
            List<Item> chDrops = collectGroundItems(world);
            require(chDrops.size() >= 2 && chDrops.size() <= 3 && allMatch(chDrops, Item.ROTTEN_FLESH),
                    "Camel Husk phải rơi 2–3 Rotten Flesh");

            Wolf wolf = new Wolf(102.5f, 20f, 100.5f);
            wolf.damage(world, 20f, DamageSource.MELEE, player, 0f, 0f);
            require(collectGroundItems(world).isEmpty(), "Wolf không rơi đồ khi chết");

            Horse horse = new Horse(102.5f, 20f, 100.5f);
            horse.damage(world, 50f, DamageSource.MELEE, player, 0f, 0f);
            List<Item> horseDrops = collectGroundItems(world);
            require(allMatch(horseDrops, Item.LEATHER) && horseDrops.size() <= 2, "Ngựa chỉ rơi 0–2 Leather");

            Donkey donkey = new Donkey(102.5f, 20f, 100.5f);
            donkey.damage(world, 50f, DamageSource.MELEE, player, 0f, 0f);
            List<Item> donkeyDrops = collectGroundItems(world);
            require(allMatch(donkeyDrops, Item.LEATHER) && donkeyDrops.size() <= 2, "Lừa chỉ rơi 0–2 Leather");

            Rabbit rabbit = new Rabbit(102.5f, 20f, 100.5f);
            rabbit.damage(world, 20f, DamageSource.FIRE, player, 0f, 0f);
            for (Item drop : collectGroundItems(world)) {
                require(drop == Item.RABBIT_HIDE || drop == Item.COOKED_RABBIT || drop == Item.RABBIT_FOOT,
                        "Thỏ cháy chỉ rơi da, thịt thỏ chín hoặc chân thỏ");
            }
        } finally {
            world.dispose();
        }
    }

    /** Kiểm tra gà tự đẻ trứng khi bộ đếm kết thúc chu kỳ. */
    private static void checkChickenEggLaying() {
        World world = arena();
        try {
            Chicken chicken = new Chicken(100.5f, 20f, 100.5f);
            chicken.setEggTimerForTest(0.1f);
            chicken.update(world, 0.2f);
            List<Item> drops = collectGroundItems(world);
            require(drops.size() == 1 && drops.get(0) == Item.EGG, "Gà hết chu kỳ phải đẻ ra 1 Egg");
            require(chicken.eggTimer() >= 299f, "Sau khi đẻ trứng phải đặt lại chu kỳ 300–600s");
        } finally {
            world.dispose();
        }
    }

    /** Kiểm tra cắt lông cừu bằng Shears, chết khi không còn lông và mọc lại lông sau khi ăn cỏ. */
    private static void checkSheepShearingAndRegrowth() {
        World world = arena();
        try {
            Player player = new Player(100.5f, 20f, 100.5f);
            world.registerPlayer(player);
            Sheep pinkSheep = new Sheep(102.5f, 20f, 100.5f, Sheep.WoolColor.PINK);

            player.getHotbar().setSlot(6, Item.SHEARS, 1);
            player.getHotbar().selectSlot(6); // Shears
            require(pinkSheep.onPlayerInteract(world, player), "Cừu phải cho phép cắt lông bằng Shears");
            require(pinkSheep.isSheared() && pinkSheep.mobVisualState().isSheepSheared(),
                    "Cừu sau cắt lông phải cập nhật trạng thái sheared");
            List<Item> woolDrops = collectGroundItems(world);
            require(woolDrops.size() >= 1 && woolDrops.size() <= 3 && allMatch(woolDrops, Item.PINK_WOOL),
                    "Cắt lông cừu hồng phải rơi 1–3 Pink Wool");
            require(!pinkSheep.onPlayerInteract(world, player), "Cừu đã trọc lông không thể cắt lần nữa");

            // Khi mọc lại lông thì phải rơi lại len lúc bị giết
            pinkSheep.regrowWool();
            require(!pinkSheep.isSheared() && !pinkSheep.mobVisualState().isSheepSheared(),
                    "Cừu ăn cỏ mọc lại lông");
            pinkSheep.damage(world, 20f, DamageSource.MELEE, player, 0f, 0f);
            List<Item> deathDrops = collectGroundItems(world);
            require(countItem(deathDrops, Item.PINK_WOOL) == 1 && countItem(deathDrops, Item.MUTTON) >= 1,
                    "Cừu có lông chết phải rơi 1 len đúng màu và thịt cừu");

            // Cừu đã cắt lông chết không rơi len
            Sheep shearedSheep = new Sheep(102.5f, 20f, 100.5f, Sheep.WoolColor.WHITE);
            shearedSheep.shear(world);
            collectGroundItems(world);
            shearedSheep.damage(world, 20f, DamageSource.FIRE, player, 0f, 0f);
            List<Item> shearedDeathDrops = collectGroundItems(world);
            require(countItem(shearedDeathDrops, Item.WHITE_WOOL) == 0
                            && countItem(shearedDeathDrops, Item.COOKED_MUTTON) >= 1,
                    "Cừu đã cắt lông chết cháy chỉ rơi thịt cừu chín");
        } finally {
            world.dispose();
        }
    }

    /** Kiểm tra vắt sữa bò & dê, uống Milk Bucket xóa hiệu ứng và dê húc đá rơi sừng. */
    private static void checkCowAndGoatMilkingAndHorn() {
        World world = arena();
        try {
            Player player = new Player(100.5f, 20f, 100.5f);
            world.registerPlayer(player);
            player.applyEffect(StatusEffectType.POISON, 0, 20f);
            require(player.hasEffect(StatusEffectType.POISON), "Cần hiệu ứng để kiểm tra Milk Bucket");

            Cow cow = new Cow(102.5f, 20f, 100.5f);
            player.getHotbar().setSlot(8, Item.BUCKET, 1);
            player.getHotbar().selectSlot(8); // Bucket ở ô 9
            require(cow.onPlayerInteract(world, player), "Vắt sữa bò bằng Bucket phải thành công");
            require(player.getHotbar().getSlotItem(0) == Item.MILK_BUCKET, "Milk Bucket phải vào ô trống Hotbar");

            // Uống sữa xóa hiệu ứng và trả lại Bucket
            player.clearStatusEffects();
            require(!player.hasEffect(StatusEffectType.POISON), "Uống Milk Bucket phải xóa hiệu ứng");

            // Vắt sữa dê
            Goat milkGoat = new Goat(102.5f, 20f, 100.5f);
            player.getHotbar().setSlot(8, Item.BUCKET, 1);
            player.getHotbar().selectSlot(8);
            require(milkGoat.onPlayerInteract(world, player), "Vắt sữa dê bằng Bucket phải thành công");

            // Dê húc vào cột đá phải rơi Goat Horn
            player.setPosition(96.5f, 20f, 100.5f);
            world.setBlock(104, 20, 100, Block.STONE.getId());
            world.setBlock(104, 21, 100, Block.STONE.getId());
            Goat ramGoat = new Goat(102.5f, 20f, 100.5f);
            world.addLivingEntity(ramGoat);
            // Ép mục tiêu giả phía sau bức tường đá để dê lao thẳng vào đá
            Cow dummyTarget = new Cow(105.2f, 20f, 100.5f);
            world.addLivingEntity(dummyTarget);
            // Dùng reflection đặt ramDelay = 0 để dê bắt đầu húc ngay
            var ramDelayField = Goat.class.getDeclaredField("ramDelay");
            ramDelayField.setAccessible(true);
            ramDelayField.setFloat(ramGoat, 0f);
            for (int i = 0; i < 60; i++) {
                ramGoat.update(world, 0.05f);
            }
            List<Item> goatDrops = collectGroundItems(world);
            require(countItem(goatDrops, Item.GOAT_HORN) >= 1 && ramGoat.hornCount() < 2,
                    "Dê húc vào khối đá phải rơi ra Goat Horn");
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("Lỗi kiểm tra Goat ram", e);
        } finally {
            world.dispose();
        }
    }

    /** Kiểm tra rơi đồ quái thù địch: Skeleton, Stray, Parched, Husk, Creeper đĩa nhạc, Enderman, Witch. */
    private static void checkHostileAndSpecialDrops() {
        World world = arena();
        try {
            Player player = new Player(100.5f, 20f, 100.5f);
            world.registerPlayer(player);

            // Creeper bị Skeleton bắn chết -> rơi đĩa nhạc 13 hoặc cat
            Skeleton skeleton = new Skeleton(100.5f, 20f, 100.5f);
            Creeper creeperShot = new Creeper(103.5f, 20f, 100.5f);
            world.addLivingEntity(creeperShot);
            ArrowEntity arrow = new ArrowEntity(skeleton, 102.5f, 21f, 100.5f, 10f, 0f, 0f, ArrowType.NORMAL, 25f);
            creeperShot.damage(world, 25f, DamageSource.ARROW, skeleton, 0f, 0f);
            List<Item> creeperDrops = collectGroundItems(world);
            require(countItem(creeperDrops, Item.MUSIC_DISC_13) + countItem(creeperDrops, Item.MUSIC_DISC_CAT) == 1,
                    "Creeper bị Skeleton bắn chết phải rơi đúng 1 đĩa nhạc");
            arrow.isFinished();

            // Creeper tự nổ (discard) -> không rơi đồ
            Creeper creeperBoom = new Creeper(103.5f, 20f, 100.5f);
            creeperBoom.discard();
            require(collectGroundItems(world).isEmpty(), "Creeper tự nổ không được rơi vật phẩm");

            // Enderman giữ khối -> phải rơi khối đang giữ khi chết
            Enderman enderman = new Enderman(103.5f, 20f, 100.5f);
            var heldField = Enderman.class.getDeclaredField("heldBlock");
            heldField.setAccessible(true);
            heldField.set(enderman, Block.GRASS);
            enderman.damage(world, 50f, DamageSource.MELEE, player, 0f, 0f);
            List<Item> enderDrops = collectGroundItems(world);
            require(countItem(enderDrops, Item.of(Block.GRASS)) == 1,
                    "Enderman chết phải rơi lại khối đang cầm");

            // Witch đang uống thuốc -> có cơ hội rơi đúng loại thuốc đang uống
            Witch witch = new Witch(103.5f, 20f, 100.5f);
            witch.damage(world, 2f, DamageSource.MELEE, player, 0f, 0f);
            witch.update(world, 0.2f);
            require(witch.drinkingPotionItem() == Item.POTION_HEALING,
                    "Witch bị thương phải chuyển sang uống Potion of Healing");

            // Witch chết chuẩn Java 1.21+: luôn rơi cố định 4–8 Redstone Dust + 1–3 lượt × 0–2 từ 6 món còn lại
            int extraDropsTotal = 0;
            for (int i = 0; i < 30; i++) {
                Witch lootWitch = new Witch(103.5f, 20f, 100.5f);
                lootWitch.damage(world, 50f, DamageSource.MELEE, player, 0f, 0f);
                List<Item> witchDrops = collectGroundItems(world);
                int redstoneCount = countItem(witchDrops, Item.REDSTONE);
                require(redstoneCount >= 4 && redstoneCount <= 8,
                        "Witch phải luôn rơi cố định 4–8 Redstone Dust (nhận " + redstoneCount + ")");
                int nonRedstone = 0;
                for (Item drop : witchDrops) {
                    if (drop == Item.REDSTONE) {
                        continue;
                    }
                    require(drop == Item.GLASS_BOTTLE || drop == Item.GLOWSTONE_DUST || drop == Item.GUNPOWDER
                                    || drop == Item.SPIDER_EYE || drop == Item.SUGAR || drop == Item.STICK,
                            "Vật phẩm phụ của Witch phải thuộc 6 món hợp lệ (" + drop + ")");
                    nonRedstone++;
                }
                require(nonRedstone <= 6, "Tối đa 3 lượt × 2 món phụ từ Witch (" + nonRedstone + ")");
                extraDropsTotal += nonRedstone;
            }
            require(extraDropsTotal > 0, "Witch phải có rơi thêm vật phẩm phụ ngoài Redstone");

            // Kiểm tra Husk cầm giáo sắt, Zombie, Zombie Villager, Stray, Parched, Spider không ném lỗi
            new Zombie(103.5f, 20f, 100.5f, false).damage(world, 30f, DamageSource.FIRE, player, 0f, 0f);
            new ZombieVillager(103.5f, 20f, 100.5f).damage(world, 30f, DamageSource.MELEE, player, 0f, 0f);
            new Husk(103.5f, 20f, 100.5f, true).damage(world, 30f, DamageSource.MELEE, player, 0f, 0f);
            new Stray(103.5f, 20f, 100.5f).damage(world, 30f, DamageSource.MELEE, player, 0f, 0f);
            new Parched(103.5f, 20f, 100.5f).damage(world, 30f, DamageSource.MELEE, player, 0f, 0f);
            new Spider(103.5f, 20f, 100.5f).damage(world, 30f, DamageSource.MELEE, player, 0f, 0f);
            collectGroundItems(world);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("Lỗi kiểm tra Enderman heldBlock", e);
        } finally {
            world.dispose();
        }
    }

    private static List<Item> collectGroundItems(World world) {
        List<Item> result = new ArrayList<>();
        for (int i = 0; i < world.entityCount(); i++) {
            if (world.entityAt(i) instanceof ItemEntity entity && !entity.isCollected()) {
                Item item = entity.collectItemForMob();
                if (item != null) {
                    result.add(item);
                }
            }
        }
        return result;
    }

    private static boolean allMatch(List<Item> items, Item expected) {
        for (Item item : items) {
            if (item != expected) {
                return false;
            }
        }
        return true;
    }

    private static int countItem(List<Item> items, Item target) {
        int count = 0;
        for (Item item : items) {
            if (item == target) {
                count++;
            }
        }
        return count;
    }

    private static World arena() {
        World world = World.empty();
        for (int x = 96; x <= 108; x++) {
            for (int z = 96; z <= 108; z++) {
                world.setBlock(x, 19, z, Block.STONE.getId());
            }
        }
        return world;
    }

    private static InputStream openAsset(String path) {
        InputStream stream = MobLootChecks.class.getClassLoader().getResourceAsStream(path);
        require(stream != null, "Thiếu tài nguyên: " + path);
        return stream;
    }

    private static String sha1Hex(byte[] bytes) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-1").digest(bytes);
            return java.util.HexFormat.of().formatHex(digest);
        } catch (NoSuchAlgorithmException e) {
            throw new AssertionError(e);
        }
    }

    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

package com.voxelgame.engine;

import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.monster.Zombie;
import com.voxelgame.world.level.biome.BiomeType;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.weather.WeatherManager;
import com.voxelgame.world.level.World;

/** Kiểm tra chuyển động mob với địa hình nhỏ, không cần GPU hoặc bộ phát âm thanh. */
final class MobPhysicsChecks {
    /** Chạy các phép thử bậc, chất lỏng, tránh nguy hiểm và ánh nắng. */
    static void run() {
        World world = World.empty();
        try {
            checkJumpAndCeiling(world);
            checkDirectStepAndHazards(world);
            checkCornerRouting(world);
            checkWaterAndLava(world);
            checkSunlight(world);
        } finally {
            world.dispose();
        }
    }

    /** Bộ điều hướng đổi hướng quanh đầu tường ngắn rồi tiếp tục về đích. */
    private static void checkCornerRouting(World world) {
        fill(world, 68, 78, 47, 57, 15, Block.STONE);
        for (int y = 16; y <= 18; y++) {
            fill(world, 72, 72, 50, 52, y, Block.STONE);
        }
        Fixture corner = new Fixture(MobType.ZOMBIE, 70.5f, 16f, 51.5f);
        corner.update(world, 0.05f);
        for (int i = 0; i < 92; i++) {
            corner.moveToward(world, 76.5f, 16f, 51.5f, 1f);
            corner.update(world, 0.05f);
        }
        require(corner.x() > 75f && Math.abs(corner.z() - 51.5f) < 0.4f,
                "Điều hướng phải vòng được đầu tường thay vì dừng ở góc");
    }

    /** Bước thẳng được qua bậc 1,5 block và lệnh đi vẫn tránh gai, vực sâu. */
    private static void checkDirectStepAndHazards(World world) {
        fill(world, 41, 47, 10, 13, 15, Block.STONE);
        fill(world, 43, 47, 10, 13, 16, Block.STONE);
        for (int x = 43; x <= 47; x++) {
            for (int z = 10; z <= 13; z++) {
                world.setBlockInternal(x, 17, z, Block.SNOW_LAYER.getId(), 4);
            }
        }
        Fixture mount = new Fixture(MobType.COW, 42.5f, 16f, 11.5f);
        mount.setStepHeight(1.5f);
        mount.setDirectStep(true);
        mount.update(world, 0.05f);
        for (int i = 0; i < 50; i++) {
            mount.moveToward(world, 45.5f, 17.5f, 11.5f, 1f);
            mount.update(world, 0.05f);
            require(mount.isOnGround() && mount.y() <= 17.5f, "Bước thẳng phải luôn giữ chân trên nền");
        }
        require(mount.x() > 44.5f && mount.y() == 17.5f, "Thú dùng bước thẳng phải lên được bậc 1,5 block");

        fill(world, 50, 54, 10, 13, 20, Block.STONE);
        fill(world, 55, 59, 10, 13, 15, Block.STONE);
        fill(world, 52, 52, 10, 13, 21, Block.CACTUS);
        Fixture nearCactus = new Fixture(MobType.ZOMBIE, 51.5f, 21f, 11.5f);
        Fixture nearCliff = new Fixture(MobType.ZOMBIE, 54.5f, 21f, 11.5f);
        nearCactus.update(world, 0.05f);
        nearCliff.update(world, 0.05f);
        for (int i = 0; i < 50; i++) {
            nearCactus.moveToward(world, 54.5f, 21f, 11.5f, 1f);
            nearCliff.moveToward(world, 58.5f, 16f, 11.5f, 1f);
            nearCactus.update(world, 0.05f);
            nearCliff.update(world, 0.05f);
        }
        require(nearCactus.x() < 52f && nearCliff.y() == 21f && nearCliff.x() < 55.5f,
                "Điều hướng phải tránh gai và từ chối vực sâu quá ba block");
        require(new Fixture(MobType.GOAT, 0f, 0f, 0f).maxSafeFall() > nearCliff.maxSafeFall()
                        && new Fixture(MobType.CHICKEN, 0f, 0f, 0f).maxSafeFall() > nearCliff.maxSafeFall(),
                "Dê và gà phải có ngưỡng rơi an toàn lớn hơn mặc định");
    }

    /** Một bậc cao một khối đi được, cùng bậc dưới trần thấp phải chặn. */
    private static void checkJumpAndCeiling(World world) {
        fill(world, 11, 17, 10, 13, 15, Block.STONE);
        fill(world, 13, 17, 10, 13, 16, Block.STONE);
        Fixture open = new Fixture(MobType.ZOMBIE, 12.5f, 16f, 11.5f);
        open.update(world, 0.05f);
        float top = open.y();
        for (int i = 0; i < 64; i++) {
            open.moveToward(world, 15.5f, 17f, 11.5f, 1f);
            open.update(world, 0.05f);
            top = Math.max(top, open.y());
        }
        require(open.x() > 14f && open.y() >= 17f && top > 17.1f,
                "Mob phải tự bật qua bậc cao một block");

        fill(world, 12, 17, 10, 13, 18, Block.STONE);
        Fixture roof = new Fixture(MobType.ZOMBIE, 12.5f, 16f, 11.5f);
        roof.update(world, 0.05f);
        for (int i = 0; i < 40; i++) {
            roof.moveToward(world, 15.5f, 17f, 11.5f, 1f);
            roof.update(world, 0.05f);
        }
        require(roof.x() < 13f && Math.abs(roof.y() - 16f) < 0.01f,
                "Mob chỉ nhảy nếu đủ khoảng trống phía trên bậc");
    }

    /** Mob tự nổi ở nước và giữ chân khỏi dung nham, kể cả khi đích nằm bên kia. */
    private static void checkWaterAndLava(World world) {
        fill(world, 21, 25, 21, 25, 14, Block.STONE);
        fill(world, 21, 25, 21, 25, 15, Block.WATER);
        fill(world, 21, 25, 21, 25, 16, Block.WATER);
        Fixture swimmer = new Fixture(MobType.COW, 23.5f, 15.05f, 23.5f);
        for (int i = 0; i < 28; i++) {
            swimmer.update(world, 0.05f);
        }
        require(swimmer.y() > 16.3f && swimmer.y() < 17.7f,
                "Mob phải tự nổi lên gần mặt nước");
        swimmer.setCanFloat(false);
        for (int i = 0; i < 32; i++) {
            swimmer.update(world, 0.05f);
        }
        require(swimmer.y() < 15.5f, "AI của loài có thể tắt lực nổi mặc định");

        fill(world, 30, 37, 20, 27, 14, Block.STONE);
        fill(world, 33, 33, 20, 27, 15, Block.LAVA);
        Fixture walker = new Fixture(MobType.COW, 32.5f, 15f, 23.5f);
        walker.update(world, 0.05f);
        for (int i = 0; i < 32; i++) {
            walker.moveToward(world, 36.5f, 15f, 23.5f, 1f);
            walker.update(world, 0.05f);
        }
        require(walker.x() < 33f && walker.getFireTimer() == 0f,
                "Mob không được tự bước vào dung nham");
    }

    /** Đúng loài bốc cháy khi nắng, còn bóng râm, nước, mưa (ở Plains/Forest/Flower Forest) và đêm thì bảo vệ. */
    private static void checkSunlight(World world) {
        final int plainsX = 2000;
        fill(world, plainsX, plainsX + 7, 60, 60, 11, Block.STONE);
        world.setBlockInternal(plainsX + 2, 15, 60, Block.OAK_LEAVES.getId(), 0);
        world.setBlockInternal(plainsX + 4, 12, 60, Block.WATER.getId(), 0);
        Fixture sunny = new Fixture(MobType.ZOMBIE, plainsX + 0.5f, 12f, 60.5f);
        Fixture shaded = new Fixture(MobType.ZOMBIE, plainsX + 2.5f, 12f, 60.5f);
        Fixture wet = new Fixture(MobType.ZOMBIE, plainsX + 4.5f, 12f, 60.5f);
        Fixture nonBurning = new Fixture(MobType.HUSK, plainsX + 6.5f, 12f, 60.5f);
        sunny.update(world, 0.05f);
        shaded.update(world, 0.05f);
        wet.update(world, 0.05f);
        nonBurning.update(world, 0.05f);
        require(sunny.getFireTimer() > 1.9f && shaded.getFireTimer() == 0f && wet.getFireTimer() == 0f
                && nonBurning.getFireTimer() == 0f, "Cháy nắng phải đúng loại và xét bóng râm, nước");

        WeatherManager weather = new WeatherManager(72);
        weather.toggle();
        weather.update(5f);
        world.setWeather(weather);
        Fixture rain = new Fixture(MobType.ZOMBIE, plainsX + 0.5f, 12f, 60.5f);
        rain.update(world, 0.05f);
        require(rain.getFireTimer() == 0f, "Mưa tại cột Plains phải ngăn cháy nắng");

        fill(world, 1200, 1200, 60, 60, 11, Block.STONE);
        fill(world, 2800, 2800, 60, 60, 11, Block.STONE);
        Fixture forestRain = new Fixture(MobType.ZOMBIE, 1200.5f, 12f, 60.5f);
        Fixture flowerForestRain = new Fixture(MobType.ZOMBIE, 2800.5f, 12f, 60.5f);
        forestRain.update(world, 0.05f);
        flowerForestRain.update(world, 0.05f);
        require(forestRain.getFireTimer() == 0f && flowerForestRain.getFireTimer() == 0f,
                "Mưa ở Forest và Flower Forest cũng phải ngăn cháy nắng");

        fill(world, 3500, 3500, 60, 60, 11, Block.STONE);
        Fixture desert = new Fixture(MobType.ZOMBIE, 3500.5f, 12f, 60.5f);
        desert.update(world, 0.05f);
        require(world.getBiome(3500, 60) == BiomeType.DESERT && desert.getFireTimer() > 1.9f,
                "Mưa ở nơi khác không bảo vệ mob tại cột Desert");

        world.setWeather(null);
        world.worldTime().update(850f);
        Fixture night = new Fixture(MobType.ZOMBIE, plainsX + 0.5f, 12f, 60.5f);
        night.update(world, 0.05f);
        require(night.getFireTimer() == 0f, "Zombie không tự bắt lửa vào ban đêm");
    }

    /** Đặt một khu vực nhỏ trên cùng cao độ cho từng kịch bản vật lý. */
    private static void fill(World world, int minX, int maxX, int minZ, int maxZ, int y, Block block) {
        for (int x = minX; x <= maxX; x++) {
            for (int z = minZ; z <= maxZ; z++) {
                world.setBlockInternal(x, y, z, block.getId(), 0);
            }
        }
    }

    /** Báo rõ tính chất vi phạm nếu phép thử không đạt. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    /** Bỏ bộ goal ngẫu nhiên để đo trực tiếp vật lý chung của cùng kiểu mob. */
    private static final class Fixture extends MobEntity {
        /** Tạo mob theo kích thước thực trong danh mục. */
        private Fixture(MobType type, float x, float y, float z) {
            super(type, x, y, z);
        }

        /** Để nguyên các yêu cầu chuyển động mà phép thử đã gửi. */
        @Override
        protected void updateGoals(World world, float dt) {
        }
    }
}

package com.voxelgame.engine;

import com.voxelgame.world.entity.mob.MobCategory;
import com.voxelgame.world.entity.mob.MobSpawnTable;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.level.biome.BiomeType;
import com.voxelgame.world.level.biome.SnowSubZone;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

/** Kiểm tra xác suất sinh bầy và phân vùng tuyết từ dữ liệu voxel trên CPU. */
final class MobSpawnTableChecks {
    /** Lưu một dòng đặc tả độc lập với bảng đang kiểm tra. */
    private record Expected(MobType type, int weight, int min, int max) {
    }

    /** Chạy các kiểm tra xác suất và phân vùng tuyết trong bộ hồi quy chung. */
    static void run() {
        checkPlains();
        checkForestAndFlowerForest();
        checkDesert();
        checkSnowTables();
        checkSnowTerrain();
    }

    /** Đồng bằng dùng các bầy chăn thả ban ngày và danh mục quái mặc định. */
    private static void checkPlains() {
        checkTable(BiomeType.PLAINS, MobCategory.CREATURE, null,
                new Expected(MobType.SHEEP, 12, 4, 4), new Expected(MobType.PIG, 10, 4, 4),
                new Expected(MobType.CHICKEN, 10, 4, 4), new Expected(MobType.COW, 8, 4, 4),
                new Expected(MobType.HORSE, 5, 2, 6), new Expected(MobType.DONKEY, 1, 1, 3));
        checkTable(BiomeType.PLAINS, MobCategory.MONSTER, null,
                new Expected(MobType.SPIDER, 100, 4, 4), new Expected(MobType.SKELETON, 100, 4, 4),
                new Expected(MobType.CREEPER, 100, 4, 4), new Expected(MobType.ZOMBIE, 95, 4, 4),
                new Expected(MobType.ENDERMAN, 10, 1, 4), new Expected(MobType.ZOMBIE_VILLAGER, 5, 1, 1),
                new Expected(MobType.WITCH, 5, 1, 1));
    }

    /** Rừng sồi có thêm sói hoang; rừng hoa có thêm thỏ trắng thay cho ngựa và lừa. */
    private static void checkForestAndFlowerForest() {
        checkTable(BiomeType.FOREST, MobCategory.CREATURE, null,
                new Expected(MobType.SHEEP, 12, 4, 4), new Expected(MobType.PIG, 10, 4, 4),
                new Expected(MobType.CHICKEN, 10, 4, 4), new Expected(MobType.COW, 8, 4, 4),
                new Expected(MobType.WOLF, 5, 4, 4));
        checkTable(BiomeType.FLOWER_FOREST, MobCategory.CREATURE, null,
                new Expected(MobType.SHEEP, 12, 4, 4), new Expected(MobType.PIG, 10, 4, 4),
                new Expected(MobType.CHICKEN, 10, 4, 4), new Expected(MobType.COW, 8, 4, 4),
                new Expected(MobType.SNOW_RABBIT, 4, 2, 3));
        for (BiomeType forest : new BiomeType[]{BiomeType.FOREST, BiomeType.FLOWER_FOREST}) {
            checkTable(forest, MobCategory.MONSTER, null,
                    new Expected(MobType.SPIDER, 100, 4, 4), new Expected(MobType.SKELETON, 100, 4, 4),
                    new Expected(MobType.CREEPER, 100, 4, 4), new Expected(MobType.ZOMBIE, 95, 4, 4),
                    new Expected(MobType.ENDERMAN, 10, 1, 4), new Expected(MobType.ZOMBIE_VILLAGER, 5, 1, 1),
                    new Expected(MobType.WITCH, 5, 1, 1));
        }
    }

    /** Sa mạc chỉ sinh thỏ vàng (trọng số 4), với tổng trọng số quái bằng 415. */
    private static void checkDesert() {
        checkTable(BiomeType.DESERT, MobCategory.CREATURE, null,
                new Expected(MobType.RABBIT, 4, 2, 3));
        checkTable(BiomeType.DESERT, MobCategory.MONSTER, null,
                new Expected(MobType.SPIDER, 100, 4, 4), new Expected(MobType.CREEPER, 100, 4, 4),
                new Expected(MobType.HUSK, 80, 4, 4), new Expected(MobType.PARCHED, 50, 4, 4),
                new Expected(MobType.SKELETON, 50, 4, 4), new Expected(MobType.ZOMBIE, 19, 4, 4),
                new Expected(MobType.ENDERMAN, 10, 1, 4), new Expected(MobType.WITCH, 5, 1, 1),
                new Expected(MobType.ZOMBIE_VILLAGER, 1, 1, 1));
    }

    /** Ba phân vùng tuyết có ba nhóm thú (Grove có thỏ trọng số 4) và cùng một bảng quái. */
    private static void checkSnowTables() {
        checkTable(BiomeType.SNOWY_PLAINS, MobCategory.CREATURE, SnowSubZone.SNOWY_PLAINS_FLAT,
                new Expected(MobType.SNOW_RABBIT, 10, 2, 3), new Expected(MobType.POLAR_BEAR, 1, 1, 2));
        checkTable(BiomeType.SNOWY_PLAINS, MobCategory.CREATURE, SnowSubZone.SNOWY_GROVE,
                new Expected(MobType.WOLF, 8, 4, 4), new Expected(MobType.SNOW_FOX, 8, 2, 4),
                new Expected(MobType.SNOW_RABBIT, 4, 2, 3));
        checkTable(BiomeType.SNOWY_PLAINS, MobCategory.CREATURE, SnowSubZone.SNOWY_SLOPES_PEAKS,
                new Expected(MobType.GOAT, 5, 1, 3), new Expected(MobType.SNOW_RABBIT, 4, 2, 3));
        for (SnowSubZone zone : SnowSubZone.values()) {
            checkTable(BiomeType.SNOWY_PLAINS, MobCategory.MONSTER, zone,
                    new Expected(MobType.SPIDER, 100, 4, 4), new Expected(MobType.CREEPER, 100, 4, 4),
                    new Expected(MobType.ZOMBIE, 95, 4, 4), new Expected(MobType.STRAY, 80, 4, 4),
                    new Expected(MobType.SKELETON, 20, 4, 4), new Expected(MobType.ENDERMAN, 10, 1, 4),
                    new Expected(MobType.ZOMBIE_VILLAGER, 5, 1, 1), new Expected(MobType.WITCH, 5, 1, 1));
        }
    }

    /** Duyệt hết các giá trị xúc xắc để kiểm tra chính xác trọng số và cỡ bầy. */
    private static void checkTable(BiomeType biome, MobCategory category, SnowSubZone zone, Expected... expected) {
        MobSpawnTable table = MobSpawnTable.forBiome(biome, category, zone);
        int roll = 0;
        for (Expected row : expected) {
            for (int i = 0; i < row.weight(); i++) {
                MobSpawnTable.Entry actual = table.select(roll++);
                require(actual.type() == row.type() && actual.weight() == row.weight()
                                && actual.minPackSize() == row.min() && actual.maxPackSize() == row.max(),
                        "Sai dữ liệu sinh bầy của " + row.type() + " trong " + biome + " / " + category);
            }
        }
        require(roll == table.totalWeight(), "Tổng trọng số sai trong " + biome + " / " + category);
    }

    /** Kiểm tra nền bằng, ngưỡng cao, mặt dốc và khoảng cách thực tới vân sam. */
    private static void checkSnowTerrain() {
        World world = World.empty();
        try {
            world.setBlockInternal(100, 29, 100, Block.GRASS.getId(), 0);
            world.setBlockInternal(110, 30, 101, Block.SPRUCE_LEAVES.getId(), 0);
            require(SnowSubZone.classify(world, 100, 30, 100) == SnowSubZone.SNOWY_PLAINS_FLAT,
                    "Lá vân sam cách hơn mười block theo đường chéo phải nằm ngoài Grove");
            world.setBlockInternal(110, 30, 100, Block.SPRUCE_LOG.getId(), 0);
            require(SnowSubZone.classify(world, 100, 30, 100) == SnowSubZone.SNOWY_GROVE,
                    "Vân sam cách đúng mười block thuộc Grove");
            require(SnowSubZone.classify(world, 100, 29, 100) == SnowSubZone.SNOWY_PLAINS_FLAT,
                    "Độ cao dưới 30 thuộc đồng bằng tuyết");

            world.setBlockInternal(100, 61, 100, Block.GRASS.getId(), 0);
            world.setBlockInternal(100, 63, 100, Block.SPRUCE_LEAVES.getId(), 0);
            require(SnowSubZone.classify(world, 100, 62, 100) == SnowSubZone.SNOWY_SLOPES_PEAKS,
                    "Ngưỡng núi cao được ưu tiên dù có vân sam");

            world.setBlockInternal(150, 53, 150, Block.STONE.getId(), 0);
            world.setBlockInternal(151, 51, 150, Block.GRAVEL.getId(), 0);
            world.setBlockInternal(150, 56, 150, Block.SPRUCE_LEAVES.getId(), 0);
            require(SnowSubZone.classify(world, 150, 54, 150) == SnowSubZone.SNOWY_SLOPES_PEAKS,
                    "Nền đá dốc ở cao độ chân núi phải thuộc sườn tuyết");
        } finally {
            world.dispose();
        }
    }

    /** Nêu điều kiện sai để bộ hồi quy báo đúng khu vực cần sửa. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

package com.voxelgame.engine;

import com.voxelgame.client.render.Camera;
import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.mob.animal.PolarBear;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.monster.Stray;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.entity.projectile.ArrowEntity;
import com.voxelgame.world.entity.projectile.ArrowType;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.math.Vector3;

/** Kiểm tra hành vi của dê, gấu Bắc Cực và sói bằng nhịp mô phỏng CPU. */
final class NeutralSnowChecks {
    /** Mô phỏng theo bước cố định 20 Hz. */
    private static final float TICK = 0.05f;

    /** Chạy các tình huống chiến đấu và di chuyển riêng của ba loài. */
    static void run() {
        checkGoatFallAndRam();
        checkGoatJumpsGap();
        checkPolarBearProtectsCub();
        checkWolfDefendsPackAndHunts();
        checkWolfChangesEscapedPrey();
        checkWolfRetaliatesThroughCombat();
        checkWolfTiltAndShake();
    }

    /** Bố trí một hố trống rộng ba block và giữ dê trên mỏm đá khi nó chưa lấy đà. */
    private static void checkGoatJumpsGap() {
        World world = World.empty();
        try {
            for (int x = 9; x <= 20; x++) {
                if (x >= 12 && x <= 14) {
                    continue;
                }
                for (int z = 3; z <= 17; z++) {
                    // Bờ xuất phát hẹp theo cả hai trục để mọi đích nhảy đều ở phía bên kia hố.
                    if (x >= 15 || z >= 9 && z <= 11) {
                        world.setBlockInternal(x, 0, z, Block.STONE.getId(), 0);
                    }
                }
            }
            MobEntity goat = create(MobType.GOAT, 10.5f, 1f, 10.5f);
            float peak = goat.y();
            for (int tick = 0; tick < 3200; tick++) {
                if (goat.mobVisualState().pose() != MobVisualState.Pose.HOP && goat.isOnGround()) {
                    if (goat.x() >= 15f) {
                        break;
                    }
                    goat.setPosition(10.5f, 1f, 10.5f);
                }
                goat.update(world, TICK);
                peak = Math.max(peak, goat.y());
            }
            require(goat.x() >= 15f && goat.isOnGround() && peak > 3f && peak <= 11.01f,
                    "Dê phải bật cao và tiếp đất ở phía bên kia hố trong giới hạn 10 block");
        } finally {
            world.dispose();
        }
    }

    /** Dê trừ 10 block quãng rơi và cú húc định kỳ đánh trúng mục tiêu đứng yên. */
    private static void checkGoatFallAndRam() {
        World world = World.empty();
        try {
            floor(world);
            MobEntity goat = create(MobType.GOAT, 10.5f, 21f, 10.5f);
            for (int tick = 0; tick < 120 && !goat.isOnGround(); tick++) {
                goat.update(world, TICK);
            }
            require(goat.isOnGround() && Math.abs(goat.getHealth() - 3f) < 0.05f,
                    "Dê rơi từ 20 block phải chỉ mất 7 HP");

            goat = create(MobType.GOAT, 10.5f, 1f, 10.5f);
            Player player = new Player(14.5f, 1f, 10.5f);
            world.registerPlayer(player);
            for (int tick = 0; tick < 6320 && player.getHealth() == 20f; tick++) {
                if (goat.mobVisualState().pose() != MobVisualState.Pose.RAM && goat.isOnGround()) {
                    goat.setPosition(10.5f, 1f, 10.5f);
                }
                goat.update(world, TICK);
            }
            player.attachControls(new Camera());
            player.update(world, TICK);
            require(Math.abs(player.getHealth() - 18f) < 0.001f && player.getPosition().x > 15f,
                    "Cú húc định kỳ phải gây 2 HP và đẩy mạnh người chơi khỏi dê");
        } finally {
            world.dispose();
        }
    }

    /** Gấu trưởng thành cảnh báo khi gấu con bị tiếp cận và gọi cả nhóm khi bị đánh. */
    private static void checkPolarBearProtectsCub() {
        World world = World.empty();
        try {
            floor(world);
            Player player = new Player(15.5f, 1f, 10.5f);
            world.registerPlayer(player);
            MobEntity bear = create(MobType.POLAR_BEAR, 10.5f, 1f, 10.5f);
            PolarBear cub = new PolarBear(13.5f, 1f, 10.5f, true);
            world.addLivingEntity(cub);
            require(cub.isBaby() && Math.abs(cub.getHeight() - 0.7f) < 0.001f,
                    "Gấu con phải có thân cao 0,7 block");
            bear.update(world, TICK);
            require(bear.target() == player && bear.mobVisualState().pose() == MobVisualState.Pose.REAR,
                    "Gấu phải đứng dựng lên khi người chơi áp sát gấu con");
            MobEntity ally = create(MobType.POLAR_BEAR, 19.5f, 1f, 10.5f);
            world.addLivingEntity(bear);
            world.addLivingEntity(ally);
            bear.damage(world, 1f, DamageSource.MELEE, player, 0f, 0f);
            require(ally.target() == player && cub.target() == null,
                    "Gấu trưởng thành trả đũa theo nhóm còn gấu con bỏ chạy");
        } finally {
            world.dispose();
        }
    }

    /** Sói săn cung thủ ngoài tự nhiên và đổi mắt đỏ cùng đồng loại khi bị người chơi đánh. */
    private static void checkWolfDefendsPackAndHunts() {
        World world = World.empty();
        try {
            floor(world);
            Player player = new Player(10.5f, 1f, 16.5f);
            world.registerPlayer(player);
            MobEntity wolf = create(MobType.WOLF, 10.5f, 1f, 10.5f);
            MobEntity ally = create(MobType.WOLF, 26.5f, 1f, 10.5f);
            MobEntity outsider = create(MobType.WOLF, 27f, 1f, 10.5f);
            MobEntity stray = create(MobType.STRAY, 11.5f, 1f, 10.5f);
            world.addLivingEntity(wolf);
            world.addLivingEntity(ally);
            world.addLivingEntity(outsider);
            world.addLivingEntity(stray);
            wolf.update(world, TICK);
            require(wolf.target() == stray && stray.getHealth() == stray.getMaxHealth() - 4f,
                    "Sói phải chủ động đánh Stray gây 4 HP");
            wolf.damage(world, 1f, DamageSource.MELEE, player, 0f, 0f);
            require(ally.target() == player && outsider.target() == null && wolf.target() == player
                            && wolf.mobVisualState().appearance() == MobAppearance.WOLF_SNOWY_ANGRY
                            && ally.mobVisualState().appearance() == MobAppearance.WOLF_SNOWY_ANGRY,
                    "Chỉ các con sói trong 16 block phải cùng đổi mắt đỏ và tấn công người chơi");
        } finally {
            world.dispose();
        }
    }

    /** Sói chuyển sang mồi khác khi con mồi cũ thoát tầm và vẫn giữ cơn giận với người chơi. */
    private static void checkWolfChangesEscapedPrey() {
        World world = World.empty();
        try {
            floor(world);
            MobEntity wolf = create(MobType.WOLF, 8.5f, 1f, 10.5f);
            MobEntity rabbit = create(MobType.SNOW_RABBIT, 11.5f, 1f, 10.5f);
            MobEntity skeleton = create(MobType.SKELETON, 11.5f, 1f, 12.5f);
            world.addEntity(wolf);
            world.addEntity(rabbit);
            wolf.update(world, TICK);
            require(wolf.target() == rabbit, "Sói phải nhận con thỏ gần làm mồi đầu tiên");
            rabbit.setPosition(36.5f, 1f, 10.5f);
            world.addEntity(skeleton);
            for (int tick = 0; tick < 20; tick++) {
                wolf.update(world, TICK);
            }
            require(wolf.target() == skeleton,
                    "Sói phải chuyển sang con mồi gần khi mục tiêu cũ thoát khỏi tầm đuổi");
            Player player = new Player(80.5f, 1f, 10.5f);
            wolf.damage(world, 1f, DamageSource.MELEE, player, 0f, 0f);
            for (int tick = 0; tick < 20; tick++) {
                wolf.update(world, TICK);
            }
            require(wolf.target() != player, "Sói phải bỏ mục tiêu người chơi đã chạy quá xa");
        } finally {
            world.dispose();
        }
    }

    /** Mũi tên giữ tác nhân và cả đàn có thể đuổi, cắn người chơi đã đánh sói. */
    private static void checkWolfRetaliatesThroughCombat() {
        World world = World.empty();
        try {
            floor(world);
            Player player = new Player(7.5f, 1f, 10.5f);
            world.registerPlayer(player);
            MobEntity wolf = create(MobType.WOLF, 9.5f, 1f, 10.5f);
            MobEntity ally = create(MobType.WOLF, 11.5f, 1f, 10.5f);
            world.addLivingEntity(wolf);
            world.addLivingEntity(ally);
            player.attack(world, wolf, Vector3.X);
            require(wolf.lastAttacker() == player && wolf.target() == player && ally.target() == player,
                    "Đòn tay không phải kích động cả đàn");
            wolf.setPosition(9.5f, 1f, 10.5f);
            for (int tick = 0; tick < 24; tick++) {
                wolf.update(world, TICK);
            }
            require(player.getHealth() < player.getMaxHealth(), "Sói phải đuổi và cắn người chơi");
            wolf.setPosition(9.5f, 1f, 10.5f);
            ArrowEntity arrow = new ArrowEntity(player, 8.5f, 1.5f, 10.5f,
                    24f, 0f, 0f, ArrowType.NORMAL, 1f);
            float beforeArrow = wolf.getHealth();
            arrow.update(world, TICK);
            require(wolf.getHealth() < beforeArrow && wolf.lastAttacker() == player && wolf.angerTimer() >= 20f && wolf.angerTimer() < 40f,
                    "Tên của người chơi phải làm mới thời gian giận");
        } finally {
            world.dispose();
        }
    }

    /** Sói bình thản nghiêng đầu nhìn người gần đó và lắc mình sau khi lên bờ. */
    private static void checkWolfTiltAndShake() {
        World world = World.empty();
        try {
            floor(world);
            Player player = new Player(14.5f, 1f, 10.5f);
            world.registerPlayer(player);
            MobEntity wolf = create(MobType.WOLF, 10.5f, 1f, 10.5f);
            wolf.update(world, TICK);
            require(wolf.mobVisualState().pose() == MobVisualState.Pose.TILT_HEAD,
                    "Sói bình thản phải nghiêng đầu khi người chơi ở gần");
            world.setBlockInternal(10, 1, 10, Block.WATER.getId(), 0);
            wolf.update(world, TICK);
            wolf.setPosition(12.5f, 1f, 10.5f);
            for (int tick = 0; tick < 20 && wolf.mobVisualState().pose() != MobVisualState.Pose.SHAKE; tick++) {
                wolf.update(world, TICK);
            }
            require(wolf.mobVisualState().pose() == MobVisualState.Pose.SHAKE,
                    "Sói lên bờ phải lắc người để rũ nước");
        } finally {
            world.dispose();
        }
    }

    /** Tạo qua danh mục để đồng thời kiểm tra các hàm tạo đã được nối. */
    private static MobEntity create(MobType type, float x, float y, float z) {
        MobEntity mob = type.create(x, y, z);
        require(mob != null, "Chưa đăng ký hàm tạo cho " + type);
        return mob;
    }

    /** Dựng mặt đứng phẳng và kín trong khu vực thử nghiệm. */
    private static void floor(World world) {
        for (int x = 2; x < 38; x++) {
            for (int z = 2; z < 24; z++) {
                world.setBlockInternal(x, 0, z, Block.STONE.getId(), 0);
            }
        }
    }

    /** Báo chính xác hành vi sai khi kiểm tra thất bại. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

