/**
 * Bộ kiểm thử CPU xác nhận kiến trúc Hướng đối tượng (OOP) chuẩn Minecraft:
 * kiểm tra cây kế thừa, tính trừu tượng, giao diện hợp đồng và hành vi đa hình.
 */
public final class OopArchitectureChecks {

    private OopArchitectureChecks() {
    }

    /** Chạy toàn bộ các kiểm tra kiến trúc OOP hiện hành. */
    public static void run() {
        checkBlockHierarchy();
        checkBiomeAndWeatherHierarchy();
        checkEntityAndMobHierarchy();
        checkItemHierarchyAndDispatch();
        checkGameModeHierarchy();
        checkClientScreenHierarchy();
    }

    /** Xác nhận hệ phân cấp OOP của GameMode (Trừu tượng, Kế thừa, Đóng gói và Đa hình). */
    private static void checkGameModeHierarchy() {
        requireAbstract(GameMode.class);
        requireSubclass(GameMode.class, CreativeGameMode.class, SurvivalGameMode.class);
        GameMode creative = CreativeGameMode.INSTANCE;
        GameMode survival = SurvivalGameMode.INSTANCE;
        require(creative.toggle() == survival && survival.toggle() == creative,
                "GameMode.toggle() phải điều phối đa hình giữa Creative và Survival");
    }

    /** Xác nhận Block đã tách khỏi Entity, đủ lớp trừu tượng trung gian và bảo toàn 33 ID 0..32. */
    private static void checkBlockHierarchy() {
        require(!Entity.class.isAssignableFrom(Block.class),
                "Block không được kế thừa Entity (sửa vi phạm LSP)");
        require(Tickable.class.isAssignableFrom(Entity.class),
                "Entity phải triển khai Tickable");
        require(Renderable.class.isAssignableFrom(Entity.class),
                "Entity phải triển khai Renderable");
        require(Tickable.class.isAssignableFrom(LeafDecaySystem.class),
                "LeafDecaySystem phải triển khai Tickable");
        require(Tickable.class.isAssignableFrom(LiquidFlowSimulator.class),
                "LiquidFlowSimulator phải triển khai Tickable");

        requireAbstract(Block.class);
        requireAbstract(SolidBlock.class);
        requireAbstract(GravityBlock.class);
        requireAbstract(LiquidBlock.class);
        requireAbstract(LogBlock.class);
        requireAbstract(LeavesBlock.class);
        requireAbstract(PlantBlock.class);

        require(Block.SAND instanceof GravityBlock && Block.GRAVEL instanceof GravityBlock,
                "Sand và Gravel phải kế thừa GravityBlock");
        require(Block.WATER instanceof LiquidBlock && Block.LAVA instanceof LiquidBlock,
                "Water và Lava phải kế thừa LiquidBlock");
        require(Block.OAK_LOG instanceof LogBlock && Block.SPRUCE_LOG instanceof LogBlock,
                "OakLog và SpruceLog phải kế thừa LogBlock");
        require(Block.OAK_LEAVES instanceof LeavesBlock && Block.SPRUCE_LEAVES instanceof LeavesBlock,
                "OakLeaves và SpruceLeaves phải kế thừa LeavesBlock");
        require(Block.DIRT instanceof SolidBlock
                        && Block.STONE instanceof SolidBlock
                        && Block.BEDROCK instanceof SolidBlock
                        && Block.SANDSTONE instanceof SolidBlock
                        && Block.SNOW_BLOCK instanceof SolidBlock
                        && Block.WHITE_WOOL instanceof SolidBlock
                        && Block.GRASS instanceof SolidBlock
                        && Block.CHEST instanceof SolidBlock,
                "Các khối rắn đục phải kế thừa SolidBlock");

        for (int id = 0; id <= 32; id++) {
            Block block = Block.fromId((byte) id);
            require(block != null && block.getId() == (byte) id,
                    "ID block " + id + " phải giữ nguyên ánh xạ trong Block.fromId");
        }
    }

    /** Xác nhận hệ phân cấp đa hình Biome (5 lớp con) và Weather (3 lớp con, State/Strategy). */
    private static void checkBiomeAndWeatherHierarchy() {
        requireAbstract(Biome.class);
        requireAbstract(Weather.class);

        for (BiomeType type : BiomeType.values()) {
            Biome b1 = Biome.of(type);
            Biome b2 = type.toBiome();
            require(b1 != null && b1 == b2,
                    "Biome.of và BiomeType.toBiome phải trả về cùng singleton Flyweight cho " + type);
            require(b1.getType() == type, "Biome.getType() phải khớp " + type);
        }

        require(Biome.of(BiomeType.PLAINS) instanceof PlainsBiome, "PLAINS phải là PlainsBiome");
        require(Biome.of(BiomeType.FOREST) instanceof ForestBiome, "FOREST phải là ForestBiome");
        require(Biome.of(BiomeType.FLOWER_FOREST) instanceof FlowerForestBiome, "FLOWER_FOREST phải là FlowerForestBiome");
        require(Biome.of(BiomeType.DESERT) instanceof DesertBiome, "DESERT phải là DesertBiome");
        require(Biome.of(BiomeType.SNOWY_PLAINS) instanceof SnowyPlainsBiome, "SNOWY_PLAINS phải là SnowyPlainsBiome");

        checkBiomeColors(BiomeType.PLAINS, 0x91BD59, 0x77AB2F);
        checkBiomeColors(BiomeType.FOREST, 0x79C05A, 0x59AE30);
        checkBiomeColors(BiomeType.FLOWER_FOREST, 0x88BB67, 0x6BA941);
        checkBiomeColors(BiomeType.DESERT, 0xBFB755, 0xAEA42A);
        checkBiomeColors(BiomeType.SNOWY_PLAINS, 0x80B497, 0x60A17B);

        require(Biome.of(BiomeType.PLAINS).resolvePrecipitationWeather() == RainWeather.INSTANCE,
                "PLAINS phải chuyển sang RainWeather khi có giáng thủy");
        require(Biome.of(BiomeType.FOREST).resolvePrecipitationWeather() == RainWeather.INSTANCE,
                "FOREST phải chuyển sang RainWeather khi có giáng thủy");
        require(Biome.of(BiomeType.FLOWER_FOREST).resolvePrecipitationWeather() == RainWeather.INSTANCE,
                "FLOWER_FOREST phải chuyển sang RainWeather khi có giáng thủy");
        require(Biome.of(BiomeType.SNOWY_PLAINS).resolvePrecipitationWeather() == SnowWeather.INSTANCE,
                "SNOWY_PLAINS phải chuyển sang SnowWeather khi có giáng thủy");
        require(Biome.of(BiomeType.DESERT).resolvePrecipitationWeather() == ClearWeather.INSTANCE,
                "DESERT phải giữ ClearWeather ngay cả khi có giáng thủy toàn cục");

        require(Biome.of(BiomeType.PLAINS).getSpawnTable(MobCategory.CREATURE, SnowSubZone.SNOWY_PLAINS_FLAT)
                == MobSpawnTable.forBiome(BiomeType.PLAINS, MobCategory.CREATURE, SnowSubZone.SNOWY_PLAINS_FLAT),
                "Biome.getSpawnTable phải đồng bộ với MobSpawnTable.forBiome");

        require("CLEAR".equals(ClearWeather.INSTANCE.getLabel())
                && !ClearWeather.INSTANCE.extinguishesFire()
                && !ClearWeather.INSTANCE.accumulatesSnow(),
                "ClearWeather phải có thuộc tính trời quang");
        require("RAIN".equals(RainWeather.INSTANCE.getLabel())
                && RainWeather.INSTANCE.extinguishesFire()
                && !RainWeather.INSTANCE.accumulatesSnow(),
                "RainWeather phải dập lửa và không tích tuyết");
        require("SNOW".equals(SnowWeather.INSTANCE.getLabel())
                && !SnowWeather.INSTANCE.extinguishesFire()
                && SnowWeather.INSTANCE.accumulatesSnow(),
                "SnowWeather phải tích tuyết và không dập lửa");

        World world = World.empty();
        try {
            WeatherManager weather = new WeatherManager(World.WORLD_SEED);
            Vector3 eye = new Vector3();
            require(weather.currentWeather() == ClearWeather.INSTANCE,
                    "Trạng thái thời tiết ban đầu phải là ClearWeather");

            weather.toggle();
            weather.update(5f, world, eye.set(2000.5f, 35f, 1024.5f), null);
            require(weather.currentWeather() == RainWeather.INSTANCE,
                    "Khi bật giáng thủy ở Plains phải là RainWeather");

            weather.update(1f, world, eye.set(200.5f, 35f, 1024.5f), null);
            require(weather.currentWeather() == SnowWeather.INSTANCE,
                    "Khi di chuyển sang Snowy Plains trong lúc giáng thủy phải là SnowWeather");

            weather.update(1f, world, eye.set(3700.5f, 35f, 1024.5f), null);
            require(weather.currentWeather() == ClearWeather.INSTANCE,
                    "Khi di chuyển sang Desert phải là ClearWeather");
        } finally {
            world.dispose();
        }
    }

    /** Xác nhận hệ phân cấp Entity/Mob (abstract, LSP Horse/Donkey) và điều phối Interactable 2 lượt. */
    private static void checkEntityAndMobHierarchy() {
        requireAbstract(Entity.class);
        requireAbstract(LivingEntity.class);
        requireAbstract(MobEntity.class);
        requireAbstract(HostileMob.class);
        requireAbstract(PassiveMob.class);
        requireAbstract(NeutralMob.class);
        requireAbstract(MountableMob.class);
        requireAbstract(EquineMob.class);
        requireAbstract(RangedMob.class);
        requireAbstract(ProjectileEntity.class);

        requireSubclass(HostileMob.class, Zombie.class, ZombieVillager.class, Husk.class, Creeper.class,
                RangedMob.class, Skeleton.class, Stray.class, Parched.class, Witch.class);
        requireSubclass(PassiveMob.class, Cow.class, Sheep.class, Pig.class, Chicken.class, Rabbit.class);
        requireSubclass(NeutralMob.class, Spider.class, Enderman.class, Goat.class, PolarBear.class,
                Wolf.class, SnowFox.class);
        requireSubclass(EquineMob.class, Horse.class, Donkey.class);
        require(!Horse.class.isAssignableFrom(Donkey.class),
                "Donkey không được kế thừa Horse (giữ nguyên lý thay thế Liskov qua EquineMob)");
        requireSubclass(MountableMob.class, EquineMob.class, Horse.class, Donkey.class, Camel.class, CamelHusk.class);

        requireSubclass(Interactable.class, Sheep.class, Cow.class, Goat.class, Wolf.class, MountableMob.class);
        require(!Interactable.class.isAssignableFrom(Zombie.class)
                && !Interactable.class.isAssignableFrom(Creeper.class),
                "Zombie và Creeper không được triển khai Interactable");

        // Kiểm tra điều phối 2 lượt: Flint and Steel ưu tiên đốt mọi mob (kể cả mob không phải Interactable và Sheep)
        World world = World.empty();
        try {
            Player player = new Player(10.5f, 10f, 10.5f);
            player.getHotbar().setSlot(0, Item.FLINT_AND_STEEL, 1);
            player.getHotbar().selectSlot(0);

            Zombie zombie = new Zombie(11.5f, 10f, 10.5f);
            require(zombie.onPlayerInteract(world, player) && zombie.getFireTimer() > 0f,
                    "Flint and Steel phải đốt được Zombie dù Zombie không triển khai Interactable");

            Sheep sheep = new Sheep(12.5f, 10f, 10.5f);
            require(sheep.onPlayerInteract(world, player) && sheep.getFireTimer() > 0f && !sheep.isSheared(),
                    "Flint and Steel phải ưu tiên đốt Sheep trước tương tác cắt len");

            player.getHotbar().setSlot(0, Item.SHEARS, 1);
            require(sheep.onPlayerInteract(world, player) && sheep.isSheared(),
                    "Shears phải kích hoạt Interactable.onInteract cắt len Sheep");
        } finally {
            world.dispose();
        }
    }

    /** Xác nhận hệ phân cấp Item đa hình (13 lớp con), 56 standalone items và 19 FoodItem khớp FoodRegistry. */
    private static void checkItemHierarchyAndDispatch() {
        requireAbstract(Item.class);
        requireAbstract(ConsumableItem.class);
        requireAbstract(ToolItem.class);

        require(Item.allStandaloneItems().size() == 56,
                "Phải bảo toàn đúng 56 vật phẩm độc lập trong Item.allStandaloneItems()");
        require(FoodRegistry.count() == 19,
                "FoodRegistry phải giữ đúng 19 món ăn chuẩn Minecraft");

        require(Item.BOW instanceof BowItem, "Item.BOW phải là BowItem");
        require(Item.IRON_SPEAR instanceof SpearItem, "Item.IRON_SPEAR phải là SpearItem");
        require(Item.ENDER_PEARL instanceof ThrowableItem && Item.EGG instanceof ThrowableItem,
                "ENDER_PEARL và EGG phải là ThrowableItem");
        require(Item.SHEARS instanceof ShearsItem, "Item.SHEARS phải là ShearsItem");
        require(Item.FLINT_AND_STEEL instanceof FlintAndSteelItem, "Item.FLINT_AND_STEEL phải là FlintAndSteelItem");
        require(Item.BUCKET instanceof BucketItem, "Item.BUCKET phải là BucketItem");
        require(Item.GOAT_HORN instanceof GoatHornItem, "Item.GOAT_HORN phải là GoatHornItem");
        require(Item.LEATHER instanceof SimpleItem && Item.ARROW instanceof SimpleItem,
                "Vật phẩm nguyên liệu/mũi tên phải là SimpleItem");

        Item[] allFoods = {
                Item.BEEF, Item.COOKED_BEEF, Item.PORKCHOP, Item.COOKED_PORKCHOP,
                Item.MUTTON, Item.COOKED_MUTTON, Item.CHICKEN, Item.COOKED_CHICKEN,
                Item.RABBIT, Item.COOKED_RABBIT, Item.COD, Item.COOKED_COD,
                Item.SALMON, Item.COOKED_SALMON, Item.CARROT, Item.POTATO,
                Item.BAKED_POTATO, Item.ROTTEN_FLESH, Item.SPIDER_EYE
        };
        require(allFoods.length == 19, "Danh sách kiểm tra thức ăn phải đủ 19 món");
        for (Item item : allFoods) {
            require(item instanceof FoodItem food && food.getFoodSpec().equals(FoodRegistry.of(item)),
                    item.getDisplayName() + " phải là FoodItem khớp hoàn toàn với FoodRegistry");
        }

        require(Item.POTION_HEALING instanceof PotionItem
                        && Item.POTION_FIRE_RESISTANCE instanceof PotionItem
                        && Item.POTION_WATER_BREATHING instanceof PotionItem
                        && Item.POTION_SWIFTNESS instanceof PotionItem
                        && Item.MILK_BUCKET instanceof PotionItem,
                "4 thuốc Witch và MILK_BUCKET phải là PotionItem");

        require(Item.WHITE_WOOL instanceof BlockItem
                        && Item.LIGHT_GRAY_WOOL instanceof BlockItem
                        && Item.GRAY_WOOL instanceof BlockItem
                        && Item.BLACK_WOOL instanceof BlockItem
                        && Item.BROWN_WOOL instanceof BlockItem
                        && Item.PINK_WOOL instanceof BlockItem,
                "6 vật phẩm len phải là BlockItem");
        require(Item.of(Block.WHITE_WOOL) == Item.WHITE_WOOL,
                "Liên kết 2 chiều Block.WHITE_WOOL -> Item.WHITE_WOOL phải nguyên vẹn");
        require(Item.of(Block.STONE) instanceof BlockItem,
                "Item.of(Block.STONE) phải là BlockItem");

        require(Item.SHEARS.getMiningSpeedMultiplier(Block.WHITE_WOOL) == 5.0f
                        && Item.SHEARS.getMiningSpeedMultiplier(Block.OAK_LEAVES) == 5.0f
                        && Item.SHEARS.getMiningSpeedMultiplier(Block.STONE) == 1.0f
                        && Item.of(Block.STONE).getMiningSpeedMultiplier(Block.WHITE_WOOL) == 1.0f,
                "ShearsItem.getMiningSpeedMultiplier phải trả 5.0f cho len/lá và 1.0f cho khối khác");

        require(Item.IRON_SPEAR.getMeleeReach() == ItemUseHandler.SPEAR_JAB_REACH
                        && Item.IRON_SPEAR.getMeleeDamage() == ItemUseHandler.SPEAR_JAB_DAMAGE,
                "SpearItem phải cung cấp đúng thông số Jab đa hình");
    }

    /** Xác nhận hệ phân cấp màn hình Client/GUI (Screen, PauseScreen, InventoryScreen, BitmapFont, HudRenderer). */
    private static void checkClientScreenHierarchy() {
        requireAbstract(Screen.class);
        requireSubclass(Screen.class, PauseScreen.class, InventoryScreen.class, CreativeInventoryScreen.class);

        PauseScreen pauseScreen = new PauseScreen();
        InventoryScreen inventoryScreen = new InventoryScreen();
        CreativeInventoryScreen creativeScreen = new CreativeInventoryScreen();
        try {
            require(pauseScreen.pausesWorld(), "PauseScreen phải tạm dừng vòng cập nhật thế giới");
            require(!inventoryScreen.pausesWorld(), "InventoryScreen không được tạm dừng thế giới");
            require(!creativeScreen.pausesWorld(), "CreativeInventoryScreen không được tạm dừng thế giới");
            require(!pauseScreen.isOpen() && !inventoryScreen.isOpen() && !creativeScreen.isOpen(),
                    "Màn hình Screen mặc định phải ở trạng thái đóng");
            pauseScreen.open();
            require(pauseScreen.isOpen(), "open() phải mở PauseScreen");
            pauseScreen.close();
            require(!pauseScreen.isOpen(), "close() phải đóng PauseScreen");
        } finally {
            pauseScreen.dispose();
            inventoryScreen.dispose();
            creativeScreen.dispose();
        }

        require(com.badlogic.gdx.utils.Disposable.class.isAssignableFrom(Screen.class)
                        && com.badlogic.gdx.utils.Disposable.class.isAssignableFrom(HudRenderer.class),
                "Screen và HudRenderer phải triển khai Disposable");

        char[] requiredChars = {'A', 'Z', 'a', 'z', '0', '9', ':', '%', '-', '+', '.', '/', ',', '(', ')', '='};
        for (char c : requiredChars) {
            require(BitmapFont.hasGlyph(c), "BitmapFont phải cung cấp glyph 5x7 cho ký tự '" + c + "'");
        }
        require(BitmapFont.measureWidth("HELLO", 2.0f) == 5 * 6.0f * 2.0f,
                "BitmapFont.measureWidth phải tính đúng bề rộng chuỗi 5x7");
    }

    /** Xác nhận mọi lớp con đều kế thừa hoặc triển khai từ lớp/giao diện cha. */
    private static void requireSubclass(Class<?> parent, Class<?>... children) {
        for (Class<?> child : children) {
            require(parent.isAssignableFrom(child),
                    child.getSimpleName() + " phải kế thừa/triển khai " + parent.getSimpleName());
        }
    }

    /** Xác nhận màu cỏ và màu lá của từng lớp con Biome khớp bảng chuẩn. */
    private static void checkBiomeColors(BiomeType type, int expectedGrass, int expectedFoliage) {
        Biome biome = Biome.of(type);
        require(biome.getGrassColorRgb() == expectedGrass && biome.getFoliageColorRgb() == expectedFoliage,
                "Màu cỏ/lá của " + type + " không khớp đặc tả");
    }

    /** Xác nhận lớp mục tiêu có khai báo abstract. */
    private static void requireAbstract(Class<?> type) {
        require(Modifier.isAbstract(type.getModifiers()),
                type.getSimpleName() + " phải là lớp abstract");
    }

    /** Ném lỗi ngay khi điều kiện kiến trúc không đạt. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError("OopArchitectureChecks thất bại: " + message);
        }
    }
}

package com.voxelgame.engine;

import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.mob.animal.Chicken;
import com.voxelgame.world.entity.mob.animal.Cow;
import com.voxelgame.world.entity.mob.animal.Pig;
import com.voxelgame.world.entity.mob.animal.Sheep;
import com.voxelgame.world.entity.mob.MobAttitude;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

/** Kiểm tra chỉ số và hành vi của bốn loài hiền lành ở Plains trên CPU. */
final class PlainsAnimalChecks {
    /** Chạy các ca theo đàn, ăn cỏ, màu lông, hoảng loạn và hạ cánh. */
    static void run() {
        World world = World.empty();
        try {
            checkStatsAndPanic(world);
            checkHerd(world);
            checkWoolColors();
            checkGrazing(world);
            checkChickenFall(world);
        } finally {
            world.dispose();
        }
    }

    /** Đọc cấu hình của cá thể thực và xác nhận phản ứng bị đánh của từng loài. */
    private static void checkStatsAndPanic(World world) {
        MobEntity[] animals = {
                new Cow(5.5f, 11f, 5.5f), new Sheep(6.5f, 11f, 5.5f),
                new Pig(7.5f, 11f, 5.5f), new Chicken(8.5f, 11f, 5.5f)
        };
        float[] hp = {10f, 8f, 10f, 4f};
        float[] width = {0.9f, 0.9f, 0.9f, 0.4f};
        float[] height = {1.4f, 1.3f, 0.9f, 0.7f};
        float[] speed = {2f, 2.3f, 2.5f, 2.5f};
        Player source = new Player(4.5f, 11f, 5.5f);
        for (int i = 0; i < animals.length; i++) {
            MobEntity animal = animals[i];
            near(animal.getMaxHealth(), hp[i], "HP của thú Plains");
            near(animal.getHalfWidth() * 2f, width[i], "Chiều rộng hộp của thú Plains");
            near(animal.getHeight(), height[i], "Chiều cao hộp của thú Plains");
            near(animal.moveSpeed(), speed[i], "Tốc độ của thú Plains");
            require(animal.attitude() == MobAttitude.PASSIVE && animal.isPersistent(), "Thú Plains hiền và được giữ lại");
            require(animal.damage(world, 1f, DamageSource.MELEE, source, 0f, 0f)
                            && animal.panicTime() >= 3f && animal.panicTime() < 5f && animal.target() == null,
                    "Thú Plains hoảng khi bị đánh và không trả đòn");
        }
    }

    /** Bò đi gần lại đồng loại khi bị tách đàn trên nền an toàn. */
    private static void checkHerd(World world) {
        for (int x = 15; x <= 36; x++) {
            for (int z = 14; z <= 24; z++) {
                world.setBlockInternal(x, 15, z, Block.STONE.getId(), 0);
            }
        }
        Cow leader = new Cow(29.5f, 16f, 19.5f);
        Cow follower = new Cow(22.5f, 16f, 19.5f);
        world.addLivingEntity(leader);
        leader.update(world, 0.05f);
        follower.update(world, 0.05f);
        for (int i = 0; i < 64; i++) {
            follower.update(world, 0.05f);
        }
        require(follower.x() > 25.5f, "Bò phải tiến về đàn khi đứng cách đồng loại bảy block");
    }

    /** Quét hết bộ chọn rời rạc, tránh phép đo xác suất có thể dao động giữa các lần chạy. */
    private static void checkWoolColors() {
        Sheep.WoolColor[] colors = Sheep.WoolColor.values();
        int[] exact = {81_836, 5_000, 5_000, 5_000, 3_000, 164};
        int[] totals = new int[colors.length];
        require(colors.length == exact.length, "Bảng màu cừu có đúng sáu biến thể tự nhiên");
        for (int roll = 0; roll < 100_000; roll++) {
            totals[Sheep.WoolColor.fromRoll(roll).ordinal()]++;
        }
        for (int i = 0; i < colors.length; i++) {
            require(totals[i] == exact[i], "Tỷ lệ màu len sai ở " + colors[i]);
        }
        Sheep pink = new Sheep(0f, 0f, 0f, Sheep.WoolColor.PINK);
        require(pink.woolColor() == Sheep.WoolColor.PINK && pink.mobVisualState().sheepWoolColor() == pink.woolColor().rgb(),
                "Màu len được chuyển vào lớp hiển thị của cá thể");
    }

    /** Ăn bụi cỏ trước, gặm nền cỏ bằng đường cập nhật gameplay của World (1/1000 trưởng thành, 1/50 con non). */
    private static void checkGrazing(World world) {
        require(Sheep.ADULT_GRAZE_CHANCE_DIVISOR == 1000 && Sheep.BABY_GRAZE_CHANCE_DIVISOR == 50,
                "Xác suất ăn cỏ của cừu phải đúng 1/1000 (trưởng thành) và 1/50 (con non)");
        pen(world, 43, 30, Block.SHORT_GRASS);
        // Cỏ cao thiếu nửa trên sẽ bị dọn khi đường ghi gameplay thông báo cho ô phía trên nền.
        pen(world, 49, 30, Block.TALL_GRASS);
        Sheep eater = new Sheep(43.5f, 16f, 30.5f, Sheep.WoolColor.WHITE);
        Sheep grazer = new Sheep(49.5f, 16f, 30.5f, Sheep.WoolColor.BROWN);
        require(waitForGrass(world, eater, 43, 16, 30, Block.SHORT_GRASS, 20_000),
                "Cừu phải cúi đầu trước khi ăn bụi cỏ");
        require(world.getBlock(43, 16, 30) == Block.AIR.getId() && world.getBlock(43, 15, 30) == Block.GRASS.getId(),
                "Ăn Short Grass giữ nguyên nền cỏ");
        require(waitForGrass(world, grazer, 49, 15, 30, Block.GRASS, 20_000),
                "Cừu phải cúi đầu trước khi gặm Grass Block");
        require(world.getBlock(49, 15, 30) == Block.DIRT.getId() && world.getBlock(49, 16, 30) == Block.AIR.getId(),
                "Gặm nền cỏ đổi thành Dirt và chạy cập nhật lân cận");

        // Cừu con có hitbox 0,5× và tần suất ăn cỏ 1/50 mỗi tick (nhanh hơn rõ rệt so với cừu lớn).
        pen(world, 55, 30, Block.SHORT_GRASS);
        Sheep lamb = new Sheep(55.5f, 16f, 30.5f, Sheep.WoolColor.WHITE);
        lamb.setBaby(true);
        near(lamb.getHalfWidth() * 2f, 0.45f, "Chiều rộng hitbox cừu con");
        near(lamb.getHeight(), 0.65f, "Chiều cao hitbox cừu con");
        require(waitForGrass(world, lamb, 55, 16, 30, Block.SHORT_GRASS, 1_500),
                "Cừu con với xác suất 1/50 mỗi tick phải ăn được cỏ nhanh hơn cừu lớn");

        pen(world, 43, 38, Block.SHORT_GRASS);
        Sheep interrupted = new Sheep(43.5f, 16f, 38.5f, Sheep.WoolColor.LIGHT_GRAY);
        for (int i = 0; i < 20_000 && interrupted.mobVisualState().pose() != MobVisualState.Pose.GRAZE; i++) {
            interrupted.update(world, 0.05f);
        }
        require(interrupted.mobVisualState().pose() == MobVisualState.Pose.GRAZE, "Cừu bắt đầu lượt ăn trước khi bị đánh");
        Player attacker = new Player(41.5f, 16f, 38.5f);
        require(interrupted.damage(world, 1f, DamageSource.MELEE, attacker, 0f, 0f), "Đòn đánh ngắt lượt ăn");
        for (int i = 0; i < 25; i++) {
            interrupted.update(world, 0.05f);
        }
        require(interrupted.mobVisualState().pose() == MobVisualState.Pose.IDLE
                        && world.getBlock(43, 16, 38) == Block.SHORT_GRASS.getId(),
                "Khi chạy hoảng, cừu ngẩng đầu và không ăn cỏ của lượt đã hủy");
    }

    /** Tạo ô đứng cố định để việc canh thời điểm ăn độc lập với hướng đi ngẫu nhiên. */
    private static void pen(World world, int x, int z, Block cover) {
        world.setBlockInternal(x, 15, z, Block.GRASS.getId(), 0);
        world.setBlockInternal(x, 16, z, cover.getId(), 0);
        for (int y = 16; y < 19; y++) {
            world.setBlockInternal(x - 1, y, z, Block.STONE.getId(), 0);
            world.setBlockInternal(x + 1, y, z, Block.STONE.getId(), 0);
            world.setBlockInternal(x, y, z - 1, Block.STONE.getId(), 0);
            world.setBlockInternal(x, y, z + 1, Block.STONE.getId(), 0);
        }
    }

    /** Theo dõi tư thế cúi đầu rồi dừng ngay khi mẫu đang ăn đổi trạng thái. */
    private static boolean waitForGrass(World world, Sheep sheep, int x, int y, int z, Block expected, int maxTicks) {
        boolean grazing = false;
        for (int i = 0; i < maxTicks && world.getBlock(x, y, z) == expected.getId(); i++) {
            sheep.update(world, 0.05f);
            grazing |= sheep.mobVisualState().pose() == MobVisualState.Pose.GRAZE;
        }
        return grazing;
    }

    /** Gà rơi chậm, có hoạt ảnh cánh và miễn nhiễm cả sát thương rơi gọi trực tiếp. */
    private static void checkChickenFall(World world) {
        // Cách xa các chuồng để gà không chọn mái chuồng làm đích lang thang trong lúc rơi.
        world.setBlockInternal(85, 13, 30, Block.STONE.getId(), 0);
        Chicken chicken = new Chicken(85.5f, 34f, 30.5f);
        require(!chicken.damage(world, 100f, DamageSource.FALL, null, 0f, 0f), "Gà miễn sát thương FALL");
        for (int i = 0; i < 60; i++) {
            chicken.update(world, 0.05f);
        }
        require(chicken.y() > 28f && chicken.y() < 32f && chicken.getVelocity().y > -2f
                        && chicken.mobVisualState().pose() == MobVisualState.Pose.FLAP,
                "Gà vỗ cánh và giới hạn vận tốc trong lúc hạ xuống");
        for (int i = 0; i < 240 && !chicken.isOnGround(); i++) {
            chicken.update(world, 0.05f);
        }
        require(chicken.isOnGround() && chicken.mobVisualState().pose() == MobVisualState.Pose.IDLE,
                "Gà thu cánh khi đã đáp đất");
        near(chicken.getHealth(), 4f, "Gà không mất HP sau khi hạ từ độ cao 20 block");
    }

    /** So sánh chỉ số dấu chấm động theo sai số nhỏ. */
    private static void near(float actual, float expected, String message) {
        require(Math.abs(actual - expected) < 0.0001f, message + " (" + actual + " thay vì " + expected + ")");
    }

    /** Báo riêng tính chất không còn đúng. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

package com.voxelgame.engine;

import com.voxelgame.client.render.ShaderProgram;
import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.world.effect.StatusEffectType;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.LivingEntity;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.monster.Parched;
import com.voxelgame.world.entity.mob.monster.Stray;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.entity.projectile.ArrowEntity;
import com.voxelgame.world.entity.projectile.ArrowType;
import com.voxelgame.world.entity.projectile.PotionType;
import com.voxelgame.world.entity.projectile.ThrownEnderPearlEntity;
import com.voxelgame.world.entity.projectile.ThrownPotionEntity;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

/** Kiểm tra đường đi và tác động của đạn đạo trên CPU. */
final class ProjectileChecks {
    /** Chạy các ca va chạm, phe, hiệu ứng và vòng đời. */
    static void run() {
        World world = World.empty();
        try {
            checkSweptArrowAndRetaliation(world);
            checkOcclusionAndDisposal(world);
            checkGrazingBlock(world);
            checkTippedArrowsAndDodge(world);
            checkArrowStickingAndPickup(world);
            checkPotionSplash(world);
            checkInstantPotions(world);
        } finally {
            world.dispose();
        }
    }

    /** Bán kính đạn chạm đá ở ô bên cạnh, còn cạnh trống quanh xương rồng vẫn thông. */
    private static void checkGrazingBlock(World world) {
        world.setBlockInternal(73, 11, 70, Block.STONE.getId(), 0);
        world.setBlockInternal(73, 11, 80, Block.CACTUS.getId(), 0);
        Dummy behindStone = new Dummy(75.5f, 10.5f, 69.97f, false, 0);
        Dummy behindCactus = new Dummy(75.5f, 10.5f, 79.97f, false, 0);
        world.addEntity(behindStone);
        world.addEntity(behindCactus);

        ArrowEntity stone = new ArrowEntity(null, 71.5f, 11.6f, 69.97f, 35f, 0f, 0f, ArrowType.NORMAL, 4f);
        stone.update(world, 0.15f);
        require(stone.isInGround() && !stone.isFinished(), "Tên sượt cạnh phải dừng và cắm vào khối chắn");
        near(stone.getPosition().x, 73f - 0.045f, "Tâm tên dừng cách mặt đá đúng bán kính tên");
        near(behindStone.getHealth(), 20f, "Đá chặn tên sượt mép trước mục tiêu");

        ArrowEntity cactus = new ArrowEntity(null, 71.5f, 11.6f, 79.97f, 35f, 0f, 0f, ArrowType.NORMAL, 4f);
        cactus.update(world, 0.15f);
        near(behindCactus.getHealth(), 16f, "Tên lọt qua mép trống của hộp va chạm xương rồng");

        ThrownPotionEntity potion = new ThrownPotionEntity(null, 71.5f, 11.6f, 69.9f, 35f, 0f, 0f,
                PotionType.SLOWNESS);
        potion.update(world, 0.05f);
        require(potion.isFinished(), "Lọ thuốc sượt khối phải vỡ theo bán kính riêng");

        world.setBlockInternal(73, 11, 65, Block.STONE.getId(), 0);
        ArrowEntity tangent = new ArrowEntity(null, 75.5f, 11.6f, 66f + 0.045f, -35f, 0f, 0f,
                ArrowType.NORMAL, 4f);
        tangent.update(world, 0.15f);
        require(tangent.isInGround() && !tangent.isFinished(), "Biên ô phía dưới vẫn được tính và tên cắm vào khối");
        near(tangent.getPosition().x, 74f + 0.045f, "Tên bắn ngược dừng ở mặt đá gần");
    }

    /** Một đoạn dài vẫn chọn nạn nhân gần nhất bằng hộp và loại chủ, thú cưỡi, đồng phe. */
    private static void checkSweptArrowAndRetaliation(World world) {
        Dummy mount = new Dummy(11.3f, 10f, 10.5f, false, 1);
        MobEntity shooter = new MobEntity(MobType.SKELETON, 10.5f, 10f, 10.5f) { };
        MobEntity ally = new MobEntity(MobType.SKELETON, 12.8f, 10f, 10.5f) { };
        MobEntity victim = new MobEntity(MobType.ZOMBIE, 15.5f, 10f, 10.5f) { };
        Dummy far = new Dummy(17.5f, 10f, 10.5f, false, 0);
        require(shooter.tryMount(mount, 0), "Chuẩn bị thú cưỡi cho người bắn");
        world.addEntity(far);
        world.addEntity(ally);
        world.addEntity(victim);
        world.addEntity(mount);
        world.addEntity(shooter);
        ArrowEntity arrow = new ArrowEntity(shooter, 10.5f, 11.5f, 10.5f, 50f, 0f, 0f,
                ArrowType.NORMAL, 3.5f);
        arrow.update(world, 0.19f);
        require(arrow.isStuckInMob() && arrow.getStuckMob() == victim && victim.getHealth() < victim.getMaxHealth(),
                "Tên tốc độ cao phải chạm và cắm vào quái vật khác phe gần nhất");
        near(shooter.getHealth(), shooter.getMaxHealth(), "Tên không trúng người bắn");
        near(ally.getHealth(), ally.getMaxHealth(), "Tên không trúng đồng phe");
        near(mount.getHealth(), mount.getMaxHealth(), "Tên không trúng thú đang cưỡi");
        near(far.getHealth(), far.getMaxHealth(), "Tên dừng trước mục tiêu phía sau");
        require(shooter.target() == victim && victim.target() == shooter, "Hai quái khác phe phải trả đòn");
    }

    /** Hộp block chặn đường tới mục tiêu và đạn hết hạn kết thúc vòng đời. */
    private static void checkOcclusionAndDisposal(World world) {
        Dummy victim = new Dummy(25.5f, 10f, 20.5f, false, 0);
        world.addEntity(victim);
        world.setBlockInternal(24, 11, 20, Block.STONE.getId(), 0);
        ArrowEntity arrow = new ArrowEntity(null, 20.5f, 11.5f, 20.5f, 80f, 0f, 0f,
                ArrowType.NORMAL, 4f);
        arrow.update(world, 0.15f);
        require(arrow.isInGround() && !arrow.isFinished() && arrow.getPosition().x <= 24.01f, "Tên cắm ở mặt tường");
        near(victim.getHealth(), 20f, "Tên không xuyên khối chắc");

        ArrowEntity expired = new ArrowEntity(null, 110.5f, 40f, 110.5f, 0f, 80f, 0f,
                ArrowType.NORMAL, 4f);
        expired.update(world, 7.9f);
        require(!expired.isFinished(), "Đạn trong thế giới vẫn bay trước khi hết tuổi thọ");
        expired.update(world, 0.11f);
        require(expired.isFinished() && expired.getPosition().y > 0f, "Đạn hết tuổi thọ phải kết thúc trong thế giới");

        ArrowEntity leaving = new ArrowEntity(null, 0.5f, 11.5f, 20.5f, -40f, 0f, 0f,
                ArrowType.NORMAL, 4f);
        int previousCount = world.entityCount();
        world.addEntity(leaving);
        world.updateEntities(0.05f);
        require(leaving.isFinished() && world.entityCount() == previousCount,
                "World phải thu hồi đạn vừa rời biên");
    }

    /** Tên đặc thù gắn đúng hiệu ứng; hook né được gọi trước mọi tác động. */
    private static void checkTippedArrowsAndDodge(World world) {
        Dummy slow = new Dummy(35.5f, 10f, 30.5f, false, 0);
        Dummy weak = new Dummy(35.5f, 10f, 34.5f, false, 0);
        Dodger dodger = new Dodger(35.5f, 10f, 38.5f);
        world.addEntity(slow);
        world.addEntity(weak);
        world.addEntity(dodger);
        new ArrowEntity(null, 31.5f, 11.4f, 30.5f, 30f, 0f, 0f, ArrowType.SLOWNESS, 3f).update(world, 0.2f);
        new ArrowEntity(null, 31.5f, 11.4f, 34.5f, 30f, 0f, 0f, ArrowType.WEAKNESS, 3f).update(world, 0.2f);
        new ArrowEntity(null, 31.5f, 11.4f, 38.5f, 30f, 0f, 0f, ArrowType.SLOWNESS, 3f).update(world, 0.2f);
        near(slow.getEffectDuration(StatusEffectType.SLOWNESS), 30f, "Tên Stray làm chậm 30 giây");
        require(slow.getVelocity().x > 0f, "Tên đẩy mục tiêu theo hướng bay");
        near(weak.getEffectDuration(StatusEffectType.WEAKNESS), 30f, "Tên Parched làm yếu 30 giây");
        require(dodger.attempts == 1 && !dodger.hasEffect(StatusEffectType.SLOWNESS), "Né chặn cả hiệu ứng tên");
        near(dodger.getHealth(), 20f, "Né xảy ra trước sát thương");
    }

    /** Kiểm tra mũi tên cắm đất, rơi khi đào khối đỡ, người chơi nhặt lại, cắm theo mob và diện mạo Ender Pearl. */
    private static void checkArrowStickingAndPickup(World world) {
        ThrownEnderPearlEntity pearl = new ThrownEnderPearlEntity(null, 90.5f, 20f, 90.5f, 10f, 2f, 0f);
        require(pearl.mobVisualState().appearance() == MobAppearance.ENDER_PEARL,
                "Ender Pearl ném ra phải dùng diện mạo MobAppearance.ENDER_PEARL");

        // 1. Mũi tên của người chơi cắm xuống khối đá, rơi khi đào khối đó rồi được nhặt lại
        world.setBlockInternal(92, 12, 90, Block.STONE.getId(), 0);
        world.setBlockInternal(92, 10, 90, Block.STONE.getId(), 0);
        Player shooter = new Player(92.5f, 15f, 90.5f);
        world.registerPlayer(shooter);
        ArrowEntity playerArrow = new ArrowEntity(shooter, 92.5f, 14f, 90.5f, 0f, -20f, 0f,
                ArrowType.SLOWNESS, 4f);
        playerArrow.update(world, 0.2f);
        require(playerArrow.isInGround() && !playerArrow.isFinished() && playerArrow.isPickupable(),
                "Mũi tên của người chơi phải cắm trên khối đá và cho phép nhặt");

        // Phá khối đá đỡ -> mũi tên rời trạng thái cắm, rơi xuống khối bên dưới (y=10)
        world.setBlockInternal(92, 12, 90, Block.AIR.getId(), 0);
        playerArrow.update(world, 0.05f);
        require(!playerArrow.isInGround(), "Khi khối đỡ bị phá, mũi tên phải rơi tiếp");
        playerArrow.update(world, 0.6f);
        require(playerArrow.isInGround() && playerArrow.getPosition().y <= 11.2f,
                "Mũi tên rơi xuống phải cắm vào khối đá bên dưới");

        // Đưa người chơi lại gần sau khi qua độ trễ nhặt -> mũi tên vào túi đồ và kết thúc vòng đời
        shooter.setPosition(92.5f, 11.0f, 90.5f);
        for (int i = 0; i < 8 && !playerArrow.isFinished(); i++) {
            playerArrow.update(world, 0.05f);
        }
        require(playerArrow.isFinished() && shooter.getInventory().getItem(0) == Item.TIPPED_ARROW_SLOWNESS
                        && shooter.getInventory().getCount(0) == 1,
                "Người chơi lại gần phải nhặt được đúng mũi tên cắm trên đất vào túi đồ");

        // 2. Mũi tên cắm vào mob di chuyển theo mob và biến mất khi mob chết
        MobEntity targetMob = new MobEntity(MobType.ZOMBIE, 96.5f, 11f, 90.5f) { };
        world.addEntity(targetMob);
        ArrowEntity mobArrow = new ArrowEntity(shooter, 94.5f, 12.0f, 90.5f, 40f, 0f, 0f,
                ArrowType.NORMAL, 3f);
        mobArrow.update(world, 0.1f);
        require(mobArrow.isStuckInMob() && mobArrow.getStuckMob() == targetMob && !mobArrow.isFinished(),
                "Mũi tên bắn trúng mob sống phải cắm vào thân mob");
        float beforeArrowX = mobArrow.getPosition().x;
        targetMob.setPosition(99.5f, 11f, 90.5f);
        mobArrow.update(world, 0.05f);
        require(mobArrow.getPosition().x > beforeArrowX + 2.5f,
                "Mũi tên cắm trên mob phải di chuyển theo mob");
        targetMob.update(world, 0.6f);
        targetMob.damage(world, 50f, DamageSource.MELEE, shooter, 0f, 0f);
        mobArrow.update(world, 0.05f);
        require(mobArrow.isFinished() && !mobArrow.isStuckInMob(),
                "Khi mob chết, mũi tên cắm trên thân mob phải tự dọn sạch");
    }

    /** Vỡ trên block tạo vòng ảnh hưởng quanh điểm va chạm thật. */
    private static void checkPotionSplash(World world) {
        Dummy inside = new Dummy(46.5f, 10.5f, 42.5f, false, 0);
        Dummy outside = new Dummy(46.5f, 10.5f, 44.8f, false, 0);
        world.addEntity(inside);
        world.addEntity(outside);
        world.setBlockInternal(46, 11, 40, Block.STONE.getId(), 0);
        ThrownPotionEntity splash = new ThrownPotionEntity(null, 40.5f, 11.7f, 40.5f, 38f, 0f, 0f,
                PotionType.SLOWNESS);
        splash.update(world, 0.2f);
        require(splash.isFinished(), "Lọ thuốc vỡ trên mặt khối");
        near(inside.getEffectDuration(StatusEffectType.SLOWNESS), 90f, "Làm chậm trong bán kính bốn block");
        require(!outside.hasEffect(StatusEffectType.SLOWNESS), "Bên ngoài bán kính không nhận thuốc");

        Dummy poison = new Dummy(52.5f, 10f, 41.5f, false, 0);
        Dummy weakness = new Dummy(52.5f, 10f, 48.5f, false, 0);
        world.addEntity(poison);
        world.addEntity(weakness);
        tossAt(world, null, 52.5f, 41.5f, PotionType.POISON);
        tossAt(world, null, 52.5f, 48.5f, PotionType.WEAKNESS);
        near(poison.getEffectDuration(StatusEffectType.POISON), 45f, "Thuốc độc kéo dài 45 giây");
        near(weakness.getEffectDuration(StatusEffectType.WEAKNESS), 90f, "Thuốc yếu kéo dài 90 giây");
    }

    /** Thuốc tức thời đổi dấu theo undead, giảm độ mạnh khi vỡ xa hơn. */
    private static void checkInstantPotions(World world) {
        Dummy direct = new Dummy(66.5f, 10f, 58.5f, false, 0);
        Dummy near = new Dummy(66.5f, 10f, 60.5f, false, 0);
        Dummy undead = new Dummy(66.5f, 10f, 56.8f, true, 0);
        Dummy owner = new Dummy(62.5f, 10f, 58.5f, false, 0);
        undead.damage(world, 8f, DamageSource.FALL, null, 0f, 0f);
        world.addEntity(direct);
        world.addEntity(near);
        world.addEntity(undead);
        world.addEntity(owner);
        tossAt(world, owner, 66.5f, 58.5f, PotionType.HARMING);
        near(direct.getHealth(), 14f, "Trúng trực tiếp Harming mất sáu HP");
        require(near.getHealth() > 14f && near.getHealth() < 20f, "Mức sát thương giảm dần theo khoảng cách");
        require(undead.getHealth() > 12f && undead.getHealth() < 16f, "Harming hồi HP cho undead gần tâm");
        near(owner.getHealth(), 20f, "Miễn tác động cho người ném ngay cả trong vòng thuốc");

        Dummy cursed = new Dummy(66.5f, 10f, 68.5f, true, 0);
        world.addEntity(cursed);
        tossAt(world, null, 66.5f, 68.5f, PotionType.HEALING);
        near(cursed.getHealth(), 14f, "Healing gây sát thương phép cho undead");

        Dummy wounded = new Dummy(66.5f, 10f, 74.5f, false, 0);
        wounded.damage(world, 5f, DamageSource.FALL, null, 0f, 0f);
        world.addEntity(wounded);
        tossAt(world, null, 66.5f, 74.5f, PotionType.HEALING);
        near(wounded.getHealth(), 19f, "Healing hồi bốn HP nếu trúng trực tiếp cá thể sống");
    }

    /** Phóng một lọ theo đường cố định tới vị trí kiểm tra. */
    private static void tossAt(World world, Entity owner, float x, float z, PotionType type) {
        new ThrownPotionEntity(owner, x - 4f, 11.4f, z, 30f, 0f, 0f, type).update(world, 0.2f);
    }

    /** So sánh đủ chính xác để phát hiện lượng HP hay giây hiệu ứng bị đổi. */
    private static void near(float actual, float expected, String message) {
        require(Math.abs(actual - expected) < 0.0001f, message + " (" + actual + " thay vì " + expected + ")");
    }

    /** Báo tình huống vi phạm thay vì tiếp tục cả chuỗi kiểm tra. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    /** Mục tiêu bất động giúp đo chính xác điểm và lượng tác động. */
    private static class Dummy extends LivingEntity {
        /** Dựng hộp mục tiêu thông thường và số ghế yêu cầu. */
        private Dummy(float x, float y, float z, boolean undead, int seats) {
            super(x, y, z, 0.3f, 1.8f, 20f, 0f, undead, seats);
        }

        /** Giữ nguyên vị trí giữa các lần bắn. */
        @Override
        protected void updateLiving(World world, float dt) {
        }

        /** Mục tiêu CPU không cần hình học. */
        @Override
        public void render(ShaderProgram shader) {
        }
    }

    /** Mục tiêu kiểm tra đường gọi né chung của mọi mũi tên. */
    private static final class Dodger extends Dummy {
        private int attempts;

        /** Tạo mục tiêu có khả năng né dứt khoát. */
        private Dodger(float x, float y, float z) {
            super(x, y, z, false, 0);
        }

        /** Đếm lần gọi để xác nhận mũi tên không gây tác động sau khi né. */
        @Override
        public boolean dodgeProjectile(World world, Entity owner) {
            attempts++;
            return true;
        }
    }
}

package com.voxelgame.engine;

import com.voxelgame.client.render.entity.MobAppearance;
import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.ItemEntity;
import com.voxelgame.world.entity.mob.animal.Rabbit;
import com.voxelgame.world.entity.mob.animal.SnowFox;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.player.Hotbar;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

/** Kiểm tra biến thể, cách đi, hành vi ngủ, săn mồi và mang vật phẩm bằng CPU. */
final class RabbitFoxChecks {
    /** Chạy các trường hợp trong thế giới phẳng, với thời gian và tư thế người chơi được đặt trực tiếp. */
    static void run() {
        checkRabbitVariants();
        checkRabbitHoppingAndTemptation();
        checkRabbitThreatRanges();
        checkFoxSleepAndSneak();
        checkFoxPounce();
        checkFoxMissesOnThinSnow();
        checkFoxCarrying();
    }

    /** Kiểm tra toàn bộ miền bốc màu với bước 1%, cộng ngưỡng phân chia chính xác. */
    private static void checkRabbitVariants() {
        int white = 0;
        int splotched = 0;
        for (int i = 0; i < 100; i++) {
            float roll = i / 100f;
            require(Rabbit.appearanceFor(MobType.RABBIT, roll) == MobAppearance.RABBIT_GOLD,
                    "Thỏ sa mạc luôn dùng lông vàng cát");
            MobAppearance snow = Rabbit.appearanceFor(MobType.SNOW_RABBIT, roll);
            white += snow == MobAppearance.RABBIT_WHITE ? 1 : 0;
            splotched += snow == MobAppearance.RABBIT_WHITE_SPLOTCHED ? 1 : 0;
        }
        require(white == 80 && splotched == 20, "Thỏ tuyết có đúng tỉ lệ 80% trắng và 20% đốm");
        require(new Rabbit(0, 0, 0).mobVisualState().appearance() == MobAppearance.RABBIT_GOLD
                && Rabbit.snow(0, 0, 0).type() == MobType.SNOW_RABBIT,
                "Hai lối khởi tạo phải chọn đúng cấu hình nơi sinh");
    }

    /** Thỏ dùng nhảy gần hai block và đổi từ tháo chạy sang đi theo người cầm bồ công anh. */
    private static void checkRabbitHoppingAndTemptation() {
        World world = arena(false);
        try {
            Rabbit rabbit = new Rabbit(100.5f, 20f, 100.5f);
            Player player = new Player(106.5f, 20f, 100.5f);
            world.registerPlayer(player);
            float highest = rabbit.y();
            boolean hopped = false;
            for (int i = 0; i < 40; i++) {
                rabbit.update(world, 0.025f);
                highest = Math.max(highest, rabbit.y());
                hopped |= rabbit.mobVisualState().pose() == MobVisualState.Pose.HOP;
            }
            require(hopped && highest > 21.7f && highest < 22.2f,
                    "Thỏ phải di chuyển bằng vòng nhảy gần hai block");
            require(rabbit.x() < 99.7f, "Thỏ phải tránh người chơi trong tám block khi không có mồi");

            require(player.getHotbar().addItem(Block.DANDELION, 1), "Cần đặt bồ công anh vào Hotbar");
            player.getHotbar().selectSlot(0);
            Rabbit following = new Rabbit(100.5f, 20f, 100.5f);
            tick(world, following, 1.1);
            require(following.x() > 101.3f, "Thỏ phải tiến về người chơi đang cầm bồ công anh");
        } finally {
            world.dispose();
        }
    }

    /** Sói cách chín block và quái thù địch cách ba block đều làm thỏ tháo chạy. */
    private static void checkRabbitThreatRanges() {
        World world = arena(false);
        try {
            Rabbit rabbit = new Rabbit(100.5f, 20f, 100.5f);
            MobEntity wolf = new MobEntity(MobType.WOLF, 109.5f, 20f, 100.5f) { };
            world.addLivingEntity(wolf);
            tick(world, rabbit, 0.6);
            require(rabbit.x() < 100f, "Thỏ phải nhận ra sói ở ngoài bán kính sợ người chơi");
            wolf.setPosition(150.5f, 20f, 100.5f);
            world.addLivingEntity(new MobEntity(MobType.ZOMBIE, 103.5f, 20f, 100.5f) { });
            Rabbit againstMonster = new Rabbit(100.5f, 20f, 100.5f);
            tick(world, againstMonster, 0.6);
            require(againstMonster.x() < 100f, "Thỏ phải tránh quái ở trong bốn block");
        } finally {
            world.dispose();
        }
    }

    /** Cáo tìm tới tán vân sam, giữ giấc ngủ trước người cúi rón rén và tỉnh dậy để bỏ chạy. */
    private static void checkFoxSleepAndSneak() {
        World world = arena(false);
        try {
            world.setBlock(103, 22, 100, Block.SPRUCE_LEAVES.getId());
            SnowFox fox = new SnowFox(100.5f, 20f, 100.5f);
            tick(world, fox, 2.2);
            require(fox.isSleeping() && fox.mobVisualState().appearance() == MobAppearance.SNOW_FOX_SLEEP,
                    "Cáo phải tìm tán vân sam xung quanh và dùng diện mạo ngủ");
            float sleepingX = fox.x();
            float sleepingZ = fox.z();
            QuietPlayer player = new QuietPlayer(sleepingX + 10f, 20f, sleepingZ);
            world.registerPlayer(player);
            tick(world, fox, 0.35);
            require(fox.isSleeping() && fox.x() == sleepingX && fox.z() == sleepingZ,
                    "Người rón rén tới gần không được làm cáo thức hay chạy trốn");
            player.sneaking = false;
            tick(world, fox, 0.8);
            require(!fox.isSleeping() && fox.mobVisualState().appearance() == MobAppearance.SNOW_FOX,
                    "Người đứng thẳng trong mười hai block phải làm cáo thức");
            float dx = fox.x() - sleepingX;
            float dz = fox.z() - sleepingZ;
            require(dx * dx + dz * dz > 0.4f, "Cáo phải chạy khỏi vị trí ngủ khi phát hiện người");
        } finally {
            world.dispose();
        }
    }

    /** Dùng một thỏ thật đứng phẳng để xác minh lấy đà, vòng cung và đúng sát thương khi vồ. */
    private static void checkFoxPounce() {
        World world = arena(true);
        try {
            SnowFox fox = new SnowFox(100.5f, 20f, 100.5f);
            Rabbit prey = Rabbit.snow(104.5f, 20f, 100.5f);
            world.addLivingEntity(prey);
            boolean crouched = false;
            boolean leapt = false;
            float highest = fox.y();
            for (int i = 0; i < 90 && prey.getHealth() == 3f; i++) {
                fox.update(world, 0.025f);
                crouched |= fox.mobVisualState().pose() == MobVisualState.Pose.CROUCH;
                leapt |= fox.mobVisualState().pose() == MobVisualState.Pose.POUNCE;
                highest = Math.max(highest, fox.y());
            }
            require(crouched && leapt && highest > 21.4f && prey.getHealth() == 1f,
                    "Cáo phải lấy đà, nhảy thành vòng cung và gây hai HP khi vồ trúng thỏ");
        } finally {
            world.dispose();
        }
    }

    /** Dời mồi sau khi cáo nhảy để cú vồ hụt kết thúc trong lớp tuyết mỏng. */
    private static void checkFoxMissesOnThinSnow() {
        World world = arena(true);
        try {
            for (int x = 103; x <= 105; x++) {
                world.setBlock(x, 20, 100, Block.SNOW_LAYER.getId(), 0);
            }
            SnowFox fox = new SnowFox(100.5f, 20f, 100.5f);
            Rabbit prey = Rabbit.snow(104.5f, 20.125f, 100.5f);
            world.addLivingEntity(prey);
            boolean moved = false;
            boolean faceplanted = false;
            for (int i = 0; i < 84 && !faceplanted; i++) {
                fox.update(world, 0.025f);
                if (!moved && fox.mobVisualState().pose() == MobVisualState.Pose.POUNCE) {
                    prey.setPosition(104.5f, 20f, 104.5f);
                    moved = true;
                }
                faceplanted = fox.mobVisualState().pose() == MobVisualState.Pose.FACEPLANT;
            }
            require(moved && faceplanted && prey.getHealth() == 3f,
                    "Cáo vồ hụt phải chúi đầu vào tuyết mỏng mà không gây sát thương");
            tick(world, fox, 0.8);
            require(fox.mobVisualState().pose() != MobVisualState.Pose.FACEPLANT,
                    "Cáo phải đứng dậy sau khi chúi xuống tuyết");
        } finally {
            world.dispose();
        }
    }

    /** Cáo nhặt đúng một vật phẩm và trả ra thế giới khi chết. */
    private static void checkFoxCarrying() {
        World world = arena(true);
        try {
            SnowFox fox = new SnowFox(100.5f, 20f, 100.5f);
            world.spawnDroppedItem(new ItemEntity(101f, 20f, 100.5f, Block.DANDELION));
            world.spawnDroppedItem(new ItemEntity(101.4f, 20f, 100.5f, Block.DIRT));
            tick(world, fox, 0.35);
            require(fox.mobVisualState().heldBlock() == Block.DANDELION,
                    "Cáo nhặt vật phẩm gần nhất để ngậm và chỉ giữ một vật phẩm");
            fox.damage(world, 20f, DamageSource.MELEE, null, 0f, 0f);
            tick(world, fox, 0.05);
            require(fox.mobVisualState().heldBlock() == null && countGroundItems(world, Block.DANDELION) == 1
                    && countGroundItems(world, Block.DIRT) == 1,
                    "Cáo chết trả lại đúng vật phẩm đã nhặt và giữ nguyên vật phẩm khác");
        } finally {
            world.dispose();
        }
    }

    /** Đếm các vật phẩm vẫn tồn tại trên mặt đất theo loại block. */
    private static int countGroundItems(World world, Block block) {
        int count = 0;
        for (int i = 0; i < world.entityCount(); i++) {
            if (world.entityAt(i) instanceof ItemEntity item && !item.isCollected() && item.getBlock() == block) {
                count++;
            }
        }
        return count;
    }

    /** Tạo mặt nền đủ rộng cho các nhịp tìm vị trí hợp lệ. */
    private static World arena(boolean night) {
        World world = World.empty();
        for (int x = 87; x <= 119; x++) {
            for (int z = 87; z <= 113; z++) {
                world.setBlock(x, 19, z, Block.STONE.getId());
            }
        }
        if (night) {
            world.worldTime().update(850);
        }
        return world;
    }

    /** Chỉ cập nhật cá thể đang kiểm tra để mục tiêu thử đứng nguyên vị trí. */
    private static void tick(World world, MobEntity mob, double seconds) {
        int frames = (int) Math.round(seconds / 0.025);
        for (int i = 0; i < frames; i++) {
            mob.update(world, 0.025f);
        }
    }

    /** Phát lỗi có ngữ cảnh khi kết quả không khớp hành vi đòi hỏi. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    /** Người chơi đứng yên có trạng thái Sneak được đặt trực tiếp cho tình huống kiểm thử. */
    private static final class QuietPlayer extends Player {
        private boolean sneaking = true;

        /** Khởi tạo đúng hình học của người chơi thật trên nền thử. */
        private QuietPlayer(float x, float y, float z) {
            super(x, y, z);
        }

        /** Trả trạng thái cúi của nhịp thử hiện tại. */
        @Override
        public boolean isSneaking() {
            return sneaking;
        }
    }
}

package com.voxelgame.engine;

import com.voxelgame.client.render.entity.MobVisualState;
import com.voxelgame.world.effect.StatusEffectType;
import com.voxelgame.world.entity.DamageSource;
import com.voxelgame.world.entity.Entity;
import com.voxelgame.world.entity.mob.MobEntity;
import com.voxelgame.world.entity.mob.MobType;
import com.voxelgame.world.entity.mob.monster.Parched;
import com.voxelgame.world.entity.mob.monster.Skeleton;
import com.voxelgame.world.entity.mob.monster.Stray;
import com.voxelgame.world.entity.mob.monster.Witch;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.entity.projectile.ArrowEntity;
import com.voxelgame.world.entity.projectile.PotionType;
import com.voxelgame.world.entity.projectile.ProjectileEntity;
import com.voxelgame.world.entity.projectile.ThrownPotionEntity;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.World;

/** Kiểm tra AI đánh xa, nhắm mục tiêu và hiệu ứng của các mob bước bốn trên CPU. */
final class RangedHostileChecks {
    /** Chạy các trường hợp bắn từ mặt đất, từ thú cưỡi, chọn thuốc và phòng vệ. */
    static void run() {
        checkStrafingAndMountedFire();
        checkArrowEffects(false);
        checkArrowEffects(true);
        checkWitchPotionPriority();
        checkWitchThrows();
        checkWitchDrinks();
        checkWitchWaterAndSpeed();
    }

    /** Skeleton lùi trước người chơi áp sát và có thể bắn khi đang ngồi trên lưng nhện. */
    private static void checkStrafingAndMountedFire() {
        World world = arena();
        try {
            Skeleton walker = new Skeleton(100.5f, 20f, 100.5f);
            Player player = new Player(103.5f, 20f, 100.5f);
            world.registerPlayer(player);
            for (int i = 0; i < 8; i++) {
                walker.update(world, 0.05f);
            }
            require(walker.x() < 100.1f, "Skeleton phải lùi khi mục tiêu cách dưới bốn block");
            require(walker.mobVisualState().pose() == MobVisualState.Pose.AIM_BOW,
                    "Skeleton phải giương cung trong khi di chuyển");
            Player distant = new Player(109.5f, 20f, 105.5f);
            world.registerPlayer(distant);
            Skeleton strafe = new Skeleton(100.5f, 20f, 105.5f);
            for (int i = 0; i < 8; i++) {
                strafe.update(world, 0.05f);
            }
            require(Math.abs(strafe.z() - 105.5f) > 0.3f, "Skeleton phải di chuyển ngang khi đã trong tầm bắn");
            Skeleton rider = new Skeleton(100.5f, 20f, 105.5f);
            TestMount mount = new TestMount(100.5f, 20f, 105.5f);
            world.addLivingEntity(mount);
            require(rider.tryMount(mount, 0), "Ghế của nhện thử phải nhận Skeleton");
            for (int i = 0; i < 20; i++) {
                rider.update(world, 0.05f);
            }
            require(projectile(world, rider, ArrowEntity.class) == null
                            && rider.mobVisualState().poseAmount() >= 0.9f,
                    "Cung đã căng nhưng chưa bắn khi chưa đủ 20 tick kể từ lúc bắt đầu kéo");
            rider.update(world, 0.05f);
            require(projectile(world, rider, ArrowEntity.class) != null && rider.getMount() == mount
                            && rider.mobVisualState().poseAmount() == 0f,
                    "Skeleton cưỡi nhện phải nhả dây đúng tick tạo tên");
        } finally {
            world.dispose();
        }
    }

    /** Đạn do AI tạo phải đến được người chơi và áp dụng hiệu ứng riêng của loài. */
    private static void checkArrowEffects(boolean parchedVariant) {
        World world = arena();
        try {
            Skeleton archer = parchedVariant ? new Parched(100.5f, 20f, 100.5f)
                    : new Stray(100.5f, 20f, 100.5f);
            Player player = new Player(109.5f, 20f, 100.5f);
            world.registerPlayer(player);
            world.addLivingEntity(archer);
            for (int i = 0; i < 30 && projectile(world, archer, ArrowEntity.class) == null; i++) {
                archer.update(world, 0.05f);
            }
            ArrowEntity arrow = projectile(world, archer, ArrowEntity.class);
            require(arrow != null, "Mob bắn cung phải tạo đạn trong khoảng giương cung đầu");
            for (int i = 0; i < 35 && player.getHealth() == 20f; i++) {
                arrow.update(world, 0.025f);
            }
            StatusEffectType effect = parchedVariant ? StatusEffectType.WEAKNESS : StatusEffectType.SLOWNESS;
            require(player.hasEffect(effect) && player.getHealth() < 20f,
                    "Mũi tên trúng phải gây sát thương và hiệu ứng " + effect);
            near(player.getEffectDuration(effect), 30f, "Tên đặc biệt phải gây hiệu ứng trong đúng ba mươi giây");
            float damage = 20f - player.getHealth();
            float damageMinimum = parchedVariant ? 2f : 3f;
            require(damage >= damageMinimum && damage <= damageMinimum + 1f,
                    "Sát thương tên phải nằm trong dải HP của biến thể");
            if (parchedVariant) {
                require(archer.getHealth() == 16f && !archer.applyEffect(StatusEffectType.WEAKNESS, 0, 30f)
                        && !archer.hasEffect(StatusEffectType.WEAKNESS),
                        "Parched phải có 16 HP và không thể bị suy yếu");
            }
        } finally {
            world.dispose();
        }
    }

    /** Xác minh thứ tự ưu tiên thuốc và cả hai phía của ngưỡng ngẫu nhiên. */
    private static void checkWitchPotionPriority() {
        Player target = new Player(105.5f, 20f, 100.5f);
        require(Witch.choosePotion(target, 8f, 0.9f) == PotionType.SLOWNESS,
                "Khoảng cách từ tám block phải ưu tiên Slowness");
        target.applyEffect(StatusEffectType.SLOWNESS, 0, 90f);
        require(Witch.choosePotion(target, 8f, 0.9f) == PotionType.POISON,
                "Khi đã chậm, mục tiêu đủ HP nhận Poison");
        require(Witch.choosePotion(target, 3f, 0.1f) == PotionType.POISON,
                "Poison phải được ưu tiên hơn Weakness");
        target.applyEffect(StatusEffectType.POISON, 0, 45f);
        require(Witch.choosePotion(target, 3f, 0.249f) == PotionType.WEAKNESS,
                "Weakness phải dùng khoảng xác suất nhỏ hơn 25%");
        require(Witch.choosePotion(target, 3f, 0.25f) == PotionType.HARMING,
                "Xác suất đúng 25% thuộc nhánh Harming");
        target.applyEffect(StatusEffectType.WEAKNESS, 0, 90f);
        require(Witch.choosePotion(target, 2f, 0f) == PotionType.HARMING,
                "Có hiệu ứng Weakness rồi thì dùng Harming");
    }

    /** Witch phải tạo lọ thuốc có vùng hiệu ứng khi thấy mục tiêu mặc dù không đứng trong tầm cận chiến. */
    private static void checkWitchThrows() {
        World world = arena();
        try {
            Witch witch = new Witch(100.5f, 20f, 100.5f);
            Player player = new Player(109.5f, 20f, 100.5f);
            world.registerPlayer(player);
            world.addLivingEntity(witch);
            for (int i = 0; i < 30 && projectile(world, witch, ThrownPotionEntity.class) == null; i++) {
                witch.update(world, 0.05f);
            }
            ThrownPotionEntity potion = projectile(world, witch, ThrownPotionEntity.class);
            require(potion != null, "Witch phải ném thuốc khi mục tiêu ở cách chín block");
            for (int i = 0; i < 80 && !player.hasEffect(StatusEffectType.SLOWNESS); i++) {
                potion.update(world, 0.025f);
            }
            require(player.hasEffect(StatusEffectType.SLOWNESS), "Lọ thuốc quan sát được phải làm chậm mục tiêu");
        } finally {
            world.dispose();
        }
    }

    /** Kháng phép đúng 85% và uống xong hồi đúng bốn HP, không tạo đòn đánh thay thế. */
    private static void checkWitchDrinks() {
        World world = arena();
        try {
            Witch witch = new Witch(100.5f, 20f, 100.5f);
            require(witch.damage(world, 6f, DamageSource.POTION_MAGIC, null, 0f, 0f),
                    "Witch vẫn phải nhận phần sát thương phép sau kháng");
            near(witch.getHealth(), 25.1f, "Witch phải giảm 85% sát thương phép");
            for (int i = 0; i < 11; i++) {
                witch.update(world, 0.05f);
            }
            witch.damage(world, 6f, DamageSource.MELEE, null, 0f, 0f);
            float injured = witch.getHealth();
            for (int i = 0; i < 24; i++) {
                witch.update(world, 0.05f);
            }
            near(witch.getHealth(), injured + 4f, "Sau khi uống thuốc, Witch phải hồi bốn HP");
            Witch burning = new Witch(104.5f, 20f, 100.5f);
            burning.ignite(10f);
            for (int i = 0; i < 35; i++) {
                burning.update(world, 0.05f);
            }
            require(burning.hasEffect(StatusEffectType.FIRE_RESISTANCE)
                    && !burning.damage(world, 4f, DamageSource.LAVA, null, 0f, 0f),
                    "Witch đang cháy phải uống kháng lửa và chặn sát thương Lava");

            world.setBlock(108, 20, 100, Block.LAVA.getId());
            Witch inLava = new Witch(108.5f, 20f, 100.5f);
            require(inLava.getFireTimer() == 0f, "Witch thử nghiệm chưa được châm lửa trước nhịp đầu");
            inLava.update(world, 0.05f);
            require(inLava.mobVisualState().pose() == MobVisualState.Pose.DRINK,
                    "Witch phải bắt đầu uống ngay khi thân chạm Lava");
            for (int i = 0; i < 34; i++) {
                inLava.update(world, 0.05f);
            }
            require(inLava.hasEffect(StatusEffectType.FIRE_RESISTANCE),
                    "Witch chạm Lava phải hoàn tất thuốc kháng lửa");
        } finally {
            world.dispose();
        }
    }

    /** Khi ngập đầu hoặc đuổi người chơi ở xa, Witch chọn đúng thuốc phòng vệ kéo dài. */
    private static void checkWitchWaterAndSpeed() {
        World world = arena();
        try {
            for (int y = 20; y <= 25; y++) {
                world.setBlock(104, y, 100, Block.WATER.getId());
            }
            Witch submerged = new Witch(104.5f, 20f, 100.5f);
            for (int i = 0; i < 35; i++) {
                submerged.update(world, 0.05f);
            }
            require(submerged.hasEffect(StatusEffectType.WATER_BREATHING)
                    && !submerged.damage(world, 2f, DamageSource.DROWNING, null, 0f, 0f),
                    "Witch bị ngập đầu phải uống thuốc thở dưới nước");

            Witch pursuing = new Witch(100.5f, 20f, 105.5f);
            world.registerPlayer(new Player(112.5f, 20f, 105.5f));
            for (int i = 0; i < 35; i++) {
                pursuing.update(world, 0.05f);
            }
            require(pursuing.hasEffect(StatusEffectType.SWIFTNESS) && pursuing.getMovementSpeedMultiplier() > 1f,
                    "Witch đang đuổi mục tiêu xa trên mười một block phải uống thuốc tăng tốc");
        } finally {
            world.dispose();
        }
    }

    /** Dùng vùng nền phẳng đủ chỗ né ngang mà không sinh ngẫu nhiên thêm thực thể. */
    private static World arena() {
        World world = World.empty();
        for (int x = 94; x <= 114; x++) {
            for (int z = 94; z <= 111; z++) {
                world.setBlock(x, 19, z, Block.STONE.getId());
            }
        }
        world.worldTime().update(850);
        return world;
    }

    /** Lấy đúng đạn do cá thể đang thử bắn ra khỏi danh sách của World. */
    private static <T extends ProjectileEntity> T projectile(World world, MobEntity owner, Class<T> projectileType) {
        for (int i = 0; i < world.entityCount(); i++) {
            Entity entity = world.entityAt(i);
            if (projectileType.isInstance(entity) && entity instanceof ProjectileEntity shot
                    && shot.owner() == owner) {
                return projectileType.cast(entity);
            }
        }
        return null;
    }

    /** So sánh số thực trong giới hạn nhiễu tính toán khung cập nhật. */
    private static void near(float actual, float expected, String reason) {
        require(Math.abs(actual - expected) < 0.001f, reason + ". Nhận " + actual + ", đợi " + expected);
    }

    /** Phát lỗi có ngữ cảnh khi điều kiện hồi quy không khớp. */
    private static void require(boolean condition, String reason) {
        if (!condition) {
            throw new AssertionError(reason);
        }
    }

    /** Nhện đứng yên có một ghế để kiểm tra đường cập nhật khi cá thể bắn đang cưỡi. */
    private static final class TestMount extends MobEntity {
        /** Dựng hitbox nhện và một ghế sử dụng cơ chế cưỡi chung. */
        private TestMount(float x, float y, float z) {
            super(MobType.SPIDER, x, y, z, 0f, 1, false);
        }
    }
}

package com.voxelgame.engine;

import com.voxelgame.client.gui.DebugOverlayRenderer;
import com.voxelgame.client.gui.GuiTextureAtlas;
import com.voxelgame.client.gui.InventoryScreen;
import com.voxelgame.client.gui.UIRenderer;
import com.voxelgame.client.render.Camera;
import com.voxelgame.world.effect.StatusEffectType;
import com.voxelgame.world.entity.ItemEntity;
import com.voxelgame.world.entity.player.Hotbar;
import com.voxelgame.world.entity.player.Player;
import com.voxelgame.world.entity.player.PlayerInventory;
import com.voxelgame.world.item.Item;
import com.voxelgame.world.level.block.Block;
import com.voxelgame.world.level.block.OakLeavesBlock;
import com.voxelgame.world.level.block.SpruceLeavesBlock;
import com.voxelgame.world.level.LeafDecaySystem;
import com.voxelgame.world.level.World;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.Input;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.math.Vector3;
import com.badlogic.gdx.utils.GdxNativesLoader;
import java.io.IOException;
import java.io.InputStream;
import java.lang.reflect.Proxy;

/**
 * Kiểm tra hồi quy CPU cho các hệ thống sinh tồn, túi đồ 36 ô và môi trường của Track C.
 */
public final class SurvivalWorldChecks {

    private SurvivalWorldChecks() {
    }

    /** Chạy toàn bộ các ca kiểm thử của Track C. */
    public static void run() {
        checkInventoryAndDrop();
        checkInventorySlotInteractions();
        checkOxygenAndSprintSwimming();
        checkLeafDecayAndShearsSpeed();
        checkLiquidFlowAndStoneReaction();
        checkGuiTexturesPresent();
    }

    /**
     * Kiểm tra túi đồ 36 ô đồng bộ với Hotbar 9 ô và thao tác vứt vật phẩm (Q / Ctrl+Q).
     */
    private static void checkInventoryAndDrop() {
        World world = World.empty();
        try {
            world.setBlockInternal(10, 10, 10, Block.STONE.getId(), 0);
            world.setBlockInternal(10, 10, 9, Block.STONE.getId(), 0);

            Player player = new Player(10.5f, 11f, 10.5f);
            Camera camera = new Camera();
            player.attachControls(camera);
            world.registerPlayer(player);

            PlayerInventory inv = player.getInventory();
            require(inv != null, "Player phải sở hữu PlayerInventory");
            require(PlayerInventory.TOTAL_SLOTS == 36, "Tổng số ô túi đồ phải bằng 36");
            require(inv.getHotbar() == player.getHotbar(), "Hotbar phải đồng bộ với 9 ô đầu của PlayerInventory");

            // Khởi tạo Hotbar phải trống hoàn toàn; sau đó điền đầy 9 ô Hotbar để kiểm tra tràn sang balo
            for (int slot = 0; slot < Hotbar.SLOT_COUNT; slot++) {
                require(inv.getItem(slot) == Item.NONE && inv.getCount(slot) == 0,
                        "Ô Hotbar " + slot + " ban đầu phải trống");
            }
            player.getHotbar().setSlot(0, Block.DIRT, 16);
            for (int slot = 1; slot < Hotbar.SLOT_COUNT; slot++) {
                player.getHotbar().setSlot(slot, Block.STONE, 16);
            }
            player.getHotbar().setSlot(5, Item.EGG, 20);
            require(inv.getItem(5) == Item.EGG && inv.getCount(5) == 16,
                    "Egg trong ô 5 phải bị giới hạn đúng maxStackSize = 16");

            // Khi 9 ô Hotbar đã đầy, addItem qua Hotbar phải tự tràn sang ô 9 của PlayerInventory
            require(player.getHotbar().addItem(Item.IRON_INGOT, 10),
                    "Thêm vật phẩm khi Hotbar đầy phải tràn sang balo 27 ô");
            require(inv.getItem(9) == Item.IRON_INGOT && inv.getCount(9) == 10,
                    "Iron Ingot phải nằm tại ô đầu tiên của balo (ô 9)");

            // Kiểm tra cộng dồn và tách stack qua trần 64 giữa các ô balo
            require(inv.addItem(Item.IRON_INGOT, 60), "Phải cộng dồn được vào ô 9 và tràn sang ô 10");
            require(inv.getItem(9) == Item.IRON_INGOT && inv.getCount(9) == 64,
                    "Ô 9 phải đầy đúng 64 Iron Ingot");
            require(inv.getItem(10) == Item.IRON_INGOT && inv.getCount(10) == 6,
                    "Phần dư 6 Iron Ingot phải tràn sang ô 10");

            // Kiểm tra consumeFromSlot
            require(inv.consumeFromSlot(9, 10) == 10 && inv.getCount(9) == 54,
                    "consumeFromSlot(9, 10) phải lấy đúng 10 và còn 54");
            require(inv.consumeFromSlot(9, 100) == 54 && inv.getItem(9) == Item.NONE && inv.getCount(9) == 0,
                    "Tiêu thụ hết ô 9 phải đưa ô về Item.NONE");

            // Lấp đầy toàn bộ 36 ô để xác nhận từ chối khi túi đồ không còn chỗ
            for (int slot = 9; slot < PlayerInventory.TOTAL_SLOTS; slot++) {
                inv.setSlot(slot, Item.IRON_INGOT, 64);
            }
            require(!inv.addItem(Item.IRON_INGOT, 1), "Khi cả 36 ô đều đầy thì addItem phải trả về false");

            // Giải phóng 1 ô balo để kiểm tra vứt đồ và nhặt lại sau hết delay
            inv.setSlot(9, Item.NONE, 0);

            // Chọn ô 0 chứa 16 Dirt, gọi dropSelectedItem(world, false)
            player.getHotbar().selectSlot(0);
            require(player.getHotbar().getSelectedItem() == Item.of(Block.DIRT)
                    && player.getHotbar().getSelectedCount() == 16, "Ô 0 ban đầu phải có 16 Dirt");

            ItemEntity singleDrop = player.dropSelectedItem(world, false);
            require(singleDrop != null, "Vứt 1 vật phẩm phải tạo ItemEntity");
            require(player.getHotbar().getSelectedCount() == 15, "Sau khi vứt 1 Dirt ô 0 phải còn 15");
            require(inv.getCount(0) == 15, "PlayerInventory ô 0 phải đồng bộ còn 15");
            require(singleDrop.getItem() == Item.of(Block.DIRT) && singleDrop.getCount() == 1,
                    "ItemEntity vứt lẻ phải mang 1 Dirt");
            require(singleDrop.getPickupDelay() >= 1.0f,
                    "ItemEntity ném bằng Q phải có pickupDelay >= 1.0s để không hút lại ngay");

            Vector3 front = camera.getFront();
            float dotFront = (singleDrop.getPosition().x - player.getPosition().x) * front.x
                    + (singleDrop.getPosition().z - player.getPosition().z) * front.z;
            require(dotFront > 0f, "ItemEntity ném ra phải nằm phía trước mặt người chơi");

            // Đảm bảo ngay cả khi đứng sát người chơi trước 1.0s, ItemEntity vẫn chưa bị hút lại
            for (int i = 0; i < 6; i++) {
                singleDrop.setPosition(player.getPosition().x, player.getPosition().y + 0.9f, player.getPosition().z);
                singleDrop.update(world, player, player.getHotbar(), 0.05f);
            }
            require(!singleDrop.isCollected() && player.getHotbar().getSelectedCount() == 15,
                    "Không được tự nhặt lại ItemEntity khi chưa qua pickupDelay >= 1.0s");

            // Tiếp tục vứt cả stack còn lại (15 Dirt) với wholeStack = true
            ItemEntity stackDrop = player.dropSelectedItem(world, true);
            require(stackDrop != null, "Vứt cả stack phải tạo ItemEntity");
            require(player.getHotbar().getSelectedItem() == Item.NONE && player.getHotbar().getSelectedCount() == 0,
                    "Sau khi vứt cả stack ô 0 phải trống (Item.NONE, count 0)");
            require(inv.getItem(0) == Item.NONE && inv.getCount(0) == 0,
                    "PlayerInventory ô 0 phải trống sau khi vứt cả stack");
            require(stackDrop.getItem() == Item.of(Block.DIRT) && stackDrop.getCount() == 15,
                    "ItemEntity vứt cả stack phải mang đủ 15 Dirt");
            require(stackDrop.getPickupDelay() >= 1.0f,
                    "ItemEntity vứt cả stack cũng phải có pickupDelay >= 1.0s");

            // Vứt khi ô đang trống phải trả về null
            require(player.dropSelectedItem(world, false) == null,
                    "Vứt trên ô trống không được sinh ItemEntity");

            // Cho stackDrop trôi qua thời gian pickupDelay >= 1.0s rồi đặt sát tâm người chơi để nhặt lại
            for (int i = 0; i < 21; i++) {
                stackDrop.update(world, player, player.getHotbar(), 0.05f);
            }
            require(!stackDrop.isCollected(), "Stack bay ra xa phía trước chưa được nhặt khi ngoài tầm nam châm");
            stackDrop.setPosition(player.getPosition().x, player.getPosition().y + 0.9f, player.getPosition().z);
            stackDrop.update(world, player, player.getHotbar(), 0.05f);
            require(stackDrop.isCollected() && inv.getItem(0) == Item.of(Block.DIRT) && inv.getCount(0) == 15,
                    "Sau khi hết pickupDelay, người chơi phải nhặt lại đủ 15 Dirt vào ô trống");
        } finally {
            world.dispose();
        }
    }

    /**
     * Kiểm tra tương tác kéo thả, chia đôi stack, đặt từng đơn vị và Shift-Click trên túi đồ 36 ô.
     */
    private static void checkInventorySlotInteractions() {
        InventoryScreen screen = new InventoryScreen();
        World world = World.empty();
        try {
            Player player = new Player(10.5f, 11f, 10.5f);
            PlayerInventory inv = player.getInventory();

            require(!screen.isOpen(), "Màn hình túi đồ mặc định phải đóng");
            screen.toggle(player, world);
            require(screen.isOpen(), "toggle() phải mở màn hình túi đồ");

            // 1. Hoán đổi 2 ô bằng LEFT_CLICK: ô 9 (balo) và ô 0 (Hotbar)
            inv.setSlot(9, Block.STONE, 10);
            inv.setSlot(0, Block.OAK_LOG, 5);
            require(screen.handleSlotInteraction(inv, 9, InventoryScreen.LEFT_CLICK, false),
                    "Nhấn chuột trái vào ô 9 phải nhặt stack lên con trỏ");
            require(screen.getCursorItem() == Item.of(Block.STONE) && screen.getCursorCount() == 10,
                    "Con trỏ phải cầm 10 Stone");
            require(inv.getItem(9) == Item.NONE && inv.getCount(9) == 0,
                    "Ô 9 phải trống sau khi nhặt lên con trỏ");

            require(screen.handleSlotInteraction(inv, 0, InventoryScreen.LEFT_CLICK, false),
                    "Nhấn chuột trái vào ô 0 phải hoán đổi Stone và Oak Log");
            require(inv.getItem(0) == Item.of(Block.STONE) && inv.getCount(0) == 10,
                    "Ô 0 phải nhận 10 Stone");
            require(screen.getCursorItem() == Item.of(Block.OAK_LOG) && screen.getCursorCount() == 5,
                    "Con trỏ phải cầm lại 5 Oak Log từ ô 0");

            require(screen.handleSlotInteraction(inv, 9, InventoryScreen.LEFT_CLICK, false),
                    "Đặt 5 Oak Log vào ô 9 trống");
            require(inv.getItem(9) == Item.of(Block.OAK_LOG) && inv.getCount(9) == 5,
                    "Ô 9 phải chứa 5 Oak Log sau khi hoàn tất hoán đổi");
            require(screen.getCursorItem() == Item.NONE && screen.getCursorCount() == 0,
                    "Con trỏ phải trống sau khi đặt item xuống");

            // 2. Chia đôi stack bằng RIGHT_CLICK (16 -> cầm 8, để lại 8) và thả 1 đơn vị bằng RIGHT_CLICK
            inv.setSlot(10, Block.DIRT, 16);
            inv.setSlot(11, Item.NONE, 0);
            require(screen.handleSlotInteraction(inv, 10, InventoryScreen.RIGHT_CLICK, false),
                    "Chuột phải vào ô có 16 Dirt phải chia đôi");
            require(screen.getCursorItem() == Item.of(Block.DIRT) && screen.getCursorCount() == 8,
                    "Con trỏ phải cầm đúng 8 Dirt khi chia đôi 16");
            require(inv.getItem(10) == Item.of(Block.DIRT) && inv.getCount(10) == 8,
                    "Ô 10 phải giữ lại đúng 8 Dirt");

            require(screen.handleSlotInteraction(inv, 11, InventoryScreen.RIGHT_CLICK, false),
                    "Chuột phải vào ô 11 trống phải thả 1 Dirt");
            require(inv.getItem(11) == Item.of(Block.DIRT) && inv.getCount(11) == 1,
                    "Ô 11 phải nhận đúng 1 Dirt");
            require(screen.getCursorCount() == 7, "Con trỏ phải còn 7 Dirt sau khi thả 1");

            require(screen.handleSlotInteraction(inv, 11, InventoryScreen.RIGHT_CLICK, false),
                    "Chuột phải lần nữa vào ô 11 cùng loại phải cộng thêm 1 Dirt");
            require(inv.getCount(11) == 2 && screen.getCursorCount() == 6,
                    "Ô 11 phải tăng lên 2 Dirt và con trỏ còn 6");

            // Trả phần còn lại về ô 10
            require(screen.handleSlotInteraction(inv, 10, InventoryScreen.LEFT_CLICK, false),
                    "Chuột trái vào ô 10 phải gộp 6 Dirt còn lại vào 8 Dirt");
            require(inv.getCount(10) == 14 && screen.getCursorItem() == Item.NONE,
                    "Ô 10 phải thành 14 Dirt và con trỏ trống");

            // 3. SHIFT + LEFT_CLICK chuyển nhanh từ balo (9..35) về Hotbar (0..8) và ngược lại
            PlayerInventory quickInv = new PlayerInventory();
            // Thiết lập ô 0..4 và 6..8 có đồ (ô 2 có 16 Stone, ô 5 trống) để kiểm tra gộp & tràn vào ô trống
            quickInv.setSlot(0, Block.DIRT, 16);
            quickInv.setSlot(1, Block.GRASS, 16);
            quickInv.setSlot(2, Block.STONE, 16);
            quickInv.setSlot(3, Block.OAK_LOG, 12);
            quickInv.setSlot(4, Block.OAK_LEAVES, 16);
            quickInv.setSlot(6, Item.SHEARS, 1);
            quickInv.setSlot(7, Item.FLINT_AND_STEEL, 1);
            quickInv.setSlot(8, Item.BUCKET, 1);
            quickInv.setSlot(9, Block.STONE, 10);
            require(screen.handleSlotInteraction(quickInv, 9, InventoryScreen.LEFT_CLICK, true),
                    "Shift-Click Stone từ ô balo 9 phải chuyển về Hotbar");
            require(quickInv.getItem(2) == Item.of(Block.STONE) && quickInv.getCount(2) == 26,
                    "Shift-Click phải ưu tiên gộp vào stack Stone sẵn có ở ô Hotbar 2 (16+10=26)");
            require(quickInv.getItem(9) == Item.NONE && quickInv.getCount(9) == 0,
                    "Ô 9 phải trống sau khi chuyển hết Stone về Hotbar");

            // Chuyển item chưa có trên Hotbar -> phải vào ô trống đầu tiên (ô 5)
            quickInv.setSlot(12, Item.IRON_INGOT, 12);
            require(screen.handleSlotInteraction(quickInv, 12, InventoryScreen.LEFT_CLICK, true),
                    "Shift-Click Iron Ingot từ ô 12 phải chuyển vào ô Hotbar trống đầu tiên");
            require(quickInv.getItem(5) == Item.IRON_INGOT && quickInv.getCount(5) == 12,
                    "Ô Hotbar 5 phải nhận 12 Iron Ingot");
            require(quickInv.getItem(12) == Item.NONE, "Ô 12 phải trống sau khi Shift-Click");

            // Chuyển ngược từ Hotbar ô 5 về balo (phải vào ô trống đầu tiên của balo là ô 9)
            require(screen.handleSlotInteraction(quickInv, 5, InventoryScreen.LEFT_CLICK, true),
                    "Shift-Click từ Hotbar ô 5 phải chuyển về balo");
            require(quickInv.getItem(9) == Item.IRON_INGOT && quickInv.getCount(9) == 12,
                    "Ô balo 9 phải nhận lại 12 Iron Ingot");
            require(quickInv.getItem(5) == Item.NONE, "Ô Hotbar 5 phải trống sau khi chuyển về balo");

            // 4. Kiểm tra hit-test handleClick theo tọa độ màn hình 1280x720 và close() trả item về kho
            float hitX = -1f;
            float hitY = -1f;
            for (float y = 200f; y <= 550f && hitX < 0f; y += 8f) {
                for (float x = 350f; x <= 930f; x += 8f) {
                    if (screen.getSlotAt(x, y, 1280, 720) == 15) {
                        hitX = x;
                        hitY = y;
                        break;
                    }
                }
            }
            require(hitX >= 0f, "Phải xác định được tọa độ pixel của ô balo 15 trên màn hình 1280x720");
            player.getInventory().setSlot(15, Item.IRON_INGOT, 4);
            require(screen.handleClick(player.getInventory(), hitX, hitY, 1280, 720,
                    InventoryScreen.LEFT_CLICK, false),
                    "handleClick tại ô 15 phải xử lý nhặt 4 Iron Ingot lên con trỏ");
            require(screen.getCursorItem() == Item.IRON_INGOT && screen.getCursorCount() == 4,
                    "Con trỏ đang cầm 4 Iron Ingot trước khi đóng túi đồ");
            require(player.getInventory().getItem(15) == Item.NONE,
                    "Ô 15 của player phải trống sau khi nhặt lên con trỏ");

            screen.close(player, world);
            require(!screen.isOpen(), "close() phải đóng màn hình túi đồ");
            require(screen.getCursorItem() == Item.NONE && screen.getCursorCount() == 0,
                    "close() phải dọn sạch item đang cầm trên con trỏ");
            require(player.getInventory().getItem(1) == Item.IRON_INGOT
                    && player.getInventory().getCount(1) == 4,
                    "close() phải trả lại 4 Iron Ingot từ con trỏ về ô trống đầu tiên trong túi đồ (ô Hotbar 1)");
        } finally {
            screen.dispose();
            world.dispose();
        }
    }

    /**
     * Kiểm tra thanh Oxy (300 tick / 15 giây), ngạt nước (-2 HP/s), hiệu ứng Water Breathing,
     * hồi Oxy khi lên khỏi nước và Sprint-Swimming (Ctrl + di chuyển trong nước 1.55x).
     */
    private static void checkOxygenAndSprintSwimming() {
        Input previousInput = Gdx.input;
        boolean[] heldKeys = new boolean[256];
        Gdx.input = (Input) Proxy.newProxyInstance(Input.class.getClassLoader(), new Class<?>[]{Input.class},
                (proxy, method, args) -> {
                    if (method.getName().equals("isKeyPressed")) {
                        int key = (int) args[0];
                        return key >= 0 && key < heldKeys.length && heldKeys[key];
                    }
                    throw new AssertionError("Cuộc gọi input ngoài dự kiến: " + method.getName());
                });

        World world = World.empty();
        try {
            // Tạo bể nước kín kích thước đủ rộng để kiểm tra ngạt nước và bơi nhanh
            for (int x = 18; x <= 26; x++) {
                for (int z = 19; z <= 21; z++) {
                    world.setBlockInternal(x, 9, z, Block.STONE.getId(), 0);
                    for (int y = 10; y <= 14; y++) {
                        world.setBlockInternal(x, y, z, Block.WATER.getId(), 0);
                    }
                }
            }
            // Sàn đá khô bên ngoài bể nước để kiểm tra hồi Oxy khi lên bờ
            world.setBlockInternal(30, 10, 20, Block.STONE.getId(), 0);

            Player player = new Player(20.5f, 10.5f, 20.5f);
            Camera camera = new Camera();
            camera.rotate(90f, 0f);
            player.attachControls(camera);

            require(player.getAirTicks() == Player.AIR_MAX_TICKS,
                    "Oxy khởi đầu của người chơi phải bằng AIR_MAX_TICKS = 300");
            require(player.isEyeInWater(world),
                    "Khi đứng ngập trong bể nước, isEyeInWater(world) phải trả về true");

            // 1. Ngập nước liên tục 15.0 giây (300 tick * 0.05s) -> airTicks về 0, chưa mất HP
            for (int i = 0; i < 300; i++) {
                player.update(world, 0.05f);
            }
            require(player.getAirTicks() == 0,
                    "Sau 15.0 giây ngập nước, getAirTicks() phải giảm về 0");
            require(Math.abs(player.getHealth() - 20.0f) < 0.001f,
                    "Ngay khi Oxy vừa chạm 0 ở giây thứ 15 chưa được trừ HP ngạt");

            // 2. Chạy thêm 2.0 giây dưới nước -> mất 2.0 HP/s => HP giảm từ 20 xuống 16
            for (int i = 0; i < 40; i++) {
                player.update(world, 0.05f);
            }
            require(Math.abs(player.getHealth() - 16.0f) < 0.001f,
                    "Sau 2.0 giây ngạt nước phải mất 4 HP (từ 20 xuống 16), thực tế: " + player.getHealth());

            // 3. Lên khỏi nước -> isEyeInWater == false và airTicks hồi nhanh về 300
            player.setPosition(30.5f, 11.0f, 20.5f);
            require(!player.isEyeInWater(world),
                    "Khi đứng trên sàn đá khô, isEyeInWater(world) phải trả về false");
            player.update(world, 0.05f);
            require(player.getAirTicks() > 0,
                    "Ngay khi lên khỏi nước, airTicks phải bắt đầu hồi phục");
            for (int i = 0; i < 60; i++) {
                player.update(world, 0.05f);
            }
            require(player.getAirTicks() == Player.AIR_MAX_TICKS,
                    "Khi lên khỏi nước đủ thời gian ngắn, getAirTicks() phải hồi đầy về 300");

            // 4. Có StatusEffectType.WATER_BREATHING -> giữ nguyên 300 Oxy và không mất HP khi ngập nước
            player.heal(4.0f);
            require(Math.abs(player.getHealth() - 20.0f) < 0.001f,
                    "Hồi máu về 20.0f trước khi kiểm tra Water Breathing");
            player.setPosition(20.5f, 10.5f, 20.5f);
            player.applyEffect(StatusEffectType.WATER_BREATHING, 0, 30.0f);
            for (int i = 0; i < 400; i++) {
                player.update(world, 0.05f);
            }
            require(player.getAirTicks() == Player.AIR_MAX_TICKS,
                    "Khi có WATER_BREATHING, getAirTicks() phải giữ nguyên 300");
            require(Math.abs(player.getHealth() - 20.0f) < 0.001f,
                    "Khi có WATER_BREATHING không được mất HP vì ngạt nước");

            // 5. Kiểm tra bơi thường (không Ctrl) và Sprint-Swimming (Left Ctrl + di chuyển trong nước ~1.55x)
            Player swimmer = new Player(19.5f, 11.5f, 20.5f);
            Camera swimCam = new Camera();
            swimCam.rotate(90f, 0f); // yaw = 0, pitch = 0 (nhìn thẳng +X)
            swimmer.attachControls(swimCam);

            heldKeys[Input.Keys.W] = true;
            heldKeys[Input.Keys.CONTROL_LEFT] = false;
            swimmer.update(world, 1f / 60f);
            Vector3 normalVel = swimmer.getVelocity();
            float normalSwimSpeed = (float) Math.hypot(normalVel.x, normalVel.z);
            require(!swimmer.isSwimSprinting(),
                    "Khi không giữ Left Ctrl, isSwimSprinting() phải là false");
            require(Math.abs(normalSwimSpeed - 5.5f * 0.65f) < 0.02f,
                    "Bơi thường không nhấn Ctrl phải giữ nguyên vận tốc 3.575 block/s, thực tế: " + normalSwimSpeed);

            // Giữ Left Ctrl + W trong Block.WATER -> isSwimSprinting() == true và tốc độ tăng ~1.55x
            swimmer.setPosition(19.5f, 11.5f, 20.5f);
            heldKeys[Input.Keys.CONTROL_LEFT] = true;
            swimmer.update(world, 1f / 60f);
            Vector3 sprintVel = swimmer.getVelocity();
            float sprintSwimSpeed = (float) Math.hypot(sprintVel.x, sprintVel.z);
            require(swimmer.isSwimSprinting(),
                    "Khi ở trong Block.WATER và giữ Left Ctrl + di chuyển, isSwimSprinting() phải trả về true");
            float speedRatio = sprintSwimSpeed / normalSwimSpeed;
            require(Math.abs(speedRatio - 1.55f) < 0.02f,
                    "Tốc độ Sprint-Swimming phải đạt ~1.55x tốc độ bơi thường, thực tế: " + speedRatio);

            // Kiểm tra điều hướng dọc theo pitch khi giữ W + Left Ctrl
            swimCam.rotate(0f, -45f); // nhìn chéo xuống -45 độ
            swimmer.setPosition(20.5f, 11.5f, 20.5f);
            swimmer.update(world, 1f / 60f);
            require(swimmer.isSwimSprinting() && swimmer.getVelocity().y < -1.0f,
                    "Sprint-Swimming khi nhìn xuống phải tạo vận tốc lặn xuống theo góc pitch");

            swimCam.rotate(0f, 90f); // nhìn chéo lên +45 độ
            swimmer.setPosition(20.5f, 11.5f, 20.5f);
            swimmer.update(world, 1f / 60f);
            require(swimmer.isSwimSprinting() && swimmer.getVelocity().y > 1.0f,
                    "Sprint-Swimming khi mắt còn trong nước và nhìn lên phải tạo vận tốc nổi lên theo góc pitch");

            // Kiểm tra trong Block.LAVA không kích hoạt Sprint-Swimming
            world.setBlockInternal(35, 10, 20, Block.LAVA.getId(), 0);
            world.setBlockInternal(35, 11, 20, Block.LAVA.getId(), 0);
            Player lavaWalker = new Player(35.5f, 10.5f, 20.5f);
            lavaWalker.attachControls(swimCam);
            lavaWalker.update(world, 1f / 60f);
            require(!lavaWalker.isSwimSprinting(),
                    "Trong Block.LAVA không được kích hoạt isSwimSprinting()");
        } finally {
            Gdx.input = previousInput;
            world.dispose();
        }
    }

    /**
     * Kiểm tra hệ thống phân hủy lá cây (LeafDecaySystem), bảo vệ lá đặt tay (state = 1),
     * lan truyền khi chặt gỗ và hệ số tốc độ đào Shears 5.0x trên lá/len.
     */
    private static void checkLeafDecayAndShearsSpeed() {
        World world = World.empty();
        try {
            // 1. Lá sồi tự nhiên (state = 0) lơ lửng không có gỗ gần -> không nối gỗ và phân hủy thành AIR
            world.setBlock(40, 20, 40, Block.OAK_LEAVES.getId(), 0);
            require(!LeafDecaySystem.isConnectedToLog(world, 40, 20, 40),
                    "Lá sồi lơ lửng không có gỗ gần phải có isConnectedToLog == false");
            LeafDecaySystem.tickLeaf(world, 40, 20, 40);
            require(world.getBlock(40, 20, 40) == Block.AIR.getId(),
                    "tickLeaf trên lá sồi tự nhiên lơ lửng phải đổi khối thành Block.AIR");

            // Lá vân sam tự nhiên (state = 0) lơ lửng cũng phải phân hủy
            world.setBlock(42, 20, 40, Block.SPRUCE_LEAVES.getId(), 0);
            require(!LeafDecaySystem.isConnectedToLog(world, 42, 20, 40),
                    "Lá vân sam lơ lửng không có gỗ gần phải có isConnectedToLog == false");
            LeafDecaySystem.tickLeaf(world, 42, 20, 40);
            require(world.getBlock(42, 20, 40) == Block.AIR.getId(),
                    "tickLeaf trên lá vân sam tự nhiên lơ lửng phải đổi khối thành Block.AIR");

            // 2. Lá đặt tay (state = PERSISTENT_LEAF_STATE = 1) lơ lửng -> giữ nguyên state = 1 và không phân hủy
            world.setBlock(44, 20, 40, Block.OAK_LEAVES.getId(), LeafDecaySystem.PERSISTENT_LEAF_STATE);
            require(world.getBlockState(44, 20, 40) == LeafDecaySystem.PERSISTENT_LEAF_STATE,
                    "OakLeavesBlock phải bảo toàn metadata PERSISTENT_LEAF_STATE = 1");
            LeafDecaySystem.tickLeaf(world, 44, 20, 40);
            require(world.getBlock(44, 20, 40) == Block.OAK_LEAVES.getId(),
                    "Lá sồi đặt tay (state = 1) không bao giờ được tự phân hủy");

            world.setBlock(46, 20, 40, Block.SPRUCE_LEAVES.getId(), LeafDecaySystem.PERSISTENT_LEAF_STATE);
            require(world.getBlockState(46, 20, 40) == LeafDecaySystem.PERSISTENT_LEAF_STATE,
                    "SpruceLeavesBlock phải bảo toàn metadata PERSISTENT_LEAF_STATE = 1");
            LeafDecaySystem.tickLeaf(world, 46, 20, 40);
            require(world.getBlock(46, 20, 40) == Block.SPRUCE_LEAVES.getId(),
                    "Lá vân sam đặt tay (state = 1) không bao giờ được tự phân hủy");

            // 3. Đặt OAK_LOG cách 3 ô lá nối liền -> isConnectedToLog == true và tickLeaf giữ nguyên lá
            world.setBlock(50, 20, 40, Block.OAK_LOG.getId(), 0);
            world.setBlock(51, 20, 40, Block.OAK_LEAVES.getId(), 0);
            world.setBlock(52, 20, 40, Block.OAK_LEAVES.getId(), 0);
            world.setBlock(53, 20, 40, Block.OAK_LEAVES.getId(), 0);
            require(LeafDecaySystem.isConnectedToLog(world, 53, 20, 40),
                    "Lá nối liền qua 3 ô tới OAK_LOG phải có isConnectedToLog == true");
            LeafDecaySystem.tickLeaf(world, 53, 20, 40);
            require(world.getBlock(53, 20, 40) == Block.OAK_LEAVES.getId(),
                    "Lá còn nối tới gỗ không được phân hủy khi tickLeaf");

            // Kiểm tra giới hạn bán kính tối đa 6: ô thứ 7 không còn nối gỗ
            world.setBlock(54, 20, 40, Block.OAK_LEAVES.getId(), 0);
            world.setBlock(55, 20, 40, Block.OAK_LEAVES.getId(), 0);
            world.setBlock(56, 20, 40, Block.OAK_LEAVES.getId(), 0);
            world.setBlock(57, 20, 40, Block.OAK_LEAVES.getId(), 0);
            require(LeafDecaySystem.isConnectedToLog(world, 56, 20, 40),
                    "Lá ở khoảng cách 6 từ gỗ vẫn phải nối gỗ");
            require(!LeafDecaySystem.isConnectedToLog(world, 57, 20, 40),
                    "Lá ở khoảng cách 7 vượt quá bán kính 6 phải trả về false");

            // 4. Chặt gỗ nối lá -> notifyNeighbors + updateEntities tự phân hủy dây chuyền lá
            world.breakBlockAndSpawnDrop(50, 20, 40);
            for (int tick = 0; tick < 60; tick++) {
                world.updateEntities(0.05f);
            }
            require(world.getBlock(51, 20, 40) == Block.AIR.getId()
                    && world.getBlock(52, 20, 40) == Block.AIR.getId()
                    && world.getBlock(53, 20, 40) == Block.AIR.getId(),
                    "Sau khi chặt OAK_LOG, các lá tự nhiên nối kèm phải tự phân hủy");

            // 5. Kiểm tra hệ số tốc độ đào Shears (5.0f trên lá và 6 khối len; 1.0f trên khối/item khác)
            require(Math.abs(LeafDecaySystem.miningSpeedMultiplier(Item.SHEARS, Block.OAK_LEAVES) - 5.0f) < 0.001f,
                    "Shears trên Oak Leaves phải nhân tốc độ 5.0x");
            require(Math.abs(LeafDecaySystem.miningSpeedMultiplier(Item.SHEARS, Block.SPRUCE_LEAVES) - 5.0f) < 0.001f,
                    "Shears trên Spruce Leaves phải nhân tốc độ 5.0x");

            Block[] woolBlocks = {
                    Block.WHITE_WOOL, Block.LIGHT_GRAY_WOOL, Block.GRAY_WOOL,
                    Block.BLACK_WOOL, Block.BROWN_WOOL, Block.PINK_WOOL
            };
            for (Block wool : woolBlocks) {
                require(Math.abs(LeafDecaySystem.miningSpeedMultiplier(Item.SHEARS, wool) - 5.0f) < 0.001f,
                        "Shears trên " + wool.getDisplayName() + " phải nhân tốc độ 5.0x");
            }

            require(Math.abs(LeafDecaySystem.miningSpeedMultiplier(Item.SHEARS, Block.STONE) - 1.0f) < 0.001f,
                    "Shears trên Stone phải giữ hệ số 1.0x");
            require(Math.abs(LeafDecaySystem.miningSpeedMultiplier(Item.STICK, Block.OAK_LEAVES) - 1.0f) < 0.001f,
                    "Item khác ngoài Shears trên lá phải giữ hệ số 1.0x");
            require(Math.abs(LeafDecaySystem.miningSpeedMultiplier(Item.NONE, Block.WHITE_WOOL) - 1.0f) < 0.001f,
                    "Tay không trên len phải giữ hệ số 1.0x");
        } finally {
            world.dispose();
        }
    }

    /**
     * Kiểm tra mô phỏng dòng chảy Water (7 ô, 0.25s), Lava (3 ô, 1.50s), phản ứng tạo Stone,
     * ưu tiên chảy thẳng xuống dưới rửa trôi cây chữ X và màn hình thông số F3 (zero-GC).
     */
    private static void checkLiquidFlowAndStoneReaction() {
        World world = World.empty();
        DebugOverlayRenderer debug = new DebugOverlayRenderer();
        try {
            // 1. Sàn đá dài 12 block (x = 10..21, z = 10) có thành chắn 2 bên để đo dòng chảy chuẩn theo trục +X
            for (int x = 9; x <= 21; x++) {
                world.setBlockInternal(x, 10, 10, Block.STONE.getId(), 0);
                world.setBlockInternal(x, 11, 9, Block.STONE.getId(), 0);
                world.setBlockInternal(x, 11, 11, Block.STONE.getId(), 0);
            }
            world.setBlockInternal(9, 11, 10, Block.STONE.getId(), 0);

            // Đặt 1 nguồn Block.WATER (state = 0) tại (10, 11, 10) và chạy tick 4.0f giây
            world.setBlock(10, 11, 10, Block.WATER.getId(), 0);
            for (int i = 0; i < 80; i++) {
                world.updateEntities(0.05f);
            }
            for (int d = 0; d <= 7; d++) {
                require(world.getBlock(10 + d, 11, 10) == Block.WATER.getId(),
                        "Nước phải lan tới ô thứ " + d + " trên sàn đá");
                require(world.getBlockState(10 + d, 11, 10) == d,
                        "Mực state dòng chảy nước tại ô " + d + " phải bằng " + d
                                + ", thực tế: " + world.getBlockState(10 + d, 11, 10));
            }
            require(world.getBlock(18, 11, 10) == Block.AIR.getId(),
                    "Ô thứ 8 tính từ nguồn nước phải giữ nguyên Block.AIR");

            // 2. Đặt 1 nguồn Block.LAVA (state = 0) sát dòng chảy Block.WATER -> tạo Block.STONE tại vị trí tiếp xúc
            world.setBlock(18, 11, 10, Block.LAVA.getId(), 0);
            for (int i = 0; i < 40; i++) {
                world.updateEntities(0.05f);
            }
            require(world.getBlock(18, 11, 10) == Block.STONE.getId()
                            || world.getBlock(17, 11, 10) == Block.STONE.getId(),
                    "Tiếp xúc giữa Water và Lava phải tạo Block.STONE tại vị trí tiếp xúc");

            // 3. Kiểm tra Lava chảy ngang tối đa 3 ô với nhịp 1.50s
            for (int x = 29; x <= 40; x++) {
                world.setBlockInternal(x, 10, 10, Block.STONE.getId(), 0);
                world.setBlockInternal(x, 11, 9, Block.STONE.getId(), 0);
                world.setBlockInternal(x, 11, 11, Block.STONE.getId(), 0);
            }
            world.setBlockInternal(29, 11, 10, Block.STONE.getId(), 0);
            world.setBlock(30, 11, 10, Block.LAVA.getId(), 0);
            for (int i = 0; i < 120; i++) {
                world.updateEntities(0.05f);
            }
            require(world.getBlock(30, 11, 10) == Block.LAVA.getId() && world.getBlockState(30, 11, 10) == 0,
                    "Nguồn Lava phải giữ state = 0");
            require(world.getBlock(31, 11, 10) == Block.LAVA.getId()
                            && world.getBlock(32, 11, 10) == Block.LAVA.getId()
                            && world.getBlock(33, 11, 10) == Block.LAVA.getId(),
                    "Lava phải lan tối đa 3 ô ngang");
            require(world.getBlock(34, 11, 10) == Block.AIR.getId(),
                    "Ô thứ 4 tính từ nguồn Lava phải giữ nguyên Block.AIR");

            // 4. Nước ưu tiên chảy thẳng xuống dưới và rửa trôi Block.SHORT_GRASS thành ItemEntity rơi
            world.setBlockInternal(50, 10, 10, Block.STONE.getId(), 0);
            world.setBlockInternal(50, 11, 10, Block.DIRT.getId(), 0);
            world.setBlockInternal(50, 12, 10, Block.SHORT_GRASS.getId(), 0);
            world.setBlock(50, 15, 10, Block.WATER.getId(), 0);
            for (int i = 0; i < 30; i++) {
                world.updateEntities(0.05f);
            }
            require(world.getBlock(51, 15, 10) == Block.AIR.getId()
                            && world.getBlock(49, 15, 10) == Block.AIR.getId(),
                    "Khi bên dưới là khoảng trống, nước phải ưu tiên chảy thẳng xuống thay vì lan ngang");
            require(world.getBlock(50, 14, 10) == Block.WATER.getId()
                            && world.getBlock(50, 13, 10) == Block.WATER.getId()
                            && world.getBlock(50, 12, 10) == Block.WATER.getId(),
                    "Nước chảy xuống phải chiếm các ô không khí và rửa trôi Short Grass");

            boolean droppedShortGrass = false;
            for (int i = 0; i < world.entityCount(); i++) {
                if (world.entityAt(i) instanceof ItemEntity dropped
                        && dropped.getItem() == Item.of(Block.SHORT_GRASS)) {
                    droppedShortGrass = true;
                    break;
                }
            }
            require(droppedShortGrass, "Rửa trôi Block.SHORT_GRASS phải sinh ItemEntity rơi");

            // 5. Kiểm tra DebugOverlayRenderer (F3), tái sử dụng StringBuilder zero-GC và glyph 5x7
            require(!debug.isVisible(), "DebugOverlayRenderer mặc định phải tắt");
            debug.toggle();
            require(debug.isVisible(), "toggle() lần 1 phải bật DebugOverlayRenderer");
            debug.toggle();
            require(!debug.isVisible(), "toggle() lần 2 phải tắt DebugOverlayRenderer");
            debug.toggle();

            Player player = new Player(50.5f, 16.0f, 10.5f);
            Camera camera = new Camera();
            camera.setPosition(50.5f, 17.62f, 10.5f);
            world.registerPlayer(player);

            debug.formatLines(world, player, camera, 60);
            StringBuilder firstLine0 = debug.getLineBuffer(0);
            int lineCount = debug.getLineCount();
            require(lineCount >= 7, "DebugOverlayRenderer phải hiển thị đủ 7 dòng thông số F3");

            String allText = collectDebugText(debug);
            require(allText.contains("FPS: 60"), "F3 phải có dòng FPS");
            require(allText.contains("XYZ:"), "F3 phải có dòng XYZ");
            require(allText.contains("CHUNK:"), "F3 phải có dòng CHUNK");
            require(allText.contains("FACING:"), "F3 phải có dòng FACING");
            require(allText.contains("BIOME:"), "F3 phải có dòng BIOME");
            require(allText.contains("LIGHT:"), "F3 phải có dòng LIGHT");
            require(allText.contains("ENTITIES:"), "F3 phải có dòng ENTITIES");

            debug.formatLines(world, player, camera, 120);
            require(debug.getLineBuffer(0) == firstLine0,
                    "DebugOverlayRenderer phải tái sử dụng StringBuilder thành viên (zero-GC)");
            require(UIRenderer.hasGlyph('.') && UIRenderer.hasGlyph('/') && UIRenderer.hasGlyph(',')
                            && UIRenderer.hasGlyph('(') && UIRenderer.hasGlyph(')') && UIRenderer.hasGlyph('='),
                    "Font 5x7 của UIRenderer phải hỗ trợ đầy đủ ký tự .,/()= cho màn hình F3");
        } finally {
            debug.dispose();
            world.dispose();
        }
    }

    /**
     * Kiểm tra toàn bộ bộ sprite PNG giao diện Minecraft 1.21.11 trong {@code textures/gui/}
     * giải mã được qua {@link Pixmap} đúng kích thước và {@link GuiTextureAtlas} tính UV chuẩn zero-GC.
     */
    private static void checkGuiTexturesPresent() {
        GdxNativesLoader.load();
        ClassLoader loader = SurvivalWorldChecks.class.getClassLoader();

        String[] paths = {
                "textures/gui/container/inventory.png",
                "textures/gui/sprites/hud/hotbar.png",
                "textures/gui/sprites/hud/hotbar_selection.png",
                "textures/gui/sprites/hud/crosshair.png",
                "textures/gui/sprites/hud/heart/container.png",
                "textures/gui/sprites/hud/heart/full.png",
                "textures/gui/sprites/hud/heart/half.png",
                "textures/gui/sprites/hud/heart/poisoned_full.png",
                "textures/gui/sprites/hud/heart/poisoned_half.png",
                "textures/gui/sprites/hud/heart/vehicle_container.png",
                "textures/gui/sprites/hud/heart/vehicle_full.png",
                "textures/gui/sprites/hud/heart/vehicle_half.png",
                "textures/gui/sprites/hud/food_empty.png",
                "textures/gui/sprites/hud/food_full.png",
                "textures/gui/sprites/hud/food_half.png",
                "textures/gui/sprites/hud/food_empty_hunger.png",
                "textures/gui/sprites/hud/food_full_hunger.png",
                "textures/gui/sprites/hud/food_half_hunger.png",
                "textures/gui/sprites/hud/air.png",
                "textures/gui/sprites/hud/air_bursting.png",
                "textures/gui/sprites/hud/air_empty.png",
                "textures/gui/sprites/hud/jump_bar_background.png",
                "textures/gui/sprites/hud/jump_bar_progress.png",
                "textures/gui/sprites/hud/jump_bar_cooldown.png",
                "textures/gui/sprites/widget/button.png",
                "textures/gui/sprites/widget/button_highlighted.png",
                "textures/gui/sprites/widget/button_disabled.png",
                "textures/gui/sprites/widget/slider.png",
                "textures/gui/sprites/widget/slider_highlighted.png",
                "textures/gui/sprites/widget/slider_handle.png",
                "textures/gui/sprites/widget/slider_handle_highlighted.png"
        };
        int[] expectedWidths = {
                256, 182, 24, 15,
                9, 9, 9, 9, 9, 9, 9, 9,
                9, 9, 9, 9, 9, 9,
                9, 9, 9,
                182, 182, 182,
                200, 200, 200, 200, 200, 8, 8
        };
        int[] expectedHeights = {
                256, 22, 23, 15,
                9, 9, 9, 9, 9, 9, 9, 9,
                9, 9, 9, 9, 9, 9,
                9, 9, 9,
                5, 5, 5,
                20, 20, 20, 20, 20, 20, 20
        };

        for (int i = 0; i < paths.length; i++) {
            String path = paths[i];
            try (InputStream stream = loader.getResourceAsStream(path)) {
                require(stream != null, "Thiếu tài nguyên GUI bắt buộc: " + path);
                byte[] bytes = stream.readAllBytes();
                Pixmap pixmap = new Pixmap(bytes, 0, bytes.length);
                try {
                    require(pixmap.getWidth() == expectedWidths[i] && pixmap.getHeight() == expectedHeights[i],
                            "Sai kích thước GUI PNG " + path + ": kỳ vọng "
                                    + expectedWidths[i] + "x" + expectedHeights[i]
                                    + ", thực tế " + pixmap.getWidth() + "x" + pixmap.getHeight());
                } finally {
                    pixmap.dispose();
                }
            } catch (IOException e) {
                throw new AssertionError("Không đọc được tài nguyên GUI: " + path, e);
            }
        }

        // Xác nhận toàn bộ SpriteKey của GuiTextureAtlas tính UV hợp lệ trong [0, 1] và zero-GC
        GuiTextureAtlas.SpriteKey[] keys = GuiTextureAtlas.SpriteKey.values();
        require(keys.length >= 30, "GuiTextureAtlas.SpriteKey phải đủ 30 sprite HUD & Widget");
        for (GuiTextureAtlas.SpriteKey key : keys) {
            float[] uv1 = GuiTextureAtlas.uvOf(key);
            float[] uv2 = GuiTextureAtlas.uvOf(key);
            require(uv1 == uv2, "GuiTextureAtlas.uvOf(" + key + ") phải trả mảng tính sẵn (zero-GC)");
            require(uv1.length == 4, "UV phải có đúng 4 phần tử [u0, v0, u1, v1]");
            require(uv1[0] >= 0f && uv1[0] < uv1[2] && uv1[2] <= 1f,
                    "Tọa độ U không hợp lệ cho " + key + ": [" + uv1[0] + ", " + uv1[2] + "]");
            require(uv1[1] >= 0f && uv1[1] < uv1[3] && uv1[3] <= 1f,
                    "Tọa độ V không hợp lệ cho " + key + ": [" + uv1[1] + ", " + uv1[3] + "]");
            float actualW = (uv1[2] - uv1[0]) * GuiTextureAtlas.ATLAS_WIDTH;
            float actualH = (uv1[3] - uv1[1]) * GuiTextureAtlas.ATLAS_HEIGHT;
            require(Math.abs(actualW - key.width) < 0.01f && Math.abs(actualH - key.height) < 0.01f,
                    "Kích thước UV không khớp kích thước sprite cho " + key);
        }

        // Xác nhận đóng gói CPU Pixmap cho atlas HUD & Widget không làm trắng ảnh Grayscale (button.png)
        Pixmap atlasCpu = GuiTextureAtlas.buildHudAtlasPixmap();
        try {
            require(atlasCpu.getWidth() == GuiTextureAtlas.ATLAS_WIDTH
                            && atlasCpu.getHeight() == GuiTextureAtlas.ATLAS_HEIGHT,
                    "Kích thước CPU atlas phải là 512x256");
            int btnX = GuiTextureAtlas.SpriteKey.WIDGET_BUTTON.atlasX;
            int btnY = GuiTextureAtlas.SpriteKey.WIDGET_BUTTON.atlasY;
            boolean hasDarkGray = false;
            for (int y = 0; y < GuiTextureAtlas.SpriteKey.WIDGET_BUTTON.height && !hasDarkGray; y++) {
                for (int x = 0; x < GuiTextureAtlas.SpriteKey.WIDGET_BUTTON.width; x++) {
                    int rgba = atlasCpu.getPixel(btnX + x, btnY + y);
                    int r = (rgba >>> 24) & 0xFF;
                    int g = (rgba >>> 16) & 0xFF;
                    int b = (rgba >>> 8) & 0xFF;
                    if (r == g && g == b && r < 200) {
                        hasDarkGray = true;
                        break;
                    }
                }
            }
            require(hasDarkGray, "WIDGET_BUTTON grayscale PNG không được bị giải mã thành trắng tinh");
        } finally {
            atlasCpu.dispose();
        }
    }

    /** Gom nội dung các dòng F3 trong test để kiểm tra từ khóa bắt buộc. */
    private static String collectDebugText(DebugOverlayRenderer debug) {
        StringBuilder combined = new StringBuilder();
        for (int i = 0; i < debug.getLineCount(); i++) {
            combined.append(debug.getLineBuffer(i)).append('\n');
        }
        return combined.toString();
    }

    /** Báo lỗi khẳng định nếu điều kiện kiểm tra không thỏa mãn. */
    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}
